  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(LABEL_TAC "cova") THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`a:A`]
    AUTNSTAGE_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `cda:A` (CONJUNCTS_THEN2 (LABEL_TAC "cdaD")
    (LABEL_TAC "astga"))) THEN
