(* ===================================================================== *)
(* step 8g-1 : stage co-functionality object formula (for autN             *)
(*   injectivity).  goodinj(d): the autN stage value read off the          *)
(*   resolvent graph at slot 81 (apply_form 81 0 82) is CO-FUNCTIONAL:     *)
(*   two member pairs with equal second coordinate have equal first        *)
(*   coordinate.  Slots: 82=stage (apply binds 83,84,85), 88/89 the two    *)
(*   member pairs (forallmem over 82), 90/91/92 = u,u',vv (opair_forms     *)
(*   bind 93,94).  Mirror of goodcheck/HOLDS_GOODCHECK + GOODF2AUTN_SEM.   *)
(* ===================================================================== *)

let goodinj = new_definition
  `goodinj =
     ?? 82 (apply_form 81 0 82 &&
            !!- 88 82 (!!- 89 82 (
              !! 90 (!! 91 (!! 92 (
                (opair_form 90 92 88 && opair_form 91 92 89)
                --> Eq 90 91))))))`;;

let HOLDS_GOODINJ = prove
 (`!D (E:A->A->bool) v.
     model D E ZF_AX /\ valuation D v
     ==> (holds D E v goodinj <=>
          ?stg. stg IN D /\ eapply D E (v 81) (v 0) stg /\
                !pp. pp IN D /\ E pp stg
                     ==> !pp'. pp' IN D /\ E pp' stg
                          ==> !u u' vv.
                                 u IN D /\ u' IN D /\ vv IN D /\
                                 eopair D E u vv pp /\ eopair D E u' vv pp'
                                 ==> u = u')`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!n. (v:num->A) n IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[goodinj; HOLDS_EX; HOLDS_AND] THEN
  MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s))
     ==> ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
  X_GEN_TAC `stg:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `valuation D ((82 |-> (stg:A)) v)` ASSUME_TAC THENL
   [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
           (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC)); ALL_TAC] THEN
  SUBGOAL_THEN
   `holds D E ((82 |-> (stg:A)) v) (apply_form 81 0 82) <=>
    eapply D E (v 81) (v 0) stg`
  (fun th -> REWRITE_TAC[th]) THENL
   [ASM_SIMP_TAC[HOLDS_APPLY_FORM] THEN REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  MATCH_MP_TAC(TAUT `(y <=> z) ==> ((x /\ y) <=> (x /\ z))`) THEN
  ASM_SIMP_TAC[HOLDS_FORALLMEM; ARITH_RULE `~(88 = 82)`] THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN
  MATCH_MP_TAC(MESON[]
    `(!pp:A. M pp ==> (P pp <=> Q pp))
     ==> ((!pp. M pp ==> P pp) <=> (!pp. M pp ==> Q pp))`) THEN
  X_GEN_TAC `pp:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((88 |-> (pp:A)) ((82 |-> (stg:A)) v))`
  ASSUME_TAC THENL [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
      (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC)); ALL_TAC] THEN
  ASM_SIMP_TAC[HOLDS_FORALLMEM; ARITH_RULE `~(89 = 82)`] THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN
  MATCH_MP_TAC(MESON[]
    `(!pp':A. M pp' ==> (P pp' <=> Q pp'))
     ==> ((!pp'. M pp' ==> P pp') <=> (!pp'. M pp' ==> Q pp'))`) THEN
  X_GEN_TAC `pp':A` THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `valuation D ((89 |-> (pp':A)) ((88 |-> (pp:A)) ((82 |-> (stg:A)) v)))`
  ASSUME_TAC THENL [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
      (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC)); ALL_TAC] THEN
  REWRITE_TAC[holds] THEN
  MATCH_MP_TAC(MESON[]
    `(!u u' vv:A. u IN D /\ u' IN D /\ vv IN D
         ==> (H u u' vv <=> (R u u' vv ==> u = u')))
     ==> ((!u. u IN D ==> !u'. u' IN D ==> !vv. vv IN D ==> H u u' vv) <=>
          (!u u' vv. u IN D /\ u' IN D /\ vv IN D /\ R u u' vv
           ==> u = u'))`) THEN
  MAP_EVERY X_GEN_TAC [`u:A`;`u':A`;`vv:A`] THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `valuation D ((92 |-> (vv:A)) ((91 |-> (u':A)) ((90 |-> (u:A))
      ((89 |-> (pp':A)) ((88 |-> (pp:A)) ((82 |-> (stg:A)) v))))))`
  ASSUME_TAC THENL [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
      (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC)); ALL_TAC] THEN
  MATCH_MP_TAC(TAUT
    `(a <=> c) /\ (b <=> d) ==> ((a ==> b) <=> (c ==> d))`) THEN
  CONJ_TAC THENL
   [REWRITE_TAC[HOLDS_AND] THEN
    ASM_SIMP_TAC[HOLDS_OPAIR_FORM] THEN REWRITE_TAC[VALMOD; ARITH_EQ];
    REWRITE_TAC[VALMOD; ARITH_EQ]]);;

let GOODINJ_SEM = prove
 (`!D (E:A->A->bool) B autB sa rc v0 b.
      model D E ZF_AX /\ B IN D /\ autB IN D /\ eordinal D E sa /\
      rc IN D /\ valuation D v0 /\
      (!pp. pp IN D
            ==> (E pp rc <=>
                 ?b' z'. b' IN D /\ z' IN D /\ E b' sa /\
                         autnstage D E B autB b' z' /\ eopair D E b' z' pp)) /\
      b IN D /\ E b sa
      ==> (holds D E ((0 |-> b) ((81 |-> rc) v0)) goodinj <=>
           !cd. cd IN D /\ autnstage D E B autB b cd
                ==> !pp. pp IN D /\ E pp cd
                     ==> !pp'. pp' IN D /\ E pp' cd
                          ==> !u u' vv.
                                 u IN D /\ u' IN D /\ vv IN D /\
                                 eopair D E u vv pp /\ eopair D E u' vv pp'
                                 ==> u = u')`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
        (CONJUNCTS_THEN2 (LABEL_TAC "rcc")
          (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC)))))))) THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) b` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((0 |-> (b:A)) ((81 |-> (rc:A)) v0))`
  ASSUME_TAC THENL [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
      (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC)); ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;
    `(0 |-> (b:A)) ((81 |-> (rc:A)) v0)`] HOLDS_GOODINJ) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `stg:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 (LABEL_TAC "eac") (LABEL_TAC "cov")))) THEN
    SUBGOAL_THEN `autnstage D (E:A->A->bool) B autB b stg` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;
        `autnstage D (E:A->A->bool) B autB`;`sa:A`;`rc:A`;`b:A`;`stg:A`]
        EGRAPH_APPLY) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> MP_TAC(EQ_MP th
        (ASSUME `eapply D (E:A->A->bool) rc b stg`))) THEN
      DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC ACCEPT_TAC);
      ALL_TAC] THEN
    X_GEN_TAC `cd:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `cd:A = stg` SUBST_ALL_TAC THENL
     [ASM_MESON_TAC[AUTNSTAGE_UNIQUE]; ALL_TAC] THEN
    USE_THEN "cov" ACCEPT_TAC;
    DISCH_THEN(LABEL_TAC "sem") THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`b:A`]
      AUTNSTAGE_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `stg:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `stg:A` THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `eapply D (E:A->A->bool) rc b stg` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;
        `autnstage D (E:A->A->bool) B autB`;`sa:A`;`rc:A`;`b:A`;`stg:A`]
        EGRAPH_APPLY) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "sem" (MP_TAC o SPEC `stg:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]]);;

(* ===================================================================== *)
(* step 8g-2 : autN injectivity.  AUTNINJ_STEP: if all earlier stages     *)
(*   are co-functional then stage d is: two names u,u' in bnfuns(B,wa)    *)
(*   with the same aprrel image are equal, by extensionality -- a member  *)
(*   <t,c> of u maps to the pair q = <gacc t, autB c> IN image; reading   *)
(*   q back through u''s image char and using co-functionality of the     *)
(*   accumulated graph (from the IH + EAUTN_COHERE) plus injectivity of   *)
(*   autB (ebij) recovers the SAME member <t,c> IN u'.  AUTNSTAGE_COFUN   *)
(*   wraps by least counterexample over goodinj; AUTN_INJ lifts to the    *)
(*   eautn operator via EAUTN_COHERE + EORDINAL_TRICHOTOMY.               *)
(* ===================================================================== *)

let AUTNINJ_STEP = prove
 (`!D (E:A->A->bool) B autB d.
      model D E ZF_AX /\ B IN D /\ autB IN D /\ ebij D E autB B B /\
      eordinal D E d /\
      (!b'. b' IN D /\ E b' d
            ==> !cd. cd IN D /\ autnstage D E B autB b' cd
                 ==> !pp. pp IN D /\ E pp cd
                      ==> !pp'. pp' IN D /\ E pp' cd
                           ==> !u u' vv.
                                  u IN D /\ u' IN D /\ vv IN D /\
                                  eopair D E u vv pp /\ eopair D E u' vv pp'
                                  ==> u = u')
      ==> !cd. cd IN D /\ autnstage D E B autB d cd
           ==> !pp. pp IN D /\ E pp cd
                ==> !pp'. pp' IN D /\ E pp' cd
                     ==> !u u' vv.
                            u IN D /\ u' IN D /\ vv IN D /\
                            eopair D E u vv pp /\ eopair D E u' vv pp'
                            ==> u = u'`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
    (CONJUNCTS_THEN2 (LABEL_TAC "BD")
      (CONJUNCTS_THEN2 (LABEL_TAC "autBD")
        (CONJUNCTS_THEN2 (LABEL_TAC "bij")
          (CONJUNCTS_THEN2 (LABEL_TAC "dord") (LABEL_TAC "IH")))))) THEN
  SUBGOAL_THEN
   `(!c. (c:A) IN D /\ (E:A->A->bool) c B
         ==> ?c'. c' IN D /\ eapply D E autB c c') /\
    (!k k' t. (k:A) IN D /\ k' IN D /\ t IN D /\
              eapply D (E:A->A->bool) autB k t /\ eapply D E autB k' t
              ==> k = k')`
  (CONJUNCTS_THEN2 (LABEL_TAC "atot") (LABEL_TAC "ainj")) THENL
   [USE_THEN "bij" (STRIP_ASSUME_TAC o GEN_REWRITE_RULE I [ebij]) THEN
    CONJ_TAC THENL [ASM_MESON_TAC[]; ASM_MESON_TAC[]];
    ALL_TAC] THEN
  X_GEN_TAC `cd:A` THEN STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`d:A`;`cd:A`]
        EAUTNSTAGE_CHAR) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `gacc:A` (X_CHOOSE_THEN `wa:A`
   (X_CHOOSE_THEN `stg:A`
    (CONJUNCTS_THEN2 (LABEL_TAC "gaccD") (CONJUNCTS_THEN2 (LABEL_TAC "waD")
     (CONJUNCTS_THEN2 (LABEL_TAC "stgD") (CONJUNCTS_THEN2 (LABEL_TAC "gaccch")
      (CONJUNCTS_THEN2 (LABEL_TAC "domn") (CONJUNCTS_THEN2 (LABEL_TAC "bnfa")
       (LABEL_TAC "cdch")))))))))) THEN
  SUBGOAL_THEN
   `!t s t'. (t:A) IN D /\ (s:A) IN D /\ (t':A) IN D /\
             eapply D (E:A->A->bool) gacc t t' /\ eapply D E gacc s t'
             ==> t = s`
  (LABEL_TAC "gcof") THENL
   [MAP_EVERY X_GEN_TAC [`t:A`;`s:A`;`t':A`] THEN STRIP_TAC THEN
    UNDISCH_TAC `eapply D (E:A->A->bool) gacc t t'` THEN
    REWRITE_TAC[eapply] THEN
    DISCH_THEN(X_CHOOSE_THEN `p1:A` STRIP_ASSUME_TAC) THEN
    UNDISCH_TAC `eapply D (E:A->A->bool) gacc s t'` THEN
    REWRITE_TAC[eapply] THEN
    DISCH_THEN(X_CHOOSE_THEN `p2:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(p1:A) IN D /\ (p2:A) IN D` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    USE_THEN "gaccch" (MP_TAC o C MATCH_MP (ASSUME `(p1:A) IN D`)) THEN
    REWRITE_TAC[ASSUME `(E:A->A->bool) p1 gacc`] THEN
    DISCH_THEN(X_CHOOSE_THEN `b1:A` (X_CHOOSE_THEN `z1:A`
      STRIP_ASSUME_TAC)) THEN
    USE_THEN "gaccch" (MP_TAC o C MATCH_MP (ASSUME `(p2:A) IN D`)) THEN
    REWRITE_TAC[ASSUME `(E:A->A->bool) p2 gacc`] THEN
    DISCH_THEN(X_CHOOSE_THEN `b2:A` (X_CHOOSE_THEN `z2:A`
      STRIP_ASSUME_TAC)) THEN
    SUBGOAL_THEN
     `eordinal D (E:A->A->bool) b1 /\ eordinal D E b2`
    STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`b1:A`;`b2:A`]
      EORDINAL_TRICHOTOMY) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN ASSUME_TAC) THENL
     [SUBGOAL_THEN `(E:A->A->bool) p1 z2` ASSUME_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`b2:A`;
                      `b1:A`;`z1:A`;`z2:A`] EAUTN_COHERE) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        REWRITE_TAC[esubset] THEN
        DISCH_THEN(MP_TAC o SPEC `p1:A`) THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      USE_THEN "IH" (MP_TAC o SPEC `b2:A`) THEN
