let AUTNSTAGE_COFUN = prove
 (`!D (E:A->A->bool) B autB a cd.
     model D E ZF_AX /\ B IN D /\ autB IN D /\ ebij D E autB B B /\
     eordinal D E a /\ cd IN D /\ autnstage D E B autB a cd
     ==> !pp. pp IN D /\ E pp cd
          ==> !pp'. pp' IN D /\ E pp' cd
               ==> !u u' vv. u IN D /\ u' IN D /\ vv IN D /\
                      eopair D E u vv pp /\ eopair D E u' vv pp'
                      ==> u = u'`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(a:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`a:A`] ESUC_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `sa:A`) THEN
  SUBGOAL_THEN `(sa:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) sa` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_ESUC]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) a sa` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_MEMBER]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`sa:A`]
    EAUTNSTAGE_RESGRAPH) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `rc:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "rcc"))) THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v0:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  SUBGOAL_THEN `valuation D ((81 |-> (rc:A)) v0)`
  ASSUME_TAC THENL [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
      (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC)); ALL_TAC] THEN
  SUBGOAL_THEN
   `!dd. dd IN D /\ E dd sa
         ==> holds D E ((0 |-> dd) ((81 |-> (rc:A)) v0)) goodinj`
  (LABEL_TAC "good") THENL
   [GEN_TAC THEN STRIP_TAC THEN
    MATCH_MP_TAC(TAUT `(~p ==> F) ==> p`) THEN
    DISCH_THEN(LABEL_TAC "bad0") THEN
    SUBGOAL_THEN `eordinal D (E:A->A->bool) dd` ASSUME_TAC THENL
     [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`Not goodinj`;
                  `(81 |-> (rc:A)) v0`;`dd:A`]
      EORDINAL_LEAST) THEN
    ASM_REWRITE_TAC[HOLDS_NOT] THEN
    DISCH_THEN(X_CHOOSE_THEN `d:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 (LABEL_TAC "dbad")
        (LABEL_TAC "dmin"))))) THEN
    SUBGOAL_THEN `(d:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) d sa` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`d:A`;`dd:A`]
        EORDINAL_TRICHOTOMY) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN ASSUME_TAC) THENL
       [ASM_MESON_TAC[EORDINAL_TRANS_E];
        ASM_MESON_TAC[];
        USE_THEN "dmin" (MP_TAC o SPEC `dd:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        USE_THEN "bad0" (fun th -> REWRITE_TAC[th])];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `!b'. b' IN D /\ (E:A->A->bool) b' d
           ==> !cd. cd IN D /\ autnstage D E B autB b' cd
                ==> !pp. pp IN D /\ E pp cd
                     ==> !pp'. pp' IN D /\ E pp' cd
                          ==> !u u' vv.
                                 u IN D /\ u' IN D /\ vv IN D /\
                                 eopair D E u vv pp /\ eopair D E u' vv pp'
                                 ==> u = u'`
    ASSUME_TAC THENL
     [X_GEN_TAC `b':A` THEN STRIP_TAC THEN
      SUBGOAL_THEN `(E:A->A->bool) b' sa` ASSUME_TAC THENL
       [ASM_MESON_TAC[EORDINAL_TRANS_E]; ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`sa:A`;
                    `rc:A`;`v0:num->A`;`b':A`] GOODINJ_SEM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(MP_TAC o fst o EQ_IMP_RULE) THEN
      ANTS_TAC THENL
       [USE_THEN "dmin" (MP_TAC o SPEC `b':A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
        DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `holds D E ((0 |-> (d:A)) ((81 |-> (rc:A)) v0)) goodinj`
    MP_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`sa:A`;
                    `rc:A`;`v0:num->A`;`d:A`] GOODINJ_SEM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`d:A`]
        AUTNINJ_STEP) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      USE_THEN "dbad" (fun th -> REWRITE_TAC[th])];
    ALL_TAC] THEN
  USE_THEN "good" (MP_TAC o SPEC `a:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`sa:A`;`rc:A`;
                `v0:num->A`;`a:A`] GOODINJ_SEM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o fst o EQ_IMP_RULE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `cd:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]);;

let AUTN_INJ = prove
 (`!D (E:A->A->bool) B autB u u' v.
     model D E ZF_AX /\ B IN D /\ autB IN D /\ ebij D E autB B B /\
     eautn D E B autB u v /\ eautn D E B autB u' v
     ==> u = u'`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 MP_TAC MP_TAC))))) THEN
  REWRITE_TAC[eautn] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
    (X_CHOOSE_THEN `a2:A` (X_CHOOSE_THEN `cd2:A` (X_CHOOSE_THEN `pp2:A`
      (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th))))))) THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
    (X_CHOOSE_THEN `a1:A` (X_CHOOSE_THEN `cd1:A` (X_CHOOSE_THEN `pp1:A`
      (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th))))))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`a1:A`;`a2:A`]
    EORDINAL_TRICHOTOMY) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN ASSUME_TAC) THENL
   [SUBGOAL_THEN `(E:A->A->bool) pp1 cd2` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`a2:A`;
                    `a1:A`;`cd1:A`;`cd2:A`] EAUTN_COHERE) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      REWRITE_TAC[esubset] THEN
      DISCH_THEN(MP_TAC o SPEC `pp1:A`) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`a2:A`;`cd2:A`]
      AUTNSTAGE_COFUN) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPEC `pp1:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPEC `pp2:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPECL [`u:A`;`u':A`;`v:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    UNDISCH_THEN `a1:A = a2` SUBST_ALL_TAC THEN
    SUBGOAL_THEN `cd1:A = cd2` SUBST_ALL_TAC THENL
     [ASM_MESON_TAC[AUTNSTAGE_UNIQUE]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`a2:A`;`cd2:A`]
      AUTNSTAGE_COFUN) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPEC `pp1:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPEC `pp2:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPECL [`u:A`;`u':A`;`v:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    SUBGOAL_THEN `(E:A->A->bool) pp2 cd1` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`a1:A`;
                    `a2:A`;`cd2:A`;`cd1:A`] EAUTN_COHERE) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      REWRITE_TAC[esubset] THEN
      DISCH_THEN(MP_TAC o SPEC `pp2:A`) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`a1:A`;`cd1:A`]
      AUTNSTAGE_COFUN) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPEC `pp1:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPEC `pp2:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPECL [`u:A`;`u':A`;`v:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]]);;

(* ===================================================================== *)
(* step 8h : the autN image of a (function-coded) name is a function.     *)
(*   Members of v = autN(x) are pairs <autN t, autB c> (AUTN_MEM);        *)
(*   single-valuedness: equal first coords autN t = autN s force t = s    *)
(*   by AUTN_INJ, then c = e by eisfun x, then equal second coords by     *)
(*   the functionality of autB (ebij).                                     *)
(* ===================================================================== *)

let AUTN_ISFUN = prove
 (`!D (E:A->A->bool) B autB x v.
     model D E ZF_AX /\ B IN D /\ autB IN D /\ ebij D E autB B B /\
     eisfun D E x /\ eautn D E B autB x v
     ==> eisfun D E v`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
    (CONJUNCTS_THEN2 (LABEL_TAC "BD")
      (CONJUNCTS_THEN2 (LABEL_TAC "autBD")
        (CONJUNCTS_THEN2 (LABEL_TAC "bij")
          (CONJUNCTS_THEN2 (LABEL_TAC "fnx") (LABEL_TAC "aut")))))) THEN
  SUBGOAL_THEN `(x:A) IN D /\ (v:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[AUTN_IMP]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!k t t'. (k:A) IN D /\ (t:A) IN D /\ (t':A) IN D /\
             eapply D (E:A->A->bool) autB k t /\ eapply D E autB k t'
             ==> t = t'`
  (LABEL_TAC "asv") THENL
   [USE_THEN "bij" (STRIP_ASSUME_TAC o GEN_REWRITE_RULE I [ebij]) THEN
    ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!u w w' z z'. (u:A) IN D /\ (w:A) IN D /\ (w':A) IN D /\
                  eopair D (E:A->A->bool) u w z /\ E z x /\
                  eopair D E u w' z' /\ E z' x
                  ==> w = w'`
  (LABEL_TAC "xsv") THENL
   [USE_THEN "fnx" (STRIP_ASSUME_TAC o GEN_REWRITE_RULE I [eisfun]) THEN
    ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!z. (z:A) IN D
        ==> ((E:A->A->bool) z v <=>
             ?m t c t' c'. m IN D /\ t IN D /\ c IN D /\ t' IN D /\
                   c' IN D /\
                   E m x /\ eopair D E t c m /\ eautn D E B autB t t' /\
                   eapply D E autB c c' /\ eopair D E t' c' z)`
  (LABEL_TAC "memv") THENL
   [X_GEN_TAC `z:A` THEN DISCH_TAC THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`x:A`;`v:A`;
                  `z:A`] AUTN_MEM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  REWRITE_TAC[eisfun] THEN REPEAT CONJ_TAC THENL
   [FIRST_ASSUM ACCEPT_TAC;
    X_GEN_TAC `z:A` THEN STRIP_TAC THEN
    USE_THEN "memv" (MP_TAC o C MATCH_MP (ASSUME `(z:A) IN D`)) THEN
    REWRITE_TAC[ASSUME `(E:A->A->bool) z v`] THEN
    DISCH_THEN(X_CHOOSE_THEN `m:A` (X_CHOOSE_THEN `t:A` (X_CHOOSE_THEN `c:A`
      (X_CHOOSE_THEN `t':A` (X_CHOOSE_THEN `c':A`
        STRIP_ASSUME_TAC))))) THEN
    MAP_EVERY EXISTS_TAC [`t':A`;`c':A`] THEN ASM_REWRITE_TAC[];
    MAP_EVERY X_GEN_TAC [`u0:A`;`w:A`;`w':A`;`z:A`;`z':A`] THEN
    STRIP_TAC THEN
    SUBGOAL_THEN `(z:A) IN D /\ (z':A) IN D` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    USE_THEN "memv" (MP_TAC o C MATCH_MP (ASSUME `(z:A) IN D`)) THEN
    REWRITE_TAC[ASSUME `(E:A->A->bool) z v`] THEN
    DISCH_THEN(X_CHOOSE_THEN `m:A` (X_CHOOSE_THEN `t:A` (X_CHOOSE_THEN `c:A`
      (X_CHOOSE_THEN `t':A` (X_CHOOSE_THEN `c':A`
        STRIP_ASSUME_TAC))))) THEN
    USE_THEN "memv" (MP_TAC o C MATCH_MP (ASSUME `(z':A) IN D`)) THEN
    REWRITE_TAC[ASSUME `(E:A->A->bool) z' v`] THEN
    DISCH_THEN(X_CHOOSE_THEN `m2:A` (X_CHOOSE_THEN `s:A` (X_CHOOSE_THEN `e:A`
      (X_CHOOSE_THEN `s':A` (X_CHOOSE_THEN `e':A`
        STRIP_ASSUME_TAC))))) THEN
    SUBGOAL_THEN `t':A = u0 /\ c':A = w`
      (CONJUNCTS_THEN2 SUBST_ALL_TAC SUBST_ALL_TAC) THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`t':A`;`c':A`;`u0:A`;`w:A`;
                    `z:A`] EOPAIR_INJ) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `s':A = u0 /\ e':A = w'`
      (CONJUNCTS_THEN2 SUBST_ALL_TAC SUBST_ALL_TAC) THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`s':A`;`e':A`;`u0:A`;`w':A`;
                    `z':A`] EOPAIR_INJ) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `s:A = t` SUBST_ALL_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`s:A`;`t:A`;
                    `u0:A`] AUTN_INJ) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `e:A = c` SUBST_ALL_TAC THENL
     [USE_THEN "xsv" (MP_TAC o SPECL [`t:A`;`e:A`;`c:A`;`m2:A`;`m:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    USE_THEN "asv" (MP_TAC o SPECL [`c:A`;`w:A`;`w':A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]]);;

(* ===================================================================== *)
(* step 8i-1 : stage-stability object formula.  stab_form(d): every       *)
(*   pair <x,v> in the autN stage gamma_d (slot 81 resgraph) whose first   *)
(*   coordinate lies in the B-name stage y_d (slot 80 resgraph) has its    *)
(*   second coordinate in y_d too -- "autN maps stage-d names to stage-d   *)
(*   names".  Slots: 95=bn-stage (apply 80 0 95), 82=autn-stage (apply     *)
(*   81 0 82), 88=pair (forallmem over 82), 89=x, 90=v (opair binds 91,92).*)
(*   Mirror of cover_form/HOLDS_COVER_FORM/AUTNCOVER_SEM.                  *)
(* ===================================================================== *)

let stab_form = new_definition
  `stab_form =
     ?? 95 (apply_form 80 0 95 &&
            ?? 82 (apply_form 81 0 82 &&
                   !!- 88 82 (!! 89 (!! 90 (opair_form 89 90 88 -->
                                            ((89 %% 95) -->
                                             (90 %% 95)))))))`;;

let HOLDS_STAB_FORM = prove
 (`!D (E:A->A->bool) v.
     model D E ZF_AX /\ valuation D v
     ==> (holds D E v stab_form <=>
          ?yL. yL IN D /\ eapply D E (v 80) (v 0) yL /\
               ?stg. stg IN D /\ eapply D E (v 81) (v 0) stg /\
                     !pp. pp IN D /\ E pp stg
                          ==> !x vv. x IN D /\ vv IN D /\
                                     eopair D E x vv pp
                                     ==> E x yL ==> E vv yL)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!n. (v:num->A) n IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[stab_form; HOLDS_EX; HOLDS_AND] THEN
  MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s))
     ==> ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
  X_GEN_TAC `yL:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `valuation D ((95 |-> (yL:A)) v)` ASSUME_TAC THENL
   [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
           (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC)); ALL_TAC] THEN
  SUBGOAL_THEN
   `holds D E ((95 |-> (yL:A)) v) (apply_form 80 0 95) <=>
    eapply D E (v 80) (v 0) yL`
  (fun th -> REWRITE_TAC[th]) THENL
   [ASM_SIMP_TAC[HOLDS_APPLY_FORM] THEN REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  MATCH_MP_TAC(TAUT `(y <=> z) ==> ((x /\ y) <=> (x /\ z))`) THEN
  REWRITE_TAC[HOLDS_EX; HOLDS_AND] THEN
  MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s))
     ==> ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
  X_GEN_TAC `stg:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `valuation D ((82 |-> (stg:A)) ((95 |-> (yL:A)) v))`
  ASSUME_TAC THENL [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
      (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC)); ALL_TAC] THEN
  SUBGOAL_THEN
   `holds D E ((82 |-> (stg:A)) ((95 |-> (yL:A)) v)) (apply_form 81 0 82) <=>
    eapply D E (v 81) (v 0) stg`
  (fun th -> REWRITE_TAC[th]) THENL
   [ASM_SIMP_TAC[HOLDS_APPLY_FORM] THEN REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  MATCH_MP_TAC(TAUT `(y <=> z) ==> ((x /\ y) <=> (x /\ z))`) THEN
  ASM_SIMP_TAC[HOLDS_FORALLMEM; ARITH_RULE `~(88 = 82)`] THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN
  MATCH_MP_TAC(MESON[]
    `(!pp:A. M pp ==> (P pp <=> Q pp))
     ==> ((!pp. M pp ==> P pp) <=> (!pp. M pp ==> Q pp))`) THEN
  X_GEN_TAC `pp:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `valuation D ((88 |-> (pp:A)) ((82 |-> (stg:A)) ((95 |-> (yL:A)) v)))`
  ASSUME_TAC THENL [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
      (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC)); ALL_TAC] THEN
  REWRITE_TAC[holds] THEN
  MATCH_MP_TAC(MESON[]
    `(!x vv:A. x IN D /\ vv IN D ==> (H x vv <=> (R x vv ==> S x vv)))
     ==> ((!x. x IN D ==> !vv. vv IN D ==> H x vv) <=>
          (!x vv. x IN D /\ vv IN D /\ R x vv ==> S x vv))`) THEN
  MAP_EVERY X_GEN_TAC [`x:A`;`vv:A`] THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `valuation D ((90 |-> (vv:A)) ((89 |-> (x:A)) ((88 |-> (pp:A))
      ((82 |-> (stg:A)) ((95 |-> (yL:A)) v)))))`
  ASSUME_TAC THENL [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
      (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC)); ALL_TAC] THEN
  MATCH_MP_TAC(TAUT
    `(a <=> c) /\ (b <=> d) ==> ((a ==> b) <=> (c ==> d))`) THEN
  CONJ_TAC THENL
   [ASM_SIMP_TAC[HOLDS_OPAIR_FORM] THEN REWRITE_TAC[VALMOD; ARITH_EQ];
    REWRITE_TAC[VALMOD; ARITH_EQ]]);;

let STAB_SEM = prove
 (`!D (E:A->A->bool) B autB sa rL rc v0 b.
      model D E ZF_AX /\ B IN D /\ autB IN D /\ eordinal D E sa /\
      rL IN D /\ rc IN D /\ valuation D v0 /\
      (!pp. pp IN D
            ==> (E pp rL <=>
                 ?b' z'. b' IN D /\ z' IN D /\ E b' sa /\
                         ebnstage D E B b' z' /\ eopair D E b' z' pp)) /\
      (!pp. pp IN D
            ==> (E pp rc <=>
                 ?b' z'. b' IN D /\ z' IN D /\ E b' sa /\
                         autnstage D E B autB b' z' /\ eopair D E b' z' pp)) /\
      b IN D /\ E b sa
      ==> (holds D E ((0 |-> b) ((80 |-> rL) ((81 |-> rc) v0))) stab_form <=>
           !yb cd.
              yb IN D /\ cd IN D /\
              ebnstage D E B b yb /\ autnstage D E B autB b cd
              ==> !pp. pp IN D /\ E pp cd
                   ==> !x vv. x IN D /\ vv IN D /\ eopair D E x vv pp
                              ==> E x yb ==> E vv yb)`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
        (CONJUNCTS_THEN2 ASSUME_TAC
          (CONJUNCTS_THEN2 (LABEL_TAC "rLc") (CONJUNCTS_THEN2 (LABEL_TAC "rcc")
            (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC)))))))))) THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) b` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
  SUBGOAL_THEN
   `valuation D ((0 |-> (b:A)) ((80 |-> (rL:A)) ((81 |-> (rc:A)) v0)))`
  ASSUME_TAC THENL [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
      (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC)); ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;
    `(0 |-> (b:A)) ((80 |-> (rL:A)) ((81 |-> (rc:A)) v0))`]
    HOLDS_STAB_FORM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `yL:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 (LABEL_TAC "eaL")
        (X_CHOOSE_THEN `stg:A` (CONJUNCTS_THEN2 ASSUME_TAC
          (CONJUNCTS_THEN2 (LABEL_TAC "eac") (LABEL_TAC "stab"))))))) THEN
    SUBGOAL_THEN `ebnstage D (E:A->A->bool) B b yL` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;
        `ebnstage D (E:A->A->bool) B`;
        `sa:A`;`rL:A`;`b:A`;`yL:A`] EGRAPH_APPLY) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> MP_TAC(EQ_MP th
        (ASSUME `eapply D (E:A->A->bool) rL b yL`))) THEN
      DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC ACCEPT_TAC);
      ALL_TAC] THEN
    SUBGOAL_THEN `autnstage D (E:A->A->bool) B autB b stg` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;
        `autnstage D (E:A->A->bool) B autB`;`sa:A`;`rc:A`;`b:A`;`stg:A`]
        EGRAPH_APPLY) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> MP_TAC(EQ_MP th
        (ASSUME `eapply D (E:A->A->bool) rc b stg`))) THEN
      DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC ACCEPT_TAC);
      ALL_TAC] THEN
    MAP_EVERY X_GEN_TAC [`yb:A`;`cd:A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN `yb:A = yL` SUBST_ALL_TAC THENL
     [ASM_MESON_TAC[EBNSTAGE_UNIQUE]; ALL_TAC] THEN
    SUBGOAL_THEN `cd:A = stg` SUBST_ALL_TAC THENL
     [ASM_MESON_TAC[AUTNSTAGE_UNIQUE]; ALL_TAC] THEN
    USE_THEN "stab" ACCEPT_TAC;
    DISCH_THEN(LABEL_TAC "sem") THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`b:A`]
      EBNSTAGE_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `yL:A` STRIP_ASSUME_TAC) THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`b:A`]
      AUTNSTAGE_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `stg:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `yL:A` THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `eapply D (E:A->A->bool) rL b yL` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;
        `ebnstage D (E:A->A->bool) B`;
        `sa:A`;`rL:A`;`b:A`;`yL:A`] EGRAPH_APPLY) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN EXISTS_TAC `stg:A` THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `eapply D (E:A->A->bool) rc b stg` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;
        `autnstage D (E:A->A->bool) B autB`;`sa:A`;`rc:A`;`b:A`;`stg:A`]
        EGRAPH_APPLY) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "sem" (MP_TAC o SPECL [`yL:A`;`stg:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]]);;

(* ===================================================================== *)
(* step 8i-2 : STAB_STEP, the stage-preservation induction step.          *)
(*   Given stability below d: a pair <x,v> in gamma_d with x IN y_d       *)
(*   (B-name stage) has v IN y_d.  Members of v are <gacc t, autB c> for  *)
(*   <t,c> IN x; t IN w_bn(d) places t in an earlier bn-stage y_b, the    *)
(*   gacc-pair <t,t'> lives in an earlier autn-stage gamma_b'; lifting    *)
(*   both to the larger of b,b' (EBNSTAGE_MONO / EAUTN_COHERE) the IH     *)
(*   puts t' = autN t in that earlier bn-stage, hence in w_bn(d); autB c  *)
(*   IN B by ebij range.  So v IN bnfuns(B,w_bn(d)) = y_d via             *)
(*   EBNMEM_GENERAL (v is a function by AUTN_ISFUN).                      *)
(* ===================================================================== *)

let STAB_STEP = prove
 (`!D (E:A->A->bool) B autB d.
      model D E ZF_AX /\ B IN D /\ autB IN D /\ ebij D E autB B B /\
      eordinal D E d /\
      (!b'. b' IN D /\ E b' d
            ==> !yb cd.
                   yb IN D /\ cd IN D /\
                   ebnstage D E B b' yb /\ autnstage D E B autB b' cd
                   ==> !pp. pp IN D /\ E pp cd
                        ==> !x vv. x IN D /\ vv IN D /\ eopair D E x vv pp
                                   ==> E x yb ==> E vv yb)
      ==> !yd cd.
             yd IN D /\ cd IN D /\
             ebnstage D E B d yd /\ autnstage D E B autB d cd
             ==> !pp. pp IN D /\ E pp cd
                  ==> !x vv. x IN D /\ vv IN D /\ eopair D E x vv pp
                             ==> E x yd ==> E vv yd`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
    (CONJUNCTS_THEN2 (LABEL_TAC "BD")
      (CONJUNCTS_THEN2 (LABEL_TAC "autBD")
        (CONJUNCTS_THEN2 (LABEL_TAC "bij")
          (CONJUNCTS_THEN2 (LABEL_TAC "dord") (LABEL_TAC "IH")))))) THEN
  SUBGOAL_THEN
   `!k t. (k:A) IN D /\ (t:A) IN D /\ eapply D (E:A->A->bool) autB k t
          ==> E t B`
  (LABEL_TAC "arng") THENL
   [USE_THEN "bij" (STRIP_ASSUME_TAC o GEN_REWRITE_RULE I [ebij]) THEN
    ASM_MESON_TAC[];
    ALL_TAC] THEN
  MAP_EVERY X_GEN_TAC [`yd:A`;`cd:A`] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "ydD")
    (CONJUNCTS_THEN2 (LABEL_TAC "cdD")
      (CONJUNCTS_THEN2 (LABEL_TAC "bstg") (LABEL_TAC "astg")))) THEN
  X_GEN_TAC `pp:A` THEN STRIP_TAC THEN
  MAP_EVERY X_GEN_TAC [`x:A`;`vv:A`] THEN STRIP_TAC THEN DISCH_TAC THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`d:A`;`yd:A`]
    EBNSTAGE_CHAR) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `wb:A` (CONJUNCTS_THEN2 (LABEL_TAC "wbD")
    (CONJUNCTS_THEN2 (LABEL_TAC "wbc") (LABEL_TAC "bnfb")))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`d:A`;`cd:A`]
        EAUTNSTAGE_CHAR) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `gacc:A` (X_CHOOSE_THEN `wa:A`
   (X_CHOOSE_THEN `stg:A`
    (CONJUNCTS_THEN2 (LABEL_TAC "gaccD") (CONJUNCTS_THEN2 (LABEL_TAC "waD")
     (CONJUNCTS_THEN2 (LABEL_TAC "stgD") (CONJUNCTS_THEN2 (LABEL_TAC "gaccch")
      (CONJUNCTS_THEN2 (LABEL_TAC "domn") (CONJUNCTS_THEN2 (LABEL_TAC "bnfa")
       (LABEL_TAC "cdch")))))))))) THEN
  (* the pair <x,vv> read through the stage characterisation *)
  USE_THEN "cdch" (MP_TAC o C MATCH_MP (ASSUME `(pp:A) IN D`)) THEN
  REWRITE_TAC[ASSUME `(E:A->A->bool) pp cd`] THEN
  DISCH_THEN(X_CHOOSE_THEN `x2:A` (X_CHOOSE_THEN `img:A`
    (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 (LABEL_TAC "xstg") (CONJUNCTS_THEN2 ASSUME_TAC
        (LABEL_TAC "imgch"))))))) THEN
  SUBGOAL_THEN `x2:A = x /\ img:A = vv`
    (CONJUNCTS_THEN2 SUBST_ALL_TAC SUBST_ALL_TAC) THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`x2:A`;`img:A`;`x:A`;`vv:A`;
                  `pp:A`] EOPAIR_INJ) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  (* x is a bn-function over wb (from E x yd) *)
  SUBGOAL_THEN `ebnmem D (E:A->A->bool) B wb x` (LABEL_TAC "bnmxb") THENL
   [USE_THEN "bnfb" (MP_TAC o SPEC `x:A` o CONJUNCT2 o
      GEN_REWRITE_RULE I [ebnfuns]) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `eisfun D (E:A->A->bool) x /\
    ?cr. (cr:A) IN D /\ ecross D (E:A->A->bool) wb B cr /\ esubset D E x cr`
  (CONJUNCTS_THEN2 (LABEL_TAC "fnx") STRIP_ASSUME_TAC) THENL
   [USE_THEN "bnmxb" (MP_TAC o GEN_REWRITE_RULE I [ebnmem]) THEN
    DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  (* vv is autN(x), hence a function *)
  SUBGOAL_THEN `eautn D (E:A->A->bool) B autB x vv` (LABEL_TAC "aut") THENL
   [MATCH_MP_TAC AUTN_STAGE THEN
    MAP_EVERY EXISTS_TAC [`d:A`;`cd:A`;`pp:A`] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `eisfun D (E:A->A->bool) vv` (LABEL_TAC "fnv") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`x:A`;`vv:A`]
      AUTN_ISFUN) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  (* transfer: gacc moves wb-members to wb-members, via the IH *)
  SUBGOAL_THEN
   `!t t'. (t:A) IN D /\ (t':A) IN D /\ (E:A->A->bool) t wb /\
           eapply D E gacc t t'
           ==> E t' wb`
  (LABEL_TAC "tfer") THENL
   [MAP_EVERY X_GEN_TAC [`t:A`;`t':A`] THEN STRIP_TAC THEN
    USE_THEN "wbc" (MP_TAC o SPEC `t:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(EQ_MP th
      (ASSUME `(E:A->A->bool) t wb`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `zb:A`
      (fun t -> MAP_EVERY ASSUME_TAC (CONJUNCTS t)))) THEN
    SUBGOAL_THEN `eordinal D (E:A->A->bool) b` ASSUME_TAC THENL
     [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
    UNDISCH_TAC `eapply D (E:A->A->bool) gacc t t'` THEN
    REWRITE_TAC[eapply] THEN
    DISCH_THEN(X_CHOOSE_THEN `pt:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(pt:A) IN D` ASSUME_TAC THENL
     [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
    USE_THEN "gaccch" (MP_TAC o C MATCH_MP (ASSUME `(pt:A) IN D`)) THEN
    REWRITE_TAC[ASSUME `(E:A->A->bool) pt gacc`] THEN
    DISCH_THEN(X_CHOOSE_THEN `b':A` (X_CHOOSE_THEN `zb':A`
      STRIP_ASSUME_TAC)) THEN
    SUBGOAL_THEN `eordinal D (E:A->A->bool) b'` ASSUME_TAC THENL
     [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`b:A`;`b':A`]
      EORDINAL_TRICHOTOMY) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN ASSUME_TAC) THENL
     [(* E b b' : work at b' *)
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`b':A`]
        EBNSTAGE_EXISTS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `yb':A` STRIP_ASSUME_TAC) THEN
      SUBGOAL_THEN `(E:A->A->bool) t yb'` ASSUME_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`b':A`;`b:A`;
                      `yb':A`;`zb:A`;`t:A`] EBNSTAGE_MONO) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
        ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) t' yb'` ASSUME_TAC THENL
       [USE_THEN "IH" (MP_TAC o SPEC `b':A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(MP_TAC o SPECL [`yb':A`;`zb':A`]) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(MP_TAC o SPEC `pt:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(MP_TAC o SPECL [`t:A`;`t':A`]) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(MP_TAC o C MP (ASSUME `(E:A->A->bool) t yb'`)) THEN
        DISCH_THEN ACCEPT_TAC;
        ALL_TAC] THEN
      USE_THEN "wbc" (MP_TAC o SPEC `t':A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MAP_EVERY EXISTS_TAC [`b':A`;`yb':A`] THEN ASM_REWRITE_TAC[];
      (* b = b' : work at b' with zb *)
      UNDISCH_THEN `b:A = b'` SUBST_ALL_TAC THEN
      SUBGOAL_THEN `(E:A->A->bool) t' zb` ASSUME_TAC THENL
       [USE_THEN "IH" (MP_TAC o SPEC `b':A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(MP_TAC o SPECL [`zb:A`;`zb':A`]) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(MP_TAC o SPEC `pt:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(MP_TAC o SPECL [`t:A`;`t':A`]) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(MP_TAC o C MP (ASSUME `(E:A->A->bool) t zb`)) THEN
        DISCH_THEN ACCEPT_TAC;
        ALL_TAC] THEN
      USE_THEN "wbc" (MP_TAC o SPEC `t':A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MAP_EVERY EXISTS_TAC [`b':A`;`zb:A`] THEN ASM_REWRITE_TAC[];
      (* E b' b : lift the pair into gamma_b *)
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`b:A`]
        AUTNSTAGE_EXISTS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `cdb:A` STRIP_ASSUME_TAC) THEN
      SUBGOAL_THEN `(E:A->A->bool) pt cdb` ASSUME_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`b:A`;
                      `b':A`;`zb':A`;`cdb:A`] EAUTN_COHERE) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        REWRITE_TAC[esubset] THEN
        DISCH_THEN(MP_TAC o SPEC `pt:A`) THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) t' zb` ASSUME_TAC THENL
       [USE_THEN "IH" (MP_TAC o SPEC `b:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(MP_TAC o SPECL [`zb:A`;`cdb:A`]) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(MP_TAC o SPEC `pt:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(MP_TAC o SPECL [`t:A`;`t':A`]) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(MP_TAC o C MP (ASSUME `(E:A->A->bool) t zb`)) THEN
        DISCH_THEN ACCEPT_TAC;
        ALL_TAC] THEN
      USE_THEN "wbc" (MP_TAC o SPEC `t':A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MAP_EVERY EXISTS_TAC [`b:A`;`zb:A`] THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  (* assemble: vv IN bnfuns(B,wb) = yd *)
  SUBGOAL_THEN `ebnmem D (E:A->A->bool) B wb vv` ASSUME_TAC THENL
   [MATCH_MP_TAC EBNMEM_GENERAL THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `q:A` THEN STRIP_TAC THEN
    USE_THEN "imgch" (MP_TAC o C MATCH_MP (ASSUME `(q:A) IN D`)) THEN
    REWRITE_TAC[ASSUME `(E:A->A->bool) q vv`] THEN
    DISCH_THEN(X_CHOOSE_THEN `m:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC MP_TAC))) THEN
    REWRITE_TAC[aprrel] THEN
    DISCH_THEN(X_CHOOSE_THEN `t0:A` (X_CHOOSE_THEN `c0:A`
      (X_CHOOSE_THEN `t':A` (X_CHOOSE_THEN `c':A` STRIP_ASSUME_TAC)))) THEN
    SUBGOAL_THEN `(E:A->A->bool) m cr` ASSUME_TAC THENL
     [UNDISCH_TAC `esubset D (E:A->A->bool) x cr` THEN
      REWRITE_TAC[esubset] THEN
      DISCH_THEN(MP_TAC o SPEC `m:A`) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`wb:A`;`B:A`;`cr:A`;`m:A`]
      ECROSS_MEMBER) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) m cr`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `t:A` (X_CHOOSE_THEN `c:A`
      STRIP_ASSUME_TAC)) THEN
    SUBGOAL_THEN `t0:A = t /\ c0:A = c`
      (CONJUNCTS_THEN2 SUBST_ALL_TAC SUBST_ALL_TAC) THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`t0:A`;`c0:A`;`t:A`;`c:A`;
                    `m:A`] EOPAIR_INJ) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`t':A`;`c':A`] THEN ASM_REWRITE_TAC[] THEN
    CONJ_TAC THENL
     [USE_THEN "tfer" (MP_TAC o SPECL [`t:A`;`t':A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      USE_THEN "arng" (MP_TAC o SPECL [`c:A`;`c':A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]];
    ALL_TAC] THEN
  USE_THEN "bnfb" (MP_TAC o SPEC `vv:A` o CONJUNCT2 o
    GEN_REWRITE_RULE I [ebnfuns]) THEN
  ASM_REWRITE_TAC[]);;

(* ===================================================================== *)
(* step 8i-3 : stage preservation of autN + "autN images are B-names".    *)
(*   AUTN_STAGE_PRESERVE runs BOTH least-counterexample inductions over   *)
(*   the shared resolvent graphs (coverage to land the pair <x,autN x> at *)
(*   x's own bn-stage index a, stability to keep the image inside y_a).   *)
(* ===================================================================== *)

let AUTN_STAGE_PRESERVE = prove
 (`!D (E:A->A->bool) B autB a ya x v.
     model D E ZF_AX /\ B IN D /\ autB IN D /\ ebij D E autB B B /\
     eordinal D E a /\ ya IN D /\ ebnstage D E B a ya /\
     x IN D /\ E x ya /\ v IN D /\ eautn D E B autB x v
     ==> E v ya`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(a:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`a:A`] ESUC_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `sa:A`) THEN
  SUBGOAL_THEN `(sa:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) sa` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_ESUC]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) a sa` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_MEMBER]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`sa:A`]
    EBNSTAGE_RESGRAPH) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `rL:A` (CONJUNCTS_THEN2 (LABEL_TAC "rLD")
    (LABEL_TAC "rLc"))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`sa:A`]
    EAUTNSTAGE_RESGRAPH) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `rc:A` (CONJUNCTS_THEN2 (LABEL_TAC "rcD")
    (LABEL_TAC "rcc"))) THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v0:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  SUBGOAL_THEN `valuation D ((80 |-> (rL:A)) ((81 |-> (rc:A)) v0))`
  ASSUME_TAC THENL [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
      (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC)); ALL_TAC] THEN
  SUBGOAL_THEN
   `!dd. dd IN D /\ E dd sa
         ==> holds D E ((0 |-> dd) ((80 |-> (rL:A)) ((81 |-> (rc:A)) v0)))
                       cover_form`
  (LABEL_TAC "cov") THENL
   [GEN_TAC THEN STRIP_TAC THEN
    MATCH_MP_TAC(TAUT `(~p ==> F) ==> p`) THEN
    DISCH_THEN(LABEL_TAC "bad0") THEN
    SUBGOAL_THEN `eordinal D (E:A->A->bool) dd` ASSUME_TAC THENL
     [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`Not cover_form`;
                  `(80 |-> (rL:A)) ((81 |-> (rc:A)) v0)`;`dd:A`]
      EORDINAL_LEAST) THEN
    ASM_REWRITE_TAC[HOLDS_NOT] THEN
    DISCH_THEN(X_CHOOSE_THEN `d:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 (LABEL_TAC "dbad")
        (LABEL_TAC "dmin"))))) THEN
    SUBGOAL_THEN `(d:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) d sa` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`d:A`;`dd:A`]
        EORDINAL_TRICHOTOMY) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN ASSUME_TAC) THENL
       [ASM_MESON_TAC[EORDINAL_TRANS_E];
        ASM_MESON_TAC[];
        USE_THEN "dmin" (MP_TAC o SPEC `dd:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        USE_THEN "bad0" (fun th -> REWRITE_TAC[th])];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `!b'. b' IN D /\ (E:A->A->bool) b' d
           ==> !yb cd.
                  yb IN D /\ cd IN D /\
                  ebnstage D E B b' yb /\ autnstage D E B autB b' cd
                  ==> !u. u IN D /\ E u yb
                          ==> ?img. img IN D /\ ?pp. pp IN D /\
                                    eopair D E u img pp /\ E pp cd`
    ASSUME_TAC THENL
     [X_GEN_TAC `b':A` THEN STRIP_TAC THEN
      SUBGOAL_THEN `(E:A->A->bool) b' sa` ASSUME_TAC THENL
       [ASM_MESON_TAC[EORDINAL_TRANS_E]; ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`sa:A`;
                    `rL:A`;`rc:A`;`v0:num->A`;`b':A`] AUTNCOVER_SEM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(MP_TAC o fst o EQ_IMP_RULE) THEN
      ANTS_TAC THENL
       [USE_THEN "dmin" (MP_TAC o SPEC `b':A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
        DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `holds D E ((0 |-> (d:A)) ((80 |-> (rL:A)) ((81 |-> (rc:A)) v0)))
                cover_form`
    MP_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`sa:A`;
                    `rL:A`;`rc:A`;`v0:num->A`;`d:A`] AUTNCOVER_SEM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`d:A`]
        AUTNCOVER_STEP) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      USE_THEN "dbad" (fun th -> REWRITE_TAC[th])];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!dd. dd IN D /\ E dd sa
         ==> holds D E ((0 |-> dd) ((80 |-> (rL:A)) ((81 |-> (rc:A)) v0)))
                       stab_form`
  (LABEL_TAC "stb") THENL
   [GEN_TAC THEN STRIP_TAC THEN
    MATCH_MP_TAC(TAUT `(~p ==> F) ==> p`) THEN
    DISCH_THEN(LABEL_TAC "bad0") THEN
    SUBGOAL_THEN `eordinal D (E:A->A->bool) dd` ASSUME_TAC THENL
     [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`Not stab_form`;
                  `(80 |-> (rL:A)) ((81 |-> (rc:A)) v0)`;`dd:A`]
      EORDINAL_LEAST) THEN
    ASM_REWRITE_TAC[HOLDS_NOT] THEN
    DISCH_THEN(X_CHOOSE_THEN `d:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 (LABEL_TAC "dbad")
        (LABEL_TAC "dmin"))))) THEN
    SUBGOAL_THEN `(d:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) d sa` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`d:A`;`dd:A`]
