let EAUTN_IS_BNAME = prove
 (`!D (E:A->A->bool) B autB x v.
     model D E ZF_AX /\ B IN D /\ autB IN D /\ ebij D E autB B B /\
     bname D E B x /\ eautn D E B autB x v
     ==> bname D E B v`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(x:A) IN D /\ (v:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[AUTN_IMP]; ALL_TAC] THEN
  UNDISCH_TAC `bname D (E:A->A->bool) B x` THEN
  REWRITE_TAC[bname] THEN
  DISCH_THEN(X_CHOOSE_THEN `a:A` (X_CHOOSE_THEN `ya:A`
    (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th)))) THEN
  SUBGOAL_THEN `(E:A->A->bool) v ya` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`a:A`;`ya:A`;
                  `x:A`;`v:A`] AUTN_STAGE_PRESERVE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`a:A`;`ya:A`] THEN ASM_REWRITE_TAC[]);;

(* ===================================================================== *)
(* step 8j-1 : composition object formula.  comp_form(d): for every        *)
(*   x in the B-name stage y_d (slot 79 resgraph), pair <x,v> in the       *)
(*   autB-tower stage gamma_d (slot 81) and pair <v,w> in the autB'-tower  *)
(*   stage gamma'_d (slot 80), w = x -- "autN' o autN = id on stage-d      *)
(*   names".  Slots: stages 100 (bn), 110 (autB'), 120 (autB); x=130      *)
(*   (forallmem over 100), p=131 (over 120), p'=132 (over 110); v=133,    *)
(*   w=136 (opair_forms bind 134,135 resp. 137,138).                       *)
(* ===================================================================== *)

let comp_form = new_definition
  `comp_form =
     ?? 100 (apply_form 79 0 100 &&
      ?? 110 (apply_form 80 0 110 &&
       ?? 120 (apply_form 81 0 120 &&
        !!- 130 100 (!!- 131 120 (!!- 132 110 (
          !! 133 (!! 136 (
            (opair_form 130 133 131 && opair_form 133 136 132)
            --> Eq 136 130))))))))`;;

let HOLDS_COMP_FORM = prove
 (`!D (E:A->A->bool) v.
     model D E ZF_AX /\ valuation D v
     ==> (holds D E v comp_form <=>
          ?yL. yL IN D /\ eapply D E (v 79) (v 0) yL /\
           ?ga. ga IN D /\ eapply D E (v 80) (v 0) ga /\
            ?stg. stg IN D /\ eapply D E (v 81) (v 0) stg /\
                  !x. x IN D /\ E x yL
                      ==> !pp. pp IN D /\ E pp stg
                           ==> !pp'. pp' IN D /\ E pp' ga
                                ==> !vv w.
                                       vv IN D /\ w IN D /\
                                       eopair D E x vv pp /\
                                       eopair D E vv w pp'
                                       ==> w = x)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!n. (v:num->A) n IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[comp_form; HOLDS_EX; HOLDS_AND] THEN
  MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s))
     ==> ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
  X_GEN_TAC `yL:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `valuation D ((100 |-> (yL:A)) v)` ASSUME_TAC THENL
   [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
           (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC)); ALL_TAC] THEN
  SUBGOAL_THEN
   `holds D E ((100 |-> (yL:A)) v) (apply_form 79 0 100) <=>
    eapply D E (v 79) (v 0) yL`
  (fun th -> REWRITE_TAC[th]) THENL
   [ASM_SIMP_TAC[HOLDS_APPLY_FORM] THEN REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  MATCH_MP_TAC(TAUT `(y <=> z) ==> ((x /\ y) <=> (x /\ z))`) THEN
  REWRITE_TAC[HOLDS_EX; HOLDS_AND] THEN
  MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s))
     ==> ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
  X_GEN_TAC `ga:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `valuation D ((110 |-> (ga:A)) ((100 |-> (yL:A)) v))`
  ASSUME_TAC THENL [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
      (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC)); ALL_TAC] THEN
  SUBGOAL_THEN
   `holds D E ((110 |-> (ga:A)) ((100 |-> (yL:A)) v))
      (apply_form 80 0 110) <=>
    eapply D E (v 80) (v 0) ga`
  (fun th -> REWRITE_TAC[th]) THENL
   [ASM_SIMP_TAC[HOLDS_APPLY_FORM] THEN REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  MATCH_MP_TAC(TAUT `(y <=> z) ==> ((x /\ y) <=> (x /\ z))`) THEN
  REWRITE_TAC[HOLDS_EX; HOLDS_AND] THEN
  MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s))
     ==> ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
  X_GEN_TAC `stg:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN
   `valuation D ((120 |-> (stg:A)) ((110 |-> (ga:A)) ((100 |-> (yL:A)) v)))`
  ASSUME_TAC THENL [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
      (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC)); ALL_TAC] THEN
  SUBGOAL_THEN
   `holds D E ((120 |-> (stg:A)) ((110 |-> (ga:A)) ((100 |-> (yL:A)) v)))
      (apply_form 81 0 120) <=>
    eapply D E (v 81) (v 0) stg`
  (fun th -> REWRITE_TAC[th]) THENL
   [ASM_SIMP_TAC[HOLDS_APPLY_FORM] THEN REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  MATCH_MP_TAC(TAUT `(y <=> z) ==> ((x /\ y) <=> (x /\ z))`) THEN
  ASM_SIMP_TAC[HOLDS_FORALLMEM; ARITH_RULE `~(130 = 100)`] THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN
  MATCH_MP_TAC(MESON[]
    `(!x:A. M x ==> (P x <=> Q x))
     ==> ((!x. M x ==> P x) <=> (!x. M x ==> Q x))`) THEN
  X_GEN_TAC `x:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `valuation D ((130 |-> (x:A)) ((120 |-> (stg:A)) ((110 |-> (ga:A))
      ((100 |-> (yL:A)) v))))`
  ASSUME_TAC THENL [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
      (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC)); ALL_TAC] THEN
  ASM_SIMP_TAC[HOLDS_FORALLMEM; ARITH_RULE `~(131 = 120)`] THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN
  MATCH_MP_TAC(MESON[]
    `(!pp:A. M pp ==> (P pp <=> Q pp))
     ==> ((!pp. M pp ==> P pp) <=> (!pp. M pp ==> Q pp))`) THEN
  X_GEN_TAC `pp:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `valuation D ((131 |-> (pp:A)) ((130 |-> (x:A)) ((120 |-> (stg:A))
      ((110 |-> (ga:A)) ((100 |-> (yL:A)) v)))))`
  ASSUME_TAC THENL [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
      (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC)); ALL_TAC] THEN
  ASM_SIMP_TAC[HOLDS_FORALLMEM; ARITH_RULE `~(132 = 110)`] THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN
  MATCH_MP_TAC(MESON[]
    `(!pp':A. M pp' ==> (P pp' <=> Q pp'))
     ==> ((!pp'. M pp' ==> P pp') <=> (!pp'. M pp' ==> Q pp'))`) THEN
  X_GEN_TAC `pp':A` THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `valuation D ((132 |-> (pp':A)) ((131 |-> (pp:A)) ((130 |-> (x:A))
      ((120 |-> (stg:A)) ((110 |-> (ga:A)) ((100 |-> (yL:A)) v))))))`
  ASSUME_TAC THENL [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
      (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC)); ALL_TAC] THEN
  REWRITE_TAC[holds] THEN
  MATCH_MP_TAC(MESON[]
    `(!vv w:A. vv IN D /\ w IN D
         ==> (H vv w <=> (R vv w ==> w = x)))
     ==> ((!vv. vv IN D ==> !w. w IN D ==> H vv w) <=>
          (!vv w. vv IN D /\ w IN D /\ R vv w ==> w = x))`) THEN
  MAP_EVERY X_GEN_TAC [`vv:A`;`w:A`] THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `valuation D ((136 |-> (w:A)) ((133 |-> (vv:A)) ((132 |-> (pp':A))
