let COMP_SEM = prove
 (`!D (E:A->A->bool) B autB autB' sa rbn rg rc v0 b.
      model D E ZF_AX /\ B IN D /\ autB IN D /\ autB' IN D /\
      eordinal D E sa /\
      rbn IN D /\ rg IN D /\ rc IN D /\ valuation D v0 /\
      (!pp. pp IN D
            ==> (E pp rbn <=>
                 ?b' z'. b' IN D /\ z' IN D /\ E b' sa /\
                         ebnstage D E B b' z' /\ eopair D E b' z' pp)) /\
      (!pp. pp IN D
            ==> (E pp rg <=>
                 ?b' z'. b' IN D /\ z' IN D /\ E b' sa /\
                         autnstage D E B autB' b' z' /\
                         eopair D E b' z' pp)) /\
      (!pp. pp IN D
            ==> (E pp rc <=>
                 ?b' z'. b' IN D /\ z' IN D /\ E b' sa /\
                         autnstage D E B autB b' z' /\
                         eopair D E b' z' pp)) /\
      b IN D /\ E b sa
      ==> (holds D E ((0 |-> b) ((79 |-> rbn) ((80 |-> rg)
             ((81 |-> rc) v0)))) comp_form <=>
           !yb cd' cd.
              yb IN D /\ cd' IN D /\ cd IN D /\
              ebnstage D E B b yb /\ autnstage D E B autB' b cd' /\
              autnstage D E B autB b cd
              ==> !x. x IN D /\ E x yb
                   ==> !pp. pp IN D /\ E pp cd
                        ==> !pp'. pp' IN D /\ E pp' cd'
                             ==> !vv w.
                                    vv IN D /\ w IN D /\
                                    eopair D E x vv pp /\
                                    eopair D E vv w pp'
                                    ==> w = x)`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
        (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
