    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `yL:A` STRIP_ASSUME_TAC) THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB':A`;`b:A`]
      AUTNSTAGE_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `gaa:A` STRIP_ASSUME_TAC) THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`b:A`]
      AUTNSTAGE_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `stg:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `yL:A` THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `eapply D (E:A->A->bool) rbn b yL` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;
        `ebnstage D (E:A->A->bool) B`;
        `sa:A`;`rbn:A`;`b:A`;`yL:A`] EGRAPH_APPLY) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN EXISTS_TAC `gaa:A` THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `eapply D (E:A->A->bool) rg b gaa` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;
        `autnstage D (E:A->A->bool) B autB'`;`sa:A`;`rg:A`;`b:A`;`gaa:A`]
        EGRAPH_APPLY) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN EXISTS_TAC `stg:A` THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `eapply D (E:A->A->bool) rc b stg` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;
        `autnstage D (E:A->A->bool) B autB`;`sa:A`;`rc:A`;`b:A`;`stg:A`]
        EGRAPH_APPLY) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "sem" (MP_TAC o SPECL [`yL:A`;`gaa:A`;`stg:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]]);;

(* ===================================================================== *)
(* step 8j-2 : COMP_STEP.  Composition autN' o autN = id at stage d,      *)
(*   given (below d) coverage of both towers, stability of the autB       *)
(*   tower, and the composition IH.  Core = "key": for t IN wb with       *)
(*   gacc-value t', the autB'-tower graph gacc' maps t' back to t --      *)
(*   land t's pair at its OWN bn-stage b (coverage + AUTN_SV), keep t'    *)
(*   at stage b (stability), take t''s autB'-pair at b (coverage') and    *)
(*   identify its value with t by the composition IH at b.  Then w = x    *)
(*   by extensionality through the two image characterisations, using    *)
(*   eisfun gacc' (EAUTN_GACC_ISFUN + EAUTN_COHERE) and the autB          *)
(*   injectivity / inverse characterisation on second coordinates.        *)
(* ===================================================================== *)

let COMP_STEP = prove
 (`!D (E:A->A->bool) B autB autB' d.
      model D E ZF_AX /\ B IN D /\ autB IN D /\ autB' IN D /\
      ebij D E autB B B /\
      (!k t. k IN D /\ t IN D
             ==> (eapply D E autB' t k <=> eapply D E autB k t)) /\
      eordinal D E d /\
      (!b'. b' IN D /\ E b' d
            ==> !yb cd.
                   yb IN D /\ cd IN D /\
                   ebnstage D E B b' yb /\ autnstage D E B autB b' cd
                   ==> !u. u IN D /\ E u yb
                           ==> ?img. img IN D /\ ?pp. pp IN D /\
                                     eopair D E u img pp /\ E pp cd) /\
      (!b'. b' IN D /\ E b' d
            ==> !yb cd.
                   yb IN D /\ cd IN D /\
                   ebnstage D E B b' yb /\ autnstage D E B autB' b' cd
                   ==> !u. u IN D /\ E u yb
                           ==> ?img. img IN D /\ ?pp. pp IN D /\
                                     eopair D E u img pp /\ E pp cd) /\
      (!b'. b' IN D /\ E b' d
            ==> !yb cd.
                   yb IN D /\ cd IN D /\
                   ebnstage D E B b' yb /\ autnstage D E B autB b' cd
                   ==> !pp. pp IN D /\ E pp cd
                        ==> !x vv. x IN D /\ vv IN D /\ eopair D E x vv pp
                                   ==> E x yb ==> E vv yb) /\
      (!b'. b' IN D /\ E b' d
            ==> !yb cd' cd.
                   yb IN D /\ cd' IN D /\ cd IN D /\
                   ebnstage D E B b' yb /\
                   autnstage D E B autB' b' cd' /\
                   autnstage D E B autB b' cd
                   ==> !x. x IN D /\ E x yb
                        ==> !pp. pp IN D /\ E pp cd
                             ==> !pp'. pp' IN D /\ E pp' cd'
                                  ==> !vv w.
                                         vv IN D /\ w IN D /\
                                         eopair D E x vv pp /\
                                         eopair D E vv w pp'
                                         ==> w = x)
      ==> !yd cd' cd.
             yd IN D /\ cd' IN D /\ cd IN D /\
             ebnstage D E B d yd /\ autnstage D E B autB' d cd' /\
             autnstage D E B autB d cd
             ==> !x. x IN D /\ E x yd
                  ==> !pp. pp IN D /\ E pp cd
                       ==> !pp'. pp' IN D /\ E pp' cd'
                            ==> !vv w.
                                   vv IN D /\ w IN D /\
                                   eopair D E x vv pp /\
                                   eopair D E vv w pp'
                                   ==> w = x`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
   (CONJUNCTS_THEN2 (LABEL_TAC "BD")
    (CONJUNCTS_THEN2 (LABEL_TAC "aBD")
     (CONJUNCTS_THEN2 (LABEL_TAC "aB'D")
      (CONJUNCTS_THEN2 (LABEL_TAC "bij")
       (CONJUNCTS_THEN2 (LABEL_TAC "invch")
        (CONJUNCTS_THEN2 (LABEL_TAC "dord")
         (CONJUNCTS_THEN2 (LABEL_TAC "covA")
          (CONJUNCTS_THEN2 (LABEL_TAC "covB")
           (CONJUNCTS_THEN2 (LABEL_TAC "stabA")
            (LABEL_TAC "cih"))))))))))) THEN
  SUBGOAL_THEN
   `(!c. (c:A) IN D /\ (E:A->A->bool) c B
         ==> ?c'. c' IN D /\ E c' B /\ eapply D E autB c c') /\
    (!k k' t. (k:A) IN D /\ k' IN D /\ t IN D /\
              eapply D (E:A->A->bool) autB k t /\ eapply D E autB k' t
              ==> k = k')`
  (CONJUNCTS_THEN2 (LABEL_TAC "atot") (LABEL_TAC "ainj")) THENL
   [USE_THEN "bij" (STRIP_ASSUME_TAC o GEN_REWRITE_RULE I [ebij]) THEN
    CONJ_TAC THENL [ASM_MESON_TAC[]; ASM_MESON_TAC[]];
    ALL_TAC] THEN
  MAP_EVERY X_GEN_TAC [`yd:A`;`cd':A`;`cd:A`] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "ydD")
    (CONJUNCTS_THEN2 (LABEL_TAC "cd'D")
      (CONJUNCTS_THEN2 (LABEL_TAC "cdD")
        (CONJUNCTS_THEN2 (LABEL_TAC "bstg")
          (CONJUNCTS_THEN2 (LABEL_TAC "astg'") (LABEL_TAC "astg")))))) THEN
  X_GEN_TAC `x:A` THEN STRIP_TAC THEN
  X_GEN_TAC `pp:A` THEN STRIP_TAC THEN
  X_GEN_TAC `pp':A` THEN STRIP_TAC THEN
  MAP_EVERY X_GEN_TAC [`vv:A`;`w:A`] THEN STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`d:A`;`yd:A`]
    EBNSTAGE_CHAR) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `wb:A` (CONJUNCTS_THEN2 (LABEL_TAC "wbD")
    (CONJUNCTS_THEN2 (LABEL_TAC "wbc") (LABEL_TAC "bnfb")))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`d:A`;`cd:A`]
        EAUTNSTAGE_CHAR) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `gacc:A` (X_CHOOSE_THEN `wa:A`
   (X_CHOOSE_THEN `stg:A`
    (CONJUNCTS_THEN2 (LABEL_TAC "gaccD") (CONJUNCTS_THEN2 (LABEL_TAC "waD")
     (CONJUNCTS_THEN2 (LABEL_TAC "stgD") (CONJUNCTS_THEN2 (LABEL_TAC "gaccch")
      (CONJUNCTS_THEN2 (LABEL_TAC "domn") (CONJUNCTS_THEN2 (LABEL_TAC "bnfa")
       (LABEL_TAC "cdch")))))))))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB':A`;`d:A`;`cd':A`]
        EAUTNSTAGE_CHAR) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `gacc':A` (X_CHOOSE_THEN `wa':A`
   (X_CHOOSE_THEN `stg':A`
    (CONJUNCTS_THEN2 (LABEL_TAC "gacc'D") (CONJUNCTS_THEN2 (LABEL_TAC "wa'D")
     (CONJUNCTS_THEN2 (LABEL_TAC "stg'D")
      (CONJUNCTS_THEN2 (LABEL_TAC "gaccch'")
       (CONJUNCTS_THEN2 (LABEL_TAC "domn'")
        (CONJUNCTS_THEN2 (LABEL_TAC "bnfa'")
         (LABEL_TAC "cdch'")))))))))) THEN
  SUBGOAL_THEN `eisfun D (E:A->A->bool) gacc'` (LABEL_TAC "fng'") THENL
   [MATCH_MP_TAC EAUTN_GACC_ISFUN THEN
    MAP_EVERY EXISTS_TAC [`B:A`;`autB':A`;`d:A`] THEN ASM_REWRITE_TAC[] THEN
    MAP_EVERY X_GEN_TAC [`c1:A`;`c2:A`;`z1:A`;`z2:A`] THEN STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB':A`;`c2:A`;`c1:A`;
                  `z1:A`;`z2:A`] EAUTN_COHERE) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[EORDINAL_MEMBER];
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  (* the pair <x,vv> in cd and <vv,w> in cd' *)
  USE_THEN "cdch" (MP_TAC o C MATCH_MP (ASSUME `(pp:A) IN D`)) THEN
  REWRITE_TAC[ASSUME `(E:A->A->bool) pp cd`] THEN
  DISCH_THEN(X_CHOOSE_THEN `x2:A` (X_CHOOSE_THEN `img:A`
    (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 (LABEL_TAC "xstg") (CONJUNCTS_THEN2 ASSUME_TAC
        (LABEL_TAC "imgch"))))))) THEN
  SUBGOAL_THEN `x2:A = x /\ img:A = vv`
    (CONJUNCTS_THEN2 SUBST_ALL_TAC SUBST_ALL_TAC) THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`x2:A`;`img:A`;`x:A`;`vv:A`;
                  `pp:A`] EOPAIR_INJ) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  USE_THEN "cdch'" (MP_TAC o C MATCH_MP (ASSUME `(pp':A) IN D`)) THEN
  REWRITE_TAC[ASSUME `(E:A->A->bool) pp' cd'`] THEN
  DISCH_THEN(X_CHOOSE_THEN `x3:A` (X_CHOOSE_THEN `img':A`
    (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 (LABEL_TAC "vstg'") (CONJUNCTS_THEN2 ASSUME_TAC
        (LABEL_TAC "imgch'"))))))) THEN
  SUBGOAL_THEN `x3:A = vv /\ img':A = w`
    (CONJUNCTS_THEN2 SUBST_ALL_TAC SUBST_ALL_TAC) THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`x3:A`;`img':A`;`vv:A`;`w:A`;
                  `pp':A`] EOPAIR_INJ) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  (* x decomposes over wb (bn side) and over wa (autn side) *)
  SUBGOAL_THEN `ebnmem D (E:A->A->bool) B wb x` (LABEL_TAC "bnmxb") THENL
   [USE_THEN "bnfb" (MP_TAC o SPEC `x:A` o CONJUNCT2 o
      GEN_REWRITE_RULE I [ebnfuns]) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `eisfun D (E:A->A->bool) x /\
    ?crb. (crb:A) IN D /\ ecross D (E:A->A->bool) wb B crb /\
          esubset D E x crb`
  (CONJUNCTS_THEN2 (LABEL_TAC "fnxb") STRIP_ASSUME_TAC) THENL
   [USE_THEN "bnmxb" (MP_TAC o GEN_REWRITE_RULE I [ebnmem]) THEN
    DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `ebnmem D (E:A->A->bool) B wa x` (LABEL_TAC "bnmxa") THENL
   [USE_THEN "bnfa" (MP_TAC o SPEC `x:A` o CONJUNCT2 o
      GEN_REWRITE_RULE I [ebnfuns]) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `?cra. (cra:A) IN D /\ ecross D (E:A->A->bool) wa B cra /\
          esubset D E x cra`
  STRIP_ASSUME_TAC THENL
   [USE_THEN "bnmxa" (MP_TAC o GEN_REWRITE_RULE I [ebnmem]) THEN
    DISCH_THEN(ACCEPT_TAC o CONJUNCT2);
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!t. (t:A) IN D /\ (E:A->A->bool) t wa
        ==> ?t'. t' IN D /\ eapply D E gacc t t'`
  (LABEL_TAC "gapp") THENL
   [X_GEN_TAC `t:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `eindom D (E:A->A->bool) gacc t` MP_TAC THENL
     [USE_THEN "domn" (MP_TAC o CONJUNCT2 o REWRITE_RULE[edomain]) THEN
      DISCH_THEN(MP_TAC o SPEC `t:A`) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[eindom] THEN DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  (* key: gacc' sends the gacc-value of a wb-member back to it *)
  SUBGOAL_THEN
   `!t t'. (t:A) IN D /\ (t':A) IN D /\ (E:A->A->bool) t wb /\
           eapply D E gacc t t'
           ==> eapply D E gacc' t' t`
  (LABEL_TAC "key") THENL
   [MAP_EVERY X_GEN_TAC [`t:A`;`t':A`] THEN STRIP_TAC THEN
    USE_THEN "wbc" (MP_TAC o SPEC `t:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(EQ_MP th
      (ASSUME `(E:A->A->bool) t wb`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `zb:A`
      (fun t -> MAP_EVERY ASSUME_TAC (CONJUNCTS t)))) THEN
    SUBGOAL_THEN `eordinal D (E:A->A->bool) b` ASSUME_TAC THENL
     [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
    SUBGOAL_THEN `eautn D (E:A->A->bool) B autB t t'` ASSUME_TAC THENL
     [UNDISCH_TAC `eapply D (E:A->A->bool) gacc t t'` THEN
      REWRITE_TAC[eapply] THEN
      DISCH_THEN(X_CHOOSE_THEN `pt:A` STRIP_ASSUME_TAC) THEN
      SUBGOAL_THEN `(pt:A) IN D` ASSUME_TAC THENL
       [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
      USE_THEN "gaccch" (MP_TAC o C MATCH_MP (ASSUME `(pt:A) IN D`)) THEN
      REWRITE_TAC[ASSUME `(E:A->A->bool) pt gacc`] THEN
      DISCH_THEN(X_CHOOSE_THEN `b2:A` (X_CHOOSE_THEN `z2:A`
        STRIP_ASSUME_TAC)) THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`b2:A`;
                    `z2:A`;`t:A`;`t':A`;`pt:A`] AUTN_STAGE) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[EORDINAL_MEMBER];
        DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`b:A`]
      AUTNSTAGE_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `cdb:A` (CONJUNCTS_THEN2 (LABEL_TAC "cdbD")
      (LABEL_TAC "astgb"))) THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB':A`;`b:A`]
      AUTNSTAGE_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `cdb':A` (CONJUNCTS_THEN2 (LABEL_TAC "cdb'D")
      (LABEL_TAC "astgb'"))) THEN
    USE_THEN "covA" (MP_TAC o SPEC `b:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPECL [`zb:A`;`cdb:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPEC `t:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `i1:A` (CONJUNCTS_THEN2 (LABEL_TAC "i1D")
      (X_CHOOSE_THEN `q1:A`
        (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th))))) THEN
    SUBGOAL_THEN `eautn D (E:A->A->bool) B autB t i1` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`b:A`;
                    `cdb:A`;`t:A`;`i1:A`;`q1:A`] AUTN_STAGE) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `i1:A = t'` SUBST_ALL_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`t:A`;
                    `i1:A`;`t':A`] AUTN_SV) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) t' zb` ASSUME_TAC THENL
     [USE_THEN "stabA" (MP_TAC o SPEC `b:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(MP_TAC o SPECL [`zb:A`;`cdb:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(MP_TAC o SPEC `q1:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(MP_TAC o SPECL [`t:A`;`t':A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(MP_TAC o C MP (ASSUME `(E:A->A->bool) t zb`)) THEN
      DISCH_THEN ACCEPT_TAC;
      ALL_TAC] THEN
    USE_THEN "covB" (MP_TAC o SPEC `b:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPECL [`zb:A`;`cdb':A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPEC `t':A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `i2:A` (CONJUNCTS_THEN2 (LABEL_TAC "i2D")
      (X_CHOOSE_THEN `q2:A`
        (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th))))) THEN
    SUBGOAL_THEN `i2:A = t` SUBST_ALL_TAC THENL
     [USE_THEN "cih" (MP_TAC o SPEC `b:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(MP_TAC o SPECL [`zb:A`;`cdb':A`;`cdb:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(MP_TAC o SPEC `t:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(MP_TAC o SPEC `q1:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(MP_TAC o SPEC `q2:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(MP_TAC o SPECL [`t':A`;`i2:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    REWRITE_TAC[eapply] THEN EXISTS_TAC `q2:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "gaccch'" (MP_TAC o C MATCH_MP
      (ASSUME `(q2:A) IN D`)) THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MAP_EVERY EXISTS_TAC [`b:A`;`cdb':A`] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* w = x by extensionality *)
  FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
  ASM_REWRITE_TAC[] THEN X_GEN_TAC `m:A` THEN DISCH_TAC THEN
  EQ_TAC THEN DISCH_TAC THENL
   [(* m IN w ==> m IN x *)
    USE_THEN "imgch'" (MP_TAC o C MATCH_MP (ASSUME `(m:A) IN D`)) THEN
    REWRITE_TAC[ASSUME `(E:A->A->bool) m w`] THEN
    DISCH_THEN(X_CHOOSE_THEN `q0:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC MP_TAC))) THEN
    REWRITE_TAC[aprrel] THEN
    DISCH_THEN(X_CHOOSE_THEN `al:A` (X_CHOOSE_THEN `be:A`
      (X_CHOOSE_THEN `al':A` (X_CHOOSE_THEN `be':A`
        STRIP_ASSUME_TAC)))) THEN
    USE_THEN "imgch" (MP_TAC o C MATCH_MP (ASSUME `(q0:A) IN D`)) THEN
    REWRITE_TAC[ASSUME `(E:A->A->bool) q0 vv`] THEN
    DISCH_THEN(X_CHOOSE_THEN `m0:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC MP_TAC))) THEN
    REWRITE_TAC[aprrel] THEN
    DISCH_THEN(X_CHOOSE_THEN `t:A` (X_CHOOSE_THEN `c:A`
      (X_CHOOSE_THEN `t'':A` (X_CHOOSE_THEN `c'':A`
        STRIP_ASSUME_TAC)))) THEN
    SUBGOAL_THEN `al:A = t'' /\ be:A = c''`
      (CONJUNCTS_THEN2 SUBST_ALL_TAC SUBST_ALL_TAC) THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`al:A`;`be:A`;`t'':A`;
                    `c'':A`;`q0:A`] EOPAIR_INJ) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) m0 crb` ASSUME_TAC THENL
     [UNDISCH_TAC `esubset D (E:A->A->bool) x crb` THEN
      REWRITE_TAC[esubset] THEN
      DISCH_THEN(MP_TAC o SPEC `m0:A`) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`wb:A`;`B:A`;`crb:A`;`m0:A`]
      ECROSS_MEMBER) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(EQ_MP th
      (ASSUME `(E:A->A->bool) m0 crb`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `tb:A` (X_CHOOSE_THEN `cb:A`
      STRIP_ASSUME_TAC)) THEN
    SUBGOAL_THEN `tb:A = t /\ cb:A = c`
      (CONJUNCTS_THEN2 SUBST_ALL_TAC SUBST_ALL_TAC) THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`tb:A`;`cb:A`;`t:A`;`c:A`;
                    `m0:A`] EOPAIR_INJ) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `eapply D (E:A->A->bool) gacc' t'' t` ASSUME_TAC THENL
     [USE_THEN "key" (MP_TAC o SPECL [`t:A`;`t'':A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `al':A = t` SUBST_ALL_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`gacc':A`;`t'':A`;`al':A`;
                    `t:A`] EAPPLY_UNIQUE) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `be':A = c` SUBST_ALL_TAC THENL
     [SUBGOAL_THEN `eapply D (E:A->A->bool) autB be' c''` ASSUME_TAC THENL
       [USE_THEN "invch" (MP_TAC o SPECL [`be':A`;`c'':A`]) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
        FIRST_ASSUM ACCEPT_TAC;
        ALL_TAC] THEN
      USE_THEN "ainj" (MP_TAC o SPECL [`be':A`;`c:A`;`c'':A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `m:A = m0` SUBST_ALL_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`t:A`;`c:A`;`m:A`;`m0:A`]
        EOPAIR_UNIQUE) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    FIRST_ASSUM ACCEPT_TAC;
    (* m IN x ==> m IN w *)
    SUBGOAL_THEN `(E:A->A->bool) m crb` ASSUME_TAC THENL
     [UNDISCH_TAC `esubset D (E:A->A->bool) x crb` THEN
      REWRITE_TAC[esubset] THEN
      DISCH_THEN(MP_TAC o SPEC `m:A`) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`wb:A`;`B:A`;`crb:A`;`m:A`]
      ECROSS_MEMBER) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(EQ_MP th
      (ASSUME `(E:A->A->bool) m crb`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `t:A` (X_CHOOSE_THEN `c:A`
      STRIP_ASSUME_TAC)) THEN
    SUBGOAL_THEN `(E:A->A->bool) m cra` ASSUME_TAC THENL
     [UNDISCH_TAC `esubset D (E:A->A->bool) x cra` THEN
      REWRITE_TAC[esubset] THEN
      DISCH_THEN(MP_TAC o SPEC `m:A`) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`wa:A`;`B:A`;`cra:A`;`m:A`]
      ECROSS_MEMBER) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(EQ_MP th
      (ASSUME `(E:A->A->bool) m cra`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `ta:A` (X_CHOOSE_THEN `ca:A`
      STRIP_ASSUME_TAC)) THEN
    SUBGOAL_THEN `ta:A = t /\ ca:A = c`
      (CONJUNCTS_THEN2 SUBST_ALL_TAC SUBST_ALL_TAC) THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`ta:A`;`ca:A`;`t:A`;`c:A`;
                    `m:A`] EOPAIR_INJ) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    USE_THEN "gapp" (MP_TAC o SPEC `t:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `t':A` STRIP_ASSUME_TAC) THEN
    USE_THEN "atot" (MP_TAC o SPEC `c:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `c':A` STRIP_ASSUME_TAC) THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`t':A`;`c':A`]
      EOPAIR_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_TAC `q:A`) THEN
    SUBGOAL_THEN `(q:A) IN D` ASSUME_TAC THENL
     [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) q vv` ASSUME_TAC THENL
     [USE_THEN "imgch" (MP_TAC o C MATCH_MP (ASSUME `(q:A) IN D`)) THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      EXISTS_TAC `m:A` THEN ASM_REWRITE_TAC[] THEN
      REWRITE_TAC[aprrel] THEN
      MAP_EVERY EXISTS_TAC [`t:A`;`c:A`;`t':A`;`c':A`] THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    USE_THEN "imgch'" (MP_TAC o C MATCH_MP (ASSUME `(m:A) IN D`)) THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EXISTS_TAC `q:A` THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[aprrel] THEN
    MAP_EVERY EXISTS_TAC [`t':A`;`c':A`;`t:A`;`c:A`] THEN
    ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [USE_THEN "key" (MP_TAC o SPECL [`t:A`;`t':A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      USE_THEN "invch" (MP_TAC o SPECL [`c:A`;`c':A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      FIRST_ASSUM ACCEPT_TAC]]);;

(* ===================================================================== *)
(* step 8j-3 : AUTN_COMPOSE (autN' o autN = id on B-names, for autB'      *)
(*   the inverse characterisation of autB).  The proof runs FOUR          *)
(*   least-counterexample inductions over shared resolvent graphs:        *)
(*   coverage of both towers,                                             *)
(*   stability of the autB tower, and the composition invariant itself    *)
(*   (COMP_STEP consumes the first three below the critical index).       *)
(* ===================================================================== *)

let AUTN_COMPOSE = prove
 (`!D (E:A->A->bool) B autB autB' x v w.
     model D E ZF_AX /\ B IN D /\ autB IN D /\ autB' IN D /\
     ebij D E autB B B /\
     (!k t. k IN D /\ t IN D
            ==> (eapply D E autB' t k <=> eapply D E autB k t)) /\
     bname D E B x /\
     eautn D E B autB x v /\ eautn D E B autB' v w
     ==> w = x`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
   (CONJUNCTS_THEN2 (LABEL_TAC "BD")
    (CONJUNCTS_THEN2 (LABEL_TAC "aBD")
     (CONJUNCTS_THEN2 (LABEL_TAC "aB'D")
      (CONJUNCTS_THEN2 (LABEL_TAC "bij")
       (CONJUNCTS_THEN2 (LABEL_TAC "invch")
        (CONJUNCTS_THEN2 (LABEL_TAC "bn")
         (CONJUNCTS_THEN2 (LABEL_TAC "autx") (LABEL_TAC "autv"))))))))) THEN
  SUBGOAL_THEN `(x:A) IN D /\ (v:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[AUTN_IMP]; ALL_TAC] THEN
  SUBGOAL_THEN `(w:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[AUTN_IMP]; ALL_TAC] THEN
  USE_THEN "bn" (MP_TAC o REWRITE_RULE[bname]) THEN
  DISCH_THEN(X_CHOOSE_THEN `a:A` (X_CHOOSE_THEN `ya:A`
    (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th)))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`a:A`] ESUC_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `sa:A`) THEN
  SUBGOAL_THEN `(sa:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) sa` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_ESUC]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) a sa` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_MEMBER]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`sa:A`]
    EBNSTAGE_RESGRAPH) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `rbn:A` (CONJUNCTS_THEN2 (LABEL_TAC "rbnD")
    (LABEL_TAC "rbnc"))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB':A`;`sa:A`]
    EAUTNSTAGE_RESGRAPH) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `rg:A` (CONJUNCTS_THEN2 (LABEL_TAC "rgD")
    (LABEL_TAC "rgc"))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`sa:A`]
    EAUTNSTAGE_RESGRAPH) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `rc:A` (CONJUNCTS_THEN2 (LABEL_TAC "rcD")
    (LABEL_TAC "rcc"))) THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v0:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  SUBGOAL_THEN
   `valuation D ((80 |-> (rbn:A)) ((81 |-> (rc:A)) v0)) /\
    valuation D ((80 |-> (rbn:A)) ((81 |-> (rg:A)) v0)) /\
    valuation D ((79 |-> (rbn:A)) ((80 |-> (rg:A)) ((81 |-> (rc:A)) v0)))`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  (* coverage of the autB tower below sa *)
  SUBGOAL_THEN
   `!dd. dd IN D /\ E dd sa
         ==> holds D E ((0 |-> dd) ((80 |-> (rbn:A)) ((81 |-> (rc:A)) v0)))
                       cover_form`
  (LABEL_TAC "covA") THENL
   [GEN_TAC THEN STRIP_TAC THEN
    MATCH_MP_TAC(TAUT `(~p ==> F) ==> p`) THEN
    DISCH_THEN(LABEL_TAC "bad0") THEN
    SUBGOAL_THEN `eordinal D (E:A->A->bool) dd` ASSUME_TAC THENL
     [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`Not cover_form`;
                  `(80 |-> (rbn:A)) ((81 |-> (rc:A)) v0)`;`dd:A`]
      EORDINAL_LEAST) THEN
    ASM_REWRITE_TAC[HOLDS_NOT] THEN
    DISCH_THEN(X_CHOOSE_THEN `d:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 (LABEL_TAC "dbad")
        (LABEL_TAC "dmin"))))) THEN
    SUBGOAL_THEN `(d:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) d sa` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`d:A`;`dd:A`]
        EORDINAL_TRICHOTOMY) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN ASSUME_TAC) THENL
       [ASM_MESON_TAC[EORDINAL_TRANS_E];
        ASM_MESON_TAC[];
        USE_THEN "dmin" (MP_TAC o SPEC `dd:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        USE_THEN "bad0" (fun th -> REWRITE_TAC[th])];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `!b'. b' IN D /\ (E:A->A->bool) b' d
           ==> !yb cd.
                  yb IN D /\ cd IN D /\
                  ebnstage D E B b' yb /\ autnstage D E B autB b' cd
                  ==> !u. u IN D /\ E u yb
                          ==> ?img. img IN D /\ ?pp. pp IN D /\
                                    eopair D E u img pp /\ E pp cd`
    ASSUME_TAC THENL
     [X_GEN_TAC `b':A` THEN STRIP_TAC THEN
      SUBGOAL_THEN `(E:A->A->bool) b' sa` ASSUME_TAC THENL
       [ASM_MESON_TAC[EORDINAL_TRANS_E]; ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`sa:A`;
                    `rbn:A`;`rc:A`;`v0:num->A`;`b':A`] AUTNCOVER_SEM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(MP_TAC o fst o EQ_IMP_RULE) THEN
      ANTS_TAC THENL
       [USE_THEN "dmin" (MP_TAC o SPEC `b':A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
        DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `holds D E ((0 |-> (d:A)) ((80 |-> (rbn:A)) ((81 |-> (rc:A)) v0)))
                cover_form`
    MP_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`sa:A`;
                    `rbn:A`;`rc:A`;`v0:num->A`;`d:A`] AUTNCOVER_SEM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`d:A`]
        AUTNCOVER_STEP) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      USE_THEN "dbad" (fun th -> REWRITE_TAC[th])];
    ALL_TAC] THEN
  (* coverage of the autB' tower below sa *)
  SUBGOAL_THEN
   `!dd. dd IN D /\ E dd sa
         ==> holds D E ((0 |-> dd) ((80 |-> (rbn:A)) ((81 |-> (rg:A)) v0)))
                       cover_form`
  (LABEL_TAC "covB") THENL
   [GEN_TAC THEN STRIP_TAC THEN
    MATCH_MP_TAC(TAUT `(~p ==> F) ==> p`) THEN
    DISCH_THEN(LABEL_TAC "bad0") THEN
    SUBGOAL_THEN `eordinal D (E:A->A->bool) dd` ASSUME_TAC THENL
     [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`Not cover_form`;
                  `(80 |-> (rbn:A)) ((81 |-> (rg:A)) v0)`;`dd:A`]
      EORDINAL_LEAST) THEN
    ASM_REWRITE_TAC[HOLDS_NOT] THEN
    DISCH_THEN(X_CHOOSE_THEN `d:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 (LABEL_TAC "dbad")
        (LABEL_TAC "dmin"))))) THEN
    SUBGOAL_THEN `(d:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) d sa` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`d:A`;`dd:A`]
        EORDINAL_TRICHOTOMY) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN ASSUME_TAC) THENL
       [ASM_MESON_TAC[EORDINAL_TRANS_E];
        ASM_MESON_TAC[];
        USE_THEN "dmin" (MP_TAC o SPEC `dd:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        USE_THEN "bad0" (fun th -> REWRITE_TAC[th])];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `!b'. b' IN D /\ (E:A->A->bool) b' d
           ==> !yb cd.
                  yb IN D /\ cd IN D /\
                  ebnstage D E B b' yb /\ autnstage D E B autB' b' cd
                  ==> !u. u IN D /\ E u yb
                          ==> ?img. img IN D /\ ?pp. pp IN D /\
                                    eopair D E u img pp /\ E pp cd`
    ASSUME_TAC THENL
     [X_GEN_TAC `b':A` THEN STRIP_TAC THEN
      SUBGOAL_THEN `(E:A->A->bool) b' sa` ASSUME_TAC THENL
       [ASM_MESON_TAC[EORDINAL_TRANS_E]; ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB':A`;`sa:A`;
                    `rbn:A`;`rg:A`;`v0:num->A`;`b':A`] AUTNCOVER_SEM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(MP_TAC o fst o EQ_IMP_RULE) THEN
      ANTS_TAC THENL
       [USE_THEN "dmin" (MP_TAC o SPEC `b':A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
        DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `holds D E ((0 |-> (d:A)) ((80 |-> (rbn:A)) ((81 |-> (rg:A)) v0)))
                cover_form`
    MP_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB':A`;`sa:A`;
                    `rbn:A`;`rg:A`;`v0:num->A`;`d:A`] AUTNCOVER_SEM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB':A`;`d:A`]
        AUTNCOVER_STEP) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      USE_THEN "dbad" (fun th -> REWRITE_TAC[th])];
    ALL_TAC] THEN
  (* stability of the autB tower below sa *)
  SUBGOAL_THEN
   `!dd. dd IN D /\ E dd sa
         ==> holds D E ((0 |-> dd) ((80 |-> (rbn:A)) ((81 |-> (rc:A)) v0)))
                       stab_form`
  (LABEL_TAC "stbA") THENL
   [GEN_TAC THEN STRIP_TAC THEN
    MATCH_MP_TAC(TAUT `(~p ==> F) ==> p`) THEN
    DISCH_THEN(LABEL_TAC "bad0") THEN
    SUBGOAL_THEN `eordinal D (E:A->A->bool) dd` ASSUME_TAC THENL
     [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
