(* ===================================================================== *)
(* step 10a : the TABLE pushforward relation (two-level pair relabel).    *)
(*   tabrel G autB m q : m = <<u,t>,z> |--> q = <<G u, G t>, autB z>.     *)
(*   Mirrors aprrel/rlb_form/HOLDS_RLB/AUTNIMG_EXISTS one pair-level up:  *)
(*   slots m=11, q=10, G=4, autB=3, source set at 8; witnesses            *)
(*   u=20,t=21,z=22,p=26,u'=50,t'=60,z'=70,p'=80 (binders 27,28 /          *)
(*   51-53 / 61-63 / 71-73 / 81,82 all clear).  TABIMG_EXISTS gives the    *)
(*   image set of any table under (G,autB) -- the sIN'/sEQ' pushforwards.  *)
(* ===================================================================== *)

let tabrel = new_definition
 `tabrel D (E:A->A->bool) G autB m q <=>
    ?u t z p u' t' z' p'.
       u IN D /\ t IN D /\ z IN D /\ p IN D /\
       u' IN D /\ t' IN D /\ z' IN D /\ p' IN D /\
       eopair D E u t p /\ eopair D E p z m /\
       eapply D E G u u' /\ eapply D E G t t' /\ eapply D E autB z z' /\
       eopair D E u' t' p' /\ eopair D E p' z' q`;;

let tabrel_form = new_definition
  `tabrel_form =
     ?? 20 (?? 21 (?? 22 (?? 26 (?? 50 (?? 60 (?? 70 (?? 80
       (opair_form 20 21 26 && opair_form 26 22 11 &&
        apply_form 4 20 50 && apply_form 4 21 60 && apply_form 3 22 70 &&
        opair_form 50 60 80 && opair_form 80 70 10))))))))`;;

let TAB_ATOMS = prove
 (`!D (E:A->A->bool) (v:num->A).
     valuation D v
     ==> !a20 a21 a22 a26 a50 a60 a70 a80:A.
           a20 IN D /\ a21 IN D /\ a22 IN D /\ a26 IN D /\
           a50 IN D /\ a60 IN D /\ a70 IN D /\ a80 IN D
           ==> (holds D E ((80 |-> a80) ((70 |-> a70) ((60 |-> a60)
                  ((50 |-> a50) ((26 |-> a26) ((22 |-> a22) ((21 |-> a21)
                  ((20 |-> a20) v)))))))) (opair_form 20 21 26) <=>
                eopair D E a20 a21 a26) /\
               (holds D E ((80 |-> a80) ((70 |-> a70) ((60 |-> a60)
                  ((50 |-> a50) ((26 |-> a26) ((22 |-> a22) ((21 |-> a21)
                  ((20 |-> a20) v)))))))) (opair_form 26 22 11) <=>
                eopair D E a26 a22 (v 11)) /\
               (holds D E ((80 |-> a80) ((70 |-> a70) ((60 |-> a60)
                  ((50 |-> a50) ((26 |-> a26) ((22 |-> a22) ((21 |-> a21)
                  ((20 |-> a20) v)))))))) (apply_form 4 20 50) <=>
                eapply D E (v 4) a20 a50) /\
               (holds D E ((80 |-> a80) ((70 |-> a70) ((60 |-> a60)
                  ((50 |-> a50) ((26 |-> a26) ((22 |-> a22) ((21 |-> a21)
                  ((20 |-> a20) v)))))))) (apply_form 4 21 60) <=>
                eapply D E (v 4) a21 a60) /\
               (holds D E ((80 |-> a80) ((70 |-> a70) ((60 |-> a60)
                  ((50 |-> a50) ((26 |-> a26) ((22 |-> a22) ((21 |-> a21)
                  ((20 |-> a20) v)))))))) (apply_form 3 22 70) <=>
                eapply D E (v 3) a22 a70) /\
               (holds D E ((80 |-> a80) ((70 |-> a70) ((60 |-> a60)
                  ((50 |-> a50) ((26 |-> a26) ((22 |-> a22) ((21 |-> a21)
                  ((20 |-> a20) v)))))))) (opair_form 50 60 80) <=>
                eopair D E a50 a60 a80) /\
               (holds D E ((80 |-> a80) ((70 |-> a70) ((60 |-> a60)
                  ((50 |-> a50) ((26 |-> a26) ((22 |-> a22) ((21 |-> a21)
