     (X_CHOOSE_THEN `a70:A` (CONJUNCTS_THEN2 ASSUME_TAC
     (X_CHOOSE_THEN `a80:A` STRIP_ASSUME_TAC))))))))))))))) THEN
    MAP_EVERY EXISTS_TAC
      [`a20:A`;`a21:A`;`a22:A`;`a26:A`;`a50:A`;`a60:A`;`a70:A`;`a80:A`] THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "atoms" (MP_TAC o SPECL
      [`a20:A`;`a21:A`;`a22:A`;`a26:A`;`a50:A`;`a60:A`;`a70:A`;`a80:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
