        (X_CHOOSE_THEN `t':A` (X_CHOOSE_THEN `z':A` (X_CHOOSE_THEN `p':A`
          STRIP_ASSUME_TAC)))))))) THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`crGG:A`;`u2a:A`;`capS:A`;
                   `q:A`] ECROSS_MEMBER) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
