(* ===================================================================== *)
(* step 10b-0 : stage-level wraps for the ebvatt pushforward.             *)
(*   AUTN_COVER_AT : coverage at EVERY index (the cover good-block, once, *)
(*     as a clean theorem).                                               *)
(*   AUTN_STAGE_SURJ : autN maps each bn-stage ONTO itself (inverse       *)
(*     tower + stage preservation + composition).                         *)
(*   AUTN_APPLY : function-application transport along                    *)
(*     autN (members of autN(x) are the relabelled members of x).         *)
(* ===================================================================== *)

let AUTN_COVER_AT = prove
 (`!D (E:A->A->bool) B autB a ya cd.
     model D E ZF_AX /\ B IN D /\ autB IN D /\ eordinal D E a /\
     ya IN D /\ cd IN D /\ ebnstage D E B a ya /\
     autnstage D E B autB a cd
     ==> !u. u IN D /\ E u ya
             ==> ?img pp. img IN D /\ pp IN D /\
                          eopair D E u img pp /\ E pp cd`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(a:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`a:A`] ESUC_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `sa:A`) THEN
  SUBGOAL_THEN `(sa:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) sa` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_ESUC]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) a sa` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_MEMBER]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`sa:A`]
    EBNSTAGE_RESGRAPH) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `rL:A` (CONJUNCTS_THEN2 (LABEL_TAC "rLD")
    (LABEL_TAC "rLc"))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`sa:A`]
    EAUTNSTAGE_RESGRAPH) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `rc:A` (CONJUNCTS_THEN2 (LABEL_TAC "rcD")
    (LABEL_TAC "rcc"))) THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v0:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  SUBGOAL_THEN `valuation D ((80 |-> (rL:A)) ((81 |-> (rc:A)) v0))`
  ASSUME_TAC THENL [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
      (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC)); ALL_TAC] THEN
  SUBGOAL_THEN
   `!dd. dd IN D /\ E dd sa
         ==> holds D E ((0 |-> dd) ((80 |-> (rL:A)) ((81 |-> (rc:A)) v0)))
                       cover_form`
  (LABEL_TAC "cov") THENL
   [GEN_TAC THEN STRIP_TAC THEN
    MATCH_MP_TAC(TAUT `(~p ==> F) ==> p`) THEN
    DISCH_THEN(LABEL_TAC "bad0") THEN
    SUBGOAL_THEN `eordinal D (E:A->A->bool) dd` ASSUME_TAC THENL
     [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`Not cover_form`;
                  `(80 |-> (rL:A)) ((81 |-> (rc:A)) v0)`;`dd:A`]
      EORDINAL_LEAST) THEN
    ASM_REWRITE_TAC[HOLDS_NOT] THEN
    DISCH_THEN(X_CHOOSE_THEN `d:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 (LABEL_TAC "dbad")
        (LABEL_TAC "dmin"))))) THEN
    SUBGOAL_THEN `(d:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) d sa` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`d:A`;`dd:A`]
        EORDINAL_TRICHOTOMY) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN ASSUME_TAC) THENL
       [ASM_MESON_TAC[EORDINAL_TRANS_E];
        ASM_MESON_TAC[];
        USE_THEN "dmin" (MP_TAC o SPEC `dd:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        USE_THEN "bad0" (fun th -> REWRITE_TAC[th])];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `!b'. b' IN D /\ (E:A->A->bool) b' d
           ==> !yb cd.
                  yb IN D /\ cd IN D /\
                  ebnstage D E B b' yb /\ autnstage D E B autB b' cd
                  ==> !u. u IN D /\ E u yb
                          ==> ?img. img IN D /\ ?pp. pp IN D /\
                                    eopair D E u img pp /\ E pp cd`
    ASSUME_TAC THENL
     [X_GEN_TAC `b':A` THEN STRIP_TAC THEN
      SUBGOAL_THEN `(E:A->A->bool) b' sa` ASSUME_TAC THENL
       [ASM_MESON_TAC[EORDINAL_TRANS_E]; ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`sa:A`;
                    `rL:A`;`rc:A`;`v0:num->A`;`b':A`] AUTNCOVER_SEM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(MP_TAC o fst o EQ_IMP_RULE) THEN
      ANTS_TAC THENL
       [USE_THEN "dmin" (MP_TAC o SPEC `b':A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
        DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `holds D E ((0 |-> (d:A)) ((80 |-> (rL:A)) ((81 |-> (rc:A)) v0)))
                cover_form`
    MP_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`sa:A`;
                    `rL:A`;`rc:A`;`v0:num->A`;`d:A`] AUTNCOVER_SEM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`d:A`]
        AUTNCOVER_STEP) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      USE_THEN "dbad" (fun th -> REWRITE_TAC[th])];
    ALL_TAC] THEN
  X_GEN_TAC `u:A` THEN STRIP_TAC THEN
  USE_THEN "cov" (MP_TAC o SPEC `a:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`sa:A`;`rL:A`;
                `rc:A`;`v0:num->A`;`a:A`] AUTNCOVER_SEM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o fst o EQ_IMP_RULE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL [`ya:A`;`cd:A`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `u:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `img:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (X_CHOOSE_THEN `pp:A`
      (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th))))) THEN
  MAP_EVERY EXISTS_TAC [`img:A`;`pp:A`] THEN ASM_REWRITE_TAC[]);;

let AUTN_STAGE_SURJ = prove
 (`!D (E:A->A->bool) B autB a ya v.
     model D E ZF_AX /\ B IN D /\ autB IN D /\ ebij D E autB B B /\
     eordinal D E a /\ ya IN D /\ ebnstage D E B a ya /\
     v IN D /\ E v ya
     ==> ?x. x IN D /\ E x ya /\ eautn D E B autB x v`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(a:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B v` ASSUME_TAC THENL
   [MATCH_MP_TAC BNAME_STAGE THEN
    MAP_EVERY EXISTS_TAC [`a:A`;`ya:A`] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`autB:A`;`B:A`;`B:A`]
    EBIJ_INV_CHAR) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `autB':A` (CONJUNCTS_THEN2 (LABEL_TAC "aB'D")
    (CONJUNCTS_THEN2 (LABEL_TAC "bij'") (LABEL_TAC "invch")))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB':A`;`v:A`]
    AUTN_TOTAL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `x:A` (CONJUNCTS_THEN2 (LABEL_TAC "xD")
    (LABEL_TAC "autv"))) THEN
  SUBGOAL_THEN `(E:A->A->bool) x ya` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB':A`;`a:A`;`ya:A`;
                  `v:A`;`x:A`] AUTN_STAGE_PRESERVE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B x` ASSUME_TAC THENL
   [MATCH_MP_TAC BNAME_STAGE THEN
    MAP_EVERY EXISTS_TAC [`a:A`;`ya:A`] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`x:A`]
    AUTN_TOTAL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `v2:A` (CONJUNCTS_THEN2 (LABEL_TAC "v2D")
    (LABEL_TAC "autx2"))) THEN
  SUBGOAL_THEN `v2:A = v` SUBST_ALL_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB':A`;`autB:A`;
                  `v:A`;`x:A`;`v2:A`] AUTN_COMPOSE) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN
      MAP_EVERY X_GEN_TAC [`k:A`;`t:A`] THEN STRIP_TAC THEN
      USE_THEN "invch" (MP_TAC o SPECL [`t:A`;`k:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]);
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  EXISTS_TAC `x:A` THEN ASM_REWRITE_TAC[]);;

(* Function-application transport: autN(x)(autN y) = autB (x(y)).         *)
let AUTN_APPLY = prove
 (`!D (E:A->A->bool) B autB x x' y y' qy qy'.
     model D E ZF_AX /\ B IN D /\ autB IN D /\
     x IN D /\ x' IN D /\ y IN D /\ y' IN D /\ qy IN D /\ qy' IN D /\
     eautn D E B autB x x' /\ eautn D E B autB y y' /\
     eapply D E autB qy qy' /\ eapply D E x y qy
     ==> eapply D E x' y' qy'`,
  REPEAT STRIP_TAC THEN
  UNDISCH_TAC `eapply D (E:A->A->bool) x y qy` THEN
  REWRITE_TAC[eapply] THEN
  DISCH_THEN(X_CHOOSE_THEN `m:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `(m:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`y':A`;`qy':A`] EOPAIR_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `q:A`) THEN
  SUBGOAL_THEN `(q:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
  EXISTS_TAC `q:A` THEN ASM_REWRITE_TAC[] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`x:A`;`x':A`;
                `q:A`] AUTN_MEM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MAP_EVERY EXISTS_TAC [`m:A`;`y:A`;`qy:A`;`y':A`;`qy':A`] THEN
  ASM_REWRITE_TAC[]);;

(* ===================================================================== *)
(* step 10b-1 : the (G,autB)-pushforward of an ebvatt value table is an   *)
(*   ebvatt table on the SAME stage w.  G is an abstract stage-level      *)
(*   graph of the name action: eautn-connected (conn), total into w,      *)
(*   onto w; w's names decompose over w X B (wmem).  Discharged in the    *)
(*   equivariance wrap from the autN stage machinery.                     *)
(* ===================================================================== *)

let AUTTAB_EBVATT = prove
 (`!D (E:A->A->bool) B leq autB w G sIN sEQ sIN' sEQ'.
   model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
   autB IN D /\ ebij D E autB B B /\
   (!x y xi yi. x IN D /\ y IN D /\ xi IN D /\ yi IN D /\
                eapply D E autB x xi /\ eapply D E autB y yi
                ==> (erel D E leq x y <=> erel D E leq xi yi)) /\
   w IN D /\ G IN D /\
   (!x x'. x IN D /\ x' IN D /\ eapply D E G x x'
           ==> eautn D E B autB x x') /\
   (!x. x IN D /\ E x w ==> ?x'. x' IN D /\ E x' w /\ eapply D E G x x') /\
   (!x'. x' IN D /\ E x' w ==> ?x. x IN D /\ E x w /\ eapply D E G x x') /\
   (!x m t c. x IN D /\ E x w /\ m IN D /\ E m x /\ t IN D /\ c IN D /\
              eopair D E t c m
              ==> E t w /\ E c B) /\
   ebvatt D E B leq w sIN sEQ /\
   sIN' IN D /\ sEQ' IN D /\
   (!q. q IN D ==> (E q sIN' <=> ?m. m IN D /\ E m sIN /\
                                      tabrel D E G autB m q)) /\
   (!q. q IN D ==> (E q sEQ' <=> ?m. m IN D /\ E m sEQ /\
                                      tabrel D E G autB m q))
   ==> ebvatt D E B leq w sIN' sEQ'`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
   (CONJUNCTS_THEN2 (LABEL_TAC "cba")
    (CONJUNCTS_THEN2 (LABEL_TAC "BD")
     (CONJUNCTS_THEN2 (LABEL_TAC "leqD")
      (CONJUNCTS_THEN2 (LABEL_TAC "aBD")
       (CONJUNCTS_THEN2 (LABEL_TAC "bij")
        (CONJUNCTS_THEN2 (LABEL_TAC "ord")
         (CONJUNCTS_THEN2 (LABEL_TAC "wD")
          (CONJUNCTS_THEN2 (LABEL_TAC "GD")
           (CONJUNCTS_THEN2 (LABEL_TAC "conn")
            (CONJUNCTS_THEN2 (LABEL_TAC "tot")
             (CONJUNCTS_THEN2 (LABEL_TAC "onto")
              (CONJUNCTS_THEN2 (LABEL_TAC "wmem")
               (CONJUNCTS_THEN2 (LABEL_TAC "att")
                (CONJUNCTS_THEN2 (LABEL_TAC "sIN'D")
                 (CONJUNCTS_THEN2 (LABEL_TAC "sEQ'D")
                  (CONJUNCTS_THEN2 (LABEL_TAC "chIN")
                   (LABEL_TAC "chEQ")))))))))))))))))) THEN
  USE_THEN "att" (MP_TAC o GEN_REWRITE_RULE I [ebvatt]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "fnIN")
    (CONJUNCTS_THEN2 (LABEL_TAC "fnEQ")
      (CONJUNCTS_THEN2 (X_CHOOSE_THEN `c0:A` (CONJUNCTS_THEN2
          (LABEL_TAC "crossc") (CONJUNCTS_THEN2 (LABEL_TAC "domIN")
            (LABEL_TAC "domEQ"))))
        (CONJUNCTS_THEN2 (LABEL_TAC "clIN") (LABEL_TAC "clEQ"))))) THEN
  SUBGOAL_THEN `(c0:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ecross]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` (LABEL_TAC "pord") THENL
   [ASM_MESON_TAC[ecba; EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` (LABEL_TAC "balg") THENL
   [ASM_MESON_TAC[ecba]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!x s s'. (x:A) IN D /\ (s:A) IN D /\ (s':A) IN D /\
             eapply D (E:A->A->bool) G x s /\ eapply D E G x s'
             ==> s = s'`
  (LABEL_TAC "gfun") THENL
   [REPEAT STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`x:A`;`s:A`;
                  `s':A`] AUTN_SV) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN CONJ_TAC THEN
      USE_THEN "conn" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!x y s. (x:A) IN D /\ (y:A) IN D /\ (s:A) IN D /\
            eapply D (E:A->A->bool) G x s /\ eapply D E G y s
            ==> x = y`
  (LABEL_TAC "gcof") THENL
   [REPEAT STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`x:A`;`y:A`;
                  `s:A`] AUTN_INJ) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN CONJ_TAC THEN
      USE_THEN "conn" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(!c. (c:A) IN D /\ (E:A->A->bool) c B
         ==> ?c'. c' IN D /\ E c' B /\ eapply D E autB c c') /\
    (!k k' t. (k:A) IN D /\ k' IN D /\ t IN D /\
              eapply D (E:A->A->bool) autB k t /\ eapply D E autB k' t
              ==> k = k') /\
    (!k t t'. (k:A) IN D /\ t IN D /\ t' IN D /\
              eapply D (E:A->A->bool) autB k t /\ eapply D E autB k t'
              ==> t = t') /\
    (!k t. (k:A) IN D /\ t IN D /\ eapply D (E:A->A->bool) autB k t
           ==> E k B /\ E t B)`
  (CONJUNCTS_THEN2 (LABEL_TAC "atotB") (CONJUNCTS_THEN2 (LABEL_TAC "ainjB")
    (CONJUNCTS_THEN2 (LABEL_TAC "afunB") (LABEL_TAC "arngB")))) THENL
   [USE_THEN "bij" (STRIP_ASSUME_TAC o GEN_REWRITE_RULE I [ebij]) THEN
    REPEAT CONJ_TAC THENL
     [ASM_MESON_TAC[]; ASM_MESON_TAC[]; ASM_MESON_TAC[]; ASM_MESON_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!pr val. (pr:A) IN D /\ (val:A) IN D /\
             eapply D (E:A->A->bool) sIN pr val
             ==> ?u v. u IN D /\ v IN D /\ E u w /\ E v w /\
                       eopair D E u v pr /\ E val B /\
                       ebvin D E B leq sEQ v u val`
  (LABEL_TAC "sINval") THENL
   [MAP_EVERY X_GEN_TAC [`pr:A`;`val:A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) pr c0` ASSUME_TAC THENL
     [USE_THEN "domIN" (MP_TAC o SPEC `pr:A` o CONJUNCT2 o
