      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[eindom] THEN EXISTS_TAC `val:A` THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`w:A`;`c0:A`;`pr:A`]
      ECROSS_MEMBER) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) pr c0`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `u:A` (X_CHOOSE_THEN `v:A`
      STRIP_ASSUME_TAC)) THEN
    USE_THEN "clIN" (MP_TAC o SPECL [`u:A`;`v:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `pr0:A` (X_CHOOSE_THEN `val0:A`
      STRIP_ASSUME_TAC)) THEN
    SUBGOAL_THEN `(pr0:A) IN D` ASSUME_TAC THENL
     [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
    SUBGOAL_THEN `pr0:A = pr` SUBST_ALL_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`u:A`;`v:A`;`pr0:A`;`pr:A`]
        EOPAIR_UNIQUE) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `(val0:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[ebvin; ELUB_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `val0:A = val` SUBST_ALL_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`sIN:A`;`pr:A`;`val0:A`;
                    `val:A`] EAPPLY_UNIQUE) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`u:A`;`v:A`] THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[ebvin; ELUB_IN];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!pr val. (pr:A) IN D /\ (val:A) IN D /\
             eapply D (E:A->A->bool) sEQ pr val
