   [MAP_EVERY X_GEN_TAC [`pr:A`;`val:A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) pr c0` ASSUME_TAC THENL
     [USE_THEN "domEQ" (MP_TAC o SPEC `pr:A` o CONJUNCT2 o
        REWRITE_RULE[edomain]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
