let AUT_EBVEQ = prove
 (`!D (E:A->A->bool) B leq autB u t z u' t' z'.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
     autB IN D /\ ebij D E autB B B /\
     (!x y xi yi. x IN D /\ y IN D /\ xi IN D /\ yi IN D /\
                  eapply D E autB x xi /\ eapply D E autB y yi
                  ==> (erel D E leq x y <=> erel D E leq xi yi)) /\
     u IN D /\ t IN D /\ z IN D /\ u' IN D /\ t' IN D /\ z' IN D /\
     eautn D E B autB u u' /\ eautn D E B autB t t' /\
     ebv_eq D E B leq u t z /\ eapply D E autB z z'
     ==> ebv_eq D E B leq u' t' z'`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
   (CONJUNCTS_THEN2 (LABEL_TAC "cba")
    (CONJUNCTS_THEN2 (LABEL_TAC "BD")
     (CONJUNCTS_THEN2 (LABEL_TAC "leqD")
      (CONJUNCTS_THEN2 (LABEL_TAC "aBD")
       (CONJUNCTS_THEN2 (LABEL_TAC "bij")
        (CONJUNCTS_THEN2 (LABEL_TAC "ord")
         (CONJUNCTS_THEN2 (LABEL_TAC "uD")
          (CONJUNCTS_THEN2 (LABEL_TAC "tD")
           (CONJUNCTS_THEN2 (LABEL_TAC "zD")
            (CONJUNCTS_THEN2 (LABEL_TAC "u'D")
             (CONJUNCTS_THEN2 (LABEL_TAC "t'D")
              (CONJUNCTS_THEN2 (LABEL_TAC "z'D")
               (CONJUNCTS_THEN2 (LABEL_TAC "autu")
                (CONJUNCTS_THEN2 (LABEL_TAC "autt")
                 (CONJUNCTS_THEN2 (LABEL_TAC "bv")
                  (LABEL_TAC "az"))))))))))))))))) THEN
  USE_THEN "bv" (MP_TAC o GEN_REWRITE_RULE I [ebv_eq]) THEN
  DISCH_THEN(X_CHOOSE_THEN `a:A` (X_CHOOSE_THEN `w:A`
    (X_CHOOSE_THEN `sIN:A` (X_CHOOSE_THEN `sEQ:A`
