(* ===================================================================== *)
(* S3-1 : internal permutations of om and the pointwise-fixing predicate. *)
(*   eperm om s = s is an internal bijection om -> om;                    *)
(*   efixes s e = s is the identity on the members of e.                  *)
(*   The normal filter F = { fix_e : e finite } stays VIRTUAL: every use  *)
(*   is "?e. efin e /\ esubset e om /\ !s. eperm s /\ efixes s e ==> ...".*)
(* ===================================================================== *)

let eperm = new_definition
 `eperm D (E:A->A->bool) om s <=> ebij D E s om om`;;

let efixes = new_definition
 `efixes D (E:A->A->bool) s e <=>
    !n. n IN D /\ E n e ==> eapply D E s n n`;;

let EPERM_IN = prove
 (`!D (E:A->A->bool) om s. eperm D E om s ==> s IN D`,
  REWRITE_TAC[eperm; ebij] THEN MESON_TAC[]);;

let EFIXES_SUBSET = prove
 (`!D (E:A->A->bool) s e e'.
     efixes D E s e /\ esubset D E e' e ==> efixes D E s e'`,
  REWRITE_TAC[efixes; esubset] THEN MESON_TAC[]);;

(* ===================================================================== *)
(* S3-3 : high-slot recursion application binding slots 4,5 (leaves the   *)
(* B/autB parameter slots 2,3 untouched) + the bridge to the autN tower.  *)
(* Mirror of recapp3_form/HOLDS_RECAPP3_FORM/HOLDS_RECAPP3_BNSTEP.        *)
(* ===================================================================== *)

let recapp45_form = new_definition
  `recapp45_form q i j = !! 4 (!! 5 ((Eq 4 i && Eq 5 j) --> q))`;;

let HOLDS_RECAPP45_FORM = prove
 (`!D (E:A->A->bool) v q i j.
        valuation D v /\ ~(i = 4) /\ ~(i = 5) /\ ~(j = 4) /\
        ~(j = 5)
        ==> (holds D E v (recapp45_form q i j) <=>
             holds D E ((5 |-> v j) ((4 |-> v i) v)) q)`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[recapp45_form; holds; HOLDS_AND] THEN
  ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE `~(4 = 5)`] THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  EQ_TAC THENL
   [DISCH_THEN(MP_TAC o SPEC `(v:num->A) i`) THEN ASM_SIMP_TAC[] THEN
    DISCH_THEN(MP_TAC o SPEC `(v:num->A) j`) THEN ASM_SIMP_TAC[];
    MESON_TAC[]]);;

let HOLDS_RECAPP45_AUTNSTEP = prove
 (`!D (E:A->A->bool) v i j.
        model D E ZF_AX /\ valuation D v /\
        ~(i = 4) /\ ~(i = 5) /\ ~(j = 4) /\ ~(j = 5)
        ==> (holds D E v (recapp45_form (rec_form autn_step_form 4) i j) <=>
             autnstage D E (v 2) (v 3) (v i) (v j))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`;
                `rec_form autn_step_form 4`; `i:num`; `j:num`]
        HOLDS_RECAPP45_FORM) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`;
                `autn_step_form`; `4`; `(v:num->A) i`; `(v:num->A) j`]
        HOLDS_REC_FORM) THEN
  ASM_REWRITE_TAC[FVLT_AUTN_STEP_FORM; ARITH_RULE `1 < 4`;
                  ARITH_RULE `4 + 1 = 5`] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(v:num->A) 2`;
                `(v:num->A) 3`; `(v:num->A) i`; `(v:num->A) j`;
                `v:num->A`] AUTNSTAGE_EREC) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]));;

(* ===================================================================== *)
(* S3-2a : "iF is THE muPrel-image function of ig on carrier iP" as an    *)
(* object formula (parametric slots < 150; internal binders 150/151/      *)
(* 160/161 + apply_form binders 152-154, 162-164).  Uniform building      *)
(* block for the internal sigma |-> autB(sigma) chain.                    *)
(* ===================================================================== *)

let imgfun_form = new_definition
 `imgfun_form ig iP iF =
    !! 150 (!! 151 ((apply_form iF 150 151) <->
      ((150 %% iP) &&
       !! 160 ((160 %% 151) <->
               ?? 161 ((161 %% 150) && apply_form ig 161 160)))))`;;

let HOLDS_IMGFUN = prove
 (`!D (E:A->A->bool) v ig iP iF.
     valuation D v /\ ig < 150 /\ iP < 150 /\ iF < 150
     ==> (holds D E v (imgfun_form ig iP iF) <=>
          !p q. p IN D /\ q IN D
                ==> (eapply D E (v iF) p q <=>
                     E p (v iP) /\ muPrel D E (v ig) p q))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[imgfun_form; holds; HOLDS_IFF; HOLDS_AND; HOLDS_EX] THEN
  MATCH_MP_TAC(MESON[]
    `(!p q:A. p IN D /\ q IN D ==> (P p q <=> Q p q))
     ==> ((!p. p IN D ==> !q. q IN D ==> P p q) <=>
          (!p q. p IN D /\ q IN D ==> Q p q))`) THEN
  MAP_EVERY X_GEN_TAC [`p:A`;`q:A`] THEN STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((151 |-> (q:A)) ((150 |-> (p:A)) v))`
  ASSUME_TAC THENL [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
      (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC)); ALL_TAC] THEN
  SUBGOAL_THEN
   `holds D E ((151 |-> (q:A)) ((150 |-> (p:A)) v)) (apply_form iF 150 151) <=>
    eapply D E (v iF) p q`
  (fun th -> REWRITE_TAC[th]) THENL
   [ASM_SIMP_TAC[HOLDS_APPLY_FORM] THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER;
      ARITH_RULE `~(150 = 151)`;
      ARITH_RULE `iF < 150 ==> ~(iF = 150) /\ ~(iF = 151)`];
    ALL_TAC] THEN
  MATCH_MP_TAC(TAUT `(a <=> c) ==> ((x <=> a) <=> (x <=> c))`) THEN
  SUBGOAL_THEN
   `((151 |-> (q:A)) ((150 |-> (p:A)) v)) 150 = p /\
    ((151 |-> (q:A)) ((150 |-> (p:A)) v)) iP = v iP`
  STRIP_ASSUME_TAC THENL
   [ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER;
      ARITH_RULE `~(150 = 151)`;
      ARITH_RULE `iP < 150 ==> ~(iP = 150) /\ ~(iP = 151)`];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC(TAUT `(b <=> d) ==> ((x /\ b) <=> (x /\ d))`) THEN
  REWRITE_TAC[muPrel] THEN ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC(MESON[]
    `(!y:A. y IN D ==> (P y <=> Q y))
     ==> ((!y. y IN D ==> P y) <=> (!y. y IN D ==> Q y))`) THEN
  X_GEN_TAC `y:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN
   `valuation D ((160 |-> (y:A)) ((151 |-> (q:A)) ((150 |-> (p:A)) v)))`
  ASSUME_TAC THENL [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
      (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC)); ALL_TAC] THEN
  SUBGOAL_THEN
   `((160 |-> (y:A)) ((151 |-> (q:A)) ((150 |-> (p:A)) v))) 160 = y /\
    ((160 |-> (y:A)) ((151 |-> (q:A)) ((150 |-> (p:A)) v))) 151 = q`
  STRIP_ASSUME_TAC THENL
   [SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE `~(160 = 151)`];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC(TAUT `(a <=> c) ==> ((x <=> a) <=> (x <=> c))`) THEN
  MATCH_MP_TAC(MESON[]
    `(!x:A. x IN D ==> (P x <=> Q x))
     ==> ((?x. x IN D /\ P x) <=> (?x. x IN D /\ Q x))`) THEN
  X_GEN_TAC `x:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN
   `valuation D ((161 |-> (x:A)) ((160 |-> (y:A)) ((151 |-> (q:A))
      ((150 |-> (p:A)) v))))`
  ASSUME_TAC THENL [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
      (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC)); ALL_TAC] THEN
  MATCH_MP_TAC(TAUT `(a <=> c) /\ (b <=> d) ==> ((a /\ b) <=> (c /\ d))`) THEN
  CONJ_TAC THENL
   [ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER;
      ARITH_RULE `~(161 = 160) /\ ~(161 = 151) /\ ~(160 = 151)`;
      ARITH_RULE `~(161 = 150) /\ ~(160 = 150) /\ ~(151 = 150)`];
    ASM_SIMP_TAC[HOLDS_APPLY_FORM] THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER;
      ARITH_RULE `~(161 = 160)`;
      ARITH_RULE
       `ig < 150
        ==> ~(ig = 161) /\ ~(ig = 160) /\ ~(ig = 151) /\ ~(ig = 150)`]]);;

(* ===================================================================== *)
(* S3-2b : three-slot rebinding wrapper (binds 0,1,2 -- the permci_form   *)
(* interface slots u_in/out/sigma) so permci_form can be applied at       *)
(* arbitrary argument slots.  Mirror of recapp3_form/recapp45_form.       *)
(* ===================================================================== *)

let recapp012_form = new_definition
  `recapp012_form q i j k =
     !! 0 (!! 1 (!! 2 ((Eq 0 i && Eq 1 j && Eq 2 k) --> q)))`;;

let HOLDS_RECAPP012_FORM = prove
 (`!D (E:A->A->bool) v q i j k.
        valuation D v /\ ~(i = 0) /\ ~(i = 1) /\ ~(i = 2) /\
        ~(j = 0) /\ ~(j = 1) /\ ~(j = 2) /\
        ~(k = 0) /\ ~(k = 1) /\ ~(k = 2)
        ==> (holds D E v (recapp012_form q i j k) <=>
             holds D E ((2 |-> v k) ((1 |-> v j) ((0 |-> v i) v))) q)`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[recapp012_form; holds; HOLDS_AND] THEN
  ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER;
    ARITH_RULE `~(0 = 1) /\ ~(0 = 2) /\ ~(1 = 2)`] THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  EQ_TAC THENL
   [DISCH_THEN(MP_TAC o SPEC `(v:num->A) i`) THEN ASM_SIMP_TAC[] THEN
    DISCH_THEN(MP_TAC o SPEC `(v:num->A) j`) THEN ASM_SIMP_TAC[] THEN
    DISCH_THEN(MP_TAC o SPEC `(v:num->A) k`) THEN ASM_SIMP_TAC[];
    MESON_TAC[]]);;

(* ===================================================================== *)
(* S3-2 : mucifun_form (S3-2c) then autb_of_form                          *)
(* (S3-2) -- the uniform  sigma |-> autB(sigma)  object formula.          *)
(* ===================================================================== *)

(* ===================================================================== *)
(* S3-2c : mucifun_form -- "iF is THE mucirel-graph function of the perm  *)
(* (v is) on carrier (v ici)" as an object formula.  First link of the    *)
(* uniform sigma |-> autB(sigma) chain (imgfun_form then lifts twice:      *)
(* muci |-> muP |-> autB).  Needs HOLDS_PERMCI_PAIR2, the slot-2-modded    *)
(* variant of HOLDS_PERMCI_PAIR (recapp012_form rebinds slot 2 = sigma).   *)
(* ===================================================================== *)

(* permci_form at the triple-mod (2|->s),(1|->out),(0|->u): slot 2 is     *)
(* now read from the explicit mod (= s), not the base valuation.          *)
let HOLDS_PERMCI_PAIR2 = prove
 (`!D (E:A->A->bool) v u out s.
      valuation D v /\ u IN D /\ out IN D /\ s IN D
      ==> (holds D E ((2 |-> s) ((1 |-> out) ((0 |-> u) v))) permci_form <=>
           ?w. mucirel D E s u w /\ eopair D E u w out)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;
    `(2 |-> s) ((1 |-> out) ((0 |-> u) (v:num->A)))`] HOLDS_PERMCI_FORM) THEN
  ANTS_TAC THENL [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
                         (MATCH_MP_TAC VALUATION_VALMOD THEN
                          CONJ_TAC)); ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN
  SUBGOAL_THEN
   `((2 |-> s) ((1 |-> out) ((0 |-> u) (v:num->A)))) 0 = u /\
    ((2 |-> s) ((1 |-> out) ((0 |-> u) (v:num->A)))) 1 = out /\
    ((2 |-> s) ((1 |-> out) ((0 |-> u) (v:num->A)))) 2 = s`
   (fun th -> REWRITE_TAC[th]) THENL
   [SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER;
      ARITH_RULE `~(0 = 1) /\ ~(1 = 2) /\ ~(0 = 2) /\ ~(1 = 0) /\
                  ~(2 = 1) /\ ~(2 = 0)`];
    ALL_TAC] THEN
  REWRITE_TAC[mucirel] THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `a3:A` (X_CHOOSE_THEN `a4:A` (X_CHOOSE_THEN `a5:A`
      (X_CHOOSE_THEN `a6:A` (X_CHOOSE_THEN `a7:A` (X_CHOOSE_THEN `a8:A`
      (X_CHOOSE_THEN `a9:A` STRIP_ASSUME_TAC))))))) THEN
    EXISTS_TAC `a9:A` THEN CONJ_TAC THENL
     [MAP_EVERY EXISTS_TAC [`a3:A`;`a4:A`;`a5:A`;`a6:A`;`a7:A`;`a8:A`] THEN
      ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[]];
    DISCH_THEN(X_CHOOSE_THEN `w:A` (CONJUNCTS_THEN2
      (X_CHOOSE_THEN `a3:A` (X_CHOOSE_THEN `a4:A` (X_CHOOSE_THEN `a5:A`
        (X_CHOOSE_THEN `a6:A` (X_CHOOSE_THEN `a7:A` (X_CHOOSE_THEN `a8:A`
        STRIP_ASSUME_TAC))))))
      ASSUME_TAC)) THEN
    SUBGOAL_THEN `(w:A) IN D` ASSUME_TAC THENL
     [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC
      [`a3:A`;`a4:A`;`a5:A`;`a6:A`;`a7:A`;`a8:A`;`w:A`] THEN
    ASM_REWRITE_TAC[]]);;

let mucifun_form = new_definition
 `mucifun_form is ici iF =
    !! 150 (!! 151 ((apply_form iF 150 151) <->
      ((150 %% ici) &&
       ?? 160 (opair_form 150 151 160 &&
               recapp012_form permci_form 150 160 is))))`;;

let HOLDS_MUCIFUN = prove
 (`!D (E:A->A->bool) v is ici iF.
     model D E ZF_AX /\ valuation D v /\
     2 < is /\ is < 150 /\ ici < 150 /\ iF < 150
     ==> (holds D E v (mucifun_form is ici iF) <=>
          !u w. u IN D /\ w IN D
                ==> (eapply D E (v iF) u w <=>
                     E u (v ici) /\ mucirel D E (v is) u w))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[mucifun_form; holds; HOLDS_IFF; HOLDS_AND; HOLDS_EX] THEN
  MATCH_MP_TAC(MESON[]
    `(!p q:A. p IN D /\ q IN D ==> (P p q <=> Q p q))
     ==> ((!p. p IN D ==> !q. q IN D ==> P p q) <=>
          (!p q. p IN D /\ q IN D ==> Q p q))`) THEN
  MAP_EVERY X_GEN_TAC [`u:A`;`w:A`] THEN STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((151 |-> (w:A)) ((150 |-> (u:A)) v))`
  ASSUME_TAC THENL [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
      (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC)); ALL_TAC] THEN
  SUBGOAL_THEN
   `holds D E ((151 |-> (w:A)) ((150 |-> (u:A)) v)) (apply_form iF 150 151) <=>
    eapply D E (v iF) u w`
  (fun th -> REWRITE_TAC[th]) THENL
   [ASM_SIMP_TAC[HOLDS_APPLY_FORM] THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER;
      ARITH_RULE `~(150 = 151)`;
      ARITH_RULE `iF < 150 ==> ~(iF = 150) /\ ~(iF = 151)`];
    ALL_TAC] THEN
  MATCH_MP_TAC(TAUT `(a <=> c) ==> ((x <=> a) <=> (x <=> c))`) THEN
  SUBGOAL_THEN
   `((151 |-> (w:A)) ((150 |-> (u:A)) v)) 150 = u /\
    ((151 |-> (w:A)) ((150 |-> (u:A)) v)) ici = v ici`
  STRIP_ASSUME_TAC THENL
   [ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER;
      ARITH_RULE `~(150 = 151)`;
      ARITH_RULE `ici < 150 ==> ~(ici = 150) /\ ~(ici = 151)`];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC(TAUT `(b <=> d) ==> ((x /\ b) <=> (x /\ d))`) THEN
  SUBGOAL_THEN
   `!op:A. op IN D
           ==> (holds D E ((160 |-> op) ((151 |-> (w:A)) ((150 |-> (u:A)) v)))
                          (opair_form 150 151 160) <=>
                eopair D E u w op)`
  (LABEL_TAC "opair") THENL
   [X_GEN_TAC `op:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN
     `valuation D ((160 |-> op) ((151 |-> (w:A)) ((150 |-> (u:A)) v)))`
    ASSUME_TAC THENL [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
        (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC)); ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_OPAIR_FORM] THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER;
      ARITH_RULE `~(150 = 151) /\ ~(150 = 160) /\ ~(151 = 160)`];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!op:A. op IN D
           ==> (holds D E ((160 |-> op) ((151 |-> (w:A)) ((150 |-> (u:A)) v)))
                          (recapp012_form permci_form 150 160 is) <=>
                (?w2. mucirel D E (v is) u w2 /\ eopair D E u w2 op))`
  (LABEL_TAC "rec") THENL
   [X_GEN_TAC `op:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN
     `valuation D ((160 |-> op) ((151 |-> (w:A)) ((150 |-> (u:A)) v)))`
    ASSUME_TAC THENL [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
        (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC)); ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;
      `(160 |-> op) ((151 |-> (w:A)) ((150 |-> (u:A)) v))`;
      `permci_form`;`150`;`160`;`is:num`] HOLDS_RECAPP012_FORM) THEN
    ANTS_TAC THENL
     [CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ASM_ARITH_TAC]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    SUBGOAL_THEN
     `((160 |-> op) ((151 |-> (w:A)) ((150 |-> (u:A)) v))) 150 = u /\
      ((160 |-> op) ((151 |-> (w:A)) ((150 |-> (u:A)) v))) 160 = op /\
      ((160 |-> op) ((151 |-> (w:A)) ((150 |-> (u:A)) v))) is = v is`
    STRIP_ASSUME_TAC THENL
     [ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER;
        ARITH_RULE `~(150 = 151) /\ ~(150 = 160) /\ ~(151 = 160)`] THEN
      ASM_SIMP_TAC[VALMOD_OTHER;
        ARITH_RULE `2 < is /\ is < 150
                    ==> ~(is = 150) /\ ~(is = 151) /\ ~(is = 160)`];
      ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;
      `(160 |-> op) ((151 |-> (w:A)) ((150 |-> (u:A)) v))`;
      `u:A`;`op:A`;`(v:num->A) is`] HOLDS_PERMCI_PAIR2) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]);
    ALL_TAC] THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `op:A`
      (CONJUNCTS_THEN2 (LABEL_TAC "opD")
        (CONJUNCTS_THEN2 (LABEL_TAC "hop") (LABEL_TAC "hrec")))) THEN
    SUBGOAL_THEN `eopair D (E:A->A->bool) u w op` (LABEL_TAC "eop") THENL
     [USE_THEN "opair" (MP_TAC o SPEC `op:A`) THEN
      ANTS_TAC THENL [USE_THEN "opD" ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> USE_THEN "hop" (ACCEPT_TAC o EQ_MP th));
      ALL_TAC] THEN
    USE_THEN "rec" (MP_TAC o SPEC `op:A`) THEN
    ANTS_TAC THENL [USE_THEN "opD" ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "hrec" (MP_TAC o EQ_MP th)) THEN
    DISCH_THEN(X_CHOOSE_THEN `w2:A`
      (CONJUNCTS_THEN2 (LABEL_TAC "muc") (LABEL_TAC "eop2"))) THEN
    SUBGOAL_THEN `(w2:A) IN D` ASSUME_TAC THENL
     [USE_THEN "muc" (STRIP_ASSUME_TAC o REWRITE_RULE[mucirel]) THEN
      ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `(w2:A) = w` SUBST_ALL_TAC THENL
     [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`u:A`;`w2:A`;`u:A`;`w:A`;`op:A`]
        EOPAIR_INJ) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN(ACCEPT_TAC o CONJUNCT2)];
      ALL_TAC] THEN
    USE_THEN "muc" ACCEPT_TAC;
    DISCH_TAC THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`u:A`;`w:A`] EOPAIR_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `op:A` (LABEL_TAC "eop")) THEN
    SUBGOAL_THEN `(op:A) IN D` (LABEL_TAC "opD") THENL
     [USE_THEN "eop" (ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
    EXISTS_TAC `op:A` THEN
    USE_THEN "opD" (fun th -> REWRITE_TAC[th]) THEN CONJ_TAC THENL
     [USE_THEN "opair" (MP_TAC o SPEC `op:A`) THEN
      ANTS_TAC THENL [USE_THEN "opD" ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN USE_THEN "eop" ACCEPT_TAC;
      USE_THEN "rec" (MP_TAC o SPEC `op:A`) THEN
      ANTS_TAC THENL [USE_THEN "opD" ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[]]]);;

(* ===================================================================== *)
(* S3-2 : autb_of_form -- the uniform  sigma |-> autB(sigma)  object       *)
(* formula.  Composes the three levels of the S1 chain:                    *)
(*   X = muci  : eapply X u w <=> E u P /\ mucirel sigma u w   (mucifun)    *)
(*   Y = muP   : eapply Y p q <=> E p P /\ muPrel  X    p q    (imgfun)     *)
(*   v ib=autB : eapply (v ib) b c <=> E b B /\ muPrel Y b c   (imgfun)     *)
(* internal witness slots 148 (= muci) and 149 (= muP), below every binder *)
(* used by mucifun_form/imgfun_form (150,151,160,161) and apply_form       *)
(* (152-154,162-164); parameter slots is,iP,iB,ib all < 148.               *)
(* ===================================================================== *)
let autb_of_form = new_definition
 `autb_of_form is iP iB ib =
    ?? 148 (?? 149 (mucifun_form is iP 148 &&
                    (imgfun_form 148 iP 149 &&
                     imgfun_form 149 iB ib)))`;;

let HOLDS_AUTB_OF = prove
 (`!D (E:A->A->bool) v is iP iB ib.
     model D E ZF_AX /\ valuation D v /\
     2 < is /\ is < 148 /\ iP < 148 /\ iB < 148 /\ ib < 148
     ==> (holds D E v (autb_of_form is iP iB ib) <=>
          ?muci muP. muci IN D /\ muP IN D /\
            (!u w. u IN D /\ w IN D
                   ==> (eapply D E muci u w <=>
                        E u (v iP) /\ mucirel D E (v is) u w)) /\
            (!p q. p IN D /\ q IN D
                   ==> (eapply D E muP p q <=>
                        E p (v iP) /\ muPrel D E muci p q)) /\
            (!b c. b IN D /\ c IN D
                   ==> (eapply D E (v ib) b c <=>
                        E b (v iB) /\ muPrel D E muP b c)))`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[autb_of_form; HOLDS_EX; HOLDS_AND] THEN
  MATCH_MP_TAC(MESON[]
    `(!X Y:A. X IN D /\ Y IN D ==> (b X Y <=> c X Y))
     ==> ((?X. X IN D /\ (?Y. Y IN D /\ b X Y)) <=>
          (?X Y. X IN D /\ Y IN D /\ c X Y))`) THEN
  MAP_EVERY X_GEN_TAC [`X:A`;`Y:A`] THEN STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((149 |-> (Y:A)) ((148 |-> (X:A)) v))`
  ASSUME_TAC THENL [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
      (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC)); ALL_TAC] THEN
  (* ---- level 1 : mucifun_form is iP 148  reads slot 148 = X ---- *)
  SUBGOAL_THEN
   `holds D E ((149 |-> (Y:A)) ((148 |-> (X:A)) v)) (mucifun_form is iP 148) <=>
    (!u w. u IN D /\ w IN D
           ==> (eapply D E X u w <=>
                E u (v iP) /\ mucirel D E (v is) u w))`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;
      `(149 |-> (Y:A)) ((148 |-> (X:A)) v)`;`is:num`;`iP:num`;`148`]
      HOLDS_MUCIFUN) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER;
      ARITH_RULE `~(148 = 149)`;
      ARITH_RULE `is < 148 ==> ~(is = 148) /\ ~(is = 149)`;
      ARITH_RULE `iP < 148 ==> ~(iP = 148) /\ ~(iP = 149)`];
    ALL_TAC] THEN
  (* ---- level 2 : imgfun_form 148 iP 149  reads 148=X, 149=Y ---- *)
  SUBGOAL_THEN
   `holds D E ((149 |-> (Y:A)) ((148 |-> (X:A)) v)) (imgfun_form 148 iP 149) <=>
    (!p q. p IN D /\ q IN D
           ==> (eapply D E Y p q <=>
                E p (v iP) /\ muPrel D E X p q))`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;
      `(149 |-> (Y:A)) ((148 |-> (X:A)) v)`;`148`;`iP:num`;`149`]
      HOLDS_IMGFUN) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER;
      ARITH_RULE `~(148 = 149)`;
      ARITH_RULE `iP < 148 ==> ~(iP = 148) /\ ~(iP = 149)`];
    ALL_TAC] THEN
  (* ---- level 3 : imgfun_form 149 iB ib  reads 149=Y, ib=v ib ---- *)
  SUBGOAL_THEN
   `holds D E ((149 |-> (Y:A)) ((148 |-> (X:A)) v)) (imgfun_form 149 iB ib) <=>
    (!b c. b IN D /\ c IN D
           ==> (eapply D E (v ib) b c <=>
                E b (v iB) /\ muPrel D E Y b c))`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;
      `(149 |-> (Y:A)) ((148 |-> (X:A)) v)`;`149`;`iB:num`;`ib:num`]
      HOLDS_IMGFUN) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER;
      ARITH_RULE `~(148 = 149)`;
      ARITH_RULE `iB < 148 ==> ~(iB = 148) /\ ~(iB = 149)`;
      ARITH_RULE `ib < 148 ==> ~(ib = 148) /\ ~(ib = 149)`];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[]);;

(* ===== L11 group: S3-4 symfix_form + S3-5a hssym internals ===== *)

(* ===================================================================== *)
(* S3-4 : symfix_form -- the object formula  "autN_sigma(x) = x"          *)
(*   (sigma fixes the B-name x).  Composes autb_of_form (slot 3 := the    *)
(*   autB of the perm at slot is, with B at slot 2) with the autN tower   *)
(*   read via  recapp45_form (rec_form autn_step_form 4):                  *)
(*     symfix_form is iP ix =                                              *)
(*       ?? 3 (autb_of_form is iP 2 3 &&                                   *)
(*             ?? 30 (ordinal_form 30 &&                                   *)
(*               ?? 31 (recapp45_form (rec_form autn_step_form 4) 30 31 && *)
(*                 ?? 32 (opair_form ix ix 32 && (32 %% 31)))))            *)
(*   By AUTN_STAGE/eautn this says exactly  eautn D E B autB(sigma) x x.    *)
(*   Internal binders 3 (autB), 30 (ordinal a), 31 (stage cd), 32 (pair);  *)
(*   opair_form ix ix 32 uses 33,34.  Params: 2<is<148, is<>3; iP<148,     *)
(*   iP<>3; ix<30, ix<>3.                                                   *)
(* ===================================================================== *)

let symfix_form = new_definition
 `symfix_form is iP ix =
    ?? 3 (autb_of_form is iP 2 3 &&
          ?? 30 (ordinal_form 30 &&
                 ?? 31 (recapp45_form (rec_form autn_step_form 4) 30 31 &&
                        ?? 32 (opair_form ix ix 32 && (32 %% 31)))))`;;

let HOLDS_SYMFIX = prove
 (`!D (E:A->A->bool) v is iP ix.
     model D E ZF_AX /\ valuation D v /\
     2 < is /\ is < 148 /\ ~(is = 3) /\
     iP < 148 /\ ~(iP = 3) /\
     ix < 30 /\ ~(ix = 3)
     ==> (holds D E v (symfix_form is iP ix) <=>
          ?autB. autB IN D /\
            (?muci muP. muci IN D /\ muP IN D /\
               (!u w. u IN D /\ w IN D
                      ==> (eapply D E muci u w <=>
                           E u (v iP) /\ mucirel D E (v is) u w)) /\
               (!p q. p IN D /\ q IN D
                      ==> (eapply D E muP p q <=>
                           E p (v iP) /\ muPrel D E muci p q)) /\
               (!b c. b IN D /\ c IN D
                      ==> (eapply D E autB b c <=>
                           E b (v 2) /\ muPrel D E muP b c))) /\
            eautn D E (v 2) autB (v ix) (v ix))`,
  REPEAT STRIP_TAC THEN
  (* ---- (a') the autb_of_form conjunct, uniform in W ---- *)
  SUBGOAL_THEN
   `!W:A. W IN D ==>
       (holds D E ((3 |-> W) v) (autb_of_form is iP 2 3) <=>
        ?muci muP. muci IN D /\ muP IN D /\
          (!u w. u IN D /\ w IN D
                 ==> (eapply D E muci u w <=>
                      E u (v iP) /\ mucirel D E (v is) u w)) /\
          (!p q. p IN D /\ q IN D
                 ==> (eapply D E muP p q <=>
                      E p (v iP) /\ muPrel D E muci p q)) /\
          (!b c. b IN D /\ c IN D
                 ==> (eapply D E W b c <=>
                      E b (v 2) /\ muPrel D E muP b c)))`
  (LABEL_TAC "aeq") THENL
   [X_GEN_TAC `W:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `valuation D ((3 |-> (W:A)) v)` ASSUME_TAC THENL
     [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
             (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC)); ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`(3 |-> (W:A)) v`;
                   `is:num`;`iP:num`;`2`;`3`] HOLDS_AUTB_OF) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE `~(2 = 3)`];
    ALL_TAC] THEN
  (* ---- (b') the autN-tower conjunct = eautn, uniform in W ---- *)
  SUBGOAL_THEN
   `!W:A. W IN D ==>
       (holds D E ((3 |-> W) v)
          (?? 30 (ordinal_form 30 &&
                  ?? 31 (recapp45_form (rec_form autn_step_form 4) 30 31 &&
                         ?? 32 (opair_form ix ix 32 && (32 %% 31))))) <=>
        eautn D E (v 2) W (v ix) (v ix))`
  (LABEL_TAC "beq") THENL
   [X_GEN_TAC `W:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `(v:num->A) ix IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
    SUBGOAL_THEN `valuation D ((3 |-> (W:A)) v)` ASSUME_TAC THENL
     [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
             (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC)); ALL_TAC] THEN
    SUBGOAL_THEN
     `holds D E ((3 |-> (W:A)) v)
        (?? 30 (ordinal_form 30 &&
                ?? 31 (recapp45_form (rec_form autn_step_form 4) 30 31 &&
                       ?? 32 (opair_form ix ix 32 && (32 %% 31))))) <=>
      (?a. a IN D /\ eordinal D E a /\
           (?c. c IN D /\ autnstage D E (v 2) W a c /\
                (?pp. pp IN D /\ eopair D E (v ix) (v ix) pp /\ E pp c)))`
     (fun th -> REWRITE_TAC[th]) THENL
     [REWRITE_TAC[HOLDS_EX] THEN
      MATCH_MP_TAC(MESON[]
        `(!a:A. a IN D ==> (P a <=> Q a))
         ==> ((?a. a IN D /\ P a) <=> (?a. a IN D /\ Q a))`) THEN
      X_GEN_TAC `a:A` THEN DISCH_TAC THEN
      SUBGOAL_THEN `valuation D ((30 |-> (a:A)) ((3 |-> (W:A)) v))`
      ASSUME_TAC THENL [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
          (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC)); ALL_TAC] THEN
      REWRITE_TAC[HOLDS_AND] THEN
      SUBGOAL_THEN
       `holds D E ((30 |-> (a:A)) ((3 |-> (W:A)) v)) (ordinal_form 30) <=>
        eordinal D E a`
       (fun th -> REWRITE_TAC[th]) THENL
       [ASM_SIMP_TAC[HOLDS_ORDINAL_FORM] THEN REWRITE_TAC[VALMOD_BASIC];
        ALL_TAC] THEN
      MATCH_MP_TAC(TAUT `(b <=> b') ==> ((e /\ b) <=> (e /\ b'))`) THEN
      REWRITE_TAC[HOLDS_EX] THEN
      MATCH_MP_TAC(MESON[]
        `(!c:A. c IN D ==> (P c <=> Q c))
         ==> ((?c. c IN D /\ P c) <=> (?c. c IN D /\ Q c))`) THEN
      X_GEN_TAC `c:A` THEN DISCH_TAC THEN
      SUBGOAL_THEN
       `valuation D ((31 |-> (c:A)) ((30 |-> (a:A)) ((3 |-> (W:A)) v)))`
      ASSUME_TAC THENL [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
          (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC)); ALL_TAC] THEN
      REWRITE_TAC[HOLDS_AND] THEN
      SUBGOAL_THEN
       `holds D E ((31 |-> (c:A)) ((30 |-> (a:A)) ((3 |-> (W:A)) v)))
          (recapp45_form (rec_form autn_step_form 4) 30 31) <=>
        autnstage D E (v 2) W a c`
       (fun th -> REWRITE_TAC[th]) THENL
       [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;
          `(31 |-> (c:A)) ((30 |-> (a:A)) ((3 |-> (W:A)) v))`;`30`;`31`]
          HOLDS_RECAPP45_AUTNSTEP) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN ARITH_TAC; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER;
          ARITH_RULE `~(2 = 31) /\ ~(2 = 30) /\ ~(2 = 3) /\
                      ~(3 = 31) /\ ~(3 = 30) /\ ~(30 = 31)`];
        ALL_TAC] THEN
      MATCH_MP_TAC(TAUT `(b <=> b') ==> ((e /\ b) <=> (e /\ b'))`) THEN
      REWRITE_TAC[HOLDS_EX] THEN
      MATCH_MP_TAC(MESON[]
        `(!pp:A. pp IN D ==> (P pp <=> Q pp))
         ==> ((?pp. pp IN D /\ P pp) <=> (?pp. pp IN D /\ Q pp))`) THEN
      X_GEN_TAC `pp:A` THEN DISCH_TAC THEN
      SUBGOAL_THEN
       `valuation D ((32 |-> (pp:A))
          ((31 |-> (c:A)) ((30 |-> (a:A)) ((3 |-> (W:A)) v))))`
      ASSUME_TAC THENL [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
          (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC)); ALL_TAC] THEN
      REWRITE_TAC[HOLDS_AND] THEN
      SUBGOAL_THEN
       `holds D E ((32 |-> (pp:A))
          ((31 |-> (c:A)) ((30 |-> (a:A)) ((3 |-> (W:A)) v))))
          (opair_form ix ix 32) <=> eopair D E (v ix) (v ix) pp`
       ASSUME_TAC THENL
       [ASM_SIMP_TAC[HOLDS_OPAIR_FORM] THEN
        ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER;
          ARITH_RULE `ix < 30 ==> ~(ix = 32) /\ ~(ix = 31) /\ ~(ix = 30)`];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `holds D E ((32 |-> (pp:A))
          ((31 |-> (c:A)) ((30 |-> (a:A)) ((3 |-> (W:A)) v)))) (32 %% 31) <=>
        E (pp:A) c`
       ASSUME_TAC THENL
       [REWRITE_TAC[holds] THEN
        ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE `~(31 = 32)`];
        ALL_TAC] THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    REWRITE_TAC[eautn] THEN ASM_REWRITE_TAC[] THEN MESON_TAC[];
    ALL_TAC] THEN
  (* ---- assemble ---- *)
  REWRITE_TAC[symfix_form] THEN
  ONCE_REWRITE_TAC[HOLDS_EX] THEN
  ONCE_REWRITE_TAC[HOLDS_AND] THEN
  MATCH_MP_TAC(MESON[]
    `(!W:A. W IN D ==> (b W <=> c W))
     ==> ((?W. W IN D /\ b W) <=> (?W. W IN D /\ c W))`) THEN
  X_GEN_TAC `autB:A` THEN DISCH_TAC THEN
  USE_THEN "aeq" (fun ath -> USE_THEN "beq" (fun bth ->
    ASM_SIMP_TAC[ath; bth])));;

(* ===================================================================== *)
(* S3-5a step A1 : bijfun_form f a b                                      *)
(*   "the element named at slot f IS a bijection (v a) <-> (v b)".        *)
(*   = bijform's body with the function slot FREED to the parameter f     *)
(*   (no outer binder).  Helper band = MAX f (MAX a b) + 2..5 (above      *)
(*   f,a,b).  Clone of HOLDS_BIJFORM MINUS the ?f peel:                    *)
(*   raw curried HOLDS_BIJFUN, then a 2-line ebij wrapper HOLDS_BIJFUN_FORM*)
(*   mirroring HOLDS_BIJFORM_EBIJ.                                         *)
(* ===================================================================== *)

let bijfun_form = new_definition
 `bijfun_form f a b =
    ((!! (MAX f (MAX a b) + 2) (!! (MAX f (MAX a b) + 3)
         (apply_form f (MAX f (MAX a b) + 2) (MAX f (MAX a b) + 3) -->
            (((MAX f (MAX a b) + 2) %% a) && ((MAX f (MAX a b) + 3) %% b))))) &&
     ((!! (MAX f (MAX a b) + 2)
         (((MAX f (MAX a b) + 2) %% a) -->
            ?? (MAX f (MAX a b) + 3)
               (((MAX f (MAX a b) + 3) %% b) &&
                apply_form f (MAX f (MAX a b) + 2) (MAX f (MAX a b) + 3)))) &&
      ((!! (MAX f (MAX a b) + 2) (!! (MAX f (MAX a b) + 3)
          (!! (MAX f (MAX a b) + 4)
          ((apply_form f (MAX f (MAX a b) + 2) (MAX f (MAX a b) + 3) &&
            apply_form f (MAX f (MAX a b) + 2) (MAX f (MAX a b) + 4)) -->
           Eq (MAX f (MAX a b) + 3) (MAX f (MAX a b) + 4))))) &&
       ((!! (MAX f (MAX a b) + 2) (!! (MAX f (MAX a b) + 5)
           (!! (MAX f (MAX a b) + 3)
           ((apply_form f (MAX f (MAX a b) + 2) (MAX f (MAX a b) + 3) &&
             apply_form f (MAX f (MAX a b) + 5) (MAX f (MAX a b) + 3)) -->
            Eq (MAX f (MAX a b) + 2) (MAX f (MAX a b) + 5))))) &&
        (!! (MAX f (MAX a b) + 3)
           (((MAX f (MAX a b) + 3) %% b) -->
            ?? (MAX f (MAX a b) + 2)
               (((MAX f (MAX a b) + 2) %% a) &&
                apply_form f (MAX f (MAX a b) + 2)
                    (MAX f (MAX a b) + 3))))))))`;;

let BIJFUN_DISEQ = ARITH_RULE
 `~(MAX f (MAX a b) + 2 = MAX f (MAX a b) + 3) /\
  ~(MAX f (MAX a b) + 3 = MAX f (MAX a b) + 2) /\
  ~(MAX f (MAX a b) + 2 = MAX f (MAX a b) + 4) /\
  ~(MAX f (MAX a b) + 4 = MAX f (MAX a b) + 2) /\
  ~(MAX f (MAX a b) + 2 = MAX f (MAX a b) + 5) /\
  ~(MAX f (MAX a b) + 5 = MAX f (MAX a b) + 2) /\
  ~(MAX f (MAX a b) + 3 = MAX f (MAX a b) + 4) /\
  ~(MAX f (MAX a b) + 4 = MAX f (MAX a b) + 3) /\
  ~(MAX f (MAX a b) + 3 = MAX f (MAX a b) + 5) /\
  ~(MAX f (MAX a b) + 5 = MAX f (MAX a b) + 3) /\
  ~(MAX f (MAX a b) + 4 = MAX f (MAX a b) + 5) /\
  ~(MAX f (MAX a b) + 5 = MAX f (MAX a b) + 4) /\
  ~(f = MAX f (MAX a b) + 2) /\ ~(f = MAX f (MAX a b) + 3) /\
  ~(f = MAX f (MAX a b) + 4) /\ ~(f = MAX f (MAX a b) + 5) /\
  ~(a = MAX f (MAX a b) + 2) /\ ~(a = MAX f (MAX a b) + 3) /\
  ~(a = MAX f (MAX a b) + 4) /\ ~(a = MAX f (MAX a b) + 5) /\
  ~(b = MAX f (MAX a b) + 2) /\ ~(b = MAX f (MAX a b) + 3) /\
  ~(b = MAX f (MAX a b) + 4) /\ ~(b = MAX f (MAX a b) + 5)`;;

(* raw curried satisfaction, cloning HOLDS_BIJFORM's RHS with f at slot f  *)
(* (so (v f) in place of the bound function) and NO ?f existential peel.   *)
let HOLDS_BIJFUN = prove
 (`!D (E:A->A->bool) v f a b.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v (bijfun_form f a b) <=>
             (!k. k IN D
                  ==> !t. t IN D
                          ==> eapply D E (v f) k t
                              ==> E k (v a) /\ E t (v b)) /\
             (!k. k IN D
                  ==> E k (v a)
                      ==> ?t. t IN D /\
                              E t (v b) /\ eapply D E (v f) k t) /\
             (!k. k IN D
                  ==> !t. t IN D
                          ==> !t'. t' IN D
                                   ==> eapply D E (v f) k t /\
                                       eapply D E (v f) k t'
                                       ==> t = t') /\
             (!k. k IN D
                  ==> !k'. k' IN D
                           ==> !t. t IN D
                                   ==> eapply D E (v f) k t /\
                                       eapply D E (v f) k' t
                                       ==> k = k') /\
             (!t. t IN D
                  ==> E t (v b)
                      ==> ?k. k IN D /\
                              E k (v a) /\ eapply D E (v f) k t))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  (* r1: canonical (k,t) tower *)
  SUBGOAL_THEN
   `!k t:A. k IN D /\ t IN D
      ==> (holds D E (((MAX f (MAX a b) + 3) |-> t)
                      (((MAX f (MAX a b) + 2) |-> k) v))
             (apply_form f (MAX f (MAX a b) + 2) (MAX f (MAX a b) + 3)) <=>
           eapply D (E:A->A->bool) (v f) k t)`
  (LABEL_TAC "r1") THENL
   [REPEAT STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `((MAX f (MAX a b) + 3) |-> (t:A)) (((MAX f (MAX a b) + 2) |-> (k:A)) v)`;
      `f:num`; `MAX f (MAX a b) + 2`; `MAX f (MAX a b) + 3`]
          HOLDS_APPLY_FORM) THEN
    ANTS_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; BIJFUN_DISEQ];
    ALL_TAC] THEN
  (* r2: (k,t,t') tower for single-valued clause *)
  SUBGOAL_THEN
   `!k t t':A. k IN D /\ t IN D /\ t' IN D
      ==> (holds D E (((MAX f (MAX a b) + 4) |-> t')
                      (((MAX f (MAX a b) + 3) |-> t)
             (((MAX f (MAX a b) + 2) |-> k) v)))
             (apply_form f (MAX f (MAX a b) + 2) (MAX f (MAX a b) + 3)) <=>
           eapply D (E:A->A->bool) (v f) k t) /\
          (holds D E (((MAX f (MAX a b) + 4) |-> t')
                      (((MAX f (MAX a b) + 3) |-> t)
             (((MAX f (MAX a b) + 2) |-> k) v)))
             (apply_form f (MAX f (MAX a b) + 2) (MAX f (MAX a b) + 4)) <=>
           eapply D E (v f) k t')`
  (LABEL_TAC "r2") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `((MAX f (MAX a b) + 4) |-> (t':A)) (((MAX f (MAX a b) + 3) |-> (t:A))
           (((MAX f (MAX a b) + 2) |-> (k:A)) v))`;
        `f:num`; `MAX f (MAX a b) + 2`; `MAX f (MAX a b) + 3`]
            HOLDS_APPLY_FORM);
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `((MAX f (MAX a b) + 4) |-> (t':A)) (((MAX f (MAX a b) + 3) |-> (t:A))
           (((MAX f (MAX a b) + 2) |-> (k:A)) v))`;
        `f:num`; `MAX f (MAX a b) + 2`; `MAX f (MAX a b) + 4`]
            HOLDS_APPLY_FORM)]
    THEN
    (ANTS_TAC THENL
      [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
       MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
       MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
       ALL_TAC] THEN
     DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
     SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; BIJFUN_DISEQ]);
    ALL_TAC] THEN
  (* r3: (k,k',t) tower for injective clause *)
  SUBGOAL_THEN
   `!k k' t:A. k IN D /\ k' IN D /\ t IN D
      ==> (holds D E (((MAX f (MAX a b) + 3) |-> t)
                      (((MAX f (MAX a b) + 5) |-> k')
             (((MAX f (MAX a b) + 2) |-> k) v)))
             (apply_form f (MAX f (MAX a b) + 2) (MAX f (MAX a b) + 3)) <=>
           eapply D (E:A->A->bool) (v f) k t) /\
          (holds D E (((MAX f (MAX a b) + 3) |-> t)
                      (((MAX f (MAX a b) + 5) |-> k')
             (((MAX f (MAX a b) + 2) |-> k) v)))
             (apply_form f (MAX f (MAX a b) + 5) (MAX f (MAX a b) + 3)) <=>
           eapply D E (v f) k' t)`
  (LABEL_TAC "r3") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `((MAX f (MAX a b) + 3) |-> (t:A)) (((MAX f (MAX a b) + 5) |-> (k':A))
           (((MAX f (MAX a b) + 2) |-> (k:A)) v))`;
        `f:num`; `MAX f (MAX a b) + 2`; `MAX f (MAX a b) + 3`]
            HOLDS_APPLY_FORM);
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `((MAX f (MAX a b) + 3) |-> (t:A)) (((MAX f (MAX a b) + 5) |-> (k':A))
           (((MAX f (MAX a b) + 2) |-> (k:A)) v))`;
        `f:num`; `MAX f (MAX a b) + 5`; `MAX f (MAX a b) + 3`]
            HOLDS_APPLY_FORM)]
    THEN
    (ANTS_TAC THENL
      [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
       MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
       MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
       ALL_TAC] THEN
     DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
     SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; BIJFUN_DISEQ]);
    ALL_TAC] THEN
  REWRITE_TAC[bijfun_form; HOLDS_EX; HOLDS_AND; holds] THEN
  SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; BIJFUN_DISEQ] THEN
  USE_THEN "r1" (fun th1 -> USE_THEN "r2" (fun th2 ->
    USE_THEN "r3" (fun th3 -> ASM_SIMP_TAC[th1; th2; th3]))) THEN
  (* r4: swapped (t,k) tower for the total/surjective existential clauses *)
  SUBGOAL_THEN
   `!k t:A. k IN D /\ t IN D
      ==> (holds D E (((MAX f (MAX a b) + 2) |-> k)
                      (((MAX f (MAX a b) + 3) |-> t) v))
             (apply_form f (MAX f (MAX a b) + 2) (MAX f (MAX a b) + 3)) <=>
           eapply D (E:A->A->bool) (v f) k t)`
  (LABEL_TAC "r4") THENL
   [REPEAT STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `((MAX f (MAX a b) + 2) |-> (k:A)) (((MAX f (MAX a b) + 3) |-> (t:A)) v)`;
      `f:num`; `MAX f (MAX a b) + 2`; `MAX f (MAX a b) + 3`]
          HOLDS_APPLY_FORM) THEN
    ANTS_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; BIJFUN_DISEQ];
    ALL_TAC] THEN
  MATCH_MP_TAC(TAUT
   `(b <=> b') /\ (e <=> e')
    ==> ((a /\ b /\ c /\ d /\ e) <=> (a /\ b' /\ c /\ d /\ e'))`) THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC(MESON[]
     `(!k:A. P k <=> Q k) ==> ((!k:A. P k) <=> (!k:A. Q k))`) THEN
    X_GEN_TAC `k:A` THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
    DISCH_TAC THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
    DISCH_TAC THEN
    MATCH_MP_TAC(MESON[]
     `(!t:A. P t <=> Q t) ==> ((?t:A. P t) <=> (?t:A. Q t))`) THEN
    X_GEN_TAC `t:A` THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
    DISCH_TAC THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
    DISCH_TAC THEN
    USE_THEN "r1" (fun th -> ASM_SIMP_TAC[th]);
    MATCH_MP_TAC(MESON[]
     `(!t:A. P t <=> Q t) ==> ((!t:A. P t) <=> (!t:A. Q t))`) THEN
    X_GEN_TAC `t:A` THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
    DISCH_TAC THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
    DISCH_TAC THEN
    MATCH_MP_TAC(MESON[]
     `(!k:A. P k <=> Q k) ==> ((?k:A. P k) <=> (?k:A. Q k))`) THEN
    X_GEN_TAC `k:A` THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
    DISCH_TAC THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
    DISCH_TAC THEN
    USE_THEN "r4" (fun th -> ASM_SIMP_TAC[th])]);;

(* ebij wrapper : clone of HOLDS_BIJFORM_EBIJ with the ?f peel              *)
(* replaced by discharging (v f) IN D from valuation.                       *)
let HOLDS_BIJFUN_FORM = prove
 (`!D (E:A->A->bool) v f a b.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v (bijfun_form f a b) <=>
             ebij D E (v f) (v a) (v b))`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`;
                `f:num`; `a:num`; `b:num`] HOLDS_BIJFUN) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  SUBGOAL_THEN `(v:num->A) f IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  ASM_REWRITE_TAC[ebij; IMP_CONJ; RIGHT_IMP_FORALL_THM]);;

(* ===================================================================== *)
(* S3-5a step A2 : permom_form s iom = bijfun_form s iom iom  (<=> eperm)  *)
(* ===================================================================== *)
let permom_form = new_definition
 `permom_form s iom = bijfun_form s iom iom`;;

let HOLDS_PERMOM_FORM = prove
 (`!D (E:A->A->bool) v s iom.
      model D E ZF_AX /\ valuation D v
      ==> (holds D E v (permom_form s iom) <=> eperm D E (v iom) (v s))`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[permom_form; eperm] THEN
  ASM_SIMP_TAC[HOLDS_BIJFUN_FORM]);;

(* ===================================================================== *)
(* S3-5a step A3 : fixes_form s ie  (<=> efixes D E (v s) (v ie))  *)
(*   = !! NN ((NN %% ie) --> apply_form s NN NN),  NN = MAX s ie + 1.      *)
(* ===================================================================== *)
let fixes_form = new_definition
 `fixes_form s ie =
    !! (MAX s ie + 1)
       (((MAX s ie + 1) %% ie) --> apply_form s (MAX s ie + 1)
        (MAX s ie + 1))`;;

let HOLDS_FIXES_FORM = prove
 (`!D (E:A->A->bool) v s ie.
      model D E ZF_AX /\ valuation D v
      ==> (holds D E v (fixes_form s ie) <=> efixes D E (v s) (v ie))`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[fixes_form; efixes; IMP_CONJ] THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[holds] THEN
  MATCH_MP_TAC(MESON[]
   `(!n:A. n IN D ==> (P n <=> Q n))
    ==> ((!n. n IN D ==> P n) <=> (!n. n IN D ==> Q n))`) THEN
  X_GEN_TAC `n:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `valuation D (((MAX s ie + 1) |-> (n:A)) v)` ASSUME_TAC THENL
   [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
           (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC)); ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `((MAX s ie + 1) |-> (n:A)) v`;
                `s:num`; `MAX s ie + 1`; `MAX s ie + 1`] HOLDS_APPLY_FORM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER;
    ARITH_RULE `~(MAX s ie + 1 = ie) /\ ~(MAX s ie + 1 = s)`]);;

(* ===================================================================== *)
(* S3-5a step A4 : finite_form ix iom  (parameterized bijfam_form)        *)
(*   holds <=> ?n. n IN D /\ E n (v iom) /\ ?f. ebij D E f n (v ix)        *)
(* ===================================================================== *)
let finite_form = new_definition
 `finite_form ix iom =
    ?? (MAX ix iom + 1)
       (((MAX ix iom + 1) %% iom) && bijform (MAX ix iom + 1) ix)`;;

let HOLDS_FINITE_FORM = prove
 (`!D (E:A->A->bool) v ix iom.
      model D E ZF_AX /\ valuation D v
      ==> (holds D E v (finite_form ix iom) <=>
           ?n. n IN D /\ E n (v iom) /\ ?f. ebij D E f n (v ix))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[finite_form] THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[HOLDS_EX] THEN
  MATCH_MP_TAC(MESON[]
   `(!n:A. n IN D ==> (P n <=> Q n))
    ==> ((?n. n IN D /\ P n) <=> (?n. n IN D /\ Q n))`) THEN
  X_GEN_TAC `n:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `valuation D (((MAX ix iom + 1) |-> (n:A)) v)` ASSUME_TAC THENL
   [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
           (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC)); ALL_TAC] THEN
  ASM_SIMP_TAC[HOLDS_AND] THEN
  SUBGOAL_THEN
   `holds D E (((MAX ix iom + 1) |-> (n:A)) v) ((MAX ix iom + 1) %% iom) <=>
    E n (v iom)` SUBST1_TAC THENL
   [REWRITE_TAC[HOLDS_MEM] THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER;
      ARITH_RULE `~(MAX ix iom + 1 = iom)`];
    ALL_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`; `E:A->A->bool`;
    `((MAX ix iom + 1) |-> (n:A)) v`; `MAX ix iom + 1`; `ix:num`]
    HOLDS_BIJFORM_EBIJ) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[];
    DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
  ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER;
    ARITH_RULE `~(MAX ix iom + 1 = ix)`]);;

(* ===================================================================== *)
(* S3-5a step A5 : hssym_form ix iom iP   (the "x is symmetric" core).    *)
(*   ie=40 (?? support), is=42 (!! permutation).  Slot 2 = B throughout.  *)
(* ===================================================================== *)
let hssym_form = new_definition
 `hssym_form ix iom iP =
    ?? 40 (finite_form 40 iom &&
           subset_form 40 iom &&
           !! 42 ((permom_form 42 iom && fixes_form 42 40)
                  --> symfix_form 42 iP ix))`;;

let HOLDS_HSSYM_FORM = prove
 (`!D (E:A->A->bool) v ix iom iP.
      model D E ZF_AX /\ valuation D v /\
      ix < 30 /\ ~(ix = 3) /\ iP < 148 /\ ~(iP = 3) /\
      ~(iP = 40) /\ ~(iP = 42) /\ ~(iom = 40) /\ ~(iom = 42)
      ==> (holds D E v (hssym_form ix iom iP) <=>
           ?e. e IN D /\
               (?n. n IN D /\ E n (v iom) /\ ?f. ebij D E f n e) /\
               esubset D E e (v iom) /\
               (!s. s IN D /\ eperm D E (v iom) s /\ efixes D E s e
                    ==> ?autB. autB IN D /\
                          (?muci muP. muci IN D /\ muP IN D /\
                             (!u w. u IN D /\ w IN D
                                    ==> (eapply D E muci u w <=>
                                         E u (v iP) /\ mucirel D E s u w)) /\
                             (!p q. p IN D /\ q IN D
                                    ==> (eapply D E muP p q <=>
                                         E p (v iP) /\ muPrel D E muci p q)) /\
                             (!b c. b IN D /\ c IN D
                                    ==> (eapply D E autB b c <=>
                                         E b (v 2) /\ muPrel D E muP b c))) /\
                          eautn D E (v 2) autB (v ix) (v ix)))`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[hssym_form] THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `~(ix = 40) /\ ~(ix = 42) /\ ~((2:num) = 40) /\ ~((2:num) = 42) /\
    ~((40:num) = 42)` STRIP_ASSUME_TAC THENL
   [ASM_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[HOLDS_EX] THEN
  MATCH_MP_TAC EXISTS_AND_CONG THEN BETA_TAC THEN
  X_GEN_TAC `e:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `valuation D ((40 |-> (e:A)) v)` ASSUME_TAC THENL
   [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
           (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC)); ALL_TAC] THEN
  REWRITE_TAC[HOLDS_AND] THEN
  SUBGOAL_THEN
   `holds D E ((40 |-> (e:A)) v) (finite_form 40 iom) <=>
    (?n. n IN D /\ E n (v iom) /\ ?f. ebij D E f n e)`
  (LABEL_TAC "fin") THENL
   [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `(40 |-> (e:A)) v`;
                   `40`; `iom:num`] HOLDS_FINITE_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN(fun th ->
        REWRITE_TAC[th])] THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `holds D E ((40 |-> (e:A)) v) (subset_form 40 iom) <=>
    esubset D E e (v iom)`
  (LABEL_TAC "sub") THENL
   [REWRITE_TAC[HOLDS_SUBSET_FORM] THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `holds D E ((40 |-> (e:A)) v)
      (!! 42 ((permom_form 42 iom && fixes_form 42 40)
              --> symfix_form 42 iP ix)) <=>
    (!s. s IN D /\ eperm D E (v iom) s /\ efixes D E s e
         ==> ?autB. autB IN D /\
               (?muci muP. muci IN D /\ muP IN D /\
                  (!u w. u IN D /\ w IN D
                         ==> (eapply D E muci u w <=>
                              E u (v iP) /\ mucirel D E s u w)) /\
                  (!p q. p IN D /\ q IN D
                         ==> (eapply D E muP p q <=>
                              E p (v iP) /\ muPrel D E muci p q)) /\
                  (!b c. b IN D /\ c IN D
                         ==> (eapply D E autB b c <=>
                              E b (v 2) /\ muPrel D E muP b c))) /\
               eautn D E (v 2) autB (v ix) (v ix))`
  (LABEL_TAC "fa") THENL
   [REWRITE_TAC[HOLDS_ALL] THEN
    MATCH_MP_TAC(MESON[]
     `(!s:A. s IN D ==> (R s <=> (B s /\ C s ==> G s)))
      ==> ((!s. s IN D ==> R s) <=> (!s. s IN D /\ B s /\ C s ==> G s))`) THEN
    X_GEN_TAC `s:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `valuation D ((42 |-> (s:A)) ((40 |-> (e:A)) v))`
    ASSUME_TAC THENL [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
        (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC)); ALL_TAC] THEN
    REWRITE_TAC[HOLDS_IMP; HOLDS_AND] THEN
    SUBGOAL_THEN
     `holds D E ((42 |-> (s:A)) ((40 |-> (e:A)) v)) (permom_form 42 iom) <=>
      eperm D E (v iom) s` SUBST1_TAC THENL
     [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`;
        `(42 |-> (s:A)) ((40 |-> (e:A)) v)`; `42`; `iom:num`]
        HOLDS_PERMOM_FORM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[];
                      DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `holds D E ((42 |-> (s:A)) ((40 |-> (e:A)) v)) (fixes_form 42 40) <=>
      efixes D E s e` SUBST1_TAC THENL
     [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`;
        `(42 |-> (s:A)) ((40 |-> (e:A)) v)`; `42`; `40`]
        HOLDS_FIXES_FORM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[];
                      DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `holds D E ((42 |-> (s:A)) ((40 |-> (e:A)) v)) (symfix_form 42 iP ix) <=>
      (?autB. autB IN D /\
          (?muci muP. muci IN D /\ muP IN D /\
             (!u w. u IN D /\ w IN D
                    ==> (eapply D E muci u w <=>
                         E u (v iP) /\ mucirel D E s u w)) /\
             (!p q. p IN D /\ q IN D
                    ==> (eapply D E muP p q <=>
                         E p (v iP) /\ muPrel D E muci p q)) /\
             (!b c. b IN D /\ c IN D
                    ==> (eapply D E autB b c <=>
                         E b (v 2) /\ muPrel D E muP b c))) /\
          eautn D E (v 2) autB (v ix) (v ix))` SUBST1_TAC THENL
     [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`;
        `(42 |-> (s:A)) ((40 |-> (e:A)) v)`; `42`; `iP:num`; `ix:num`]
        HOLDS_SYMFIX) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
        DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER];
      ALL_TAC] THEN
    REFL_TAC;
    ALL_TAC] THEN
  USE_THEN "fin" (fun a -> USE_THEN "sub" (fun b -> USE_THEN "fa" (fun c ->
    REWRITE_TAC[a; b; c]))));;

let hs_step_form = new_definition
  `hs_step_form =
     ?? 3 ((!! 4 (4 %% 3 <-> ranmem_form 4 0)) &&
           (!! 4 (4 %% 1 <-> (bnmem_form 4 3 2 && hssym_form 4 8 9))))`;;

(* ---- the autN recursor's FV, bounded to a concrete literal set ---- *)
let FV_REC_AUTN_SUB = prove
 (`FV(rec_form autn_step_form 4) SUBSET {2,3,4,5}`,
  MP_TAC(SPECL [`autn_step_form`; `4`] FV_REC_FORM_SUB) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL [ARITH_TAC; ACCEPT_TAC FVLT_AUTN_STEP_FORM]; ALL_TAC] THEN
  MP_TAC FV_AUTN_STEP_FORM_SUB THEN
  REWRITE_TAC[ARITH_RULE `4 + 1 = 5`] THEN
  SET_TAC[]);;

let FV_RECAPP45_AUTN = prove
 (`FV(recapp45_form (rec_form autn_step_form 4) 30 31) SUBSET {2,3,30,31}`,
  MP_TAC FV_REC_AUTN_SUB THEN
  REWRITE_TAC[recapp45_form; FV; FV_CLAUSES] THEN
  SET_TAC[]);;

(* ---- fully-concrete leaves (ground MAX reduced) : ARITH_TAC ---- *)
let FV_FINITE_40_8 = prove
 (`FV(finite_form 40 8) SUBSET {8,40}`,
  REWRITE_TAC[finite_form; ARITH_RULE `MAX 40 8 + 1 = 41`; bijform;
              ARITH_RULE `MAX 41 40 = 41`;
              FV; FV_CLAUSES; FV_APPLY_FORM] THEN
  REWRITE_TAC[SUBSET; IN_DELETE; IN_UNION; IN_INSERT; NOT_IN_EMPTY] THEN
  ARITH_TAC);;

let FV_PERMOM_42_8 = prove
 (`FV(permom_form 42 8) SUBSET {8,42}`,
  REWRITE_TAC[permom_form; bijfun_form;
              ARITH_RULE `MAX 8 8 = 8`; ARITH_RULE `MAX 42 8 = 42`;
              FV; FV_CLAUSES; FV_APPLY_FORM] THEN
  REWRITE_TAC[SUBSET; IN_DELETE; IN_UNION; IN_INSERT; NOT_IN_EMPTY] THEN
  ARITH_TAC);;

let FV_FIXES_42_40 = prove
 (`FV(fixes_form 42 40) SUBSET {40,42}`,
  REWRITE_TAC[fixes_form; ARITH_RULE `MAX 42 40 + 1 = 43`;
              FV; FV_CLAUSES; FV_APPLY_FORM] THEN
  REWRITE_TAC[SUBSET; IN_DELETE; IN_UNION; IN_INSERT; NOT_IN_EMPTY] THEN
  ARITH_TAC);;

(* ---- autb_of at concrete args : ground set-algebra (ARITH blows up on
       the fully-unfolded literal structure) : SET_TAC.  Deleted-literal
       branches self-contradict; target-literal branches close by
       reflexivity -- no literal distinctness needed. ---- *)
let FV_AUTB_42_9_2_3 = prove
 (`FV(autb_of_form 42 9 2 3) SUBSET {2,3,9,42}`,
  REWRITE_TAC[autb_of_form; mucifun_form; imgfun_form; recapp012_form;
              permci_form; FV; FV_CLAUSES; FV_APPLY_FORM; FV_OPAIR_FORM] THEN
  SET_TAC[]);;

(* ---- composition lemmas : opaque sub-FVs bounded by MP'd hyps : SET_TAC *)
(* ----                                                                    *)
let FV_SYMFIX_42_9_4 = prove
 (`FV(symfix_form 42 9 4) SUBSET {2,4,9,42}`,
  MP_TAC FV_AUTB_42_9_2_3 THEN MP_TAC FV_RECAPP45_AUTN THEN
  REWRITE_TAC[symfix_form; FV; FV_CLAUSES; FV_ORDINAL_FORM; FV_OPAIR_FORM] THEN
  SET_TAC[]);;

let FV_HSSYM_4_8_9 = prove
 (`FV(hssym_form 4 8 9) SUBSET {2,4,8,9}`,
  MP_TAC FV_FINITE_40_8 THEN MP_TAC FV_PERMOM_42_8 THEN
  MP_TAC FV_FIXES_42_40 THEN MP_TAC FV_SYMFIX_42_9_4 THEN
  REWRITE_TAC[hssym_form; FV; FV_CLAUSES; FV_SUBSET_FORM] THEN
  SET_TAC[]);;

let FV_HS_STEP_FORM_SUB = prove
 (`FV hs_step_form SUBSET {0,1,2,8,9}`,
  MP_TAC FV_HSSYM_4_8_9 THEN
  REWRITE_TAC[hs_step_form; FV; FV_CLAUSES; FV_RANMEM_FORM; FV_BNMEM_FORM] THEN
  SET_TAC[]);;

let FVLT_HS_STEP_FORM = prove
 (`!m. m IN FV hs_step_form /\ ~(m = 0) /\ ~(m = 1) ==> m = 2 \/
  m = 8 \/ m = 9`,
  GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(REWRITE_RULE[SUBSET] FV_HS_STEP_FORM_SUB) THEN
  DISCH_THEN(MP_TAC o SPEC `m:num`) THEN
  ASM_REWRITE_TAC[IN_INSERT; NOT_IN_EMPTY] THEN ASM_ARITH_TAC);;

(* ===================================================================== *)
(* S3-5b meta layer (group 1): the HS-function-set + the step relation.   *)
(*   ehssym  = HOLDS_HSSYM_FORM's RHS as a semantic predicate (nm = the    *)
(*             candidate name; B at slot 2, om, P).                        *)
(*   ehsmem  = ebnmem (partial fn w->B) AND hereditarily symmetric.        *)
(*   ehsfuns = the set of all such names (mirror ebnfuns).                 *)
(*   hsstep  = the erec step (mirror bnstep): w = range-union of g, then   *)
(*             y = ehsfuns over w.                                         *)
(* ===================================================================== *)

let ehssym = new_definition
 `ehssym D (E:A->A->bool) B om P nm <=>
    ?e. e IN D /\
        (?n. n IN D /\ E n om /\ ?f. ebij D E f n e) /\
        esubset D E e om /\
        (!s. s IN D /\ eperm D E om s /\ efixes D E s e
             ==> ?autB. autB IN D /\
                   (?muci muP. muci IN D /\ muP IN D /\
                      (!u w. u IN D /\ w IN D
                             ==> (eapply D E muci u w <=>
                                  E u P /\ mucirel D E s u w)) /\
                      (!p q. p IN D /\ q IN D
                             ==> (eapply D E muP p q <=>
                                  E p P /\ muPrel D E muci p q)) /\
                      (!b c. b IN D /\ c IN D
                             ==> (eapply D E autB b c <=>
                                  E b B /\ muPrel D E muP b c))) /\
                   eautn D E B autB nm nm)`;;

let ehsmem = new_definition
 `ehsmem D (E:A->A->bool) B om P w f <=>
    ebnmem D E B w f /\ ehssym D E B om P f`;;

let ehsfuns = new_definition
 `ehsfuns D (E:A->A->bool) B om P w y <=>
    y IN D /\ !f. f IN D ==> (E f y <=> ehsmem D E B om P w f)`;;

let EHSFUNS_IN = prove
 (`!D (E:A->A->bool) B om P w y. ehsfuns D E B om P w y ==> y IN D`,
  SIMP_TAC[ehsfuns]);;

let EHSFUNS_UNIQUE = prove
 (`!D (E:A->A->bool) B om P w y y'.
        model D E ZF_AX /\ ehsfuns D E B om P w y /\ ehsfuns D E B om P w y'
        ==> y = y'`,
  REWRITE_TAC[ehsfuns] THEN REPEAT STRIP_TAC THEN
  FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
  ASM_SIMP_TAC[]);;

(* ---- the key existence step: separation {f IN pow(w x B) | fun /\ hssym} *)
(* ----                                                                     *)
let EHSFUNS_EXISTS = prove
 (`!D (E:A->A->bool) B om P w.
        model D E ZF_AX /\ B IN D /\ om IN D /\ P IN D /\ w IN D
        ==> ?y. ehsfuns D E B om P w y`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `w:A`; `B:A`] ECROSS_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `cr:A`) THEN
  SUBGOAL_THEN `(cr:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ecross]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `cr:A`] EPOW_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `pc:A`) THEN
  SUBGOAL_THEN `(pc:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EPOW_IN]; ALL_TAC] THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v00:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  ABBREV_TAC `v0 = (9 |-> (P:A)) ((8 |-> (om:A)) ((2 |-> (B:A)) v00))` THEN
  SUBGOAL_THEN
   `valuation D (v0:num->A) /\ (v0:num->A) 2 = B /\ v0 8 = om /\ v0 9 = P`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "v0" THEN REPEAT CONJ_TAC THENL
     [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
             (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC));
      SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE `~(9=2) /\ ~(8=2)`];
      SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE `~(9=8)`];
      REWRITE_TAC[VALMOD_BASIC]];
    ALL_TAC] THEN
  FIRST_ASSUM(MP_TAC o SPECL
    [`fun_form 0 && hssym_form 0 8 9`; `0`; `v0:num->A`; `pc:A`] o
    MATCH_MP ZF_SEPARATION) THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `y:A` THEN STRIP_TAC THEN
  ASM_REWRITE_TAC[ehsfuns] THEN X_GEN_TAC `f:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `valuation D ((0 |-> (f:A)) v0)` ASSUME_TAC THENL
   [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
           (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC)); ALL_TAC] THEN
  ASM_SIMP_TAC[] THEN
  REWRITE_TAC[HOLDS_AND] THEN
  SUBGOAL_THEN
   `holds D E ((0 |-> (f:A)) v0) (fun_form 0) <=> eisfun D E f`
  SUBST1_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(0 |-> (f:A)) v0`; `0`]
          HOLDS_FUN_FORM) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `holds D E ((0 |-> (f:A)) v0) (hssym_form 0 8 9) <=> ehssym D E B om P f`
  SUBST1_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(0 |-> (f:A)) v0`;
                  `0`; `8`; `9`] HOLDS_HSSYM_FORM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN CONV_TAC NUM_REDUCE_CONV; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[ehssym] THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER;
      ARITH_RULE `~(0=2) /\ ~(0=8) /\ ~(0=9)`];
    ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) f pc <=> esubset D E f cr`
  SUBST1_TAC THENL
   [ASM_MESON_TAC[epow]; ALL_TAC] THEN
  REWRITE_TAC[ehsmem; ebnmem] THEN
  EQ_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[] THENL
   [EXISTS_TAC `cr:A` THEN ASM_REWRITE_TAC[];
    SUBGOAL_THEN `cr':A = cr` (fun th -> ASM_MESON_TAC[th]) THEN
    ASM_MESON_TAC[ECROSS_UNIQUE]]);;

(* ---- the step relation (mirror bnstep) ---- *)
let hsstep = new_definition
 `hsstep D (E:A->A->bool) B om P g y <=>
    ?w. w IN D /\ eranu D E g w /\ ehsfuns D E B om P w y`;;

let HSSTEP_FUN = prove
 (`!D (E:A->A->bool) B om P g y y'.
        model D E ZF_AX /\ hsstep D E B om P g y /\ hsstep D E B om P g y'
        ==> y = y'`,
  REWRITE_TAC[hsstep] THEN REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `w:A = w'` SUBST_ALL_TAC THENL
   [ASM_MESON_TAC[ERANU_UNIQUE]; ALL_TAC] THEN
  ASM_MESON_TAC[EHSFUNS_UNIQUE]);;

let HSSTEP_TOTAL = prove
 (`!D (E:A->A->bool) B om P g.
      model D E ZF_AX /\ B IN D /\ om IN D /\ P IN D /\ g IN D
      ==> ?y. hsstep D E B om P g y`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[hsstep] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `g:A`] ERANU_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `w:A`) THEN
  SUBGOAL_THEN `(w:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[eranu]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `om:A`; `P:A`; `w:A`]
        EHSFUNS_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]);;

(* ===================================================================== *)
(* S3-5b group 2 : HOLDS_HS_STEP_FORM (mirror HOLDS_BNAME_STEP_FORM).      *)
(*   Difference: the inner body is (bnmem_form 4 3 2 && hssym_form 4 8 9),  *)
(*   so the top HOLDS_AND splits it -> the "piles" lemma carries THREE      *)
(*   clauses (ranmem / bnmem / hssym) and the main body folds              *)
(*   ehsmem = ebnmem /\ ehssym.  The hssym clause is proved exactly as in   *)
(*   EHSFUNS_EXISTS (HOLDS_HSSYM_FORM at ix=4,iom=8,iP=9, numerals true).   *)
(* ===================================================================== *)

let HOLDS_HS_STEP_FORM = prove
 (`!D (E:A->A->bool) v g y.
      model D E ZF_AX /\ valuation D v /\ g IN D /\ y IN D
      ==> (holds D E ((1 |-> y) ((0 |-> g) v)) hs_step_form <=>
           hsstep D E (v 2) (v 8) (v 9) g y)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[hs_step_form; holds; HOLDS_IFF; HOLDS_EX; HOLDS_AND;
              hsstep] THEN
  SUBGOAL_THEN
   `!w u:A. w IN D /\ u IN D
      ==> (holds D E
            ((4 |-> u) ((3 |-> w) ((1 |-> y) ((0 |-> g) v))))
            (ranmem_form 4 0) <=>
           eranmem D E u g) /\
          (holds D E
            ((4 |-> u) ((3 |-> w) ((1 |-> y) ((0 |-> g) v))))
            (bnmem_form 4 3 2) <=>
           ebnmem D E (v 2) w u) /\
          (holds D E
            ((4 |-> u) ((3 |-> w) ((1 |-> y) ((0 |-> g) v))))
            (hssym_form 4 8 9) <=>
           ehssym D E (v 2) (v 8) (v 9) u)`
  (LABEL_TAC "piles") THENL
   [REPEAT GEN_TAC THEN DISCH_TAC THEN
    SUBGOAL_THEN
     `valuation D
       ((4 |-> (u:A)) ((3 |-> w) ((1 |-> y) ((0 |-> g) v))))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    REPEAT CONJ_TAC THENL
     [ASM_SIMP_TAC[HOLDS_RANMEM_FORM] THEN
      REWRITE_TAC[VALMOD; ARITH_EQ];
      ASM_SIMP_TAC[HOLDS_BNMEM_FORM] THEN
      REWRITE_TAC[VALMOD; ARITH_EQ];
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
                    `(4 |-> (u:A)) ((3 |-> w) ((1 |-> y) ((0 |-> g) v)))`;
                    `4`; `8`; `9`] HOLDS_HSSYM_FORM) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN CONV_TAC NUM_REDUCE_CONV; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[ehssym; VALMOD; ARITH_EQ]];
    ALL_TAC] THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN
  MATCH_MP_TAC(MESON[]
    `(!w:A. w IN D ==> (P w <=> Q w))
     ==> ((?w. w IN D /\ P w) <=> (?w. w IN D /\ Q w))`) THEN
  X_GEN_TAC `w:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN
   `(eranu D (E:A->A->bool) g w <=>
     !u. u IN D ==> (E u w <=> eranmem D E u g)) /\
    (ehsfuns D (E:A->A->bool) (v 2) (v 8) (v 9) w y <=>
     !u. u IN D ==> (E u y <=> ehsmem D E (v 2) (v 8) (v 9) w u))`
  (fun th -> REWRITE_TAC[th]) THENL
   [ASM_REWRITE_TAC[eranu; ehsfuns]; ALL_TAC] THEN
  MATCH_MP_TAC(TAUT
    `(a <=> a') /\ (b <=> b') ==> ((a /\ b) <=> (a' /\ b'))`) THEN
  CONJ_TAC THEN
  (MATCH_MP_TAC(MESON[]
    `(!u:A. u IN D ==> (P u <=> Q u))
     ==> ((!u. u IN D ==> P u) <=> (!u. u IN D ==> Q u))`) THEN
   X_GEN_TAC `u:A` THEN DISCH_TAC THEN
   USE_THEN "piles" (fun th -> MP_TAC(SPECL [`w:A`; `u:A`] th)) THEN
   ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
   DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
   REWRITE_TAC[ehsmem; VALMOD; ARITH_EQ]));;

(* ===================================================================== *)
(* S3-5b group 3 : QFUN/QTOTAL for the step, then the hsstage recursion    *)
(*   layer (hsstage + EREC/UNIQUE/EXISTS), mirror BNSTEP_Q* / EBNSTAGE_*.   *)
(*   Three params threaded through valuation slots 2 (B), 8 (om), 9 (P);    *)
(*   FVLT_HS_STEP_FORM gives the slot case m=2\/m=8\/m=9 for EREC_VALUATION.*)
(* ===================================================================== *)

let HSSTEP_QFUN = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> !r w w'. r IN D /\ w IN D /\ w' IN D /\
                     holds D E ((1 |-> w) ((0 |-> r) v)) hs_step_form /\
                     holds D E ((1 |-> w') ((0 |-> r) v)) hs_step_form
                     ==> w = w'`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN REPEAT GEN_TAC THEN STRIP_TAC THEN
  MATCH_MP_TAC HSSTEP_FUN THEN
  MAP_EVERY EXISTS_TAC
    [`D:A->bool`; `E:A->A->bool`; `(v:num->A) 2`; `(v:num->A) 8`;
     `(v:num->A) 9`; `r:A`] THEN
  ASM_MESON_TAC[HOLDS_HS_STEP_FORM]);;

let HSSTEP_QTOTAL = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> !x. x IN D
                ==> ?y. y IN D /\
                        holds D E ((1 |-> y) ((0 |-> x) v)) hs_step_form`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(v:num->A) 2 IN D /\ (v:num->A) 8 IN D /\ (v:num->A) 9 IN D`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(v:num->A) 2`; `(v:num->A) 8`;
                `(v:num->A) 9`; `x:A`] HSSTEP_TOTAL) THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `y:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `(y:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[hsstep; EHSFUNS_IN]; ALL_TAC] THEN
  ASM_MESON_TAC[HOLDS_HS_STEP_FORM]);;

(* ---- hsstage: erec over the HS step, B/om/P threaded through 2/8/9 ---- *)
let hsstage = new_definition
  `hsstage D (E:A->A->bool) B om P a y <=>
        ?v. valuation D v /\ v 2 = B /\ v 8 = om /\ v 9 = P /\
            erec D E hs_step_form v a y`;;

let HSSTAGE_EREC = prove
 (`!D (E:A->A->bool) B om P a y v.
        model D E ZF_AX /\ valuation D v /\ v 2 = B /\ v 8 = om /\ v 9 = P
        ==> (hsstage D E B om P a y <=> erec D E hs_step_form v a y)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[hsstage] THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `v':num->A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN
     `erec D (E:A->A->bool) hs_step_form v' a y <=>
      erec D E hs_step_form v a y`
    (fun th -> ASM_MESON_TAC[th]) THEN
    MATCH_MP_TAC EREC_VALUATION THEN
    X_GEN_TAC `m:num` THEN STRIP_TAC THEN
    MP_TAC(SPEC `m:num` FVLT_HS_STEP_FORM) THEN
    ASM_REWRITE_TAC[] THEN STRIP_TAC THEN ASM_MESON_TAC[];
    ASM_MESON_TAC[]]);;

let HSSTAGE_UNIQUE = prove
 (`!D (E:A->A->bool) B om P a y y'.
        model D E ZF_AX /\ B IN D /\ om IN D /\ P IN D /\ a IN D /\
        y IN D /\ y' IN D /\
        hsstage D E B om P a y /\ hsstage D E B om P a y'
        ==> y = y'`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v0:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  ABBREV_TAC `v = (9 |-> (P:A)) ((8 |-> (om:A)) ((2 |-> (B:A)) v0))` THEN
  SUBGOAL_THEN
   `valuation D (v:num->A) /\ (v:num->A) 2 = B /\ v 8 = om /\ v 9 = P`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "v" THEN REPEAT CONJ_TAC THENL
     [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
             (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC));
      SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE `~(9=2) /\ ~(8=2)`];
      SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE `~(9=8)`];
      REWRITE_TAC[VALMOD_BASIC]];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `hs_step_form`; `v:num->A`;
                `a:A`; `y:A`; `y':A`] EREC_UNIQUE) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`] HSSTEP_QFUN) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN ASM_REWRITE_TAC[] THEN
  ASM_MESON_TAC[HSSTAGE_EREC]);;

let HSSTAGE_EXISTS = prove
 (`!D (E:A->A->bool) B om P a.
        model D E ZF_AX /\ B IN D /\ om IN D /\ P IN D /\ eordinal D E a
        ==> ?y. y IN D /\ hsstage D E B om P a y`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v0:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  ABBREV_TAC `v = (9 |-> (P:A)) ((8 |-> (om:A)) ((2 |-> (B:A)) v0))` THEN
  SUBGOAL_THEN
   `valuation D (v:num->A) /\ (v:num->A) 2 = B /\ v 8 = om /\ v 9 = P`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "v" THEN REPEAT CONJ_TAC THENL
     [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
             (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC));
      SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE `~(9=2) /\ ~(8=2)`];
      SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE `~(9=8)`];
      REWRITE_TAC[VALMOD_BASIC]];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `hs_step_form`; `v:num->A`;
                `a:A`] EREC_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN ANTS_TAC THENL
   [ASM_MESON_TAC[HSSTEP_QFUN; HSSTEP_QTOTAL]; ALL_TAC] THEN
  MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `y:A` THEN STRIP_TAC THEN
  ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[HSSTAGE_EREC]);;

(* ===================================================================== *)
(* S3-5e : HSSTAGE_CHAR (mirror EBNSTAGE_CHAR) -- the stage-union reader   *)
(*   needed by the S3-6 hsname class (cumulativity / directedness).        *)
(* ===================================================================== *)

let HSSTAGE_CHAR = prove
 (`!D (E:A->A->bool) B om P a y.
      model D E ZF_AX /\ B IN D /\ om IN D /\ P IN D /\ eordinal D E a /\
      y IN D /\ hsstage D E B om P a y
      ==> ?w. w IN D /\
              (!u. u IN D
                   ==> (E u w <=>
                        ?b z. b IN D /\ z IN D /\ E b a /\
                              hsstage D E B om P b z /\ E u z)) /\
              ehsfuns D E B om P w y`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(a:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v0:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  ABBREV_TAC `v = (9 |-> (P:A)) ((8 |-> (om:A)) ((2 |-> (B:A)) v0))` THEN
  SUBGOAL_THEN
   `valuation D (v:num->A) /\ (v:num->A) 2 = B /\ v 8 = om /\ v 9 = P`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "v" THEN REPEAT CONJ_TAC THENL
     [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
             (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC));
      SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE `~(9=2) /\ ~(8=2)`];
      SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE `~(9=8)`];
      REWRITE_TAC[VALMOD_BASIC]];
    ALL_TAC] THEN
  SUBGOAL_THEN `?r:A. erecres D (E:A->A->bool) hs_step_form v a r`
  STRIP_ASSUME_TAC THENL
   [MATCH_MP_TAC ERECRES_EXISTS THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[HSSTEP_QFUN; HSSTEP_QTOTAL];
    ALL_TAC] THEN
  SUBGOAL_THEN `(r:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[erecres]; ALL_TAC] THEN
  SUBGOAL_THEN `hsstep D (E:A->A->bool) B om P r y` MP_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `r:A`; `y:A`]
          HOLDS_HS_STEP_FORM) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
    MATCH_MP_TAC EREC_EQUATION THEN
    EXISTS_TAC `a:A` THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[HSSTEP_QFUN; HSSTAGE_EREC];
    ALL_TAC] THEN
  REWRITE_TAC[hsstep] THEN
  MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `w:A` THEN STRIP_TAC THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN
   `!b z:A. erec D (E:A->A->bool) hs_step_form v b z <=>
            hsstage D E B om P b z`
  (LABEL_TAC "conv") THENL
   [ASM_MESON_TAC[HSSTAGE_EREC]; ALL_TAC] THEN
  X_GEN_TAC `u:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `(E:A->A->bool) u w <=> eranmem D E u r`
  (fun th -> REWRITE_TAC[th]) THENL
   [ASM_MESON_TAC[eranu]; ALL_TAC] THEN
  REWRITE_TAC[eranmem] THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `vl:A` (X_CHOOSE_THEN `pr:A`
      (X_CHOOSE_THEN `ord:A`
        (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th))))) THEN
    SUBGOAL_THEN
     `?b z:A. b IN D /\ z IN D /\ E b a /\
              erec D (E:A->A->bool) hs_step_form v b z /\
              eopair D E b z pr`
    STRIP_ASSUME_TAC THENL
     [FIRST_ASSUM(MP_TAC o SPEC `pr:A` o CONJUNCT2 o
        GEN_REWRITE_RULE I [erecres]) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `ord:A = b /\ vl:A = z` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_INJ]; ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`b:A`; `z:A`] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `z:A`
      (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th)))) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `b:A`; `z:A`]
          EOPAIR_EXISTS) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `pr:A`) THEN
    SUBGOAL_THEN `(pr:A) IN D` ASSUME_TAC THENL
     [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`z:A`; `pr:A`; `b:A`] THEN
    ASM_REWRITE_TAC[] THEN
    FIRST_ASSUM(MP_TAC o SPEC `pr:A` o CONJUNCT2 o
      GEN_REWRITE_RULE I [erecres]) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_MESON_TAC[]]);;

(* ===================================================================== *)
(* S3-6 : the hsname class (mirror of the bname class, godel_forcing.ml)   *)
(* + the hsname_form object-formula layer (mirror bname_form).              *)
(*   ECROSS_MONO_SUBSET is generic (reused from Part 2, not redefined).     *)
(* ===================================================================== *)

let hsname = new_definition
  `hsname D (E:A->A->bool) B om P u <=>
        ?a y. a IN D /\ y IN D /\ eordinal D E a /\
              hsstage D E B om P a y /\ E u y`;;

let HSNAME_STAGE = prove
 (`!D (E:A->A->bool) B om P a y u.
        a IN D /\ y IN D /\ eordinal D E a /\ hsstage D E B om P a y /\ E u y
        ==> hsname D E B om P u`,
  REWRITE_TAC[hsname] THEN MESON_TAC[]);;

(* Cumulativity: a member of the earlier HS stage (b < a) is a member of    *)
(* the later HS stage.  Mirror EBNSTAGE_MONO: stage-union w_b SUBSET w_a by  *)
(* ordinal transitivity -> cross w_b B SUBSET cross w_a B.  The symmetry     *)
(* conjunct of ehsmem is w-independent, so it transfers unchanged; only the  *)
(* ebnmem (partial-function) conjunct must be re-based onto w_a.             *)

let EHSSTAGE_MONO = prove
 (`!D (E:A->A->bool) B om P a b ya yb u.
        model D E ZF_AX /\ B IN D /\ om IN D /\ P IN D /\
        eordinal D E a /\ E b a /\ b IN D /\
        ya IN D /\ yb IN D /\
        hsstage D E B om P a ya /\ hsstage D E B om P b yb /\
        u IN D /\ E u yb
        ==> E u ya`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) b` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `om:A`; `P:A`;
                `a:A`; `ya:A`] HSSTAGE_CHAR) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `wa:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 (LABEL_TAC "wa") ASSUME_TAC))) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `om:A`; `P:A`;
                `b:A`; `yb:A`] HSSTAGE_CHAR) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `wb:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 (LABEL_TAC "wb") ASSUME_TAC))) THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) wb wa` ASSUME_TAC THENL
   [REWRITE_TAC[esubset] THEN ASM_MESON_TAC[EORDINAL_TRANS_MEM];
    ALL_TAC] THEN
  SUBGOAL_THEN `ehsmem D (E:A->A->bool) B om P wb u` MP_TAC THENL
   [UNDISCH_TAC `ehsfuns D (E:A->A->bool) B om P wb yb` THEN
    REWRITE_TAC[ehsfuns] THEN STRIP_TAC THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[ehsmem] THEN STRIP_TAC THEN
  UNDISCH_TAC `ebnmem D (E:A->A->bool) B wb u` THEN
  REWRITE_TAC[ebnmem] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (X_CHOOSE_THEN `cr:A`
    (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th)))) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `wa:A`; `B:A`] ECROSS_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `cr':A`) THEN
  SUBGOAL_THEN `(cr':A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ecross]; ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) cr cr'` ASSUME_TAC THENL
   [MATCH_MP_TAC ECROSS_MONO_SUBSET THEN
    MAP_EVERY EXISTS_TAC [`wb:A`; `wa:A`; `B:A`] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  UNDISCH_TAC `ehsfuns D (E:A->A->bool) B om P wa ya` THEN
  REWRITE_TAC[ehsfuns] THEN
  DISCH_THEN(MP_TAC o SPEC `u:A` o CONJUNCT2) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[ehsmem; ebnmem] THEN ASM_REWRITE_TAC[] THEN
  EXISTS_TAC `cr':A` THEN ASM_REWRITE_TAC[] THEN
  ASM_MESON_TAC[esubset]);;

let FVLT10_HS_STEP_FORM = prove
 (`!m. m IN FV hs_step_form ==> m < 10`,
  GEN_TAC THEN DISCH_TAC THEN
  MP_TAC(SPEC `m:num` (REWRITE_RULE[SUBSET] FV_HS_STEP_FORM_SUB)) THEN
  ASM_REWRITE_TAC[IN_INSERT; NOT_IN_EMPTY] THEN ARITH_TAC);;

(* High-slot recursion-application wrapper for N=10 : binds slots 10,11    *)
(* (the arg/value slots of rec_form _ 10), leaving params 2,8,9 untouched. *)
(* Verbatim clone of recapp3_form with 3,4 -> 10,11.                       *)
let recapp10_form = new_definition
  `recapp10_form q i j = !! 10 (!! 11 ((Eq 10 i && Eq 11 j) --> q))`;;

let HOLDS_RECAPP10_FORM = prove
 (`!D (E:A->A->bool) v q i j.
        valuation D v /\ ~(i = 10) /\ ~(i = 11) /\ ~(j = 10) /\
        ~(j = 11)
        ==> (holds D E v (recapp10_form q i j) <=>
             holds D E ((11 |-> v j) ((10 |-> v i) v)) q)`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[recapp10_form; holds; HOLDS_AND] THEN
  ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE `~(10 = 11)`] THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  EQ_TAC THENL
   [DISCH_THEN(MP_TAC o SPEC `(v:num->A) i`) THEN ASM_SIMP_TAC[] THEN
    DISCH_THEN(MP_TAC o SPEC `(v:num->A) j`) THEN ASM_SIMP_TAC[];
    MESON_TAC[]]);;

(* Bridge: recapp10 of the HS recursion at slots i,j is hsstage at the     *)
(* params (v 2)(v 8)(v 9).  Mirror HOLDS_RECAPP3_BNSTEP.                    *)
let HOLDS_RECAPP10_HSSTEP = prove
 (`!D (E:A->A->bool) v i j.
        model D E ZF_AX /\ valuation D v /\
        ~(i = 10) /\ ~(i = 11) /\ ~(j = 10) /\ ~(j = 11)
        ==> (holds D E v (recapp10_form (rec_form hs_step_form 10) i j) <=>
             hsstage D E (v 2) (v 8) (v 9) (v i) (v j))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`;
                `rec_form hs_step_form 10`; `i:num`; `j:num`]
        HOLDS_RECAPP10_FORM) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`;
                `hs_step_form`; `10`; `(v:num->A) i`; `(v:num->A) j`]
        HOLDS_REC_FORM) THEN
  ASM_REWRITE_TAC[FVLT10_HS_STEP_FORM; ARITH_RULE `1 < 10`;
                  ARITH_RULE `10 + 1 = 11`] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(v:num->A) 2`; `(v:num->A) 8`;
                `(v:num->A) 9`; `(v:num->A) i`; `(v:num->A) j`; `v:num->A`]
        HSSTAGE_EREC) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]));;

(* hsname as an object formula.  Mirror bname_form.                        *)
let hsname_form = new_definition
  `hsname_form k =
     ?? 30 (ordinal_form 30 &&
            ?? 31 (recapp10_form (rec_form hs_step_form 10) 30 31
                   && k %% 31))`;;

let HOLDS_HSNAME_FORM = prove
 (`!D (E:A->A->bool) v k.
        model D E ZF_AX /\ valuation D v /\ ~(k = 30) /\ ~(k = 31)
        ==> (holds D E v (hsname_form k) <=>
             hsname D E (v 2) (v 8) (v 9) (v k))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[hsname_form] THEN
  SUBGOAL_THEN
   `!a y:A. a IN D /\ y IN D
      ==> (holds D E ((31 |-> y) ((30 |-> a) v))
             (recapp10_form (rec_form hs_step_form 10) 30 31) <=>
           hsstage D E (v 2) (v 8) (v 9) a y)`
  (LABEL_TAC "rc") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((31 |-> (y:A)) ((30 |-> (a:A)) v))`
        ASSUME_TAC THENL
     [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
             (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC)); ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
                  `(31 |-> (y:A)) ((30 |-> (a:A)) v)`; `30`; `31`]
          HOLDS_RECAPP10_HSSTEP) THEN
    ASM_REWRITE_TAC[ARITH_RULE
      `~(30 = 10) /\ ~(30 = 11) /\ ~(31 = 10) /\ ~(31 = 11)`] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!a:A. a IN D
      ==> (holds D E ((30 |-> a) v)
             (ordinal_form 30 &&
              ?? 31 (recapp10_form (rec_form hs_step_form 10) 30 31
                     && k %% 31)) <=>
           eordinal D E a /\
           (?y. y IN D /\ hsstage D E (v 2) (v 8) (v 9) a y /\ E (v k) y))`
  (LABEL_TAC "step") THENL
   [X_GEN_TAC `a:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `valuation D ((30 |-> (a:A)) v)` ASSUME_TAC THENL
     [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
             (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC)); ALL_TAC] THEN
    REWRITE_TAC[HOLDS_AND] THEN
    ASM_SIMP_TAC[HOLDS_ORDINAL_FORM; VALMOD; ARITH_EQ] THEN
    MATCH_MP_TAC(TAUT `(y <=> z) ==> ((x /\ y) <=> (x /\ z))`) THEN
    REWRITE_TAC[HOLDS_EX; HOLDS_AND; holds] THEN
    MATCH_MP_TAC(MESON[]
      `(!y:A. y IN D ==> (P y <=> Q y))
       ==> ((?y. y IN D /\ P y) <=> (?y. y IN D /\ Q y))`) THEN
    X_GEN_TAC `y:A` THEN DISCH_TAC THEN
    USE_THEN "rc" (MP_TAC o SPECL [`a:A`; `y:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  REWRITE_TAC[hsname; HOLDS_EX] THEN
  MATCH_MP_TAC(MESON[]
   `(!a:A. a IN D ==> (P a <=> S a /\ (?y. y IN D /\ R a y)))
    ==> ((?a. a IN D /\ P a) <=>
         (?a y. a IN D /\ y IN D /\ S a /\ R a y))`) THEN
  USE_THEN "step" ACCEPT_TAC);;

(* ===================================================================== *)
(* S3-7 / 9a : autN fixes every check-name (steps 9a-0 .. 9a-4').         *)
(* autnfix_form/HOLDS_AUTNFIX_FORM (general ix) -> goodfix2/HOLDS_GOODFIX2 *)
(* -> GOODFIX2_SEM -> EAUTB_FIXES_TOP -> GOODFIX2_STEP -> EAUT_CHECK.      *)
(* ===================================================================== *)
let autnfix_form = new_definition
  `autnfix_form ix =
     ?? 30 (ordinal_form 30 &&
            ?? 31 (recapp45_form (rec_form autn_step_form 4) 30 31 &&
                   ?? 32 (opair_form ix ix 32 && (32 %% 31))))`;;

(* HOLDS_AUTNFIX_FORM: for general ix (disequalities, not ix<30) so that it *)
(* applies at ix=90 for goodfix.                                            *)
let HOLDS_AUTNFIX_FORM = prove
 (`!D (E:A->A->bool) v ix.
     model D E ZF_AX /\ valuation D v /\
     ~(ix = 30) /\ ~(ix = 31) /\ ~(ix = 32)
     ==> (holds D E v (autnfix_form ix) <=>
          eautn D E (v 2) (v 3) (v ix) (v ix))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[autnfix_form] THEN
  SUBGOAL_THEN `(v:num->A) ix IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `holds D (E:A->A->bool) v
      (?? 30 (ordinal_form 30 &&
              ?? 31 (recapp45_form (rec_form autn_step_form 4) 30 31 &&
                     ?? 32 (opair_form ix ix 32 && (32 %% 31))))) <=>
    (?a. a IN D /\ eordinal D E a /\
         (?c. c IN D /\ autnstage D E (v 2) (v 3) a c /\
              (?pp. pp IN D /\ eopair D E (v ix) (v ix) pp /\ E pp c)))`
   (fun th -> REWRITE_TAC[th]) THENL
   [REWRITE_TAC[HOLDS_EX] THEN
    MATCH_MP_TAC(MESON[]
      `(!a:A. a IN D ==> (P a <=> Q a))
       ==> ((?a. a IN D /\ P a) <=> (?a. a IN D /\ Q a))`) THEN
    X_GEN_TAC `a:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `valuation D ((30 |-> (a:A)) v)`
    ASSUME_TAC THENL [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
        (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC)); ALL_TAC] THEN
    REWRITE_TAC[HOLDS_AND] THEN
    SUBGOAL_THEN
     `holds D E ((30 |-> (a:A)) v) (ordinal_form 30) <=> eordinal D E a`
     (fun th -> REWRITE_TAC[th]) THENL
     [ASM_SIMP_TAC[HOLDS_ORDINAL_FORM] THEN REWRITE_TAC[VALMOD_BASIC];
      ALL_TAC] THEN
    MATCH_MP_TAC(TAUT `(b <=> b') ==> ((e /\ b) <=> (e /\ b'))`) THEN
    REWRITE_TAC[HOLDS_EX] THEN
    MATCH_MP_TAC(MESON[]
      `(!c:A. c IN D ==> (P c <=> Q c))
       ==> ((?c. c IN D /\ P c) <=> (?c. c IN D /\ Q c))`) THEN
    X_GEN_TAC `c:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN
     `valuation D ((31 |-> (c:A)) ((30 |-> (a:A)) v))`
    ASSUME_TAC THENL [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
        (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC)); ALL_TAC] THEN
    REWRITE_TAC[HOLDS_AND] THEN
    SUBGOAL_THEN
     `holds D E ((31 |-> (c:A)) ((30 |-> (a:A)) v))
        (recapp45_form (rec_form autn_step_form 4) 30 31) <=>
      autnstage D E (v 2) (v 3) a c`
     (fun th -> REWRITE_TAC[th]) THENL
     [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;
        `(31 |-> (c:A)) ((30 |-> (a:A)) v)`;`30`;`31`]
        HOLDS_RECAPP45_AUTNSTEP) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN ARITH_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER;
        ARITH_RULE `~(2 = 31) /\ ~(2 = 30) /\ ~(2 = 3) /\
                    ~(3 = 31) /\ ~(3 = 30) /\ ~(30 = 31)`];
      ALL_TAC] THEN
    MATCH_MP_TAC(TAUT `(b <=> b') ==> ((e /\ b) <=> (e /\ b'))`) THEN
    REWRITE_TAC[HOLDS_EX] THEN
    MATCH_MP_TAC(MESON[]
      `(!pp:A. pp IN D ==> (P pp <=> Q pp))
       ==> ((?pp. pp IN D /\ P pp) <=> (?pp. pp IN D /\ Q pp))`) THEN
    X_GEN_TAC `pp:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN
     `valuation D ((32 |-> (pp:A))
        ((31 |-> (c:A)) ((30 |-> (a:A)) v)))`
    ASSUME_TAC THENL [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
        (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC)); ALL_TAC] THEN
    REWRITE_TAC[HOLDS_AND] THEN
    SUBGOAL_THEN
     `holds D E ((32 |-> (pp:A))
        ((31 |-> (c:A)) ((30 |-> (a:A)) v)))
        (opair_form ix ix 32) <=> eopair D E (v ix) (v ix) pp`
     ASSUME_TAC THENL
     [ASM_SIMP_TAC[HOLDS_OPAIR_FORM] THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `holds D E ((32 |-> (pp:A))
        ((31 |-> (c:A)) ((30 |-> (a:A)) v))) (32 %% 31) <=> E (pp:A) c`
     ASSUME_TAC THENL
     [REWRITE_TAC[holds] THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE `~(31 = 32)`];
      ALL_TAC] THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[eautn] THEN ASM_REWRITE_TAC[] THEN MESON_TAC[]);;

(* ===================================================================== *)
(* S3-7 step 9a-1' : goodfix2 object formula + HOLDS_GOODFIX2 bridge.       *)
(* STAGE-FREE design: every pair <x,vv> in the check-stage cd_d (read via   *)
(* the resolvent graph rc at slot 81, apply_form 81 0 82) has its 2nd coord *)
(* vv FIXED by autN -- expressed directly as `autnfix_form 90` whose HOLDS   *)
(* reading is `eautn (v 2) (v 3) vv vv` (B at slot 2, autB at slot 3).       *)
(* Clone of HOLDS_GOODFIX with branch 2 swapped to HOLDS_AUTNFIX_FORM.       *)
(* ===================================================================== *)
let goodfix2 = new_definition
  `goodfix2 =
     ?? 82 (apply_form 81 0 82 &&
            !!- 88 82 (!! 89 (!! 90 (opair_form 89 90 88 -->
                autnfix_form 90))))`;;

let HOLDS_GOODFIX2 = prove
 (`!D (E:A->A->bool) v.
     model D E ZF_AX /\ valuation D v
     ==> (holds D E v goodfix2 <=>
          ?stg. stg IN D /\ eapply D E (v 81) (v 0) stg /\
                !pp. pp IN D /\ E pp stg
                     ==> !x vv. x IN D /\ vv IN D /\ eopair D E x vv pp
                                ==> eautn D E (v 2) (v 3) vv vv)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!n. (v:num->A) n IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[goodfix2; HOLDS_EX; HOLDS_AND] THEN
  MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s))
     ==> ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
  X_GEN_TAC `stg:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `valuation D ((82 |-> (stg:A)) v)` ASSUME_TAC THENL
   [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
           (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC)); ALL_TAC] THEN
  SUBGOAL_THEN
   `holds D E ((82 |-> (stg:A)) v) (apply_form 81 0 82) <=>
    eapply D E (v 81) (v 0) stg`
  (fun th -> REWRITE_TAC[th]) THENL
   [ASM_SIMP_TAC[HOLDS_APPLY_FORM] THEN
    REWRITE_TAC[VALMOD; ARITH_EQ]; ALL_TAC] THEN
  MATCH_MP_TAC(TAUT `(y <=> z) ==> ((x /\ y) <=> (x /\ z))`) THEN
  ASM_SIMP_TAC[HOLDS_FORALLMEM; ARITH_RULE `~(88 = 82)`] THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN
  MATCH_MP_TAC(MESON[]
    `(!pp:A. M pp ==> (P pp <=> Q pp))
     ==> ((!pp. M pp ==> P pp) <=> (!pp. M pp ==> Q pp))`) THEN
  X_GEN_TAC `pp:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((88 |-> (pp:A)) ((82 |-> (stg:A)) v))`
      ASSUME_TAC THENL
   [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
           (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC)); ALL_TAC] THEN
  REWRITE_TAC[holds] THEN
  MATCH_MP_TAC(MESON[]
    `(!x vv:A. x IN D /\ vv IN D ==> (H x vv <=> (R x vv ==> S vv)))
     ==> ((!x. x IN D ==> !vv. vv IN D ==> H x vv) <=>
          (!x vv. x IN D /\ vv IN D /\ R x vv ==> S vv))`) THEN
  MAP_EVERY X_GEN_TAC [`x:A`; `vv:A`] THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `valuation D ((90 |-> (vv:A)) ((89 |-> (x:A))
       ((88 |-> (pp:A)) ((82 |-> (stg:A)) v))))`
  ASSUME_TAC THENL [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
      (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC)); ALL_TAC] THEN
  MATCH_MP_TAC(TAUT `(a <=> c) /\ (b <=> d) ==> ((a ==> b) <=> (c ==> d))`) THEN
  CONJ_TAC THENL
   [ASM_SIMP_TAC[HOLDS_OPAIR_FORM] THEN REWRITE_TAC[VALMOD; ARITH_EQ];
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;
      `(90 |-> (vv:A)) ((89 |-> (x:A)) ((88 |-> (pp:A)) ((82 |-> (stg:A)) v)))`;
      `90`] HOLDS_AUTNFIX_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN ARITH_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD; ARITH_EQ]]);;

(* S3-7 step 9a-2' : GOODFIX2_SEM -- semantic reading of `holds goodfix2` at *)
(* index b, via the check-tower resolvent graph rc at slot 81. Stage-free: *)
(* the per-pair conclusion is `eautn (v0 2) (v0 3) vv vv` (B at slot 2, autB *)
(* at                                                                        *)
(* slot 3 of v0). Clone of GOODFIX_SEM with the slot-79 fixed-stage dropped. *)
let GOODFIX2_SEM = prove
 (`!D (E:A->A->bool) onebee sa rc v0 b.
      model D E ZF_AX /\ onebee IN D /\ eordinal D E sa /\
      rc IN D /\ valuation D v0 /\
      (!pp. pp IN D
            ==> (E pp rc <=>
                 ?b' z'. b' IN D /\ z' IN D /\ E b' sa /\
                         echecktower D E onebee b' z' /\
                             eopair D E b' z' pp)) /\
      b IN D /\ E b sa
      ==> (holds D E ((0 |-> b) ((81 |-> rc) v0)) goodfix2 <=>
           !zb pp x vv.
              zb IN D /\ pp IN D /\ x IN D /\ vv IN D /\
              echecktower D E onebee b zb /\ E pp zb /\ eopair D E x vv pp
              ==> eautn D E (v0 2) (v0 3) vv vv)`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 (LABEL_TAC "rcc")
        (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC))))))) THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) b` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((0 |-> (b:A)) ((81 |-> (rc:A)) v0))`
  ASSUME_TAC THENL [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
      (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC)); ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;
    `(0 |-> (b:A)) ((81 |-> (rc:A)) v0)`] HOLDS_GOODFIX2) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `stg:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "allp")))) THEN
    SUBGOAL_THEN `echecktower D (E:A->A->bool) onebee b stg` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;
        `echecktower D (E:A->A->bool) onebee`;`sa:A`;`rc:A`;`b:A`;`stg:A`]
        EGRAPH_APPLY) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> MP_TAC(EQ_MP th
        (ASSUME `eapply D (E:A->A->bool) rc b stg`))) THEN
      DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC ACCEPT_TAC);
      ALL_TAC] THEN
    MAP_EVERY X_GEN_TAC [`zb:A`;`pp:A`;`x:A`;`vv:A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN `zb:A = stg` SUBST_ALL_TAC THENL
     [ASM_MESON_TAC[ECHECKTOWER_UNIQUE]; ALL_TAC] THEN
    USE_THEN "allp" (MP_TAC o SPEC `pp:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPECL [`x:A`;`vv:A`]) THEN
    ASM_REWRITE_TAC[];
    DISCH_THEN(LABEL_TAC "sem") THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`b:A`]
      ECHECKTOWER_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `stgw:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `stgw:A` THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `eapply D (E:A->A->bool) rc b stgw` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;
        `echecktower D (E:A->A->bool) onebee`;`sa:A`;`rc:A`;`b:A`;`stgw:A`]
        EGRAPH_APPLY) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `pp:A` THEN STRIP_TAC THEN
    MAP_EVERY X_GEN_TAC [`x:A`;`vv:A`] THEN STRIP_TAC THEN
    USE_THEN "sem" (MP_TAC o SPECL [`stgw:A`;`pp:A`;`x:A`;`vv:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]]);;

(* S3-7 step 9a-2.6 : EAUTB_FIXES_TOP -- the c.b.a. automorphism autB fixes   *)
(* the top element onebee of (B,inclB). AUTB_IMG gives the image ui; *)
(* EAUTB_TOP shows ui is again a top; ETOP_UNIQUE (eporder) collapses *)
(* ui=onebee.                                                         *)
let EAUTB_FIXES_TOP = prove
 (`!D (E:A->A->bool) B inclB autB onebee.
      model D E ZF_AX /\ B IN D /\ autB IN D /\ onebee IN D /\ E onebee B /\
      ebij D E autB B B /\
      (!a b ai bi. a IN D /\ b IN D /\ ai IN D /\ bi IN D /\
                   eapply D E autB a ai /\ eapply D E autB b bi
                   ==> (erel D E inclB a b <=> erel D E inclB ai bi)) /\
      eporder D E B inclB /\ etop D E B inclB onebee
      ==> eapply D E autB onebee onebee`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;
                 `onebee:A`] AUTB_IMG) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ui:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `etop D (E:A->A->bool) B inclB ui` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`autB:A`;
                   `onebee:A`;`ui:A`] EAUTB_TOP) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `ui:A = onebee` SUBST_ALL_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`onebee:A`;`ui:A`]
      ETOP_UNIQUE) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(ACCEPT_TAC o SYM);
    ALL_TAC] THEN
  FIRST_ASSUM ACCEPT_TAC);;

(* ===================================================================== *)
(* S3-7 step 9a-3' : GOODFIX2_STEP -- the transfinite-induction step for    *)
(* "autN fixes every check-name".  Mirrors GOODCHECK_STEP's skeleton        *)
(* (ECHECK_STAGE + ECHECKTOWER_VALUE + EOPAIR_INJ + the imgch/gaccch CORE)  *)
(* but concludes `eautn B autB vv vv` for every pair <x,vv> in check-stage  *)
(* d.  CORE now yields, for each member z of vv, its 1st coordinate vy with  *)
(* vy fixed by autN (via the IH at the earlier stage).  TAIL: vv is a       *)
(* B-name (ECHECK_IS_BNAME) so autN(vv)=v' exists (AUTN_TOTAL); autB fixes   *)
(* onebee (EAUTB_FIXES_TOP); member-comparison via AUTN_MEM both ways gives  *)
(* v'=vv (ZF_EXTENSIONALITY); hence eautn B autB vv vv.  MESON-free.         *)
(* ===================================================================== *)
let GOODFIX2_STEP = prove
 (`!D (E:A->A->bool) onebee B inclB autB d.
      model D E ZF_AX /\ onebee IN D /\ B IN D /\ autB IN D /\ E onebee B /\
      ebij D E autB B B /\
      (!a b ai bi. a IN D /\ b IN D /\ ai IN D /\ bi IN D /\
                   eapply D E autB a ai /\ eapply D E autB b bi
                   ==> (erel D E inclB a b <=> erel D E inclB ai bi)) /\
      eporder D E B inclB /\ etop D E B inclB onebee /\
      eordinal D E d /\
      (!b'. b' IN D /\ E b' d
            ==> !zb pp x vv.
                   zb IN D /\ pp IN D /\ x IN D /\ vv IN D /\
                   echecktower D E onebee b' zb /\ E pp zb /\
                   eopair D E x vv pp
                   ==> eautn D E B autB vv vv)
      ==> !zd pp x vv.
             zd IN D /\ pp IN D /\ x IN D /\ vv IN D /\
             echecktower D E onebee d zd /\ E pp zd /\ eopair D E x vv pp
             ==> eautn D E B autB vv vv`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
    (CONJUNCTS_THEN2 (LABEL_TAC "oneD")
      (CONJUNCTS_THEN2 (LABEL_TAC "BD")
        (CONJUNCTS_THEN2 (LABEL_TAC "autBD")
          (CONJUNCTS_THEN2 (LABEL_TAC "oneB")
            (CONJUNCTS_THEN2 (LABEL_TAC "bij")
              (CONJUNCTS_THEN2 (LABEL_TAC "ord")
                (CONJUNCTS_THEN2 (LABEL_TAC "porder")
                  (CONJUNCTS_THEN2 (LABEL_TAC "top")
                    (CONJUNCTS_THEN2 (LABEL_TAC "dord")
                     (LABEL_TAC "IH"))))))))))) THEN
  (* single-valuedness of autB, extracted from ebij (4th conjunct) *)
  USE_THEN "bij" (LABEL_TAC "autBsv" o
    CONJUNCT1 o CONJUNCT2 o CONJUNCT2 o CONJUNCT2 o REWRITE_RULE[ebij]) THEN
  MAP_EVERY X_GEN_TAC [`zd:A`;`pp:A`;`x:A`;`vv:A`] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "zdD")
    (CONJUNCTS_THEN2 (LABEL_TAC "ppD")
      (CONJUNCTS_THEN2 (LABEL_TAC "xD")
        (CONJUNCTS_THEN2 (LABEL_TAC "vvD")
          (CONJUNCTS_THEN2 (LABEL_TAC "tow")
            (CONJUNCTS_THEN2 (LABEL_TAC "ppzd") (LABEL_TAC "pairp"))))))) THEN
  (* echeck onebee x vv (needed by ECHECK_IS_BNAME in the tail) *)
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`d:A`;`zd:A`;`x:A`;`vv:A`;
                `pp:A`] ECHECK_STAGE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(LABEL_TAC "chk") THEN
  (* expose the accumulator gacc and (pinned) image vv via ECHECKTOWER_VALUE *)
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`d:A`;`zd:A`;`pp:A`]
        ECHECKTOWER_VALUE) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `gacc:A` (X_CHOOSE_THEN `w:A`
    (X_CHOOSE_THEN `x2:A` (X_CHOOSE_THEN `img:A`
      (CONJUNCTS_THEN2 (LABEL_TAC "gaccD") (CONJUNCTS_THEN2 (LABEL_TAC "wD")
        (CONJUNCTS_THEN2 (LABEL_TAC "x2D") (CONJUNCTS_THEN2 (LABEL_TAC "imgD")
          (CONJUNCTS_THEN2 (LABEL_TAC "gaccch")
           (CONJUNCTS_THEN2 (LABEL_TAC "domn")
            (CONJUNCTS_THEN2 (LABEL_TAC "pairx")
             (CONJUNCTS_THEN2 (LABEL_TAC "subxw")
              (LABEL_TAC "imgch"))))))))))))) THEN
  SUBGOAL_THEN `x2:A = x /\ img:A = vv`
    (CONJUNCTS_THEN2 SUBST_ALL_TAC SUBST_ALL_TAC) THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`x2:A`;`img:A`;`x:A`;`vv:A`;`pp:A`]
      EOPAIR_INJ) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* CORE: every member z of vv is <vy,onebee> with vy fixed by autN (via IH) *)
  SUBGOAL_THEN
   `!z:A. z IN D /\ (E:A->A->bool) z vv
          ==> ?vy. vy IN D /\ eopair D E vy onebee z /\
                   eautn D E B autB vy vy`
  (LABEL_TAC "core") THENL
   [X_GEN_TAC `z:A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "zD") (LABEL_TAC "ezvv")) THEN
    USE_THEN "imgch" (MP_TAC o C MATCH_MP (ASSUME `(z:A) IN D`)) THEN
    REWRITE_TAC[ASSUME `(E:A->A->bool) z vv`] THEN
    DISCH_THEN(X_CHOOSE_THEN `y:A` (CONJUNCTS_THEN2 (LABEL_TAC "yD")
      (X_CHOOSE_THEN `vy:A` (fun th -> MAP_EVERY ASSUME_TAC
                             (CONJUNCTS th))))) THEN
    SUBGOAL_THEN `eautn D (E:A->A->bool) B autB vy vy` ASSUME_TAC THENL
     [UNDISCH_TAC `eapply D (E:A->A->bool) gacc y vy` THEN
      REWRITE_TAC[eapply] THEN
      DISCH_THEN(X_CHOOSE_THEN `p:A` (CONJUNCTS_THEN2 (LABEL_TAC "pairyp")
        (LABEL_TAC "pgacc"))) THEN
      SUBGOAL_THEN `(p:A) IN D` (LABEL_TAC "pD") THENL
       [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`y:A`;`vy:A`;`p:A`]
               EOPAIR_IN) THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      USE_THEN "gaccch" (MP_TAC o C MATCH_MP (ASSUME `(p:A) IN D`)) THEN
      REWRITE_TAC[ASSUME `(E:A->A->bool) p gacc`] THEN
      DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `zb:A`
        (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th)))) THEN
      USE_THEN "IH" (MP_TAC o SPEC `b:A`) THEN ANTS_TAC THENL
       [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(MP_TAC o SPECL [`zb:A`;`p:A`;`y:A`;`vy:A`]) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    EXISTS_TAC `vy:A` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* TAIL.  (1) vv is a B-name. *)
  SUBGOAL_THEN `bname D (E:A->A->bool) B vv` (LABEL_TAC "bnvv") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;`x:A`;`vv:A`]
      ECHECK_IS_BNAME) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
  (* (2) autB fixes onebee. *)
  SUBGOAL_THEN `eapply D (E:A->A->bool) autB onebee onebee`
      (LABEL_TAC "fixtop") THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;
                   `autB:A`;`onebee:A`]
      EAUTB_FIXES_TOP) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
  (* (3) autN(vv) exists, call it v'. *)
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`vv:A`]
         AUTN_TOTAL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `v':A` (CONJUNCTS_THEN2 (LABEL_TAC "v'D")
    (LABEL_TAC "autnvv"))) THEN
  (* (4) v' = vv by extensionality; then eautn B autB vv vv follows. *)
  SUBGOAL_THEN `(v':A) = vv` SUBST_ALL_TAC THENL
   [FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "v'D" ACCEPT_TAC; USE_THEN "vvD" ACCEPT_TAC; ALL_TAC] THEN
    X_GEN_TAC `z:A` THEN DISCH_TAC THEN EQ_TAC THENL
     [(* forward: E z v' ==> E z vv *)
      DISCH_TAC THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;
                    `vv:A`;`v':A`;`z:A`]
        AUTN_MEM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) z v'`))) THEN
      DISCH_THEN(X_CHOOSE_THEN `m:A` (X_CHOOSE_THEN `t:A` (X_CHOOSE_THEN `c:A`
        (X_CHOOSE_THEN `t':A` (X_CHOOSE_THEN `c':A`
          (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th))))))) THEN
      USE_THEN "core" (MP_TAC o SPEC `m:A`) THEN ANTS_TAC THENL
       [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `vy:A`
        (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th))) THEN
      SUBGOAL_THEN `t:A = vy /\ c:A = onebee`
        (CONJUNCTS_THEN2 SUBST_ALL_TAC SUBST_ALL_TAC) THENL
       [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`t:A`;`c:A`;`vy:A`;
                      `onebee:A`;`m:A`]
          EOPAIR_INJ) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `t':A = vy` SUBST_ALL_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;
                      `vy:A`;`t':A`;`vy:A`]
          AUTN_SV) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `c':A = onebee` SUBST_ALL_TAC THENL
       [USE_THEN "autBsv" (fun th ->
          MP_TAC(SPECL [`onebee:A`;`c':A`;`onebee:A`] th)) THEN
        ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                        DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
      SUBGOAL_THEN `z:A = m` SUBST_ALL_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`vy:A`;`onebee:A`;`z:A`;`m:A`]
          EOPAIR_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      FIRST_ASSUM ACCEPT_TAC;
      (* backward: E z vv ==> E z v' *)
      DISCH_TAC THEN
      USE_THEN "core" (MP_TAC o SPEC `z:A`) THEN ANTS_TAC THENL
       [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `vy:A`
        (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th))) THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;
                    `vv:A`;`v':A`;`z:A`]
        AUTN_MEM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MAP_EVERY EXISTS_TAC [`z:A`;`vy:A`;`onebee:A`;`vy:A`;`onebee:A`] THEN
      ASM_REWRITE_TAC[]];
    FIRST_ASSUM ACCEPT_TAC]);;

(* ===================================================================== *)
(* S3-7 step 9a-4' : EAUT_CHECK -- the autN wrapper over check-names.       *)
(* Clone of ECHECK_IS_BNAME with goodcheck->goodfix2,                       *)
(* GOODCHECK_SEM->GOODFIX2_SEM (no B arg; B at slot 2, autB at slot 3 of     *)
(* the base valuation, reduced via VALMOD/ARITH_EQ), GOODCHECK_STEP->        *)
(* GOODFIX2_STEP (extra ebij/congruence/eporder/etop hyps, ANTS discharged   *)
(* by REPEAT CONJ_TAC + FIRST_ASSUM ACCEPT_TAC), bname -> eautn B autB.      *)
(* Conclusion: autN fixes the check-name vx of every x.                      *)
(* ===================================================================== *)
let EAUT_CHECK = prove
 (`!D (E:A->A->bool) onebee B inclB autB x vx.
      model D E ZF_AX /\ onebee IN D /\ B IN D /\ autB IN D /\ E onebee B /\
      ebij D E autB B B /\
      (!a b ai bi. a IN D /\ b IN D /\ ai IN D /\ bi IN D /\
                   eapply D E autB a ai /\ eapply D E autB b bi
                   ==> (erel D E inclB a b <=> erel D E inclB ai bi)) /\
      eporder D E B inclB /\ etop D E B inclB onebee /\
      x IN D /\ vx IN D /\ echeck D E onebee x vx
      ==> eautn D E B autB vx vx`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
   (CONJUNCTS_THEN2 (LABEL_TAC "oneD")
    (CONJUNCTS_THEN2 (LABEL_TAC "BD")
     (CONJUNCTS_THEN2 (LABEL_TAC "autBD")
      (CONJUNCTS_THEN2 (LABEL_TAC "oneB")
       (CONJUNCTS_THEN2 (LABEL_TAC "bijB")
        (CONJUNCTS_THEN2 (LABEL_TAC "congB")
         (CONJUNCTS_THEN2 (LABEL_TAC "porder")
          (CONJUNCTS_THEN2 (LABEL_TAC "top")
           (CONJUNCTS_THEN2 (LABEL_TAC "xD")
            (CONJUNCTS_THEN2 (LABEL_TAC "vxD")
              (MP_TAC o REWRITE_RULE[echeck])))))))))))) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
   (CONJUNCTS_THEN2 (K ALL_TAC)
    (X_CHOOSE_THEN `a:A` (X_CHOOSE_THEN `cd:A` (X_CHOOSE_THEN `pp:A`
      (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th))))))) THEN
  (* sa = esuc a *)
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`a:A`] ESUC_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `sa:A`) THEN
  SUBGOAL_THEN `(sa:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) sa` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_ESUC]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) a sa` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_MEMBER]; ALL_TAC] THEN
  (* resolvent graph rc for the check-tower at sa *)
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`sa:A`]
    ECHECKTOWER_RESGRAPH) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `rc:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "rcc"))) THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v0:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  SUBGOAL_THEN `valuation D ((2 |-> (B:A)) v0)` ASSUME_TAC THENL
   [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
           (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC)); ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((3 |-> (autB:A)) ((2 |-> (B:A)) v0))`
  ASSUME_TAC THENL [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
      (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC)); ALL_TAC] THEN
  SUBGOAL_THEN
   `valuation D ((81 |-> (rc:A)) ((3 |-> (autB:A)) ((2 |-> (B:A)) v0)))`
  ASSUME_TAC THENL [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
      (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC)); ALL_TAC] THEN
  (* goodfix2-semantic holds at every ordinal below sa *)
  SUBGOAL_THEN
   `!dd. dd IN D /\ E dd sa
         ==> holds D E ((0 |-> dd) ((81 |-> (rc:A))
                        ((3 |-> (autB:A)) ((2 |-> (B:A)) v0))))
                       goodfix2`
  (LABEL_TAC "good") THENL
   [GEN_TAC THEN STRIP_TAC THEN
    MATCH_MP_TAC(TAUT `(~p ==> F) ==> p`) THEN
    DISCH_THEN(LABEL_TAC "bad0") THEN
    SUBGOAL_THEN `eordinal D (E:A->A->bool) dd` ASSUME_TAC THENL
     [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`Not goodfix2`;
                  `(81 |-> (rc:A)) ((3 |-> (autB:A)) ((2 |-> (B:A)) v0))`;
                  `dd:A`]
      EORDINAL_LEAST) THEN
    ASM_REWRITE_TAC[HOLDS_NOT] THEN
    DISCH_THEN(X_CHOOSE_THEN `d:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 (LABEL_TAC "dbad")
        (LABEL_TAC "dmin"))))) THEN
    SUBGOAL_THEN `(d:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) d sa` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`d:A`;`dd:A`]
        EORDINAL_TRICHOTOMY) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN ASSUME_TAC) THENL
       [ASM_MESON_TAC[EORDINAL_TRANS_E];
        ASM_MESON_TAC[];
        USE_THEN "dmin" (MP_TAC o SPEC `dd:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        USE_THEN "bad0" (fun th -> REWRITE_TAC[th])];
      ALL_TAC] THEN
    (* IH: the semantic statement holds at every b' < d *)
    SUBGOAL_THEN
     `!b'. b' IN D /\ E b' d
           ==> !zb pp x vv.
                  zb IN D /\ pp IN D /\ x IN D /\ vv IN D /\
                  echecktower D (E:A->A->bool) onebee b' zb /\ E pp zb /\
                  eopair D E x vv pp
                  ==> eautn D E B autB vv vv`
    ASSUME_TAC THENL
     [X_GEN_TAC `b':A` THEN STRIP_TAC THEN
      SUBGOAL_THEN `(E:A->A->bool) b' sa` ASSUME_TAC THENL
       [ASM_MESON_TAC[EORDINAL_TRANS_E]; ALL_TAC] THEN
      MP_TAC(REWRITE_RULE[VALMOD; ARITH_EQ]
        (SPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`sa:A`;`rc:A`;
                `(3 |-> (autB:A)) ((2 |-> (B:A)) v0)`;`b':A`]
                    GOODFIX2_SEM)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(MP_TAC o fst o EQ_IMP_RULE) THEN
      ANTS_TAC THENL
       [USE_THEN "dmin" (MP_TAC o SPEC `b':A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
        DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    (* holds at d, contradicting dbad *)
    SUBGOAL_THEN
     `holds D E ((0 |-> (d:A)) ((81 |-> (rc:A))
                 ((3 |-> (autB:A)) ((2 |-> (B:A)) v0)))) goodfix2`
    MP_TAC THENL
     [MP_TAC(REWRITE_RULE[VALMOD; ARITH_EQ]
        (SPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`sa:A`;`rc:A`;
                `(3 |-> (autB:A)) ((2 |-> (B:A)) v0)`;`d:A`] GOODFIX2_SEM)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;`inclB:A`;
                    `autB:A`;`d:A`] GOODFIX2_STEP) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN ACCEPT_TAC];
      USE_THEN "dbad" (fun th -> REWRITE_TAC[th])];
    ALL_TAC] THEN
  (* instantiate at a and feed the (x,vx)-pair from echeck *)
  USE_THEN "good" (MP_TAC o SPEC `a:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN
  MP_TAC(REWRITE_RULE[VALMOD; ARITH_EQ]
    (SPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`sa:A`;`rc:A`;
            `(3 |-> (autB:A)) ((2 |-> (B:A)) v0)`;`a:A`] GOODFIX2_SEM)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o fst o EQ_IMP_RULE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL [`cd:A`;`pp:A`;`x:A`;`vx:A`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]);;

(* ===================================================================== *)
(* S3-7 group 9b : autN permutes the Cohen-real names.  Steps 9b-0..2.    *)
(* EMBF_VAL_CHAR (value char extractor) -> AUTB_EMBVAL (generator-image   *)
(* fact: autB(e({cv})) = e({muci cv}) at char level) -> EAUT_REAL         *)
(* (autN_sigma(rdot_alpha) = rdot_{sigma alpha}).                         *)
(* ===================================================================== *)
(* S3-7 step 9b-0 : EMBF_VAL_CHAR -- extract the order-theoretic value        *)
(* characterization (STAR) from `eapply embf cvs bb` + the embf graph char.   *)
(* = the opening moves of EMBF_VAL_IN_B (eapply unfold +                      *)
(* EOPAIR_IN + graph char at the pair + EOPAIR_INJ), with NO Cohen context.   *)
let EMBF_VAL_CHAR = prove
 (`!D (E:A->A->bool) P leqp ci embf cvs bb.
     model D E ZF_AX /\ embf IN D /\
     (!z. z IN D
          ==> (E z embf <=>
               ?cv b. cv IN D /\ b IN D /\ E cv ci /\ eopair D E cv b z /\
                      (!q. q IN D
                           ==> (E q b <=>
                                E q P /\
                                (!r. r IN D /\ erel D E leqp r q
                                     ==> ?s. s IN D /\ erel D E leqp s r /\
                                             E cv s))))) /\
     cvs IN D /\ bb IN D /\ eapply D E embf cvs bb
     ==> !q. q IN D
             ==> (E q bb <=>
                  E q P /\
                  (!r. r IN D /\ erel D E leqp r q
                       ==> ?s. s IN D /\ erel D E leqp s r /\ E cvs s))`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
   (CONJUNCTS_THEN2 (LABEL_TAC "embfD")
    (CONJUNCTS_THEN2 (LABEL_TAC "gc")
     (CONJUNCTS_THEN2 (LABEL_TAC "cvsD")
      (CONJUNCTS_THEN2 (LABEL_TAC "bbD") (LABEL_TAC "app")))))) THEN
  USE_THEN "app" (MP_TAC o REWRITE_RULE[eapply]) THEN
  DISCH_THEN(X_CHOOSE_THEN `zp:A` (CONJUNCTS_THEN2 (LABEL_TAC "zpair")
    (LABEL_TAC "zmem"))) THEN
  SUBGOAL_THEN `(zp:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
  USE_THEN "gc" (MP_TAC o SPEC `zp:A`) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) zp embf`))) THEN
  DISCH_THEN(X_CHOOSE_THEN `cv:A` (X_CHOOSE_THEN `b:A`
    (CONJUNCTS_THEN2 (LABEL_TAC "cvD") (CONJUNCTS_THEN2 (LABEL_TAC "bD")
      (CONJUNCTS_THEN2 (LABEL_TAC "cvci") (CONJUNCTS_THEN2 (LABEL_TAC "cpair")
        (LABEL_TAC "bchar"))))))) THEN
  SUBGOAL_THEN `cvs:A = cv /\ bb:A = b`
    (CONJUNCTS_THEN2 SUBST_ALL_TAC SUBST_ALL_TAC) THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`cvs:A`;`bb:A`;`cv:A`;`b:A`;
                  `zp:A`] EOPAIR_INJ) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  USE_THEN "bchar" ACCEPT_TAC);;

(* ===================================================================== *)
(* S3-7 step 9b-1 : AUTB_EMBVAL -- the generator-image fact.                *)
(* The embf VALUE b at coordinate-atom cv has the order-theoretic char       *)
(*   (STAR)  E q b <=> E q P /\ (!r<=q. ?s<=r. E cv s);                      *)
(* autB (= muP-image on B) transports (STAR)@cv for b to (STAR)@(muci cv)    *)
(* for autB(b), because muP is an order-automorphism of (P,leqp) and         *)
(* condition-membership of atoms transports along muci (muPrel + muci-inj).  *)
(* ===================================================================== *)
let AUTB_EMBVAL = prove
 (`!D (E:A->A->bool) P leqp B ci muci muP autB cv cv' b b'.
      model D E ZF_AX /\ P IN D /\ ci IN D /\ muci IN D /\ muP IN D /\
      B IN D /\ eleqp D E P leqp /\
      ebij D E muci ci ci /\
      (!u w. u IN D /\ w IN D
             ==> (eapply D E muP u w <=> E u P /\ muPrel D E muci u w)) /\
      ebij D E muP P P /\
      (!pa pb qa qb. pa IN D /\ pb IN D /\ qa IN D /\ qb IN D /\
                     eapply D E muP pa qa /\ eapply D E muP pb qb
                     ==> (erel D E leqp pa pb <=> erel D E leqp qa qb)) /\
      (!u w. u IN D /\ w IN D
             ==> (eapply D E autB u w <=> E u B /\ muPrel D E muP u w)) /\
      cv IN D /\ cv' IN D /\ eapply D E muci cv cv' /\
      b IN D /\ b' IN D /\ eapply D E autB b b' /\
      (!q. q IN D
           ==> (E q b <=>
                E q P /\
                (!r. r IN D /\ erel D E leqp r q
                     ==> ?s. s IN D /\ erel D E leqp s r /\ E cv s)))
      ==> (!q. q IN D
               ==> (E q b' <=>
                    E q P /\
                    (!r. r IN D /\ erel D E leqp r q
                         ==> ?s. s IN D /\ erel D E leqp s r /\ E cv' s)))`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
   (CONJUNCTS_THEN2 (LABEL_TAC "PD")
    (CONJUNCTS_THEN2 (LABEL_TAC "ciD")
     (CONJUNCTS_THEN2 (LABEL_TAC "muciD")
      (CONJUNCTS_THEN2 (LABEL_TAC "muPD")
       (CONJUNCTS_THEN2 (LABEL_TAC "BD")
        (CONJUNCTS_THEN2 (LABEL_TAC "leq")
         (CONJUNCTS_THEN2 (LABEL_TAC "bijci")
          (CONJUNCTS_THEN2 (LABEL_TAC "muPch")
           (CONJUNCTS_THEN2 (LABEL_TAC "bijP")
            (CONJUNCTS_THEN2 (LABEL_TAC "quad")
             (CONJUNCTS_THEN2 (LABEL_TAC "autBch")
              (CONJUNCTS_THEN2 (LABEL_TAC "cvD")
               (CONJUNCTS_THEN2 (LABEL_TAC "cv'D")
                (CONJUNCTS_THEN2 (LABEL_TAC "mucicv")
                 (CONJUNCTS_THEN2 (LABEL_TAC "bD")
                  (CONJUNCTS_THEN2 (LABEL_TAC "b'D")
                   (CONJUNCTS_THEN2 (LABEL_TAC "app")
                     (LABEL_TAC "bchar"))))))))))))))))))) THEN
  (* ebij conjunct extraction: muP bnd/tot/ont, muci inj *)
  USE_THEN "bijP" (LABEL_TAC "Pbnd" o CONJUNCT1 o CONJUNCT2 o
                   REWRITE_RULE[ebij]) THEN
  USE_THEN "bijP" (LABEL_TAC "Ptot" o CONJUNCT1 o CONJUNCT2 o CONJUNCT2 o
                   REWRITE_RULE[ebij]) THEN
  USE_THEN "bijP" (LABEL_TAC "Pont" o CONJUNCT2 o CONJUNCT2 o CONJUNCT2 o
                   CONJUNCT2 o CONJUNCT2 o REWRITE_RULE[ebij]) THEN
  USE_THEN "bijci" (LABEL_TAC "ciinj" o CONJUNCT1 o CONJUNCT2 o CONJUNCT2 o
                    CONJUNCT2 o CONJUNCT2 o REWRITE_RULE[ebij]) THEN
  (* E b B and muPrel muP b b' from the autB char *)
  USE_THEN "autBch" (MP_TAC o SPECL [`b:A`;`b':A`]) THEN
  ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th ->
    MP_TAC(EQ_MP th (ASSUME `eapply D (E:A->A->bool) autB b b'`))) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "bB") (LABEL_TAC "mrel")) THEN
  X_GEN_TAC `q':A` THEN DISCH_THEN(LABEL_TAC "q'D") THEN EQ_TAC THENL
   [(* ==== FWD: E q' b' ==> E q' P /\ rcond@cv' ==== *)
    DISCH_THEN(LABEL_TAC "q'b'") THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`muP:A`;`b:A`;`b':A`;`q':A`]
      MUP_REL_MEM) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th ->
      MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) q' b'`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `p0:A` (CONJUNCTS_THEN2 (LABEL_TAC "p0D")
      (CONJUNCTS_THEN2 (LABEL_TAC "p0b") (LABEL_TAC "mp0")))) THEN
    USE_THEN "bchar" (MP_TAC o SPEC `p0:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th ->
      MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) p0 b`))) THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "p0P") (LABEL_TAC "rcond")) THEN
    CONJ_TAC THENL
     [USE_THEN "Pbnd" (MP_TAC o SPECL [`p0:A`;`q':A`]) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN(ACCEPT_TAC o CONJUNCT2)];
      ALL_TAC] THEN
    X_GEN_TAC `r':A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "r'D") (LABEL_TAC "r'le")) THEN
    SUBGOAL_THEN `(E:A->A->bool) r' P` (LABEL_TAC "r'P") THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`r':A`;`q':A`]
        ELEQP_EREL) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN(ACCEPT_TAC o CONJUNCT1)];
      ALL_TAC] THEN
    USE_THEN "Pont" (MP_TAC o SPEC `r':A`) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `r0:A` (CONJUNCTS_THEN2 (LABEL_TAC "r0D")
      (CONJUNCTS_THEN2 (LABEL_TAC "r0P") (LABEL_TAC "mr0")))) THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leqp r0 p0` (LABEL_TAC "r0le") THENL
     [USE_THEN "quad" (MP_TAC o SPECL [`r0:A`;`p0:A`;`r':A`;`q':A`]) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN FIRST_ASSUM ACCEPT_TAC;
      ALL_TAC] THEN
    USE_THEN "rcond" (MP_TAC o SPEC `r0:A`) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `s0:A` (CONJUNCTS_THEN2 (LABEL_TAC "s0D")
      (CONJUNCTS_THEN2 (LABEL_TAC "s0le") (LABEL_TAC "cvs0")))) THEN
    SUBGOAL_THEN `(E:A->A->bool) s0 P` (LABEL_TAC "s0P") THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`s0:A`;`r0:A`]
        ELEQP_EREL) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN(ACCEPT_TAC o CONJUNCT1)];
      ALL_TAC] THEN
    USE_THEN "Ptot" (MP_TAC o SPEC `s0:A`) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `s':A` (CONJUNCTS_THEN2 (LABEL_TAC "s'D")
      (CONJUNCTS_THEN2 (LABEL_TAC "s'P") (LABEL_TAC "ms0")))) THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leqp s' r'` (LABEL_TAC "s'le") THENL
     [USE_THEN "quad" (MP_TAC o SPECL [`s0:A`;`r0:A`;`s':A`;`r':A`]) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN FIRST_ASSUM ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `muPrel D (E:A->A->bool) muci s0 s'` (LABEL_TAC "mrs0") THENL
     [USE_THEN "muPch" (MP_TAC o SPECL [`s0:A`;`s':A`]) THEN
      ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        MP_TAC(EQ_MP th (ASSUME `eapply D (E:A->A->bool) muP s0 s'`))) THEN
      DISCH_THEN(ACCEPT_TAC o CONJUNCT2);
      ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) cv' s'` (LABEL_TAC "cv's'") THENL
