(* ===================================================================== *)
(* S3-7 step 9b-2 : EAUT_REAL -- autN_sigma(rdot_alpha) = rdot_{sigma a}.   *)
(* rdot_alpha = {<n^, embf<<alpha,n>,onetw>> : n<om} (COHEN_REALNAME char,   *)
(* ON := onebee).  autN sends <n^,b> to <n^, autB b> (check-names fixed by   *)
(* 9a EAUT_CHECK); autB(embf cv) = embf(muci cv) at char level by 9b-1       *)
(* AUTB_EMBVAL + EMBF_VAL_CHAR + ZF_EXTENSIONALITY.  Both rdot chars are     *)
(* hyps (abstract bundle); conclude eautn B autB rdot rdot' via AUTN_TOTAL   *)
(* + member-extensionality (the GOODFIX2_STEP-TAIL pattern).                 *)
(* ===================================================================== *)
let EAUT_REAL = prove
 (`!D (E:A->A->bool) P leqp B inclB onebee ci muci muP autB sigma
     iibase om ii tw embf alpha alpha' onetw rdot rdot'.
      model D E ZF_AX /\
      onebee IN D /\ B IN D /\ autB IN D /\ E onebee B /\
      ebij D E autB B B /\
      (!a b ai bi. a IN D /\ b IN D /\ ai IN D /\ bi IN D /\
                   eapply D E autB a ai /\ eapply D E autB b bi
                   ==> (erel D E inclB a b <=> erel D E inclB ai bi)) /\
      eporder D E B inclB /\ etop D E B inclB onebee /\
      P IN D /\ ci IN D /\ muci IN D /\ muP IN D /\ eleqp D E P leqp /\
      ebij D E muci ci ci /\
      (!u w. u IN D /\ w IN D
             ==> (eapply D E muci u w <=> E u ci /\ mucirel D E sigma u w)) /\
      (!u w. u IN D /\ w IN D
             ==> (eapply D E muP u w <=> E u P /\ muPrel D E muci u w)) /\
      ebij D E muP P P /\
      (!pa pb qa qb. pa IN D /\ pb IN D /\ qa IN D /\ qb IN D /\
                     eapply D E muP pa qa /\ eapply D E muP pb qb
                     ==> (erel D E leqp pa pb <=> erel D E leqp qa qb)) /\
      (!u w. u IN D /\ w IN D
             ==> (eapply D E autB u w <=> E u B /\ muPrel D E muP u w)) /\
      ecross D E iibase om ii /\ ecross D E ii tw ci /\
      embf IN D /\
      (!z. z IN D
           ==> (E z embf <=>
                ?cv b. cv IN D /\ b IN D /\ E cv ci /\ eopair D E cv b z /\
                       (!q. q IN D
                            ==> (E q b <=>
                                 E q P /\
                                 (!r. r IN D /\ erel D E leqp r q
                                      ==> ?s. s IN D /\ erel D E leqp s r /\
                                              E cv s))))) /\
      (!cvs. cvs IN D /\ E cvs ci ==> ?b. b IN D /\ eapply D E embf cvs b) /\
      (!cvs bb. cvs IN D /\ bb IN D /\ eapply D E embf cvs bb ==> E bb B) /\
      alpha IN D /\ E alpha iibase /\ alpha' IN D /\ E alpha' iibase /\
      eapply D E sigma alpha alpha' /\ onetw IN D /\ E onetw tw /\
      rdot IN D /\ bname D E B rdot /\
      (!z. z IN D
           ==> (E z rdot <=>
                ?n sig b p15 cvs. n IN D /\ sig IN D /\ b IN D /\ p15 IN D /\
                    cvs IN D /\ E n om /\
                    echeck D E onebee n sig /\ eopair D E alpha n p15 /\
                    eopair D E p15 onetw cvs /\ eapply D E embf cvs b /\
                    eopair D E sig b z)) /\
      rdot' IN D /\
      (!z. z IN D
           ==> (E z rdot' <=>
                ?n sig b p15 cvs. n IN D /\ sig IN D /\ b IN D /\ p15 IN D /\
                    cvs IN D /\ E n om /\
                    echeck D E onebee n sig /\ eopair D E alpha' n p15 /\
                    eopair D E p15 onetw cvs /\ eapply D E embf cvs b /\
                    eopair D E sig b z))
      ==> eautn D E B autB rdot rdot'`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
   (CONJUNCTS_THEN2 (LABEL_TAC "oneD")
    (CONJUNCTS_THEN2 (LABEL_TAC "BD")
     (CONJUNCTS_THEN2 (LABEL_TAC "autBD")
      (CONJUNCTS_THEN2 (LABEL_TAC "oneB")
       (CONJUNCTS_THEN2 (LABEL_TAC "bijB")
        (CONJUNCTS_THEN2 (LABEL_TAC "quadB")
         (CONJUNCTS_THEN2 (LABEL_TAC "porder")
          (CONJUNCTS_THEN2 (LABEL_TAC "top")
           (CONJUNCTS_THEN2 (LABEL_TAC "PD")
            (CONJUNCTS_THEN2 (LABEL_TAC "ciD")
             (CONJUNCTS_THEN2 (LABEL_TAC "muciD")
              (CONJUNCTS_THEN2 (LABEL_TAC "muPD")
               (CONJUNCTS_THEN2 (LABEL_TAC "leq")
                (CONJUNCTS_THEN2 (LABEL_TAC "bijci")
                 (CONJUNCTS_THEN2 (LABEL_TAC "mucich")
                  (CONJUNCTS_THEN2 (LABEL_TAC "muPch")
                   (CONJUNCTS_THEN2 (LABEL_TAC "bijP")
                    (CONJUNCTS_THEN2 (LABEL_TAC "quadP")
                     (CONJUNCTS_THEN2 (LABEL_TAC "autBch")
                      (CONJUNCTS_THEN2 (LABEL_TAC "cr1")
                       (CONJUNCTS_THEN2 (LABEL_TAC "cr2")
                        (CONJUNCTS_THEN2 (LABEL_TAC "embfD")
                         (CONJUNCTS_THEN2 (LABEL_TAC "gc")
                          (CONJUNCTS_THEN2 (LABEL_TAC "etot")
                           (CONJUNCTS_THEN2 (LABEL_TAC "evalB")
                            (CONJUNCTS_THEN2 (LABEL_TAC "aD")
                             (CONJUNCTS_THEN2 (LABEL_TAC "aib")
                              (CONJUNCTS_THEN2 (LABEL_TAC "a'D")
                               (CONJUNCTS_THEN2 (LABEL_TAC "a'ib")
                                (CONJUNCTS_THEN2 (LABEL_TAC "sgap")
                                 (CONJUNCTS_THEN2 (LABEL_TAC "otD")
                                  (CONJUNCTS_THEN2 (LABEL_TAC "ottw")
                                   (CONJUNCTS_THEN2 (LABEL_TAC "rD")
                                    (CONJUNCTS_THEN2 (LABEL_TAC "bn")
                                     (CONJUNCTS_THEN2 (LABEL_TAC "rch")
                                      (CONJUNCTS_THEN2 (LABEL_TAC "r'D")
                                        (LABEL_TAC "r'ch")
                                       )))))))))))))))))))))))))))))))))))))
                                           THEN
  (* v' := autN(rdot) *)
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`rdot:A`]
    AUTN_TOTAL) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `v':A` (CONJUNCTS_THEN2 (LABEL_TAC "v'D")
    (LABEL_TAC "autnr"))) THEN
  SUBGOAL_THEN `(v':A) = rdot'` SUBST_ALL_TAC THENL
   [FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "v'D" ACCEPT_TAC; USE_THEN "r'D" ACCEPT_TAC; ALL_TAC] THEN
    X_GEN_TAC `z:A` THEN DISCH_THEN(LABEL_TAC "zD") THEN EQ_TAC THENL
     [(* ==== FWD: z IN autN(rdot) ==> z IN rdot' ==== *)
      DISCH_THEN(LABEL_TAC "zv'") THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`rdot:A`;
                    `v':A`;`z:A`] AUTN_MEM) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) z v'`))) THEN
      DISCH_THEN(X_CHOOSE_THEN `m:A` (X_CHOOSE_THEN `t:A` (X_CHOOSE_THEN `c:A`
        (X_CHOOSE_THEN `t':A` (X_CHOOSE_THEN `c':A`
          (CONJUNCTS_THEN2 (LABEL_TAC "mD") (CONJUNCTS_THEN2 (LABEL_TAC "tD")
            (CONJUNCTS_THEN2 (LABEL_TAC "cD") (CONJUNCTS_THEN2 (LABEL_TAC "t'D")
              (CONJUNCTS_THEN2 (LABEL_TAC "c'D")
               (CONJUNCTS_THEN2 (LABEL_TAC "mr")
                (CONJUNCTS_THEN2 (LABEL_TAC "tcm")
                 (CONJUNCTS_THEN2 (LABEL_TAC "att")
                  (CONJUNCTS_THEN2 (LABEL_TAC "acc")
                    (LABEL_TAC "pz"))))))))))))))) THEN
      USE_THEN "rch" (MP_TAC o SPEC `m:A`) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) m rdot`))) THEN
      DISCH_THEN(X_CHOOSE_THEN `n:A` (X_CHOOSE_THEN `sig:A` (X_CHOOSE_THEN `b:A`
        (X_CHOOSE_THEN `p15:A` (X_CHOOSE_THEN `cvs:A`
          (CONJUNCTS_THEN2 (LABEL_TAC "nD") (CONJUNCTS_THEN2 (LABEL_TAC "sigD")
            (CONJUNCTS_THEN2 (LABEL_TAC "bD")
             (CONJUNCTS_THEN2 (LABEL_TAC "p15D")
              (CONJUNCTS_THEN2 (LABEL_TAC "cvsD")
               (CONJUNCTS_THEN2 (LABEL_TAC "nom")
                (CONJUNCTS_THEN2 (LABEL_TAC "chk")
                 (CONJUNCTS_THEN2 (LABEL_TAC "p15p")
                  (CONJUNCTS_THEN2 (LABEL_TAC "cvsp")
                    (CONJUNCTS_THEN2 (LABEL_TAC "appb")
                      (LABEL_TAC "sigbm")))))))))))))))) THEN
      SUBGOAL_THEN `t:A = sig /\ c:A = b`
        (CONJUNCTS_THEN2 SUBST_ALL_TAC SUBST_ALL_TAC) THENL
       [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`t:A`;`c:A`;`sig:A`;`b:A`;
                      `m:A`] EOPAIR_INJ) THEN
        ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                        DISCH_THEN ACCEPT_TAC];
        ALL_TAC] THEN
      SUBGOAL_THEN `eautn D (E:A->A->bool) B autB sig sig`
        (LABEL_TAC "fixsig") THENL
       [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;`inclB:A`;
                      `autB:A`;`n:A`;`sig:A`] EAUT_CHECK) THEN
        ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                        DISCH_THEN ACCEPT_TAC];
        ALL_TAC] THEN
      SUBGOAL_THEN `t':A = sig` SUBST_ALL_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`sig:A`;
