      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `cvs':A` (LABEL_TAC "cvs'p")) THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`p15':A`;`onetw:A`;`cvs':A`]
        EOPAIR_IN) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN(LABEL_TAC "cvs'D")] THEN
      SUBGOAL_THEN `(E:A->A->bool) p15' ii` (LABEL_TAC "p15'ii") THENL
       [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`iibase:A`;`om:A`;`ii:A`;
                      `p15':A`] ECROSS_MEMBER) THEN
        ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        MAP_EVERY EXISTS_TAC [`alpha':A`;`n:A`] THEN
        REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) cvs' ci` (LABEL_TAC "cvs'ci") THENL
       [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`ii:A`;`tw:A`;`ci:A`;
                      `cvs':A`] ECROSS_MEMBER) THEN
        ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        MAP_EVERY EXISTS_TAC [`p15':A`;`onetw:A`] THEN
        REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) p15 ii` (LABEL_TAC "p15ii") THENL
       [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`iibase:A`;`om:A`;`ii:A`;
                      `p15:A`] ECROSS_MEMBER) THEN
        ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        MAP_EVERY EXISTS_TAC [`alpha:A`;`n:A`] THEN
        REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) cvs ci` (LABEL_TAC "cvsci") THENL
       [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`ii:A`;`tw:A`;`ci:A`;
                      `cvs:A`] ECROSS_MEMBER) THEN
        ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
