(* ===================================================================== *)
(* S3-7 / 9c : the HS domain parameter, and the HS rank layer.            *)
(*                                                                          *)
(* !! HS DOMAIN PARAMETER (read before using ehssym / hsstage / hsname) !!  *)
(* autb_of_form is iP iB ib (S3-2) reads BOTH the atom action muci          *)
(* (mucifun_form, whose 2nd argument is the ATOM set) and the condition     *)
(* action muP (imgfun_form 148 iP 149) off the SAME slot iP.  Hence         *)
(* symfix_form / hssym_form / ehssym / ehsmem / hsstage / hsname all take   *)
(* ONE domain parameter "P" that serves as the domain of muci AND of muP.   *)
(* Instantiating it at the atom set ci or at the condition set P alone      *)
(* makes the induced autB degenerate.  The lemmas are all generic in       *)
(* that parameter, so the HS layer is used at a set X with ci SUBSET X and  *)
(* P SUBSET X (e.g. X = ci UNION P): there the X-domain muci agrees with    *)
(* the true one on atoms, the X-domain muP with the true one on conditions, *)
(* and the induced autB is EXACTLY the true c.b.a. automorphism             *)
(* (MUPREL_X_AGREE).  Later results see only the true bundle (chars on ci / *)
(* P / B, ebij x3, both order quadruples).                                  *)
(*                                                                          *)
(* Contents: B1 MUCI_EXISTS_ON (muci on an arbitrary domain, separation +   *)
(* EIMG_FAMILY), B2 MUPREL_CONG / MUPREL_X_AGREE; R: instage_hs_form,       *)
(* hsrank_form + HOLDS lemmas, HSNAME_RANK(_UNIQUE), HSNAME_BOUND; S:       *)
(* ECHECK_HSNAME_STEP/SUCC; E: EBIJ_EEMPTY; G: goodhs, HOLDS_GOODHS,      *)
(* GOODHS_SEM.                                                              *)
(* ===================================================================== *)
(* ===================================================================== *)
(* S3-7 step 9c-B1 : MUCI_EXISTS_ON -- the coordinate action muci on an      *)
(* ARBITRARY domain set X (not just ci).  Needed because the                 *)
(* autb_of_form / hssym_form / ehssym read BOTH muci and muP off one domain  *)
(* slot P; the HS layer is therefore instantiated at a set X containing ci   *)
(* AND the Cohen conditions, and the muci it quantifies over has domain X.   *)
(* Separation X' = {u IN X | ?w. mucirel sigma u w} (via ?? 1 permci_form),  *)
(* then the MUCI_EXISTS EIMG_FAMILY construction over X'.                    *)
(* ===================================================================== *)
let MUCI_EXISTS_ON = prove
 (`!D (E:A->A->bool) sigma X v.
     model D E ZF_AX /\ valuation D v /\ v 2 = sigma /\ X IN D /\
     (!k t t'. k IN D /\ t IN D /\ t' IN D /\
               eapply D E sigma k t /\ eapply D E sigma k t' ==> t = t')
     ==> ?ff. ff IN D /\
              (!u w. u IN D /\ w IN D
                     ==> (eapply D E ff u w <=>
                          E u X /\ mucirel D E sigma u w))`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
   (CONJUNCTS_THEN2 (LABEL_TAC "val")
    (CONJUNCTS_THEN2 (LABEL_TAC "v2")
     (CONJUNCTS_THEN2 (LABEL_TAC "XD") (LABEL_TAC "sigSV"))))) THEN
  (* X' = {u IN X | ?w. mucirel sigma u w} *)
  USE_THEN "modl" (MP_TAC o SPECL [`?? 1 permci_form`; `0`; `v:num->A`; `X:A`] o
    MATCH_MP ZF_SEPARATION) THEN
  ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `X':A` (CONJUNCTS_THEN2 (LABEL_TAC "X'D")
    (LABEL_TAC "sepch"))) THEN
  SUBGOAL_THEN
   `!u:A. u IN D ==> (E u X' <=> E u X /\ ?w. mucirel D E sigma u w)`
   (LABEL_TAC "X'ch") THENL
   [X_GEN_TAC `u:A` THEN DISCH_THEN(LABEL_TAC "uD") THEN
    USE_THEN "sepch" (MP_TAC o SPEC `u:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MATCH_MP_TAC(TAUT `(b <=> c) ==> (a /\ b <=> a /\ c)`) THEN
    REWRITE_TAC[HOLDS_EX] THEN EQ_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `out:A` (CONJUNCTS_THEN2 (LABEL_TAC "outD")
        (LABEL_TAC "hp"))) THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`v:num->A`;`u:A`;`out:A`]
        HOLDS_PERMCI_PAIR) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> USE_THEN "hp" (MP_TAC o EQ_MP th)) THEN
      DISCH_THEN(X_CHOOSE_THEN `w:A` (CONJUNCTS_THEN2 (LABEL_TAC "mr")
        (K ALL_TAC))) THEN
      EXISTS_TAC `w:A` THEN
      USE_THEN "v2" (fun eq -> USE_THEN "mr" (fun th ->
        ACCEPT_TAC(REWRITE_RULE[eq] th)));
      DISCH_THEN(X_CHOOSE_THEN `w:A` (LABEL_TAC "mr")) THEN
      SUBGOAL_THEN `(w:A) IN D` (LABEL_TAC "wD") THENL
       [USE_THEN "mr" (fun th -> ACCEPT_TAC(CONJUNCT2(MATCH_MP
           MUCI_REL_IN th)));
        ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`u:A`;`w:A`] EOPAIR_EXISTS) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `out:A` (LABEL_TAC "pr")) THEN
      SUBGOAL_THEN `(out:A) IN D` (LABEL_TAC "outD") THENL
       [USE_THEN "pr" (ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
      EXISTS_TAC `out:A` THEN
      CONJ_TAC THENL [USE_THEN "outD" ACCEPT_TAC; ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`v:num->A`;`u:A`;`out:A`]
        HOLDS_PERMCI_PAIR) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      EXISTS_TAC `w:A` THEN
      USE_THEN "v2" (fun eq -> REWRITE_TAC[eq]) THEN
      CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`permci_form`;`0`;`1`;
                 `v:num->A`;`X':A`] EIMG_FAMILY) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [USE_THEN "modl" ACCEPT_TAC;
      USE_THEN "val" ACCEPT_TAC;
      USE_THEN "X'D" ACCEPT_TAC;
      ARITH_TAC;
      (* ---- func-cond ---- *)
      X_GEN_TAC `u:A` THEN
      DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "uD") (LABEL_TAC "uX'")) THEN
      USE_THEN "X'ch" (MP_TAC o SPEC `u:A`) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> USE_THEN "uX'" (MP_TAC o EQ_MP th)) THEN
      DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
        (X_CHOOSE_THEN `w:A` (LABEL_TAC "mr"))) THEN
      SUBGOAL_THEN `(w:A) IN D` (LABEL_TAC "wD") THENL
       [USE_THEN "mr" (fun th -> ACCEPT_TAC(CONJUNCT2(MATCH_MP
           MUCI_REL_IN th)));
        ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`u:A`;`w:A`] EOPAIR_EXISTS) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `out:A` (LABEL_TAC "pr")) THEN
      SUBGOAL_THEN `(out:A) IN D` (LABEL_TAC "outD") THENL
       [USE_THEN "pr" (ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
      EXISTS_TAC `out:A` THEN REPEAT CONJ_TAC THENL
       [USE_THEN "outD" ACCEPT_TAC;
        MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`v:num->A`;`u:A`;`out:A`]
          HOLDS_PERMCI_PAIR) THEN
        ANTS_TAC THENL [REPEAT CONJ_TAC THEN
                        FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        EXISTS_TAC `w:A` THEN
        USE_THEN "v2" (fun eq -> REWRITE_TAC[eq]) THEN
        CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
        X_GEN_TAC `out':A` THEN
        DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "out'D") (LABEL_TAC "hp'")) THEN
        MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`v:num->A`;`u:A`;`out':A`]
          HOLDS_PERMCI_PAIR) THEN
        ANTS_TAC THENL [REPEAT CONJ_TAC THEN
                        FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
        DISCH_THEN(fun th -> USE_THEN "hp'" (MP_TAC o EQ_MP th)) THEN
        DISCH_THEN(X_CHOOSE_THEN `wb:A` (CONJUNCTS_THEN2 (LABEL_TAC "mrb")
          (LABEL_TAC "prb"))) THEN
        SUBGOAL_THEN `wb:A = w` SUBST_ALL_TAC THENL
         [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`sigma:A`;`u:A`;`wb:A`;`w:A`]
            MUCI_REL_FUNC) THEN
          ANTS_TAC THENL
           [REPEAT CONJ_TAC THENL
             [USE_THEN "modl" ACCEPT_TAC;
              USE_THEN "sigSV" ACCEPT_TAC;
              USE_THEN "v2" (fun eq -> USE_THEN "mrb" (fun th ->
                ACCEPT_TAC(REWRITE_RULE[eq] th)));
              USE_THEN "mr" ACCEPT_TAC];
            DISCH_THEN ACCEPT_TAC];
          ALL_TAC] THEN
        MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`u:A`;`w:A`;`out':A`;`out:A`]
          EOPAIR_UNIQUE) THEN
        ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                        DISCH_THEN ACCEPT_TAC]];
      (* ---- hf-cond ---- *)
      MAP_EVERY X_GEN_TAC [`u:A`;`out:A`] THEN
      DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "uD") (CONJUNCTS_THEN2 (K ALL_TAC)
        (CONJUNCTS_THEN2 (LABEL_TAC "outD") (LABEL_TAC "hp")))) THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`v:num->A`;`u:A`;`out:A`]
        HOLDS_PERMCI_PAIR) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> USE_THEN "hp" (MP_TAC o EQ_MP th)) THEN
      DISCH_THEN(X_CHOOSE_THEN `w:A` (CONJUNCTS_THEN2 (LABEL_TAC "mr")
        (LABEL_TAC "pr"))) THEN
      EXISTS_TAC `w:A` THEN CONJ_TAC THENL
       [USE_THEN "mr" (fun th -> ACCEPT_TAC(CONJUNCT2(MATCH_MP
           MUCI_REL_IN th)));
        USE_THEN "pr" ACCEPT_TAC]];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ff:A`
    (CONJUNCTS_THEN2 (LABEL_TAC "ffD")
     (CONJUNCTS_THEN2 (LABEL_TAC "ffmem") (K ALL_TAC)))) THEN
  EXISTS_TAC `ff:A` THEN CONJ_TAC THENL
      [USE_THEN "ffD" ACCEPT_TAC; ALL_TAC] THEN
  MAP_EVERY X_GEN_TAC [`u:A`;`w:A`] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "uD") (LABEL_TAC "wD"))
      THEN EQ_TAC THENL
   [(* ==> *)
    DISCH_THEN(MP_TAC o GEN_REWRITE_RULE I [eapply]) THEN
    DISCH_THEN(X_CHOOSE_THEN `z:A` (CONJUNCTS_THEN2 (LABEL_TAC "pz")
      (LABEL_TAC "zff"))) THEN
    SUBGOAL_THEN `(z:A) IN D` (LABEL_TAC "zD") THENL
     [USE_THEN "pz" (ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
    USE_THEN "ffmem" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "zff" (MP_TAC o EQ_MP th)) THEN
    DISCH_THEN(X_CHOOSE_THEN `u':A` (CONJUNCTS_THEN2 (LABEL_TAC "u'D")
      (CONJUNCTS_THEN2 (LABEL_TAC "u'X'") (LABEL_TAC "hp")))) THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`v:num->A`;`u':A`;`z:A`]
      HOLDS_PERMCI_PAIR) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "hp" (MP_TAC o EQ_MP th)) THEN
    DISCH_THEN(X_CHOOSE_THEN `w':A` (CONJUNCTS_THEN2 (LABEL_TAC "mr'")
      (LABEL_TAC "pz'"))) THEN
    SUBGOAL_THEN `(w':A) IN D` (LABEL_TAC "w'D") THENL
     [USE_THEN "mr'" (fun th -> ACCEPT_TAC(CONJUNCT2(MATCH_MP MUCI_REL_IN th)));
      ALL_TAC] THEN
    SUBGOAL_THEN `u:A = u' /\ w:A = w'`
      (CONJUNCTS_THEN2 SUBST_ALL_TAC SUBST_ALL_TAC) THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`u:A`;`w:A`;`u':A`;`w':A`;`z:A`]
        EOPAIR_INJ) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    CONJ_TAC THENL
     [USE_THEN "X'ch" (MP_TAC o SPEC `u':A`) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> USE_THEN "u'X'" (MP_TAC o EQ_MP th)) THEN
      DISCH_THEN(ACCEPT_TAC o CONJUNCT1);
      USE_THEN "v2" (fun eq -> USE_THEN "mr'" (fun th ->
        ACCEPT_TAC(REWRITE_RULE[eq] th)))];
    (* <== *)
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "uX") (LABEL_TAC "mr")) THEN
    REWRITE_TAC[eapply] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`u:A`;`w:A`] EOPAIR_EXISTS) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `z:A` (LABEL_TAC "pz")) THEN
    SUBGOAL_THEN `(z:A) IN D` (LABEL_TAC "zD") THENL
     [USE_THEN "pz" (ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
    EXISTS_TAC `z:A` THEN CONJ_TAC THENL
        [USE_THEN "pz" ACCEPT_TAC; ALL_TAC] THEN
    USE_THEN "ffmem" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EXISTS_TAC `u:A` THEN REPEAT CONJ_TAC THENL
     [USE_THEN "uD" ACCEPT_TAC;
      USE_THEN "X'ch" (MP_TAC o SPEC `u:A`) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      CONJ_TAC THENL [USE_THEN "uX" ACCEPT_TAC;
                      EXISTS_TAC `w:A` THEN USE_THEN "mr" ACCEPT_TAC];
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`v:num->A`;`u:A`;`z:A`]
        HOLDS_PERMCI_PAIR) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      EXISTS_TAC `w:A` THEN
      USE_THEN "v2" (fun eq -> REWRITE_TAC[eq]) THEN
      CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC]]);;

(* S3-7 step 9c-B2a : MUPREL_CONG -- the image relation muPrel g p q only     *)
(* depends on g's graph restricted to members of p.                          *)
let MUPREL_CONG = prove
 (`!D (E:A->A->bool) g g' p q.
      (!x y. x IN D /\ y IN D /\ E x p
             ==> (eapply D E g x y <=> eapply D E g' x y))
      ==> (muPrel D E g p q <=> muPrel D E g' p q)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN REWRITE_TAC[muPrel] THEN
  ASM_MESON_TAC[]);;

(* S3-7 step 9c-B2 : MUPREL_X_AGREE -- the X-domain muci/muP (as quantified  *)
(* in ehssym at P := X) induce on each b IN B the SAME image as the true     *)
(* muci0 (domain ci) / muP0 (domain P), provided ci SUBSET X, P SUBSET X,    *)
(* conditions are subsets of ci and members of B are subsets of P.          *)
let MUPREL_X_AGREE = prove
 (`!D (E:A->A->bool) ci P B X sigma muci muP muci0 muP0 b c.
      (!u. u IN D /\ E u ci ==> E u X) /\
      (!p. p IN D /\ E p P ==> E p X) /\
      (!p u. p IN D /\ E p P /\ u IN D /\ E u p ==> E u ci) /\
      (!bb x. bb IN D /\ E bb B /\ x IN D /\ E x bb ==> E x P) /\
      (!u w. u IN D /\ w IN D
             ==> (eapply D E muci u w <=> E u X /\ mucirel D E sigma u w)) /\
      (!p q. p IN D /\ q IN D
             ==> (eapply D E muP p q <=> E p X /\ muPrel D E muci p q)) /\
      (!u w. u IN D /\ w IN D
             ==> (eapply D E muci0 u w <=> E u ci /\ mucirel D E sigma u w)) /\
      (!p q. p IN D /\ q IN D
             ==> (eapply D E muP0 p q <=> E p P /\ muPrel D E muci0 p q)) /\
      b IN D /\ E b B
      ==> (muPrel D E muP b c <=> muPrel D E muP0 b c)`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "ciX")
   (CONJUNCTS_THEN2 (LABEL_TAC "PX")
    (CONJUNCTS_THEN2 (LABEL_TAC "Pci")
     (CONJUNCTS_THEN2 (LABEL_TAC "BP")
      (CONJUNCTS_THEN2 (LABEL_TAC "mch")
       (CONJUNCTS_THEN2 (LABEL_TAC "Pch")
        (CONJUNCTS_THEN2 (LABEL_TAC "mch0")
         (CONJUNCTS_THEN2 (LABEL_TAC "Pch0")
          (CONJUNCTS_THEN2 (LABEL_TAC "bD") (LABEL_TAC "bB")))))))))) THEN
  (* level 1: muci, muci0 agree on the atoms of a condition *)
  SUBGOAL_THEN
   `!p u z. p IN D /\ E p P /\ u IN D /\ z IN D /\ E u p
            ==> (eapply D (E:A->A->bool) muci u z <=> eapply D E muci0 u z)`
   (LABEL_TAC "ag1") THENL
   [REPEAT GEN_TAC THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "pD")
               (CONJUNCTS_THEN2 (LABEL_TAC "pP")
      (CONJUNCTS_THEN2 (LABEL_TAC "uD") (CONJUNCTS_THEN2 (LABEL_TAC "zD")
        (LABEL_TAC "up"))))) THEN
    SUBGOAL_THEN `(E:A->A->bool) u ci` (LABEL_TAC "uci") THENL
     [USE_THEN "Pci" (MP_TAC o SPECL [`p:A`;`u:A`]) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) u X` (LABEL_TAC "uX") THENL
     [USE_THEN "ciX" (MP_TAC o SPEC `u:A`) THEN
      ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    USE_THEN "mch" (MP_TAC o SPECL [`u:A`;`z:A`]) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "mch0" (MP_TAC o SPECL [`u:A`;`z:A`]) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "uX" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "uci" (fun th -> REWRITE_TAC[th]);
    ALL_TAC] THEN
  (* level 2: muP, muP0 agree on conditions *)
  SUBGOAL_THEN
   `!x y. x IN D /\ y IN D /\ E x P
          ==> (eapply D (E:A->A->bool) muP x y <=> eapply D E muP0 x y)`
   (LABEL_TAC "ag2") THENL
   [REPEAT GEN_TAC THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "xD")
               (CONJUNCTS_THEN2 (LABEL_TAC "yD")
      (LABEL_TAC "xP"))) THEN
    SUBGOAL_THEN `(E:A->A->bool) x X` (LABEL_TAC "xX") THENL
     [USE_THEN "PX" (MP_TAC o SPEC `x:A`) THEN
      ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    USE_THEN "Pch" (MP_TAC o SPECL [`x:A`;`y:A`]) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "Pch0" (MP_TAC o SPECL [`x:A`;`y:A`]) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "xX" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "xP" (fun th -> REWRITE_TAC[th]) THEN
    MATCH_MP_TAC MUPREL_CONG THEN
    MAP_EVERY X_GEN_TAC [`u:A`;`z:A`] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "uD")
               (CONJUNCTS_THEN2 (LABEL_TAC "zD")
      (LABEL_TAC "ux"))) THEN
    USE_THEN "ag1" (MP_TAC o SPECL [`x:A`;`u:A`;`z:A`]) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  (* level 3: the images of b agree *)
  MATCH_MP_TAC MUPREL_CONG THEN
  MAP_EVERY X_GEN_TAC [`x:A`;`y:A`] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "xD") (CONJUNCTS_THEN2 (LABEL_TAC "yD")
    (LABEL_TAC "xb"))) THEN
  SUBGOAL_THEN `(E:A->A->bool) x P` (LABEL_TAC "xP") THENL
   [USE_THEN "BP" (MP_TAC o SPECL [`b:A`;`x:A`]) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  USE_THEN "ag2" (MP_TAC o SPECL [`x:A`;`y:A`]) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                  DISCH_THEN ACCEPT_TAC]);;

(* ===================================================================== *)
(* S3-7 step 9c-R : the HS-tower rank layer + HSNAME_BOUND.                  *)
(* Clones of instage_bn_form / bnrank_form / BNAME_RANK / BNAME_RANK_UNIQUE /*)
(* BNAME_BOUND with ebnstage B -> hsstage B om P (slots                      *)
(* 2,8,9), recapp3/rec_form bname_step_form 3 -> recapp10/rec_form          *)
(* hs_step_form 10 (binds 10,11), witness slots relocated 11..13 -> 21..23.  *)
(* HSNAME_BOUND: a D-set of HS names lies in a single HS stage.              *)
(* ===================================================================== *)

(* "element (v 1) is in the HS stage (v 0)". *)
let instage_hs_form = new_definition
  `instage_hs_form = ?? 21 (recapp10_form (rec_form hs_step_form 10) 0 21 &&
                            1 %% 21)`;;

let HOLDS_INSTAGE_HS_FORM = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v instage_hs_form <=>
             ?y. y IN D /\ hsstage D E (v 2) (v 8) (v 9) (v 0) y /\ E (v 1) y)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[instage_hs_form; HOLDS_EX; HOLDS_AND; holds] THEN
  SUBGOAL_THEN
   `!y:A. y IN D
      ==> (holds D E ((21 |-> y) v)
             (recapp10_form (rec_form hs_step_form 10) 0 21) <=>
           hsstage D E (v 2) (v 8) (v 9) (v 0) y)`
  ASSUME_TAC THENL
   [X_GEN_TAC `y:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `valuation D ((21 |-> (y:A)) v)` ASSUME_TAC THENL
     [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
             (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC)); ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(21 |-> (y:A)) v`;
                  `0`; `21`] HOLDS_RECAPP10_HSSTEP) THEN
    ASM_REWRITE_TAC[ARITH_RULE
      `~(0 = 10) /\ ~(0 = 11) /\ ~(21 = 10) /\ ~(21 = 11)`] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN ASM_MESON_TAC[]);;

(* Rank in the HS tower: v 1 is the least stage-index whose HS stage       *)
(* contains v 0. *)
let hsrank_form = new_definition
  `hsrank_form = ordinal_form 1 &&
                 (?? 21 (recapp10_form (rec_form hs_step_form 10) 1 21 &&
                         0 %% 21)) &&
                 (!!- 22 1 (Not(?? 23 (recapp10_form (rec_form hs_step_form 10)
                                       22 23 && 0 %% 23))))`;;

let HOLDS_HSRANK_FORM = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v hsrank_form <=>
             eordinal D E (v 1) /\
             (?y. y IN D /\ hsstage D E (v 2) (v 8) (v 9) (v 1) y
              /\ E (v 0) y) /\
             (!c. c IN D /\ E c (v 1)
                  ==> ~(?y. y IN D /\ hsstage D E (v 2) (v 8) (v 9) c y /\
                            E (v 0) y)))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[hsrank_form] THEN
  SIMP_TAC[HOLDS_AND; HOLDS_EX; HOLDS_NOT; HOLDS_FORALLMEM;
           ARITH_RULE `~(22 = 1)`] THEN
  ASM_SIMP_TAC[HOLDS_ORDINAL_FORM] THEN
  REWRITE_TAC[holds] THEN
  SUBGOAL_THEN
   `!y:A. y IN D
      ==> (holds D E ((21 |-> y) v)
             (recapp10_form (rec_form hs_step_form 10) 1 21) <=>
           hsstage D E (v 2) (v 8) (v 9) (v 1) y)`
  ASSUME_TAC THENL
   [X_GEN_TAC `y:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `valuation D ((21 |-> (y:A)) v)` ASSUME_TAC THENL
     [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
             (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC)); ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(21 |-> (y:A)) v`;
                  `1`; `21`] HOLDS_RECAPP10_HSSTEP) THEN
    ASM_REWRITE_TAC[ARITH_RULE
      `~(1 = 10) /\ ~(1 = 11) /\ ~(21 = 10) /\ ~(21 = 11)`] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!c y:A. c IN D /\ y IN D
      ==> (holds D E ((23 |-> y) ((22 |-> c) v))
             (recapp10_form (rec_form hs_step_form 10) 22 23) <=>
           hsstage D E (v 2) (v 8) (v 9) c y)`
  ASSUME_TAC THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((23 |-> (y:A)) ((22 |-> (c:A)) v))`
    ASSUME_TAC THENL
     [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
             (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC)); ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
                  `(23 |-> (y:A)) ((22 |-> (c:A)) v)`;
                  `22`; `23`] HOLDS_RECAPP10_HSSTEP) THEN
    ASM_REWRITE_TAC[ARITH_RULE
      `~(22 = 10) /\ ~(22 = 11) /\ ~(23 = 10) /\ ~(23 = 11)`] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN ASM_MESON_TAC[]);;

(* Every HS name has a (least) HS-tower rank. *)
let HSNAME_RANK = prove
 (`!D (E:A->A->bool) B om P x.
        model D E ZF_AX /\ B IN D /\ om IN D /\ P IN D /\
        hsname D E B om P x /\ x IN D
        ==> ?a. a IN D /\ eordinal D E a /\
                (?y. y IN D /\ hsstage D E B om P a y /\ E x y) /\
                (!c. c IN D /\ E c a
                     ==> ~(?y. y IN D /\ hsstage D E B om P c y /\ E x y))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_ASSUM(MP_TAC o GEN_REWRITE_RULE I [hsname]) THEN
  DISCH_THEN(X_CHOOSE_THEN `a0:A` (X_CHOOSE_THEN `y0:A`
    (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th)))) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a0:A`] ESUC_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `sa0:A`) THEN
  SUBGOAL_THEN `(sa0:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) sa0` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_ESUC]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) a0 sa0` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_MEMBER]; ALL_TAC] THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  ABBREV_TAC `vh = (9 |-> (P:A)) ((8 |-> (om:A)) ((2 |-> (B:A)) v0))` THEN
  SUBGOAL_THEN
   `valuation D (vh:num->A) /\ (vh:num->A) 2 = B /\ vh 8 = om /\ vh 9 = P`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vh" THEN REPEAT CONJ_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD];
      REWRITE_TAC[VALMOD; ARITH_EQ];
      REWRITE_TAC[VALMOD; ARITH_EQ];
      REWRITE_TAC[VALMOD; ARITH_EQ]];
    ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((1 |-> (x:A)) vh)` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_SEPARATION) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`instage_hs_form`; `0`; `(1 |-> (x:A)) vh`; `sa0:A`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ss:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "sch"))) THEN
  SUBGOAL_THEN
   `!t:A. t IN D
      ==> ((E:A->A->bool) t ss <=>
           E t sa0 /\ ?y. y IN D /\ hsstage D E B om P t y /\ E x y)`
  (LABEL_TAC "sch2") THENL
   [X_GEN_TAC `t:A` THEN DISCH_TAC THEN
    USE_THEN "sch" (MP_TAC o SPEC `t:A`) THEN ANTS_TAC THENL
     [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
                  `(0 |-> (t:A)) ((1 |-> (x:A)) vh)`]
          HOLDS_INSTAGE_HS_FORM) THEN
    ANTS_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_FOUNDATION) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `ss:A`) THEN ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN EXISTS_TAC `a0:A` THEN
    SUBGOAL_THEN `(a0:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "sch2" (MP_TAC o SPEC `a0:A`) THEN ANTS_TAC THENL
     [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `a:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "min")))) THEN
  SUBGOAL_THEN
   `(E:A->A->bool) a sa0 /\ ?y. y IN D /\ hsstage D E B om P a y /\ E x y`
  STRIP_ASSUME_TAC THENL
   [USE_THEN "sch2" (MP_TAC o SPEC `a:A`) THEN ANTS_TAC THENL
     [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(fst(EQ_IMP_RULE th))) THEN
    DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  EXISTS_TAC `a:A` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
  CONJ_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
  X_GEN_TAC `c:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN `(E:A->A->bool) c sa0` ASSUME_TAC THENL
   [ASM_MESON_TAC[eordinal; etransitive; esubset]; ALL_TAC] THEN
  USE_THEN "min" (MP_TAC o SPEC `c:A`) THEN ASM_REWRITE_TAC[] THEN
  DISCH_TAC THEN
  USE_THEN "sch2" (MP_TAC o SPEC `c:A`) THEN ANTS_TAC THENL
   [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN ASM_MESON_TAC[]);;

(* HS rank is unique. *)
let HSNAME_RANK_UNIQUE = prove
 (`!D (E:A->A->bool) B om P x a a'.
        model D E ZF_AX /\
        eordinal D E a /\
        (?y. y IN D /\ hsstage D E B om P a y /\ E x y) /\
        (!c. c IN D /\ E c a
             ==> ~(?y. y IN D /\ hsstage D E B om P c y /\ E x y)) /\
        eordinal D E a' /\
        (?y. y IN D /\ hsstage D E B om P a' y /\ E x y) /\
        (!c. c IN D /\ E c a'
             ==> ~(?y. y IN D /\ hsstage D E B om P c y /\ E x y))
        ==> a = a'`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `a':A`]
        EORDINAL_TRICHOTOMY) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
  ASM_MESON_TAC[EORDINAL_IN]);;

(* HSNAME_BOUND: a D-set all of whose members are HS names has a common     *)
(* bounding HS stage (rank function by REPLACEMENT along hsrank_form ->     *)
(* union of ranks -> its stage -> EHSSTAGE_MONO places every element).      *)
let HSNAME_BOUND = prove
 (`!D (E:A->A->bool) B om P pl.
        model D E ZF_AX /\ B IN D /\ om IN D /\ P IN D /\ pl IN D /\
        (!z. z IN D /\ E z pl ==> hsname D E B om P z)
        ==> ?c yc. c IN D /\ yc IN D /\ eordinal D E c /\
                   hsstage D E B om P c yc /\
                   !z. z IN D /\ E z pl ==> E z yc`,
  REPEAT GEN_TAC THEN DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
     (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
      (LABEL_TAC "allc")))))) THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  ABBREV_TAC `vh = (9 |-> (P:A)) ((8 |-> (om:A)) ((2 |-> (B:A)) v0))` THEN
  SUBGOAL_THEN
   `valuation D (vh:num->A) /\ (vh:num->A) 2 = B /\ vh 8 = om /\ vh 9 = P`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vh" THEN REPEAT CONJ_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD];
      REWRITE_TAC[VALMOD; ARITH_EQ];
      REWRITE_TAC[VALMOD; ARITH_EQ];
      REWRITE_TAC[VALMOD; ARITH_EQ]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!z w:A. z IN D /\ w IN D
        ==> (holds D E ((1 |-> w) ((0 |-> z) vh)) hsrank_form <=>
             eordinal D E w /\
             (?y. y IN D /\ hsstage D E B om P w y /\ E z y) /\
             (!c. c IN D /\ E c w
                  ==> ~(?y. y IN D /\ hsstage D E B om P c y /\ E z y)))`
  (LABEL_TAC "hrk") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
                  `(1 |-> (w:A)) ((0 |-> (z:A)) vh)`]
          HOLDS_HSRANK_FORM) THEN
    ANTS_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_REPLACEMENT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`hsrank_form`; `0`; `1`; `vh:num->A`; `pl:A`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[ARITH_EQ] THEN
    X_GEN_TAC `z:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `hsname D (E:A->A->bool) B om P z` ASSUME_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `om:A`; `P:A`; `z:A`]
      HSNAME_RANK) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `a:A` (fun th ->
      MAP_EVERY ASSUME_TAC (CONJUNCTS th))) THEN
    EXISTS_TAC `a:A` THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `w':A` THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `eordinal D (E:A->A->bool) w' /\
      (?y. y IN D /\ hsstage D E B om P w' y /\ E z y) /\
      (!c. c IN D /\ E c w'
           ==> ~(?y. y IN D /\ hsstage D E B om P c y /\ E z y))`
    STRIP_ASSUME_TAC THENL
     [USE_THEN "hrk" (MP_TAC o SPECL [`z:A`; `w':A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> MP_TAC(fst(EQ_IMP_RULE th))) THEN
      DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `om:A`; `P:A`; `z:A`;
                  `w':A`; `a:A`] HSNAME_RANK_UNIQUE) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `bb:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "bch"))) THEN
  SUBGOAL_THEN
   `!w:A. w IN D /\ (E:A->A->bool) w bb ==> eordinal D E w`
  (LABEL_TAC "bord") THENL
   [X_GEN_TAC `w:A` THEN STRIP_TAC THEN
    USE_THEN "bch" (MP_TAC o SPEC `w:A`) THEN ANTS_TAC THENL
     [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(fst(EQ_IMP_RULE th))) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC) THEN
    USE_THEN "hrk" (MP_TAC o SPECL [`z:A`; `w:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(fst(EQ_IMP_RULE th))) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th)) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `?b0:A. eunion D (E:A->A->bool) bb b0`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EUNION_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(b0:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EUNION_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) b0` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `bb:A`; `b0:A`]
          EORDINAL_EUNION) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `?yb:A. yb IN D /\ hsstage D (E:A->A->bool) B om P b0 yb`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[HSSTAGE_EXISTS]; ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`b0:A`; `yb:A`] THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `z:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN `hsname D (E:A->A->bool) B om P z` ASSUME_TAC THENL
   [ASM_MESON_TAC[]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `om:A`; `P:A`; `z:A`]
    HSNAME_RANK) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `a:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2
      (X_CHOOSE_THEN `ya:A` STRIP_ASSUME_TAC)
      (LABEL_TAC "amin"))))) THEN
  SUBGOAL_THEN `(E:A->A->bool) a bb` ASSUME_TAC THENL
   [USE_THEN "bch" (MP_TAC o SPEC `a:A`) THEN ANTS_TAC THENL
     [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "hrk" (MP_TAC o SPECL [`z:A`; `a:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) a b0` ASSUME_TAC THENL
   [REWRITE_TAC[esubset] THEN X_GEN_TAC `t:A` THEN STRIP_TAC THEN
    FIRST_ASSUM(MP_TAC o GEN_REWRITE_RULE I [eunion]) THEN
    DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (MP_TAC o SPEC `t:A`)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EXISTS_TAC `a:A` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `b0:A`]
        EORDINAL_SUBSET_MEMBER) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  STRIP_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `om:A`; `P:A`; `b0:A`;
                  `a:A`; `yb:A`; `ya:A`; `z:A`] EHSSTAGE_MONO) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ASM_MESON_TAC[HSSTAGE_UNIQUE; EORDINAL_IN]]);;

(* S3-7 step 9c-S : ECHECK_HSNAME_STEP / ECHECK_HSNAME_SUCC -- a check-name   *)
(* v = x^ that is symmetric (ehssym) and whose domain elements all lie in HS *)
(* stages below a lands in the HS stage at a (hence is an HS name).  Clones  *)
(* of ECHECK_BNAME_STEP/SUCC: EBNSTAGE_CHAR ->                               *)
(* HSSTAGE_CHAR, ebnfuns -> ehsfuns, membership ehsmem = ebnmem /\ ehssym    *)
(* (ebnmem half by ECHECK_EBNMEM verbatim, ehssym half supplied as a hyp).   *)
let ECHECK_HSNAME_STEP = prove
 (`!D (E:A->A->bool) B om P onebee x v a ya.
     model D E ZF_AX /\ B IN D /\ om IN D /\ P IN D /\
     onebee IN D /\ E onebee B /\
     eordinal D E a /\ ya IN D /\ hsstage D E B om P a ya /\
     echeck D E onebee x v /\ ehssym D E B om P v /\
     (!u ww z. u IN D /\ ww IN D /\ eopair D E u ww z /\ E z v
               ==> ?b yb. b IN D /\ E b a /\ yb IN D /\
                          hsstage D E B om P b yb /\ E u yb)
     ==> E v ya`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(v:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`om:A`;`P:A`;`a:A`;`ya:A`]
    HSSTAGE_CHAR) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `w:A` (CONJUNCTS_THEN2 (LABEL_TAC "wD")
    (CONJUNCTS_THEN2 (LABEL_TAC "wchar") (LABEL_TAC "funs")))) THEN
  SUBGOAL_THEN `ebnmem D (E:A->A->bool) B w v` ASSUME_TAC THENL
   [MATCH_MP_TAC ECHECK_EBNMEM THEN
    MAP_EVERY EXISTS_TAC [`onebee:A`;`x:A`] THEN
    ASM_REWRITE_TAC[] THEN
    REPEAT STRIP_TAC THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  USE_THEN "funs" (fun th ->
    MP_TAC(SPEC `v:A` (CONJUNCT2 (REWRITE_RULE[ehsfuns] th)))) THEN
  ASM_REWRITE_TAC[ehsmem]);;

let ECHECK_HSNAME_SUCC = prove
 (`!D (E:A->A->bool) B om P onebee x v a ya.
     model D E ZF_AX /\ B IN D /\ om IN D /\ P IN D /\
     onebee IN D /\ E onebee B /\
     eordinal D E a /\ ya IN D /\ hsstage D E B om P a ya /\
     echeck D E onebee x v /\ ehssym D E B om P v /\
     (!u ww z. u IN D /\ ww IN D /\ eopair D E u ww z /\ E z v
               ==> ?b yb. b IN D /\ E b a /\ yb IN D /\
                          hsstage D E B om P b yb /\ E u yb)
     ==> hsname D E B om P v`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(E:A->A->bool) v ya` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`om:A`;`P:A`;`onebee:A`;
                  `x:A`;`v:A`;`a:A`;`ya:A`] ECHECK_HSNAME_STEP) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  ASM_MESON_TAC[HSNAME_STAGE; EORDINAL_IN]);;

(* S3-7 step 9c-E : empty-support helpers.                                   *)
(* The empty set is a bijection onto itself.                               *)
let EBIJ_EEMPTY = prove
 (`!D (E:A->A->bool) e. eempty D E e ==> ebij D E e e e`,
  REWRITE_TAC[eempty; ebij; eapply] THEN MESON_TAC[EOPAIR_IN]);;

(* ===================================================================== *)
(* S3-7 step 9c-G : goodhs object formula + HOLDS_GOODHS + GOODHS_SEM.      *)
(* Generated from goodfix2 / HOLDS_GOODFIX2 / GOODFIX2_SEM (9a) by the      *)
(* substitution  autnfix_form 90 -> hsname_form 90  and  eautn (v 2) (v 3)  *)
(* vv vv -> hsname (v 2) (v 8) (v 9) vv  (HS params B,om,P at slots 2,8,9). *)
(* ===================================================================== *)
let goodhs = new_definition
  `goodhs =
     ?? 82 (apply_form 81 0 82 &&
            !!- 88 82 (!! 89 (!! 90 (opair_form 89 90 88 -->
                hsname_form 90))))`;;

let HOLDS_GOODHS = prove
 (`!D (E:A->A->bool) v.
     model D E ZF_AX /\ valuation D v
     ==> (holds D E v goodhs <=>
          ?stg. stg IN D /\ eapply D E (v 81) (v 0) stg /\
                !pp. pp IN D /\ E pp stg
                     ==> !x vv. x IN D /\ vv IN D /\ eopair D E x vv pp
                                ==> hsname D E (v 2) (v 8) (v 9) vv)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!n. (v:num->A) n IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[goodhs; HOLDS_EX; HOLDS_AND] THEN
  MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s))
     ==> ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
  X_GEN_TAC `stg:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `valuation D ((82 |-> (stg:A)) v)` ASSUME_TAC THENL
   [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
           (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC)); ALL_TAC] THEN
  SUBGOAL_THEN
   `holds D E ((82 |-> (stg:A)) v) (apply_form 81 0 82) <=>
    eapply D E (v 81) (v 0) stg`
  (fun th -> REWRITE_TAC[th]) THENL
   [ASM_SIMP_TAC[HOLDS_APPLY_FORM] THEN
    REWRITE_TAC[VALMOD; ARITH_EQ]; ALL_TAC] THEN
  MATCH_MP_TAC(TAUT `(y <=> z) ==> ((x /\ y) <=> (x /\ z))`) THEN
  ASM_SIMP_TAC[HOLDS_FORALLMEM; ARITH_RULE `~(88 = 82)`] THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN
  MATCH_MP_TAC(MESON[]
    `(!pp:A. M pp ==> (P pp <=> Q pp))
     ==> ((!pp. M pp ==> P pp) <=> (!pp. M pp ==> Q pp))`) THEN
  X_GEN_TAC `pp:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((88 |-> (pp:A)) ((82 |-> (stg:A)) v))`
      ASSUME_TAC THENL
   [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
           (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC)); ALL_TAC] THEN
  REWRITE_TAC[holds] THEN
  MATCH_MP_TAC(MESON[]
    `(!x vv:A. x IN D /\ vv IN D ==> (H x vv <=> (R x vv ==> S vv)))
     ==> ((!x. x IN D ==> !vv. vv IN D ==> H x vv) <=>
          (!x vv. x IN D /\ vv IN D /\ R x vv ==> S vv))`) THEN
  MAP_EVERY X_GEN_TAC [`x:A`; `vv:A`] THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `valuation D ((90 |-> (vv:A)) ((89 |-> (x:A))
       ((88 |-> (pp:A)) ((82 |-> (stg:A)) v))))`
  ASSUME_TAC THENL [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
      (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC)); ALL_TAC] THEN
  MATCH_MP_TAC(TAUT `(a <=> c) /\ (b <=> d) ==> ((a ==> b) <=> (c ==> d))`) THEN
  CONJ_TAC THENL
   [ASM_SIMP_TAC[HOLDS_OPAIR_FORM] THEN REWRITE_TAC[VALMOD; ARITH_EQ];
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;
      `(90 |-> (vv:A)) ((89 |-> (x:A)) ((88 |-> (pp:A)) ((82 |-> (stg:A)) v)))`;
      `90`] HOLDS_HSNAME_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN ARITH_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD; ARITH_EQ]]);;

let GOODHS_SEM = prove
 (`!D (E:A->A->bool) onebee sa rc v0 b.
      model D E ZF_AX /\ onebee IN D /\ eordinal D E sa /\
      rc IN D /\ valuation D v0 /\
      (!pp. pp IN D
            ==> (E pp rc <=>
                 ?b' z'. b' IN D /\ z' IN D /\ E b' sa /\
                         echecktower D E onebee b' z' /\
                             eopair D E b' z' pp)) /\
      b IN D /\ E b sa
      ==> (holds D E ((0 |-> b) ((81 |-> rc) v0)) goodhs <=>
           !zb pp x vv.
              zb IN D /\ pp IN D /\ x IN D /\ vv IN D /\
              echecktower D E onebee b zb /\ E pp zb /\ eopair D E x vv pp
              ==> hsname D E (v0 2) (v0 8) (v0 9) vv)`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 (LABEL_TAC "rcc")
        (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC))))))) THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) b` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((0 |-> (b:A)) ((81 |-> (rc:A)) v0))`
  ASSUME_TAC THENL [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
      (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC)); ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;
    `(0 |-> (b:A)) ((81 |-> (rc:A)) v0)`] HOLDS_GOODHS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `stg:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "allp")))) THEN
    SUBGOAL_THEN `echecktower D (E:A->A->bool) onebee b stg` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;
        `echecktower D (E:A->A->bool) onebee`;`sa:A`;`rc:A`;`b:A`;`stg:A`]
        EGRAPH_APPLY) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> MP_TAC(EQ_MP th
        (ASSUME `eapply D (E:A->A->bool) rc b stg`))) THEN
      DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC ACCEPT_TAC);
      ALL_TAC] THEN
    MAP_EVERY X_GEN_TAC [`zb:A`;`pp:A`;`x:A`;`vv:A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN `zb:A = stg` SUBST_ALL_TAC THENL
     [ASM_MESON_TAC[ECHECKTOWER_UNIQUE]; ALL_TAC] THEN
    USE_THEN "allp" (MP_TAC o SPEC `pp:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPECL [`x:A`;`vv:A`]) THEN
    ASM_REWRITE_TAC[];
    DISCH_THEN(LABEL_TAC "sem") THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`b:A`]
      ECHECKTOWER_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `stgw:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `stgw:A` THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `eapply D (E:A->A->bool) rc b stgw` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;
        `echecktower D (E:A->A->bool) onebee`;`sa:A`;`rc:A`;`b:A`;`stgw:A`]
        EGRAPH_APPLY) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `pp:A` THEN STRIP_TAC THEN
    MAP_EVERY X_GEN_TAC [`x:A`;`vv:A`] THEN STRIP_TAC THEN
    USE_THEN "sem" (MP_TAC o SPECL [`stgw:A`;`pp:A`;`x:A`;`vv:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]]);;

(* ===================================================================== *)
(* S3-7 / 9d + 9e : helpers for real names and pairing.                    *)
(* 9d: ESING_FINITE ({al} finite), HSSTAGE_INTRO (a symmetric function with *)
(*     HS-bounded domain and B-values lands in the next HS stage).          *)
(* 9e: autN congruence in autB (APRREL/AUTNSTEP/EATTEMPT/EREC/AUTNSTAGE/    *)
(*     EAUTN_CONG + BUNDLE_AGREE: eautn reads autB only through its graph); *)
(*     BNSTAGE_INTRO + HSNAME_BNAME (every HS name is a B-name); pair names *)
(*     UPN_EXISTS/ISFUN/BNAME, HSNAME_SYM, AUTN_UPN (autN-equivariance).    *)
(* ===================================================================== *)
(* ===================================================================== *)
(* S3-7 step 9d-0 : ESING_FINITE + HSSTAGE_INTRO (general helpers).         *)
(* ESING_FINITE: the singleton {al} exists and is finite (bijection         *)
(*   {<0,al>} : 1 -> {al}, 1 = esuc 0 IN om) -- the support of rdot_al.     *)
(* HSSTAGE_INTRO: a symmetric function f whose pairs are <u,c> with u in an *)
(*   HS stage below a and c IN B lies in the HS stage at a (HSSTAGE_CHAR +  *)
(*   ehsfuns: ehsmem = ebnmem /\ ehssym; ebnmem via ECROSS_EXISTS).          *)
(* ===================================================================== *)
let ESING_FINITE = prove
 (`!D (E:A->A->bool) om al.
      model D E ZF_AX /\ eomega D E om /\ al IN D
      ==> ?e. e IN D /\ (!w. w IN D ==> (E w e <=> w = al)) /\
              (?n. n IN D /\ E n om /\ ?f. ebij D E f n e)`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
    (CONJUNCTS_THEN2 (LABEL_TAC "eom") (LABEL_TAC "alD"))) THEN
  (* e = {al} *)
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`al:A`;`al:A`] EPAIR_EXISTS) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `e:A` (LABEL_TAC "ep")) THEN
  SUBGOAL_THEN `(e:A) IN D` (LABEL_TAC "eD") THENL
   [USE_THEN "ep" (ACCEPT_TAC o MATCH_MP EPAIR_IN); ALL_TAC] THEN
  SUBGOAL_THEN `!w:A. w IN D ==> ((E:A->A->bool) w e <=> w = al)`
    (LABEL_TAC "ech") THENL
   [X_GEN_TAC `w:A` THEN DISCH_TAC THEN
    USE_THEN "ep" (MP_TAC o SPEC `w:A` o CONJUNCT2 o REWRITE_RULE[epair]) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN MESON_TAC[];
    ALL_TAC] THEN
  (* n = {e0} = esuc e0 *)
  USE_THEN "modl" (X_CHOOSE_THEN `e0:A` (LABEL_TAC "emp") o
                   MATCH_MP EEMPTY_EXISTS) THEN
  SUBGOAL_THEN `(e0:A) IN D` (LABEL_TAC "e0D") THENL
   [USE_THEN "emp" (ACCEPT_TAC o MATCH_MP EEMPTY_IN); ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`e0:A`] ESUC_EXISTS) THEN
  ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `n:A` (LABEL_TAC "nsuc")) THEN
  SUBGOAL_THEN `(n:A) IN D` (LABEL_TAC "nD") THENL
   [USE_THEN "nsuc" (ACCEPT_TAC o MATCH_MP ESUC_IN); ALL_TAC] THEN
  SUBGOAL_THEN `!w:A. w IN D ==> ((E:A->A->bool) w n <=> w = e0)`
    (LABEL_TAC "nch") THENL
   [X_GEN_TAC `w:A` THEN DISCH_TAC THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`e0:A`;`n:A`;`w:A`] ESUC_E) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "emp" (MP_TAC o SPEC `w:A` o CONJUNCT2 o REWRITE_RULE[eempty]) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]);
    ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) n om` (LABEL_TAC "nom") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`om:A`;`e0:A`;`n:A`]
           EOMEGA_SUC) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`om:A`;`e0:A`] EOMEGA_EMPTY) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN ACCEPT_TAC];
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  (* f = {<e0,al>} *)
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`e0:A`;`al:A`] EOPAIR_EXISTS) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `pr:A` (LABEL_TAC "prp")) THEN
  SUBGOAL_THEN `(pr:A) IN D` (LABEL_TAC "prD") THENL
   [USE_THEN "prp" (ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`pr:A`;`pr:A`] EPAIR_EXISTS) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `f:A` (LABEL_TAC "fp")) THEN
  SUBGOAL_THEN `(f:A) IN D` (LABEL_TAC "fD") THENL
   [USE_THEN "fp" (ACCEPT_TAC o MATCH_MP EPAIR_IN); ALL_TAC] THEN
  SUBGOAL_THEN `!z:A. z IN D ==> ((E:A->A->bool) z f <=> z = pr)`
    (LABEL_TAC "fch") THENL
   [X_GEN_TAC `z:A` THEN DISCH_TAC THEN
    USE_THEN "fp" (MP_TAC o SPEC `z:A` o CONJUNCT2 o REWRITE_RULE[epair]) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!k t:A. k IN D /\ t IN D
            ==> (eapply D (E:A->A->bool) f k t <=> k = e0 /\ t = al)`
    (LABEL_TAC "fap") THENL
   [REPEAT GEN_TAC THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "kD") (LABEL_TAC "tD")) THEN
    REWRITE_TAC[eapply] THEN EQ_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `z:A` (CONJUNCTS_THEN2 (LABEL_TAC "kz")
        (LABEL_TAC "zf"))) THEN
      SUBGOAL_THEN `(z:A) IN D` (LABEL_TAC "zD") THENL
       [USE_THEN "kz" (ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
      SUBGOAL_THEN `z:A = pr` SUBST_ALL_TAC THENL
       [USE_THEN "fch" (MP_TAC o SPEC `z:A`) THEN
        ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
        DISCH_THEN(fun th -> USE_THEN "zf" (ACCEPT_TAC o EQ_MP th));
        ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`k:A`;`t:A`;`e0:A`;`al:A`;
                    `pr:A`] EOPAIR_INJ) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN ACCEPT_TAC];
      DISCH_THEN(CONJUNCTS_THEN2 SUBST1_TAC SUBST1_TAC) THEN
      EXISTS_TAC `pr:A` THEN CONJ_TAC THENL
          [USE_THEN "prp" ACCEPT_TAC; ALL_TAC] THEN
      USE_THEN "fch" (MP_TAC o SPEC `pr:A`) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th])];
    ALL_TAC] THEN
  EXISTS_TAC `e:A` THEN REPEAT CONJ_TAC THENL
   [USE_THEN "eD" ACCEPT_TAC; USE_THEN "ech" ACCEPT_TAC; ALL_TAC] THEN
  EXISTS_TAC `n:A` THEN REPEAT CONJ_TAC THENL
   [USE_THEN "nD" ACCEPT_TAC; USE_THEN "nom" ACCEPT_TAC; ALL_TAC] THEN
  EXISTS_TAC `f:A` THEN REWRITE_TAC[ebij] THEN REPEAT CONJ_TAC THENL
   [USE_THEN "fD" ACCEPT_TAC;
    (* bnd *)
    MAP_EVERY X_GEN_TAC [`k:A`;`t:A`] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "kD")
               (CONJUNCTS_THEN2 (LABEL_TAC "tD")
      (LABEL_TAC "ap"))) THEN
    USE_THEN "fap" (MP_TAC o SPECL [`k:A`;`t:A`]) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "ap" (MP_TAC o EQ_MP th)) THEN
    DISCH_THEN(CONJUNCTS_THEN2 SUBST_ALL_TAC SUBST_ALL_TAC) THEN
    CONJ_TAC THENL
     [USE_THEN "nch" (MP_TAC o SPEC `e0:A`) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN(fun th -> REWRITE_TAC[th])];
      USE_THEN "ech" (MP_TAC o SPEC `al:A`) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN(fun th -> REWRITE_TAC[th])]];
    (* tot *)
    X_GEN_TAC `k:A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "kD") (LABEL_TAC "kn")) THEN
    SUBGOAL_THEN `k:A = e0` SUBST_ALL_TAC THENL
     [USE_THEN "nch" (MP_TAC o SPEC `k:A`) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> USE_THEN "kn" (ACCEPT_TAC o EQ_MP th));
      ALL_TAC] THEN
    EXISTS_TAC `al:A` THEN REPEAT CONJ_TAC THENL
     [USE_THEN "alD" ACCEPT_TAC;
      USE_THEN "ech" (MP_TAC o SPEC `al:A`) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN(fun th -> REWRITE_TAC[th])];
      USE_THEN "fap" (MP_TAC o SPECL [`e0:A`;`al:A`]) THEN
      ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN(fun th -> REWRITE_TAC[th])]];
    (* sv *)
    MAP_EVERY X_GEN_TAC [`k:A`;`t:A`;`t':A`] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "kD")
               (CONJUNCTS_THEN2 (LABEL_TAC "tD")
      (CONJUNCTS_THEN2 (LABEL_TAC "t'D") (CONJUNCTS_THEN2 (LABEL_TAC "a1")
        (LABEL_TAC "a2"))))) THEN
    USE_THEN "fap" (MP_TAC o SPECL [`k:A`;`t:A`]) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "a1" (MP_TAC o CONJUNCT2 o EQ_MP th)) THEN
    USE_THEN "fap" (MP_TAC o SPECL [`k:A`;`t':A`]) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "a2" (MP_TAC o CONJUNCT2 o EQ_MP th)) THEN
    MESON_TAC[];
    (* inj *)
    MAP_EVERY X_GEN_TAC [`k:A`;`k':A`;`t:A`] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "kD")
               (CONJUNCTS_THEN2 (LABEL_TAC "k'D")
      (CONJUNCTS_THEN2 (LABEL_TAC "tD") (CONJUNCTS_THEN2 (LABEL_TAC "a1")
        (LABEL_TAC "a2"))))) THEN
    USE_THEN "fap" (MP_TAC o SPECL [`k:A`;`t:A`]) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "a1" (MP_TAC o CONJUNCT1 o EQ_MP th)) THEN
    USE_THEN "fap" (MP_TAC o SPECL [`k':A`;`t:A`]) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "a2" (MP_TAC o CONJUNCT1 o EQ_MP th)) THEN
    MESON_TAC[];
    (* ont *)
    X_GEN_TAC `t:A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "tD") (LABEL_TAC "te")) THEN
    SUBGOAL_THEN `t:A = al` SUBST_ALL_TAC THENL
     [USE_THEN "ech" (MP_TAC o SPEC `t:A`) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> USE_THEN "te" (ACCEPT_TAC o EQ_MP th));
      ALL_TAC] THEN
    EXISTS_TAC `e0:A` THEN REPEAT CONJ_TAC THENL
     [USE_THEN "e0D" ACCEPT_TAC;
      USE_THEN "nch" (MP_TAC o SPEC `e0:A`) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN(fun th -> REWRITE_TAC[th])];
      USE_THEN "fap" (MP_TAC o SPECL [`e0:A`;`al:A`]) THEN
      ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN(fun th -> REWRITE_TAC[th])]]]);;

let HSSTAGE_INTRO = prove
 (`!D (E:A->A->bool) B om P f a ya.
      model D E ZF_AX /\ B IN D /\ om IN D /\ P IN D /\
      eordinal D E a /\ ya IN D /\ hsstage D E B om P a ya /\
      f IN D /\ eisfun D E f /\
      (!z. z IN D /\ E z f
           ==> ?u c. u IN D /\ c IN D /\ eopair D E u c z /\ E c B /\
                     ?b yb. b IN D /\ E b a /\ yb IN D /\
                            hsstage D E B om P b yb /\ E u yb) /\
      ehssym D E B om P f
      ==> E f ya`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
   (CONJUNCTS_THEN2 (LABEL_TAC "BD")
    (CONJUNCTS_THEN2 (LABEL_TAC "omD")
     (CONJUNCTS_THEN2 (LABEL_TAC "PD")
      (CONJUNCTS_THEN2 (LABEL_TAC "aord")
       (CONJUNCTS_THEN2 (LABEL_TAC "yaD")
        (CONJUNCTS_THEN2 (LABEL_TAC "hsa")
         (CONJUNCTS_THEN2 (LABEL_TAC "fD")
          (CONJUNCTS_THEN2 (LABEL_TAC "ffun")
           (CONJUNCTS_THEN2 (LABEL_TAC "fdom") (LABEL_TAC "fsym"))))))))))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`om:A`;`P:A`;`a:A`;`ya:A`]
    HSSTAGE_CHAR) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `w:A` (CONJUNCTS_THEN2 (LABEL_TAC "wD")
    (CONJUNCTS_THEN2 (LABEL_TAC "wchar") (LABEL_TAC "funs")))) THEN
  USE_THEN "funs" (MP_TAC o SPEC `f:A` o CONJUNCT2 o REWRITE_RULE[ehsfuns]) THEN
  ANTS_TAC THENL [USE_THEN "fD" ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[ehsmem; ebnmem] THEN REPEAT CONJ_TAC THENL
   [USE_THEN "ffun" ACCEPT_TAC;
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`B:A`] ECROSS_EXISTS) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `cr:A` (LABEL_TAC "crp")) THEN
    EXISTS_TAC `cr:A` THEN REPEAT CONJ_TAC THENL
     [USE_THEN "crp" (ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[ecross]);
      USE_THEN "crp" ACCEPT_TAC;
      REWRITE_TAC[esubset] THEN X_GEN_TAC `z:A` THEN
      DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "zD") (LABEL_TAC "zf")) THEN
      USE_THEN "fdom" (MP_TAC o SPEC `z:A`) THEN
      ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `u:A` (X_CHOOSE_THEN `c:A`
        (CONJUNCTS_THEN2 (LABEL_TAC "uD") (CONJUNCTS_THEN2 (LABEL_TAC "cD")
          (CONJUNCTS_THEN2 (LABEL_TAC "ucz") (CONJUNCTS_THEN2 (LABEL_TAC "cB")
            (LABEL_TAC "ulow"))))))) THEN
      SUBGOAL_THEN `(E:A->A->bool) u w` (LABEL_TAC "uw") THENL
       [USE_THEN "wchar" (MP_TAC o SPEC `u:A`) THEN
        ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        USE_THEN "ulow" (X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `yb:A`
          (CONJUNCTS_THEN2 (LABEL_TAC "bD") (CONJUNCTS_THEN2 (LABEL_TAC "ba")
            (CONJUNCTS_THEN2 (LABEL_TAC "ybD")
             (CONJUNCTS_THEN2 (LABEL_TAC "hsb")
              (LABEL_TAC "uyb"))))))) THEN
        MAP_EVERY EXISTS_TAC [`b:A`;`yb:A`] THEN
        REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
        ALL_TAC] THEN
      USE_THEN "crp" (MP_TAC o SPEC `z:A` o CONJUNCT2 o
                      REWRITE_RULE[ecross]) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MAP_EVERY EXISTS_TAC [`u:A`;`c:A`] THEN
      REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC];
    USE_THEN "fsym" ACCEPT_TAC]);;

(* ===================================================================== *)
(* S3-7 step 9e-0 : autN congruence in autB + universal ehssym elimination. *)
(* eautn reads autB ONLY through its eapply graph (aprrel inside autnstep,  *)
(* the erec step), so two autB with equal graphs induce the same autN.      *)
(* Hence ANY true bundle at s fixes an HS name (not just the ehssym         *)
(* witness) -- needed to combine supports of several names.                 *)
(* ===================================================================== *)
let APRREL_CONG = prove
 (`!D (E:A->A->bool) gmap h h' m m'.
     (!c c'. c IN D /\ c' IN D ==> (eapply D E h c c' <=> eapply D E h' c c'))
     ==> (aprrel D E gmap h m m' <=> aprrel D E gmap h' m m')`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN REWRITE_TAC[aprrel] THEN ASM_MESON_TAC[]);;

let AUTNSTEP_CONG = prove
 (`!D (E:A->A->bool) B autB autB' r y.
     (!c c'. c IN D /\ c' IN D
             ==> (eapply D E autB c c' <=> eapply D E autB' c c'))
     ==> (autnstep D E B autB r y <=> autnstep D E B autB' r y)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN REWRITE_TAC[autnstep] THEN
  SUBGOAL_THEN
   `!G m q:A. aprrel D (E:A->A->bool) G autB m q <=> aprrel D E G autB' m q`
   (fun th -> REWRITE_TAC[th]) THEN
  REPEAT GEN_TAC THEN MATCH_MP_TAC APRREL_CONG THEN FIRST_ASSUM ACCEPT_TAC);;

let EATTEMPT_CONG = prove
 (`!D (E:A->A->bool) q q' v v' g a.
     (!r y. r IN D /\ y IN D
            ==> (holds D E ((1 |-> y) ((0 |-> r) v)) q <=>
                 holds D E ((1 |-> y) ((0 |-> r) v')) q'))
     ==> (eattempt D E q v g a <=> eattempt D E q' v' g a)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN REWRITE_TAC[eattempt] THEN
      ASM_MESON_TAC[]);;

let EREC_CONG = prove
 (`!D (E:A->A->bool) q q' v v' a y.
     (!r y. r IN D /\ y IN D
            ==> (holds D E ((1 |-> y) ((0 |-> r) v)) q <=>
                 holds D E ((1 |-> y) ((0 |-> r) v')) q'))
     ==> (erec D E q v a y <=> erec D E q' v' a y)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  SUBGOAL_THEN `!g t:A. eattempt D (E:A->A->bool) q v g t <=>
      eattempt D E q' v' g t`
   (fun th -> REWRITE_TAC[erec; th]) THEN
  REPEAT GEN_TAC THEN MATCH_MP_TAC EATTEMPT_CONG THEN FIRST_ASSUM ACCEPT_TAC);;

let AUTNSTAGE_CONG = prove
 (`!D (E:A->A->bool) B autB autB' a y.
     model D E ZF_AX /\ B IN D /\ autB IN D /\ autB' IN D /\
     (!c c'. c IN D /\ c' IN D
             ==> (eapply D E autB c c' <=> eapply D E autB' c c'))
     ==> (autnstage D E B autB a y <=> autnstage D E B autB' a y)`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
             (CONJUNCTS_THEN2 (LABEL_TAC "BD")
    (CONJUNCTS_THEN2 (LABEL_TAC "aD") (CONJUNCTS_THEN2 (LABEL_TAC "a'D")
      (LABEL_TAC "gr"))))) THEN
  USE_THEN "modl" (X_CHOOSE_TAC `v0:num->A` o MATCH_MP VALUATION_EXISTS o
                   MATCH_MP MODEL_NONEMPTY) THEN
  SUBGOAL_THEN `valuation D ((2 |-> (B:A)) v0)` ASSUME_TAC THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((3 |-> (autB:A)) ((2 |-> (B:A)) v0))`
      (LABEL_TAC "v1") THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((3 |-> (autB':A)) ((2 |-> (B:A)) v0))`
      (LABEL_TAC "v2") THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`a:A`;`y:A`;
                `(3 |-> (autB:A)) ((2 |-> (B:A)) v0)`] AUTNSTAGE_EREC) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [USE_THEN "modl" ACCEPT_TAC; USE_THEN "v1" ACCEPT_TAC;
      REWRITE_TAC[VALMOD; ARITH_EQ]; REWRITE_TAC[VALMOD; ARITH_EQ]];
    DISCH_THEN SUBST1_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB':A`;`a:A`;`y:A`;
                `(3 |-> (autB':A)) ((2 |-> (B:A)) v0)`] AUTNSTAGE_EREC) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [USE_THEN "modl" ACCEPT_TAC; USE_THEN "v2" ACCEPT_TAC;
      REWRITE_TAC[VALMOD; ARITH_EQ]; REWRITE_TAC[VALMOD; ARITH_EQ]];
    DISCH_THEN SUBST1_TAC] THEN
  MATCH_MP_TAC EREC_CONG THEN
  MAP_EVERY X_GEN_TAC [`r:A`;`w:A`] THEN STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;
                `(3 |-> (autB:A)) ((2 |-> (B:A)) v0)`;`r:A`;`w:A`]
    HOLDS_AUTN_STEP_FORM) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                  DISCH_THEN SUBST1_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;
                `(3 |-> (autB':A)) ((2 |-> (B:A)) v0)`;`r:A`;`w:A`]
    HOLDS_AUTN_STEP_FORM) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                  DISCH_THEN SUBST1_TAC] THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN
  MATCH_MP_TAC AUTNSTEP_CONG THEN USE_THEN "gr" ACCEPT_TAC);;

let EAUTN_CONG = prove
 (`!D (E:A->A->bool) B autB autB' x v.
     model D E ZF_AX /\ B IN D /\ autB IN D /\ autB' IN D /\
     (!c c'. c IN D /\ c' IN D
             ==> (eapply D E autB c c' <=> eapply D E autB' c c'))
     ==> (eautn D E B autB x v <=> eautn D E B autB' x v)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  SUBGOAL_THEN `!a y:A. autnstage D (E:A->A->bool) B autB a y <=>
                        autnstage D E B autB' a y`
   (fun th -> REWRITE_TAC[eautn; th]) THEN
  REPEAT GEN_TAC THEN MATCH_MP_TAC AUTNSTAGE_CONG THEN FIRST_ASSUM ACCEPT_TAC);;

(* Two true bundles at the same s have the same autB graph. *)
let BUNDLE_AGREE = prove
 (`!D (E:A->A->bool) ci P B s muci muP autB muci' muP' autB'.
     (!u w. u IN D /\ w IN D
            ==> (eapply D E muci u w <=> E u ci /\ mucirel D E s u w)) /\
     (!p q. p IN D /\ q IN D
            ==> (eapply D E muP p q <=> E p P /\ muPrel D E muci p q)) /\
     (!b c. b IN D /\ c IN D
            ==> (eapply D E autB b c <=> E b B /\ muPrel D E muP b c)) /\
     (!u w. u IN D /\ w IN D
            ==> (eapply D E muci' u w <=> E u ci /\ mucirel D E s u w)) /\
     (!p q. p IN D /\ q IN D
            ==> (eapply D E muP' p q <=> E p P /\ muPrel D E muci' p q)) /\
     (!b c. b IN D /\ c IN D
            ==> (eapply D E autB' b c <=> E b B /\ muPrel D E muP' b c))
     ==> (!c c'. c IN D /\ c' IN D
                 ==> (eapply D E autB c c' <=> eapply D E autB' c c'))`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "m1") (CONJUNCTS_THEN2 (LABEL_TAC "P1")
    (CONJUNCTS_THEN2 (LABEL_TAC "a1") (CONJUNCTS_THEN2 (LABEL_TAC "m2")
      (CONJUNCTS_THEN2 (LABEL_TAC "P2") (LABEL_TAC "a2")))))) THEN
  SUBGOAL_THEN `!u w. u IN D /\ w IN D
                      ==> (eapply D (E:A->A->bool) muci u w <=>
                           eapply D E muci' u w)`
   (LABEL_TAC "gm") THENL
   [REPEAT GEN_TAC THEN DISCH_TAC THEN
    USE_THEN "m1" (fun th -> USE_THEN "m2" (fun th' ->
      REWRITE_TAC[MATCH_MP th (ASSUME `(u:A) IN D /\ (w:A) IN D`);
                  MATCH_MP th' (ASSUME `(u:A) IN D /\ (w:A) IN D`)]));
    ALL_TAC] THEN
  SUBGOAL_THEN `!p q. p IN D /\ q IN D
                      ==> (eapply D (E:A->A->bool) muP p q <=>
                           eapply D E muP' p q)`
   (LABEL_TAC "gP") THENL
   [REPEAT GEN_TAC THEN DISCH_TAC THEN
    USE_THEN "P1" (fun th -> USE_THEN "P2" (fun th' ->
      REWRITE_TAC[MATCH_MP th (ASSUME `(p:A) IN D /\ (q:A) IN D`);
                  MATCH_MP th' (ASSUME `(p:A) IN D /\ (q:A) IN D`)])) THEN
    MATCH_MP_TAC(TAUT `(b <=> c) ==> (a /\ b <=> a /\ c)`) THEN
    MATCH_MP_TAC MUPREL_CONG THEN REPEAT STRIP_TAC THEN
    USE_THEN "gm" MATCH_MP_TAC THEN CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  USE_THEN "a1" (fun th -> USE_THEN "a2" (fun th' ->
    REWRITE_TAC[MATCH_MP th (ASSUME `(c:A) IN D /\ (c':A) IN D`);
                MATCH_MP th' (ASSUME `(c:A) IN D /\ (c':A) IN D`)])) THEN
  MATCH_MP_TAC(TAUT `(b <=> c) ==> (a /\ b <=> a /\ c)`) THEN
  MATCH_MP_TAC MUPREL_CONG THEN REPEAT STRIP_TAC THEN
  USE_THEN "gP" MATCH_MP_TAC THEN CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC);;

(* ===================================================================== *)
(* S3-7 step 9e-3 : BNSTAGE_INTRO + HSNAME_BNAME -- every HS name is a      *)
(* B-name (the HS class is a subclass of V^B; needed for AUTN_TOTAL, bvalf).*)
(* Least-HS-rank counterexample, via SEPARATION over esuc(rank u) with      *)
(*   psi(a) = ?? 0 (hsrank_form && Not (bname_form 0))   (rank at slot 1)    *)
(* + ZF_FOUNDATION.  A minimal bad z has all domain elements of smaller HS   *)
(* rank, hence B-names; BNAME_BOUND + BNSTAGE_INTRO put z in a B-name stage. *)
(* ===================================================================== *)
let BNSTAGE_INTRO = prove
 (`!D (E:A->A->bool) B f a ya.
      model D E ZF_AX /\ B IN D /\
      eordinal D E a /\ ya IN D /\ ebnstage D E B a ya /\
      f IN D /\ eisfun D E f /\
      (!z. z IN D /\ E z f
           ==> ?u c. u IN D /\ c IN D /\ eopair D E u c z /\ E c B /\
                     ?b yb. b IN D /\ E b a /\ yb IN D /\
                            ebnstage D E B b yb /\ E u yb)
      ==> E f ya`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
   (CONJUNCTS_THEN2 (LABEL_TAC "BD")
    (CONJUNCTS_THEN2 (LABEL_TAC "aord")
     (CONJUNCTS_THEN2 (LABEL_TAC "yaD")
      (CONJUNCTS_THEN2 (LABEL_TAC "bna")
       (CONJUNCTS_THEN2 (LABEL_TAC "fD")
        (CONJUNCTS_THEN2 (LABEL_TAC "ffun") (LABEL_TAC "fdom")))))))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`a:A`;`ya:A`]
         EBNSTAGE_CHAR) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `w:A` (CONJUNCTS_THEN2 (LABEL_TAC "wD")
    (CONJUNCTS_THEN2 (LABEL_TAC "wchar") (LABEL_TAC "funs")))) THEN
  USE_THEN "funs" (MP_TAC o SPEC `f:A` o CONJUNCT2 o REWRITE_RULE[ebnfuns]) THEN
  ANTS_TAC THENL [USE_THEN "fD" ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[ebnmem] THEN CONJ_TAC THENL
   [USE_THEN "ffun" ACCEPT_TAC; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`B:A`] ECROSS_EXISTS) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `cr:A` (LABEL_TAC "crp")) THEN
  EXISTS_TAC `cr:A` THEN REPEAT CONJ_TAC THENL
   [USE_THEN "crp" (ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[ecross]);
    USE_THEN "crp" ACCEPT_TAC;
    REWRITE_TAC[esubset] THEN X_GEN_TAC `z:A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "zD") (LABEL_TAC "zf")) THEN
    USE_THEN "fdom" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `u:A` (X_CHOOSE_THEN `c:A`
      (CONJUNCTS_THEN2 (LABEL_TAC "uD") (CONJUNCTS_THEN2 (LABEL_TAC "cD")
        (CONJUNCTS_THEN2 (LABEL_TAC "ucz") (CONJUNCTS_THEN2 (LABEL_TAC "cB")
          (LABEL_TAC "ulow"))))))) THEN
    SUBGOAL_THEN `(E:A->A->bool) u w` (LABEL_TAC "uw") THENL
     [USE_THEN "wchar" (MP_TAC o SPEC `u:A`) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      USE_THEN "ulow" (X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `yb:A`
        (CONJUNCTS_THEN2 (LABEL_TAC "bD") (CONJUNCTS_THEN2 (LABEL_TAC "ba")
          (CONJUNCTS_THEN2 (LABEL_TAC "ybD") (CONJUNCTS_THEN2 (LABEL_TAC "bnb")
            (LABEL_TAC "uyb"))))))) THEN
      MAP_EVERY EXISTS_TAC [`b:A`;`yb:A`] THEN
      REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
      ALL_TAC] THEN
    USE_THEN "crp" (MP_TAC o SPEC `z:A` o CONJUNCT2 o REWRITE_RULE[ecross]) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MAP_EVERY EXISTS_TAC [`u:A`;`c:A`] THEN
    REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC]);;

let HSNAME_BNAME = prove
 (`!D (E:A->A->bool) B om P u.
      model D E ZF_AX /\ B IN D /\ om IN D /\ P IN D /\ u IN D /\
      hsname D E B om P u
      ==> bname D E B u`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
             (CONJUNCTS_THEN2 (LABEL_TAC "BD")
    (CONJUNCTS_THEN2 (LABEL_TAC "omD") (CONJUNCTS_THEN2 (LABEL_TAC "PD")
      (CONJUNCTS_THEN2 (LABEL_TAC "uD") (LABEL_TAC "hsu")))))) THEN
  MATCH_MP_TAC(TAUT `(~p ==> F) ==> p`) THEN DISCH_THEN(LABEL_TAC "nbu") THEN
  (* HS rank a0 of u, sa0 = esuc a0 *)
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`om:A`;`P:A`;`u:A`]
         HSNAME_RANK) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `a0:A` (CONJUNCTS_THEN2 (LABEL_TAC "a0D")
    (CONJUNCTS_THEN2 (LABEL_TAC "a0ord") (CONJUNCTS_THEN2 (LABEL_TAC "a0in")
      (LABEL_TAC "a0min"))))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`a0:A`] ESUC_EXISTS) THEN
  ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `sa0:A` (LABEL_TAC "suc")) THEN
  SUBGOAL_THEN `(sa0:A) IN D` (LABEL_TAC "sa0D") THENL
   [USE_THEN "suc" (ACCEPT_TAC o MATCH_MP ESUC_IN); ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) sa0` (LABEL_TAC "sa0ord") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`a0:A`;`sa0:A`] EORDINAL_ESUC) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) a0 sa0` (LABEL_TAC "a0sa0") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`a0:A`;`sa0:A`] ESUC_MEMBER) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  (* valuation carrying B, om, P at slots 2, 8, 9 *)
  USE_THEN "modl" (X_CHOOSE_TAC `v0:num->A` o MATCH_MP VALUATION_EXISTS o
                   MATCH_MP MODEL_NONEMPTY) THEN
  SUBGOAL_THEN
   `valuation D ((9 |-> (P:A)) ((8 |-> (om:A)) ((2 |-> (B:A)) v0)))`
   (LABEL_TAC "vh") THENL
   [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
           (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC)); ALL_TAC] THEN
  (* S = {a IN sa0 | some z of HS rank a is not a B-name} *)
  USE_THEN "modl" (MP_TAC o SPECL
    [`?? 0 (hsrank_form && Not (bname_form 0))`; `1`;
     `(9 |-> (P:A)) ((8 |-> (om:A)) ((2 |-> (B:A)) v0))`; `sa0:A`] o
    MATCH_MP ZF_SEPARATION) THEN
  ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `S:A` (CONJUNCTS_THEN2 (LABEL_TAC "SD")
    (LABEL_TAC "Sch"))) THEN
  SUBGOAL_THEN
   `!a:A. a IN D
          ==> ((E:A->A->bool) a S <=>
               E a sa0 /\
               ?z. z IN D /\
                   (eordinal D E a /\
                    (?y. y IN D /\ hsstage D E B om P a y /\ E z y) /\
                    (!c. c IN D /\ E c a
                         ==> ~(?y. y IN D /\ hsstage D E B om P c
                               y /\ E z y))) /\
                   ~bname D E B z)`
   (LABEL_TAC "Sch2") THENL
   [X_GEN_TAC `a:A` THEN DISCH_THEN(LABEL_TAC "aD") THEN
    USE_THEN "Sch" (MP_TAC o SPEC `a:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MATCH_MP_TAC(TAUT `(b <=> c) ==> (x /\ b <=> x /\ c)`) THEN
    REWRITE_TAC[HOLDS_EX; HOLDS_AND; HOLDS_NOT] THEN
    MATCH_MP_TAC(MESON[]
      `(!z:A. z IN D ==> (P z <=> Q z))
       ==> ((?z. z IN D /\ P z) <=> (?z. z IN D /\ Q z))`) THEN
    X_GEN_TAC `z:A` THEN DISCH_THEN(LABEL_TAC "zD") THEN
    SUBGOAL_THEN
     `valuation D ((0 |-> (z:A)) ((1 |-> (a:A))
        ((9 |-> (P:A)) ((8 |-> (om:A)) ((2 |-> (B:A)) v0)))))`
     (LABEL_TAC "vz") THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THENL
       [MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
        FIRST_ASSUM ACCEPT_TAC];
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;
      `(0 |-> (z:A)) ((1 |-> (a:A))
         ((9 |-> (P:A)) ((8 |-> (om:A)) ((2 |-> (B:A)) v0))))`]
      HOLDS_HSRANK_FORM) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;
      `(0 |-> (z:A)) ((1 |-> (a:A))
         ((9 |-> (P:A)) ((8 |-> (om:A)) ((2 |-> (B:A)) v0))))`; `0`]
      HOLDS_BNAME_FORM) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ARITH_TAC;
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  (* a0 IN S, so S nonempty *)
  SUBGOAL_THEN `(E:A->A->bool) a0 S` (LABEL_TAC "a0S") THENL
   [USE_THEN "Sch2" (MP_TAC o SPEC `a0:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    CONJ_TAC THENL [USE_THEN "a0sa0" ACCEPT_TAC; ALL_TAC] THEN
    EXISTS_TAC `u:A` THEN REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  (* an E-minimal element as of S *)
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`] ZF_FOUNDATION) THEN
  ANTS_TAC THENL [USE_THEN "modl" ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `S:A`) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL [USE_THEN "SD" ACCEPT_TAC; ALL_TAC] THEN
    EXISTS_TAC `a0:A` THEN CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `as:A` (CONJUNCTS_THEN2 (LABEL_TAC "asD")
    (CONJUNCTS_THEN2 (LABEL_TAC "asS") (LABEL_TAC "asmin")))) THEN
  USE_THEN "Sch2" (MP_TAC o SPEC `as:A`) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> USE_THEN "asS" (MP_TAC o EQ_MP th)) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "assa0")
    (X_CHOOSE_THEN `z:A` (CONJUNCTS_THEN2 (LABEL_TAC "zD")
      (CONJUNCTS_THEN2
        (CONJUNCTS_THEN2 (LABEL_TAC "asord")
          (CONJUNCTS_THEN2
            (X_CHOOSE_THEN `ya:A` (CONJUNCTS_THEN2 (LABEL_TAC "yaD")
              (CONJUNCTS_THEN2 (LABEL_TAC "hsya") (LABEL_TAC "zya"))))
            (K ALL_TAC)))
        (LABEL_TAC "nbz"))))) THEN
  (* z is an HS-stage member: an ebnmem function over w = union of earlier *)
  (* stages                                                                *)
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`om:A`;`P:A`;`as:A`;`ya:A`]
    HSSTAGE_CHAR) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `w:A` (CONJUNCTS_THEN2 (LABEL_TAC "wD")
    (CONJUNCTS_THEN2 (LABEL_TAC "wchar") (LABEL_TAC "funs")))) THEN
  USE_THEN "funs" (MP_TAC o SPEC `z:A` o CONJUNCT2 o REWRITE_RULE[ehsfuns]) THEN
  ANTS_TAC THENL [USE_THEN "zD" ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> USE_THEN "zya" (MP_TAC o EQ_MP th)) THEN
  REWRITE_TAC[ehsmem; ebnmem] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (CONJUNCTS_THEN2 (LABEL_TAC "zfun")
    (X_CHOOSE_THEN `cr:A` (CONJUNCTS_THEN2 (LABEL_TAC "crD")
      (CONJUNCTS_THEN2 (LABEL_TAC "crp") (LABEL_TAC "zsub")))))
          (K ALL_TAC)) THEN
  (* every pair of z is <t,c> with t IN w, c IN B *)
  SUBGOAL_THEN
   `!p:A. p IN D /\ E p z
          ==> ?t c. t IN D /\ c IN D /\ eopair D E t c p /\ E c B /\ E t w`
   (LABEL_TAC "zpairs") THENL
   [X_GEN_TAC `p:A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "pD") (LABEL_TAC "pz")) THEN
    SUBGOAL_THEN `(E:A->A->bool) p cr` MP_TAC THENL
     [USE_THEN "zsub" (MP_TAC o SPEC `p:A` o REWRITE_RULE[esubset]) THEN
      ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    USE_THEN "crp" (MP_TAC o SPEC `p:A` o CONJUNCT2 o REWRITE_RULE[ecross]) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    DISCH_THEN(X_CHOOSE_THEN `t:A` (X_CHOOSE_THEN `c:A`
      (CONJUNCTS_THEN2 (LABEL_TAC "tD") (CONJUNCTS_THEN2 (LABEL_TAC "cD")
        (CONJUNCTS_THEN2 (LABEL_TAC "tw") (CONJUNCTS_THEN2 (LABEL_TAC "cB")
          (LABEL_TAC "tcp"))))))) THEN
    MAP_EVERY EXISTS_TAC [`t:A`;`c:A`] THEN
    REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  (* every first coordinate t (t IN w) is a B-name, by minimality of as *)
  SUBGOAL_THEN `!t:A. t IN D /\ E t w ==> bname D E B t` (LABEL_TAC "wbn") THENL
   [X_GEN_TAC `t:A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "tD") (LABEL_TAC "tw")) THEN
    USE_THEN "wchar" (MP_TAC o SPEC `t:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "tw" (MP_TAC o EQ_MP th)) THEN
    DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `zb:A`
      (CONJUNCTS_THEN2 (LABEL_TAC "bD") (CONJUNCTS_THEN2 (LABEL_TAC "zbD")
        (CONJUNCTS_THEN2 (LABEL_TAC "bas") (CONJUNCTS_THEN2 (LABEL_TAC "hsb")
          (LABEL_TAC "tzb"))))))) THEN
    SUBGOAL_THEN `eordinal D (E:A->A->bool) b` (LABEL_TAC "bord") THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`as:A`;`b:A`]
             EORDINAL_MEMBER) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    MATCH_MP_TAC(TAUT `(~p ==> F) ==> p`) THEN DISCH_THEN(LABEL_TAC "nbt") THEN
    SUBGOAL_THEN `hsname D (E:A->A->bool) B om P t` (LABEL_TAC "hst") THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`om:A`;`P:A`;
                    `b:A`;`zb:A`;`t:A`]
        HSNAME_STAGE) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`om:A`;`P:A`;`t:A`]
           HSNAME_RANK) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `r:A` (CONJUNCTS_THEN2 (LABEL_TAC "rD")
      (CONJUNCTS_THEN2 (LABEL_TAC "rord") (CONJUNCTS_THEN2 (LABEL_TAC "rin")
        (LABEL_TAC "rmin"))))) THEN
    (* r IN as *)
    SUBGOAL_THEN `(E:A->A->bool) r as` (LABEL_TAC "ras") THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`r:A`;`b:A`]
             EORDINAL_TRICHOTOMY) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN ASSUME_TAC) THENL
       [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`as:A`;`r:A`;`b:A`]
          EORDINAL_TRANS_E) THEN
        ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                        DISCH_THEN ACCEPT_TAC];
        FIRST_X_ASSUM(SUBST1_TAC o check (is_eq o concl)) THEN
        USE_THEN "bas" ACCEPT_TAC;
        USE_THEN "rmin" (MP_TAC o SPEC `b:A`) THEN
        ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
        DISCH_THEN(MP_TAC o check (fun th -> true)) THEN
        MATCH_MP_TAC(TAUT `p ==> ~p ==> q`) THEN
        EXISTS_TAC `zb:A` THEN REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC];
      ALL_TAC] THEN
    (* r IN S contradicts minimality of as *)
    USE_THEN "asmin" (MP_TAC o SPEC `r:A`) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    MATCH_MP_TAC(TAUT `p ==> ~p ==> F`) THEN
    USE_THEN "Sch2" (MP_TAC o SPEC `r:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`sa0:A`;`r:A`;`as:A`]
        EORDINAL_TRANS_E) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN ACCEPT_TAC];
      EXISTS_TAC `t:A` THEN REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC];
    ALL_TAC] THEN
  (* bound dom(z) in one B-name stage *)
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`z:A`] EDOMAIN_EXISTS) THEN
  ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `dv:A` (LABEL_TAC "domz")) THEN
  SUBGOAL_THEN `(dv:A) IN D` (LABEL_TAC "dvD") THENL
   [USE_THEN "domz" (ACCEPT_TAC o CONJUNCT1 o
                     REWRITE_RULE[edomain]); ALL_TAC] THEN
  SUBGOAL_THEN `!t:A. t IN D /\ E t dv
      ==> bname D E B t` (LABEL_TAC "dvbn") THENL
   [X_GEN_TAC `t:A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "tD") (LABEL_TAC "tdv")) THEN
    USE_THEN "domz" (MP_TAC o SPEC `t:A` o CONJUNCT2 o
                     REWRITE_RULE[edomain]) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "tdv" (MP_TAC o EQ_MP th)) THEN
    REWRITE_TAC[eindom; eapply] THEN
    DISCH_THEN(X_CHOOSE_THEN `ww:A` (CONJUNCTS_THEN2 (LABEL_TAC "wwD")
      (X_CHOOSE_THEN `p:A` (CONJUNCTS_THEN2 (LABEL_TAC "twp")
        (LABEL_TAC "pz"))))) THEN
    SUBGOAL_THEN `(p:A) IN D` (LABEL_TAC "pD") THENL
     [USE_THEN "twp" (ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
    USE_THEN "zpairs" (MP_TAC o SPEC `p:A`) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `t':A` (X_CHOOSE_THEN `c:A`
      (CONJUNCTS_THEN2 (LABEL_TAC "t'D") (CONJUNCTS_THEN2 (LABEL_TAC "cD")
        (CONJUNCTS_THEN2 (LABEL_TAC "t'cp") (CONJUNCTS_THEN2 (K ALL_TAC)
          (LABEL_TAC "t'w"))))))) THEN
    SUBGOAL_THEN `t:A = t'` SUBST_ALL_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`t:A`;`ww:A`;`t':A`;`c:A`;`p:A`]
        EOPAIR_INJ) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN(ACCEPT_TAC o CONJUNCT1)];
      ALL_TAC] THEN
    USE_THEN "wbn" (MP_TAC o SPEC `t':A`) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`dv:A`] BNAME_BOUND) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `c0:A` (X_CHOOSE_THEN `yc0:A`
    (CONJUNCTS_THEN2 (LABEL_TAC "c0D") (CONJUNCTS_THEN2 (LABEL_TAC "yc0D")
      (CONJUNCTS_THEN2 (LABEL_TAC "c0ord") (CONJUNCTS_THEN2 (LABEL_TAC "bnc0")
        (LABEL_TAC "bnd"))))))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`c0:A`] ESUC_EXISTS) THEN
  ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `a2:A` (LABEL_TAC "suc2")) THEN
  SUBGOAL_THEN `(a2:A) IN D` (LABEL_TAC "a2D") THENL
   [USE_THEN "suc2" (ACCEPT_TAC o MATCH_MP ESUC_IN); ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) a2` (LABEL_TAC "a2ord") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`c0:A`;`a2:A`] EORDINAL_ESUC) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) c0 a2` (LABEL_TAC "c0a2") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`c0:A`;`a2:A`] ESUC_MEMBER) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`a2:A`] EBNSTAGE_EXISTS) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ya2:A` (CONJUNCTS_THEN2 (LABEL_TAC "ya2D")
    (LABEL_TAC "bna2"))) THEN
  SUBGOAL_THEN `(E:A->A->bool) z ya2` (LABEL_TAC "zya2") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`z:A`;`a2:A`;`ya2:A`]
      BNSTAGE_INTRO) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      X_GEN_TAC `p:A` THEN
      DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "pD") (LABEL_TAC "pz")) THEN
      USE_THEN "zpairs" (MP_TAC o SPEC `p:A`) THEN
      ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `t:A` (X_CHOOSE_THEN `c:A`
        (CONJUNCTS_THEN2 (LABEL_TAC "tD") (CONJUNCTS_THEN2 (LABEL_TAC "cD")
          (CONJUNCTS_THEN2 (LABEL_TAC "tcp") (CONJUNCTS_THEN2 (LABEL_TAC "cB")
            (K ALL_TAC))))))) THEN
      MAP_EVERY EXISTS_TAC [`t:A`;`c:A`] THEN REPEAT CONJ_TAC THEN
      TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      MAP_EVERY EXISTS_TAC [`c0:A`;`yc0:A`] THEN REPEAT CONJ_TAC THEN
      TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      USE_THEN "bnd" MATCH_MP_TAC THEN
      CONJ_TAC THENL [USE_THEN "tD" ACCEPT_TAC; ALL_TAC] THEN
      USE_THEN "domz" (MP_TAC o SPEC `t:A` o CONJUNCT2 o
                       REWRITE_RULE[edomain]) THEN
      ANTS_TAC THENL [USE_THEN "tD" ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[eindom; eapply] THEN
      EXISTS_TAC `c:A` THEN CONJ_TAC THENL
          [USE_THEN "cD" ACCEPT_TAC; ALL_TAC] THEN
      EXISTS_TAC `p:A` THEN CONJ_TAC THENL
       [USE_THEN "tcp" ACCEPT_TAC; USE_THEN "pz" ACCEPT_TAC];
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  USE_THEN "nbz" (fun th -> MP_TAC th) THEN REWRITE_TAC[] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`a2:A`;`ya2:A`;`z:A`]
         BNAME_STAGE) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                  DISCH_THEN(fun th -> REWRITE_TAC[th])]);;

(* ===================================================================== *)
(* S3-7 step 9e-4 : unordered pair names up = {<a,c>, <b,c>}.               *)
(* UPN_EXISTS, UPN_ISFUN, UPN_BNAME, HSNAME_SYM, AUTN_UPN (autN-equivariance *)
(* for c = onebee: autN{a,b} = {autN a, autN b}).                            *)
(* ===================================================================== *)
let UPN_EXISTS = prove
 (`!D (E:A->A->bool) a b c.
      model D E ZF_AX /\ a IN D /\ b IN D /\ c IN D
      ==> ?up. up IN D /\
               (!z. z IN D ==> (E z up <=> eopair D E a c z \/
                                eopair D E b c z))`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
             (CONJUNCTS_THEN2 (LABEL_TAC "aD")
    (CONJUNCTS_THEN2 (LABEL_TAC "bD") (LABEL_TAC "cD")))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`a:A`;`c:A`] EOPAIR_EXISTS) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `p1:A` (LABEL_TAC "p1p")) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`b:A`;`c:A`] EOPAIR_EXISTS) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `p2:A` (LABEL_TAC "p2p")) THEN
  SUBGOAL_THEN `(p1:A) IN D /\ (p2:A) IN D` (CONJUNCTS_THEN2 (LABEL_TAC "p1D")
    (LABEL_TAC "p2D")) THENL
   [CONJ_TAC THENL [USE_THEN "p1p" (ACCEPT_TAC o MATCH_MP EOPAIR_IN);
                    USE_THEN "p2p" (ACCEPT_TAC o MATCH_MP EOPAIR_IN)];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`p1:A`;`p2:A`] EPAIR_EXISTS) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `up:A` (LABEL_TAC "upp")) THEN
  EXISTS_TAC `up:A` THEN CONJ_TAC THENL
   [USE_THEN "upp" (ACCEPT_TAC o MATCH_MP EPAIR_IN); ALL_TAC] THEN
  X_GEN_TAC `z:A` THEN DISCH_THEN(LABEL_TAC "zD") THEN
  USE_THEN "upp" (MP_TAC o SPEC `z:A` o CONJUNCT2 o REWRITE_RULE[epair]) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN
  USE_THEN "modl" (fun m -> USE_THEN "p1p" (fun h1 -> USE_THEN "p2p" (fun h2 ->
    MESON_TAC[m; h1; h2; EOPAIR_UNIQUE]))));;

let UPN_ISFUN = prove
 (`!D (E:A->A->bool) a b c up.
      model D E ZF_AX /\ a IN D /\ b IN D /\ c IN D /\ up IN D /\
      (!z. z IN D ==> (E z up <=> eopair D E a c z \/ eopair D E b c z))
      ==> eisfun D E up`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
             (CONJUNCTS_THEN2 (LABEL_TAC "aD")
    (CONJUNCTS_THEN2 (LABEL_TAC "bD") (CONJUNCTS_THEN2 (LABEL_TAC "cD")
      (CONJUNCTS_THEN2 (LABEL_TAC "upD") (LABEL_TAC "upch")))))) THEN
  SUBGOAL_THEN
   `!t q p. t IN D /\ q IN D /\ p IN D /\ eopair D E t q p /\
            (E:A->A->bool) p up ==> q = c`
   (LABEL_TAC "val") THENL
   [REPEAT GEN_TAC THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "tD")
               (CONJUNCTS_THEN2 (LABEL_TAC "qD")
      (CONJUNCTS_THEN2 (LABEL_TAC "pD") (CONJUNCTS_THEN2 (LABEL_TAC "tqp")
        (LABEL_TAC "pup"))))) THEN
    USE_THEN "upch" (MP_TAC o SPEC `p:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "pup" (MP_TAC o EQ_MP th)) THEN
    STRIP_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`t:A`;`q:A`;`a:A`;`c:A`;`p:A`]
        EOPAIR_INJ) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN(ACCEPT_TAC o CONJUNCT2)];
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`t:A`;`q:A`;`b:A`;`c:A`;`p:A`]
        EOPAIR_INJ) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN(ACCEPT_TAC o CONJUNCT2)]];
    ALL_TAC] THEN
  REWRITE_TAC[eisfun] THEN REPEAT CONJ_TAC THENL
   [USE_THEN "upD" ACCEPT_TAC;
    X_GEN_TAC `z:A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "zD") (LABEL_TAC "zup")) THEN
    USE_THEN "upch" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "zup" (MP_TAC o EQ_MP th)) THEN
    STRIP_TAC THENL
     [MAP_EVERY EXISTS_TAC [`a:A`;`c:A`] THEN REPEAT CONJ_TAC THEN
      FIRST_ASSUM ACCEPT_TAC;
      MAP_EVERY EXISTS_TAC [`b:A`;`c:A`] THEN REPEAT CONJ_TAC THEN
      FIRST_ASSUM ACCEPT_TAC];
    MAP_EVERY X_GEN_TAC [`u:A`;`w:A`;`w':A`;`z:A`;`z':A`] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "uD")
               (CONJUNCTS_THEN2 (LABEL_TAC "wD")
      (CONJUNCTS_THEN2 (LABEL_TAC "w'D") (CONJUNCTS_THEN2 (LABEL_TAC "uwz")
        (CONJUNCTS_THEN2 (LABEL_TAC "zup") (CONJUNCTS_THEN2 (LABEL_TAC "uw'z'")
          (LABEL_TAC "z'up"))))))) THEN
    SUBGOAL_THEN `(z:A) IN D /\ (z':A) IN D` (CONJUNCTS_THEN2 (LABEL_TAC "zD")
      (LABEL_TAC "z'D")) THENL
     [CONJ_TAC THENL [USE_THEN "uwz" (ACCEPT_TAC o MATCH_MP EOPAIR_IN);
                      USE_THEN "uw'z'" (ACCEPT_TAC o MATCH_MP EOPAIR_IN)];
      ALL_TAC] THEN
    SUBGOAL_THEN `w:A = c /\ w':A = c` (fun th -> REWRITE_TAC[th]) THEN
    CONJ_TAC THENL
     [USE_THEN "val" (MP_TAC o SPECL [`u:A`;`w:A`;`z:A`]) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN ACCEPT_TAC];
      USE_THEN "val" (MP_TAC o SPECL [`u:A`;`w':A`;`z':A`]) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN ACCEPT_TAC]]]);;

let UPN_BNAME = prove
 (`!D (E:A->A->bool) B a b c up.
      model D E ZF_AX /\ B IN D /\ a IN D /\ b IN D /\ c IN D /\ E c B /\
      bname D E B a /\ bname D E B b /\ up IN D /\
      (!z. z IN D ==> (E z up <=> eopair D E a c z \/ eopair D E b c z))
      ==> bname D E B up`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
             (CONJUNCTS_THEN2 (LABEL_TAC "BD")
    (CONJUNCTS_THEN2 (LABEL_TAC "aD") (CONJUNCTS_THEN2 (LABEL_TAC "bD")
      (CONJUNCTS_THEN2 (LABEL_TAC "cD") (CONJUNCTS_THEN2 (LABEL_TAC "cB")
        (CONJUNCTS_THEN2 (LABEL_TAC "bna") (CONJUNCTS_THEN2 (LABEL_TAC "bnb")
          (CONJUNCTS_THEN2 (LABEL_TAC "upD") (LABEL_TAC "upch")))))))))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`a:A`;`b:A`] EPAIR_EXISTS) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `pl:A` (LABEL_TAC "plp")) THEN
  SUBGOAL_THEN `(pl:A) IN D` (LABEL_TAC "plD") THENL
   [USE_THEN "plp" (ACCEPT_TAC o MATCH_MP EPAIR_IN); ALL_TAC] THEN
  SUBGOAL_THEN `!w:A. w IN D ==> ((E:A->A->bool) w pl <=> w = a \/ w = b)`
   (LABEL_TAC "plch") THENL
   [USE_THEN "plp" (ACCEPT_TAC o CONJUNCT2 o REWRITE_RULE[epair]); ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`pl:A`] BNAME_BOUND) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    X_GEN_TAC `t:A` THEN DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "tD")
        (LABEL_TAC "tpl")) THEN
    USE_THEN "plch" (MP_TAC o SPEC `t:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "tpl" (MP_TAC o EQ_MP th)) THEN
    DISCH_THEN(DISJ_CASES_THEN SUBST1_TAC) THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `c0:A` (X_CHOOSE_THEN `yc0:A`
    (CONJUNCTS_THEN2 (LABEL_TAC "c0D") (CONJUNCTS_THEN2 (LABEL_TAC "yc0D")
      (CONJUNCTS_THEN2 (LABEL_TAC "c0ord") (CONJUNCTS_THEN2 (LABEL_TAC "bnc0")
        (LABEL_TAC "bnd"))))))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`c0:A`] ESUC_EXISTS) THEN
  ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `a2:A` (LABEL_TAC "suc")) THEN
  SUBGOAL_THEN `(a2:A) IN D` (LABEL_TAC "a2D") THENL
   [USE_THEN "suc" (ACCEPT_TAC o MATCH_MP ESUC_IN); ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) a2` (LABEL_TAC "a2ord") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`c0:A`;`a2:A`] EORDINAL_ESUC) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) c0 a2` (LABEL_TAC "c0a2") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`c0:A`;`a2:A`] ESUC_MEMBER) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`a2:A`] EBNSTAGE_EXISTS) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ya2:A` (CONJUNCTS_THEN2 (LABEL_TAC "ya2D")
    (LABEL_TAC "bna2"))) THEN
  SUBGOAL_THEN `eisfun D (E:A->A->bool) up` (LABEL_TAC "upfun") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`a:A`;`b:A`;`c:A`;`up:A`]
           UPN_ISFUN) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) up ya2` (LABEL_TAC "upya2") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`up:A`;`a2:A`;`ya2:A`]
      BNSTAGE_INTRO) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      X_GEN_TAC `z:A` THEN
      DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "zD") (LABEL_TAC "zup")) THEN
      USE_THEN "upch" (MP_TAC o SPEC `z:A`) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> USE_THEN "zup" (MP_TAC o EQ_MP th)) THEN
      DISCH_THEN(DISJ_CASES_THEN (LABEL_TAC "zp")) THENL
       [MAP_EVERY EXISTS_TAC [`a:A`;`c:A`] THEN REPEAT CONJ_TAC THEN
        TRY(FIRST_ASSUM ACCEPT_TAC) THEN
        MAP_EVERY EXISTS_TAC [`c0:A`;`yc0:A`] THEN REPEAT CONJ_TAC THEN
        TRY(FIRST_ASSUM ACCEPT_TAC) THEN
        USE_THEN "bnd" MATCH_MP_TAC THEN CONJ_TAC THENL
            [USE_THEN "aD" ACCEPT_TAC; ALL_TAC] THEN
        USE_THEN "plch" (MP_TAC o SPEC `a:A`) THEN
        ANTS_TAC THENL [USE_THEN "aD" ACCEPT_TAC;
                        DISCH_THEN(fun th -> REWRITE_TAC[th])];
        MAP_EVERY EXISTS_TAC [`b:A`;`c:A`] THEN REPEAT CONJ_TAC THEN
        TRY(FIRST_ASSUM ACCEPT_TAC) THEN
        MAP_EVERY EXISTS_TAC [`c0:A`;`yc0:A`] THEN REPEAT CONJ_TAC THEN
        TRY(FIRST_ASSUM ACCEPT_TAC) THEN
        USE_THEN "bnd" MATCH_MP_TAC THEN CONJ_TAC THENL
            [USE_THEN "bD" ACCEPT_TAC; ALL_TAC] THEN
        USE_THEN "plch" (MP_TAC o SPEC `b:A`) THEN
        ANTS_TAC THENL [USE_THEN "bD" ACCEPT_TAC;
                        DISCH_THEN(fun th -> REWRITE_TAC[th])]];
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`a2:A`;`ya2:A`;`up:A`]
         BNAME_STAGE) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                  DISCH_THEN ACCEPT_TAC]);;

let HSNAME_SYM = prove
 (`!D (E:A->A->bool) B om P u.
      model D E ZF_AX /\ B IN D /\ om IN D /\ P IN D /\ u IN D /\
      hsname D E B om P u
      ==> ehssym D E B om P u`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
             (CONJUNCTS_THEN2 (LABEL_TAC "BD")
    (CONJUNCTS_THEN2 (LABEL_TAC "omD") (CONJUNCTS_THEN2 (LABEL_TAC "PD")
      (CONJUNCTS_THEN2 (LABEL_TAC "uD") (MP_TAC o
          REWRITE_RULE[hsname])))))) THEN
  DISCH_THEN(X_CHOOSE_THEN `a:A` (X_CHOOSE_THEN `y:A`
    (CONJUNCTS_THEN2 (LABEL_TAC "aD") (CONJUNCTS_THEN2 (LABEL_TAC "yD")
      (CONJUNCTS_THEN2 (LABEL_TAC "aord") (CONJUNCTS_THEN2 (LABEL_TAC "hsy")
        (LABEL_TAC "uy"))))))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`om:A`;`P:A`;`a:A`;`y:A`]
    HSSTAGE_CHAR) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `w:A` (CONJUNCTS_THEN2 (K ALL_TAC)
    (CONJUNCTS_THEN2 (K ALL_TAC) (LABEL_TAC "funs")))) THEN
  USE_THEN "funs" (MP_TAC o SPEC `u:A` o CONJUNCT2 o REWRITE_RULE[ehsfuns]) THEN
  ANTS_TAC THENL [USE_THEN "uD" ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> USE_THEN "uy" (MP_TAC o EQ_MP th)) THEN
  REWRITE_TAC[ehsmem] THEN DISCH_THEN(ACCEPT_TAC o CONJUNCT2));;

(* autN-equivariance of the pair name at the top value onebee. *)
let AUTN_UPN = prove
 (`!D (E:A->A->bool) B inclB onebee autB a b a' b' up up'.
      model D E ZF_AX /\ onebee IN D /\ B IN D /\ autB IN D /\ E onebee B /\
      ebij D E autB B B /\
      (!x y xi yi. x IN D /\ y IN D /\ xi IN D /\ yi IN D /\
                   eapply D E autB x xi /\ eapply D E autB y yi
                   ==> (erel D E inclB x y <=> erel D E inclB xi yi)) /\
      eporder D E B inclB /\ etop D E B inclB onebee /\
      up IN D /\ bname D E B up /\
      (!z. z IN D ==> (E z up <=> eopair D E a onebee z \/
                       eopair D E b onebee z)) /\
      up' IN D /\
      (!z. z IN D ==> (E z up' <=> eopair D E a' onebee z \/
                       eopair D E b' onebee z)) /\
      eautn D E B autB a a' /\ eautn D E B autB b b'
      ==> eautn D E B autB up up'`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
   (CONJUNCTS_THEN2 (LABEL_TAC "oneD")
    (CONJUNCTS_THEN2 (LABEL_TAC "BD")
     (CONJUNCTS_THEN2 (LABEL_TAC "autBD")
      (CONJUNCTS_THEN2 (LABEL_TAC "oneB")
       (CONJUNCTS_THEN2 (LABEL_TAC "bijB")
        (CONJUNCTS_THEN2 (LABEL_TAC "quadB")
         (CONJUNCTS_THEN2 (LABEL_TAC "porder")
          (CONJUNCTS_THEN2 (LABEL_TAC "top")
           (CONJUNCTS_THEN2 (LABEL_TAC "upD")
            (CONJUNCTS_THEN2 (LABEL_TAC "bnup")
             (CONJUNCTS_THEN2 (LABEL_TAC "upch")
              (CONJUNCTS_THEN2 (LABEL_TAC "up'D")
               (CONJUNCTS_THEN2 (LABEL_TAC "up'ch")
                (CONJUNCTS_THEN2 (LABEL_TAC "aa'")
                  (LABEL_TAC "bb'")))))))))))))))) THEN
  USE_THEN "bijB" (LABEL_TAC "autBsv" o
    CONJUNCT1 o CONJUNCT2 o CONJUNCT2 o CONJUNCT2 o REWRITE_RULE[ebij]) THEN
  SUBGOAL_THEN `eapply D (E:A->A->bool) autB onebee onebee`
      (LABEL_TAC "fixtop") THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;
                   `autB:A`;`onebee:A`]
      EAUTB_FIXES_TOP) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  USE_THEN "aa'" (fun th -> LABEL_TAC "aD"
                  (CONJUNCT1(MATCH_MP AUTN_IMP th)) THEN
                            LABEL_TAC "a'D" (CONJUNCT2(MATCH_MP
                                AUTN_IMP th))) THEN
  USE_THEN "bb'" (fun th -> LABEL_TAC "bD"
                  (CONJUNCT1(MATCH_MP AUTN_IMP th)) THEN
                            LABEL_TAC "b'D" (CONJUNCT2(MATCH_MP
                                AUTN_IMP th))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`up:A`]
         AUTN_TOTAL) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `v:A` (CONJUNCTS_THEN2 (LABEL_TAC "vD")
    (LABEL_TAC "autnv"))) THEN
  SUBGOAL_THEN `v:A = up'` SUBST_ALL_TAC THENL
   [FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "vD" ACCEPT_TAC; USE_THEN "up'D" ACCEPT_TAC; ALL_TAC] THEN
    X_GEN_TAC `z:A` THEN DISCH_THEN(LABEL_TAC "zD") THEN
    USE_THEN "up'ch" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`up:A`;`v:A`;`z:A`]
      AUTN_MEM) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN EQ_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `m:A` (X_CHOOSE_THEN `t:A` (X_CHOOSE_THEN `c:A`
        (X_CHOOSE_THEN `t':A` (X_CHOOSE_THEN `c':A`
          (CONJUNCTS_THEN2 (LABEL_TAC "mD") (CONJUNCTS_THEN2 (LABEL_TAC "tD")
            (CONJUNCTS_THEN2 (LABEL_TAC "cD") (CONJUNCTS_THEN2 (LABEL_TAC "t'D")
              (CONJUNCTS_THEN2 (LABEL_TAC "c'D")
               (CONJUNCTS_THEN2 (LABEL_TAC "mup")
                (CONJUNCTS_THEN2 (LABEL_TAC "tcm")
                 (CONJUNCTS_THEN2 (LABEL_TAC "att")
                  (CONJUNCTS_THEN2 (LABEL_TAC "acc")
                    (LABEL_TAC "pz"))))))))))))))) THEN
      SUBGOAL_THEN `c':A = onebee` SUBST_ALL_TAC THENL
       [SUBGOAL_THEN `c:A = onebee` SUBST_ALL_TAC THENL
         [USE_THEN "upch" (MP_TAC o SPEC `m:A`) THEN
          ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
          DISCH_THEN(fun th -> USE_THEN "mup" (MP_TAC o EQ_MP th)) THEN
          STRIP_TAC THENL
           [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`t:A`;`c:A`;`a:A`;
                          `onebee:A`;`m:A`]
              EOPAIR_INJ) THEN
            ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                            DISCH_THEN(ACCEPT_TAC o CONJUNCT2)];
            MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`t:A`;`c:A`;`b:A`;
                          `onebee:A`;`m:A`]
              EOPAIR_INJ) THEN
            ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                            DISCH_THEN(ACCEPT_TAC o CONJUNCT2)]];
          ALL_TAC] THEN
        USE_THEN "autBsv" (fun th ->
          MP_TAC(SPECL [`onebee:A`;`c':A`;`onebee:A`] th)) THEN
        ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                        DISCH_THEN ACCEPT_TAC];
        ALL_TAC] THEN
      USE_THEN "upch" (MP_TAC o SPEC `m:A`) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> USE_THEN "mup" (MP_TAC o EQ_MP th)) THEN
      STRIP_TAC THENL
       [SUBGOAL_THEN `t:A = a` SUBST_ALL_TAC THENL
         [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`t:A`;`c:A`;`a:A`;
                        `onebee:A`;`m:A`]
            EOPAIR_INJ) THEN
          ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                          DISCH_THEN(ACCEPT_TAC o CONJUNCT1)];
          ALL_TAC] THEN
        SUBGOAL_THEN `t':A = a'` SUBST_ALL_TAC THENL
         [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;
                        `a:A`;`t':A`;`a':A`]
            AUTN_SV) THEN
          ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                          DISCH_THEN ACCEPT_TAC];
          ALL_TAC] THEN
        DISJ1_TAC THEN USE_THEN "pz" ACCEPT_TAC;
        SUBGOAL_THEN `t:A = b` SUBST_ALL_TAC THENL
         [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`t:A`;`c:A`;`b:A`;
                        `onebee:A`;`m:A`]
            EOPAIR_INJ) THEN
          ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                          DISCH_THEN(ACCEPT_TAC o CONJUNCT1)];
          ALL_TAC] THEN
        SUBGOAL_THEN `t':A = b'` SUBST_ALL_TAC THENL
         [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;
                        `b:A`;`t':A`;`b':A`]
            AUTN_SV) THEN
          ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                          DISCH_THEN ACCEPT_TAC];
          ALL_TAC] THEN
        DISJ2_TAC THEN USE_THEN "pz" ACCEPT_TAC];
      DISCH_THEN(DISJ_CASES_THEN (LABEL_TAC "zp")) THENL
       [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`a:A`;`onebee:A`]
               EOPAIR_EXISTS) THEN
        ANTS_TAC THENL [REPEAT CONJ_TAC THEN
                        FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
        DISCH_THEN(X_CHOOSE_THEN `m:A` (LABEL_TAC "mp")) THEN
        SUBGOAL_THEN `(m:A) IN D` (LABEL_TAC "mD") THENL
         [USE_THEN "mp" (ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
        SUBGOAL_THEN `(E:A->A->bool) m up` (LABEL_TAC "mup") THENL
         [USE_THEN "upch" (MP_TAC o SPEC `m:A`) THEN
          ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
          DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN DISJ1_TAC THEN
          USE_THEN "mp" ACCEPT_TAC;
          ALL_TAC] THEN
        MAP_EVERY EXISTS_TAC [`m:A`;`a:A`;`onebee:A`;`a':A`;`onebee:A`] THEN
        REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
        MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`b:A`;`onebee:A`]
               EOPAIR_EXISTS) THEN
        ANTS_TAC THENL [REPEAT CONJ_TAC THEN
                        FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
        DISCH_THEN(X_CHOOSE_THEN `m:A` (LABEL_TAC "mp")) THEN
        SUBGOAL_THEN `(m:A) IN D` (LABEL_TAC "mD") THENL
         [USE_THEN "mp" (ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
        SUBGOAL_THEN `(E:A->A->bool) m up` (LABEL_TAC "mup") THENL
         [USE_THEN "upch" (MP_TAC o SPEC `m:A`) THEN
          ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
          DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN DISJ2_TAC THEN
          USE_THEN "mp" ACCEPT_TAC;
          ALL_TAC] THEN
        MAP_EVERY EXISTS_TAC [`m:A`;`b:A`;`onebee:A`;`b':A`;`onebee:A`] THEN
        REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC]];
    USE_THEN "autnv" ACCEPT_TAC]);;

(* ===================================================================== *)
(* H0 : COUNTABLE SUPPORTS.                                                  *)
(* With FINITE supports the HS maximum principle fails, so no "any          *)
(* ultrafilter" quotient of the HS names models ZF (NOTAC_PLAN.txt amend. 3).*)
(* Hence the Cohen reals are indexed by w1 = aleph_1 (ii = w1 x om), with   *)
(* permutations of w1 and COUNTABLE supports, obtained by instantiating the *)
(* HS parameter of ehssym/hsstage/hsname at w1 (?n IN w1 ?f. ebij f n e).    *)
(* hsbundle packages the context; the lemmas below are the check-name,      *)
(* real-name and pairing results at that instantiation, plus countable      *)
(* support closure (CSUPPORT_EMPTY/SING/UNION).                             *)
(* ===================================================================== *)
(* ===================================================================== *)
(* H0 (part 1) : COUNTABLE-SUPPORT GENERALIZATION over w1 = aleph_1.        *)
(* hsbundle packages the HS/Cohen context: Cohen conditions FINITE over      *)
(* ii = w1 x om (ecohenp ci om P, om = omega), permutations of w1, supports  *)
(* countable (= the HS parameter "om" instantiated at w1), domain set X with *)
(* ci, P SUBSET X, V=L for internal choice.  PERM_MUP_BUNDLE and the         *)
(* EHSSYM_INTRO/ELIM lemmas are the 9c/9e arguments with iibase := w1.      *)
(* ===================================================================== *)
let hsbundle = new_definition
 `hsbundle D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X <=>
    model D E ZF_AX /\ (!u. u IN D ==> elmem D E u) /\ eomega D E om /\
    w1 IN D /\ ecardinal D E w1 /\ E om w1 /\
    (!c'. c' IN D /\ E c' w1 ==> ~(ecardinal D E c' /\ E om c')) /\
    ecross D E w1 om ii /\ ecross D E ii tw ci /\ efin D E tw /\
    ecohenp D E ci om P /\ eleqp D E P leqp /\
    eroset D E P leqp B /\ eincl D E B inclB /\
    eporder D E B inclB /\ etop D E B inclB onebee /\
    onebee IN D /\ B IN D /\ E onebee B /\
    X IN D /\ (!u. u IN D /\ E u ci ==> E u X) /\
    (!p. p IN D /\ E p P ==> E p X)`;;

let HSB_FACTS = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X.
     hsbundle D E w1 om tw ii ci P leqp B inclB onebee X
     ==> om IN D /\ eordinal D E w1 /\ P IN D /\ ci IN D /\ ii IN D /\
         (!x. x IN D /\ E x om ==> E x w1)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[hsbundle] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
   (CONJUNCTS_THEN2 (LABEL_TAC "vl")
    (CONJUNCTS_THEN2 (LABEL_TAC "eom")
     (CONJUNCTS_THEN2 (LABEL_TAC "w1D")
      (CONJUNCTS_THEN2 (LABEL_TAC "w1card")
       (CONJUNCTS_THEN2 (LABEL_TAC "omw1")
        (CONJUNCTS_THEN2 (LABEL_TAC "w1min")
         (CONJUNCTS_THEN2 (LABEL_TAC "cr1")
          (CONJUNCTS_THEN2 (LABEL_TAC "cr2")
           (CONJUNCTS_THEN2 (LABEL_TAC "ftw")
            (CONJUNCTS_THEN2 (LABEL_TAC "coh")
             (CONJUNCTS_THEN2 (LABEL_TAC "leq")
              (CONJUNCTS_THEN2 (LABEL_TAC "ros")
               (CONJUNCTS_THEN2 (LABEL_TAC "inc")
                (CONJUNCTS_THEN2 (LABEL_TAC "porder")
                 (CONJUNCTS_THEN2 (LABEL_TAC "top")
                  (CONJUNCTS_THEN2 (LABEL_TAC "oneD")
                   (CONJUNCTS_THEN2 (LABEL_TAC "BD")
                    (CONJUNCTS_THEN2 (LABEL_TAC "oneB")
                     (CONJUNCTS_THEN2 (LABEL_TAC "XD")
                      (CONJUNCTS_THEN2 (LABEL_TAC "ciX")
                        (LABEL_TAC "PX")))))))))))))))))))))) THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) w1` (LABEL_TAC "w1ord") THENL
   [USE_THEN "w1card" (MP_TAC o REWRITE_RULE[ecardinal; ecardof])
    THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(om:A) IN D` (LABEL_TAC "omD") THENL
   [USE_THEN "eom" (ACCEPT_TAC o MATCH_MP EOMEGA_IN); ALL_TAC] THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "omD" ACCEPT_TAC;
    USE_THEN "w1ord" ACCEPT_TAC;
    USE_THEN "coh" (ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[ecohenp]);
    USE_THEN "cr2" (ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[ecross]);
    USE_THEN "cr1" (ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[ecross]);
    X_GEN_TAC `x:A` THEN DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "xD")
        (LABEL_TAC "xom")) THEN
    USE_THEN "w1ord" (MP_TAC o SPEC `om:A` o CONJUNCT1 o CONJUNCT2 o
      REWRITE_RULE[eordinal; etransitive; esubset]) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPEC `x:A`) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC]]);;

let PERM_MUP_BUNDLE = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp s.
      model D E ZF_AX /\ eomega D E om /\ ecross D E w1 om ii /\
      ecross D E ii tw ci /\ ecohenp D E ci om P /\ eleqp D E P leqp /\
      s IN D /\ eperm D E w1 s
      ==> ?muci muP.
            muci IN D /\ muP IN D /\
            ebij D E muci ci ci /\ ebij D E muP P P /\
            (!u w. u IN D /\ w IN D
                   ==> (eapply D E muci u w <=> E u ci /\ mucirel D E s u w)) /\
            (!p q. p IN D /\ q IN D
                   ==> (eapply D E muP p q <=> E p P /\ muPrel D E muci p q)) /\
            (!pa pb qa qb. pa IN D /\ pb IN D /\ qa IN D /\ qb IN D /\
                           eapply D E muP pa qa /\ eapply D E muP pb qb
                           ==> (erel D E leqp pa pb <=> erel D E leqp qa qb))`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
   (CONJUNCTS_THEN2 (LABEL_TAC "eom")
    (CONJUNCTS_THEN2 (LABEL_TAC "cr1")
     (CONJUNCTS_THEN2 (LABEL_TAC "cr2")
      (CONJUNCTS_THEN2 (LABEL_TAC "coh")
       (CONJUNCTS_THEN2 (LABEL_TAC "leq")
        (CONJUNCTS_THEN2 (LABEL_TAC "sD") (LABEL_TAC "sperm")))))))) THEN
  USE_THEN "sperm" (LABEL_TAC "sbij" o REWRITE_RULE[eperm]) THEN
  USE_THEN "modl" (X_CHOOSE_TAC `v00:num->A` o MATCH_MP VALUATION_EXISTS o
                   MATCH_MP MODEL_NONEMPTY) THEN
  SUBGOAL_THEN `valuation D ((2 |-> (s:A)) (v00:num->A))` (LABEL_TAC "vs") THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `((2 |-> (s:A)) (v00:num->A)) 2 = s` (LABEL_TAC "vs2") THENL
   [REWRITE_TAC[VALMOD_BASIC]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`s:A`;`w1:A`;`om:A`;`tw:A`;`ii:A`;
                `ci:A`;`(2 |-> (s:A)) (v00:num->A)`] MUCI_EBIJ) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `muci:A` (CONJUNCTS_THEN2 (LABEL_TAC "bm")
    (LABEL_TAC "mch"))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`s:A`;`w1:A`;`om:A`;`tw:A`;`ii:A`;
                `ci:A`;`muci:A`;`P:A`;`(2 |-> (s:A))
                    (v00:num->A)`] MUP_EBIJ) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `muP:A` (CONJUNCTS_THEN2 (LABEL_TAC "bP")
    (LABEL_TAC "Pch"))) THEN
  MAP_EVERY EXISTS_TAC [`muci:A`;`muP:A`] THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "bm" (ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[ebij]);
    USE_THEN "bP" (ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[ebij]);
    USE_THEN "bm" ACCEPT_TAC;
    USE_THEN "bP" ACCEPT_TAC;
    USE_THEN "mch" ACCEPT_TAC;
    USE_THEN "Pch" ACCEPT_TAC;
    MAP_EVERY X_GEN_TAC [`pa:A`;`pb:A`;`qa:A`;`qb:A`] THEN STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`om:A`;`muci:A`;`ci:A`;`P:A`;
                  `leqp:A`;`muP:A`;`pa:A`;`pb:A`;`qa:A`;`qb:A`] MUP_ORDER) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC]]);;

let EHSSYM_INTRO = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X nm e.
      hsbundle D E w1 om tw ii ci P leqp B inclB onebee X /\
      e IN D /\ (?n. n IN D /\ E n w1 /\ ?f. ebij D E f n e) /\
      esubset D E e w1 /\
      (!s. s IN D /\ eperm D E w1 s /\ efixes D E s e
           ==> !muci muP autB.
                 muci IN D /\ muP IN D /\ autB IN D /\
                 ebij D E muci ci ci /\ ebij D E muP P P /\
                 ebij D E autB B B /\
                 (!u w. u IN D /\ w IN D
                        ==> (eapply D E muci u w <=>
                             E u ci /\ mucirel D E s u w)) /\
                 (!p q. p IN D /\ q IN D
                        ==> (eapply D E muP p q <=>
                             E p P /\ muPrel D E muci p q)) /\
                 (!b c. b IN D /\ c IN D
                        ==> (eapply D E autB b c <=>
                             E b B /\ muPrel D E muP b c)) /\
                 (!pa pb qa qb. pa IN D /\ pb IN D /\ qa IN D /\ qb IN D /\
                                eapply D E muP pa qa /\ eapply D E muP pb qb
                                ==> (erel D E leqp pa pb <=>
                                     erel D E leqp qa qb)) /\
                 (!a b ai bi. a IN D /\ b IN D /\ ai IN D /\ bi IN D /\
                              eapply D E autB a ai /\ eapply D E autB b bi
                              ==> (erel D E inclB a b <=>
                                   erel D E inclB ai bi))
                 ==> eautn D E B autB nm nm)
      ==> ehssym D E B w1 X nm`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (MP_TAC o REWRITE_RULE[hsbundle])
   (CONJUNCTS_THEN2 (LABEL_TAC "eD")
    (CONJUNCTS_THEN2 (LABEL_TAC "efin")
     (CONJUNCTS_THEN2 (LABEL_TAC "esub") (LABEL_TAC "fixall"))))) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
   (CONJUNCTS_THEN2 (LABEL_TAC "vl")
    (CONJUNCTS_THEN2 (LABEL_TAC "eom")
     (CONJUNCTS_THEN2 (LABEL_TAC "w1D")
      (CONJUNCTS_THEN2 (LABEL_TAC "w1card")
       (CONJUNCTS_THEN2 (LABEL_TAC "omw1")
        (CONJUNCTS_THEN2 (LABEL_TAC "w1min")
         (CONJUNCTS_THEN2 (LABEL_TAC "cr1")
          (CONJUNCTS_THEN2 (LABEL_TAC "cr2")
           (CONJUNCTS_THEN2 (LABEL_TAC "ftw")
            (CONJUNCTS_THEN2 (LABEL_TAC "coh")
             (CONJUNCTS_THEN2 (LABEL_TAC "leq")
              (CONJUNCTS_THEN2 (LABEL_TAC "ros")
               (CONJUNCTS_THEN2 (LABEL_TAC "inc")
                (CONJUNCTS_THEN2 (LABEL_TAC "porder")
                 (CONJUNCTS_THEN2 (LABEL_TAC "top")
                  (CONJUNCTS_THEN2 (LABEL_TAC "oneD")
                   (CONJUNCTS_THEN2 (LABEL_TAC "BD")
                    (CONJUNCTS_THEN2 (LABEL_TAC "oneB")
                     (CONJUNCTS_THEN2 (LABEL_TAC "XD")
                      (CONJUNCTS_THEN2 (LABEL_TAC "ciX")
                        (LABEL_TAC "PX")))))))))))))))))))))) THEN
  (* conditions are subsets of ci; members of B are subsets of P *)
  SUBGOAL_THEN
   `!p u. p IN D /\ E p P /\ u IN D /\ E u p ==> (E:A->A->bool) u ci`
   (LABEL_TAC "Pci") THENL
   [REPEAT GEN_TAC THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "pD")
               (CONJUNCTS_THEN2 (LABEL_TAC "pP")
      (CONJUNCTS_THEN2 (LABEL_TAC "uD") (LABEL_TAC "up")))) THEN
    USE_THEN "coh" (MP_TAC o SPEC `p:A` o CONJUNCT2 o
                    REWRITE_RULE[ecohenp]) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "pP" (MP_TAC o EQ_MP th)) THEN
    DISCH_THEN(MP_TAC o SPEC `u:A` o REWRITE_RULE[esubset] o CONJUNCT1) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!bb x. bb IN D /\ E bb B /\ x IN D /\ E x bb ==> (E:A->A->bool) x P`
   (LABEL_TAC "BP") THENL
   [REPEAT GEN_TAC THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "bbD")
               (CONJUNCTS_THEN2 (LABEL_TAC "bbB")
      (CONJUNCTS_THEN2 (LABEL_TAC "xD") (LABEL_TAC "xbb")))) THEN
    USE_THEN "ros" (MP_TAC o SPEC `bb:A` o CONJUNCT2 o
                    REWRITE_RULE[eroset]) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "bbB" (MP_TAC o EQ_MP th)) THEN
    DISCH_THEN(MP_TAC o SPEC `x:A` o REWRITE_RULE[esubset] o CONJUNCT1) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  REWRITE_TAC[ehssym] THEN EXISTS_TAC `e:A` THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "eD" ACCEPT_TAC; USE_THEN "efin" ACCEPT_TAC;
    USE_THEN "esub" ACCEPT_TAC; ALL_TAC] THEN
  X_GEN_TAC `s:A` THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "sD")
             (CONJUNCTS_THEN2 (LABEL_TAC "sperm")
    (LABEL_TAC "sfix"))) THEN
  (* the true bundle at s *)
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;
                `ii:A`;`ci:A`;`P:A`;
                `leqp:A`;`s:A`] PERM_MUP_BUNDLE) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `muci0:A` (X_CHOOSE_THEN `muP0:A`
    (CONJUNCTS_THEN2 (LABEL_TAC "m0D") (CONJUNCTS_THEN2 (LABEL_TAC "P0D")
     (CONJUNCTS_THEN2 (LABEL_TAC "bm0") (CONJUNCTS_THEN2 (LABEL_TAC "bP0")
      (CONJUNCTS_THEN2 (LABEL_TAC "mch0") (CONJUNCTS_THEN2 (LABEL_TAC "Pch0")
        (LABEL_TAC "quadP0"))))))))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`B:A`;`muP0:A`]
    EAUTB_EXISTS) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `autB:A` (CONJUNCTS_THEN2 (LABEL_TAC "aD")
    (LABEL_TAC "ach0"))) THEN
  SUBGOAL_THEN `ebij D (E:A->A->bool) autB B B` (LABEL_TAC "bA") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`B:A`;`muP0:A`;
                  `autB:A`] EAUTB_EBIJ) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!a b ai bi. a IN D /\ b IN D /\ ai IN D /\ bi IN D /\
                eapply D (E:A->A->bool) autB a ai /\ eapply D E autB b bi
                ==> (erel D E inclB a b <=> erel D E inclB ai bi)`
   (LABEL_TAC "quadB") THENL
   [MAP_EVERY X_GEN_TAC [`a:A`;`b:A`;`ai:A`;`bi:A`] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "a_D")
               (CONJUNCTS_THEN2 (LABEL_TAC "b_D")
      (CONJUNCTS_THEN2 (LABEL_TAC "ai_D") (CONJUNCTS_THEN2 (LABEL_TAC "bi_D")
        (CONJUNCTS_THEN2 (LABEL_TAC "aai") (LABEL_TAC "bbi")))))) THEN
    USE_THEN "ach0" (MP_TAC o SPECL [`a:A`;`ai:A`]) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "aai" (MP_TAC o EQ_MP th)) THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "aB") (LABEL_TAC "maai")) THEN
    USE_THEN "ach0" (MP_TAC o SPECL [`b:A`;`bi:A`]) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "bbi" (MP_TAC o EQ_MP th)) THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "bB") (LABEL_TAC "mbbi")) THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`B:A`;`inclB:A`;
                  `muP0:A`;`a:A`;`b:A`;`ai:A`;`bi:A`] EAUTB_ORDER) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `eautn D (E:A->A->bool) B autB nm nm` (LABEL_TAC "fixnm") THENL
   [USE_THEN "fixall" (MP_TAC o SPEC `s:A`) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPECL [`muci0:A`;`muP0:A`;`autB:A`]) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  (* the X-domain muci, muP *)
  USE_THEN "modl" (X_CHOOSE_TAC `v00:num->A` o MATCH_MP VALUATION_EXISTS o
                   MATCH_MP MODEL_NONEMPTY) THEN
  SUBGOAL_THEN `valuation D ((2 |-> (s:A)) (v00:num->A))` (LABEL_TAC "vs") THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `((2 |-> (s:A)) (v00:num->A)) 2 = s` (LABEL_TAC "vs2") THENL
   [REWRITE_TAC[VALMOD_BASIC]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!k t t'. k IN D /\ t IN D /\ t' IN D /\
             eapply D (E:A->A->bool) s k t /\ eapply D E s k t' ==> t = t'`
   (LABEL_TAC "sSV") THENL
   [USE_THEN "sperm" (ACCEPT_TAC o CONJUNCT1 o CONJUNCT2 o CONJUNCT2 o
                      CONJUNCT2 o REWRITE_RULE[eperm; ebij]);
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`s:A`;`X:A`;
                `(2 |-> (s:A)) (v00:num->A)`] MUCI_EXISTS_ON) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `muci:A` (CONJUNCTS_THEN2 (LABEL_TAC "mD")
    (LABEL_TAC "mch"))) THEN
  SUBGOAL_THEN `valuation D ((2 |-> (muci:A)) (v00:num->A))`
      (LABEL_TAC "vm") THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `((2 |-> (muci:A)) (v00:num->A)) 2 = muci`
      (LABEL_TAC "vm2") THENL
   [REWRITE_TAC[VALMOD_BASIC]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`muci:A`;`X:A`;
                `(2 |-> (muci:A)) (v00:num->A)`] MUP_EXISTS) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `muP:A` (CONJUNCTS_THEN2 (LABEL_TAC "PD")
    (LABEL_TAC "Pch"))) THEN
  EXISTS_TAC `autB:A` THEN REPEAT CONJ_TAC THENL
   [USE_THEN "aD" ACCEPT_TAC;
    MAP_EVERY EXISTS_TAC [`muci:A`;`muP:A`] THEN REPEAT CONJ_TAC THENL
     [USE_THEN "mD" ACCEPT_TAC; USE_THEN "PD" ACCEPT_TAC;
      USE_THEN "mch" ACCEPT_TAC; USE_THEN "Pch" ACCEPT_TAC;
      MAP_EVERY X_GEN_TAC [`b:A`;`c:A`] THEN
      DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "bD") (LABEL_TAC "cD")) THEN
      USE_THEN "ach0" (MP_TAC o SPECL [`b:A`;`c:A`]) THEN
      ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MATCH_MP_TAC(TAUT `(a ==> (b <=> c)) ==> (a /\ b <=> a /\ c)`) THEN
      DISCH_THEN(LABEL_TAC "bB") THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`ci:A`;`P:A`;`B:A`;`X:A`;`s:A`;
                    `muci:A`;`muP:A`;`muci0:A`;`muP0:A`;`b:A`;`c:A`]
        MUPREL_X_AGREE) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN(ACCEPT_TAC o GSYM)]];
    USE_THEN "fixnm" ACCEPT_TAC]);;

let EHSSYM_ELIM = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X nm.
      hsbundle D E w1 om tw ii ci P leqp B inclB onebee X /\
      ehssym D E B w1 X nm
      ==> ?e. e IN D /\ (?n. n IN D /\ E n w1 /\ ?f. ebij D E f n e) /\
              esubset D E e w1 /\
              (!s. s IN D /\ eperm D E w1 s /\ efixes D E s e
                   ==> ?muci muP autB.
                 muci IN D /\ muP IN D /\ autB IN D /\
                 ebij D E muci ci ci /\ ebij D E muP P P /\
                 ebij D E autB B B /\
                 (!u w. u IN D /\ w IN D
                        ==> (eapply D E muci u w <=>
                             E u ci /\ mucirel D E s u w)) /\
                 (!p q. p IN D /\ q IN D
                        ==> (eapply D E muP p q <=>
                             E p P /\ muPrel D E muci p q)) /\
                 (!b c. b IN D /\ c IN D
                        ==> (eapply D E autB b c <=>
                             E b B /\ muPrel D E muP b c)) /\
                 (!pa pb qa qb. pa IN D /\ pb IN D /\ qa IN D /\ qb IN D /\
                                eapply D E muP pa qa /\ eapply D E muP pb qb
                                ==> (erel D E leqp pa pb <=>
                                     erel D E leqp qa qb)) /\
                 (!a b ai bi. a IN D /\ b IN D /\ ai IN D /\ bi IN D /\
                              eapply D E autB a ai /\ eapply D E autB b bi
                              ==> (erel D E inclB a b <=>
                                   erel D E inclB ai bi)) /\
                 eautn D E B autB nm nm)`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (MP_TAC o REWRITE_RULE[hsbundle])
             (LABEL_TAC "hs")) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
   (CONJUNCTS_THEN2 (LABEL_TAC "vl")
    (CONJUNCTS_THEN2 (LABEL_TAC "eom")
     (CONJUNCTS_THEN2 (LABEL_TAC "w1D")
      (CONJUNCTS_THEN2 (LABEL_TAC "w1card")
       (CONJUNCTS_THEN2 (LABEL_TAC "omw1")
        (CONJUNCTS_THEN2 (LABEL_TAC "w1min")
         (CONJUNCTS_THEN2 (LABEL_TAC "cr1")
          (CONJUNCTS_THEN2 (LABEL_TAC "cr2")
           (CONJUNCTS_THEN2 (LABEL_TAC "ftw")
            (CONJUNCTS_THEN2 (LABEL_TAC "coh")
             (CONJUNCTS_THEN2 (LABEL_TAC "leq")
              (CONJUNCTS_THEN2 (LABEL_TAC "ros")
               (CONJUNCTS_THEN2 (LABEL_TAC "inc")
                (CONJUNCTS_THEN2 (LABEL_TAC "porder")
                 (CONJUNCTS_THEN2 (LABEL_TAC "top")
                  (CONJUNCTS_THEN2 (LABEL_TAC "oneD")
                   (CONJUNCTS_THEN2 (LABEL_TAC "BD")
                    (CONJUNCTS_THEN2 (LABEL_TAC "oneB")
                     (CONJUNCTS_THEN2 (LABEL_TAC "XD")
                      (CONJUNCTS_THEN2 (LABEL_TAC "ciX")
                        (LABEL_TAC "PX")))))))))))))))))))))) THEN
  SUBGOAL_THEN
   `!p u. p IN D /\ E p P /\ u IN D /\ E u p ==> (E:A->A->bool) u ci`
   (LABEL_TAC "Pci") THENL
   [REPEAT GEN_TAC THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "pD")
               (CONJUNCTS_THEN2 (LABEL_TAC "pP")
      (CONJUNCTS_THEN2 (LABEL_TAC "uD") (LABEL_TAC "up")))) THEN
    USE_THEN "coh" (MP_TAC o SPEC `p:A` o CONJUNCT2 o
                    REWRITE_RULE[ecohenp]) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "pP" (MP_TAC o EQ_MP th)) THEN
    DISCH_THEN(MP_TAC o SPEC `u:A` o REWRITE_RULE[esubset] o CONJUNCT1) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!bb x. bb IN D /\ E bb B /\ x IN D /\ E x bb ==> (E:A->A->bool) x P`
   (LABEL_TAC "BP") THENL
   [REPEAT GEN_TAC THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "bbD")
               (CONJUNCTS_THEN2 (LABEL_TAC "bbB")
      (CONJUNCTS_THEN2 (LABEL_TAC "xD") (LABEL_TAC "xbb")))) THEN
    USE_THEN "ros" (MP_TAC o SPEC `bb:A` o CONJUNCT2 o
                    REWRITE_RULE[eroset]) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "bbB" (MP_TAC o EQ_MP th)) THEN
    DISCH_THEN(MP_TAC o SPEC `x:A` o REWRITE_RULE[esubset] o CONJUNCT1) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  USE_THEN "hs" (MP_TAC o REWRITE_RULE[ehssym]) THEN
  DISCH_THEN(X_CHOOSE_THEN `e:A` (CONJUNCTS_THEN2 (LABEL_TAC "eD")
    (CONJUNCTS_THEN2 (LABEL_TAC "efin") (CONJUNCTS_THEN2 (LABEL_TAC "esub")
      (LABEL_TAC "fall"))))) THEN
  EXISTS_TAC `e:A` THEN REPEAT CONJ_TAC THENL
   [USE_THEN "eD" ACCEPT_TAC; USE_THEN "efin" ACCEPT_TAC;
    USE_THEN "esub" ACCEPT_TAC; ALL_TAC] THEN
  X_GEN_TAC `s:A` THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "sD")
             (CONJUNCTS_THEN2 (LABEL_TAC "sperm")
    (LABEL_TAC "sfix"))) THEN
  USE_THEN "fall" (MP_TAC o SPEC `s:A`) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `autB:A` (CONJUNCTS_THEN2 (LABEL_TAC "aD")
    (CONJUNCTS_THEN2 (X_CHOOSE_THEN `muci:A` (X_CHOOSE_THEN `muP:A`
      (CONJUNCTS_THEN2 (LABEL_TAC "mD") (CONJUNCTS_THEN2 (LABEL_TAC "PD")
        (CONJUNCTS_THEN2 (LABEL_TAC "mch") (CONJUNCTS_THEN2 (LABEL_TAC "Pch")
          (LABEL_TAC "ach")))))))
     (LABEL_TAC "fixnm")))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;
                `ii:A`;`ci:A`;`P:A`;
                `leqp:A`;`s:A`] PERM_MUP_BUNDLE) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `muci0:A` (X_CHOOSE_THEN `muP0:A`
    (CONJUNCTS_THEN2 (LABEL_TAC "m0D") (CONJUNCTS_THEN2 (LABEL_TAC "P0D")
     (CONJUNCTS_THEN2 (LABEL_TAC "bm0") (CONJUNCTS_THEN2 (LABEL_TAC "bP0")
      (CONJUNCTS_THEN2 (LABEL_TAC "mch0") (CONJUNCTS_THEN2 (LABEL_TAC "Pch0")
        (LABEL_TAC "quadP0"))))))))) THEN
  SUBGOAL_THEN
   `!b c. b IN D /\ c IN D
          ==> (eapply D (E:A->A->bool) autB b c <=> E b B /\
               muPrel D E muP0 b c)`
   (LABEL_TAC "ach0") THENL
   [MAP_EVERY X_GEN_TAC [`b:A`;`c:A`] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "bD") (LABEL_TAC "cD")) THEN
    USE_THEN "ach" (MP_TAC o SPECL [`b:A`;`c:A`]) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MATCH_MP_TAC(TAUT `(a ==> (b <=> c)) ==> (a /\ b <=> a /\ c)`) THEN
    DISCH_THEN(LABEL_TAC "bB") THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`ci:A`;`P:A`;`B:A`;`X:A`;`s:A`;
                  `muci:A`;`muP:A`;`muci0:A`;`muP0:A`;`b:A`;`c:A`]
      MUPREL_X_AGREE) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `ebij D (E:A->A->bool) autB B B` (LABEL_TAC "bA") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`B:A`;`muP0:A`;
                  `autB:A`] EAUTB_EBIJ) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!a b ai bi. a IN D /\ b IN D /\ ai IN D /\ bi IN D /\
                eapply D (E:A->A->bool) autB a ai /\ eapply D E autB b bi
                ==> (erel D E inclB a b <=> erel D E inclB ai bi)`
   (LABEL_TAC "quadB") THENL
   [MAP_EVERY X_GEN_TAC [`a:A`;`b:A`;`ai:A`;`bi:A`] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "a_D")
               (CONJUNCTS_THEN2 (LABEL_TAC "b_D")
      (CONJUNCTS_THEN2 (LABEL_TAC "ai_D") (CONJUNCTS_THEN2 (LABEL_TAC "bi_D")
        (CONJUNCTS_THEN2 (LABEL_TAC "aai") (LABEL_TAC "bbi")))))) THEN
    USE_THEN "ach0" (MP_TAC o SPECL [`a:A`;`ai:A`]) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "aai" (MP_TAC o EQ_MP th)) THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "aB") (LABEL_TAC "maai")) THEN
    USE_THEN "ach0" (MP_TAC o SPECL [`b:A`;`bi:A`]) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "bbi" (MP_TAC o EQ_MP th)) THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "bB") (LABEL_TAC "mbbi")) THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`B:A`;`inclB:A`;
                  `muP0:A`;`a:A`;`b:A`;`ai:A`;`bi:A`] EAUTB_ORDER) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`muci0:A`;`muP0:A`;`autB:A`] THEN
  REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC);;

(* ===================================================================== *)
(* H0 (part 2) : EHSSYM_ELIM_ALL + countable supports.                      *)
(* A support e is "countable": e IN D, esubset e w1 and ?n IN w1. ebij f n e.*)
(* CSUPPORT_EMPTY / CSUPPORT_SING / CSUPPORT_UNION (countable union via     *)
(* ECOUNTABLE_BELOW_A1 + EINJ_COMPOSE + EINJ_UNION2 + ECARDOF_EXISTS +      *)
(* EINJ_ORDINAL_CARD_LE: |e1 U e2| <= omega IN w1).                          *)
(* ===================================================================== *)
let EHSSYM_ELIM_ALL = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X nm.
      hsbundle D E w1 om tw ii ci P leqp B inclB onebee X /\
      ehssym D E B w1 X nm
      ==> ?e. e IN D /\ (?n. n IN D /\ E n w1 /\ ?f. ebij D E f n e) /\
              esubset D E e w1 /\
              (!s. s IN D /\ eperm D E w1 s /\ efixes D E s e
                   ==> !muci muP autB.
                         muci IN D /\ muP IN D /\ autB IN D /\
                         (!u w. u IN D /\ w IN D
                                ==> (eapply D E muci u w <=>
                                     E u ci /\ mucirel D E s u w)) /\
                         (!p q. p IN D /\ q IN D
                                ==> (eapply D E muP p q <=>
                                     E p P /\ muPrel D E muci p q)) /\
                         (!b c. b IN D /\ c IN D
                                ==> (eapply D E autB b c <=>
                                     E b B /\ muPrel D E muP b c))
                         ==> eautn D E B autB nm nm)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  SUBGOAL_THEN `model D (E:A->A->bool) ZF_AX /\ (B:A) IN D`
   (CONJUNCTS_THEN2 (LABEL_TAC "modl") (LABEL_TAC "BD")) THENL
   [FIRST_ASSUM(MP_TAC o REWRITE_RULE[hsbundle] o CONJUNCT1) THEN MESON_TAC[];
    ALL_TAC] THEN
  FIRST_ASSUM(MP_TAC o MATCH_MP EHSSYM_ELIM) THEN
  DISCH_THEN(X_CHOOSE_THEN `e:A` (CONJUNCTS_THEN2 (LABEL_TAC "eD")
    (CONJUNCTS_THEN2 (LABEL_TAC "efin") (CONJUNCTS_THEN2 (LABEL_TAC "esub")
      (LABEL_TAC "fall"))))) THEN
  EXISTS_TAC `e:A` THEN REPEAT CONJ_TAC THENL
   [USE_THEN "eD" ACCEPT_TAC; USE_THEN "efin" ACCEPT_TAC;
    USE_THEN "esub" ACCEPT_TAC; ALL_TAC] THEN
  X_GEN_TAC `s:A` THEN DISCH_THEN(LABEL_TAC "sfx") THEN
  MAP_EVERY X_GEN_TAC [`muci:A`;`muP:A`;`autB:A`] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "mD") (CONJUNCTS_THEN2 (LABEL_TAC "PD")
    (CONJUNCTS_THEN2 (LABEL_TAC "aD") (CONJUNCTS_THEN2 (LABEL_TAC "mch")
      (CONJUNCTS_THEN2 (LABEL_TAC "Pch") (LABEL_TAC "ach")))))) THEN
  USE_THEN "fall" (MP_TAC o SPEC `s:A`) THEN
  ANTS_TAC THENL [USE_THEN "sfx" ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `muci0:A` (X_CHOOSE_THEN `muP0:A`
      (X_CHOOSE_THEN `autB0:A`
    (CONJUNCTS_THEN2 (K ALL_TAC) (CONJUNCTS_THEN2 (K ALL_TAC)
     (CONJUNCTS_THEN2 (LABEL_TAC "a0D") (CONJUNCTS_THEN2 (K ALL_TAC)
      (CONJUNCTS_THEN2 (K ALL_TAC) (CONJUNCTS_THEN2 (K ALL_TAC)
       (CONJUNCTS_THEN2 (LABEL_TAC "mch0") (CONJUNCTS_THEN2 (LABEL_TAC "Pch0")
        (CONJUNCTS_THEN2 (LABEL_TAC "ach0") (CONJUNCTS_THEN2 (K ALL_TAC)
         (CONJUNCTS_THEN2 (K ALL_TAC) (LABEL_TAC "fix0"))))))))))))))) THEN
  SUBGOAL_THEN
   `!c c'. c IN D /\ c' IN D
           ==> (eapply D (E:A->A->bool) autB0 c c' <=> eapply D E autB c c')`
   (LABEL_TAC "gr") THENL
   [MATCH_MP_TAC BUNDLE_AGREE THEN
    MAP_EVERY EXISTS_TAC [`ci:A`;`P:A`;`B:A`;`s:A`;`muci0:A`;`muP0:A`;
                          `muci:A`;`muP:A`] THEN
    REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB0:A`;
                `autB:A`;`nm:A`;`nm:A`]
    EAUTN_CONG) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN USE_THEN "fix0" ACCEPT_TAC);;

let CSUPPORT_EMPTY = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X.
      hsbundle D E w1 om tw ii ci P leqp B inclB onebee X
      ==> ?e. e IN D /\ (!z. z IN D ==> ~(E z e)) /\
              (?n. n IN D /\ E n w1 /\ ?f. ebij D E f n e) /\
              esubset D E e w1`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "hsb") THEN
  USE_THEN "hsb" (MP_TAC o MATCH_MP HSB_FACTS) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "omD") (CONJUNCTS_THEN2 (K ALL_TAC)
    (CONJUNCTS_THEN2 (K ALL_TAC) (CONJUNCTS_THEN2 (K ALL_TAC)
      (CONJUNCTS_THEN2 (K ALL_TAC) (LABEL_TAC "omw1")))))) THEN
  USE_THEN "hsb" (MP_TAC o REWRITE_RULE[hsbundle]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl") (CONJUNCTS_THEN2 (K ALL_TAC)
    (CONJUNCTS_THEN2 (LABEL_TAC "eom") (K ALL_TAC)))) THEN
  USE_THEN "modl" (X_CHOOSE_THEN `e0:A` (LABEL_TAC "emp") o MATCH_MP
                   EEMPTY_EXISTS) THEN
  SUBGOAL_THEN `(e0:A) IN D` (LABEL_TAC "e0D") THENL
   [USE_THEN "emp" (ACCEPT_TAC o MATCH_MP EEMPTY_IN); ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) e0 om` (LABEL_TAC "e0om") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`om:A`;`e0:A`] EOMEGA_EMPTY) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  EXISTS_TAC `e0:A` THEN REPEAT CONJ_TAC THENL
   [USE_THEN "e0D" ACCEPT_TAC;
    USE_THEN "emp" (ACCEPT_TAC o CONJUNCT2 o REWRITE_RULE[eempty]);
    EXISTS_TAC `e0:A` THEN REPEAT CONJ_TAC THENL
     [USE_THEN "e0D" ACCEPT_TAC;
      USE_THEN "omw1" (MP_TAC o SPEC `e0:A`) THEN
      ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN ACCEPT_TAC];
      EXISTS_TAC `e0:A` THEN USE_THEN "emp"
          (ACCEPT_TAC o MATCH_MP EBIJ_EEMPTY)];
    USE_THEN "emp" (ACCEPT_TAC o SPEC `w1:A` o MATCH_MP EEMPTY_SUBSET)]);;

let CSUPPORT_SING = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X al.
      hsbundle D E w1 om tw ii ci P leqp B inclB onebee X /\
      al IN D /\ E al w1
      ==> ?e. e IN D /\ (!z. z IN D ==> (E z e <=> z = al)) /\
              (?n. n IN D /\ E n w1 /\ ?f. ebij D E f n e) /\
              esubset D E e w1`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "hsb")
             (CONJUNCTS_THEN2 (LABEL_TAC "alD")
    (LABEL_TAC "alw1"))) THEN
  USE_THEN "hsb" (MP_TAC o MATCH_MP HSB_FACTS) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "omD") (CONJUNCTS_THEN2 (K ALL_TAC)
    (CONJUNCTS_THEN2 (K ALL_TAC) (CONJUNCTS_THEN2 (K ALL_TAC)
      (CONJUNCTS_THEN2 (K ALL_TAC) (LABEL_TAC "omw1")))))) THEN
  USE_THEN "hsb" (MP_TAC o REWRITE_RULE[hsbundle]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl") (CONJUNCTS_THEN2 (K ALL_TAC)
    (CONJUNCTS_THEN2 (LABEL_TAC "eom") (K ALL_TAC)))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`om:A`;`al:A`] ESING_FINITE) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `e:A` (CONJUNCTS_THEN2 (LABEL_TAC "eD")
    (CONJUNCTS_THEN2 (LABEL_TAC "ech") (X_CHOOSE_THEN `n:A`
      (CONJUNCTS_THEN2 (LABEL_TAC "nD") (CONJUNCTS_THEN2 (LABEL_TAC "nom")
        (LABEL_TAC "nf"))))))) THEN
  EXISTS_TAC `e:A` THEN REPEAT CONJ_TAC THENL
   [USE_THEN "eD" ACCEPT_TAC;
    USE_THEN "ech" ACCEPT_TAC;
    EXISTS_TAC `n:A` THEN REPEAT CONJ_TAC THENL
     [USE_THEN "nD" ACCEPT_TAC;
      USE_THEN "omw1" (MP_TAC o SPEC `n:A`) THEN
      ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN ACCEPT_TAC];
      USE_THEN "nf" ACCEPT_TAC];
    REWRITE_TAC[esubset] THEN X_GEN_TAC `z:A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "zD") (LABEL_TAC "ze")) THEN
    SUBGOAL_THEN `z:A = al` SUBST1_TAC THENL
     [USE_THEN "ech" (MP_TAC o SPEC `z:A`) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> USE_THEN "ze" (ACCEPT_TAC o EQ_MP th));
      USE_THEN "alw1" ACCEPT_TAC]]);;

let CSUPPORT_UNION = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X e1 e2.
      hsbundle D E w1 om tw ii ci P leqp B inclB onebee X /\
      e1 IN D /\ (?n. n IN D /\ E n w1 /\ ?f. ebij D E f n e1) /\
      esubset D E e1 w1 /\
      e2 IN D /\ (?n. n IN D /\ E n w1 /\ ?f. ebij D E f n e2) /\
      esubset D E e2 w1
      ==> ?e. e IN D /\ (?n. n IN D /\ E n w1 /\ ?f. ebij D E f n e) /\
              esubset D E e w1 /\ esubset D E e1 e /\ esubset D E e2 e`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "hsb")
   (CONJUNCTS_THEN2 (LABEL_TAC "e1D")
    (CONJUNCTS_THEN2 (X_CHOOSE_THEN `n1:A` (CONJUNCTS_THEN2 (LABEL_TAC "n1D")
       (CONJUNCTS_THEN2 (LABEL_TAC "n1w")
        (X_CHOOSE_THEN `f1:A` (LABEL_TAC "bf1")))))
     (CONJUNCTS_THEN2 (LABEL_TAC "s1")
      (CONJUNCTS_THEN2 (LABEL_TAC "e2D")
       (CONJUNCTS_THEN2 (X_CHOOSE_THEN `n2:A` (CONJUNCTS_THEN2 (LABEL_TAC "n2D")
          (CONJUNCTS_THEN2 (LABEL_TAC "n2w")
           (X_CHOOSE_THEN `f2:A` (LABEL_TAC "bf2")))))
         (LABEL_TAC "s2"))))))) THEN
  USE_THEN "hsb" (MP_TAC o MATCH_MP HSB_FACTS) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "omD")
             (CONJUNCTS_THEN2 (LABEL_TAC "w1ord")
    (CONJUNCTS_THEN2 (K ALL_TAC) (CONJUNCTS_THEN2 (K ALL_TAC)
      (CONJUNCTS_THEN2 (K ALL_TAC) (LABEL_TAC "omw1")))))) THEN
  USE_THEN "hsb" (MP_TAC o REWRITE_RULE[hsbundle]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
             (CONJUNCTS_THEN2 (LABEL_TAC "vl")
    (CONJUNCTS_THEN2 (LABEL_TAC "eom") (CONJUNCTS_THEN2 (LABEL_TAC "w1D")
      (CONJUNCTS_THEN2 (LABEL_TAC "w1card") (CONJUNCTS_THEN2 (LABEL_TAC "omw1e")
        (CONJUNCTS_THEN2 (LABEL_TAC "w1min") (K ALL_TAC)))))))) THEN
  (* each ei injects into om *)
  SUBGOAL_THEN
   `!ei ni fi. ei IN D /\ ni IN D /\ E ni w1 /\ ebij D (E:A->A->bool) fi ni ei
               ==> ?k. einj D E k ei om`
   (LABEL_TAC "toom") THENL
   [REPEAT GEN_TAC THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "eiD")
               (CONJUNCTS_THEN2 (LABEL_TAC "niD")
      (CONJUNCTS_THEN2 (LABEL_TAC "niw") (LABEL_TAC "bfi")))) THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`fi:A`;`ni:A`;`ei:A`]
           EBIJ_INV_CHAR) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `gi:A` (CONJUNCTS_THEN2 (K ALL_TAC)
      (CONJUNCTS_THEN2 (LABEL_TAC "bgi") (K ALL_TAC)))) THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`om:A`;`w1:A`;`ni:A`]
      ECOUNTABLE_BELOW_A1) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `hi:A` (LABEL_TAC "ihi")) THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`gi:A`;`hi:A`;`ei:A`;`ni:A`;`om:A`]
      EINJ_COMPOSE) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      USE_THEN "bgi" (ACCEPT_TAC o MATCH_MP EBIJ_EINJ);
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  USE_THEN "toom" (MP_TAC o SPECL [`e1:A`;`n1:A`;`f1:A`]) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `k1:A` (LABEL_TAC "ik1")) THEN
  USE_THEN "toom" (MP_TAC o SPECL [`e2:A`;`n2:A`;`f2:A`]) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `k2:A` (LABEL_TAC "ik2")) THEN
  (* un = e1 UNION e2 *)
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`e1:A`;`e2:A`] EBUNION_EXISTS) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `un:A` (LABEL_TAC "unu")) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`e1:A`;`e2:A`;`un:A`]
         EBUNION_ALT) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> USE_THEN "unu" (MP_TAC o EQ_MP th)) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "unD") (LABEL_TAC "unch")) THEN
  (* 0 and 1 in om, distinct *)
  USE_THEN "modl" (X_CHOOSE_THEN `z0:A` (LABEL_TAC "emp") o MATCH_MP
                   EEMPTY_EXISTS) THEN
  SUBGOAL_THEN `(z0:A) IN D` (LABEL_TAC "z0D") THENL
   [USE_THEN "emp" (ACCEPT_TAC o MATCH_MP EEMPTY_IN); ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) z0 om` (LABEL_TAC "z0om") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`om:A`;`z0:A`] EOMEGA_EMPTY) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`z0:A`] ESUC_EXISTS) THEN
  ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `z1:A` (LABEL_TAC "z1suc")) THEN
  SUBGOAL_THEN `(z1:A) IN D` (LABEL_TAC "z1D") THENL
   [USE_THEN "z1suc" (ACCEPT_TAC o MATCH_MP ESUC_IN); ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) z1 om` (LABEL_TAC "z1om") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`om:A`;`z0:A`;`z1:A`]
           EOMEGA_SUC) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `~(z0:A = z1)` (LABEL_TAC "z01") THENL
   [DISCH_TAC THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`z0:A`;`z1:A`] ESUC_MEMBER) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    FIRST_X_ASSUM((fun th -> REWRITE_TAC[GSYM th]) o check (is_eq o concl)) THEN
    USE_THEN "emp" (MP_TAC o SPEC `z0:A` o CONJUNCT2 o
                    REWRITE_RULE[eempty]) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; MESON_TAC[]];
    ALL_TAC] THEN
  (* un injects into om *)
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`om:A`;`om:A`;`e1:A`;
                `e2:A`;`k1:A`;`k2:A`;
                `un:A`;`z0:A`;`z1:A`] EINJ_UNION2) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`om:A`] EOMEGA_CARDINAL) THEN
      ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      REWRITE_TAC[ecardinal]];
      DISJ2_TAC THEN REFL_TAC];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ku:A` (LABEL_TAC "iku")) THEN
  (* |un| = cx with cx <= om, hence cx IN w1 *)
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`un:A`] ECARDOF_EXISTS) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `cx:A` (LABEL_TAC "cxof")) THEN
  SUBGOAL_THEN `(cx:A) IN D /\ ?f. ebij D (E:A->A->bool) f cx un`
   (CONJUNCTS_THEN2 (LABEL_TAC "cxD") (LABEL_TAC "cxbij")) THENL
   [USE_THEN "cxof" (MP_TAC o REWRITE_RULE[ecardof]) THEN
    MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) cx w1` (LABEL_TAC "cxw1") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`ku:A`;`un:A`;`om:A`;`cx:A`]
      EINJ_ORDINAL_CARD_LE) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      MATCH_MP_TAC EOMEGA_ORDINAL THEN CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
      ALL_TAC] THEN
    DISCH_THEN(DISJ_CASES_THEN ASSUME_TAC) THENL
     [USE_THEN "omw1" (MP_TAC o SPEC `cx:A`) THEN
      ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN ACCEPT_TAC];
      FIRST_X_ASSUM(SUBST1_TAC o check (is_eq o concl)) THEN
      USE_THEN "omw1e" ACCEPT_TAC];
    ALL_TAC] THEN
  EXISTS_TAC `un:A` THEN REPEAT CONJ_TAC THENL
   [USE_THEN "unD" ACCEPT_TAC;
    EXISTS_TAC `cx:A` THEN REPEAT CONJ_TAC THENL
     [USE_THEN "cxD" ACCEPT_TAC; USE_THEN "cxw1" ACCEPT_TAC;
      USE_THEN "cxbij" ACCEPT_TAC];
    REWRITE_TAC[esubset] THEN X_GEN_TAC `z:A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "zD") (LABEL_TAC "zun")) THEN
    USE_THEN "unch" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "zun" (MP_TAC o EQ_MP th)) THEN
    STRIP_TAC THENL
     [USE_THEN "s1" (MP_TAC o SPEC `z:A` o REWRITE_RULE[esubset]) THEN
      ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN ACCEPT_TAC];
      USE_THEN "s2" (MP_TAC o SPEC `z:A` o REWRITE_RULE[esubset]) THEN
      ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN ACCEPT_TAC]];
    REWRITE_TAC[esubset] THEN X_GEN_TAC `z:A` THEN STRIP_TAC THEN
    USE_THEN "unch" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    DISJ1_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    REWRITE_TAC[esubset] THEN X_GEN_TAC `z:A` THEN STRIP_TAC THEN
    USE_THEN "unch" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    DISJ2_TAC THEN FIRST_ASSUM ACCEPT_TAC]);;

(* ===================================================================== *)
(* H0 (part 3a) : EHSSYM_CHECK, GOODHS_STEP, HS_CHECK -- check-names        *)
(* are HS names at the countable-support parameter w1.                      *)
(* ===================================================================== *)
let EHSSYM_CHECK = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X x vx.
      hsbundle D E w1 om tw ii ci P leqp B inclB onebee X /\
      x IN D /\ vx IN D /\ echeck D E onebee x vx
      ==> ehssym D E B w1 X vx`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "hsb") (CONJUNCTS_THEN2 (LABEL_TAC "xD")
    (CONJUNCTS_THEN2 (LABEL_TAC "vxD") (LABEL_TAC "chk")))) THEN
  USE_THEN "hsb" (MP_TAC o MATCH_MP CSUPPORT_EMPTY) THEN
  DISCH_THEN(X_CHOOSE_THEN `e0:A` (CONJUNCTS_THEN2 (LABEL_TAC "e0D")
    (CONJUNCTS_THEN2 (K ALL_TAC) (CONJUNCTS_THEN2 (LABEL_TAC "e0fin")
      (LABEL_TAC "e0sub"))))) THEN
  USE_THEN "hsb" (MP_TAC o REWRITE_RULE[hsbundle]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
   (CONJUNCTS_THEN2 (LABEL_TAC "vl")
    (CONJUNCTS_THEN2 (LABEL_TAC "eom")
     (CONJUNCTS_THEN2 (LABEL_TAC "w1D")
      (CONJUNCTS_THEN2 (LABEL_TAC "w1card")
       (CONJUNCTS_THEN2 (LABEL_TAC "omw1")
        (CONJUNCTS_THEN2 (LABEL_TAC "w1min")
         (CONJUNCTS_THEN2 (LABEL_TAC "cr1")
          (CONJUNCTS_THEN2 (LABEL_TAC "cr2")
           (CONJUNCTS_THEN2 (LABEL_TAC "ftw")
            (CONJUNCTS_THEN2 (LABEL_TAC "coh")
             (CONJUNCTS_THEN2 (LABEL_TAC "leq")
              (CONJUNCTS_THEN2 (LABEL_TAC "ros")
               (CONJUNCTS_THEN2 (LABEL_TAC "inc")
                (CONJUNCTS_THEN2 (LABEL_TAC "porder")
                 (CONJUNCTS_THEN2 (LABEL_TAC "top")
                  (CONJUNCTS_THEN2 (LABEL_TAC "oneD")
                   (CONJUNCTS_THEN2 (LABEL_TAC "BD")
                    (CONJUNCTS_THEN2 (LABEL_TAC "oneB")
                     (CONJUNCTS_THEN2 (LABEL_TAC "XD")
                      (CONJUNCTS_THEN2 (LABEL_TAC "ciX")
                        (LABEL_TAC "PX")))))))))))))))))))))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;
                `ii:A`;`ci:A`;`P:A`;
                `leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`vx:A`;`e0:A`]
                    EHSSYM_INTRO) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    X_GEN_TAC `s:A` THEN DISCH_THEN(K ALL_TAC) THEN
    MAP_EVERY X_GEN_TAC [`muci:A`;`muP:A`;`autB:A`] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (CONJUNCTS_THEN2 (K ALL_TAC)
     (CONJUNCTS_THEN2 (LABEL_TAC "aD") (CONJUNCTS_THEN2 (K ALL_TAC)
      (CONJUNCTS_THEN2 (K ALL_TAC) (CONJUNCTS_THEN2 (LABEL_TAC "bA")
       (CONJUNCTS_THEN2 (K ALL_TAC) (CONJUNCTS_THEN2 (K ALL_TAC)
        (CONJUNCTS_THEN2 (K ALL_TAC) (CONJUNCTS_THEN2 (K ALL_TAC)
          (LABEL_TAC "quadB"))))))))))) THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;`inclB:A`;
                  `autB:A`;`x:A`;`vx:A`] EAUT_CHECK) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    DISCH_THEN ACCEPT_TAC]);;

let GOODHS_STEP = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X d.
      hsbundle D E w1 om tw ii ci P leqp B inclB onebee X /\
      eordinal D E d /\
      (!b'. b' IN D /\ E b' d
            ==> !zb pp x vv.
                   zb IN D /\ pp IN D /\ x IN D /\ vv IN D /\
                   echecktower D E onebee b' zb /\ E pp zb /\
                   eopair D E x vv pp
                   ==> hsname D E B w1 X vv)
      ==> !zd pp x vv.
             zd IN D /\ pp IN D /\ x IN D /\ vv IN D /\
             echecktower D E onebee d zd /\ E pp zd /\ eopair D E x vv pp
             ==> hsname D E B w1 X vv`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "hsb")
   (CONJUNCTS_THEN2 (LABEL_TAC "dord") (LABEL_TAC "IH"))) THEN
  USE_THEN "hsb" (MP_TAC o REWRITE_RULE[hsbundle]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
   (CONJUNCTS_THEN2 (LABEL_TAC "vl")
    (CONJUNCTS_THEN2 (LABEL_TAC "eom")
     (CONJUNCTS_THEN2 (LABEL_TAC "w1D")
      (CONJUNCTS_THEN2 (LABEL_TAC "w1card")
       (CONJUNCTS_THEN2 (LABEL_TAC "omw1")
        (CONJUNCTS_THEN2 (LABEL_TAC "w1min")
         (CONJUNCTS_THEN2 (LABEL_TAC "cr1")
          (CONJUNCTS_THEN2 (LABEL_TAC "cr2")
           (CONJUNCTS_THEN2 (LABEL_TAC "ftw")
            (CONJUNCTS_THEN2 (LABEL_TAC "coh")
             (CONJUNCTS_THEN2 (LABEL_TAC "leq")
              (CONJUNCTS_THEN2 (LABEL_TAC "ros")
               (CONJUNCTS_THEN2 (LABEL_TAC "inc")
                (CONJUNCTS_THEN2 (LABEL_TAC "porder")
                 (CONJUNCTS_THEN2 (LABEL_TAC "top")
                  (CONJUNCTS_THEN2 (LABEL_TAC "oneD")
                   (CONJUNCTS_THEN2 (LABEL_TAC "BD")
                    (CONJUNCTS_THEN2 (LABEL_TAC "oneB")
                     (CONJUNCTS_THEN2 (LABEL_TAC "XD")
                      (CONJUNCTS_THEN2 (LABEL_TAC "ciX")
                        (LABEL_TAC "PX")))))))))))))))))))))) THEN
  MAP_EVERY X_GEN_TAC [`zd:A`;`pp:A`;`x:A`;`vv:A`] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "zdD")
    (CONJUNCTS_THEN2 (LABEL_TAC "ppD")
      (CONJUNCTS_THEN2 (LABEL_TAC "xD")
        (CONJUNCTS_THEN2 (LABEL_TAC "vvD")
          (CONJUNCTS_THEN2 (LABEL_TAC "tow")
            (CONJUNCTS_THEN2 (LABEL_TAC "ppzd") (LABEL_TAC "pairp"))))))) THEN
  (* echeck onebee x vv (needed by ECHECK_HSNAME_SUCC at the end) *)
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`d:A`;`zd:A`;`x:A`;`vv:A`;
                `pp:A`] ECHECK_STAGE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(LABEL_TAC "chk") THEN
  (* expose the accumulator gacc and (pinned) image vv via ECHECKTOWER_VALUE *)
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`d:A`;`zd:A`;`pp:A`]
        ECHECKTOWER_VALUE) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `gacc:A` (X_CHOOSE_THEN `w:A`
    (X_CHOOSE_THEN `x2:A` (X_CHOOSE_THEN `img:A`
      (CONJUNCTS_THEN2 (LABEL_TAC "gaccD") (CONJUNCTS_THEN2 (LABEL_TAC "wD")
        (CONJUNCTS_THEN2 (LABEL_TAC "x2D") (CONJUNCTS_THEN2 (LABEL_TAC "imgD")
          (CONJUNCTS_THEN2 (LABEL_TAC "gaccch")
           (CONJUNCTS_THEN2 (LABEL_TAC "domn")
            (CONJUNCTS_THEN2 (LABEL_TAC "pairx")
             (CONJUNCTS_THEN2 (LABEL_TAC "subxw")
              (LABEL_TAC "imgch"))))))))))))) THEN
  SUBGOAL_THEN `x2:A = x /\ img:A = vv`
    (CONJUNCTS_THEN2 SUBST_ALL_TAC SUBST_ALL_TAC) THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`x2:A`;`img:A`;`x:A`;`vv:A`;`pp:A`]
      EOPAIR_INJ) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* CORE: every domain element u of vv is a B-name (via the IH at b'<d) *)
  SUBGOAL_THEN `!u:A. u IN D /\ eindom D E vv u ==> hsname D E B w1 X u`
  (LABEL_TAC "core") THENL
   [X_GEN_TAC `u:A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "uD")
      (MP_TAC o REWRITE_RULE[eindom])) THEN
    DISCH_THEN(X_CHOOSE_THEN `ww:A` (CONJUNCTS_THEN2 (LABEL_TAC "wwD")
      (MP_TAC o REWRITE_RULE[eapply]))) THEN
    DISCH_THEN(X_CHOOSE_THEN `z:A` (CONJUNCTS_THEN2 (LABEL_TAC "pruwz")
      (LABEL_TAC "ezvv"))) THEN
    SUBGOAL_THEN `(z:A) IN D` (LABEL_TAC "zD") THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`u:A`;`ww:A`;`z:A`]
             EOPAIR_IN) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    USE_THEN "imgch" (MP_TAC o C MATCH_MP (ASSUME `(z:A) IN D`)) THEN
    REWRITE_TAC[ASSUME `(E:A->A->bool) z vv`] THEN
    DISCH_THEN(X_CHOOSE_THEN `y:A` (CONJUNCTS_THEN2 (LABEL_TAC "yD")
      (X_CHOOSE_THEN `vy:A` (fun th -> MAP_EVERY ASSUME_TAC
                             (CONJUNCTS th))))) THEN
    SUBGOAL_THEN `u:A = vy /\ ww:A = onebee`
      (CONJUNCTS_THEN2 SUBST_ALL_TAC (K ALL_TAC)) THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`u:A`;`ww:A`;`vy:A`;`onebee:A`;
                    `z:A`] EOPAIR_INJ) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    UNDISCH_TAC `eapply D (E:A->A->bool) gacc y vy` THEN
        REWRITE_TAC[eapply] THEN
    DISCH_THEN(X_CHOOSE_THEN `p:A` (CONJUNCTS_THEN2 (LABEL_TAC "pairyp")
      (LABEL_TAC "pgacc"))) THEN
    SUBGOAL_THEN `(p:A) IN D` (LABEL_TAC "pD") THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`y:A`;`vy:A`;`p:A`]
             EOPAIR_IN) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    USE_THEN "gaccch" (MP_TAC o C MATCH_MP (ASSUME `(p:A) IN D`)) THEN
    REWRITE_TAC[ASSUME `(E:A->A->bool) p gacc`] THEN
    DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `zb:A`
      (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th)))) THEN
    USE_THEN "IH" (MP_TAC o SPEC `b:A`) THEN ANTS_TAC THENL
     [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPECL [`zb:A`;`p:A`;`y:A`;`vy:A`]) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* materialize dom(vv), all of whose members are B-names *)
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`vv:A`] EDOMAIN_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `dv:A` (LABEL_TAC "domvv")) THEN
  SUBGOAL_THEN `(dv:A) IN D` (LABEL_TAC "dvD") THENL
   [USE_THEN "domvv" (ACCEPT_TAC o CONJUNCT1 o
                      REWRITE_RULE[edomain]); ALL_TAC] THEN
  SUBGOAL_THEN `!t:A. t IN D /\ E t dv
      ==> hsname D E B w1 X t` (LABEL_TAC "allbn") THENL
   [X_GEN_TAC `t:A` THEN STRIP_TAC THEN
    USE_THEN "core" MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "domvv" (MP_TAC o SPEC `t:A` o CONJUNCT2 o
                      REWRITE_RULE[edomain]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* common bounding B-name stage of dom(vv) *)
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;`dv:A`]
         HSNAME_BOUND) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `c0:A` (X_CHOOSE_THEN `yc0:A`
    (CONJUNCTS_THEN2 (LABEL_TAC "c0D") (CONJUNCTS_THEN2 (LABEL_TAC "yc0D")
      (CONJUNCTS_THEN2 (LABEL_TAC "c0ord") (CONJUNCTS_THEN2 (LABEL_TAC "bnc0")
        (LABEL_TAC "bnd"))))))) THEN
  (* a2 = esuc c0, ya2 its B-name stage *)
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`c0:A`] ESUC_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `a2:A` (LABEL_TAC "suc")) THEN
  SUBGOAL_THEN `(a2:A) IN D` (LABEL_TAC "a2D") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`c0:A`;`a2:A`] ESUC_IN) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) a2` (LABEL_TAC "a2ord") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`c0:A`;`a2:A`] EORDINAL_ESUC) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) c0 a2` (LABEL_TAC "c0a2") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`c0:A`;`a2:A`] ESUC_MEMBER) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;`a2:A`]
         HSSTAGE_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `ya2:A` (CONJUNCTS_THEN2 (LABEL_TAC "ya2D")
    (LABEL_TAC "hsa2"))) THEN
  (* vv = x^ is symmetric with empty support (EHSSYM_CHECK)   *)
  SUBGOAL_THEN `ehssym D (E:A->A->bool) B w1 X vv` (LABEL_TAC "symvv") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;
                  `ii:A`;`ci:A`;`P:A`;
                  `leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`x:A`;`vv:A`]
      EHSSYM_CHECK) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  (* land vv at HS stage a2 via ECHECK_HSNAME_SUCC *)
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;`onebee:A`;`x:A`;
                `vv:A`;`a2:A`;`ya2:A`] ECHECK_HSNAME_SUCC) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    MAP_EVERY X_GEN_TAC [`u:A`;`ww:A`;`z:A`] THEN STRIP_TAC THEN
    MAP_EVERY EXISTS_TAC [`c0:A`;`yc0:A`] THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "bnd" MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "domvv" (MP_TAC o SPEC `u:A` o CONJUNCT2 o
                      REWRITE_RULE[edomain]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[eindom] THEN EXISTS_TAC `ww:A` THEN
    ASM_REWRITE_TAC[eapply] THEN EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[];
    DISCH_THEN ACCEPT_TAC]);;

let HS_CHECK = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X x vx.
      hsbundle D E w1 om tw ii ci P leqp B inclB onebee X /\
      x IN D /\ vx IN D /\ echeck D E onebee x vx
      ==> hsname D E B w1 X vx`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "hsb") (CONJUNCTS_THEN2 (LABEL_TAC "xD")
    (CONJUNCTS_THEN2 (LABEL_TAC "vxD") (MP_TAC o REWRITE_RULE[echeck])))) THEN
  USE_THEN "hsb" (MP_TAC o REWRITE_RULE[hsbundle]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
   (CONJUNCTS_THEN2 (LABEL_TAC "vl")
    (CONJUNCTS_THEN2 (LABEL_TAC "eom")
     (CONJUNCTS_THEN2 (LABEL_TAC "w1D")
      (CONJUNCTS_THEN2 (LABEL_TAC "w1card")
       (CONJUNCTS_THEN2 (LABEL_TAC "omw1")
        (CONJUNCTS_THEN2 (LABEL_TAC "w1min")
         (CONJUNCTS_THEN2 (LABEL_TAC "cr1")
          (CONJUNCTS_THEN2 (LABEL_TAC "cr2")
           (CONJUNCTS_THEN2 (LABEL_TAC "ftw")
            (CONJUNCTS_THEN2 (LABEL_TAC "coh")
             (CONJUNCTS_THEN2 (LABEL_TAC "leq")
              (CONJUNCTS_THEN2 (LABEL_TAC "ros")
               (CONJUNCTS_THEN2 (LABEL_TAC "inc")
                (CONJUNCTS_THEN2 (LABEL_TAC "porder")
                 (CONJUNCTS_THEN2 (LABEL_TAC "top")
                  (CONJUNCTS_THEN2 (LABEL_TAC "oneD")
                   (CONJUNCTS_THEN2 (LABEL_TAC "BD")
                    (CONJUNCTS_THEN2 (LABEL_TAC "oneB")
                     (CONJUNCTS_THEN2 (LABEL_TAC "XD")
                      (CONJUNCTS_THEN2 (LABEL_TAC "ciX")
                        (LABEL_TAC "PX")))))))))))))))))))))) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
   (CONJUNCTS_THEN2 (K ALL_TAC)
    (X_CHOOSE_THEN `a:A` (X_CHOOSE_THEN `cd:A` (X_CHOOSE_THEN `pp:A`
      (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th))))))) THEN
  (* sa = esuc a *)
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`a:A`] ESUC_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `sa:A`) THEN
  SUBGOAL_THEN `(sa:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) sa` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_ESUC]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) a sa` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_MEMBER]; ALL_TAC] THEN
  (* resolvent graph rc for the check-tower at sa *)
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`sa:A`]
    ECHECKTOWER_RESGRAPH) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `rc:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "rcc"))) THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v0:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [USE_THEN "eom" (ACCEPT_TAC o MATCH_MP EOMEGA_IN); ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((2 |-> (B:A)) v0)` ASSUME_TAC THENL
   [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
           (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC)); ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((8 |-> (w1:A)) ((2 |-> (B:A)) v0))`
      ASSUME_TAC THENL
   [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
           (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC)); ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((9 |-> (X:A)) ((8 |-> (w1:A)) ((2 |-> (B:A)) v0)))`
  ASSUME_TAC THENL [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
      (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC)); ALL_TAC] THEN
  SUBGOAL_THEN
   `valuation D ((81 |-> (rc:A)) ((9 |-> (X:A))
       ((8 |-> (w1:A)) ((2 |-> (B:A)) v0))))`
  ASSUME_TAC THENL [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
      (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC)); ALL_TAC] THEN
  (* goodhs-semantic holds at every ordinal below sa *)
  SUBGOAL_THEN
   `!dd. dd IN D /\ E dd sa
         ==> holds D E ((0 |-> dd) ((81 |-> (rc:A))
                        ((9 |-> (X:A)) ((8 |-> (w1:A)) ((2 |-> (B:A)) v0)))))
                       goodhs`
  (LABEL_TAC "good") THENL
   [GEN_TAC THEN STRIP_TAC THEN
    MATCH_MP_TAC(TAUT `(~p ==> F) ==> p`) THEN
    DISCH_THEN(LABEL_TAC "bad0") THEN
    SUBGOAL_THEN `eordinal D (E:A->A->bool) dd` ASSUME_TAC THENL
     [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`Not goodhs`;
                  `(81 |-> (rc:A)) ((9 |-> (X:A))
                                    ((8 |-> (w1:A)) ((2 |-> (B:A)) v0)))`;
                  `dd:A`]
      EORDINAL_LEAST) THEN
    ASM_REWRITE_TAC[HOLDS_NOT] THEN
    DISCH_THEN(X_CHOOSE_THEN `d:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 (LABEL_TAC "dbad")
        (LABEL_TAC "dmin"))))) THEN
    SUBGOAL_THEN `(d:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) d sa` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`d:A`;`dd:A`]
        EORDINAL_TRICHOTOMY) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN ASSUME_TAC) THENL
       [ASM_MESON_TAC[EORDINAL_TRANS_E];
        ASM_MESON_TAC[];
        USE_THEN "dmin" (MP_TAC o SPEC `dd:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        USE_THEN "bad0" (fun th -> REWRITE_TAC[th])];
      ALL_TAC] THEN
    (* IH: the semantic statement holds at every b' < d *)
    SUBGOAL_THEN
     `!b'. b' IN D /\ E b' d
           ==> !zb pp x vv.
                  zb IN D /\ pp IN D /\ x IN D /\ vv IN D /\
                  echecktower D (E:A->A->bool) onebee b' zb /\ E pp zb /\
                  eopair D E x vv pp
                  ==> hsname D E B w1 X vv`
    ASSUME_TAC THENL
     [X_GEN_TAC `b':A` THEN STRIP_TAC THEN
      SUBGOAL_THEN `(E:A->A->bool) b' sa` ASSUME_TAC THENL
       [ASM_MESON_TAC[EORDINAL_TRANS_E]; ALL_TAC] THEN
      MP_TAC(REWRITE_RULE[VALMOD; ARITH_EQ]
        (SPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`sa:A`;`rc:A`;
                `(9 |-> (X:A)) ((8 |-> (w1:A)) ((2 |-> (B:A)) v0))`;`b':A`]
                    GOODHS_SEM)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(MP_TAC o fst o EQ_IMP_RULE) THEN
      ANTS_TAC THENL
       [USE_THEN "dmin" (MP_TAC o SPEC `b':A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
        DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    (* holds at d, contradicting dbad *)
    SUBGOAL_THEN
     `holds D E ((0 |-> (d:A)) ((81 |-> (rc:A))
                 ((9 |-> (X:A)) ((8 |-> (w1:A)) ((2 |-> (B:A)) v0))))) goodhs`
    MP_TAC THENL
     [MP_TAC(REWRITE_RULE[VALMOD; ARITH_EQ]
        (SPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`sa:A`;`rc:A`;
                `(9 |-> (X:A)) ((8 |-> (w1:A)) ((2 |-> (B:A)) v0))`;`d:A`]
                    GOODHS_SEM)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;
                    `ii:A`;`ci:A`;`P:A`;
                    `leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`d:A`]
                        GOODHS_STEP) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN ACCEPT_TAC];
      USE_THEN "dbad" (fun th -> REWRITE_TAC[th])];
    ALL_TAC] THEN
  (* instantiate at a and feed the (x,vx)-pair from echeck *)
  USE_THEN "good" (MP_TAC o SPEC `a:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN
  MP_TAC(REWRITE_RULE[VALMOD; ARITH_EQ]
    (SPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`sa:A`;`rc:A`;
            `(9 |-> (X:A)) ((8 |-> (w1:A)) ((2 |-> (B:A)) v0))`;`a:A`]
                GOODHS_SEM)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o fst o EQ_IMP_RULE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL [`cd:A`;`pp:A`;`x:A`;`vx:A`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]);;

let HS_REAL = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X embf
  alpha onetw rdot.
      hsbundle D E w1 om tw ii ci P leqp B inclB onebee X /\
      embf IN D /\ eisfun D E embf /\
      (!z. z IN D
           ==> (E z embf <=>
                ?cv b. cv IN D /\ b IN D /\ E cv ci /\ eopair D E cv b z /\
                       (!q. q IN D
                            ==> (E q b <=>
                                 E q P /\
                                 (!r. r IN D /\ erel D E leqp r q
                                      ==> ?s. s IN D /\ erel D E leqp s r /\
                                              E cv s))))) /\
      (!cvs. cvs IN D /\ E cvs ci ==> ?b. b IN D /\ eapply D E embf cvs b) /\
      (!cvs bb. cvs IN D /\ bb IN D /\ eapply D E embf cvs bb ==> E bb B) /\
      alpha IN D /\ E alpha w1 /\ onetw IN D /\ E onetw tw /\
      rdot IN D /\
      (!z. z IN D
           ==> (E z rdot <=>
                ?n sig b p15 cvs. n IN D /\ sig IN D /\ b IN D /\ p15 IN D /\
                    cvs IN D /\ E n om /\
                    echeck D E onebee n sig /\ eopair D E alpha n p15 /\
                    eopair D E p15 onetw cvs /\ eapply D E embf cvs b /\
                    eopair D E sig b z))
      ==> hsname D E B w1 X rdot`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "hsb")
   (CONJUNCTS_THEN2 (LABEL_TAC "embfD")
    (CONJUNCTS_THEN2 (LABEL_TAC "efun")
     (CONJUNCTS_THEN2 (LABEL_TAC "gc")
      (CONJUNCTS_THEN2 (LABEL_TAC "etot")
       (CONJUNCTS_THEN2 (LABEL_TAC "evalB")
        (CONJUNCTS_THEN2 (LABEL_TAC "alD")
         (CONJUNCTS_THEN2 (LABEL_TAC "alom")
          (CONJUNCTS_THEN2 (LABEL_TAC "otD")
           (CONJUNCTS_THEN2 (LABEL_TAC "ottw")
            (CONJUNCTS_THEN2 (LABEL_TAC "rD") (LABEL_TAC "rch")))))))))))) THEN
  USE_THEN "hsb" (MP_TAC o REWRITE_RULE[hsbundle]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
   (CONJUNCTS_THEN2 (LABEL_TAC "vl")
    (CONJUNCTS_THEN2 (LABEL_TAC "eom")
     (CONJUNCTS_THEN2 (LABEL_TAC "w1D")
      (CONJUNCTS_THEN2 (LABEL_TAC "w1card")
       (CONJUNCTS_THEN2 (LABEL_TAC "omw1")
        (CONJUNCTS_THEN2 (LABEL_TAC "w1min")
         (CONJUNCTS_THEN2 (LABEL_TAC "cr1")
          (CONJUNCTS_THEN2 (LABEL_TAC "cr2")
           (CONJUNCTS_THEN2 (LABEL_TAC "ftw")
            (CONJUNCTS_THEN2 (LABEL_TAC "coh")
             (CONJUNCTS_THEN2 (LABEL_TAC "leq")
              (CONJUNCTS_THEN2 (LABEL_TAC "ros")
               (CONJUNCTS_THEN2 (LABEL_TAC "inc")
                (CONJUNCTS_THEN2 (LABEL_TAC "porder")
                 (CONJUNCTS_THEN2 (LABEL_TAC "top")
                  (CONJUNCTS_THEN2 (LABEL_TAC "oneD")
                   (CONJUNCTS_THEN2 (LABEL_TAC "BD")
                    (CONJUNCTS_THEN2 (LABEL_TAC "oneB")
                     (CONJUNCTS_THEN2 (LABEL_TAC "XD")
                      (CONJUNCTS_THEN2 (LABEL_TAC "ciX")
                        (LABEL_TAC "PX")))))))))))))))))))))) THEN
  SUBGOAL_THEN `(om:A) IN D` (LABEL_TAC "omD") THENL
   [USE_THEN "eom" (ACCEPT_TAC o MATCH_MP EOMEGA_IN); ALL_TAC] THEN
  SUBGOAL_THEN `(P:A) IN D` (LABEL_TAC "PD") THENL
   [USE_THEN "coh" (ACCEPT_TAC o CONJUNCT1 o
                    REWRITE_RULE[ecohenp]); ALL_TAC] THEN
  SUBGOAL_THEN `(ci:A) IN D` (LABEL_TAC "ciD") THENL
   [USE_THEN "cr2" (ACCEPT_TAC o CONJUNCT1 o
                    REWRITE_RULE[ecross]); ALL_TAC] THEN
  (* rdot is a B-name and a function *)
  SUBGOAL_THEN `bname D (E:A->A->bool) B rdot` (LABEL_TAC "bn") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`onebee:A`;`om:A`;`embf:A`;
                  `alpha:A`;`onetw:A`;`rdot:A`] COHEN_REALNAME_BNAME) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `eisfun D (E:A->A->bool) rdot` (LABEL_TAC "rfun") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`onebee:A`;`om:A`;`embf:A`;
                  `alpha:A`;`onetw:A`;`rdot:A`] COHEN_REALNAME_ISFUN) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  (* every pair of rdot is <sig,b>, sig = n^ an HS name, b IN B *)
  SUBGOAL_THEN
   `!z:A. z IN D /\ E z rdot
          ==> ?u c. u IN D /\ c IN D /\ eopair D E u c z /\ E c B /\
                    hsname D E B w1 X u`
   (LABEL_TAC "rpair") THENL
   [X_GEN_TAC `z:A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "zD") (LABEL_TAC "zr")) THEN
    USE_THEN "rch" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "zr" (MP_TAC o EQ_MP th)) THEN
    DISCH_THEN(X_CHOOSE_THEN `n:A` (X_CHOOSE_THEN `sig:A` (X_CHOOSE_THEN `b:A`
