                (CONJUNCTS_THEN2 (LABEL_TAC "cvsp")
                  (CONJUNCTS_THEN2 (LABEL_TAC "appb")
                    (LABEL_TAC "sigbz")))))))))))))))) THEN
    MAP_EVERY EXISTS_TAC [`sig:A`;`b:A`] THEN REPEAT CONJ_TAC THENL
     [USE_THEN "sigD" ACCEPT_TAC; USE_THEN "bD" ACCEPT_TAC;
      USE_THEN "sigbz" ACCEPT_TAC;
      USE_THEN "evalB" (MP_TAC o SPECL [`cvs:A`;`b:A`]) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN ACCEPT_TAC];
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;
                    `ii:A`;`ci:A`;`P:A`;
                    `leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`n:A`;`sig:A`]
