   [X_GEN_TAC `t:A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "tD") (LABEL_TAC "tdv")) THEN
    USE_THEN "domr" (MP_TAC o SPEC `t:A` o CONJUNCT2 o
