    (CONJUNCTS_THEN2 (LABEL_TAC "c0D") (CONJUNCTS_THEN2 (LABEL_TAC "yc0D")
      (CONJUNCTS_THEN2 (LABEL_TAC "c0ord") (CONJUNCTS_THEN2 (LABEL_TAC "hsc0")
        (LABEL_TAC "bnd"))))))) THEN
  (* a2 = esuc c0 and its HS stage ya2 *)
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`c0:A`] ESUC_EXISTS) THEN
  ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
