    (CONJUNCTS_THEN2 (LABEL_TAC "ech") (CONJUNCTS_THEN2 (LABEL_TAC "efin")
      (LABEL_TAC "esubw"))))) THEN
  SUBGOAL_THEN `ehssym D (E:A->A->bool) B w1 X rdot` (LABEL_TAC "rsym") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;
                  `ii:A`;`ci:A`;`P:A`;
                  `leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`rdot:A`;`e:A`]
      EHSSYM_INTRO) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
       ((* every true bundle at an s fixing {alpha} fixes rdot (EAUT_REAL) *)
