      ANTS_TAC THENL [USE_THEN "uD" ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[eindom; eapply] THEN
      EXISTS_TAC `c:A` THEN CONJ_TAC THENL
          [USE_THEN "cD" ACCEPT_TAC; ALL_TAC] THEN
      EXISTS_TAC `z:A` THEN CONJ_TAC THENL
       [USE_THEN "ucz" ACCEPT_TAC; USE_THEN "zr" ACCEPT_TAC];
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;`a2:A`;`ya2:A`;
                `rdot:A`] HSNAME_STAGE) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                  DISCH_THEN ACCEPT_TAC]);;

(* H0 (part 3c) : HS_UPN -- HS names closed under pairing, countable       *)
(* supports (CSUPPORT_UNION), at parameter w1.                              *)
let HS_UPN = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X a b up.
      hsbundle D E w1 om tw ii ci P leqp B inclB onebee X /\
      a IN D /\ b IN D /\ hsname D E B w1 X a /\ hsname D E B w1 X b /\
      up IN D /\
      (!z. z IN D ==> (E z up <=> eopair D E a onebee z \/
                       eopair D E b onebee z))
      ==> hsname D E B w1 X up`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "hsb")
   (CONJUNCTS_THEN2 (LABEL_TAC "aD")
    (CONJUNCTS_THEN2 (LABEL_TAC "bD")
     (CONJUNCTS_THEN2 (LABEL_TAC "hsa")
      (CONJUNCTS_THEN2 (LABEL_TAC "hsb'")
       (CONJUNCTS_THEN2 (LABEL_TAC "upD") (LABEL_TAC "upch"))))))) THEN
  USE_THEN "hsb" (MP_TAC o REWRITE_RULE[hsbundle]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
   (CONJUNCTS_THEN2 (LABEL_TAC "vl")
    (CONJUNCTS_THEN2 (LABEL_TAC "eom")
     (CONJUNCTS_THEN2 (LABEL_TAC "w1D")
      (CONJUNCTS_THEN2 (LABEL_TAC "w1card")
       (CONJUNCTS_THEN2 (LABEL_TAC "omw1")
        (CONJUNCTS_THEN2 (LABEL_TAC "w1min")
         (CONJUNCTS_THEN2 (LABEL_TAC "cr1")
          (CONJUNCTS_THEN2 (LABEL_TAC "cr2")
           (CONJUNCTS_THEN2 (LABEL_TAC "ftw")
            (CONJUNCTS_THEN2 (LABEL_TAC "coh")
             (CONJUNCTS_THEN2 (LABEL_TAC "leq")
              (CONJUNCTS_THEN2 (LABEL_TAC "ros")
               (CONJUNCTS_THEN2 (LABEL_TAC "inc")
                (CONJUNCTS_THEN2 (LABEL_TAC "porder")
                 (CONJUNCTS_THEN2 (LABEL_TAC "top")
                  (CONJUNCTS_THEN2 (LABEL_TAC "oneD")
                   (CONJUNCTS_THEN2 (LABEL_TAC "BD")
                    (CONJUNCTS_THEN2 (LABEL_TAC "oneB")
                     (CONJUNCTS_THEN2 (LABEL_TAC "XD")
                      (CONJUNCTS_THEN2 (LABEL_TAC "ciX")
                        (LABEL_TAC "PX")))))))))))))))))))))) THEN
  SUBGOAL_THEN `(om:A) IN D` (LABEL_TAC "omD") THENL
   [USE_THEN "eom" (ACCEPT_TAC o MATCH_MP EOMEGA_IN); ALL_TAC] THEN
  (* B-names, symmetry of the components *)
  SUBGOAL_THEN `bname D (E:A->A->bool) B a /\ bname D E B b`
   (CONJUNCTS_THEN2 (LABEL_TAC "bna") (LABEL_TAC "bnb")) THENL
   [CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;
                    `a:A`] HSNAME_BNAME);
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;`b:A`]
             HSNAME_BNAME)] THEN
    ANTS_TAC THEN TRY(REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC) THEN
    DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B up` (LABEL_TAC "bnup") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`a:A`;`b:A`;
                  `onebee:A`;`up:A`]
      UPN_BNAME) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `ehssym D (E:A->A->bool) B w1 X a /\ ehssym D E B w1 X b`
   (CONJUNCTS_THEN2 (LABEL_TAC "syma") (LABEL_TAC "symb")) THENL
   [CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;
                    `a:A`] HSNAME_SYM);
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;`b:A`]
             HSNAME_SYM)] THEN
    ANTS_TAC THEN TRY(REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC) THEN
    DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;
                `ii:A`;`ci:A`;`P:A`;
                `leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`a:A`]
                    EHSSYM_ELIM_ALL) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ea:A` (CONJUNCTS_THEN2 (LABEL_TAC "eaD")
    (CONJUNCTS_THEN2 (LABEL_TAC "eafin") (CONJUNCTS_THEN2 (LABEL_TAC "easub")
      (LABEL_TAC "fixa"))))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;
                `ii:A`;`ci:A`;`P:A`;
                `leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`b:A`]
                    EHSSYM_ELIM_ALL) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `eb:A` (CONJUNCTS_THEN2 (LABEL_TAC "ebD")
    (CONJUNCTS_THEN2 (LABEL_TAC "ebfin") (CONJUNCTS_THEN2 (LABEL_TAC "ebsub")
      (LABEL_TAC "fixb"))))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;
                `ii:A`;`ci:A`;`P:A`;
                `leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`ea:A`;`eb:A`]
                    CSUPPORT_UNION) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `e:A` (CONJUNCTS_THEN2 (LABEL_TAC "eD")
    (CONJUNCTS_THEN2 (LABEL_TAC "efin") (CONJUNCTS_THEN2 (LABEL_TAC "esub")
      (CONJUNCTS_THEN2 (LABEL_TAC "eae") (LABEL_TAC "ebe")))))) THEN
  (* {a,b} is symmetric with support e *)
  SUBGOAL_THEN `ehssym D (E:A->A->bool) B w1 X up` (LABEL_TAC "symup") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;
                  `ii:A`;`ci:A`;`P:A`;
                  `leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`up:A`;`e:A`]
                      EHSSYM_INTRO) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      X_GEN_TAC `s:A` THEN
      DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "sD")
                 (CONJUNCTS_THEN2 (LABEL_TAC "sperm")
        (LABEL_TAC "sfix"))) THEN
      MAP_EVERY X_GEN_TAC [`muci:A`;`muP:A`;`autB:A`] THEN
      DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "mD")
       (CONJUNCTS_THEN2 (LABEL_TAC "muPD")
        (CONJUNCTS_THEN2 (LABEL_TAC "autBD")
         (CONJUNCTS_THEN2 (LABEL_TAC "bm")
          (CONJUNCTS_THEN2 (LABEL_TAC "bP")
           (CONJUNCTS_THEN2 (LABEL_TAC "bA")
            (CONJUNCTS_THEN2 (LABEL_TAC "mch")
             (CONJUNCTS_THEN2 (LABEL_TAC "Pch")
              (CONJUNCTS_THEN2 (LABEL_TAC "ach")
               (CONJUNCTS_THEN2 (LABEL_TAC "quadP")
                 (LABEL_TAC "quadB"))))))))))) THEN
      SUBGOAL_THEN `eautn D (E:A->A->bool) B autB a a` (LABEL_TAC "fa") THENL
       [USE_THEN "fixa" (MP_TAC o SPEC `s:A`) THEN
        ANTS_TAC THENL
         [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
          MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`s:A`;`e:A`;`ea:A`]
                 EFIXES_SUBSET) THEN
          ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                          DISCH_THEN ACCEPT_TAC];
          ALL_TAC] THEN
        DISCH_THEN(MP_TAC o SPECL [`muci:A`;`muP:A`;`autB:A`]) THEN
        ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                        DISCH_THEN ACCEPT_TAC];
        ALL_TAC] THEN
      SUBGOAL_THEN `eautn D (E:A->A->bool) B autB b b` (LABEL_TAC "fb") THENL
       [USE_THEN "fixb" (MP_TAC o SPEC `s:A`) THEN
        ANTS_TAC THENL
         [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
          MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`s:A`;`e:A`;`eb:A`]
                 EFIXES_SUBSET) THEN
          ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                          DISCH_THEN ACCEPT_TAC];
          ALL_TAC] THEN
        DISCH_THEN(MP_TAC o SPECL [`muci:A`;`muP:A`;`autB:A`]) THEN
        ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                        DISCH_THEN ACCEPT_TAC];
        ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;
                    `onebee:A`;`autB:A`;
                    `a:A`;`b:A`;`a:A`;`b:A`;`up:A`;`up:A`] AUTN_UPN) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN ACCEPT_TAC];
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  (* the HS stage *)
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`a:A`;`b:A`] EPAIR_EXISTS) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `pl:A` (LABEL_TAC "plp")) THEN
  SUBGOAL_THEN `(pl:A) IN D` (LABEL_TAC "plD") THENL
   [USE_THEN "plp" (ACCEPT_TAC o MATCH_MP EPAIR_IN); ALL_TAC] THEN
  SUBGOAL_THEN `!w:A. w IN D ==> ((E:A->A->bool) w pl <=> w = a \/ w = b)`
   (LABEL_TAC "plch") THENL
   [USE_THEN "plp" (ACCEPT_TAC o CONJUNCT2 o REWRITE_RULE[epair]); ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;`pl:A`]
         HSNAME_BOUND) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    X_GEN_TAC `t:A` THEN DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "tD")
        (LABEL_TAC "tpl")) THEN
    USE_THEN "plch" (MP_TAC o SPEC `t:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "tpl" (MP_TAC o EQ_MP th)) THEN
    DISCH_THEN(DISJ_CASES_THEN SUBST1_TAC) THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `c0:A` (X_CHOOSE_THEN `yc0:A`
    (CONJUNCTS_THEN2 (LABEL_TAC "c0D") (CONJUNCTS_THEN2 (LABEL_TAC "yc0D")
      (CONJUNCTS_THEN2 (LABEL_TAC "c0ord") (CONJUNCTS_THEN2 (LABEL_TAC "hsc0")
        (LABEL_TAC "bnd"))))))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`c0:A`] ESUC_EXISTS) THEN
  ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `a2:A` (LABEL_TAC "suc")) THEN
  SUBGOAL_THEN `(a2:A) IN D` (LABEL_TAC "a2D") THENL
   [USE_THEN "suc" (ACCEPT_TAC o MATCH_MP ESUC_IN); ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) a2` (LABEL_TAC "a2ord") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`c0:A`;`a2:A`] EORDINAL_ESUC) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) c0 a2` (LABEL_TAC "c0a2") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`c0:A`;`a2:A`] ESUC_MEMBER) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;`a2:A`]
    HSSTAGE_EXISTS) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ya2:A` (CONJUNCTS_THEN2 (LABEL_TAC "ya2D")
    (LABEL_TAC "hsa2"))) THEN
  SUBGOAL_THEN `eisfun D (E:A->A->bool) up` (LABEL_TAC "upfun") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`a:A`;`b:A`;`onebee:A`;`up:A`]
      UPN_ISFUN) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) up ya2` (LABEL_TAC "upya2") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;`up:A`;
                  `a2:A`;`ya2:A`] HSSTAGE_INTRO) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      X_GEN_TAC `z:A` THEN
      DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "zD") (LABEL_TAC "zup")) THEN
      USE_THEN "upch" (MP_TAC o SPEC `z:A`) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> USE_THEN "zup" (MP_TAC o EQ_MP th)) THEN
      DISCH_THEN(DISJ_CASES_THEN (LABEL_TAC "zp")) THENL
       [MAP_EVERY EXISTS_TAC [`a:A`;`onebee:A`] THEN REPEAT CONJ_TAC THEN
        TRY(FIRST_ASSUM ACCEPT_TAC) THEN
        MAP_EVERY EXISTS_TAC [`c0:A`;`yc0:A`] THEN REPEAT CONJ_TAC THEN
        TRY(FIRST_ASSUM ACCEPT_TAC) THEN
        USE_THEN "bnd" MATCH_MP_TAC THEN CONJ_TAC THENL
            [USE_THEN "aD" ACCEPT_TAC; ALL_TAC] THEN
        USE_THEN "plch" (MP_TAC o SPEC `a:A`) THEN
        ANTS_TAC THENL [USE_THEN "aD" ACCEPT_TAC;
                        DISCH_THEN(fun th -> REWRITE_TAC[th])];
        MAP_EVERY EXISTS_TAC [`b:A`;`onebee:A`] THEN REPEAT CONJ_TAC THEN
        TRY(FIRST_ASSUM ACCEPT_TAC) THEN
        MAP_EVERY EXISTS_TAC [`c0:A`;`yc0:A`] THEN REPEAT CONJ_TAC THEN
        TRY(FIRST_ASSUM ACCEPT_TAC) THEN
        USE_THEN "bnd" MATCH_MP_TAC THEN CONJ_TAC THENL
            [USE_THEN "bD" ACCEPT_TAC; ALL_TAC] THEN
        USE_THEN "plch" (MP_TAC o SPEC `b:A`) THEN
        ANTS_TAC THENL [USE_THEN "bD" ACCEPT_TAC;
                        DISCH_THEN(fun th -> REWRITE_TAC[th])]];
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;
                `a2:A`;`ya2:A`;`up:A`]
    HSNAME_STAGE) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                  DISCH_THEN ACCEPT_TAC]);;

(* ######################################################################### *)
(* S5 / H1 : THE HS BOOLEAN VALUATION  bval_HS / bvalf_HS                    *)
(* bval (forcing) with the !! clause ranging over HS names                   *)
(* (hsname D E B w1 X: countable supports at w1 = aleph_1); definability     *)
(* (BVAL_HS_DEFINABLE), totality + uniqueness, the function form bvalf_HS,   *)
(* and the connective/quantifier facts BVALF_HS_FALSE..BVALF_HS_ALL_GLB.     *)
(* Then H2f : SYM_BVALF_HS, the symmetry lemma for bvalf_HS relative to two  *)
(* abstract hypotheses on the autN action (HS -> HS, and onto HS).           *)
(* ######################################################################### *)
(* ===================================================================== *)
(* H1 (part 1) : the HS Boolean valuation bval_HS -- bval                   *)
(* with the !! clause ranging over HS names hsname D E B w1 X (countable    *)
(* supports at w1, domain set X).  Atomic and --> clauses are unchanged.    *)
(* BVAL_HS_IN_B / BVAL_HS_FV are verbatim clones of BVAL_IN_B / BVAL_FV.     *)
(* ===================================================================== *)
let bval_HS = new_recursive_definition form_RECURSION
 `(bval_HS D (E:A->A->bool) B leq w1 X v False z <=> ebot D E B leq z) /\
  (bval_HS D E B leq w1 X v (i %% j) z <=> ebv_in D E B leq (v i) (v j) z) /\
  (bval_HS D E B leq w1 X v (Eq i j) z <=> ebv_eq D E B leq (v i) (v j) z) /\
  (bval_HS D E B leq w1 X v (p --> q) z <=>
       ?zp zq. zp IN D /\ zq IN D /\
               bval_HS D E B leq w1 X v p zp /\ bval_HS D E B leq w1 X v q zq /\
               ebimp D E B leq zp zq z) /\
  (bval_HS D E B leq w1 X v (!! n p) z <=>
       ?S. S IN D /\
           (!zz. zz IN D
                 ==> (E zz S <=>
                      ?a. a IN D /\ hsname D E B w1 X a /\
                          bval_HS D E B leq w1 X ((n |-> a) v) p zz)) /\
           eglb D E B leq S z)`;;

(* every Boolean value lies in B (given z IN D; ebv_in/eq are not      *)
(* single-valued off D, so z IN D is a genuine hypothesis)             *)
let BVAL_HS_IN_B = prove
 (`!p D (E:A->A->bool) B leq w1 X v z.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ z IN D /\ bval_HS D E B leq w1 X v p z ==> E z B`,
  MATCH_MP_TAC form_INDUCT THEN REPEAT CONJ_TAC THENL
   [REPEAT GEN_TAC THEN REWRITE_TAC[bval_HS; ebot] THEN STRIP_TAC THEN
    ASM_REWRITE_TAC[];
    MAP_EVERY X_GEN_TAC [`i:num`; `j:num`] THEN REPEAT GEN_TAC THEN
    REWRITE_TAC[bval_HS] THEN STRIP_TAC THEN
    SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`;
      `(v:num->A) i`; `(v:num->A) j`; `z:A`] EBV_IN_IN_B) THEN
    ASM_REWRITE_TAC[];
    MAP_EVERY X_GEN_TAC [`i:num`; `j:num`] THEN REPEAT GEN_TAC THEN
    REWRITE_TAC[bval_HS] THEN STRIP_TAC THEN
    SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`;
      `(v:num->A) i`; `(v:num->A) j`; `z:A`] EBV_EQ_IN_B) THEN
    ASM_REWRITE_TAC[];
    REPEAT GEN_TAC THEN DISCH_TAC THEN REPEAT GEN_TAC THEN
    REWRITE_TAC[bval_HS] THEN STRIP_TAC THEN
    FIRST_ASSUM(ACCEPT_TAC o CONJUNCT2 o MATCH_MP EBIMP_IN);
    REPEAT GEN_TAC THEN DISCH_TAC THEN REPEAT GEN_TAC THEN
    REWRITE_TAC[bval_HS] THEN STRIP_TAC THEN
    FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EGLB_MEM_ALG)]);;

(* value depends only on the valuation at the free variables of p        *)
let BVAL_HS_FV = prove
 (`!p D (E:A->A->bool) B leq w1 X v w z.
      (!i. i IN FV p ==> v i = w i)
      ==> (bval_HS D E B leq w1 X v p z <=> bval_HS D E B leq w1 X w p z)`,
  MATCH_MP_TAC form_INDUCT THEN REPEAT CONJ_TAC THENL
   [REWRITE_TAC[bval_HS];
    MAP_EVERY X_GEN_TAC [`i:num`; `j:num`] THEN REPEAT GEN_TAC THEN
    REWRITE_TAC[FV; IN_INSERT; NOT_IN_EMPTY] THEN DISCH_TAC THEN
    REWRITE_TAC[bval_HS] THEN
    SUBGOAL_THEN `(v:num->A) i = w i /\ (v:num->A) j = w j`
      (fun th -> REWRITE_TAC[th]) THEN ASM_MESON_TAC[];
    MAP_EVERY X_GEN_TAC [`i:num`; `j:num`] THEN REPEAT GEN_TAC THEN
    REWRITE_TAC[FV; IN_INSERT; NOT_IN_EMPTY] THEN DISCH_TAC THEN
    REWRITE_TAC[bval_HS] THEN
    SUBGOAL_THEN `(v:num->A) i = w i /\ (v:num->A) j = w j`
      (fun th -> REWRITE_TAC[th]) THEN ASM_MESON_TAC[];
    MAP_EVERY X_GEN_TAC [`p:form`; `q:form`] THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC) THEN
    REPEAT GEN_TAC THEN REWRITE_TAC[FV; IN_UNION] THEN DISCH_TAC THEN
    SUBGOAL_THEN `!z. bval_HS D (E:A->A->bool) B leq w1 X v p z <=>
        bval_HS D E B leq w1 X w p z`
      ASSUME_TAC THENL
     [GEN_TAC THEN FIRST_ASSUM MATCH_MP_TAC THEN ASM_MESON_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `!z. bval_HS D (E:A->A->bool) B leq w1 X v q z <=>
        bval_HS D E B leq w1 X w q z`
      ASSUME_TAC THENL
     [GEN_TAC THEN FIRST_ASSUM MATCH_MP_TAC THEN ASM_MESON_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[bval_HS] THEN ASM_REWRITE_TAC[];
    MAP_EVERY X_GEN_TAC [`m:num`; `p:form`] THEN DISCH_TAC THEN
    REPEAT GEN_TAC THEN REWRITE_TAC[FV; IN_DELETE] THEN DISCH_TAC THEN
    SUBGOAL_THEN
     `!a zz. bval_HS D (E:A->A->bool) B leq w1 X ((m |-> a) v) p zz <=>
             bval_HS D E B leq w1 X ((m |-> a) w) p zz` ASSUME_TAC THENL
     [REPEAT GEN_TAC THEN FIRST_ASSUM MATCH_MP_TAC THEN
      X_GEN_TAC `k:num` THEN DISCH_TAC THEN
      ASM_CASES_TAC `k:num = m` THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER] THEN
          ASM_MESON_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[bval_HS] THEN ASM_REWRITE_TAC[]]);;

(* a slot outside any finite set of variable indices (for fresh choices) *)

(* H1 (part 2) : BVAL_HS_DEFINABLE -- the HS valuation is uniformly        *)
(* definable by an object formula (clone of BVAL_DEFINABLE):                *)
(* hsname_form for bname_form (reads B,w1,X at slots 2,8,9); every fresh    *)
(* slot also avoids 8,9 so those parameter slots are never rebound.          *)
let BVAL_HS_DEFINABLE = prove
 (`!p r ileq. ?f. !D (E:A->A->bool) v.
      model D E ZF_AX /\ valuation D v /\ ileq < 32
      ==> (holds D E v f <=>
           bval_HS D E (v 2) (v ileq) (v 8) (v 9) (\i. v (32 + i)) p (v r))`,
  MATCH_MP_TAC form_INDUCT THEN REPEAT CONJ_TAC THENL
   [MAP_EVERY X_GEN_TAC [`r:num`; `ileq:num`] THEN
    EXISTS_TAC `bbot_form ileq 2 r` THEN REPEAT STRIP_TAC THEN
    ASM_SIMP_TAC[HOLDS_BBOT_FORM] THEN REWRITE_TAC[bval_HS];
    MAP_EVERY X_GEN_TAC [`i:num`; `j:num`; `r:num`; `ileq:num`] THEN
    EXISTS_TAC `ebv_in_form r (32 + i) (32 + j) ileq` THEN REPEAT STRIP_TAC THEN
    ASM_SIMP_TAC[HOLDS_EBV_IN_FORM] THEN REWRITE_TAC[bval_HS];
    MAP_EVERY X_GEN_TAC [`i:num`; `j:num`; `r:num`; `ileq:num`] THEN
    EXISTS_TAC `ebv_eq_form r (32 + i) (32 + j) ileq` THEN REPEAT STRIP_TAC THEN
    ASM_SIMP_TAC[HOLDS_EBV_EQ_FORM] THEN REWRITE_TAC[bval_HS];
    (* --> *)
    MAP_EVERY X_GEN_TAC [`p:form`; `q:form`] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "ihp") (LABEL_TAC "ihq")) THEN
    MAP_EVERY X_GEN_TAC [`r:num`; `ileq:num`] THEN
    ABBREV_TAC `S0 = {2, 8, 9, r, ileq} UNION IMAGE (\k. 32 + k)
        (FV p UNION FV q)` THEN
    SUBGOAL_THEN `FINITE (S0:num->bool)` ASSUME_TAC THENL
     [EXPAND_TAC "S0" THEN
      SIMP_TAC[FINITE_UNION; FINITE_INSERT; FINITE_EMPTY; FINITE_IMAGE;
               FV_FINITE]; ALL_TAC] THEN
    SUBGOAL_THEN `?op. ~(op IN (S0:num->bool))` (X_CHOOSE_TAC `op:num`) THENL
     [MATCH_MP_TAC num_FINITE_AVOID THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `?oq. ~(oq IN (op:num) INSERT S0)`
        (X_CHOOSE_TAC `oq:num`) THENL
     [MATCH_MP_TAC num_FINITE_AVOID THEN
      ASM_SIMP_TAC[FINITE_INSERT]; ALL_TAC] THEN
    SUBGOAL_THEN
     `~(op = 2) /\ ~(op = r) /\ ~(op = ileq) /\
      ~(op = 8) /\ ~(op = 9) /\ ~(oq = 8) /\ ~(oq = 9) /\
      ~(oq = 2) /\ ~(oq = r) /\ ~(oq = ileq) /\ ~(op = oq) /\
      (!i. i IN FV p \/ i IN FV q ==> ~(op = 32 + i) /\ ~(oq = 32 + i))`
    STRIP_ASSUME_TAC THENL
     [UNDISCH_TAC `~((op:num) IN S0)` THEN
      UNDISCH_TAC `~((oq:num) IN (op:num) INSERT S0)` THEN
      EXPAND_TAC "S0" THEN
      REWRITE_TAC[IN_UNION; IN_INSERT; NOT_IN_EMPTY; IN_IMAGE;
                  DE_MORGAN_THM; NOT_EXISTS_THM] THEN
      REPEAT STRIP_TAC THEN ASM_MESON_TAC[];
      ALL_TAC] THEN
    USE_THEN "ihp" (X_CHOOSE_THEN `fp:form` (LABEL_TAC "fpb") o
      SPECL [`op:num`; `ileq:num`]) THEN
    USE_THEN "ihq" (X_CHOOSE_THEN `fq:form` (LABEL_TAC "fqb") o
      SPECL [`oq:num`; `ileq:num`]) THEN
    EXISTS_TAC `?? op (?? oq (fp && fq && bimp_form ileq 2 op oq r))` THEN
    REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `!a b:A. a IN D /\ b IN D
        ==> (holds D E ((oq |-> (b:A)) ((op |-> (a:A)) (v:num->A))) fp <=>
             bval_HS D E (v 2) (v ileq) (v 8) (v 9) (\i. v (32 + i)) p a) /\
            (holds D E ((oq |-> (b:A)) ((op |-> (a:A)) (v:num->A))) fq <=>
             bval_HS D E (v 2) (v ileq) (v 8) (v 9) (\i. v (32 + i)) q b) /\
            (holds D E ((oq |-> (b:A)) ((op |-> (a:A)) (v:num->A)))
                (bimp_form ileq 2 op oq r) <=>
             ebimp D E (v 2) (v ileq) a b (v r))`
    (LABEL_TAC "step") THENL
     [MAP_EVERY X_GEN_TAC [`a:A`; `b:A`] THEN STRIP_TAC THEN
      SUBGOAL_THEN
        `valuation D ((oq |-> (b:A)) ((op |-> (a:A)) (v:num->A)))`
            ASSUME_TAC THENL
       [ASM_SIMP_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
      REPEAT CONJ_TAC THENL
       [USE_THEN "fpb" (MP_TAC o SPECL
          [`D:A->bool`; `E:A->A->bool`;
           `(oq |-> (b:A)) ((op |-> (a:A)) (v:num->A))`]) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER] THEN
        MATCH_MP_TAC BVAL_HS_FV THEN X_GEN_TAC `i:num` THEN DISCH_TAC THEN
        ASM_SIMP_TAC[VALMOD_OTHER];
        USE_THEN "fqb" (MP_TAC o SPECL
          [`D:A->bool`; `E:A->A->bool`;
           `(oq |-> (b:A)) ((op |-> (a:A)) (v:num->A))`]) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER] THEN
        MATCH_MP_TAC BVAL_HS_FV THEN X_GEN_TAC `i:num` THEN DISCH_TAC THEN
        ASM_SIMP_TAC[VALMOD_OTHER];
        ASM_SIMP_TAC[HOLDS_BIMP_FORM] THEN
        ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER]];
      ALL_TAC] THEN
    REMOVE_THEN "fpb" (K ALL_TAC) THEN REMOVE_THEN "fqb" (K ALL_TAC) THEN
    REWRITE_TAC[HOLDS_EX; HOLDS_AND] THEN REWRITE_TAC[bval_HS] THEN
    EQ_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `a:A` (CONJUNCTS_THEN2 ASSUME_TAC
        (X_CHOOSE_THEN `b:A` (CONJUNCTS_THEN2 ASSUME_TAC MP_TAC)))) THEN
      USE_THEN "step" (fun sth -> ASM_SIMP_TAC[SPECL [`a:A`; `b:A`] sth]) THEN
      STRIP_TAC THEN MAP_EVERY EXISTS_TAC [`a:A`; `b:A`] THEN ASM_REWRITE_TAC[];
      DISCH_THEN(X_CHOOSE_THEN `zp:A` (X_CHOOSE_THEN `zq:A`
          STRIP_ASSUME_TAC)) THEN
      EXISTS_TAC `zp:A` THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `zq:A` THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "step" (fun sth -> ASM_SIMP_TAC[SPECL [`zp:A`; `zq:A`] sth])];
    (* !! m p *)
    MAP_EVERY X_GEN_TAC [`m:num`; `p:form`] THEN
        DISCH_THEN(LABEL_TAC "ihp") THEN
    MAP_EVERY X_GEN_TAC [`r:num`; `ileq:num`] THEN
    ABBREV_TAC
      `S1 = {2, 8, 9, r, ileq, 30, 31, 32 + m} UNION IMAGE
          (\k. 32 + k) (FV p)` THEN
    SUBGOAL_THEN `FINITE (S1:num->bool)` ASSUME_TAC THENL
     [EXPAND_TAC "S1" THEN
      SIMP_TAC[FINITE_UNION; FINITE_INSERT; FINITE_EMPTY; FINITE_IMAGE;
               FV_FINITE]; ALL_TAC] THEN
    SUBGOAL_THEN `?iS. ~(iS IN (S1:num->bool))` (X_CHOOSE_TAC `iS:num`) THENL
     [MATCH_MP_TAC num_FINITE_AVOID THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `?izz. ~(izz IN (iS:num) INSERT S1)`
      (X_CHOOSE_TAC `izz:num`) THENL
     [MATCH_MP_TAC num_FINITE_AVOID THEN
      ASM_SIMP_TAC[FINITE_INSERT]; ALL_TAC] THEN
    SUBGOAL_THEN
     `~(iS = 2) /\ ~(iS = r) /\ ~(iS = ileq) /\ ~(iS = 30) /\ ~(iS = 31) /\
      ~(iS = 8) /\ ~(iS = 9) /\ ~(izz = 8) /\ ~(izz = 9) /\
      ~(iS = 32 + m) /\ ~(izz = 2) /\ ~(izz = r) /\ ~(izz = ileq) /\
      ~(izz = 30) /\ ~(izz = 31) /\ ~(izz = 32 + m) /\ ~(izz = iS) /\
      (!i. i IN FV p ==> ~(iS = 32 + i) /\ ~(izz = 32 + i))`
    STRIP_ASSUME_TAC THENL
     [UNDISCH_TAC `~((iS:num) IN S1)` THEN
      UNDISCH_TAC `~((izz:num) IN (iS:num) INSERT S1)` THEN
      EXPAND_TAC "S1" THEN
      REWRITE_TAC[IN_UNION; IN_INSERT; NOT_IN_EMPTY; IN_IMAGE;
                  DE_MORGAN_THM; NOT_EXISTS_THM] THEN
      REPEAT STRIP_TAC THEN ASM_MESON_TAC[];
      ALL_TAC] THEN
    USE_THEN "ihp" (X_CHOOSE_THEN `fp:form` (LABEL_TAC "fpb") o
      SPECL [`izz:num`; `ileq:num`]) THEN
    EXISTS_TAC
     `?? iS ((!! izz ((izz %% iS) <->
                      ?? (32 + m) (hsname_form (32 + m) && fp))) &&
             eglb_form 2 ileq iS r)` THEN
    REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN `~(32 + m = 2) /\ ~(32 + m = ileq) /\
                  ~(2 = 32 + m) /\ ~(ileq = 32 + m) /\
                  ~(32 + m = 8) /\ ~(32 + m = 9) /\
                      ~(8 = 32 + m) /\ ~(9 = 32 + m)`
      STRIP_ASSUME_TAC THENL [UNDISCH_TAC `ileq < 32` THEN
                              ARITH_TAC; ALL_TAC] THEN
    SUBGOAL_THEN
     `!s zz a:A. s IN D /\ zz IN D /\ a IN D
        ==> (holds D E (((32 + m) |-> a) ((izz |-> zz) ((iS |-> s) (v:num->A))))
               (hsname_form (32 + m) && fp) <=>
             hsname D E (v 2) (v 8) (v 9) a /\
             bval_HS D E (v 2) (v ileq) (v 8) (v 9)
                 ((m |-> a) (\i. v (32 + i))) p zz)`
    (LABEL_TAC "gstep") THENL
     [MAP_EVERY X_GEN_TAC [`s:A`; `zz:A`; `a:A`] THEN STRIP_TAC THEN
      SUBGOAL_THEN
        `valuation D (((32 + m) |-> a) ((izz |-> zz) ((iS |-> s) (v:num->A))))`
        ASSUME_TAC THENL [ASM_SIMP_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
      SUBGOAL_THEN
        `holds D E (((32 + m) |-> a) ((izz |-> zz) ((iS |-> s) (v:num->A))))
           (hsname_form (32 + m)) <=> hsname D E (v 2) (v 8) (v 9) a`
        ASSUME_TAC THENL
       [ASM_SIMP_TAC[HOLDS_HSNAME_FORM; ARITH_RULE
          `~(32 + m = 30) /\ ~(32 + m = 31)`] THEN
        ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER]; ALL_TAC] THEN
      SUBGOAL_THEN
        `holds D E (((32 + m) |-> a) ((izz |-> zz)
            ((iS |-> s) (v:num->A)))) fp <=>
         bval_HS D E (v 2) (v ileq) (v 8) (v 9)
             ((m |-> a) (\i. v (32 + i))) p zz`
        ASSUME_TAC THENL
       [USE_THEN "fpb" (MP_TAC o SPECL
          [`D:A->bool`; `E:A->A->bool`;
           `((32 + m) |-> a) ((izz |-> zz) ((iS |-> s) (v:num->A)))`]) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER] THEN
        MATCH_MP_TAC BVAL_HS_FV THEN X_GEN_TAC `i:num` THEN DISCH_TAC THEN
        ASM_CASES_TAC `i:num = m` THEN
        ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER;
                     ARITH_RULE `~(i = m) ==> ~(32 + i = 32 +
                         m)`]; ALL_TAC] THEN
      ASM_REWRITE_TAC[HOLDS_AND];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `!s:A. s IN D
        ==> (holds D E ((iS |-> s) (v:num->A))
               (!! izz ((izz %% iS) <->
                        ?? (32 + m) (hsname_form (32 + m) && fp))) <=>
             (!zz. zz IN D
                   ==> (E zz s <=>
                        ?a. a IN D /\ hsname D E (v 2) (v 8) (v 9) a /\
                            bval_HS D E (v 2) (v ileq) (v 8) (v 9)
                                ((m |-> a) (\i. v (32 + i)))
                                p zz))) /\
            (holds D E ((iS |-> s) v) (eglb_form 2 ileq iS r) <=>
             eglb D E (v 2) (v ileq) s (v r))`
    (LABEL_TAC "step") THENL
     [X_GEN_TAC `s:A` THEN DISCH_TAC THEN
      SUBGOAL_THEN `valuation D ((iS |-> s) (v:num->A))` ASSUME_TAC THENL
       [ASM_SIMP_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
      CONJ_TAC THENL
       [REWRITE_TAC[last(CONJUNCTS holds)] THEN
        MATCH_MP_TAC FORALL_IMP_CONG THEN X_GEN_TAC `zz:A` THEN DISCH_TAC THEN
        SUBGOAL_THEN `valuation D ((izz |-> zz) ((iS |-> s) (v:num->A)))`
          ASSUME_TAC THENL [ASM_SIMP_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
        REWRITE_TAC[HOLDS_IFF; HOLDS_MEM; HOLDS_EX] THEN
        ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER] THEN
        MATCH_MP_TAC(TAUT `(x <=> y) ==> ((p <=> x) <=> (p <=> y))`) THEN
        MATCH_MP_TAC EXISTS_AND_CONG THEN X_GEN_TAC `a:A` THEN DISCH_TAC THEN
        USE_THEN "gstep" (fun g -> ASM_SIMP_TAC[SPECL
            [`s:A`; `zz:A`; `a:A`] g]);
        ASM_SIMP_TAC[HOLDS_EGLB_FORM] THEN
        ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER]];
      ALL_TAC] THEN
    REMOVE_THEN "fpb" (K ALL_TAC) THEN REMOVE_THEN "gstep" (K ALL_TAC) THEN
    REWRITE_TAC[HOLDS_EX; HOLDS_AND] THEN REWRITE_TAC[bval_HS] THEN
    EQ_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `s:A` (CONJUNCTS_THEN2 ASSUME_TAC MP_TAC)) THEN
      USE_THEN "step" (fun sth -> ASM_SIMP_TAC[SPEC `s:A` sth]) THEN
      STRIP_TAC THEN EXISTS_TAC `s:A` THEN ASM_REWRITE_TAC[];
      DISCH_THEN(X_CHOOSE_THEN `sv:A` STRIP_ASSUME_TAC) THEN
      EXISTS_TAC `sv:A` THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "step" (fun sth -> ASM_SIMP_TAC[SPEC `sv:A` sth])]]);;

(* H1 (part 3) : BVAL_HS_TOTAL / BVAL_HS_UNIQUE / bvalf_HS + SPEC/IN_B/EQ.   *)
(* Clones of godel_forcing.ml.  TOTAL: HS valuations; atomic cases get       *)
(* bname via HSNAME_BNAME (for EBV_TOTAL); the !! value-set separation runs  *)
(* along ??(32+m)(hsname_form(32+m) && fp) at a base valuation carrying B,   *)
(* leq, w1, X at slots 2,3,8,9 (izz avoids 8,9).                              *)
let BVAL_HS_TOTAL = prove
 (`!p D (E:A->A->bool) B leq w1 X v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      w1 IN D /\ X IN D /\
      valuation D v /\ (!i. hsname D E B w1 X (v i))
      ==> ?z. z IN D /\ bval_HS D E B leq w1 X v p z`,
  MATCH_MP_TAC form_INDUCT THEN REPEAT CONJ_TAC THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN REWRITE_TAC[bval_HS] THEN
  SUBGOAL_THEN `?zb:A. ebot D E B leq zb` STRIP_ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o CONJUNCT2 o REWRITE_RULE[ebalg] o
      CONJUNCT1 o REWRITE_RULE[ecba]); ALL_TAC] THEN
  EXISTS_TAC `zb:A` THEN ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[EBOT_IN];

MAP_EVERY X_GEN_TAC [`i:num`; `j:num`] THEN REPEAT GEN_TAC THEN STRIP_TAC THEN
  REWRITE_TAC[bval_HS] THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN `!k. bname D (E:A->A->bool) B ((v:num->A) k)` ASSUME_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC HSNAME_BNAME THEN
    MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                 `(v:num->A) i`;`(v:num->A) j`]
    EBV_TOTAL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `zi:A` STRIP_ASSUME_TAC o CONJUNCT1) THEN
  EXISTS_TAC `zi:A` THEN ASM_REWRITE_TAC[];

MAP_EVERY X_GEN_TAC [`i:num`; `j:num`] THEN REPEAT GEN_TAC THEN STRIP_TAC THEN
  REWRITE_TAC[bval_HS] THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN `!k. bname D (E:A->A->bool) B ((v:num->A) k)` ASSUME_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC HSNAME_BNAME THEN
    MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                 `(v:num->A) i`;`(v:num->A) j`]
    EBV_TOTAL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ze:A` STRIP_ASSUME_TAC o CONJUNCT2) THEN
  EXISTS_TAC `ze:A` THEN ASM_REWRITE_TAC[];

MAP_EVERY X_GEN_TAC [`p:form`; `q:form`] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "ihp") (LABEL_TAC "ihq")) THEN
  REPEAT GEN_TAC THEN STRIP_TAC THEN REWRITE_TAC[bval_HS] THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[ecba]); ALL_TAC] THEN
  USE_THEN "ihp" (MP_TAC o SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `w1:A`;`X:A`;`v:num->A`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `zp:A` STRIP_ASSUME_TAC) THEN
  USE_THEN "ihq" (MP_TAC o SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `w1:A`;`X:A`;`v:num->A`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `zq:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `E (zp:A) (B:A) /\ E (zq:A) (B:A)` STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `w1:A`;`X:A`;`v:num->A`;`zp:A`] BVAL_HS_IN_B);
      MATCH_MP_TAC(ISPECL [`q:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `w1:A`;`X:A`;`v:num->A`;`zq:A`] BVAL_HS_IN_B)] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zp:A`;`zq:A`]
         EBIMP_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `zr:A` ASSUME_TAC) THEN
  EXISTS_TAC `zr:A` THEN CONJ_TAC THENL
   [ASM_MESON_TAC[EBIMP_IN];
    MAP_EVERY EXISTS_TAC [`zp:A`; `zq:A`] THEN ASM_REWRITE_TAC[]];

MAP_EVERY X_GEN_TAC [`m:num`; `p:form`] THEN DISCH_TAC THEN
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[ecba]); ALL_TAC] THEN
  SUBGOAL_THEN
    `?izz. ~(izz IN ({2, 3, 8, 9, 30, 31, 32 + m} UNION IMAGE
                     (\k. 32 + k) (FV p)))`
    (X_CHOOSE_TAC `izz:num`) THENL
   [MATCH_MP_TAC num_FINITE_AVOID THEN
    SIMP_TAC[FINITE_UNION; FINITE_INSERT; FINITE_EMPTY;
             FINITE_IMAGE; FV_FINITE];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(izz = 2) /\ ~(izz = 3) /\ ~(izz = 30) /\ ~(izz = 31) /\ ~(izz = 32 + m) /\
    ~(izz = 8) /\ ~(izz = 9) /\
    (!i. i IN FV p ==> ~(izz = 32 + i))`
   STRIP_ASSUME_TAC THENL
   [UNDISCH_TAC
     `~(izz IN ({2, 3, 8, 9, 30, 31, 32 + m} UNION IMAGE
                (\k. 32 + k) (FV p)))` THEN
    REWRITE_TAC[IN_UNION; IN_INSERT; NOT_IN_EMPTY; IN_IMAGE;
                DE_MORGAN_THM; NOT_EXISTS_THM] THEN
    REPEAT STRIP_TAC THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  X_CHOOSE_TAC `fp:form` (ISPECL [`p:form`; `izz:num`; `3`]
                          BVAL_HS_DEFINABLE) THEN
  ABBREV_TAC `w0 = (9 |-> X) ((8 |-> w1) ((2 |-> B) ((3 |-> leq)
                    (\k. (v:num->A) (k - 32)))))` THEN
  SUBGOAL_THEN
   `valuation D (w0:num->A) /\ w0 2 = B /\ w0 3 = leq /\
    w0 8 = w1 /\ w0 9 = X /\
    (!i. w0 (32 + i) = (v:num->A) i)`
   STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "w0" THEN REPEAT CONJ_TAC THENL
     [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]) THEN
      REWRITE_TAC[valuation] THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[VALMOD; ARITH_EQ];
      REWRITE_TAC[VALMOD; ARITH_EQ];
      REWRITE_TAC[VALMOD; ARITH_EQ];
      REWRITE_TAC[VALMOD; ARITH_EQ];
      GEN_TAC THEN
      SIMP_TAC[VALMOD_OTHER; ARITH_RULE `~(32 + i = 2) /\ ~(32 + i = 3) /\
                                         ~(32 + i = 8) /\ ~(32 + i = 9)`] THEN
      AP_TERM_TAC THEN ARITH_TAC];
    ALL_TAC] THEN
SUBGOAL_THEN
   `!zz. zz IN D
      ==> (holds D E ((izz |-> zz) (w0:num->A))
             (?? (32 + m) (hsname_form (32 + m) && fp)) <=>
           (?a. a IN D /\ hsname D E B w1 X a /\
                bval_HS D E B leq w1 X ((m |-> a) v) p zz))`
   (LABEL_TAC "bridge") THENL
   [X_GEN_TAC `zz:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `valuation D ((izz |-> zz) (w0:num->A))` ASSUME_TAC THENL
     [ASM_SIMP_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    REWRITE_TAC[HOLDS_EX] THEN
    MATCH_MP_TAC EXISTS_AND_CONG THEN X_GEN_TAC `a:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `valuation D (((32 + m) |-> a) ((izz |-> zz) (w0:num->A)))`
      ASSUME_TAC THENL [ASM_SIMP_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    SUBGOAL_THEN
      `holds D E (((32 + m) |-> a) ((izz |-> zz) (w0:num->A)))
         (hsname_form (32 + m)) <=> hsname D E B w1 X a`
      ASSUME_TAC THENL
     [ASM_SIMP_TAC[HOLDS_HSNAME_FORM; VALMOD_BASIC; VALMOD_OTHER;
        ARITH_RULE `~(32 + m = 30) /\ ~(32 + m = 31) /\ ~(2 = 32 + m) /\
                   ~(8 = 32 + m) /\ ~(9 = 32 + m)`];
      ALL_TAC] THEN
    SUBGOAL_THEN
      `holds D E (((32 + m) |-> a) ((izz |-> zz) (w0:num->A))) fp <=>
       bval_HS D E B leq w1 X ((m |-> a) v) p zz`
      ASSUME_TAC THENL
     [FIRST_X_ASSUM(fun th -> MP_TAC(SPECL
        [`D:A->bool`; `E:A->A->bool`;
         `((32 + m) |-> a) ((izz |-> zz) (w0:num->A))`] th) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN ARITH_TAC; ALL_TAC]) THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER;
        ARITH_RULE `~(2 = 32 + m) /\ ~(3 = 32 + m) /\ ~(8 = 32 + m) /\
            ~(9 = 32 + m)`] THEN
      MATCH_MP_TAC BVAL_HS_FV THEN X_GEN_TAC `i:num` THEN DISCH_TAC THEN
      ASM_CASES_TAC `i:num = m` THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER;
        ARITH_RULE `~(i = m) ==> ~(32 + i = 32 + m)`]; ALL_TAC] THEN
    REWRITE_TAC[HOLDS_AND] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`] ZF_SEPARATION) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`?? (32 + m) (hsname_form (32 + m) && fp)`; `izz:num`;
     `w0:num->A`; `B:A`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `S:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN
   `!zz. zz IN D
      ==> (E zz S <=> ?a. a IN D /\ hsname D (E:A->A->bool) B w1 X a /\
                          bval_HS D (E:A->A->bool) B leq w1 X
                              ((m |-> (a:A)) v) p zz)`
   ASSUME_TAC THENL
   [X_GEN_TAC `zz:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN
     `(?a. a IN D /\ hsname D (E:A->A->bool) B w1 X a /\
       bval_HS D (E:A->A->bool) B leq w1 X ((m |-> (a:A)) v) p zz)
       ==> E zz B` ASSUME_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `a:A` STRIP_ASSUME_TAC) THEN
      MATCH_MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `w1:A`;`X:A`;`(m |-> (a:A)) (v:num->A)`;`zz:A`] BVAL_HS_IN_B) THEN
      ASM_REWRITE_TAC[] THEN MATCH_MP_TAC VALUATION_VALMOD THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    FIRST_X_ASSUM(fun sep -> MP_TAC(SPEC `zz:A` sep)) THEN
        ASM_REWRITE_TAC[] THEN
    USE_THEN "bridge"(MP_TAC o SPEC `zz:A`) THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) S B` ASSUME_TAC THENL
   [REWRITE_TAC[esubset] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`S:A`] ECBA_INF) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `u:A` ASSUME_TAC) THEN
  EXISTS_TAC `u:A` THEN CONJ_TAC THENL
   [ASM_MESON_TAC[EGLB_IN]; ALL_TAC] THEN
  REWRITE_TAC[bval_HS] THEN EXISTS_TAC `S:A` THEN ASM_REWRITE_TAC[]]);;

(* ------------------------------------------------------------------ *)
(* BVAL_UNIQUE: the Boolean value is single-valued (all values in D).   *)
(* False=EBOT_UNIQUE; atomics=EBV_IN/EQ_UNIQUE; -->=EBIMP_UNIQUE on the  *)
(* IH-equal sub-values; !!=ZF_EXTENSIONALITY (the two value-sets have    *)
(* the same members) + EGLB_UNIQUE.                                     *)
(* ------------------------------------------------------------------ *)

let BVAL_HS_UNIQUE = prove
 (`!p D (E:A->A->bool) B leq w1 X v z1 z2.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
          valuation D v /\
      z1 IN D /\ z2 IN D /\ bval_HS D E B leq w1 X v p z1 /\
          bval_HS D E B leq w1 X v p z2
      ==> z1 = z2`,
  MATCH_MP_TAC form_INDUCT THEN REPEAT CONJ_TAC THENL
   [(* False *)
    REPEAT GEN_TAC THEN REWRITE_TAC[bval_HS] THEN STRIP_TAC THEN
    SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
     [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[elattice] o CONJUNCT1 o
        REWRITE_RULE[ebalg] o CONJUNCT1 o REWRITE_RULE[ecba]); ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`z1:A`;`z2:A`]
      EBOT_UNIQUE) THEN ASM_REWRITE_TAC[];
    (* i %% j *)
    MAP_EVERY X_GEN_TAC [`i:num`;`j:num`] THEN REPEAT GEN_TAC THEN
    REWRITE_TAC[bval_HS] THEN STRIP_TAC THEN
    SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `(v:num->A) i`;`(v:num->A) j`;`z1:A`;`z2:A`] EBV_IN_UNIQUE) THEN
    ASM_REWRITE_TAC[];
    (* Eq i j *)
    MAP_EVERY X_GEN_TAC [`i:num`;`j:num`] THEN REPEAT GEN_TAC THEN
    REWRITE_TAC[bval_HS] THEN STRIP_TAC THEN
    SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `(v:num->A) i`;`(v:num->A) j`;`z1:A`;`z2:A`] EBV_EQ_UNIQUE) THEN
    ASM_REWRITE_TAC[];
    (* p --> q *)
    MAP_EVERY X_GEN_TAC [`p:form`;`q:form`] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "ihp") (LABEL_TAC "ihq")) THEN
    REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
     [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[ecba]); ALL_TAC] THEN
    FIRST_X_ASSUM(X_CHOOSE_THEN `zp2:A`
                  (X_CHOOSE_THEN `zq2:A` STRIP_ASSUME_TAC) o
      REWRITE_RULE[bval_HS]) THEN
    FIRST_X_ASSUM(X_CHOOSE_THEN `zp1:A`
                  (X_CHOOSE_THEN `zq1:A` STRIP_ASSUME_TAC) o
      REWRITE_RULE[bval_HS]) THEN
    SUBGOAL_THEN `(zp1:A) = zp2 /\ (zq1:A) = zq2` STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [USE_THEN "ihp"(MATCH_MP_TAC o SPECL
          [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;`X:A`;`v:num->A`]);
        USE_THEN "ihq"(MATCH_MP_TAC o SPECL
          [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;`X:A`;
           `v:num->A`])] THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) (zp1:A) (B:A) /\
        E (zp2:A) B` STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [MATCH_MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
          `w1:A`;`X:A`;`v:num->A`;`zp1:A`] BVAL_HS_IN_B);
        MATCH_MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
          `w1:A`;`X:A`;`v:num->A`;`zp2:A`] BVAL_HS_IN_B)] THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                         `zp1:A`;`zq1:A`;
      `z1:A`;`z2:A`] EBIMP_UNIQUE) THEN
    ASM_REWRITE_TAC[];
    (* !! m p *)
    MAP_EVERY X_GEN_TAC [`m:num`;`p:form`] THEN DISCH_TAC THEN
    REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
     [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[elattice] o CONJUNCT1 o
        REWRITE_RULE[ebalg] o CONJUNCT1 o REWRITE_RULE[ecba]); ALL_TAC] THEN
    FIRST_X_ASSUM(X_CHOOSE_THEN `ss2:A` STRIP_ASSUME_TAC o
                  REWRITE_RULE[bval_HS]) THEN
    FIRST_X_ASSUM(X_CHOOSE_THEN `ss1:A` STRIP_ASSUME_TAC o
                  REWRITE_RULE[bval_HS]) THEN
    SUBGOAL_THEN `(ss1:A) = ss2` SUBST_ALL_TAC THENL
     [FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
      ASM_REWRITE_TAC[] THEN X_GEN_TAC `zz:A` THEN DISCH_TAC THEN
      ASM_MESON_TAC[]; ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ss2:A`;
      `z1:A`;`z2:A`] EGLB_UNIQUE) THEN ASM_REWRITE_TAC[]]);;

(* ------------------------------------------------------------------ *)
(* bvalf: the Boolean value packaged as a B-valued FUNCTION.           *)
(* Well-defined on bname-valuations via BVAL_HS_TOTAL + BVAL_UNIQUE.      *)
(* ------------------------------------------------------------------ *)

let bvalf_HS = new_definition
 `bvalf_HS D (E:A->A->bool) B leq w1 X v p = @z. z IN D /\
     bval_HS D E B leq w1 X v p z`;;

let BVALF_HS_SPEC = prove
 (`!p D (E:A->A->bool) B leq w1 X v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      w1 IN D /\ X IN D /\
      valuation D v /\ (!i. hsname D E B w1 X (v i))
      ==> (bvalf_HS D E B leq w1 X v p) IN D /\
          bval_HS D E B leq w1 X v p (bvalf_HS D E B leq w1 X v p)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN REWRITE_TAC[bvalf_HS] THEN
  CONV_TAC SELECT_CONV THEN MATCH_MP_TAC BVAL_HS_TOTAL THEN ASM_REWRITE_TAC[]);;

let BVALF_HS_IN_B = prove
 (`!p D (E:A->A->bool) B leq w1 X v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      w1 IN D /\ X IN D /\
      valuation D v /\ (!i. hsname D E B w1 X (v i))
      ==> E (bvalf_HS D E B leq w1 X v p) B`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                 `X:A`;`v:num->A`]
    BVALF_HS_SPEC) THEN ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  MATCH_MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                       `X:A`;`v:num->A`;
    `bvalf_HS D (E:A->A->bool) B leq w1 X v p`] BVAL_HS_IN_B) THEN
        ASM_REWRITE_TAC[]);;

let BVALF_HS_EQ = prove
 (`!p D (E:A->A->bool) B leq w1 X v z.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      w1 IN D /\ X IN D /\
      valuation D v /\ (!i. hsname D E B w1 X (v i)) /\
      z IN D /\ bval_HS D E B leq w1 X v p z
      ==> z = bvalf_HS D E B leq w1 X v p`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                 `X:A`;`v:num->A`]
    BVALF_HS_SPEC) THEN ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  MATCH_MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                       `X:A`;`v:num->A`;
    `z:A`;`bvalf_HS D (E:A->A->bool) B leq w1 X v p`] BVAL_HS_UNIQUE) THEN
        ASM_REWRITE_TAC[]);;

(* ===================================================================== *)
(* H1 (part 4) : connective + quantifier facts for bvalf_HS, cloned from    *)
(* the V^B versions (BVALF_FALSE..BVALF_ALL_GLB) with the quantifier        *)
(* ranging over HS names (hsname D E B w1 X) instead of all B-names.        *)
(* ===================================================================== *)
let HSNAMEVAL_VALMOD = prove
 (`!D (E:A->A->bool) B w1 X n a (v:num->A).
      hsname D E B w1 X a /\ (!i. hsname D E B w1 X (v i))
      ==> (!i. hsname D E B w1 X (((n |-> a) v) i))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN GEN_TAC THEN
  ASM_CASES_TAC `i:num = n` THEN ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER]);;

let BVALF_HS_FALSE = prove
 (`!D (E:A->A->bool) B leq w1 X v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      w1 IN D /\ X IN D /\
      valuation D v /\ (!i. hsname D E B w1 X (v i))
      ==> ebot D E B leq (bvalf_HS D E B leq w1 X v False)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`False`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                 `X:A`;`v:num->A`]
    BVALF_HS_SPEC) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[bval_HS] THEN SIMP_TAC[]);;

let BVALF_HS_MEM = prove
 (`!i j D (E:A->A->bool) B leq w1 X v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      w1 IN D /\ X IN D /\
      valuation D v /\ (!k. hsname D E B w1 X (v k))
      ==> ebv_in D E B leq (v i) (v j) (bvalf_HS D E B leq w1 X v (i %% j))`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`(i:num) %% j`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                 `X:A`;`v:num->A`]
    BVALF_HS_SPEC) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[bval_HS] THEN SIMP_TAC[]);;

let BVALF_HS_EQ2 = prove
 (`!i j D (E:A->A->bool) B leq w1 X v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      w1 IN D /\ X IN D /\
      valuation D v /\ (!k. hsname D E B w1 X (v k))
      ==> ebv_eq D E B leq (v i) (v j) (bvalf_HS D E B leq w1 X v (Eq i j))`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`Eq i j`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                 `X:A`;`v:num->A`]
    BVALF_HS_SPEC) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[bval_HS] THEN SIMP_TAC[]);;

let BVALF_HS_IMP = prove
 (`!p q D (E:A->A->bool) B leq w1 X v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      w1 IN D /\ X IN D /\
      valuation D v /\ (!i. hsname D E B w1 X (v i))
      ==> ebimp D E B leq (bvalf_HS D E B leq w1 X v p)
          (bvalf_HS D E B leq w1 X v q)
                          (bvalf_HS D E B leq w1 X v (p --> q))`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`p --> q`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                 `X:A`;`v:num->A`]
    BVALF_HS_SPEC) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[bval_HS] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
    (X_CHOOSE_THEN `zp:A` (X_CHOOSE_THEN `zq:A` STRIP_ASSUME_TAC))) THEN
  SUBGOAL_THEN `bvalf_HS D (E:A->A->bool) B leq w1 X v p = zp /\
                bvalf_HS D E B leq w1 X v q = zq` STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN CONV_TAC SYM_CONV THENL
     [MATCH_MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                           `leq:A`;`w1:A`;`X:A`;
        `v:num->A`;`zp:A`] BVALF_HS_EQ);
      MATCH_MP_TAC(ISPECL [`q:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                           `leq:A`;`w1:A`;`X:A`;
        `v:num->A`;`zq:A`] BVALF_HS_EQ)] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_REWRITE_TAC[]);;

let BVALF_HS_NOT = prove
 (`!p D (E:A->A->bool) B leq w1 X v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      w1 IN D /\ X IN D /\
      valuation D v /\ (!i. hsname D E B w1 X (v i))
      ==> ecompl D E B leq (bvalf_HS D E B leq w1 X v p)
          (bvalf_HS D E B leq w1 X v (Not p))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[Not_DEF] THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[ecba]); ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `ebot D (E:A->A->bool) B leq (bvalf_HS D E B leq w1 X v False)`
      ASSUME_TAC THENL
   [MP_TAC(ISPECL [`False`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                   `X:A`;`v:num->A`]
      BVALF_HS_SPEC) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[bval_HS] THEN STRIP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`p:form`;`False`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                 `leq:A`;`w1:A`;`X:A`;
                 `v:num->A`] BVALF_HS_IMP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[ebimp] THEN
  DISCH_THEN(X_CHOOSE_THEN `c:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `(c:A) IN D /\ (E:A->A->bool) c B` STRIP_ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP ECOMPL_IN); ALL_TAC] THEN
  SUBGOAL_THEN `ejoin D (E:A->A->bool) B leq c
      (bvalf_HS D E B leq w1 X v False) c`
  ASSUME_TAC THENL
   [MATCH_MP_TAC EJOIN_SYM THEN MATCH_MP_TAC EJOIN_BOT THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `bvalf_HS D (E:A->A->bool) B leq w1 X v (p --> False) = c`
      SUBST1_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;
      `bvalf_HS D (E:A->A->bool) B leq w1 X v False`;
      `bvalf_HS D (E:A->A->bool) B leq w1 X v (p --> False)`;`c:A`]
          EJOIN_UNIQUE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_REWRITE_TAC[]);;

let BVALF_HS_ALL_LB = prove
 (`!n p D (E:A->A->bool) B leq w1 X v c.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      w1 IN D /\ X IN D /\
      valuation D v /\ (!i. hsname D E B w1 X (v i)) /\ c IN D /\
          hsname D E B w1 X c
      ==> erel D E leq (bvalf_HS D E B leq w1 X v (!! n p))
                       (bvalf_HS D E B leq w1 X ((n |-> c) v) p)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`!! n p`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                 `X:A`;`v:num->A`]
    BVALF_HS_SPEC) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[bval_HS] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
    (X_CHOOSE_THEN `sv:A` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `!i. hsname D E B w1 X (((n |-> (c:A)) (v:num->A)) i)`
      ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;`X:A`;
    `(n |-> (c:A)) (v:num->A)`] BVALF_HS_SPEC) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN STRIP_TAC THEN
  SUBGOAL_THEN `(E:A->A->bool) (bvalf_HS D (E:A->A->bool) B leq w1 X
      ((n |-> (c:A)) (v:num->A)) p) sv`
  ASSUME_TAC THENL
   [FIRST_X_ASSUM(fun th ->
      if is_forall(concl th) && mem `sv:A` (frees(concl th))
      then (MP_TAC(SPEC `bvalf_HS D (E:A->A->bool) B leq w1 X
                   ((n |-> (c:A)) (v:num->A)) p` th) THEN
            ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC])
      else failwith "skip") THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EXISTS_TAC `c:A` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`sv:A`;
    `bvalf_HS D (E:A->A->bool) B leq w1 X v (!! n p)`;
    `bvalf_HS D (E:A->A->bool) B leq w1 X ((n |-> (c:A)) (v:num->A))
        p`] EGLB_LB) THEN
  ASM_REWRITE_TAC[]);;

let BVALF_HS_EX_UB = prove
 (`!n p D (E:A->A->bool) B leq w1 X v a.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      w1 IN D /\ X IN D /\
      valuation D v /\ (!i. hsname D E B w1 X (v i)) /\ a IN D /\
          hsname D E B w1 X a
      ==> erel D E leq (bvalf_HS D E B leq w1 X ((n |-> a) v) p)
                       (bvalf_HS D E B leq w1 X v (?? n p))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((n |-> (a:A)) (v:num->A)) /\
                (!i. hsname D E B w1 X (((n |-> (a:A)) (v:num->A)) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC HSNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  REWRITE_TAC[Exists_DEF] THEN
  MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;`X:A`;
    `(n |-> (a:A)) (v:num->A)`] BVALF_HS_NOT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`!! n (Not p)`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                 `X:A`;`v:num->A`]
    BVALF_HS_NOT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
  ABBREV_TAC `pa = bvalf_HS D (E:A->A->bool) B leq w1 X
      ((n |-> (a:A)) (v:num->A)) p` THEN
  ABBREV_TAC `npa = bvalf_HS D (E:A->A->bool) B leq w1 X
      ((n |-> (a:A)) (v:num->A)) (Not p)` THEN
  ABBREV_TAC `glb = bvalf_HS D (E:A->A->bool) B leq w1 X (v:num->A)
      (!! n (Not p))` THEN
  ABBREV_TAC `cc = bvalf_HS D (E:A->A->bool) B leq w1 X (v:num->A)
      (Not(!! n (Not p)))` THEN
  SUBGOAL_THEN `(pa:A) IN D /\ (E:A->A->bool) pa B` STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "pa" THEN CONJ_TAC THENL
     [MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                     `X:A`;`(n |-> (a:A)) (v:num->A)`] BVALF_HS_SPEC) THEN
         ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                     `X:A`;`(n |-> (a:A)) (v:num->A)`] BVALF_HS_IN_B) THEN
          ASM_SIMP_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN `(npa:A) IN D /\ (E:A->A->bool) npa B` STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "npa" THEN CONJ_TAC THENL
     [MP_TAC(ISPECL [`Not p`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                     `X:A`;`(n |-> (a:A)) (v:num->A)`] BVALF_HS_SPEC) THEN
         ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`Not p`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                     `X:A`;`(n |-> (a:A)) (v:num->A)`] BVALF_HS_IN_B) THEN
          ASM_SIMP_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN `(glb:A) IN D /\ (E:A->A->bool) glb B` STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "glb" THEN CONJ_TAC THENL
     [MP_TAC(ISPECL [`!! n (Not p)`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                     `w1:A`;`X:A`;`v:num->A`] BVALF_HS_SPEC) THEN
         ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`!! n (Not p)`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                     `w1:A`;`X:A`;`v:num->A`] BVALF_HS_IN_B) THEN
          ASM_SIMP_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN `(cc:A) IN D /\ (E:A->A->bool) cc B` STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "cc" THEN CONJ_TAC THENL
     [MP_TAC(ISPECL [`Not(!! n (Not p))`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                     `leq:A`;`w1:A`;`X:A`;`v:num->A`] BVALF_HS_SPEC) THEN
         ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`Not(!! n (Not p))`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                     `leq:A`;`w1:A`;`X:A`;`v:num->A`] BVALF_HS_IN_B) THEN
          ASM_SIMP_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN `ecompl D (E:A->A->bool) B leq npa pa` ASSUME_TAC THENL
   [MATCH_MP_TAC ECOMPL_SYM THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq glb npa` ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["glb";"npa"] THEN
    MP_TAC(ISPECL [`n:num`;`Not p`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                   `w1:A`;`X:A`;`v:num->A`;`a:A`]
      BVALF_HS_ALL_LB) THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`glb:A`;
                 `npa:A`;`cc:A`;`pa:A`]
    ECOMPL_ANTITONE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]);;

let BVALF_HS_ALL_GLB = prove
 (`!n p D (E:A->A->bool) B leq w1 X v x.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      w1 IN D /\ X IN D /\
      valuation D v /\ (!i. hsname D E B w1 X (v i)) /\
      x IN D /\ E x B /\
      (!c. c IN D /\ hsname D E B w1 X c
           ==> erel D E leq x (bvalf_HS D E B leq w1 X ((n |-> c) v) p))
      ==> erel D E leq x (bvalf_HS D E B leq w1 X v (!! n p))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`!! n p`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                 `X:A`;`v:num->A`]
    BVALF_HS_SPEC) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[bval_HS] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
    (X_CHOOSE_THEN `S:A`
      (CONJUNCTS_THEN2 ASSUME_TAC
        (CONJUNCTS_THEN2 (LABEL_TAC "mem") ASSUME_TAC)))) THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`S:A`;
    `bvalf_HS D (E:A->A->bool) B leq w1 X v (!! n p)`;`x:A`] EGLB_GREATEST) THEN
  ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[elbound] THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `zz:A` THEN STRIP_TAC THEN
  USE_THEN "mem" (fun th -> MP_TAC(SPEC `zz:A` th) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC]) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `a:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `!i. hsname D E B w1 X (((n |-> (a:A)) (v:num->A)) i)`
      ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `zz:A = bvalf_HS D (E:A->A->bool) B leq w1 X
      ((n |-> (a:A)) (v:num->A)) p`
  SUBST1_TAC THENL
   [MATCH_MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                         `leq:A`;`w1:A`;`X:A`;
      `(n |-> (a:A)) (v:num->A)`;`zz:A`] BVALF_HS_EQ) THEN
    ASM_REWRITE_TAC[] THEN MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]);;

(* ===================================================================== *)
(* H2f : SYM_BVALF_HS -- the symmetry lemma for the HS valuation.            *)
(* By induction on formulas (bval_HS, !! over hsname).  The autN action on HS *)
(* names enters ONLY through two abstract hypotheses: autN maps HS names to  *)
(* HS names, and every HS name is the autN-image of an HS name (H2a-H2e      *)
(* discharge them for permutation-induced autB).  Atomic cases reuse         *)
(* AUT_EBVIN/AUT_EBVEQ through HSNAME_BNAME.                                 *)
(* ===================================================================== *)
let SYM_BVALF_HS = prove
 (`!p D (E:A->A->bool) B leq w1 X autB v vi.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
     w1 IN D /\ X IN D /\
     autB IN D /\ ebij D E autB B B /\
     (!x y xi yi. x IN D /\ y IN D /\ xi IN D /\ yi IN D /\
                  eapply D E autB x xi /\ eapply D E autB y yi
                  ==> (erel D E leq x y <=> erel D E leq xi yi)) /\
     (!c c'. c IN D /\ hsname D E B w1 X c /\ eautn D E B autB c c'
             ==> hsname D E B w1 X c') /\
     (!c'. c' IN D /\ hsname D E B w1 X c'
           ==> ?c. c IN D /\ hsname D E B w1 X c /\ eautn D E B autB c c') /\
     valuation D v /\ (!i. hsname D E B w1 X (v i)) /\
     valuation D vi /\ (!i. eautn D E B autB (v i) (vi i))
     ==> eapply D E autB (bvalf_HS D E B leq w1 X v p)
                         (bvalf_HS D E B leq w1 X vi p)`,
  MATCH_MP_TAC form_INDUCT THEN REPEAT CONJ_TAC THENL
   [(* ---- False ---- *)
    REPEAT GEN_TAC THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
     (CONJUNCTS_THEN2 (LABEL_TAC "cba")
      (CONJUNCTS_THEN2 (LABEL_TAC "BD")
       (CONJUNCTS_THEN2 (LABEL_TAC "leqD")
        (CONJUNCTS_THEN2 (LABEL_TAC "w1D")
         (CONJUNCTS_THEN2 (LABEL_TAC "XD")
          (CONJUNCTS_THEN2 (LABEL_TAC "aBD")
           (CONJUNCTS_THEN2 (LABEL_TAC "bij")
            (CONJUNCTS_THEN2 (LABEL_TAC "ord")
             (CONJUNCTS_THEN2 (LABEL_TAC "hsp")
              (CONJUNCTS_THEN2 (LABEL_TAC "hso")
               (CONJUNCTS_THEN2 (LABEL_TAC "vv")
                (CONJUNCTS_THEN2 (LABEL_TAC "bnv")
                 (CONJUNCTS_THEN2 (LABEL_TAC "vvi")
                  (LABEL_TAC "auti"))))))))))))))) THEN
    SUBGOAL_THEN `!i. hsname D (E:A->A->bool) B w1 X ((vi:num->A) i)`
    (LABEL_TAC "bnvi") THENL
     [X_GEN_TAC `i:num` THEN
      USE_THEN "hsp" (MP_TAC o SPECL [`(v:num->A) i`;`(vi:num->A) i`]) THEN
      ANTS_TAC THENL
       [REPEAT CONJ_TAC THENL
         [USE_THEN "vv" (ACCEPT_TAC o SPEC `i:num` o REWRITE_RULE[valuation]);
          USE_THEN "bnv" (ACCEPT_TAC o SPEC `i:num`);
          USE_THEN "auti" (ACCEPT_TAC o SPEC `i:num`)];
        DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `!i. bname D (E:A->A->bool) B ((v:num->A) i)`
    (LABEL_TAC "bnvB") THENL
     [X_GEN_TAC `i:num` THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;
                    `(v:num->A) i`] HSNAME_BNAME) THEN
      ANTS_TAC THENL
       [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THENL
         [USE_THEN "vv" (ACCEPT_TAC o SPEC `i:num` o REWRITE_RULE[valuation]);
          USE_THEN "bnv" (ACCEPT_TAC o SPEC `i:num`)];
        DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `!i. bname D (E:A->A->bool) B ((vi:num->A) i)`
    (LABEL_TAC "bnviB") THENL
     [X_GEN_TAC `i:num` THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;
                    `(vi:num->A) i`] HSNAME_BNAME) THEN
      ANTS_TAC THENL
       [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THENL
         [USE_THEN "vvi" (ACCEPT_TAC o SPEC `i:num` o REWRITE_RULE[valuation]);
          USE_THEN "bnvi" (ACCEPT_TAC o SPEC `i:num`)];
        DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` (LABEL_TAC "pord") THENL
     [ASM_MESON_TAC[ecba; EBALG_IMP_PORDER]; ALL_TAC] THEN
    SUBGOAL_THEN
     `(bvalf_HS D (E:A->A->bool) B leq w1 X v False) IN D /\
      (bvalf_HS D (E:A->A->bool) B leq w1 X vi False) IN D`
    STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [MP_TAC(ISPECL [`False`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                       `leq:A`;`w1:A`;`X:A`;
                   `v:num->A`] BVALF_HS_SPEC) THEN
          ANTS_TAC THENL [ASM_REWRITE_TAC[];
                          DISCH_THEN(ACCEPT_TAC o CONJUNCT1)];
        MP_TAC(ISPECL [`False`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                       `leq:A`;`w1:A`;`X:A`;
                   `vi:num->A`] BVALF_HS_SPEC) THEN
          ANTS_TAC THENL [ASM_REWRITE_TAC[];
                          DISCH_THEN(ACCEPT_TAC o CONJUNCT1)]];
      ALL_TAC] THEN
    SUBGOAL_THEN `ebot D (E:A->A->bool) B leq (bvalf_HS D E B leq w1 X v False)`
    ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                    `X:A`;`v:num->A`]
        BVALF_HS_FALSE) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `ebot D (E:A->A->bool) B leq
        (bvalf_HS D E B leq w1 X vi False)`
    ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                    `X:A`;`vi:num->A`]
        BVALF_HS_FALSE) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) (bvalf_HS D E B leq w1 X v False) B`
        ASSUME_TAC THENL
     [ASM_MESON_TAC[ebot]; ALL_TAC] THEN
    SUBGOAL_THEN
     `?z0. (z0:A) IN D /\ (E:A->A->bool) z0 B /\
           eapply D E autB (bvalf_HS D E B leq w1 X v False) z0`
    STRIP_ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;
                    `bvalf_HS D (E:A->A->bool) B leq w1 X v
                        False`] AUTB_IMG) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `ebot D (E:A->A->bool) B leq z0` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`autB:A`;
                    `bvalf_HS D (E:A->A->bool) B leq w1 X v False`;`z0:A`]
        EAUTB_BOT) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `bvalf_HS D (E:A->A->bool) B leq w1 X vi False = z0`
    SUBST1_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                    `bvalf_HS D (E:A->A->bool) B leq w1 X vi False`;`z0:A`]
        EBOT_UNIQUE) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      FIRST_ASSUM ACCEPT_TAC];
    (* ---- %% ---- *)
    MAP_EVERY X_GEN_TAC [`i0:num`;`j0:num`] THEN REPEAT GEN_TAC THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
     (CONJUNCTS_THEN2 (LABEL_TAC "cba")
      (CONJUNCTS_THEN2 (LABEL_TAC "BD")
       (CONJUNCTS_THEN2 (LABEL_TAC "leqD")
        (CONJUNCTS_THEN2 (LABEL_TAC "w1D")
         (CONJUNCTS_THEN2 (LABEL_TAC "XD")
          (CONJUNCTS_THEN2 (LABEL_TAC "aBD")
           (CONJUNCTS_THEN2 (LABEL_TAC "bij")
            (CONJUNCTS_THEN2 (LABEL_TAC "ord")
             (CONJUNCTS_THEN2 (LABEL_TAC "hsp")
              (CONJUNCTS_THEN2 (LABEL_TAC "hso")
               (CONJUNCTS_THEN2 (LABEL_TAC "vv")
                (CONJUNCTS_THEN2 (LABEL_TAC "bnv")
                 (CONJUNCTS_THEN2 (LABEL_TAC "vvi")
                  (LABEL_TAC "auti"))))))))))))))) THEN
    SUBGOAL_THEN `!i. hsname D (E:A->A->bool) B w1 X ((vi:num->A) i)`
    (LABEL_TAC "bnvi") THENL
     [X_GEN_TAC `i:num` THEN
      USE_THEN "hsp" (MP_TAC o SPECL [`(v:num->A) i`;`(vi:num->A) i`]) THEN
      ANTS_TAC THENL
       [REPEAT CONJ_TAC THENL
         [USE_THEN "vv" (ACCEPT_TAC o SPEC `i:num` o REWRITE_RULE[valuation]);
          USE_THEN "bnv" (ACCEPT_TAC o SPEC `i:num`);
          USE_THEN "auti" (ACCEPT_TAC o SPEC `i:num`)];
        DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `!i. bname D (E:A->A->bool) B ((v:num->A) i)`
    (LABEL_TAC "bnvB") THENL
     [X_GEN_TAC `i:num` THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;
                    `(v:num->A) i`] HSNAME_BNAME) THEN
      ANTS_TAC THENL
       [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THENL
         [USE_THEN "vv" (ACCEPT_TAC o SPEC `i:num` o REWRITE_RULE[valuation]);
          USE_THEN "bnv" (ACCEPT_TAC o SPEC `i:num`)];
        DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `!i. bname D (E:A->A->bool) B ((vi:num->A) i)`
    (LABEL_TAC "bnviB") THENL
     [X_GEN_TAC `i:num` THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;
                    `(vi:num->A) i`] HSNAME_BNAME) THEN
      ANTS_TAC THENL
       [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THENL
         [USE_THEN "vvi" (ACCEPT_TAC o SPEC `i:num` o REWRITE_RULE[valuation]);
          USE_THEN "bnvi" (ACCEPT_TAC o SPEC `i:num`)];
        DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    ABBREV_TAC `z = bvalf_HS D (E:A->A->bool) B leq w1 X v (i0 %% j0)` THEN
    ABBREV_TAC `zi = bvalf_HS D (E:A->A->bool) B leq w1 X vi (i0 %% j0)` THEN
    SUBGOAL_THEN `(z:A) IN D /\ (E:A->A->bool) z B` STRIP_ASSUME_TAC THENL
     [EXPAND_TAC "z" THEN CONJ_TAC THENL
       [MP_TAC(ISPECL [`(i0:num) %% j0`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                       `leq:A`;`w1:A`;`X:A`;`v:num->A`] BVALF_HS_SPEC) THEN
        ANTS_TAC THENL
         [ASM_REWRITE_TAC[]; DISCH_THEN(ACCEPT_TAC o CONJUNCT1)];
        MP_TAC(ISPECL [`(i0:num) %% j0`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                       `leq:A`;`w1:A`;`X:A`;`v:num->A`] BVALF_HS_IN_B) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]];
      ALL_TAC] THEN
    SUBGOAL_THEN `(zi:A) IN D` ASSUME_TAC THENL
     [EXPAND_TAC "zi" THEN
      MP_TAC(ISPECL [`(i0:num) %% j0`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                     `leq:A`;`w1:A`;`X:A`;`vi:num->A`] BVALF_HS_SPEC) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[]; DISCH_THEN(ACCEPT_TAC o CONJUNCT1)];
      ALL_TAC] THEN
    SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq ((v:num->A) i0) (v j0) z`
    ASSUME_TAC THENL
     [EXPAND_TAC "z" THEN
      MP_TAC(ISPECL [`i0:num`;`j0:num`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                     `leq:A`;`w1:A`;`X:A`;`v:num->A`] BVALF_HS_MEM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq ((vi:num->A) i0) (vi j0) zi`
    ASSUME_TAC THENL
     [EXPAND_TAC "zi" THEN
      MP_TAC(ISPECL [`i0:num`;`j0:num`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                     `leq:A`;`w1:A`;`X:A`;`vi:num->A`] BVALF_HS_MEM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `?z0. (z0:A) IN D /\ (E:A->A->bool) z0 B /\ eapply D E autB z z0`
    STRIP_ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`z:A`]
        AUTB_IMG) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq ((vi:num->A) i0) (vi j0) z0`
    ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`autB:A`;
                    `(v:num->A) i0`;`(v:num->A) j0`;`z:A`;
                    `(vi:num->A) i0`;`(vi:num->A) j0`;`z0:A`] AUT_EBVIN) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THEN
        TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[valuation];
        DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `zi:A = z0` SUBST1_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                    `(vi:num->A) i0`;`(vi:num->A) j0`;`zi:A`;`z0:A`]
        EBV_IN_UNIQUE) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THEN
        TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[valuation];
        DISCH_THEN ACCEPT_TAC];
      FIRST_ASSUM ACCEPT_TAC];
    (* ---- Eq ---- *)
    MAP_EVERY X_GEN_TAC [`i0:num`;`j0:num`] THEN REPEAT GEN_TAC THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
     (CONJUNCTS_THEN2 (LABEL_TAC "cba")
      (CONJUNCTS_THEN2 (LABEL_TAC "BD")
       (CONJUNCTS_THEN2 (LABEL_TAC "leqD")
