(* ######################################################################### *)
(* S5 / H2 : THE PERMUTATION ACTION PRESERVES HS AND [[.]]^HS                *)
(* H2a AUTN_GCOMP (autN respects composition of Boolean automorphisms);      *)
(* H2b pbundle + PBUNDLE_COMP / AUTN_COMP_PERM (composite permutations);     *)
(* H2c EHSSYM_AUTN (conjugation: supports transport to s[e]);                *)
(* H2d AUTN_HS (autN_s maps HS names to HS names);                           *)
(* H2e AUTN_HS_ONTO + SYM_BVALF_HS_PERM (symmetry lemma for bvalf_HS under   *)
(*     any permutation of w1).                                              *)
(* ######################################################################### *)
(* ===================================================================== *)
(* H2a : AUTN_GCOMP -- general composition of the name automorphisms.       *)
(* If autB3 = autB1 o autB2 on B (as eapply graphs) then                     *)
(*   autN_autB1 o autN_autB2 = autN_autB3 on B-names.                        *)
(* Proof: least-bn-rank counterexample.  The failure predicate is read off   *)
(* the three autN-tower stages cd1,cd2,cd3 at sa0 = rank+1 (slots 41,42,43): *)
(* gcomp_bad_form; separation over sa0 with bnrank_form, ZF_FOUNDATION; at   *)
(* the minimal counterexample z, AUTN_MEM thrice + extensionality.           *)
(* ===================================================================== *)
let gcomp_bad_form = new_definition
  `gcomp_bad_form =
     ?? 50 (?? 51 (?? 52 (?? 53 (?? 54 (?? 55 (
       opair_form 0 50 53 && (53 %% 42) &&
       opair_form 50 51 54 && (54 %% 41) &&
       opair_form 0 52 55 && (55 %% 43) && Not (Eq 51 52)))))))`;;

let HOLDS_GCOMP_BAD_FORM = prove
 (`!D (E:A->A->bool) v.
     valuation D v
     ==> (holds D E v gcomp_bad_form <=>
          ?vv. vv IN D /\ ?w. w IN D /\ ?w3. w3 IN D /\
          ?p1. p1 IN D /\ ?p2. p2 IN D /\ ?p3. p3 IN D /\
            eopair D E (v 0) vv p1 /\ E p1 (v 42) /\
            eopair D E vv w p2 /\ E p2 (v 41) /\
            eopair D E (v 0) w3 p3 /\ E p3 (v 43) /\ ~(w = w3))`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN REWRITE_TAC[gcomp_bad_form; HOLDS_EX] THEN
  MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s))
     ==> ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
  X_GEN_TAC `vv:A` THEN DISCH_TAC THEN
  MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s))
     ==> ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
  X_GEN_TAC `w:A` THEN DISCH_TAC THEN
  MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s))
     ==> ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
  X_GEN_TAC `w3:A` THEN DISCH_TAC THEN
  MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s))
     ==> ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
  X_GEN_TAC `p1:A` THEN DISCH_TAC THEN
  MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s))
     ==> ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
  X_GEN_TAC `p2:A` THEN DISCH_TAC THEN
  MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s))
     ==> ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
  X_GEN_TAC `p3:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN
   `valuation D ((55 |-> (p3:A)) ((54 |-> (p2:A)) ((53 |-> (p1:A))
      ((52 |-> (w3:A)) ((51 |-> (w:A)) ((50 |-> (vv:A)) v))))))`
   ASSUME_TAC THENL
   [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC) THEN
    FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  ASM_SIMP_TAC[HOLDS_AND; HOLDS_NOT; HOLDS_OPAIR_FORM] THEN
  REWRITE_TAC[holds; VALMOD; ARITH_EQ]);;

let AUTNSTAGE_PAIR_IN = prove
 (`!D (E:A->A->bool) B autB a ya cd t t1.
     model D E ZF_AX /\ B IN D /\ autB IN D /\ eordinal D E a /\
     ya IN D /\ cd IN D /\ ebnstage D E B a ya /\ autnstage D E B autB a cd /\
     t IN D /\ E t ya /\ eautn D E B autB t t1
     ==> ?pp. pp IN D /\ eopair D E t t1 pp /\ E pp cd`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
             (CONJUNCTS_THEN2 (LABEL_TAC "BD")
              (CONJUNCTS_THEN2 (LABEL_TAC "aBD")
               (CONJUNCTS_THEN2 (LABEL_TAC "aord")
                (CONJUNCTS_THEN2 (LABEL_TAC "yaD")
                 (CONJUNCTS_THEN2 (LABEL_TAC "cdD")
                  (CONJUNCTS_THEN2 (LABEL_TAC "bnst")
                   (CONJUNCTS_THEN2 (LABEL_TAC "aust")
                    (CONJUNCTS_THEN2 (LABEL_TAC "tD")
                     (CONJUNCTS_THEN2 (LABEL_TAC "tya")
                      (LABEL_TAC "aut1"))))))))))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`a:A`;`ya:A`;`cd:A`]
    AUTN_COVER_AT) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `t:A`) THEN
  ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `img:A` (X_CHOOSE_THEN `pp:A`
      (CONJUNCTS_THEN2 (LABEL_TAC "imgD")
       (CONJUNCTS_THEN2 (LABEL_TAC "ppD")
        (CONJUNCTS_THEN2 (LABEL_TAC "ppop") (LABEL_TAC "ppcd")))))) THEN
  SUBGOAL_THEN `eautn D (E:A->A->bool) B autB t img` (LABEL_TAC "autimg") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`a:A`;`cd:A`;
                  `t:A`;`img:A`;`pp:A`] AUTN_STAGE) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `img:A = t1` SUBST_ALL_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;
                  `t:A`;`img:A`;`t1:A`]
      AUTN_SV) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  EXISTS_TAC `pp:A` THEN REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC);;

let AUTN_GCOMP = prove
 (`!D (E:A->A->bool) B autB1 autB2 autB3 x v w.
     model D E ZF_AX /\ B IN D /\ autB1 IN D /\ autB2 IN D /\ autB3 IN D /\
     ebij D E autB1 B B /\ ebij D E autB2 B B /\
     (!c c3. c IN D /\ c3 IN D /\ E c B
             ==> (eapply D E autB3 c c3 <=>
                  ?c2. c2 IN D /\ eapply D E autB2 c c2 /\
                       eapply D E autB1 c2 c3)) /\
     x IN D /\ bname D E B x /\
     eautn D E B autB2 x v /\ eautn D E B autB1 v w
     ==> eautn D E B autB3 x w`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
             (CONJUNCTS_THEN2 (LABEL_TAC "BD")
              (CONJUNCTS_THEN2 (LABEL_TAC "a1D")
               (CONJUNCTS_THEN2 (LABEL_TAC "a2D")
