         AUTN_TOTAL) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `w3:A` (CONJUNCTS_THEN2 (LABEL_TAC "w3D")
      (LABEL_TAC "e3x"))) THEN
  USE_THEN "good" (MP_TAC o SPEC `x:A`) THEN
  ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL [`v:A`;`w:A`;`w3:A`]) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN USE_THEN "e3x" ACCEPT_TAC);;

(* ===================================================================== *)
(* H2b : composite permutations induce composite Boolean automorphisms.     *)
(* pbundle = the full true bundle (muci, muP, autB, their bijectivity, the   *)
(* three characterizations, order preservation) of a permutation s of w1.   *)
(* IMG_COMP / MUCIREL_COMP / LIFT_COMP: image-lifting of a composition;      *)
(* PBUNDLE_COMP: s3 = s1 o s2 ==> autB3 = autB1 o autB2 on B;               *)
(* AUTN_COMP_PERM: hence autN3 = autN1 o autN2 on B-names (AUTN_GCOMP).      *)
(* ===================================================================== *)
let pbundle = new_definition
 `pbundle D (E:A->A->bool) ci P leqp B inclB s muci muP autB <=>
    muci IN D /\ muP IN D /\ autB IN D /\
    ebij D E muci ci ci /\ ebij D E muP P P /\ ebij D E autB B B /\
    (!u w. u IN D /\ w IN D
           ==> (eapply D E muci u w <=> E u ci /\ mucirel D E s u w)) /\
    (!p q. p IN D /\ q IN D
           ==> (eapply D E muP p q <=> E p P /\ muPrel D E muci p q)) /\
    (!b c. b IN D /\ c IN D
           ==> (eapply D E autB b c <=> E b B /\ muPrel D E muP b c)) /\
    (!pa pb qa qb. pa IN D /\ pb IN D /\ qa IN D /\ qb IN D /\
                   eapply D E muP pa qa /\ eapply D E muP pb qb
                   ==> (erel D E leqp pa pb <=> erel D E leqp qa qb)) /\
    (!a b ai bi. a IN D /\ b IN D /\ ai IN D /\ bi IN D /\
                 eapply D E autB a ai /\ eapply D E autB b bi
                 ==> (erel D E inclB a b <=> erel D E inclB ai bi))`;;

let PBUNDLE_EXISTS = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X s.
     hsbundle D E w1 om tw ii ci P leqp B inclB onebee X /\
     s IN D /\ eperm D E w1 s
     ==> ?muci muP autB. pbundle D E ci P leqp B inclB s muci muP autB`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "hsb")
             (CONJUNCTS_THEN2 (LABEL_TAC "sD") (LABEL_TAC "sperm"))) THEN
  USE_THEN "hsb" (MP_TAC o REWRITE_RULE[hsbundle]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
             (CONJUNCTS_THEN2 (LABEL_TAC "vl")
              (CONJUNCTS_THEN2 (LABEL_TAC "eom")
               (CONJUNCTS_THEN2 (LABEL_TAC "w1D")
                (CONJUNCTS_THEN2 (LABEL_TAC "w1card")
                 (CONJUNCTS_THEN2 (LABEL_TAC "omw1")
                  (CONJUNCTS_THEN2 (LABEL_TAC "w1min")
                   (CONJUNCTS_THEN2 (LABEL_TAC "cr1")
                    (CONJUNCTS_THEN2 (LABEL_TAC "cr2")
                     (CONJUNCTS_THEN2 (LABEL_TAC "ftw")
                      (CONJUNCTS_THEN2 (LABEL_TAC "coh")
                       (CONJUNCTS_THEN2 (LABEL_TAC "leq")
                        (CONJUNCTS_THEN2 (LABEL_TAC "ros")
                         (CONJUNCTS_THEN2 (LABEL_TAC "inc")
                          (CONJUNCTS_THEN2 (LABEL_TAC "porder")
      (CONJUNCTS_THEN2 (LABEL_TAC "top")
       (CONJUNCTS_THEN2 (LABEL_TAC "oneD")
        (CONJUNCTS_THEN2 (LABEL_TAC "BD")
         (CONJUNCTS_THEN2 (LABEL_TAC "oneB")
          (CONJUNCTS_THEN2 (LABEL_TAC "XD")
           (CONJUNCTS_THEN2 (LABEL_TAC "ciX")
            (LABEL_TAC "PX")))))))))))))))))))))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;
                `ii:A`;`ci:A`;`P:A`;
                `leqp:A`;`s:A`] PERM_MUP_BUNDLE) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `muci:A` (X_CHOOSE_THEN `muP:A`
      (CONJUNCTS_THEN2 (LABEL_TAC "mD") (CONJUNCTS_THEN2 (LABEL_TAC "mPD")
      (CONJUNCTS_THEN2 (LABEL_TAC "bijm")
       (CONJUNCTS_THEN2 (LABEL_TAC "bijP")
        (CONJUNCTS_THEN2 (LABEL_TAC "mch")
         (CONJUNCTS_THEN2 (LABEL_TAC "Pch") (LABEL_TAC "ordP"))))))))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`B:A`;
                `inclB:A`;`muP:A`]
    EAUT_CBA) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `autB:A` (CONJUNCTS_THEN2 (LABEL_TAC "aD")
      (CONJUNCTS_THEN2 (LABEL_TAC "ach")
       (CONJUNCTS_THEN2 (LABEL_TAC "bijB") (LABEL_TAC "ordB"))))) THEN
  MAP_EVERY EXISTS_TAC [`muci:A`;`muP:A`;`autB:A`] THEN
  REWRITE_TAC[pbundle] THEN REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC);;

let IMG_COMP = prove
 (`!D (E:A->A->bool) g1 g2 g3 X p q1 q2 q3.
     model D E ZF_AX /\ p IN D /\ esubset D E p X /\
     (!x z. x IN D /\ z IN D /\ E x X
            ==> (eapply D E g3 x z <=>
                 ?y. y IN D /\ eapply D E g2 x y /\ eapply D E g1 y z)) /\
     muPrel D E g2 p q2 /\ muPrel D E g1 q2 q1 /\ muPrel D E g3 p q3
     ==> q1 = q3`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
             (CONJUNCTS_THEN2 (LABEL_TAC "pD")
              (CONJUNCTS_THEN2 (LABEL_TAC "psub")
               (CONJUNCTS_THEN2 (LABEL_TAC "comp")
                (CONJUNCTS_THEN2 (LABEL_TAC "m2")
                 (CONJUNCTS_THEN2 (LABEL_TAC "m1") (LABEL_TAC "m3"))))))) THEN
  USE_THEN "m2" (MP_TAC o REWRITE_RULE[muPrel]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "q2D") (LABEL_TAC "q2ch")) THEN
  USE_THEN "m1" (MP_TAC o REWRITE_RULE[muPrel]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "q1D") (LABEL_TAC "q1ch")) THEN
  USE_THEN "m3" (MP_TAC o REWRITE_RULE[muPrel]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "q3D") (LABEL_TAC "q3ch")) THEN
  USE_THEN "modl" (MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
  REPEAT CONJ_TAC THENL [USE_THEN "q1D" ACCEPT_TAC;
                         USE_THEN "q3D" ACCEPT_TAC; ALL_TAC] THEN
  X_GEN_TAC `z:A` THEN DISCH_THEN(LABEL_TAC "zD") THEN
  USE_THEN "q1ch" (MP_TAC o SPEC `z:A`) THEN
  ANTS_TAC THENL [USE_THEN "zD" ACCEPT_TAC; DISCH_THEN SUBST1_TAC] THEN
  USE_THEN "q3ch" (MP_TAC o SPEC `z:A`) THEN
  ANTS_TAC THENL [USE_THEN "zD" ACCEPT_TAC; DISCH_THEN SUBST1_TAC] THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `y:A` (CONJUNCTS_THEN2 (LABEL_TAC "yD")
       (CONJUNCTS_THEN2 (LABEL_TAC "yq2") (LABEL_TAC "g1yz")))) THEN
    USE_THEN "q2ch" (MP_TAC o SPEC `y:A`) THEN
    ANTS_TAC THENL [USE_THEN "yD" ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "yq2" (MP_TAC o EQ_MP th)) THEN
    DISCH_THEN(X_CHOOSE_THEN `x:A` (CONJUNCTS_THEN2 (LABEL_TAC "xD")
        (CONJUNCTS_THEN2 (LABEL_TAC "xp") (LABEL_TAC "g2xy")))) THEN
    EXISTS_TAC `x:A` THEN
    CONJ_TAC THENL [USE_THEN "xD" ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL [USE_THEN "xp" ACCEPT_TAC; ALL_TAC] THEN
    USE_THEN "comp" (MP_TAC o SPECL [`x:A`;`z:A`]) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      USE_THEN "psub" (MP_TAC o SPEC `x:A` o REWRITE_RULE[esubset]) THEN
      ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EXISTS_TAC `y:A` THEN REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    DISCH_THEN(X_CHOOSE_THEN `x:A` (CONJUNCTS_THEN2 (LABEL_TAC "xD")
        (CONJUNCTS_THEN2 (LABEL_TAC "xp") (LABEL_TAC "g3xz")))) THEN
    USE_THEN "comp" (MP_TAC o SPECL [`x:A`;`z:A`]) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      USE_THEN "psub" (MP_TAC o SPEC `x:A` o REWRITE_RULE[esubset]) THEN
      ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "g3xz" (MP_TAC o EQ_MP th)) THEN
    DISCH_THEN(X_CHOOSE_THEN `y:A` (CONJUNCTS_THEN2 (LABEL_TAC "yD")
        (CONJUNCTS_THEN2 (LABEL_TAC "g2xy") (LABEL_TAC "g1yz")))) THEN
    EXISTS_TAC `y:A` THEN
    CONJ_TAC THENL [USE_THEN "yD" ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL [ALL_TAC; USE_THEN "g1yz" ACCEPT_TAC] THEN
    USE_THEN "q2ch" (MP_TAC o SPEC `y:A`) THEN
    ANTS_TAC THENL [USE_THEN "yD" ACCEPT_TAC;
                    DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
    EXISTS_TAC `x:A` THEN REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC]);;

let MUCIREL_COMP = prove
 (`!D (E:A->A->bool) s1 s2 s3 u w3.
     model D E ZF_AX /\
     (!x z. x IN D /\ z IN D
            ==> (eapply D E s3 x z <=>
                 ?y. y IN D /\ eapply D E s2 x y /\ eapply D E s1 y z))
     ==> (mucirel D E s3 u w3 <=>
          ?w2. w2 IN D /\ mucirel D E s2 u w2 /\ mucirel D E s1 w2 w3)`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl") (LABEL_TAC "comp")) THEN
  EQ_TAC THENL
   [REWRITE_TAC[mucirel] THEN
    DISCH_THEN(X_CHOOSE_THEN `a3:A` (X_CHOOSE_THEN `a4:A`
        (X_CHOOSE_THEN `a5:A` (X_CHOOSE_THEN `a6:A`
        (X_CHOOSE_THEN `a7:A` (X_CHOOSE_THEN `a8:A`
        (CONJUNCTS_THEN2 (LABEL_TAC "a3D")
         (CONJUNCTS_THEN2 (LABEL_TAC "a4D")
          (CONJUNCTS_THEN2 (LABEL_TAC "a5D")
           (CONJUNCTS_THEN2 (LABEL_TAC "a6D")
            (CONJUNCTS_THEN2 (LABEL_TAC "a7D")
             (CONJUNCTS_THEN2 (LABEL_TAC "a8D")
              (CONJUNCTS_THEN2 (LABEL_TAC "op56")
               (CONJUNCTS_THEN2 (LABEL_TAC "op34")
                (CONJUNCTS_THEN2 (LABEL_TAC "s3a")
                 (CONJUNCTS_THEN2 (LABEL_TAC "op76")
                  (LABEL_TAC "op84"))))))))))))))))) THEN
    USE_THEN "comp" (MP_TAC o SPECL [`a5:A`;`a7:A`]) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "s3a" (MP_TAC o EQ_MP th)) THEN
    DISCH_THEN(X_CHOOSE_THEN `y:A` (CONJUNCTS_THEN2 (LABEL_TAC "yD")
        (CONJUNCTS_THEN2 (LABEL_TAC "s2y") (LABEL_TAC "s1y")))) THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`y:A`;`a6:A`] EOPAIR_EXISTS) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `b8:A` (LABEL_TAC "opy6")) THEN
    SUBGOAL_THEN `(b8:A) IN D` (LABEL_TAC "b8D") THENL
     [USE_THEN "opy6" (ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`b8:A`;`a4:A`] EOPAIR_EXISTS) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `w2:A` (LABEL_TAC "opw2")) THEN
    SUBGOAL_THEN `(w2:A) IN D` (LABEL_TAC "w2D") THENL
     [USE_THEN "opw2" (ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
    EXISTS_TAC `w2:A` THEN
    CONJ_TAC THENL [USE_THEN "w2D" ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL
     [MAP_EVERY EXISTS_TAC [`a3:A`;`a4:A`;`a5:A`;`a6:A`;`y:A`;`b8:A`] THEN
      REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
      MAP_EVERY EXISTS_TAC [`b8:A`;`a4:A`;`y:A`;`a6:A`;`a7:A`;`a8:A`] THEN
      REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC];
    DISCH_THEN(X_CHOOSE_THEN `w2:A` (CONJUNCTS_THEN2 (LABEL_TAC "w2D")
        (CONJUNCTS_THEN2 (MP_TAC o REWRITE_RULE[mucirel])
         (MP_TAC o REWRITE_RULE[mucirel])))) THEN
    DISCH_THEN(X_CHOOSE_THEN `b3:A` (X_CHOOSE_THEN `b4:A`
        (X_CHOOSE_THEN `b5:A` (X_CHOOSE_THEN `b6:A`
        (X_CHOOSE_THEN `b7:A` (X_CHOOSE_THEN `b8:A`
        (CONJUNCTS_THEN2 (LABEL_TAC "b3D")
         (CONJUNCTS_THEN2 (LABEL_TAC "b4D")
          (CONJUNCTS_THEN2 (LABEL_TAC "b5D")
           (CONJUNCTS_THEN2 (LABEL_TAC "b6D")
            (CONJUNCTS_THEN2 (LABEL_TAC "b7D")
             (CONJUNCTS_THEN2 (LABEL_TAC "b8D")
              (CONJUNCTS_THEN2 (LABEL_TAC "pb56")
               (CONJUNCTS_THEN2 (LABEL_TAC "pb34")
                (CONJUNCTS_THEN2 (LABEL_TAC "s1b")
                 (CONJUNCTS_THEN2 (LABEL_TAC "pb76")
                  (LABEL_TAC "pb84"))))))))))))))))) THEN
    DISCH_THEN(X_CHOOSE_THEN `a3:A` (X_CHOOSE_THEN `a4:A`
        (X_CHOOSE_THEN `a5:A` (X_CHOOSE_THEN `a6:A`
        (X_CHOOSE_THEN `a7:A` (X_CHOOSE_THEN `a8:A`
        (CONJUNCTS_THEN2 (LABEL_TAC "a3D")
         (CONJUNCTS_THEN2 (LABEL_TAC "a4D")
          (CONJUNCTS_THEN2 (LABEL_TAC "a5D")
           (CONJUNCTS_THEN2 (LABEL_TAC "a6D")
            (CONJUNCTS_THEN2 (LABEL_TAC "a7D")
             (CONJUNCTS_THEN2 (LABEL_TAC "a8D")
              (CONJUNCTS_THEN2 (LABEL_TAC "op56")
               (CONJUNCTS_THEN2 (LABEL_TAC "op34")
                (CONJUNCTS_THEN2 (LABEL_TAC "s2a")
                 (CONJUNCTS_THEN2 (LABEL_TAC "op76")
                  (LABEL_TAC "op84"))))))))))))))))) THEN
    SUBGOAL_THEN `(a8:A) = b3 /\ (a4:A) = b4`
        (CONJUNCTS_THEN2 SUBST_ALL_TAC SUBST_ALL_TAC) THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`a8:A`;`a4:A`;`b3:A`;`b4:A`;
                    `w2:A`] EOPAIR_INJ) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `(a7:A) = b5 /\ (a6:A) = b6`
        (CONJUNCTS_THEN2 SUBST_ALL_TAC SUBST_ALL_TAC) THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`a7:A`;`a6:A`;`b5:A`;`b6:A`;
                    `b3:A`] EOPAIR_INJ) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    REWRITE_TAC[mucirel] THEN
    MAP_EVERY EXISTS_TAC [`a3:A`;`b4:A`;`a5:A`;`b6:A`;`b7:A`;`b8:A`] THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    USE_THEN "comp" (MP_TAC o SPECL [`a5:A`;`b7:A`]) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EXISTS_TAC `b5:A` THEN REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC]);;

let LIFT_COMP = prove
 (`!D (E:A->A->bool) X Y g1 g2 g3 h1 h2 h3.
     model D E ZF_AX /\
     (!x z. x IN D /\ z IN D /\ E x X
            ==> (eapply D E g3 x z <=>
                 ?y. y IN D /\ eapply D E g2 x y /\ eapply D E g1 y z)) /\
     (!p q. p IN D /\ q IN D ==> (eapply D E h1 p q <=> E p Y /\
         muPrel D E g1 p q)) /\
     (!p q. p IN D /\ q IN D ==> (eapply D E h2 p q <=> E p Y /\
         muPrel D E g2 p q)) /\
     (!p q. p IN D /\ q IN D ==> (eapply D E h3 p q <=> E p Y /\
         muPrel D E g3 p q)) /\
     ebij D E h1 Y Y /\ ebij D E h2 Y Y /\ ebij D E h3 Y Y /\
     (!p. p IN D /\ E p Y ==> esubset D E p X)
     ==> (!p q3. p IN D /\ q3 IN D /\ E p Y
                 ==> (eapply D E h3 p q3 <=>
                      ?q2. q2 IN D /\ eapply D E h2 p q2 /\
                          eapply D E h1 q2 q3))`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
             (CONJUNCTS_THEN2 (LABEL_TAC "comp")
              (CONJUNCTS_THEN2 (LABEL_TAC "h1ch")
               (CONJUNCTS_THEN2 (LABEL_TAC "h2ch")
                (CONJUNCTS_THEN2 (LABEL_TAC "h3ch")
                 (CONJUNCTS_THEN2 (LABEL_TAC "bij1")
                  (CONJUNCTS_THEN2 (LABEL_TAC "bij2")
                   (CONJUNCTS_THEN2 (LABEL_TAC "bij3")
                    (LABEL_TAC "Ysub"))))))))) THEN
  MAP_EVERY X_GEN_TAC [`p:A`;`q3:A`] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "pD")
             (CONJUNCTS_THEN2 (LABEL_TAC "q3D") (LABEL_TAC "pY"))) THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) p X` (LABEL_TAC "pX") THENL
   [USE_THEN "Ysub" (MP_TAC o SPEC `p:A`) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  USE_THEN "bij2" (MP_TAC o SPEC `p:A` o CONJUNCT1 o CONJUNCT2 o CONJUNCT2 o
                   REWRITE_RULE[ebij]) THEN
  ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `q2:A` (CONJUNCTS_THEN2 (LABEL_TAC "q2D")
      (CONJUNCTS_THEN2 (LABEL_TAC "q2Y") (LABEL_TAC "h2pq2")))) THEN
  USE_THEN "bij1" (MP_TAC o SPEC `q2:A` o CONJUNCT1 o CONJUNCT2 o CONJUNCT2 o
                   REWRITE_RULE[ebij]) THEN
  ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `q1:A` (CONJUNCTS_THEN2 (LABEL_TAC "q1D")
      (CONJUNCTS_THEN2 (LABEL_TAC "q1Y") (LABEL_TAC "h1q2q1")))) THEN
  USE_THEN "bij3" (MP_TAC o SPEC `p:A` o CONJUNCT1 o CONJUNCT2 o CONJUNCT2 o
                   REWRITE_RULE[ebij]) THEN
  ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `q3x:A` (CONJUNCTS_THEN2 (LABEL_TAC "q3xD")
      (CONJUNCTS_THEN2 (LABEL_TAC "q3xY") (LABEL_TAC "h3pq3x")))) THEN
  SUBGOAL_THEN
   `muPrel D (E:A->A->bool) g2 p q2 /\ muPrel D E g1 q2 q1 /\
       muPrel D E g3 p q3x`
   (CONJUNCTS_THEN2 (LABEL_TAC "m2") (CONJUNCTS_THEN2 (LABEL_TAC "m1")
       (LABEL_TAC "m3"))) THENL
   [REPEAT CONJ_TAC THENL
     [USE_THEN "h2ch" (MP_TAC o SPECL [`p:A`;`q2:A`]) THEN
      ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> USE_THEN "h2pq2" (MP_TAC o EQ_MP th));
      USE_THEN "h1ch" (MP_TAC o SPECL [`q2:A`;`q1:A`]) THEN
      ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> USE_THEN "h1q2q1" (MP_TAC o EQ_MP th));
      USE_THEN "h3ch" (MP_TAC o SPECL [`p:A`;`q3x:A`]) THEN
      ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> USE_THEN "h3pq3x" (MP_TAC o EQ_MP th))] THEN
    DISCH_THEN(ACCEPT_TAC o CONJUNCT2);
    ALL_TAC] THEN
  SUBGOAL_THEN `q1:A = q3x` (LABEL_TAC "q13") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`g1:A`;`g2:A`;`g3:A`;`X:A`;`p:A`;
                  `q1:A`;`q2:A`;`q3x:A`] IMG_COMP) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  EQ_TAC THENL
   [DISCH_THEN(LABEL_TAC "h3pq3") THEN
    SUBGOAL_THEN `q3:A = q3x` SUBST_ALL_TAC THENL
     [USE_THEN "bij3" (MP_TAC o SPECL [`p:A`;`q3:A`;`q3x:A`] o CONJUNCT1 o
                       CONJUNCT2 o CONJUNCT2 o CONJUNCT2 o
         REWRITE_RULE[ebij]) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    EXISTS_TAC `q2:A` THEN
    CONJ_TAC THENL [USE_THEN "q2D" ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL [USE_THEN "h2pq2" ACCEPT_TAC; ALL_TAC] THEN
    USE_THEN "q13" (SUBST1_TAC o SYM) THEN USE_THEN "h1q2q1" ACCEPT_TAC;
    DISCH_THEN(X_CHOOSE_THEN `q2b:A` (CONJUNCTS_THEN2 (LABEL_TAC "q2bD")
        (CONJUNCTS_THEN2 (LABEL_TAC "h2b") (LABEL_TAC "h1b")))) THEN
    SUBGOAL_THEN `q2b:A = q2` SUBST_ALL_TAC THENL
     [USE_THEN "bij2" (MP_TAC o SPECL [`p:A`;`q2b:A`;`q2:A`] o CONJUNCT1 o
                       CONJUNCT2 o CONJUNCT2 o CONJUNCT2 o
         REWRITE_RULE[ebij]) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `q3:A = q1` SUBST_ALL_TAC THENL
     [USE_THEN "bij1" (MP_TAC o SPECL [`q2:A`;`q3:A`;`q1:A`] o CONJUNCT1 o
                       CONJUNCT2 o CONJUNCT2 o CONJUNCT2 o
         REWRITE_RULE[ebij]) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    USE_THEN "q13" SUBST1_TAC THEN USE_THEN "h3pq3x" ACCEPT_TAC]);;

let PBUNDLE_COMP = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X
     s1 s2 s3 muci1 muP1 autB1 muci2 muP2 autB2 muci3 muP3 autB3.
     hsbundle D E w1 om tw ii ci P leqp B inclB onebee X /\
     pbundle D E ci P leqp B inclB s1 muci1 muP1 autB1 /\
     pbundle D E ci P leqp B inclB s2 muci2 muP2 autB2 /\
     pbundle D E ci P leqp B inclB s3 muci3 muP3 autB3 /\
     (!x z. x IN D /\ z IN D
            ==> (eapply D E s3 x z <=>
                 ?y. y IN D /\ eapply D E s2 x y /\ eapply D E s1 y z))
     ==> (!c c3. c IN D /\ c3 IN D /\ E c B
                 ==> (eapply D E autB3 c c3 <=>
                      ?c2. c2 IN D /\ eapply D E autB2 c c2 /\
                           eapply D E autB1 c2 c3))`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "hsb")
             (CONJUNCTS_THEN2 (MP_TAC o REWRITE_RULE[pbundle])
              (CONJUNCTS_THEN2 (MP_TAC o REWRITE_RULE[pbundle])
               (CONJUNCTS_THEN2 (MP_TAC o REWRITE_RULE[pbundle])
                (LABEL_TAC "scomp"))))) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "m3D")
             (CONJUNCTS_THEN2 (LABEL_TAC "mP3D")
              (CONJUNCTS_THEN2 (LABEL_TAC "a3D")
               (CONJUNCTS_THEN2 (LABEL_TAC "bm3")
                (CONJUNCTS_THEN2 (LABEL_TAC "bP3")
                 (CONJUNCTS_THEN2 (LABEL_TAC "bA3")
                  (CONJUNCTS_THEN2 (LABEL_TAC "mch3")
                   (CONJUNCTS_THEN2 (LABEL_TAC "Pch3")
                    (CONJUNCTS_THEN2 (LABEL_TAC "ach3")
                     (CONJUNCTS_THEN2 (LABEL_TAC "oP3")
                      (LABEL_TAC "oB3"))))))))))) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "m2D")
             (CONJUNCTS_THEN2 (LABEL_TAC "mP2D")
              (CONJUNCTS_THEN2 (LABEL_TAC "a2D")
               (CONJUNCTS_THEN2 (LABEL_TAC "bm2")
                (CONJUNCTS_THEN2 (LABEL_TAC "bP2")
                 (CONJUNCTS_THEN2 (LABEL_TAC "bA2")
                  (CONJUNCTS_THEN2 (LABEL_TAC "mch2")
                   (CONJUNCTS_THEN2 (LABEL_TAC "Pch2")
                    (CONJUNCTS_THEN2 (LABEL_TAC "ach2")
                     (CONJUNCTS_THEN2 (LABEL_TAC "oP2")
                      (LABEL_TAC "oB2"))))))))))) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "m1D")
             (CONJUNCTS_THEN2 (LABEL_TAC "mP1D")
              (CONJUNCTS_THEN2 (LABEL_TAC "a1D")
               (CONJUNCTS_THEN2 (LABEL_TAC "bm1")
                (CONJUNCTS_THEN2 (LABEL_TAC "bP1")
                 (CONJUNCTS_THEN2 (LABEL_TAC "bA1")
                  (CONJUNCTS_THEN2 (LABEL_TAC "mch1")
                   (CONJUNCTS_THEN2 (LABEL_TAC "Pch1")
                    (CONJUNCTS_THEN2 (LABEL_TAC "ach1")
                     (CONJUNCTS_THEN2 (LABEL_TAC "oP1")
                      (LABEL_TAC "oB1"))))))))))) THEN
  USE_THEN "hsb" (MP_TAC o REWRITE_RULE[hsbundle]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
             (CONJUNCTS_THEN2 (LABEL_TAC "vl")
              (CONJUNCTS_THEN2 (LABEL_TAC "eom")
               (CONJUNCTS_THEN2 (LABEL_TAC "w1D")
                (CONJUNCTS_THEN2 (LABEL_TAC "w1card")
                 (CONJUNCTS_THEN2 (LABEL_TAC "omw1")
                  (CONJUNCTS_THEN2 (LABEL_TAC "w1min")
                   (CONJUNCTS_THEN2 (LABEL_TAC "cr1")
                    (CONJUNCTS_THEN2 (LABEL_TAC "cr2")
                     (CONJUNCTS_THEN2 (LABEL_TAC "ftw")
                      (CONJUNCTS_THEN2 (LABEL_TAC "coh")
                       (CONJUNCTS_THEN2 (LABEL_TAC "leq")
                        (CONJUNCTS_THEN2 (LABEL_TAC "ros")
                         (CONJUNCTS_THEN2 (LABEL_TAC "inc")
                          (CONJUNCTS_THEN2 (LABEL_TAC "porder")
      (CONJUNCTS_THEN2 (LABEL_TAC "top")
       (CONJUNCTS_THEN2 (LABEL_TAC "oneD")
        (CONJUNCTS_THEN2 (LABEL_TAC "BD")
         (CONJUNCTS_THEN2 (LABEL_TAC "oneB")
          (CONJUNCTS_THEN2 (LABEL_TAC "XD")
           (CONJUNCTS_THEN2 (LABEL_TAC "ciX")
            (LABEL_TAC "PX")))))))))))))))))))))) THEN
  (* muci3 = muci1 o muci2 on ci *)
  SUBGOAL_THEN
   `!u w3. u IN D /\ w3 IN D /\ (E:A->A->bool) u ci
           ==> (eapply D E muci3 u w3 <=>
                ?w2. w2 IN D /\ eapply D E muci2 u w2 /\
                    eapply D E muci1 w2 w3)`
   (LABEL_TAC "mcomp") THENL
   [MAP_EVERY X_GEN_TAC [`u:A`;`w3:A`] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "uD")
               (CONJUNCTS_THEN2 (LABEL_TAC "w3D") (LABEL_TAC "uci"))) THEN
    USE_THEN "mch3" (MP_TAC o SPECL [`u:A`;`w3:A`]) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN SUBST1_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`s1:A`;`s2:A`;`s3:A`;`u:A`;`w3:A`]
      MUCIREL_COMP) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN SUBST1_TAC] THEN
    EQ_TAC THENL
     [DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
        (X_CHOOSE_THEN `w2:A` (CONJUNCTS_THEN2 (LABEL_TAC "w2D")
                               (CONJUNCTS_THEN2 (LABEL_TAC "r2")
                                (LABEL_TAC "r1"))))) THEN
      SUBGOAL_THEN `eapply D (E:A->A->bool) muci2 u w2` (LABEL_TAC "e2") THENL
       [USE_THEN "mch2" (MP_TAC o SPECL [`u:A`;`w2:A`]) THEN
        ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                        DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
        CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) w2 ci` (LABEL_TAC "w2ci") THENL
       [USE_THEN "bm2" (MP_TAC o SPECL [`u:A`;`w2:A`] o CONJUNCT1 o CONJUNCT2 o
                        REWRITE_RULE[ebij]) THEN
        ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                        DISCH_THEN(ACCEPT_TAC o CONJUNCT2)];
        ALL_TAC] THEN
      EXISTS_TAC `w2:A` THEN
      CONJ_TAC THENL [USE_THEN "w2D" ACCEPT_TAC; ALL_TAC] THEN
      CONJ_TAC THENL [USE_THEN "e2" ACCEPT_TAC; ALL_TAC] THEN
      USE_THEN "mch1" (MP_TAC o SPECL [`w2:A`;`w3:A`]) THEN
      ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
      CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
      DISCH_THEN(X_CHOOSE_THEN `w2:A` (CONJUNCTS_THEN2 (LABEL_TAC "w2D")
          (CONJUNCTS_THEN2 (LABEL_TAC "e2") (LABEL_TAC "e1")))) THEN
      CONJ_TAC THENL [USE_THEN "uci" ACCEPT_TAC; ALL_TAC] THEN
      EXISTS_TAC `w2:A` THEN
      CONJ_TAC THENL [USE_THEN "w2D" ACCEPT_TAC; ALL_TAC] THEN
      CONJ_TAC THENL
       [USE_THEN "mch2" (MP_TAC o SPECL [`u:A`;`w2:A`]) THEN
        ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
        DISCH_THEN(fun th -> USE_THEN "e2" (MP_TAC o EQ_MP th)) THEN
        DISCH_THEN(ACCEPT_TAC o CONJUNCT2);
        USE_THEN "mch1" (MP_TAC o SPECL [`w2:A`;`w3:A`]) THEN
        ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
        DISCH_THEN(fun th -> USE_THEN "e1" (MP_TAC o EQ_MP th)) THEN
        DISCH_THEN(ACCEPT_TAC o CONJUNCT2)]];
    ALL_TAC] THEN
  (* muP3 = muP1 o muP2 on P *)
  SUBGOAL_THEN
   `!p q3. p IN D /\ q3 IN D /\ (E:A->A->bool) p P
           ==> (eapply D E muP3 p q3 <=>
                ?q2. q2 IN D /\ eapply D E muP2 p q2 /\ eapply D E muP1 q2 q3)`
   (LABEL_TAC "pcomp") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`ci:A`;`P:A`;`muci1:A`;
                  `muci2:A`;`muci3:A`;
                  `muP1:A`;`muP2:A`;`muP3:A`] LIFT_COMP) THEN
    ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    X_GEN_TAC `p:A` THEN DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "pD")
        (LABEL_TAC "pP")) THEN
    USE_THEN "coh" (MP_TAC o SPEC `p:A` o CONJUNCT2 o
                    REWRITE_RULE[ecohenp]) THEN
    ANTS_TAC THENL [USE_THEN "pD" ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "pP" (MP_TAC o EQ_MP th)) THEN
    DISCH_THEN(ACCEPT_TAC o CONJUNCT1);
    ALL_TAC] THEN
  (* autB3 = autB1 o autB2 on B *)
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`P:A`;`B:A`;`muP1:A`;
                `muP2:A`;`muP3:A`;
                `autB1:A`;`autB2:A`;`autB3:A`] LIFT_COMP) THEN
  ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
  REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
  X_GEN_TAC `b:A` THEN DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "bD")
      (LABEL_TAC "bB")) THEN
  USE_THEN "ros" (MP_TAC o SPEC `b:A` o CONJUNCT2 o REWRITE_RULE[eroset]) THEN
  ANTS_TAC THENL [USE_THEN "bD" ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> USE_THEN "bB" (MP_TAC o EQ_MP th)) THEN
  DISCH_THEN(ACCEPT_TAC o CONJUNCT1));;

let AUTN_COMP_PERM = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X
     s1 s2 s3 muci1 muP1 autB1 muci2 muP2 autB2 muci3 muP3 autB3 x v w.
     hsbundle D E w1 om tw ii ci P leqp B inclB onebee X /\
     pbundle D E ci P leqp B inclB s1 muci1 muP1 autB1 /\
     pbundle D E ci P leqp B inclB s2 muci2 muP2 autB2 /\
     pbundle D E ci P leqp B inclB s3 muci3 muP3 autB3 /\
     (!x z. x IN D /\ z IN D
            ==> (eapply D E s3 x z <=>
                 ?y. y IN D /\ eapply D E s2 x y /\ eapply D E s1 y z)) /\
     x IN D /\ bname D E B x /\
     eautn D E B autB2 x v /\ eautn D E B autB1 v w
     ==> eautn D E B autB3 x w`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "hsb")
             (CONJUNCTS_THEN2 (LABEL_TAC "pb1")
              (CONJUNCTS_THEN2 (LABEL_TAC "pb2")
               (CONJUNCTS_THEN2 (LABEL_TAC "pb3")
                (CONJUNCTS_THEN2 (LABEL_TAC "scomp")
                 (CONJUNCTS_THEN2 (LABEL_TAC "xD")
                  (CONJUNCTS_THEN2 (LABEL_TAC "bnx")
                   (CONJUNCTS_THEN2 (LABEL_TAC "e2x")
                    (LABEL_TAC "e1v"))))))))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;
                `ii:A`;`ci:A`;`P:A`;
                `leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`s1:A`;`s2:A`;`s3:A`;
                `muci1:A`;`muP1:A`;`autB1:A`;`muci2:A`;`muP2:A`;`autB2:A`;
                `muci3:A`;`muP3:A`;`autB3:A`] PBUNDLE_COMP) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(LABEL_TAC "bcomp") THEN
  SUBGOAL_THEN `model D (E:A->A->bool) ZF_AX /\ (B:A) IN D`
   (CONJUNCTS_THEN2 (LABEL_TAC "modl") (LABEL_TAC "BD")) THENL
   [USE_THEN "hsb" (MP_TAC o REWRITE_RULE[hsbundle]) THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]);
    ALL_TAC] THEN
  USE_THEN "pb1" (MP_TAC o REWRITE_RULE[pbundle]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "m1D")
             (CONJUNCTS_THEN2 (LABEL_TAC "mP1D")
              (CONJUNCTS_THEN2 (LABEL_TAC "a1D")
               (CONJUNCTS_THEN2 (LABEL_TAC "bm1")
                (CONJUNCTS_THEN2 (LABEL_TAC "bP1")
                 (CONJUNCTS_THEN2 (LABEL_TAC "bA1")
                  (CONJUNCTS_THEN2 (LABEL_TAC "mch1")
                   (CONJUNCTS_THEN2 (LABEL_TAC "Pch1")
                    (CONJUNCTS_THEN2 (LABEL_TAC "ach1")
                     (CONJUNCTS_THEN2 (LABEL_TAC "oP1")
                      (LABEL_TAC "oB1"))))))))))) THEN
  USE_THEN "pb2" (MP_TAC o REWRITE_RULE[pbundle]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "m2D")
             (CONJUNCTS_THEN2 (LABEL_TAC "mP2D")
              (CONJUNCTS_THEN2 (LABEL_TAC "a2D")
               (CONJUNCTS_THEN2 (LABEL_TAC "bm2")
                (CONJUNCTS_THEN2 (LABEL_TAC "bP2")
                 (CONJUNCTS_THEN2 (LABEL_TAC "bA2")
                  (CONJUNCTS_THEN2 (LABEL_TAC "mch2")
                   (CONJUNCTS_THEN2 (LABEL_TAC "Pch2")
                    (CONJUNCTS_THEN2 (LABEL_TAC "ach2")
                     (CONJUNCTS_THEN2 (LABEL_TAC "oP2")
                      (LABEL_TAC "oB2"))))))))))) THEN
  USE_THEN "pb3" (MP_TAC o REWRITE_RULE[pbundle]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "m3D")
             (CONJUNCTS_THEN2 (LABEL_TAC "mP3D")
              (CONJUNCTS_THEN2 (LABEL_TAC "a3D")
               (CONJUNCTS_THEN2 (LABEL_TAC "bm3")
                (CONJUNCTS_THEN2 (LABEL_TAC "bP3")
                 (CONJUNCTS_THEN2 (LABEL_TAC "bA3")
                  (CONJUNCTS_THEN2 (LABEL_TAC "mch3")
                   (CONJUNCTS_THEN2 (LABEL_TAC "Pch3")
                    (CONJUNCTS_THEN2 (LABEL_TAC "ach3")
                     (CONJUNCTS_THEN2 (LABEL_TAC "oP3")
                      (LABEL_TAC "oB3"))))))))))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB1:A`;`autB2:A`;`autB3:A`;
                `x:A`;`v:A`;`w:A`] AUTN_GCOMP) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                  DISCH_THEN ACCEPT_TAC]);;

(* ===================================================================== *)
(* H2c : the autN-image of a symmetric name is symmetric (conjugation).     *)
(* For s IN Sym(w1) and nm with countable support e, autN_s(nm) has support *)
(* s[e]: for t fixing s[e], t' = s^-1 o t o s fixes e, t o s = s o t', and   *)
(* AUTN_COMP_PERM along both factorizations of c = t o s gives               *)
(* autN_t(autN_s nm) = autN_c(nm) = autN_s(autN_t' nm) = autN_s(nm).         *)
(* ===================================================================== *)
let ECOMPF_EBIJ = prove
 (`!D (E:A->A->bool) f g x y z.
     model D E ZF_AX /\ x IN D /\ ebij D E f x y /\ ebij D E g y z
     ==> ?h. h IN D /\ ebij D E h x z /\
             (!k s. k IN D /\ s IN D
                    ==> (eapply D E h k s <=>
                         E k x /\ ?t. t IN D /\ eapply D E f k t /\
                                      eapply D E g t s))`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC))) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `f:A`; `g:A`;
                `x:A`; `y:A`; `z:A`] ECOMPF_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `h:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "ch"))) THEN
  UNDISCH_TAC `ebij D (E:A->A->bool) g y z` THEN
  REWRITE_TAC[ebij] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2
    (LABEL_TAC "gb") (CONJUNCTS_THEN2 (LABEL_TAC "gt")
      (CONJUNCTS_THEN2 (LABEL_TAC "gs") (CONJUNCTS_THEN2
        (LABEL_TAC "gi") (LABEL_TAC "go")))))) THEN
  UNDISCH_TAC `ebij D (E:A->A->bool) f x y` THEN
  REWRITE_TAC[ebij] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2
    (LABEL_TAC "fb") (CONJUNCTS_THEN2 (LABEL_TAC "ft")
      (CONJUNCTS_THEN2 (LABEL_TAC "fs") (CONJUNCTS_THEN2
        (LABEL_TAC "fi") (LABEL_TAC "fo")))))) THEN
  EXISTS_TAC `h:A` THEN ASM_REWRITE_TAC[] THEN
  REPEAT CONJ_TAC THENL
   [MAP_EVERY X_GEN_TAC [`k:A`; `s:A`] THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
      MP_TAC)) THEN
    USE_THEN "ch" (MP_TAC o SPECL [`k:A`; `s:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
