      (CONJUNCTS_THEN2 ASSUME_TAC (X_CHOOSE_THEN `t:A`
        (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
          ASSUME_TAC))))
      (CONJUNCTS_THEN2 ASSUME_TAC (X_CHOOSE_THEN `t':A`
