let PERM_COMP_EXISTS = prove
 (`!D (E:A->A->bool) w1 s1 s2.
     model D E ZF_AX /\ w1 IN D /\ eperm D E w1 s1 /\ eperm D E w1 s2
     ==> ?s3. s3 IN D /\ eperm D E w1 s3 /\
              (!x z. x IN D /\ z IN D
                     ==> (eapply D E s3 x z <=>
                          ?y. y IN D /\ eapply D E s2 x y /\
                              eapply D E s1 y z))`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
             (CONJUNCTS_THEN2 (LABEL_TAC "w1D")
              (CONJUNCTS_THEN2 (LABEL_TAC "p1") (LABEL_TAC "p2")))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`s2:A`;`s1:A`;`w1:A`;`w1:A`;`w1:A`]
    ECOMPF_EBIJ) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    FIRST_ASSUM(ACCEPT_TAC o REWRITE_RULE[eperm]);
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `h:A` (CONJUNCTS_THEN2 (LABEL_TAC "hD")
      (CONJUNCTS_THEN2 (LABEL_TAC "hbij") (LABEL_TAC "hch")))) THEN
  EXISTS_TAC `h:A` THEN
  CONJ_TAC THENL [USE_THEN "hD" ACCEPT_TAC; ALL_TAC] THEN
  CONJ_TAC THENL [REWRITE_TAC[eperm] THEN
                  USE_THEN "hbij" ACCEPT_TAC; ALL_TAC] THEN
  MAP_EVERY X_GEN_TAC [`x:A`;`z:A`] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "xD") (LABEL_TAC "zD")) THEN
  USE_THEN "hch" (MP_TAC o SPECL [`x:A`;`z:A`]) THEN
  ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                  DISCH_THEN SUBST1_TAC] THEN
  EQ_TAC THENL
   [DISCH_THEN(ACCEPT_TAC o CONJUNCT2);
    DISCH_TAC THEN CONJ_TAC THENL [ALL_TAC; FIRST_ASSUM ACCEPT_TAC] THEN
    FIRST_X_ASSUM(X_CHOOSE_THEN `y:A` STRIP_ASSUME_TAC) THEN
    USE_THEN "p2" (MP_TAC o SPECL [`x:A`;`y:A`] o CONJUNCT1 o CONJUNCT2 o
                   REWRITE_RULE[ebij] o REWRITE_RULE[eperm]) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN(ACCEPT_TAC o CONJUNCT1)]]);;

let CSUPPORT_TO_OM = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X e.
     hsbundle D E w1 om tw ii ci P leqp B inclB onebee X /\
     e IN D /\ (?n. n IN D /\ E n w1 /\ ?f. ebij D E f n e)
     ==> ?k. einj D E k e om`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "hsb")
             (CONJUNCTS_THEN2 (LABEL_TAC "eD")
              (X_CHOOSE_THEN `n:A` (CONJUNCTS_THEN2 (LABEL_TAC "nD")
      (CONJUNCTS_THEN2 (LABEL_TAC "nw") (X_CHOOSE_THEN `f:A`
      (LABEL_TAC "bf"))))))) THEN
  USE_THEN "hsb" (MP_TAC o MATCH_MP HSB_FACTS) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "omD")
             (CONJUNCTS_THEN2 (K ALL_TAC) (CONJUNCTS_THEN2 (K ALL_TAC)
      (CONJUNCTS_THEN2 (K ALL_TAC) (CONJUNCTS_THEN2 (K ALL_TAC)
      (LABEL_TAC "omw1")))))) THEN
  USE_THEN "hsb" (MP_TAC o REWRITE_RULE[hsbundle]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
             (CONJUNCTS_THEN2 (LABEL_TAC "vl")
              (CONJUNCTS_THEN2 (LABEL_TAC "eom")
               (CONJUNCTS_THEN2 (LABEL_TAC "w1D")
                (CONJUNCTS_THEN2 (LABEL_TAC "w1card")
                 (CONJUNCTS_THEN2 (LABEL_TAC "omw1e")
                  (CONJUNCTS_THEN2 (LABEL_TAC "w1min")
                   (CONJUNCTS_THEN2 (LABEL_TAC "cr1")
                    (CONJUNCTS_THEN2 (LABEL_TAC "cr2")
                     (CONJUNCTS_THEN2 (LABEL_TAC "ftw")
                      (CONJUNCTS_THEN2 (LABEL_TAC "coh")
                       (CONJUNCTS_THEN2 (LABEL_TAC "leq")
                        (CONJUNCTS_THEN2 (LABEL_TAC "ros")
                         (CONJUNCTS_THEN2 (LABEL_TAC "inc")
                          (CONJUNCTS_THEN2 (LABEL_TAC "porder")
      (CONJUNCTS_THEN2 (LABEL_TAC "top")
       (CONJUNCTS_THEN2 (LABEL_TAC "oneD")
        (CONJUNCTS_THEN2 (LABEL_TAC "BD")
         (CONJUNCTS_THEN2 (LABEL_TAC "oneB")
          (CONJUNCTS_THEN2 (LABEL_TAC "XD")
           (CONJUNCTS_THEN2 (LABEL_TAC "ciX")
            (LABEL_TAC "PX")))))))))))))))))))))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`f:A`;`n:A`;`e:A`]
         EBIJ_INV_CHAR) THEN
  ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `g:A` (CONJUNCTS_THEN2 (K ALL_TAC)
    (CONJUNCTS_THEN2 (LABEL_TAC "bg") (K ALL_TAC)))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`om:A`;`w1:A`;`n:A`]
    ECOUNTABLE_BELOW_A1) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `hn:A` (LABEL_TAC "ihn")) THEN
  SUBGOAL_THEN `(n:A) IN D` (LABEL_TAC "nD'") THENL
      [USE_THEN "nD" ACCEPT_TAC; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`g:A`;`hn:A`;`e:A`;`n:A`;`om:A`]
    EINJ_COMPOSE) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    USE_THEN "bg" (ACCEPT_TAC o MATCH_MP EBIJ_EINJ);
    DISCH_THEN ACCEPT_TAC]);;

let CSUPPORT_OF_INJ = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X e k.
     hsbundle D E w1 om tw ii ci P leqp B inclB onebee X /\
     e IN D /\ einj D E k e om
     ==> (?n. n IN D /\ E n w1 /\ ?f. ebij D E f n e)`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "hsb")
             (CONJUNCTS_THEN2 (LABEL_TAC "eD") (LABEL_TAC "ike"))) THEN
  USE_THEN "hsb" (MP_TAC o MATCH_MP HSB_FACTS) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "omD")
             (CONJUNCTS_THEN2 (K ALL_TAC) (CONJUNCTS_THEN2 (K ALL_TAC)
      (CONJUNCTS_THEN2 (K ALL_TAC) (CONJUNCTS_THEN2 (K ALL_TAC)
      (LABEL_TAC "omw1")))))) THEN
  USE_THEN "hsb" (MP_TAC o REWRITE_RULE[hsbundle]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
             (CONJUNCTS_THEN2 (LABEL_TAC "vl")
              (CONJUNCTS_THEN2 (LABEL_TAC "eom")
               (CONJUNCTS_THEN2 (LABEL_TAC "w1D")
                (CONJUNCTS_THEN2 (LABEL_TAC "w1card")
                 (CONJUNCTS_THEN2 (LABEL_TAC "omw1e")
                  (CONJUNCTS_THEN2 (LABEL_TAC "w1min")
                   (CONJUNCTS_THEN2 (LABEL_TAC "cr1")
                    (CONJUNCTS_THEN2 (LABEL_TAC "cr2")
                     (CONJUNCTS_THEN2 (LABEL_TAC "ftw")
                      (CONJUNCTS_THEN2 (LABEL_TAC "coh")
                       (CONJUNCTS_THEN2 (LABEL_TAC "leq")
                        (CONJUNCTS_THEN2 (LABEL_TAC "ros")
                         (CONJUNCTS_THEN2 (LABEL_TAC "inc")
                          (CONJUNCTS_THEN2 (LABEL_TAC "porder")
      (CONJUNCTS_THEN2 (LABEL_TAC "top")
       (CONJUNCTS_THEN2 (LABEL_TAC "oneD")
        (CONJUNCTS_THEN2 (LABEL_TAC "BD")
         (CONJUNCTS_THEN2 (LABEL_TAC "oneB")
          (CONJUNCTS_THEN2 (LABEL_TAC "XD")
           (CONJUNCTS_THEN2 (LABEL_TAC "ciX")
            (LABEL_TAC "PX")))))))))))))))))))))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`e:A`] ECARDOF_EXISTS) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `cx:A` (LABEL_TAC "cxof")) THEN
  SUBGOAL_THEN `(cx:A) IN D /\ ?f. ebij D (E:A->A->bool) f cx e`
   (CONJUNCTS_THEN2 (LABEL_TAC "cxD") (LABEL_TAC "cxbij")) THENL
   [USE_THEN "cxof" (MP_TAC o REWRITE_RULE[ecardof]) THEN
    MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) cx w1` (LABEL_TAC "cxw1") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`k:A`;`e:A`;`om:A`;`cx:A`]
      EINJ_ORDINAL_CARD_LE) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      MATCH_MP_TAC EOMEGA_ORDINAL THEN CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
      ALL_TAC] THEN
    DISCH_THEN(DISJ_CASES_THEN ASSUME_TAC) THENL
     [USE_THEN "omw1" (MP_TAC o SPEC `cx:A`) THEN
      ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN ACCEPT_TAC];
      FIRST_X_ASSUM(SUBST1_TAC o check (is_eq o concl)) THEN
      USE_THEN "omw1e" ACCEPT_TAC];
    ALL_TAC] THEN
  EXISTS_TAC `cx:A` THEN REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC);;

let PERM_IMAGE = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X s e.
     hsbundle D E w1 om tw ii ci P leqp B inclB onebee X /\
     s IN D /\ eperm D E w1 s /\
     e IN D /\ (?n. n IN D /\ E n w1 /\ ?f. ebij D E f n e) /\ esubset D E e w1
     ==> ?img. img IN D /\
               (!z. z IN D
                    ==> (E z img <=> ?y. y IN D /\ E y e /\
                         eapply D E s y z)) /\
               (?n. n IN D /\ E n w1 /\ ?f. ebij D E f n img) /\
               esubset D E img w1`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "hsb")
             (CONJUNCTS_THEN2 (LABEL_TAC "sD")
              (CONJUNCTS_THEN2 (LABEL_TAC "sperm")
               (CONJUNCTS_THEN2 (LABEL_TAC "eD")
                (CONJUNCTS_THEN2 (LABEL_TAC "ecs") (LABEL_TAC "esub")))))) THEN
  USE_THEN "hsb" (MP_TAC o REWRITE_RULE[hsbundle]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
             (CONJUNCTS_THEN2 (LABEL_TAC "vl")
              (CONJUNCTS_THEN2 (LABEL_TAC "eom")
               (CONJUNCTS_THEN2 (LABEL_TAC "w1D")
                (CONJUNCTS_THEN2 (LABEL_TAC "w1card")
                 (CONJUNCTS_THEN2 (LABEL_TAC "omw1e")
                  (CONJUNCTS_THEN2 (LABEL_TAC "w1min")
                   (CONJUNCTS_THEN2 (LABEL_TAC "cr1")
                    (CONJUNCTS_THEN2 (LABEL_TAC "cr2")
                     (CONJUNCTS_THEN2 (LABEL_TAC "ftw")
                      (CONJUNCTS_THEN2 (LABEL_TAC "coh")
                       (CONJUNCTS_THEN2 (LABEL_TAC "leq")
                        (CONJUNCTS_THEN2 (LABEL_TAC "ros")
                         (CONJUNCTS_THEN2 (LABEL_TAC "inc")
                          (CONJUNCTS_THEN2 (LABEL_TAC "porder")
      (CONJUNCTS_THEN2 (LABEL_TAC "top")
       (CONJUNCTS_THEN2 (LABEL_TAC "oneD")
        (CONJUNCTS_THEN2 (LABEL_TAC "BD")
         (CONJUNCTS_THEN2 (LABEL_TAC "oneB")
          (CONJUNCTS_THEN2 (LABEL_TAC "XD")
           (CONJUNCTS_THEN2 (LABEL_TAC "ciX")
            (LABEL_TAC "PX")))))))))))))))))))))) THEN
  SUBGOAL_THEN `ebij D (E:A->A->bool) s w1 w1` (LABEL_TAC "sbij") THENL
   [USE_THEN "sperm" (ACCEPT_TAC o REWRITE_RULE[eperm]); ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`e:A`;`s:A`]
         EIMGSET_EXISTS) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `img:A` (CONJUNCTS_THEN2 (LABEL_TAC "imgD")
      (LABEL_TAC "imgch0"))) THEN
  SUBGOAL_THEN
   `!z:A. z IN D ==> ((E:A->A->bool) z img <=> ?y. y IN D /\ E y e /\
                      eapply D E s y z)`
   (LABEL_TAC "imgch") THENL
   [X_GEN_TAC `z:A` THEN DISCH_THEN(LABEL_TAC "zD") THEN
    USE_THEN "imgch0" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [USE_THEN "zD" ACCEPT_TAC; DISCH_THEN SUBST1_TAC] THEN
    EQ_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `y:A` STRIP_ASSUME_TAC) THEN
      EXISTS_TAC `y:A` THEN ASM_REWRITE_TAC[];
      DISCH_THEN(X_CHOOSE_THEN `y:A` STRIP_ASSUME_TAC) THEN
      EXISTS_TAC `y:A` THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "esub" (MP_TAC o SPEC `y:A` o REWRITE_RULE[esubset]) THEN
      ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN ACCEPT_TAC]];
    ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) img w1` (LABEL_TAC "imgsub") THENL
   [REWRITE_TAC[esubset] THEN X_GEN_TAC `z:A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "zD") (LABEL_TAC "zimg")) THEN
    USE_THEN "imgch" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [USE_THEN "zD" ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "zimg" (MP_TAC o EQ_MP th)) THEN
    DISCH_THEN(X_CHOOSE_THEN `y:A` (CONJUNCTS_THEN2 (LABEL_TAC "yD")
        (CONJUNCTS_THEN2 (LABEL_TAC "ye") (LABEL_TAC "syz")))) THEN
    USE_THEN "sbij" (MP_TAC o SPECL [`y:A`;`z:A`] o CONJUNCT1 o CONJUNCT2 o
                     REWRITE_RULE[ebij]) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN(ACCEPT_TAC o CONJUNCT2)];
    ALL_TAC] THEN
  (* countability: img injects into e (via s^-1), e into om *)
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`s:A`;`w1:A`;`w1:A`]
         EBIJ_INV_CHAR) THEN
  ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `si:A` (CONJUNCTS_THEN2 (LABEL_TAC "siD")
      (CONJUNCTS_THEN2 (LABEL_TAC "sibij") (LABEL_TAC "sich")))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`si:A`;`w1:A`;`w1:A`;`img:A`;`e:A`]
    EINJ_RESTRICT_DOM) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THENL
     [USE_THEN "sibij" (ACCEPT_TAC o MATCH_MP EBIJ_EINJ);
      X_GEN_TAC `k:A` THEN DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "kD")
          (LABEL_TAC "kimg")) THEN
      USE_THEN "imgsub" (MP_TAC o SPEC `k:A` o REWRITE_RULE[esubset]) THEN
      ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN ACCEPT_TAC];
      MAP_EVERY X_GEN_TAC [`k:A`;`t:A`] THEN
      DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "kD")
                 (CONJUNCTS_THEN2 (LABEL_TAC "tD")
                  (CONJUNCTS_THEN2 (LABEL_TAC "kimg") (LABEL_TAC "sikt")))) THEN
      USE_THEN "imgch" (MP_TAC o SPEC `k:A`) THEN
      ANTS_TAC THENL [USE_THEN "kD" ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> USE_THEN "kimg" (MP_TAC o EQ_MP th)) THEN
      DISCH_THEN(X_CHOOSE_THEN `y:A` (CONJUNCTS_THEN2 (LABEL_TAC "yD")
          (CONJUNCTS_THEN2 (LABEL_TAC "ye") (LABEL_TAC "syk")))) THEN
      SUBGOAL_THEN `eapply D (E:A->A->bool) s t k` (LABEL_TAC "stk") THENL
       [USE_THEN "sich" (MP_TAC o SPECL [`t:A`;`k:A`]) THEN
        ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
        DISCH_THEN(fun th -> USE_THEN "sikt" (ACCEPT_TAC o EQ_MP th));
        ALL_TAC] THEN
      SUBGOAL_THEN `(t:A) = y` SUBST1_TAC THENL
       [USE_THEN "sbij" (MP_TAC o SPECL [`t:A`;`y:A`;`k:A`] o CONJUNCT1 o
                         CONJUNCT2 o CONJUNCT2 o CONJUNCT2 o CONJUNCT2 o
           REWRITE_RULE[ebij]) THEN
        ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                        DISCH_THEN ACCEPT_TAC];
        USE_THEN "ye" ACCEPT_TAC]];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `h:A` (LABEL_TAC "ih")) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;
                `ii:A`;`ci:A`;`P:A`;
                `leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`e:A`]
                    CSUPPORT_TO_OM) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `k:A` (LABEL_TAC "ik")) THEN
  SUBGOAL_THEN `(om:A) IN D` (LABEL_TAC "omD") THENL
   [USE_THEN "eom" (ACCEPT_TAC o MATCH_MP EOMEGA_IN); ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`h:A`;`k:A`;`img:A`;`e:A`;`om:A`]
         EINJ_COMPOSE) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `hk:A` (LABEL_TAC "ihk")) THEN
  EXISTS_TAC `img:A` THEN
  CONJ_TAC THENL [USE_THEN "imgD" ACCEPT_TAC; ALL_TAC] THEN
  CONJ_TAC THENL [USE_THEN "imgch" ACCEPT_TAC; ALL_TAC] THEN
  CONJ_TAC THENL [ALL_TAC; USE_THEN "imgsub" ACCEPT_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;
                `ii:A`;`ci:A`;`P:A`;
                `leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`img:A`;`hk:A`]
                    CSUPPORT_OF_INJ) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                  DISCH_THEN ACCEPT_TAC]);;

let EHSSYM_AUTN = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X s muci
  muP autB nm nm'.
     hsbundle D E w1 om tw ii ci P leqp B inclB onebee X /\
     nm IN D /\ bname D E B nm /\ ehssym D E B w1 X nm /\
     s IN D /\ eperm D E w1 s /\
     pbundle D E ci P leqp B inclB s muci muP autB /\
     eautn D E B autB nm nm'
     ==> ehssym D E B w1 X nm'`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "hsb")
             (CONJUNCTS_THEN2 (LABEL_TAC "nmD")
              (CONJUNCTS_THEN2 (LABEL_TAC "bnm")
               (CONJUNCTS_THEN2 (LABEL_TAC "sym")
                (CONJUNCTS_THEN2 (LABEL_TAC "sD")
                 (CONJUNCTS_THEN2 (LABEL_TAC "sperm")
                  (CONJUNCTS_THEN2 (LABEL_TAC "pbs")
                   (LABEL_TAC "aut")))))))) THEN
  USE_THEN "hsb" (MP_TAC o REWRITE_RULE[hsbundle]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
             (CONJUNCTS_THEN2 (LABEL_TAC "vl")
              (CONJUNCTS_THEN2 (LABEL_TAC "eom")
               (CONJUNCTS_THEN2 (LABEL_TAC "w1D")
                (CONJUNCTS_THEN2 (LABEL_TAC "w1card")
                 (CONJUNCTS_THEN2 (LABEL_TAC "omw1e")
                  (CONJUNCTS_THEN2 (LABEL_TAC "w1min")
                   (CONJUNCTS_THEN2 (LABEL_TAC "cr1")
                    (CONJUNCTS_THEN2 (LABEL_TAC "cr2")
                     (CONJUNCTS_THEN2 (LABEL_TAC "ftw")
                      (CONJUNCTS_THEN2 (LABEL_TAC "coh")
                       (CONJUNCTS_THEN2 (LABEL_TAC "leq")
                        (CONJUNCTS_THEN2 (LABEL_TAC "ros")
                         (CONJUNCTS_THEN2 (LABEL_TAC "inc")
                          (CONJUNCTS_THEN2 (LABEL_TAC "porder")
      (CONJUNCTS_THEN2 (LABEL_TAC "top")
       (CONJUNCTS_THEN2 (LABEL_TAC "oneD")
        (CONJUNCTS_THEN2 (LABEL_TAC "BD")
         (CONJUNCTS_THEN2 (LABEL_TAC "oneB")
          (CONJUNCTS_THEN2 (LABEL_TAC "XD")
           (CONJUNCTS_THEN2 (LABEL_TAC "ciX")
            (LABEL_TAC "PX")))))))))))))))))))))) THEN
  USE_THEN "pbs" (MP_TAC o REWRITE_RULE[pbundle]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "msD")
             (CONJUNCTS_THEN2 (LABEL_TAC "mPsD")
              (CONJUNCTS_THEN2 (LABEL_TAC "aBsD")
               (CONJUNCTS_THEN2 (LABEL_TAC "bms")
                (CONJUNCTS_THEN2 (LABEL_TAC "bPs")
                 (CONJUNCTS_THEN2 (LABEL_TAC "bAs")
                  (CONJUNCTS_THEN2 (LABEL_TAC "mchs")
                   (CONJUNCTS_THEN2 (LABEL_TAC "Pchs")
                    (CONJUNCTS_THEN2 (LABEL_TAC "achs")
                     (CONJUNCTS_THEN2 (LABEL_TAC "oPs")
                      (LABEL_TAC "oBs"))))))))))) THEN
  SUBGOAL_THEN `(nm':A) IN D` (LABEL_TAC "nm'D") THENL
   [USE_THEN "aut" (ACCEPT_TAC o CONJUNCT2 o MATCH_MP AUTN_IMP); ALL_TAC] THEN
  SUBGOAL_THEN `ebij D (E:A->A->bool) s w1 w1` (LABEL_TAC "sbij") THENL
   [USE_THEN "sperm" (ACCEPT_TAC o REWRITE_RULE[eperm]); ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B nm'` (LABEL_TAC "bnm'") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`nm:A`;`nm':A`]
      EAUTN_IS_BNAME) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  (* support e of nm, its image under s *)
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;
                `ii:A`;`ci:A`;`P:A`;
                `leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`nm:A`]
                    EHSSYM_ELIM_ALL) THEN
  ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `e:A` (CONJUNCTS_THEN2 (LABEL_TAC "eD")
      (CONJUNCTS_THEN2 (LABEL_TAC "ecs")
       (CONJUNCTS_THEN2 (LABEL_TAC "esub") (LABEL_TAC "fixall"))))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;
                `ii:A`;`ci:A`;`P:A`;
                `leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`s:A`;`e:A`]
                    PERM_IMAGE) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `img:A` (CONJUNCTS_THEN2 (LABEL_TAC "imgD")
      (CONJUNCTS_THEN2 (LABEL_TAC "imgch")
       (CONJUNCTS_THEN2 (LABEL_TAC "imgcs") (LABEL_TAC "imgsub"))))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`s:A`;`w1:A`;`w1:A`]
         EBIJ_INV_CHAR) THEN
  ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `si:A` (CONJUNCTS_THEN2 (LABEL_TAC "siD")
      (CONJUNCTS_THEN2 (LABEL_TAC "sibij") (LABEL_TAC "sich")))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;
                `ii:A`;`ci:A`;`P:A`;
                `leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`nm':A`;`img:A`]
                    EHSSYM_INTRO) THEN
  ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
  REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
  X_GEN_TAC `t:A` THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "tD")
             (CONJUNCTS_THEN2 (LABEL_TAC "tperm") (LABEL_TAC "tfix"))) THEN
  MAP_EVERY X_GEN_TAC [`mt:A`;`mPt:A`;`aBt:A`] THEN
  DISCH_THEN(LABEL_TAC "pbt0") THEN
  SUBGOAL_THEN `pbundle D (E:A->A->bool) ci P leqp B inclB t mt mPt aBt`
      (LABEL_TAC "pbt") THENL
   [REWRITE_TAC[pbundle] THEN USE_THEN "pbt0" ACCEPT_TAC; ALL_TAC] THEN
  USE_THEN "pbt0" ((CONJUNCTS_THEN2 (LABEL_TAC "mtD")
                    (CONJUNCTS_THEN2 (LABEL_TAC "mPtD")
                     (CONJUNCTS_THEN2 (LABEL_TAC "aBtD")
                      (CONJUNCTS_THEN2 (LABEL_TAC "bmt")
                       (CONJUNCTS_THEN2 (LABEL_TAC "bPt")
                        (CONJUNCTS_THEN2 (LABEL_TAC "bAt")
                         (CONJUNCTS_THEN2 (LABEL_TAC "mcht")
                          (CONJUNCTS_THEN2 (LABEL_TAC "Pcht")
      (CONJUNCTS_THEN2 (LABEL_TAC "acht")
       (CONJUNCTS_THEN2 (LABEL_TAC "oPt") (LABEL_TAC "oBt")))))))))))) THEN
  (* c = t o s ; t' = si o c *)
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`t:A`;`s:A`]
         PERM_COMP_EXISTS) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `c:A` (CONJUNCTS_THEN2 (LABEL_TAC "cD")
      (CONJUNCTS_THEN2 (LABEL_TAC "cperm") (LABEL_TAC "cch")))) THEN
  SUBGOAL_THEN `eperm D (E:A->A->bool) w1 si` (LABEL_TAC "siperm") THENL
   [REWRITE_TAC[eperm] THEN USE_THEN "sibij" ACCEPT_TAC; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`si:A`;`c:A`]
         PERM_COMP_EXISTS) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `t':A` (CONJUNCTS_THEN2 (LABEL_TAC "t'D")
      (CONJUNCTS_THEN2 (LABEL_TAC "t'perm") (LABEL_TAC "t'ch")))) THEN
  (* t' fixes e *)
  SUBGOAL_THEN `efixes D (E:A->A->bool) t' e` (LABEL_TAC "t'fix") THENL
   [REWRITE_TAC[efixes] THEN X_GEN_TAC `al:A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "alD") (LABEL_TAC "ale")) THEN
    SUBGOAL_THEN `(E:A->A->bool) al w1` (LABEL_TAC "alw1") THENL
     [USE_THEN "esub" (MP_TAC o SPEC `al:A` o REWRITE_RULE[esubset]) THEN
      ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    USE_THEN "sbij" (MP_TAC o SPEC `al:A` o CONJUNCT1 o CONJUNCT2 o CONJUNCT2 o
                     REWRITE_RULE[ebij]) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `be:A` (CONJUNCTS_THEN2 (LABEL_TAC "beD")
        (CONJUNCTS_THEN2 (LABEL_TAC "bew1") (LABEL_TAC "sbe")))) THEN
    SUBGOAL_THEN `eapply D (E:A->A->bool) t be be` (LABEL_TAC "tbe") THENL
     [USE_THEN "tfix" (MP_TAC o SPEC `be:A` o REWRITE_RULE[efixes]) THEN
      ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
      CONJ_TAC THENL [USE_THEN "beD" ACCEPT_TAC; ALL_TAC] THEN
      USE_THEN "imgch" (MP_TAC o SPEC `be:A`) THEN
      ANTS_TAC THENL [USE_THEN "beD" ACCEPT_TAC;
                      DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
      EXISTS_TAC `al:A` THEN REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
      ALL_TAC] THEN
    USE_THEN "t'ch" (MP_TAC o SPECL [`al:A`;`al:A`]) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
    EXISTS_TAC `be:A` THEN
    CONJ_TAC THENL [USE_THEN "beD" ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL
     [USE_THEN "cch" (MP_TAC o SPECL [`al:A`;`be:A`]) THEN
      ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
      EXISTS_TAC `be:A` THEN REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
      USE_THEN "sich" (MP_TAC o SPECL [`al:A`;`be:A`]) THEN
      ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
      USE_THEN "sbe" ACCEPT_TAC];
    ALL_TAC] THEN
  (* c = s o t' as graphs *)
  SUBGOAL_THEN
   `!x z. x IN D /\ z IN D
          ==> (eapply D (E:A->A->bool) c x z <=>
               ?y. y IN D /\ eapply D E t' x y /\ eapply D E s y z)`
   (LABEL_TAC "cch2") THENL
   [MAP_EVERY X_GEN_TAC [`x:A`;`z:A`] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "xD") (LABEL_TAC "zD")) THEN
    EQ_TAC THENL
     [DISCH_THEN(LABEL_TAC "cxz") THEN
      SUBGOAL_THEN `(E:A->A->bool) z w1` (LABEL_TAC "zw1") THENL
       [USE_THEN "cperm" (MP_TAC o SPECL [`x:A`;`z:A`] o CONJUNCT1 o CONJUNCT2 o
                          REWRITE_RULE[ebij] o REWRITE_RULE[eperm]) THEN
        ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                        DISCH_THEN(ACCEPT_TAC o CONJUNCT2)];
        ALL_TAC] THEN
      USE_THEN "sibij" (MP_TAC o SPEC `z:A` o CONJUNCT1 o CONJUNCT2 o CONJUNCT2
                        o REWRITE_RULE[ebij]) THEN
      ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `y:A` (CONJUNCTS_THEN2 (LABEL_TAC "yD")
          (CONJUNCTS_THEN2 (LABEL_TAC "yw1") (LABEL_TAC "sizy")))) THEN
      EXISTS_TAC `y:A` THEN
      CONJ_TAC THENL [USE_THEN "yD" ACCEPT_TAC; ALL_TAC] THEN
      CONJ_TAC THENL
       [USE_THEN "t'ch" (MP_TAC o SPECL [`x:A`;`y:A`]) THEN
        ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                        DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
        EXISTS_TAC `z:A` THEN REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
        USE_THEN "sich" (MP_TAC o SPECL [`y:A`;`z:A`]) THEN
        ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
        DISCH_THEN(fun th -> USE_THEN "sizy" (ACCEPT_TAC o EQ_MP th))];
      DISCH_THEN(X_CHOOSE_THEN `y:A` (CONJUNCTS_THEN2 (LABEL_TAC "yD")
          (CONJUNCTS_THEN2 (LABEL_TAC "t'xy") (LABEL_TAC "syz")))) THEN
      USE_THEN "t'ch" (MP_TAC o SPECL [`x:A`;`y:A`]) THEN
      ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> USE_THEN "t'xy" (MP_TAC o EQ_MP th)) THEN
      DISCH_THEN(X_CHOOSE_THEN `y':A` (CONJUNCTS_THEN2 (LABEL_TAC "y'D")
          (CONJUNCTS_THEN2 (LABEL_TAC "cxy'") (LABEL_TAC "siy'y")))) THEN
      SUBGOAL_THEN `eapply D (E:A->A->bool) s y y'` (LABEL_TAC "syy'") THENL
       [USE_THEN "sich" (MP_TAC o SPECL [`y:A`;`y':A`]) THEN
        ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
        DISCH_THEN(fun th -> USE_THEN "siy'y" (ACCEPT_TAC o EQ_MP th));
        ALL_TAC] THEN
      SUBGOAL_THEN `(y':A) = z` (fun th -> USE_THEN "cxy'"
          (ACCEPT_TAC o REWRITE_RULE[th])) THEN
      USE_THEN "sbij" (MP_TAC o SPECL [`y:A`;`y':A`;`z:A`] o CONJUNCT1 o
                       CONJUNCT2 o CONJUNCT2 o CONJUNCT2 o
          REWRITE_RULE[ebij]) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN ACCEPT_TAC]];
    ALL_TAC] THEN
  (* bundles for c and t' *)
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;
                `ii:A`;`ci:A`;`P:A`;
                `leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`c:A`]
                    PBUNDLE_EXISTS) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `mc:A` (X_CHOOSE_THEN `mPc:A`
      (X_CHOOSE_THEN `aBc:A` (LABEL_TAC "pbc")))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;
                `ii:A`;`ci:A`;`P:A`;
                `leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`t':A`]
                    PBUNDLE_EXISTS) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `mt':A` (X_CHOOSE_THEN `mPt':A`
      (X_CHOOSE_THEN `aBt':A` (LABEL_TAC "pbt'")))) THEN
  USE_THEN "pbt'" ((CONJUNCTS_THEN2 (LABEL_TAC "mt'D")
                    (CONJUNCTS_THEN2 (LABEL_TAC "mPt'D")
                     (CONJUNCTS_THEN2 (LABEL_TAC "aBt'D")
                      (CONJUNCTS_THEN2 (LABEL_TAC "bmt'")
                       (CONJUNCTS_THEN2 (LABEL_TAC "bPt'")
                        (CONJUNCTS_THEN2 (LABEL_TAC "bAt'")
                         (CONJUNCTS_THEN2 (LABEL_TAC "mcht'")
                          (CONJUNCTS_THEN2 (LABEL_TAC "Pcht'")
      (CONJUNCTS_THEN2 (LABEL_TAC "acht'")
       (CONJUNCTS_THEN2 (LABEL_TAC "oPt'") (LABEL_TAC "oBt'"))))))))))) o
      REWRITE_RULE[pbundle]) THEN
  (* autN_t' fixes nm *)
  SUBGOAL_THEN `eautn D (E:A->A->bool) B aBt' nm nm` (LABEL_TAC "fixt'") THENL
   [USE_THEN "fixall" (MP_TAC o SPEC `t':A`) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPECL [`mt':A`;`mPt':A`;`aBt':A`]) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  (* route 1: c = s o t' : autN_c nm = nm' *)
  SUBGOAL_THEN `eautn D (E:A->A->bool) B aBc nm nm'` (LABEL_TAC "r1") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;
                  `ii:A`;`ci:A`;`P:A`;
                  `leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`s:A`;`t':A`;`c:A`;
                  `muci:A`;`muP:A`;`autB:A`;`mt':A`;`mPt':A`;`aBt':A`;
                  `mc:A`;`mPc:A`;`aBc:A`;`nm:A`;`nm:A`;`nm':A`]
                      AUTN_COMP_PERM) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  (* autN_t nm' = xn *)
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`aBt:A`;`nm':A`]
         AUTN_TOTAL) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `xn:A` (CONJUNCTS_THEN2 (LABEL_TAC "xnD")
      (LABEL_TAC "txn"))) THEN
  (* route 2: c = t o s : autN_c nm = xn *)
  SUBGOAL_THEN `eautn D (E:A->A->bool) B aBc nm xn` (LABEL_TAC "r2") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;
                  `ii:A`;`ci:A`;`P:A`;
                  `leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`t:A`;`s:A`;`c:A`;
                  `mt:A`;`mPt:A`;`aBt:A`;`muci:A`;`muP:A`;`autB:A`;
                  `mc:A`;`mPc:A`;`aBc:A`;`nm:A`;`nm':A`;`xn:A`]
                      AUTN_COMP_PERM) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `(xn:A) = nm'` (fun th -> USE_THEN "txn"
      (ACCEPT_TAC o REWRITE_RULE[th])) THEN
  USE_THEN "pbc" (MP_TAC o REWRITE_RULE[pbundle]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (CONJUNCTS_THEN2 (K ALL_TAC)
    (CONJUNCTS_THEN2 (LABEL_TAC "aBcD") (K ALL_TAC)))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`aBc:A`;`nm:A`;`xn:A`;
                `nm':A`] AUTN_SV) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                  DISCH_THEN ACCEPT_TAC]);;

(* ===================================================================== *)
(* H2d : AUTN_HS -- autN_s maps HS names to HS names (s IN Sym(w1)).         *)
(* Least-HS-rank counterexample: autn_bad_form reads the autN-tower stage cd *)
(* (slot 41) at a B-name rank lam bounding hsstage(rank+1); at the minimal   *)
(* counterexample z, every first coordinate of autN z is HS (minimality),   *)
(* HSNAME_BOUND bounds them, EHSSYM_AUTN gives symmetry, HSSTAGE_INTRO.      *)
(* ===================================================================== *)
let autn_bad_form = new_definition
  `autn_bad_form =
     ?? 50 (?? 51 (opair_form 0 50 51 && (51 %% 41) && Not (hsname_form 50)))`;;

let HOLDS_AUTN_BAD_FORM = prove
 (`!D (E:A->A->bool) v.
     model D E ZF_AX /\ valuation D v
     ==> (holds D E v autn_bad_form <=>
          ?z'. z' IN D /\ ?p. p IN D /\
               eopair D E (v 0) z' p /\ E p (v 41) /\
               ~hsname D E (v 2) (v 8) (v 9) z')`,
  REPEAT GEN_TAC THEN DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC) THEN
  REWRITE_TAC[autn_bad_form; HOLDS_EX] THEN
  MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s))
     ==> ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
  X_GEN_TAC `z':A` THEN DISCH_TAC THEN
  MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s))
     ==> ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
  X_GEN_TAC `p:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `valuation D ((51 |-> (p:A)) ((50 |-> (z':A)) v))`
      ASSUME_TAC THENL
   [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC) THEN
    FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  ASM_SIMP_TAC[HOLDS_AND; HOLDS_NOT; HOLDS_OPAIR_FORM;
               HOLDS_HSNAME_FORM; ARITH_EQ] THEN
  REWRITE_TAC[holds; VALMOD; ARITH_EQ]);;

let AUTN_HS = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X s muci
  muP autB nm nm'.
     hsbundle D E w1 om tw ii ci P leqp B inclB onebee X /\
     s IN D /\ eperm D E w1 s /\
     pbundle D E ci P leqp B inclB s muci muP autB /\
     nm IN D /\ hsname D E B w1 X nm /\ eautn D E B autB nm nm'
     ==> hsname D E B w1 X nm'`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "hsb")
             (CONJUNCTS_THEN2 (LABEL_TAC "sD")
              (CONJUNCTS_THEN2 (LABEL_TAC "sperm")
               (CONJUNCTS_THEN2 (LABEL_TAC "pbs")
                (CONJUNCTS_THEN2 (LABEL_TAC "nmD")
                 (CONJUNCTS_THEN2 (LABEL_TAC "hsnm")
                  (LABEL_TAC "aut"))))))) THEN
  USE_THEN "hsb" (MP_TAC o REWRITE_RULE[hsbundle]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
             (CONJUNCTS_THEN2 (LABEL_TAC "vl")
              (CONJUNCTS_THEN2 (LABEL_TAC "eom")
               (CONJUNCTS_THEN2 (LABEL_TAC "w1D")
                (CONJUNCTS_THEN2 (LABEL_TAC "w1card")
                 (CONJUNCTS_THEN2 (LABEL_TAC "omw1e")
                  (CONJUNCTS_THEN2 (LABEL_TAC "w1min")
                   (CONJUNCTS_THEN2 (LABEL_TAC "cr1")
                    (CONJUNCTS_THEN2 (LABEL_TAC "cr2")
                     (CONJUNCTS_THEN2 (LABEL_TAC "ftw")
                      (CONJUNCTS_THEN2 (LABEL_TAC "coh")
                       (CONJUNCTS_THEN2 (LABEL_TAC "leq")
                        (CONJUNCTS_THEN2 (LABEL_TAC "ros")
                         (CONJUNCTS_THEN2 (LABEL_TAC "inc")
                          (CONJUNCTS_THEN2 (LABEL_TAC "porder")
      (CONJUNCTS_THEN2 (LABEL_TAC "top")
       (CONJUNCTS_THEN2 (LABEL_TAC "oneD")
        (CONJUNCTS_THEN2 (LABEL_TAC "BD")
         (CONJUNCTS_THEN2 (LABEL_TAC "oneB")
          (CONJUNCTS_THEN2 (LABEL_TAC "XD")
           (CONJUNCTS_THEN2 (LABEL_TAC "ciX")
            (LABEL_TAC "PX")))))))))))))))))))))) THEN
  USE_THEN "pbs" (MP_TAC o REWRITE_RULE[pbundle]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "msD")
             (CONJUNCTS_THEN2 (LABEL_TAC "mPsD")
              (CONJUNCTS_THEN2 (LABEL_TAC "aBD")
               (CONJUNCTS_THEN2 (LABEL_TAC "bms")
                (CONJUNCTS_THEN2 (LABEL_TAC "bPs")
                 (CONJUNCTS_THEN2 (LABEL_TAC "bAs")
                  (CONJUNCTS_THEN2 (LABEL_TAC "mchs")
                   (CONJUNCTS_THEN2 (LABEL_TAC "Pchs")
                    (CONJUNCTS_THEN2 (LABEL_TAC "achs")
                     (CONJUNCTS_THEN2 (LABEL_TAC "oPs")
                      (LABEL_TAC "oBs"))))))))))) THEN
  MATCH_MP_TAC(TAUT `(~p ==> F) ==> p`) THEN DISCH_THEN(LABEL_TAC "nhs") THEN
  SUBGOAL_THEN `(nm':A) IN D` (LABEL_TAC "nm'D") THENL
   [USE_THEN "aut" (ACCEPT_TAC o CONJUNCT2 o MATCH_MP AUTN_IMP); ALL_TAC] THEN
  (* HS rank a0 of nm, sa0 = esuc a0 *)
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;`nm:A`]
         HSNAME_RANK) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `a0:A` (CONJUNCTS_THEN2 (LABEL_TAC "a0D")
      (CONJUNCTS_THEN2 (LABEL_TAC "a0ord")
       (CONJUNCTS_THEN2 (LABEL_TAC "a0in") (LABEL_TAC "a0min"))))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`a0:A`] ESUC_EXISTS) THEN
  ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `sa0:A` (LABEL_TAC "suc")) THEN
  SUBGOAL_THEN `(sa0:A) IN D` (LABEL_TAC "sa0D") THENL
   [USE_THEN "suc" (ACCEPT_TAC o MATCH_MP ESUC_IN); ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) sa0` (LABEL_TAC "sa0ord") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`a0:A`;`sa0:A`] EORDINAL_ESUC) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) a0 sa0` (LABEL_TAC "a0sa0") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`a0:A`;`sa0:A`] ESUC_MEMBER) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  (* Y = hsstage(sa0), bounded inside a B-name stage ylam; cd = autN stage *)
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;`sa0:A`]
         HSSTAGE_EXISTS) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ysa:A` (CONJUNCTS_THEN2 (LABEL_TAC "ysaD")
      (LABEL_TAC "hssa"))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`ysa:A`] BNAME_BOUND) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    X_GEN_TAC `z:A` THEN DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "zD")
        (LABEL_TAC "zy")) THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;`z:A`]
           HSNAME_BNAME) THEN
    ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;
                  `sa0:A`;`ysa:A`;`z:A`]
      HSNAME_STAGE) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `lam:A` (X_CHOOSE_THEN `ylam:A`
      (CONJUNCTS_THEN2 (LABEL_TAC "lamD")
       (CONJUNCTS_THEN2 (LABEL_TAC "ylamD")
        (CONJUNCTS_THEN2 (LABEL_TAC "lamord")
         (CONJUNCTS_THEN2 (LABEL_TAC "bnlam") (LABEL_TAC "ysub"))))))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`lam:A`]
         AUTNSTAGE_EXISTS) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `cd:A` (CONJUNCTS_THEN2 (LABEL_TAC "cdD")
      (LABEL_TAC "cdst"))) THEN
  SUBGOAL_THEN
   `!t t1. t IN D /\ (E:A->A->bool) t ysa /\ eautn D E B autB t t1
           ==> ?pp. pp IN D /\ eopair D E t t1 pp /\ E pp cd`
   (LABEL_TAC "pin") THENL
   [MAP_EVERY X_GEN_TAC [`t:A`;`t1:A`] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "tD")
               (CONJUNCTS_THEN2 (LABEL_TAC "tys") (LABEL_TAC "et"))) THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`lam:A`;
                  `ylam:A`;`cd:A`;
                  `t:A`;`t1:A`] AUTNSTAGE_PAIR_IN) THEN
    ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    USE_THEN "ysub" (MP_TAC o SPEC `t:A`) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!b yb t. b IN D /\ E b sa0 /\ yb IN D /\
       hsstage D (E:A->A->bool) B w1 X b yb /\
             t IN D /\ E t yb ==> E t ysa`
   (LABEL_TAC "inysa") THENL
   [MAP_EVERY X_GEN_TAC [`b:A`;`yb:A`;`t:A`] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "bD")
               (CONJUNCTS_THEN2 (LABEL_TAC "bsa")
                (CONJUNCTS_THEN2 (LABEL_TAC "ybD")
                 (CONJUNCTS_THEN2 (LABEL_TAC "hsb'")
                  (CONJUNCTS_THEN2 (LABEL_TAC "tD") (LABEL_TAC "tyb")))))) THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;
                  `sa0:A`;`b:A`;`ysa:A`;
                  `yb:A`;`t:A`] EHSSTAGE_MONO) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  (* valuation, separation *)
  USE_THEN "modl" (X_CHOOSE_TAC `u0:num->A` o MATCH_MP VALUATION_EXISTS o
                   MATCH_MP MODEL_NONEMPTY) THEN
  SUBGOAL_THEN `valuation D ((41 |-> (cd:A))
      ((9 |-> (X:A)) ((8 |-> (w1:A)) ((2 |-> (B:A)) u0))))`
      (LABEL_TAC "vB") THENL
   [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC) THEN
    FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  USE_THEN "modl" (MP_TAC o SPECL
    [`?? 0 (hsrank_form && autn_bad_form)`; `1`;
     `(41 |-> (cd:A)) ((9 |-> (X:A)) ((8 |-> (w1:A))
        ((2 |-> (B:A)) u0)))`; `sa0:A`] o
    MATCH_MP ZF_SEPARATION) THEN
  ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `S:A` (CONJUNCTS_THEN2 (LABEL_TAC "SD")
      (LABEL_TAC "Sch"))) THEN
  SUBGOAL_THEN
   `!a:A. a IN D
          ==> ((E:A->A->bool) a S <=>
               E a sa0 /\
               ?z. z IN D /\
                   (eordinal D E a /\
                    (?y. y IN D /\ hsstage D E B w1 X a y /\ E z y) /\
                    (!c. c IN D /\ E c a
                         ==> ~(?y. y IN D /\ hsstage D E B w1 X c
                               y /\ E z y))) /\
                   (?z'. z' IN D /\ ?p. p IN D /\
                         eopair D E z z' p /\ E p cd /\ ~hsname D E B w1 X z'))`
   (LABEL_TAC "Sch2") THENL
   [X_GEN_TAC `a:A` THEN DISCH_THEN(LABEL_TAC "aD") THEN
    USE_THEN "Sch" (MP_TAC o SPEC `a:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MATCH_MP_TAC(TAUT `(b <=> c) ==> (x /\ b <=> x /\ c)`) THEN
    REWRITE_TAC[HOLDS_EX; HOLDS_AND] THEN
    MATCH_MP_TAC(MESON[]
      `(!z:A. z IN D ==> (P z <=> Q z))
       ==> ((?z. z IN D /\ P z) <=> (?z. z IN D /\ Q z))`) THEN
    X_GEN_TAC `z:A` THEN DISCH_THEN(LABEL_TAC "zD") THEN
    SUBGOAL_THEN
     `valuation D ((0 |-> (z:A)) ((1 |-> (a:A))
         ((41 |-> (cd:A)) ((9 |-> (X:A)) ((8 |-> (w1:A))
         ((2 |-> (B:A)) u0))))))`
     (LABEL_TAC "vz") THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THENL
       [MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
        FIRST_ASSUM ACCEPT_TAC];
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;
      `(0 |-> (z:A)) ((1 |-> (a:A)) ((41 |-> (cd:A))
          ((9 |-> (X:A)) ((8 |-> (w1:A)) ((2 |-> (B:A)) u0)))))`]
          HOLDS_HSRANK_FORM) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;
      `(0 |-> (z:A)) ((1 |-> (a:A)) ((41 |-> (cd:A))
          ((9 |-> (X:A)) ((8 |-> (w1:A)) ((2 |-> (B:A)) u0)))))`]
          HOLDS_AUTN_BAD_FORM) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  (* a0 IN S *)
  SUBGOAL_THEN `(E:A->A->bool) nm ysa` (LABEL_TAC "nmysa") THENL
   [USE_THEN "a0in" ((X_CHOOSE_THEN `y0:A`
                      (CONJUNCTS_THEN2 (LABEL_TAC "y0D")
                       (CONJUNCTS_THEN2 (LABEL_TAC "hsy0")
                        (LABEL_TAC "nmy0"))))) THEN
    USE_THEN "inysa" (MP_TAC o SPECL [`a0:A`;`y0:A`;`nm:A`]) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  USE_THEN "pin" (MP_TAC o SPECL [`nm:A`;`nm':A`]) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `pp0:A` (CONJUNCTS_THEN2 (LABEL_TAC "pp0D")
      (CONJUNCTS_THEN2 (LABEL_TAC "pp0op") (LABEL_TAC "pp0cd")))) THEN
  SUBGOAL_THEN `(E:A->A->bool) a0 S` (LABEL_TAC "a0S") THENL
   [USE_THEN "Sch2" (MP_TAC o SPEC `a0:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    CONJ_TAC THENL [USE_THEN "a0sa0" ACCEPT_TAC; ALL_TAC] THEN
    EXISTS_TAC `nm:A` THEN CONJ_TAC THENL
        [USE_THEN "nmD" ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    EXISTS_TAC `nm':A` THEN CONJ_TAC THENL
        [USE_THEN "nm'D" ACCEPT_TAC; ALL_TAC] THEN
    EXISTS_TAC `pp0:A` THEN REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  (* minimal element *)
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`] ZF_FOUNDATION) THEN
  ANTS_TAC THENL [USE_THEN "modl" ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `S:A`) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL [USE_THEN "SD" ACCEPT_TAC; ALL_TAC] THEN
    EXISTS_TAC `a0:A` THEN CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `as:A` (CONJUNCTS_THEN2 (LABEL_TAC "asD")
      (CONJUNCTS_THEN2 (LABEL_TAC "asS") (LABEL_TAC "asmin")))) THEN
  USE_THEN "Sch2" (MP_TAC o SPEC `as:A`) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> USE_THEN "asS" (MP_TAC o EQ_MP th)) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "assa0")
             (X_CHOOSE_THEN `z:A` (CONJUNCTS_THEN2 (LABEL_TAC "zD")
      (CONJUNCTS_THEN2 (CONJUNCTS_THEN2 (LABEL_TAC "asord")
                        (CONJUNCTS_THEN2 (X_CHOOSE_THEN `yas:A`
      (CONJUNCTS_THEN2 (LABEL_TAC "yasD")
       (CONJUNCTS_THEN2 (LABEL_TAC "hsas") (LABEL_TAC "zyas")))) (K ALL_TAC)))
      (X_CHOOSE_THEN `z':A` (CONJUNCTS_THEN2 (LABEL_TAC "z'D")
      (X_CHOOSE_THEN `q:A` (CONJUNCTS_THEN2 (LABEL_TAC "qD")
      (CONJUNCTS_THEN2 (LABEL_TAC "qop")
       (CONJUNCTS_THEN2 (LABEL_TAC "qcd") (LABEL_TAC "nz'hs"))))))))))) THEN
  SUBGOAL_THEN `eautn D (E:A->A->bool) B autB z z'` (LABEL_TAC "ezz'") THENL
