  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;
                `a2:A`;`ya2:A`;`z':A`]
    HSNAME_STAGE) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                  DISCH_THEN ACCEPT_TAC]);;

(* ===================================================================== *)
(* H2e : autN_s is ONTO the HS names; SYM_BVALF_HS_PERM.                     *)
(* The bundle of s^-1 is the graph-inverse of the bundle of s at all three  *)
(* levels (MUCIREL_INV; INV_LIFT via IMG_ROUNDTRIP; PBUNDLE_INV).  Then for *)
(* HS nm', nm = autN_{s^-1}(nm') is HS (AUTN_HS) and autN_s(nm) = nm'        *)
(* (AUTN_COMPOSE).  Discharging the two abstract hypotheses of SYM_BVALF_HS. *)
(* ===================================================================== *)
let MUCIREL_INV = prove
 (`!D (E:A->A->bool) s si u w.
     (!k t. k IN D /\ t IN D ==> (eapply D E si t k <=> eapply D E s k t))
     ==> (mucirel D E si u w <=> mucirel D E s w u)`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "inv") THEN
  REWRITE_TAC[mucirel] THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `a3:A` (X_CHOOSE_THEN `a4:A`
       (X_CHOOSE_THEN `a5:A` (X_CHOOSE_THEN `a6:A`
       (X_CHOOSE_THEN `a7:A` (X_CHOOSE_THEN `a8:A`
       (CONJUNCTS_THEN2 (LABEL_TAC "a3D")
        (CONJUNCTS_THEN2 (LABEL_TAC "a4D")
         (CONJUNCTS_THEN2 (LABEL_TAC "a5D")
          (CONJUNCTS_THEN2 (LABEL_TAC "a6D")
           (CONJUNCTS_THEN2 (LABEL_TAC "a7D")
            (CONJUNCTS_THEN2 (LABEL_TAC "a8D")
             (CONJUNCTS_THEN2 (LABEL_TAC "op56")
              (CONJUNCTS_THEN2 (LABEL_TAC "op34")
               (CONJUNCTS_THEN2 (LABEL_TAC "sia")
                (CONJUNCTS_THEN2 (LABEL_TAC "op76")
                 (LABEL_TAC "op84"))))))))))))))))) THEN
    MAP_EVERY EXISTS_TAC [`a8:A`;`a4:A`;`a7:A`;`a6:A`;`a5:A`;`a3:A`] THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    USE_THEN "inv" (MP_TAC o SPECL [`a7:A`;`a5:A`]) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "sia" (ACCEPT_TAC o EQ_MP th));
    DISCH_THEN(X_CHOOSE_THEN `a3:A` (X_CHOOSE_THEN `a4:A`
        (X_CHOOSE_THEN `a5:A` (X_CHOOSE_THEN `a6:A`
        (X_CHOOSE_THEN `a7:A` (X_CHOOSE_THEN `a8:A`
        (CONJUNCTS_THEN2 (LABEL_TAC "a3D")
         (CONJUNCTS_THEN2 (LABEL_TAC "a4D")
          (CONJUNCTS_THEN2 (LABEL_TAC "a5D")
           (CONJUNCTS_THEN2 (LABEL_TAC "a6D")
            (CONJUNCTS_THEN2 (LABEL_TAC "a7D")
             (CONJUNCTS_THEN2 (LABEL_TAC "a8D")
              (CONJUNCTS_THEN2 (LABEL_TAC "op56")
               (CONJUNCTS_THEN2 (LABEL_TAC "op34")
                (CONJUNCTS_THEN2 (LABEL_TAC "sa")
                 (CONJUNCTS_THEN2 (LABEL_TAC "op76")
                  (LABEL_TAC "op84"))))))))))))))))) THEN
    MAP_EVERY EXISTS_TAC [`a8:A`;`a4:A`;`a7:A`;`a6:A`;`a5:A`;`a3:A`] THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    USE_THEN "inv" (MP_TAC o SPECL [`a5:A`;`a7:A`]) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "sa" (ACCEPT_TAC o EQ_MP (SYM th)))]);;

let INV_LIFT = prove
 (`!D (E:A->A->bool) X Y g g' h h'.
     model D E ZF_AX /\
     ebij D E g X X /\ ebij D E g' X X /\
     (!k t. k IN D /\ t IN D ==> (eapply D E g' t k <=> eapply D E g k t)) /\
     (!p q. p IN D /\ q IN D ==> (eapply D E h p q <=> E p Y /\
         muPrel D E g p q)) /\
     (!p q. p IN D /\ q IN D ==> (eapply D E h' p q <=> E p Y /\
         muPrel D E g' p q)) /\
     ebij D E h Y Y /\ ebij D E h' Y Y /\
     (!p. p IN D /\ E p Y ==> esubset D E p X)
     ==> (!k t. k IN D /\ t IN D ==> (eapply D E h' t k <=> eapply D E h k t))`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
             (CONJUNCTS_THEN2 (LABEL_TAC "bg")
              (CONJUNCTS_THEN2 (LABEL_TAC "bg'")
               (CONJUNCTS_THEN2 (LABEL_TAC "inv")
                (CONJUNCTS_THEN2 (LABEL_TAC "hch")
                 (CONJUNCTS_THEN2 (LABEL_TAC "h'ch")
                  (CONJUNCTS_THEN2 (LABEL_TAC "bh")
                   (CONJUNCTS_THEN2 (LABEL_TAC "bh'")
                    (LABEL_TAC "Ysub"))))))))) THEN
  SUBGOAL_THEN
   `!k t. k IN D /\ t IN D ==> (eapply D (E:A->A->bool) g t k <=>
       eapply D E g' k t)`
   (LABEL_TAC "inv2") THENL
   [MAP_EVERY X_GEN_TAC [`a:A`;`b:A`] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "aD") (LABEL_TAC "bD")) THEN
    USE_THEN "inv" (MP_TAC o SPECL [`b:A`;`a:A`]) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN(fun th -> REWRITE_TAC[th])];
    ALL_TAC] THEN
  MAP_EVERY X_GEN_TAC [`k:A`;`t:A`] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "kD") (LABEL_TAC "tD")) THEN
  EQ_TAC THENL
   [DISCH_THEN(LABEL_TAC "h'tk") THEN
    USE_THEN "h'ch" (MP_TAC o SPECL [`t:A`;`k:A`]) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "h'tk" (MP_TAC o EQ_MP th)) THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "tY") (LABEL_TAC "mtk")) THEN
    SUBGOAL_THEN `(E:A->A->bool) k Y` (LABEL_TAC "kY") THENL
     [USE_THEN "bh'" (MP_TAC o SPECL [`t:A`;`k:A`] o CONJUNCT1 o CONJUNCT2 o
                      REWRITE_RULE[ebij]) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN(ACCEPT_TAC o CONJUNCT2)];
      ALL_TAC] THEN
    USE_THEN "hch" (MP_TAC o SPECL [`k:A`;`t:A`]) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN SUBST1_TAC] THEN
    CONJ_TAC THENL [USE_THEN "kY" ACCEPT_TAC; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`g:A`;`g':A`;`X:A`;`t:A`;`k:A`]
           IMG_ROUNDTRIP) THEN
    ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THENL
     [USE_THEN "bg" (ACCEPT_TAC o CONJUNCT1 o CONJUNCT2 o CONJUNCT2 o CONJUNCT2
                     o REWRITE_RULE[ebij]);
      USE_THEN "Ysub" (MP_TAC o SPEC `t:A`) THEN
      ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN ACCEPT_TAC]];
    DISCH_THEN(LABEL_TAC "hkt") THEN
    USE_THEN "hch" (MP_TAC o SPECL [`k:A`;`t:A`]) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "hkt" (MP_TAC o EQ_MP th)) THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "kY") (LABEL_TAC "mkt")) THEN
    SUBGOAL_THEN `(E:A->A->bool) t Y` (LABEL_TAC "tY") THENL
     [USE_THEN "bh" (MP_TAC o SPECL [`k:A`;`t:A`] o CONJUNCT1 o CONJUNCT2 o
                     REWRITE_RULE[ebij]) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN(ACCEPT_TAC o CONJUNCT2)];
      ALL_TAC] THEN
    USE_THEN "h'ch" (MP_TAC o SPECL [`t:A`;`k:A`]) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN SUBST1_TAC] THEN
    CONJ_TAC THENL [USE_THEN "tY" ACCEPT_TAC; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`g':A`;`g:A`;`X:A`;`k:A`;`t:A`]
           IMG_ROUNDTRIP) THEN
    ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THENL
     [USE_THEN "bg'" (ACCEPT_TAC o CONJUNCT1 o CONJUNCT2 o CONJUNCT2 o CONJUNCT2
                      o REWRITE_RULE[ebij]);
      USE_THEN "Ysub" (MP_TAC o SPEC `k:A`) THEN
      ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN ACCEPT_TAC]]]);;

let PBUNDLE_INV = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X
     s si muci muP autB muci' muP' autB'.
     hsbundle D E w1 om tw ii ci P leqp B inclB onebee X /\
     (!k t. k IN D /\ t IN D ==> (eapply D E si t k <=> eapply D E s k t)) /\
     pbundle D E ci P leqp B inclB s muci muP autB /\
     pbundle D E ci P leqp B inclB si muci' muP' autB'
     ==> (!k t. k IN D /\ t IN D ==> (eapply D E autB' t k <=>
         eapply D E autB k t))`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "hsb")
             (CONJUNCTS_THEN2 (LABEL_TAC "sinv")
              (CONJUNCTS_THEN2 (MP_TAC o REWRITE_RULE[pbundle])
               (MP_TAC o REWRITE_RULE[pbundle])))) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "mD2")
             (CONJUNCTS_THEN2 (LABEL_TAC "mPD2")
              (CONJUNCTS_THEN2 (LABEL_TAC "aD2")
               (CONJUNCTS_THEN2 (LABEL_TAC "bm2")
                (CONJUNCTS_THEN2 (LABEL_TAC "bP2")
                 (CONJUNCTS_THEN2 (LABEL_TAC "bA2")
                  (CONJUNCTS_THEN2 (LABEL_TAC "mch2")
                   (CONJUNCTS_THEN2 (LABEL_TAC "Pch2")
                    (CONJUNCTS_THEN2 (LABEL_TAC "ach2")
                     (CONJUNCTS_THEN2 (LABEL_TAC "oP2")
                      (LABEL_TAC "oB2"))))))))))) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "mD1")
             (CONJUNCTS_THEN2 (LABEL_TAC "mPD1")
              (CONJUNCTS_THEN2 (LABEL_TAC "aD1")
               (CONJUNCTS_THEN2 (LABEL_TAC "bm1")
                (CONJUNCTS_THEN2 (LABEL_TAC "bP1")
                 (CONJUNCTS_THEN2 (LABEL_TAC "bA1")
                  (CONJUNCTS_THEN2 (LABEL_TAC "mch1")
                   (CONJUNCTS_THEN2 (LABEL_TAC "Pch1")
                    (CONJUNCTS_THEN2 (LABEL_TAC "ach1")
                     (CONJUNCTS_THEN2 (LABEL_TAC "oP1")
                      (LABEL_TAC "oB1"))))))))))) THEN
  USE_THEN "hsb" (MP_TAC o REWRITE_RULE[hsbundle]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
             (CONJUNCTS_THEN2 (LABEL_TAC "vl")
              (CONJUNCTS_THEN2 (LABEL_TAC "eom")
               (CONJUNCTS_THEN2 (LABEL_TAC "w1D")
                (CONJUNCTS_THEN2 (LABEL_TAC "w1card")
                 (CONJUNCTS_THEN2 (LABEL_TAC "omw1e")
                  (CONJUNCTS_THEN2 (LABEL_TAC "w1min")
                   (CONJUNCTS_THEN2 (LABEL_TAC "cr1")
                    (CONJUNCTS_THEN2 (LABEL_TAC "cr2")
                     (CONJUNCTS_THEN2 (LABEL_TAC "ftw")
                      (CONJUNCTS_THEN2 (LABEL_TAC "coh")
                       (CONJUNCTS_THEN2 (LABEL_TAC "leq")
                        (CONJUNCTS_THEN2 (LABEL_TAC "ros")
                         (CONJUNCTS_THEN2 (LABEL_TAC "inc")
                          (CONJUNCTS_THEN2 (LABEL_TAC "porder")
      (CONJUNCTS_THEN2 (LABEL_TAC "top")
       (CONJUNCTS_THEN2 (LABEL_TAC "oneD")
        (CONJUNCTS_THEN2 (LABEL_TAC "BD")
         (CONJUNCTS_THEN2 (LABEL_TAC "oneB")
          (CONJUNCTS_THEN2 (LABEL_TAC "XD")
           (CONJUNCTS_THEN2 (LABEL_TAC "ciX")
            (LABEL_TAC "PX")))))))))))))))))))))) THEN
  (* muci' is the graph-inverse of muci *)
  SUBGOAL_THEN
   `!k t. k IN D /\ t IN D
          ==> (eapply D (E:A->A->bool) muci' t k <=> eapply D E muci k t)`
   (LABEL_TAC "minv") THENL
   [MAP_EVERY X_GEN_TAC [`k:A`;`t:A`] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "kD") (LABEL_TAC "tD")) THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`s:A`;`si:A`;`t:A`;`k:A`]
           MUCIREL_INV) THEN
    ANTS_TAC THENL [USE_THEN "sinv" ACCEPT_TAC;
                    DISCH_THEN(LABEL_TAC "mrinv")] THEN
    EQ_TAC THENL
     [DISCH_THEN(LABEL_TAC "e2") THEN
      SUBGOAL_THEN `(E:A->A->bool) k ci` (LABEL_TAC "kci") THENL
       [USE_THEN "bm2" (MP_TAC o SPECL [`t:A`;`k:A`] o CONJUNCT1 o CONJUNCT2 o
                        REWRITE_RULE[ebij]) THEN
        ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                        DISCH_THEN(ACCEPT_TAC o CONJUNCT2)];
        ALL_TAC] THEN
      USE_THEN "mch2" (MP_TAC o SPECL [`t:A`;`k:A`]) THEN
      ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> USE_THEN "e2" (MP_TAC o EQ_MP th)) THEN
      DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (LABEL_TAC "mr2")) THEN
      USE_THEN "mch1" (MP_TAC o SPECL [`k:A`;`t:A`]) THEN
      ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN SUBST1_TAC] THEN
      CONJ_TAC THENL [USE_THEN "kci" ACCEPT_TAC; ALL_TAC] THEN
      USE_THEN "mrinv" (fun th -> USE_THEN "mr2" (ACCEPT_TAC o EQ_MP th));
      DISCH_THEN(LABEL_TAC "e1") THEN
      SUBGOAL_THEN `(E:A->A->bool) t ci` (LABEL_TAC "tci") THENL
       [USE_THEN "bm1" (MP_TAC o SPECL [`k:A`;`t:A`] o CONJUNCT1 o CONJUNCT2 o
                        REWRITE_RULE[ebij]) THEN
        ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                        DISCH_THEN(ACCEPT_TAC o CONJUNCT2)];
        ALL_TAC] THEN
      USE_THEN "mch1" (MP_TAC o SPECL [`k:A`;`t:A`]) THEN
      ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> USE_THEN "e1" (MP_TAC o EQ_MP th)) THEN
      DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (LABEL_TAC "mr1")) THEN
      USE_THEN "mch2" (MP_TAC o SPECL [`t:A`;`k:A`]) THEN
      ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN SUBST1_TAC] THEN
      CONJ_TAC THENL [USE_THEN "tci" ACCEPT_TAC; ALL_TAC] THEN
      USE_THEN "mrinv" (fun th -> USE_THEN "mr1"
                        (ACCEPT_TAC o EQ_MP (SYM th)))];
    ALL_TAC] THEN
  (* muP' inverse of muP *)
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`ci:A`;`P:A`;`muci:A`;`muci':A`;
                `muP:A`;`muP':A`]
    INV_LIFT) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    X_GEN_TAC `p:A` THEN DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "pD")
        (LABEL_TAC "pP")) THEN
    USE_THEN "coh" (MP_TAC o SPEC `p:A` o CONJUNCT2 o
                    REWRITE_RULE[ecohenp]) THEN
    ANTS_TAC THENL [USE_THEN "pD" ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "pP" (MP_TAC o EQ_MP th)) THEN
    DISCH_THEN(ACCEPT_TAC o CONJUNCT1);
    DISCH_THEN(LABEL_TAC "pinv")] THEN
  (* autB' inverse of autB *)
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`P:A`;`B:A`;`muP:A`;`muP':A`;
                `autB:A`;`autB':A`]
    INV_LIFT) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    X_GEN_TAC `b:A` THEN DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "bD")
        (LABEL_TAC "bB")) THEN
    USE_THEN "ros" (MP_TAC o SPEC `b:A` o CONJUNCT2 o REWRITE_RULE[eroset]) THEN
    ANTS_TAC THENL [USE_THEN "bD" ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "bB" (MP_TAC o EQ_MP th)) THEN
    DISCH_THEN(ACCEPT_TAC o CONJUNCT1);
    DISCH_THEN ACCEPT_TAC]);;

let HSB_CBA = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X.
     hsbundle D E w1 om tw ii ci P leqp B inclB onebee X
     ==> ecba D E B inclB /\ inclB IN D /\ leqp IN D`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "hsb") THEN
  USE_THEN "hsb" (MP_TAC o MATCH_MP HSB_FACTS) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (CONJUNCTS_THEN2 (K ALL_TAC)
    (CONJUNCTS_THEN2 (LABEL_TAC "PD") (K ALL_TAC)))) THEN
  USE_THEN "hsb" (MP_TAC o REWRITE_RULE[hsbundle]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
             (CONJUNCTS_THEN2 (LABEL_TAC "vl")
              (CONJUNCTS_THEN2 (LABEL_TAC "eom")
               (CONJUNCTS_THEN2 (LABEL_TAC "w1D")
                (CONJUNCTS_THEN2 (LABEL_TAC "w1card")
                 (CONJUNCTS_THEN2 (LABEL_TAC "omw1e")
                  (CONJUNCTS_THEN2 (LABEL_TAC "w1min")
                   (CONJUNCTS_THEN2 (LABEL_TAC "cr1")
                    (CONJUNCTS_THEN2 (LABEL_TAC "cr2")
                     (CONJUNCTS_THEN2 (LABEL_TAC "ftw")
                      (CONJUNCTS_THEN2 (LABEL_TAC "coh")
                       (CONJUNCTS_THEN2 (LABEL_TAC "leq")
                        (CONJUNCTS_THEN2 (LABEL_TAC "ros")
                         (CONJUNCTS_THEN2 (LABEL_TAC "inc")
                          (CONJUNCTS_THEN2 (LABEL_TAC "porder")
      (CONJUNCTS_THEN2 (LABEL_TAC "top")
       (CONJUNCTS_THEN2 (LABEL_TAC "oneD")
        (CONJUNCTS_THEN2 (LABEL_TAC "BD")
         (CONJUNCTS_THEN2 (LABEL_TAC "oneB")
          (CONJUNCTS_THEN2 (LABEL_TAC "XD")
           (CONJUNCTS_THEN2 (LABEL_TAC "ciX")
            (LABEL_TAC "PX")))))))))))))))))))))) THEN
  SUBGOAL_THEN `(leqp:A) IN D /\ (inclB:A) IN D`
   (CONJUNCTS_THEN2 (LABEL_TAC "leqpD") (LABEL_TAC "inclBD")) THENL
   [CONJ_TAC THENL
     [USE_THEN "leq" (ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[eleqp]);
      USE_THEN "inc" (ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[eincl])];
    ALL_TAC] THEN
  REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`B:A`;`inclB:A`]
         ECBA_ROSET) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                  DISCH_THEN ACCEPT_TAC]);;

let AUTN_HS_ONTO = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X s muci muP autB nm'.
     hsbundle D E w1 om tw ii ci P leqp B inclB onebee X /\
     s IN D /\ eperm D E w1 s /\
     pbundle D E ci P leqp B inclB s muci muP autB /\
     nm' IN D /\ hsname D E B w1 X nm'
     ==> ?nm. nm IN D /\ hsname D E B w1 X nm /\ eautn D E B autB nm nm'`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "hsb")
             (CONJUNCTS_THEN2 (LABEL_TAC "sD")
              (CONJUNCTS_THEN2 (LABEL_TAC "sperm")
               (CONJUNCTS_THEN2 (LABEL_TAC "pbs")
                (CONJUNCTS_THEN2 (LABEL_TAC "nm'D")
                 (LABEL_TAC "hsnm'")))))) THEN
  USE_THEN "hsb" (MP_TAC o REWRITE_RULE[hsbundle]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
             (CONJUNCTS_THEN2 (LABEL_TAC "vl")
              (CONJUNCTS_THEN2 (LABEL_TAC "eom")
               (CONJUNCTS_THEN2 (LABEL_TAC "w1D")
                (CONJUNCTS_THEN2 (LABEL_TAC "w1card")
                 (CONJUNCTS_THEN2 (LABEL_TAC "omw1e")
                  (CONJUNCTS_THEN2 (LABEL_TAC "w1min")
                   (CONJUNCTS_THEN2 (LABEL_TAC "cr1")
                    (CONJUNCTS_THEN2 (LABEL_TAC "cr2")
                     (CONJUNCTS_THEN2 (LABEL_TAC "ftw")
                      (CONJUNCTS_THEN2 (LABEL_TAC "coh")
                       (CONJUNCTS_THEN2 (LABEL_TAC "leq")
                        (CONJUNCTS_THEN2 (LABEL_TAC "ros")
                         (CONJUNCTS_THEN2 (LABEL_TAC "inc")
                          (CONJUNCTS_THEN2 (LABEL_TAC "porder")
      (CONJUNCTS_THEN2 (LABEL_TAC "top")
       (CONJUNCTS_THEN2 (LABEL_TAC "oneD")
        (CONJUNCTS_THEN2 (LABEL_TAC "BD")
         (CONJUNCTS_THEN2 (LABEL_TAC "oneB")
          (CONJUNCTS_THEN2 (LABEL_TAC "XD")
           (CONJUNCTS_THEN2 (LABEL_TAC "ciX")
            (LABEL_TAC "PX")))))))))))))))))))))) THEN
  USE_THEN "pbs" (MP_TAC o REWRITE_RULE[pbundle]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "mDs")
             (CONJUNCTS_THEN2 (LABEL_TAC "mPDs")
              (CONJUNCTS_THEN2 (LABEL_TAC "aDs")
               (CONJUNCTS_THEN2 (LABEL_TAC "bms")
                (CONJUNCTS_THEN2 (LABEL_TAC "bPs")
                 (CONJUNCTS_THEN2 (LABEL_TAC "bAs")
                  (CONJUNCTS_THEN2 (LABEL_TAC "mchs")
                   (CONJUNCTS_THEN2 (LABEL_TAC "Pchs")
                    (CONJUNCTS_THEN2 (LABEL_TAC "achs")
                     (CONJUNCTS_THEN2 (LABEL_TAC "oPs")
                      (LABEL_TAC "oBs"))))))))))) THEN
  SUBGOAL_THEN `ebij D (E:A->A->bool) s w1 w1` (LABEL_TAC "sbij") THENL
   [USE_THEN "sperm" (ACCEPT_TAC o REWRITE_RULE[eperm]); ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`s:A`;`w1:A`;`w1:A`]
         EBIJ_INV_CHAR) THEN
  ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `si:A` (CONJUNCTS_THEN2 (LABEL_TAC "siD")
      (CONJUNCTS_THEN2 (LABEL_TAC "sibij") (LABEL_TAC "sich")))) THEN
  SUBGOAL_THEN `eperm D (E:A->A->bool) w1 si` (LABEL_TAC "siperm") THENL
   [REWRITE_TAC[eperm] THEN USE_THEN "sibij" ACCEPT_TAC; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;
                `ii:A`;`ci:A`;`P:A`;
                `leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`si:A`]
                    PBUNDLE_EXISTS) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `mi:A` (X_CHOOSE_THEN `mPi:A`
      (X_CHOOSE_THEN `aBi:A` (LABEL_TAC "pbi")))) THEN
  USE_THEN "pbi" ((CONJUNCTS_THEN2 (LABEL_TAC "mDi")
                   (CONJUNCTS_THEN2 (LABEL_TAC "mPDi")
                    (CONJUNCTS_THEN2 (LABEL_TAC "aDi")
                     (CONJUNCTS_THEN2 (LABEL_TAC "bmi")
                      (CONJUNCTS_THEN2 (LABEL_TAC "bPi")
                       (CONJUNCTS_THEN2 (LABEL_TAC "bAi")
                        (CONJUNCTS_THEN2 (LABEL_TAC "mchi")
                         (CONJUNCTS_THEN2 (LABEL_TAC "Pchi")
                          (CONJUNCTS_THEN2 (LABEL_TAC "achi")
      (CONJUNCTS_THEN2 (LABEL_TAC "oPi") (LABEL_TAC "oBi"))))))))))) o
      REWRITE_RULE[pbundle]) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;
                `ii:A`;`ci:A`;`P:A`;
                `leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`s:A`;`si:A`;
                `muci:A`;`muP:A`;`autB:A`;`mi:A`;`mPi:A`;`aBi:A`]
                    PBUNDLE_INV) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(LABEL_TAC "binv") THEN
  SUBGOAL_THEN
   `!k t. k IN D /\ t IN D ==> (eapply D (E:A->A->bool) autB t k <=>
       eapply D E aBi k t)`
   (LABEL_TAC "binv2") THENL
   [MAP_EVERY X_GEN_TAC [`a:A`;`b:A`] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "aD'") (LABEL_TAC "bD'")) THEN
    USE_THEN "binv" (MP_TAC o SPECL [`b:A`;`a:A`]) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN(fun th -> REWRITE_TAC[th])];
    ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B nm'` (LABEL_TAC "bnnm'") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;`nm':A`]
           HSNAME_BNAME) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`aBi:A`;`nm':A`]
         AUTN_TOTAL) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `nm:A` (CONJUNCTS_THEN2 (LABEL_TAC "nmD")
      (LABEL_TAC "enm"))) THEN
  SUBGOAL_THEN `hsname D (E:A->A->bool) B w1 X nm` (LABEL_TAC "hsnm") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;
                  `ii:A`;`ci:A`;`P:A`;
                  `leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;
                      `si:A`;`mi:A`;`mPi:A`;
                  `aBi:A`;`nm':A`;`nm:A`] AUTN_HS) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B nm` (LABEL_TAC "bnnm") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`aBi:A`;`nm':A`;`nm:A`]
           EAUTN_IS_BNAME) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`nm:A`]
         AUTN_TOTAL) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `w:A` (CONJUNCTS_THEN2 (LABEL_TAC "wD")
      (LABEL_TAC "enmw"))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`aBi:A`;`autB:A`;
                `nm':A`;`nm:A`;`w:A`]
    AUTN_COMPOSE) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(LABEL_TAC "weq") THEN
  EXISTS_TAC `nm:A` THEN
  CONJ_TAC THENL [USE_THEN "nmD" ACCEPT_TAC; ALL_TAC] THEN
  CONJ_TAC THENL [USE_THEN "hsnm" ACCEPT_TAC; ALL_TAC] THEN
  USE_THEN "weq" (SUBST1_TAC o SYM) THEN USE_THEN "enmw" ACCEPT_TAC);;

let SYM_BVALF_HS_PERM = prove
 (`!p D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X s
  muci muP autB v vi.
     hsbundle D E w1 om tw ii ci P leqp B inclB onebee X /\
     s IN D /\ eperm D E w1 s /\
     pbundle D E ci P leqp B inclB s muci muP autB /\
     valuation D v /\ (!i. hsname D E B w1 X (v i)) /\
     valuation D vi /\ (!i. eautn D E B autB (v i) (vi i))
     ==> eapply D E autB (bvalf_HS D E B inclB w1 X v p)
                         (bvalf_HS D E B inclB w1 X vi p)`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "hsb")
             (CONJUNCTS_THEN2 (LABEL_TAC "sD")
              (CONJUNCTS_THEN2 (LABEL_TAC "sperm")
               (CONJUNCTS_THEN2 (LABEL_TAC "pbs")
                (CONJUNCTS_THEN2 (LABEL_TAC "vv")
                 (CONJUNCTS_THEN2 (LABEL_TAC "hsv")
                  (CONJUNCTS_THEN2 (LABEL_TAC "vvi")
                   (LABEL_TAC "auti")))))))) THEN
  USE_THEN "hsb" (MP_TAC o MATCH_MP HSB_CBA) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "cba")
             (CONJUNCTS_THEN2 (LABEL_TAC "inclBD") (LABEL_TAC "leqpD"))) THEN
  USE_THEN "hsb" (MP_TAC o REWRITE_RULE[hsbundle]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
             (CONJUNCTS_THEN2 (LABEL_TAC "vl")
              (CONJUNCTS_THEN2 (LABEL_TAC "eom")
               (CONJUNCTS_THEN2 (LABEL_TAC "w1D")
                (CONJUNCTS_THEN2 (LABEL_TAC "w1card")
                 (CONJUNCTS_THEN2 (LABEL_TAC "omw1e")
                  (CONJUNCTS_THEN2 (LABEL_TAC "w1min")
                   (CONJUNCTS_THEN2 (LABEL_TAC "cr1")
                    (CONJUNCTS_THEN2 (LABEL_TAC "cr2")
                     (CONJUNCTS_THEN2 (LABEL_TAC "ftw")
                      (CONJUNCTS_THEN2 (LABEL_TAC "coh")
                       (CONJUNCTS_THEN2 (LABEL_TAC "leq")
                        (CONJUNCTS_THEN2 (LABEL_TAC "ros")
                         (CONJUNCTS_THEN2 (LABEL_TAC "inc")
                          (CONJUNCTS_THEN2 (LABEL_TAC "porder")
      (CONJUNCTS_THEN2 (LABEL_TAC "top")
       (CONJUNCTS_THEN2 (LABEL_TAC "oneD")
        (CONJUNCTS_THEN2 (LABEL_TAC "BD")
         (CONJUNCTS_THEN2 (LABEL_TAC "oneB")
          (CONJUNCTS_THEN2 (LABEL_TAC "XD")
           (CONJUNCTS_THEN2 (LABEL_TAC "ciX")
            (LABEL_TAC "PX")))))))))))))))))))))) THEN
  USE_THEN "pbs" (MP_TAC o REWRITE_RULE[pbundle]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "mDs")
             (CONJUNCTS_THEN2 (LABEL_TAC "mPDs")
              (CONJUNCTS_THEN2 (LABEL_TAC "aDs")
               (CONJUNCTS_THEN2 (LABEL_TAC "bms")
                (CONJUNCTS_THEN2 (LABEL_TAC "bPs")
                 (CONJUNCTS_THEN2 (LABEL_TAC "bAs")
                  (CONJUNCTS_THEN2 (LABEL_TAC "mchs")
                   (CONJUNCTS_THEN2 (LABEL_TAC "Pchs")
                    (CONJUNCTS_THEN2 (LABEL_TAC "achs")
                     (CONJUNCTS_THEN2 (LABEL_TAC "oPs")
                      (LABEL_TAC "oBs"))))))))))) THEN
  MP_TAC(SPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                `inclB:A`;`w1:A`;`X:A`;
                `autB:A`;`v:num->A`;`vi:num->A`] SYM_BVALF_HS) THEN
  ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
  REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THENL
   [MAP_EVERY X_GEN_TAC [`c:A`;`c':A`] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "cD")
               (CONJUNCTS_THEN2 (LABEL_TAC "hsc") (LABEL_TAC "ecc'"))) THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;
                  `ii:A`;`ci:A`;`P:A`;
                  `leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`s:A`;
                      `muci:A`;`muP:A`;
                  `autB:A`;`c:A`;`c':A`] AUTN_HS) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    X_GEN_TAC `c':A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "c'D") (LABEL_TAC "hsc'")) THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;
                  `ii:A`;`ci:A`;`P:A`;
                  `leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`s:A`;
                      `muci:A`;`muP:A`;
                  `autB:A`;`c':A`] AUTN_HS_ONTO) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC]]);;

(* ######################################################################### *)
(* S5 / H3 (part 1) : TOOLS FOR THE HS MAXIMUM PRINCIPLE                     *)
(* H3.1 HS Leibniz congruence (BVAL_SUBST_CONG_HS, MAXPRIN_LEIBNIZ_STEP_HS)   *)
(*      + BVALF_HS_IND, BVALF_HS_FV_CONG;                                    *)
(* H3.4 COLL_L (generic collection in ZF + V=L, via least L-stage ranks),    *)
(*      BVALF_HS_EX_LEAST, HSVAL_ATTAIN (a SET of HS names attaining every   *)
(*      HS value of a formula);                                             *)
(* H3.3 GDISJ_W (disjointification of a B-valued family along a well-order: *)
(*      weights below the family, pairwise disjoint, same upper bounds).    *)
(* ######################################################################### *)
(* ===================================================================== *)
(* H3.1 / H3.2 : HS clones of BVALF_IND, BVALF_FV_CONG, BVAL_SUBST_CONG      *)
(* (the Boolean Leibniz congruence) and MAXPRIN_LEIBNIZ_STEP.  The atomic   *)
(* congruences (EBV_*_CONG) still need B-name facts, derived once per case  *)
(* via HSNAME_BNAME.                                                         *)
(* ===================================================================== *)

let BVALF_HS_IND = prove
 (`!p D (E:A->A->bool) B leq w1 X v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
          w1 IN D /\ X IN D /\
      valuation D v /\ (!i. hsname D E B w1 X (v i))
      ==> bvalf_HS D E B leq w1 X v p IN D`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;`X:A`;
                 `v:num->A`] BVALF_HS_SPEC) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN ASM_REWRITE_TAC[]);;

let BVALF_HS_FV_CONG = prove
 (`!p D (E:A->A->bool) B leq w1 X v w.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
          w1 IN D /\ X IN D /\
      valuation D v /\ (!i. hsname D E B w1 X (v i)) /\
      valuation D w /\ (!i. hsname D E B w1 X (w i)) /\
      (!i. i IN FV p ==> v i = w i)
      ==> bvalf_HS D E B leq w1 X v p = bvalf_HS D E B leq w1 X w p`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                 `X:A`;`v:num->A`]
    BVALF_HS_SPEC) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                 `X:A`;`w:num->A`]
    BVALF_HS_SPEC) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN STRIP_TAC THEN
  SUBGOAL_THEN `bval_HS D (E:A->A->bool) B leq w1 X (v:num->A) (p:form)
                     (bvalf_HS D E B leq w1 X (w:num->A) (p:form))`
                         ASSUME_TAC THENL
   [MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                   `X:A`;`v:num->A`;
      `w:num->A`; `bvalf_HS D (E:A->A->bool) B leq w1 X (w:num->A) (p:form)`]
          BVAL_HS_FV) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                       `X:A`;`v:num->A`;
    `bvalf_HS D (E:A->A->bool) B leq w1 X (v:num->A) (p:form)`;
    `bvalf_HS D (E:A->A->bool) B leq w1 X (w:num->A) (p:form)`]
        BVAL_HS_UNIQUE) THEN
  ASM_REWRITE_TAC[]);;

let BVAL_SUBST_CONG_HS = prove
 (`!p D (E:A->A->bool) B leq w1 X v x w t ewt m.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
          w1 IN D /\ X IN D /\
      valuation D v /\ (!i. hsname D E B w1 X (v i)) /\
      w IN D /\ t IN D /\ hsname D E B w1 X w /\ hsname D E B w1 X t /\
      ewt IN D /\ ebv_eq D E B leq w t ewt /\
      emeet D E B leq ewt (bvalf_HS D E B leq w1 X ((x |-> w) v) p) m
      ==> erel D E leq m (bvalf_HS D E B leq w1 X ((x |-> t) v) p)`,
  MATCH_MP_TAC form_INDUCT THEN REPEAT CONJ_TAC THENL
   [ (* ============================ False ============================ *)
    (REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\
        eporder D (E:A->A->bool) B leq`
      STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) ewt B` ASSUME_TAC THENL
     [ASM_MESON_TAC[EBV_EQ_IN_B]; ALL_TAC] THEN
    SUBGOAL_THEN `bname D (E:A->A->bool) B w /\ bname D E B t /\
                  (!i. bname D (E:A->A->bool) B ((v:num->A) i))`
      STRIP_ASSUME_TAC THENL
     [REPEAT CONJ_TAC THENL
       [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
        ASM_REWRITE_TAC[];
        MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
        ASM_REWRITE_TAC[];
        GEN_TAC THEN MATCH_MP_TAC HSNAME_BNAME THEN
        MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN ASM_REWRITE_TAC[] THEN
        ASM_MESON_TAC[valuation]];
      ALL_TAC] THEN
    SUBGOAL_THEN
      `(valuation D ((x |-> w) (v:num->A)) /\
        (!i. hsname D (E:A->A->bool) B w1 X (((x |-> w) (v:num->A)) i))) /\
       (valuation D ((x |-> t) (v:num->A)) /\
        (!i. hsname D (E:A->A->bool) B w1 X (((x |-> t) (v:num->A)) i)))`
      STRIP_ASSUME_TAC THENL
     [REPEAT CONJ_TAC THEN
      (MATCH_MP_TAC VALUATION_VALMOD ORELSE MATCH_MP_TAC HSNAMEVAL_VALMOD) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
      `(!i. bname D (E:A->A->bool) B (((x |-> w) (v:num->A)) i)) /\
       (!i. bname D (E:A->A->bool) B (((x |-> t) (v:num->A)) i))`
      STRIP_ASSUME_TAC THENL
     [CONJ_TAC THEN MATCH_MP_TAC BNAMEVAL_VALMOD THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP EMEET_LE) THEN
    FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP EMEET_IN)) THEN
    SUBGOAL_THEN
      `bvalf_HS D (E:A->A->bool) B leq w1 X ((x |-> t) v) False =
       bvalf_HS D (E:A->A->bool) B leq w1 X ((x |-> w) v) False`
      (fun th -> REWRITE_TAC[th]) THENL
     [SUBGOAL_THEN
        `ebot D (E:A->A->bool) B leq (bvalf_HS D E B leq w1 X
            ((x |-> w) v) False) /\
         ebot D (E:A->A->bool) B leq (bvalf_HS D E B leq w1 X
             ((x |-> t) v) False)`
        STRIP_ASSUME_TAC THENL
       [CONJ_TAC THEN MATCH_MP_TAC BVALF_HS_FALSE THEN ASM_REWRITE_TAC[];
        ASM_MESON_TAC[EBOT_UNIQUE]];
      ASM_REWRITE_TAC[]];
    (* ============================ i %% j ============================ *)
    (REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\
        eporder D (E:A->A->bool) B leq`
      STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) ewt B` ASSUME_TAC THENL
     [ASM_MESON_TAC[EBV_EQ_IN_B]; ALL_TAC] THEN
    SUBGOAL_THEN `bname D (E:A->A->bool) B w /\ bname D E B t /\
                  (!i. bname D (E:A->A->bool) B ((v:num->A) i))`
      STRIP_ASSUME_TAC THENL
     [REPEAT CONJ_TAC THENL
       [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
        ASM_REWRITE_TAC[];
        MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
        ASM_REWRITE_TAC[];
        GEN_TAC THEN MATCH_MP_TAC HSNAME_BNAME THEN
        MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN ASM_REWRITE_TAC[] THEN
        ASM_MESON_TAC[valuation]];
      ALL_TAC] THEN
    SUBGOAL_THEN
      `(valuation D ((x |-> w) (v:num->A)) /\
        (!i. hsname D (E:A->A->bool) B w1 X (((x |-> w) (v:num->A)) i))) /\
       (valuation D ((x |-> t) (v:num->A)) /\
        (!i. hsname D (E:A->A->bool) B w1 X (((x |-> t) (v:num->A)) i)))`
      STRIP_ASSUME_TAC THENL
     [REPEAT CONJ_TAC THEN
      (MATCH_MP_TAC VALUATION_VALMOD ORELSE MATCH_MP_TAC HSNAMEVAL_VALMOD) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
      `(!i. bname D (E:A->A->bool) B (((x |-> w) (v:num->A)) i)) /\
       (!i. bname D (E:A->A->bool) B (((x |-> t) (v:num->A)) i))`
      STRIP_ASSUME_TAC THENL
     [CONJ_TAC THEN MATCH_MP_TAC BNAMEVAL_VALMOD THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP EMEET_LE) THEN
    FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP EMEET_IN)) THEN
    SUBGOAL_THEN `!i. (v:num->A) i IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
    ASM_CASES_TAC `a0:num = x` THEN ASM_CASES_TAC `a1:num = x` THENL
     [ (* a0 = x, a1 = x : x %% x *)
      UNDISCH_THEN `a1:num = x` SUBST_ALL_TAC THEN
      UNDISCH_THEN `a0:num = x` SUBST_ALL_TAC THEN
      SUBGOAL_THEN `bvalf_HS D (E:A->A->bool) B leq w1 X ((x|->w)v)
          (x %% x) IN D /\
                    bvalf_HS D (E:A->A->bool) B leq w1 X
                        ((x|->t)v) (x %% x) IN D`
        STRIP_ASSUME_TAC THENL
       [CONJ_TAC THENL
         [MP_TAC(ISPECL[`x %% x`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                        `w1:A`;`X:A`;`(x|->w)(v:num->A)`] BVALF_HS_SPEC);
          MP_TAC(ISPECL[`x %% x`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                        `w1:A`;`X:A`;`(x|->t)(v:num->A)`] BVALF_HS_SPEC)] THEN
        ASM_REWRITE_TAC[] THEN STRIP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq w w
          (bvalf_HS D E B leq w1 X ((x|->w)v) (x %% x))`
        ASSUME_TAC THENL
       [MP_TAC(ISPECL[`x:num`;`x:num`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                      `w1:A`;`X:A`;`(x|->w)(v:num->A)`] BVALF_HS_MEM) THEN
        ASM_SIMP_TAC[VALMOD_BASIC]; ALL_TAC] THEN
      SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq t t
          (bvalf_HS D E B leq w1 X ((x|->t)v) (x %% x))`
        ASSUME_TAC THENL
       [MP_TAC(ISPECL[`x:num`;`x:num`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                      `w1:A`;`X:A`;`(x|->t)(v:num->A)`] BVALF_HS_MEM) THEN
        ASM_SIMP_TAC[VALMOD_BASIC]; ALL_TAC] THEN
      MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`t:A`;`w:A`]
             EBV_TOTAL) THEN
      ASM_REWRITE_TAC[] THEN
      DISCH_THEN(CONJUNCTS_THEN2 (X_CHOOSE_THEN `h:A` STRIP_ASSUME_TAC)
                 (K ALL_TAC)) THEN
      SUBGOAL_THEN `(E:A->A->bool) h B` ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`t:A`;
                            `w:A`;`h:A`] EBV_IN_IN_B) THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `?m2. emeet D (E:A->A->bool) B leq ewt h m2`
          (X_CHOOSE_THEN `m2:A` ASSUME_TAC) THENL
       [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ewt:A`;
                            `h:A`] EBALG_MEET) THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ewt:A`;`h:A`;
                    `m2:A`] EMEET_IN) THEN
      ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
      SUBGOAL_THEN `erel D (E:A->A->bool) leq m h` ASSUME_TAC THENL
