       [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
          `w:A`;`t:A`;`t:A`;`ewt:A`;`h:A`;
          `bvalf_HS D (E:A->A->bool) B leq w1 X ((x|->t)v) (x %% x)`;`m2:A`]
              EBV_IN_CONG_R) THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `erel D (E:A->A->bool) leq m m2` ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
          `ewt:A`;`h:A`;`m2:A`;`m:A`] EMEET_GREATEST) THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;`m2:A`;
        `bvalf_HS D (E:A->A->bool) B leq w1 X ((x|->t)v) (x %% x)`]
            EPORDER_TRANS) THEN
      ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC(ISPECL[`x %% x`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                          `w1:A`;`X:A`;`(x|->t)(v:num->A)`] BVALF_HS_IN_B) THEN
      ASM_REWRITE_TAC[];
      (* a0 = x, a1 <> x : x %% a1 *)
      UNDISCH_THEN `a0:num = x` SUBST_ALL_TAC THEN
      SUBGOAL_THEN `bvalf_HS D (E:A->A->bool) B leq w1 X ((x|->w)v)
          (x %% a1) IN D /\
                    bvalf_HS D (E:A->A->bool) B leq w1 X ((x|->t)v)
                        (x %% a1) IN D`
        STRIP_ASSUME_TAC THENL
       [CONJ_TAC THENL
         [MP_TAC(ISPECL[`x %% a1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                        `w1:A`;`X:A`;`(x|->w)(v:num->A)`] BVALF_HS_SPEC);
          MP_TAC(ISPECL[`x %% a1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                        `w1:A`;`X:A`;`(x|->t)(v:num->A)`] BVALF_HS_SPEC)] THEN
        ASM_REWRITE_TAC[] THEN STRIP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq w (v(a1:num))
          (bvalf_HS D E B leq w1 X ((x|->w)v) (x %% a1))`
        ASSUME_TAC THENL
       [MP_TAC(ISPECL[`x:num`;`a1:num`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                      `w1:A`;`X:A`;`(x|->w)(v:num->A)`] BVALF_HS_MEM) THEN
        ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER]; ALL_TAC] THEN
      SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq t (v(a1:num))
