        ASSUME_TAC THENL
       [MP_TAC(ISPECL[`a0:num`;`a1:num`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                      `leq:A`;`w1:A`;`X:A`;`(x|->t)(v:num->A)`]
           BVALF_HS_MEM) THEN
        ASM_SIMP_TAC[VALMOD_OTHER]; ALL_TAC] THEN
      SUBGOAL_THEN `bvalf_HS D (E:A->A->bool) B leq w1 X ((x|->t)v) (a0 %% a1) =
                    bvalf_HS D (E:A->A->bool) B leq w1 X ((x|->w)v) (a0 %% a1)`
        (fun th -> REWRITE_TAC[th]) THENL
       [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                            `v(a0:num):A`;`v(a1:num):A`;
          `bvalf_HS D (E:A->A->bool) B leq w1 X ((x|->t)v) (a0 %% a1)`;
          `bvalf_HS D (E:A->A->bool) B leq w1 X ((x|->w)v) (a0 %% a1)`]
              EBV_IN_UNIQUE) THEN
        ASM_REWRITE_TAC[]; ASM_REWRITE_TAC[]]];
    (* ============================ Eq i j ============================ *)
    (REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\
        eporder D (E:A->A->bool) B leq`
      STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) ewt B` ASSUME_TAC THENL
