            `m:A`] ETOP_GE) THEN
      ASM_REWRITE_TAC[];
      (* Eq x a1 *)
      UNDISCH_THEN `a0:num = x` SUBST_ALL_TAC THEN
      SUBGOAL_THEN `bvalf_HS D (E:A->A->bool) B leq w1 X ((x|->w)v)
          (Eq x a1) IN D /\
                    bvalf_HS D (E:A->A->bool) B leq w1 X ((x|->t)v)
                        (Eq x a1) IN D`
        STRIP_ASSUME_TAC THENL
       [CONJ_TAC THENL
         [MP_TAC(ISPECL[`Eq x a1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                        `w1:A`;`X:A`;`(x|->w)(v:num->A)`] BVALF_HS_SPEC);
          MP_TAC(ISPECL[`Eq x a1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                        `w1:A`;`X:A`;`(x|->t)(v:num->A)`] BVALF_HS_SPEC)] THEN
        ASM_REWRITE_TAC[] THEN STRIP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `ebv_eq D (E:A->A->bool) B leq w (v(a1:num))
          (bvalf_HS D E B leq w1 X ((x|->w)v) (Eq x a1))`
        ASSUME_TAC THENL
       [MP_TAC(ISPECL[`x:num`;`a1:num`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                      `w1:A`;`X:A`;`(x|->w)(v:num->A)`] BVALF_HS_EQ2) THEN
        ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER]; ALL_TAC] THEN
      SUBGOAL_THEN `ebv_eq D (E:A->A->bool) B leq t (v(a1:num))
          (bvalf_HS D E B leq w1 X ((x|->t)v) (Eq x a1))`
        ASSUME_TAC THENL
       [MP_TAC(ISPECL[`x:num`;`a1:num`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                      `w1:A`;`X:A`;`(x|->t)(v:num->A)`] BVALF_HS_EQ2) THEN
        ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER]; ALL_TAC] THEN
      MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `t:A`;`w:A`;`v(a1:num):A`;`ewt:A`;
        `bvalf_HS D (E:A->A->bool) B leq w1 X ((x|->w)v) (Eq x a1)`;
        `bvalf_HS D (E:A->A->bool) B leq w1 X ((x|->t)v) (Eq x a1)`;`m:A`]
            EBV_EQ_CONG) THEN
      ASM_REWRITE_TAC[];
      (* Eq a0 x *)
      UNDISCH_THEN `a1:num = x` SUBST_ALL_TAC THEN
      SUBGOAL_THEN `bvalf_HS D (E:A->A->bool) B leq w1 X ((x|->w)v)
          (Eq a0 x) IN D /\
                    bvalf_HS D (E:A->A->bool) B leq w1 X ((x|->t)v)
                        (Eq a0 x) IN D`
        STRIP_ASSUME_TAC THENL
       [CONJ_TAC THENL
         [MP_TAC(ISPECL[`Eq a0 x`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                        `w1:A`;`X:A`;`(x|->w)(v:num->A)`] BVALF_HS_SPEC);
          MP_TAC(ISPECL[`Eq a0 x`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                        `w1:A`;`X:A`;`(x|->t)(v:num->A)`] BVALF_HS_SPEC)] THEN
        ASM_REWRITE_TAC[] THEN STRIP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `ebv_eq D (E:A->A->bool) B leq (v(a0:num)) w
          (bvalf_HS D E B leq w1 X ((x|->w)v) (Eq a0 x))`
        ASSUME_TAC THENL
       [MP_TAC(ISPECL[`a0:num`;`x:num`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                      `w1:A`;`X:A`;`(x|->w)(v:num->A)`] BVALF_HS_EQ2) THEN
        ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER]; ALL_TAC] THEN
      SUBGOAL_THEN `ebv_eq D (E:A->A->bool) B leq (v(a0:num)) t
          (bvalf_HS D E B leq w1 X ((x|->t)v) (Eq a0 x))`
        ASSUME_TAC THENL
       [MP_TAC(ISPECL[`a0:num`;`x:num`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                      `w1:A`;`X:A`;`(x|->t)(v:num->A)`] BVALF_HS_EQ2) THEN
        ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER]; ALL_TAC] THEN
      SUBGOAL_THEN `emeet D (E:A->A->bool) B leq
          (bvalf_HS D E B leq w1 X ((x|->w)v) (Eq a0 x)) ewt m`
        ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ewt:A`;
          `bvalf_HS D (E:A->A->bool) B leq w1 X ((x|->w)v) (Eq a0 x)`;`m:A`]
              EMEET_SYM) THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `v(a0:num):A`;`w:A`;`t:A`;
        `bvalf_HS D (E:A->A->bool) B leq w1 X ((x|->w)v) (Eq a0 x)`;`ewt:A`;
        `bvalf_HS D (E:A->A->bool) B leq w1 X ((x|->t)v) (Eq a0 x)`;`m:A`]
            EBV_EQ_CONG) THEN
      ASM_REWRITE_TAC[];
      (* Eq a0 a1 (no dependence on x) *)
      SUBGOAL_THEN `bvalf_HS D (E:A->A->bool) B leq w1 X ((x|->w)v)
          (Eq a0 a1) IN D /\
                    bvalf_HS D (E:A->A->bool) B leq w1 X ((x|->t)v)
                        (Eq a0 a1) IN D`
        STRIP_ASSUME_TAC THENL
       [CONJ_TAC THENL
         [MP_TAC(ISPECL[`Eq a0 a1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                        `w1:A`;`X:A`;`(x|->w)(v:num->A)`] BVALF_HS_SPEC);
          MP_TAC(ISPECL[`Eq a0 a1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                        `w1:A`;`X:A`;`(x|->t)(v:num->A)`] BVALF_HS_SPEC)] THEN
        ASM_REWRITE_TAC[] THEN STRIP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `ebv_eq D (E:A->A->bool) B leq (v(a0:num)) (v(a1:num))
          (bvalf_HS D E B leq w1 X ((x|->w)v) (Eq a0 a1))`
        ASSUME_TAC THENL
       [MP_TAC(ISPECL[`a0:num`;`a1:num`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                      `leq:A`;`w1:A`;`X:A`;`(x|->w)(v:num->A)`]
           BVALF_HS_EQ2) THEN
        ASM_SIMP_TAC[VALMOD_OTHER]; ALL_TAC] THEN
      SUBGOAL_THEN `ebv_eq D (E:A->A->bool) B leq (v(a0:num)) (v(a1:num))
          (bvalf_HS D E B leq w1 X ((x|->t)v) (Eq a0 a1))`
        ASSUME_TAC THENL
       [MP_TAC(ISPECL[`a0:num`;`a1:num`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                      `leq:A`;`w1:A`;`X:A`;`(x|->t)(v:num->A)`]
           BVALF_HS_EQ2) THEN
        ASM_SIMP_TAC[VALMOD_OTHER]; ALL_TAC] THEN
      SUBGOAL_THEN `bvalf_HS D (E:A->A->bool) B leq w1 X ((x|->t)v) (Eq a0 a1) =
                    bvalf_HS D (E:A->A->bool) B leq w1 X ((x|->w)v) (Eq a0 a1)`
        (fun th -> REWRITE_TAC[th]) THENL
       [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                            `v(a0:num):A`;`v(a1:num):A`;
          `bvalf_HS D (E:A->A->bool) B leq w1 X ((x|->t)v) (Eq a0 a1)`;
          `bvalf_HS D (E:A->A->bool) B leq w1 X ((x|->w)v) (Eq a0 a1)`]
              EBV_EQ_UNIQUE) THEN
        ASM_REWRITE_TAC[]; ASM_REWRITE_TAC[]]];
    (* ============================ p --> q ============================ *)
    X_GEN_TAC `a0:form` THEN X_GEN_TAC `a1:form` THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "IH0") (LABEL_TAC "IH1")) THEN
    (REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\
        eporder D (E:A->A->bool) B leq`
      STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) ewt B` ASSUME_TAC THENL
     [ASM_MESON_TAC[EBV_EQ_IN_B]; ALL_TAC] THEN
    SUBGOAL_THEN `bname D (E:A->A->bool) B w /\ bname D E B t /\
                  (!i. bname D (E:A->A->bool) B ((v:num->A) i))`
      STRIP_ASSUME_TAC THENL
     [REPEAT CONJ_TAC THENL
       [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
        ASM_REWRITE_TAC[];
        MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
        ASM_REWRITE_TAC[];
        GEN_TAC THEN MATCH_MP_TAC HSNAME_BNAME THEN
        MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN ASM_REWRITE_TAC[] THEN
        ASM_MESON_TAC[valuation]];
      ALL_TAC] THEN
    SUBGOAL_THEN
      `(valuation D ((x |-> w) (v:num->A)) /\
        (!i. hsname D (E:A->A->bool) B w1 X (((x |-> w) (v:num->A)) i))) /\
       (valuation D ((x |-> t) (v:num->A)) /\
        (!i. hsname D (E:A->A->bool) B w1 X (((x |-> t) (v:num->A)) i)))`
      STRIP_ASSUME_TAC THENL
     [REPEAT CONJ_TAC THEN
      (MATCH_MP_TAC VALUATION_VALMOD ORELSE MATCH_MP_TAC HSNAMEVAL_VALMOD) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
      `(!i. bname D (E:A->A->bool) B (((x |-> w) (v:num->A)) i)) /\
       (!i. bname D (E:A->A->bool) B (((x |-> t) (v:num->A)) i))`
      STRIP_ASSUME_TAC THENL
     [CONJ_TAC THEN MATCH_MP_TAC BNAMEVAL_VALMOD THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP EMEET_LE) THEN
    FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP EMEET_IN)) THEN
    SUBGOAL_THEN `!i. (v:num->A) i IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
    SUBGOAL_THEN `ebv_eq D (E:A->A->bool) B leq t w ewt` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;`t:A`;
                          `ewt:A`] EBV_EQ_SYM) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
      `ebimp D (E:A->A->bool) B leq
         (bvalf_HS D E B leq w1 X ((x|->w)v) a0)
             (bvalf_HS D E B leq w1 X ((x|->w)v) a1)
         (bvalf_HS D E B leq w1 X ((x|->w)v) (a0 --> a1))` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`a0:form`;`a1:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                          `leq:A`;`w1:A`;`X:A`;`(x|->w)(v:num->A)`]
         BVALF_HS_IMP) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
      `ebimp D (E:A->A->bool) B leq
         (bvalf_HS D E B leq w1 X ((x|->t)v) a0)
             (bvalf_HS D E B leq w1 X ((x|->t)v) a1)
         (bvalf_HS D E B leq w1 X ((x|->t)v) (a0 --> a1))` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`a0:form`;`a1:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                          `leq:A`;`w1:A`;`X:A`;`(x|->t)(v:num->A)`]
         BVALF_HS_IMP) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
      `(bvalf_HS D (E:A->A->bool) B leq w1 X ((x|->w)v) a0 IN D /\
        E (bvalf_HS D E B leq w1 X ((x|->w)v) a0) B) /\
       (bvalf_HS D (E:A->A->bool) B leq w1 X ((x|->w)v) a1 IN D /\
        E (bvalf_HS D E B leq w1 X ((x|->w)v) a1) B) /\
       (bvalf_HS D (E:A->A->bool) B leq w1 X ((x|->t)v) a0 IN D /\
        E (bvalf_HS D E B leq w1 X ((x|->t)v) a0) B) /\
       (bvalf_HS D (E:A->A->bool) B leq w1 X ((x|->t)v) a1 IN D /\
        E (bvalf_HS D E B leq w1 X ((x|->t)v) a1) B)`
      STRIP_ASSUME_TAC THENL
     [REPEAT CONJ_TAC THEN
      (MATCH_MP_TAC BVALF_HS_IND ORELSE MATCH_MP_TAC BVALF_HS_IN_B) THEN
          ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `?z. emeet D (E:A->A->bool) B leq m
        (bvalf_HS D E B leq w1 X ((x|->t)v) a0) z`
      (X_CHOOSE_THEN `mm:A` ASSUME_TAC) THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;
                          `bvalf_HS D (E:A->A->bool) B leq w1 X ((x|->t)v) a0`]
         EBALG_MEET) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;
                  `bvalf_HS D (E:A->A->bool) B leq w1 X ((x|->t)v) a0`;
        `mm:A`] EMEET_IN) THEN
    ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
    SUBGOAL_THEN `?z. emeet D (E:A->A->bool) B leq ewt
        (bvalf_HS D E B leq w1 X ((x|->t)v) a0) z`
      (X_CHOOSE_THEN `m3:A` ASSUME_TAC) THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ewt:A`;
                          `bvalf_HS D (E:A->A->bool) B leq w1 X ((x|->t)v) a0`]
         EBALG_MEET) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ewt:A`;
                  `bvalf_HS D (E:A->A->bool) B leq w1 X ((x|->t)v) a0`;
        `m3:A`] EMEET_IN) THEN
    ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
    SUBGOAL_THEN `?z. emeet D (E:A->A->bool) B leq ewt
        (bvalf_HS D E B leq w1 X ((x|->w)v) a1) z`
      (X_CHOOSE_THEN `m6:A` ASSUME_TAC) THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ewt:A`;
                          `bvalf_HS D (E:A->A->bool) B leq w1 X ((x|->w)v) a1`]
         EBALG_MEET) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ewt:A`;
                  `bvalf_HS D (E:A->A->bool) B leq w1 X ((x|->w)v) a1`;
        `m6:A`] EMEET_IN) THEN
    ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
    SUBGOAL_THEN `?z. emeet D (E:A->A->bool) B leq mm
        (bvalf_HS D E B leq w1 X ((x|->w)v) a0) z`
      (X_CHOOSE_THEN `m5:A` ASSUME_TAC) THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mm:A`;
                          `bvalf_HS D (E:A->A->bool) B leq w1 X ((x|->w)v) a0`]
         EBALG_MEET) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mm:A`;
                  `bvalf_HS D (E:A->A->bool) B leq w1 X ((x|->w)v) a0`;
        `m5:A`] EMEET_IN) THEN
    ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
    SUBGOAL_THEN `bvalf_HS D (E:A->A->bool) B leq w1 X
        ((x|->w)v)(a0-->a1) IN D /\
                  E (bvalf_HS D E B leq w1 X ((x|->w)v)(a0-->a1)) B /\
                  bvalf_HS D E B leq w1 X ((x|->t)v)(a0-->a1) IN D /\
                  E (bvalf_HS D E B leq w1 X ((x|->t)v)(a0-->a1)) B`
      STRIP_ASSUME_TAC THENL
     [REPEAT CONJ_TAC THEN
      (MATCH_MP_TAC BVALF_HS_IND ORELSE MATCH_MP_TAC BVALF_HS_IN_B) THEN
          ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq mm mm` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mm:A`]
                   EPORDER_REFL) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;
                  `bvalf_HS D (E:A->A->bool) B leq w1 X ((x|->t)v) a0`;
        `mm:A`] EMEET_LE) THEN
    ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq mm ewt` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mm:A`;`m:A`;
                          `ewt:A`] EPORDER_TRANS) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq mm
        (bvalf_HS D E B leq w1 X ((x|->w)v)(a0-->a1))` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mm:A`;`m:A`;
                          `bvalf_HS D (E:A->A->bool) B leq w1 X
         ((x|->w)v)(a0-->a1)`] EPORDER_TRANS) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq m3
        (bvalf_HS D E B leq w1 X ((x|->w)v) a0)` ASSUME_TAC THENL
     [USE_THEN "IH0" (MATCH_MP_TAC o ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;
         `leq:A`;`w1:A`;`X:A`;`v:num->A`;`x:num`;`t:A`;`w:A`;
         `ewt:A`;`m3:A`]) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq mm m3` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ewt:A`;
                          `bvalf_HS D (E:A->A->bool) B leq w1 X ((x|->t)v) a0`;
         `m3:A`;`mm:A`] EMEET_GREATEST) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq mm
        (bvalf_HS D E B leq w1 X ((x|->w)v) a0)` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mm:A`;
                          `m3:A`;`bvalf_HS D (E:A->A->bool) B leq w1 X
         ((x|->w)v) a0`] EPORDER_TRANS) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq m5
        (bvalf_HS D E B leq w1 X ((x|->w)v) a1)` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mm:A`;
        `bvalf_HS D (E:A->A->bool) B leq w1 X ((x|->w)v) a0`;
            `bvalf_HS D (E:A->A->bool) B leq w1 X ((x|->w)v) a1`;
        `bvalf_HS D (E:A->A->bool) B leq w1 X ((x|->w)v)(a0-->a1)`;`m5:A`]
            EBIMP_MEET_LE) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq mm m5` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mm:A`;
                          `bvalf_HS D (E:A->A->bool) B leq w1 X ((x|->w)v) a0`;
         `m5:A`;`mm:A`] EMEET_GREATEST) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq mm
        (bvalf_HS D E B leq w1 X ((x|->w)v) a1)` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mm:A`;
                          `m5:A`;`bvalf_HS D (E:A->A->bool) B leq w1 X
         ((x|->w)v) a1`] EPORDER_TRANS) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq m6
        (bvalf_HS D E B leq w1 X ((x|->t)v) a1)` ASSUME_TAC THENL
     [USE_THEN "IH1" (MATCH_MP_TAC o ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;
         `leq:A`;`w1:A`;`X:A`;`v:num->A`;`x:num`;`w:A`;`t:A`;
         `ewt:A`;`m6:A`]) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq mm m6` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ewt:A`;
                          `bvalf_HS D (E:A->A->bool) B leq w1 X ((x|->w)v) a1`;
         `m6:A`;`mm:A`] EMEET_GREATEST) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq mm
        (bvalf_HS D E B leq w1 X ((x|->t)v) a1)` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mm:A`;
                          `m6:A`;`bvalf_HS D (E:A->A->bool) B leq w1 X
         ((x|->t)v) a1`] EPORDER_TRANS) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;
      `bvalf_HS D (E:A->A->bool) B leq w1 X ((x|->t)v) a0`;
          `bvalf_HS D (E:A->A->bool) B leq w1 X ((x|->t)v) a1`;
      `bvalf_HS D (E:A->A->bool) B leq w1 X ((x|->t)v)(a0-->a1)`;`mm:A`]
          EBIMP_LE_IMP) THEN
    ASM_REWRITE_TAC[];
    (* ============================ !! n p ============================ *)
    X_GEN_TAC `a0:num` THEN X_GEN_TAC `a1:form` THEN
        DISCH_THEN(LABEL_TAC "IHP") THEN
    (REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\
        eporder D (E:A->A->bool) B leq`
      STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) ewt B` ASSUME_TAC THENL
     [ASM_MESON_TAC[EBV_EQ_IN_B]; ALL_TAC] THEN
    SUBGOAL_THEN `bname D (E:A->A->bool) B w /\ bname D E B t /\
                  (!i. bname D (E:A->A->bool) B ((v:num->A) i))`
      STRIP_ASSUME_TAC THENL
     [REPEAT CONJ_TAC THENL
       [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
        ASM_REWRITE_TAC[];
        MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
        ASM_REWRITE_TAC[];
        GEN_TAC THEN MATCH_MP_TAC HSNAME_BNAME THEN
        MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN ASM_REWRITE_TAC[] THEN
        ASM_MESON_TAC[valuation]];
      ALL_TAC] THEN
    SUBGOAL_THEN
      `(valuation D ((x |-> w) (v:num->A)) /\
        (!i. hsname D (E:A->A->bool) B w1 X (((x |-> w) (v:num->A)) i))) /\
       (valuation D ((x |-> t) (v:num->A)) /\
        (!i. hsname D (E:A->A->bool) B w1 X (((x |-> t) (v:num->A)) i)))`
      STRIP_ASSUME_TAC THENL
     [REPEAT CONJ_TAC THEN
      (MATCH_MP_TAC VALUATION_VALMOD ORELSE MATCH_MP_TAC HSNAMEVAL_VALMOD) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
      `(!i. bname D (E:A->A->bool) B (((x |-> w) (v:num->A)) i)) /\
       (!i. bname D (E:A->A->bool) B (((x |-> t) (v:num->A)) i))`
      STRIP_ASSUME_TAC THENL
     [CONJ_TAC THEN MATCH_MP_TAC BNAMEVAL_VALMOD THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP EMEET_LE) THEN
    FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP EMEET_IN)) THEN
    SUBGOAL_THEN `!i. (v:num->A) i IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
    ASM_CASES_TAC `a0:num = x` THENL
     [ (* shadowed: a0 = x -- outer binder shadows x, no dependence *)
      UNDISCH_THEN `a0:num = x` SUBST_ALL_TAC THEN
      SUBGOAL_THEN `bvalf_HS D (E:A->A->bool) B leq w1 X ((x|->t)v)(!! x a1) =
          bvalf_HS D E B leq w1 X ((x|->w)v)(!! x a1)`
        ASSUME_TAC THENL
       [REWRITE_TAC[bvalf_HS] THEN AP_TERM_TAC THEN
        REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
        REWRITE_TAC[bval_HS] THEN REWRITE_TAC[VALMOD_VALMOD]; ALL_TAC] THEN
      ASM_REWRITE_TAC[];
      (* a0 <> x : genuine bound variable, use lower-bound + IHP *)
      SUBGOAL_THEN `bvalf_HS D (E:A->A->bool) B leq w1 X
          ((x|->w)v)(!! a0 a1) IN D /\
                    E (bvalf_HS D E B leq w1 X ((x|->w)v)(!! a0 a1)) B`
                        STRIP_ASSUME_TAC THENL
       [CONJ_TAC THENL [MATCH_MP_TAC BVALF_HS_IND; MATCH_MP_TAC BVALF_HS_IN_B]
        THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      MP_TAC(ISPECL[`!! a0 a1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                    `X:A`;`(x|->t)(v:num->A)`] BVALF_HS_SPEC) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN(MP_TAC o CONJUNCT2) THEN
          REWRITE_TAC[bval_HS] THEN
      DISCH_THEN(X_CHOOSE_THEN `St:A` (CONJUNCTS_THEN2 ASSUME_TAC
          (CONJUNCTS_THEN2 (LABEL_TAC "CHARt") ASSUME_TAC))) THEN
      MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`St:A`;
         `bvalf_HS D (E:A->A->bool) B leq w1 X ((x|->t)v)(!! a0 a1)`;`m:A`]
             EGLB_GREATEST) THEN
      ASM_REWRITE_TAC[] THEN REWRITE_TAC[elbound] THEN ASM_REWRITE_TAC[] THEN
      X_GEN_TAC `zz:A` THEN STRIP_TAC THEN
      USE_THEN "CHARt" (fun ch ->
        X_CHOOSE_THEN `a:A` STRIP_ASSUME_TAC
          (EQ_MP (MP (SPEC `zz:A` ch) (ASSUME `(zz:A) IN (D:A->bool)`))
                 (ASSUME `(E:A->A->bool) (zz:A) (St:A)`))) THEN
      SUBGOAL_THEN `valuation D ((a0|->a)(v:num->A)) /\
          (!i. hsname D (E:A->A->bool) B w1 X (((a0|->a)(v:num->A)) i))`
        STRIP_ASSUME_TAC THENL
       [CONJ_TAC THENL [MATCH_MP_TAC VALUATION_VALMOD;
                        MATCH_MP_TAC HSNAMEVAL_VALMOD] THEN
           ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN
        `(valuation D ((x|->t)((a0|->a)v)) /\
          (!i. hsname D (E:A->A->bool) B w1 X
           (((x|->t)((a0|->a)(v:num->A))) i))) /\
         (valuation D ((x|->w)((a0|->a)v)) /\
          (!i. hsname D (E:A->A->bool) B w1 X
           (((x|->w)((a0|->a)(v:num->A))) i)))`
        STRIP_ASSUME_TAC THENL
       [REPEAT CONJ_TAC THEN
        (MATCH_MP_TAC VALUATION_VALMOD ORELSE MATCH_MP_TAC HSNAMEVAL_VALMOD)
            THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      MP_TAC(ISPECL[`v:num->A`;`a0:num`;`x:num`;`a:A`;`t:A`] VALMOD_SWAP) THEN
          ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
      MP_TAC(ISPECL[`v:num->A`;`a0:num`;`x:num`;`a:A`;`w:A`] VALMOD_SWAP) THEN
          ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
      SUBGOAL_THEN `zz = bvalf_HS D (E:A->A->bool) B leq w1 X
          ((x|->t)((a0|->a)v)) a1` SUBST_ALL_TAC THENL
       [MATCH_MP_TAC(ISPECL[`a1:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                            `w1:A`;`X:A`;`(x|->t)((a0|->a)(v:num->A))`;`zz:A`]
           BVALF_HS_EQ) THEN
        ASM_REWRITE_TAC[] THEN
        UNDISCH_TAC `bval_HS D (E:A->A->bool) B leq w1 X
            ((a0|->a)((x|->t)v)) a1 zz` THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `erel D (E:A->A->bool) leq
          (bvalf_HS D E B leq w1 X ((x|->w)v)(!! a0 a1))
          (bvalf_HS D E B leq w1 X ((x|->w)((a0|->a)v)) a1)`
        ASSUME_TAC THENL
       [MP_TAC(ISPECL[`a0:num`;`a1:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                      `leq:A`;`w1:A`;`X:A`;`(x|->w)(v:num->A)`;`a:A`]
           BVALF_HS_ALL_LB) THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `bvalf_HS D (E:A->A->bool) B leq w1 X
          ((x|->w)((a0|->a)v)) a1 IN D /\
                    E (bvalf_HS D E B leq w1 X ((x|->w)((a0|->a)v)) a1) B`
                        STRIP_ASSUME_TAC THENL
       [CONJ_TAC THENL [MATCH_MP_TAC BVALF_HS_IND; MATCH_MP_TAC BVALF_HS_IN_B]
        THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `?z. emeet D (E:A->A->bool) B leq ewt
          (bvalf_HS D E B leq w1 X ((x|->w)((a0|->a)v)) a1) z`
        (X_CHOOSE_THEN `mya:A` ASSUME_TAC) THENL
       [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ewt:A`;
                            `bvalf_HS D (E:A->A->bool) B leq w1 X
           ((x|->w)((a0|->a)v)) a1`] EBALG_MEET) THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ewt:A`;
                    `bvalf_HS D (E:A->A->bool) B leq w1 X ((x|->w)((a0|->a)v))
          a1`;`mya:A`] EMEET_IN) THEN
      ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
      SUBGOAL_THEN `erel D (E:A->A->bool) leq ewt ewt` ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ewt:A`]
                     EPORDER_REFL) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `erel D (E:A->A->bool) leq m mya` ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ewt:A`;
          `bvalf_HS D (E:A->A->bool) B leq w1 X ((x|->w)v)(!! a0 a1)`;`ewt:A`;
          `bvalf_HS D (E:A->A->bool) B leq w1 X ((x|->w)((a0|->a)v)) a1`;`m:A`;
              `mya:A`] EMEET_MONO) THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `erel D (E:A->A->bool) leq mya
          (bvalf_HS D E B leq w1 X ((x|->t)((a0|->a)v)) a1)` ASSUME_TAC THENL
       [USE_THEN "IHP" (MATCH_MP_TAC o ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;
           `leq:A`;`w1:A`;`X:A`;`(a0|->a)(v:num->A)`;`x:num`;`w:A`;`t:A`;
           `ewt:A`;`mya:A`]) THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `E (bvalf_HS D (E:A->A->bool) B leq w1 X ((x|->t)((a0|->a)v))
                       a1) B` ASSUME_TAC THENL
       [MATCH_MP_TAC BVALF_HS_IN_B THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;
                          `mya:A`;`bvalf_HS D (E:A->A->bool) B leq w1 X
          ((x|->t)((a0|->a)v)) a1`] EPORDER_TRANS) THEN
      ASM_REWRITE_TAC[]]]);;

let MAXPRIN_LEIBNIZ_STEP_HS = prove
 (`!n p D (E:A->A->bool) B leq w1 X v a astar c eas.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
          w1 IN D /\ X IN D /\
      valuation D v /\ (!i. hsname D E B w1 X (v i)) /\
      a IN D /\ astar IN D /\ hsname D E B w1 X a /\ hsname D E B w1 X astar /\
      c IN D /\ E c B /\
      eas IN D /\ ebv_eq D E B leq a astar eas /\
      erel D E leq c eas /\
      erel D E leq c (bvalf_HS D E B leq w1 X ((n |-> a) v) p)
      ==> erel D E leq c (bvalf_HS D E B leq w1 X ((n |-> astar) v) p)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\ eporder D (E:A->A->bool) B leq`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) eas B` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `a:A`;`astar:A`;`eas:A`] EBV_EQ_IN_B) THEN
          ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((n |-> (a:A)) v) /\
                (!i. hsname D (E:A->A->bool) B w1 X (((n |-> (a:A)) v) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC HSNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((n |-> (astar:A)) v) /\
                (!i. hsname D (E:A->A->bool) B w1 X (((n |-> (astar:A)) v) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC HSNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN
    `(bvalf_HS D (E:A->A->bool) B leq w1 X ((n |-> (a:A)) v) p) IN D /\
     (E:A->A->bool) (bvalf_HS D E B leq w1 X ((n |-> (a:A)) v) p) B`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                     `leq:A`;`w1:A`;`X:A`;
        `(n |-> (a:A)) (v:num->A)`] BVALF_HS_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                     `leq:A`;`w1:A`;`X:A`;
        `(n |-> (a:A)) (v:num->A)`] BVALF_HS_IN_B) THEN
            ASM_SIMP_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN
    `(bvalf_HS D (E:A->A->bool) B leq w1 X ((n |-> (astar:A)) v) p) IN D /\
     (E:A->A->bool) (bvalf_HS D E B leq w1 X ((n |-> (astar:A)) v) p) B`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                     `leq:A`;`w1:A`;`X:A`;
        `(n |-> (astar:A)) (v:num->A)`] BVALF_HS_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                     `leq:A`;`w1:A`;`X:A`;
        `(n |-> (astar:A)) (v:num->A)`] BVALF_HS_IN_B) THEN
            ASM_SIMP_TAC[]]; ALL_TAC] THEN
  (* m = eas /\ [[p(a)]] *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`eas:A`;
    `bvalf_HS D (E:A->A->bool) B leq w1 X ((n |-> (a:A)) v) p`] EBALG_MEET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `m:A`) THEN
  SUBGOAL_THEN `(m:A) IN D /\ (E:A->A->bool) m B` STRIP_ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EMEET_IN); ALL_TAC] THEN
  (* c <= m *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq c m` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`eas:A`;
      `bvalf_HS D (E:A->A->bool) B leq w1 X ((n |-> (a:A)) v) p`;`m:A`;`c:A`]
      EMEET_GREATEST) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* m <= [[p(astar)]]  (Leibniz) *)
  SUBGOAL_THEN
    `erel D (E:A->A->bool) leq m (bvalf_HS D E B leq w1 X
        ((n |-> (astar:A)) v) p)`
  ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                         `leq:A`;`w1:A`;`X:A`;
      `v:num->A`;`n:num`;`a:A`;`astar:A`;`eas:A`;`m:A`] BVAL_SUBST_CONG_HS) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* c <= m <= [[p(astar)]] *)
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;`m:A`;
    `bvalf_HS D (E:A->A->bool) B leq w1 X ((n |-> (astar:A)) v) p`]
        EPORDER_TRANS) THEN
  ASM_REWRITE_TAC[]);;

(* ===================================================================== *)
(* H3.4a : COLL_L -- generic COLLECTION in a model of ZF + V=L.             *)
(* If every u IN a has a witness w with p(u,w), then one SET b contains a    *)
(* witness for every u: replacement along lrank_form ("0 = the least alpha  *)
(* such that some witness lies in L_alpha") + a stage L_(sup+1).  Formulas: *)
(* lach_form k s y p = "?Y = L_(v k) (slot s) ?w IN Y (slot y). p".          *)
(* ===================================================================== *)
let lach_form = new_definition
  `lach_form k s y p =
     ?? s (recapp_form (rec_form lstep_form 2) k s && ?? y ((y %% s) && p))`;;

let HOLDS_LACH_FORM = prove
 (`!D (E:A->A->bool) v k s y p.
     model D E ZF_AX /\ valuation D v /\
     ~(k = 2) /\ ~(k = 3) /\ ~(s = 2) /\ ~(s = 3) /\ ~(k = s) /\ ~(y = s) /\
     ~(s IN FV p)
     ==> (holds D E v (lach_form k s y p) <=>
          ?Y. Y IN D /\ elstage D E (v k) Y /\
              ?w. w IN D /\ E w Y /\ holds D E ((y |-> w) v) p)`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
             (CONJUNCTS_THEN2 (LABEL_TAC "vv")
              (CONJUNCTS_THEN2 (LABEL_TAC "k2")
               (CONJUNCTS_THEN2 (LABEL_TAC "k3")
                (CONJUNCTS_THEN2 (LABEL_TAC "s2")
                 (CONJUNCTS_THEN2 (LABEL_TAC "s3")
                  (CONJUNCTS_THEN2 (LABEL_TAC "ks")
                   (CONJUNCTS_THEN2 (LABEL_TAC "ys")
                    (LABEL_TAC "ns"))))))))) THEN
  USE_THEN "ys" (LABEL_TAC "sy" o GSYM) THEN
  REWRITE_TAC[lach_form; HOLDS_EX; HOLDS_AND] THEN
  MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s))
     ==> ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
  X_GEN_TAC `Y:A` THEN DISCH_THEN(LABEL_TAC "YD") THEN
  SUBGOAL_THEN `valuation D ((s:num |-> (Y:A)) (v:num->A))`
      (LABEL_TAC "vY") THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THEN
    FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`(s:num |-> (Y:A)) (v:num->A)`;
                `k:num`;`s:num`]
    HOLDS_RECAPP_LSTEP) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN
  ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER] THEN
  MATCH_MP_TAC(TAUT `(b <=> c) ==> (a /\ b <=> a /\ c)`) THEN
  REWRITE_TAC[HOLDS_EX; HOLDS_AND] THEN
  MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s))
     ==> ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
  X_GEN_TAC `w:A` THEN DISCH_TAC THEN
  REWRITE_TAC[holds] THEN
  ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; HOLDS_VALMOD_STRIP1]);;

let lrank_form = new_definition
  `lrank_form s t y p =
     ordinal_form 0 && lach_form 0 s y p && !!- t 0 (Not (lach_form t s y p))`;;

let HOLDS_LACH_AT = prove
 (`!D (E:A->A->bool) p x y s v u al.
     model D E ZF_AX /\ valuation D v /\ u IN D /\ al IN D /\
     ~(y = 0) /\ ~(s = 0) /\ ~(s = 2) /\ ~(s = 3) /\ ~(s = y) /\
     ~(0 IN FV p) /\ ~(s IN FV p)
     ==> (holds D E ((0 |-> al) ((x |-> u) v)) (lach_form 0 s y p) <=>
          (?Y. Y IN D /\ elstage D E al Y /\ ?w. w IN D /\ E w Y /\
           holds D E ((y |-> w) ((x |-> u) v)) p))`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
             (CONJUNCTS_THEN2 (LABEL_TAC "vv")
              (CONJUNCTS_THEN2 (LABEL_TAC "uD")
               (CONJUNCTS_THEN2 (LABEL_TAC "alD")
                (CONJUNCTS_THEN2 (LABEL_TAC "y0")
                 (CONJUNCTS_THEN2 (LABEL_TAC "s0")
                  (CONJUNCTS_THEN2 (LABEL_TAC "s2")
                   (CONJUNCTS_THEN2 (LABEL_TAC "s3")
                    (CONJUNCTS_THEN2 (LABEL_TAC "sy")
                     (CONJUNCTS_THEN2 (LABEL_TAC "n0")
                      (LABEL_TAC "ns"))))))))))) THEN
  SUBGOAL_THEN `valuation D ((0 |-> (al:A)) ((x:num |-> (u:A)) (v:num->A)))`
      (LABEL_TAC "v0") THENL
   [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC) THEN
    FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;
                `(0 |-> (al:A)) ((x:num |-> (u:A)) (v:num->A))`;
                `0`;`s:num`;`y:num`;`p:form`] HOLDS_LACH_FORM) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THENL
     [ARITH_TAC; ARITH_TAC; USE_THEN "s0" (ACCEPT_TAC o GSYM);
      USE_THEN "sy" (ACCEPT_TAC o GSYM)];
    DISCH_THEN SUBST1_TAC] THEN
  REWRITE_TAC[VALMOD_BASIC] THEN
  ASM_SIMP_TAC[HOLDS_VALMOD_STRIP1]);;

let HOLDS_LRANK_AT = prove
 (`!D (E:A->A->bool) p x y s t v u al.
     model D E ZF_AX /\ valuation D v /\ u IN D /\ al IN D /\
     ~(y = 0) /\
     ~(s = 0) /\ ~(s = 2) /\ ~(s = 3) /\ ~(s = y) /\ ~(s = t) /\
     ~(t = 0) /\ ~(t = 2) /\ ~(t = 3) /\ ~(t = y) /\
     ~(0 IN FV p) /\ ~(s IN FV p) /\ ~(t IN FV p)
     ==> (holds D E ((0 |-> al) ((x |-> u) v)) (lrank_form s t y p) <=>
          eordinal D E al /\ (?Y. Y IN D /\ elstage D E al Y /\ ?w. w IN D /\
                              E w Y /\ holds D E ((y |-> w) ((x |-> u) v)) p) /\
          (!c. c IN D /\ E c al ==> ~(?Y. Y IN D /\ elstage D E c Y /\
              ?w. w IN D /\ E w Y /\ holds D E ((y |-> w) ((x |-> u) v)) p)))`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
             (CONJUNCTS_THEN2 (LABEL_TAC "vv")
              (CONJUNCTS_THEN2 (LABEL_TAC "uD")
               (CONJUNCTS_THEN2 (LABEL_TAC "alD")
                (CONJUNCTS_THEN2 (LABEL_TAC "y0")
                 (CONJUNCTS_THEN2 (LABEL_TAC "s0")
                  (CONJUNCTS_THEN2 (LABEL_TAC "s2")
                   (CONJUNCTS_THEN2 (LABEL_TAC "s3")
                    (CONJUNCTS_THEN2 (LABEL_TAC "sy")
                     (CONJUNCTS_THEN2 (LABEL_TAC "st")
                      (CONJUNCTS_THEN2 (LABEL_TAC "t0")
                       (CONJUNCTS_THEN2 (LABEL_TAC "t2")
                        (CONJUNCTS_THEN2 (LABEL_TAC "t3")
                         (CONJUNCTS_THEN2 (LABEL_TAC "ty")
                          (CONJUNCTS_THEN2 (LABEL_TAC "n0")
      (CONJUNCTS_THEN2 (LABEL_TAC "ns") (LABEL_TAC "nt"))))))))))))))))) THEN
  SUBGOAL_THEN `valuation D ((0 |-> (al:A)) ((x:num |-> (u:A)) (v:num->A)))`
      (LABEL_TAC "v0") THENL
   [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC) THEN
    FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  REWRITE_TAC[lrank_form; HOLDS_AND] THEN
  MATCH_MP_TAC(TAUT `(a <=> a') /\ (b <=> b') /\ (c <=> c')
                     ==> (a /\ b /\ c <=> a' /\ b' /\ c')`) THEN
  REPEAT CONJ_TAC THENL
   [ASM_SIMP_TAC[HOLDS_ORDINAL_FORM; VALMOD_BASIC];
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`p:form`;`x:num`;`y:num`;`s:num`;
                  `v:num->A`;`u:A`;`al:A`] HOLDS_LACH_AT) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;
                `(0 |-> (al:A)) ((x:num |-> (u:A)) (v:num->A))`;
                `t:num`;`0`;`Not (lach_form t s y (p:form))`]
                    HOLDS_FORALLMEM) THEN
  ANTS_TAC THENL [USE_THEN "t0" ACCEPT_TAC; DISCH_THEN SUBST1_TAC] THEN
  REWRITE_TAC[VALMOD_BASIC; HOLDS_NOT] THEN
  MATCH_MP_TAC(MESON[]
    `(!c:A. Ac c ==> (P c <=> Q c))
     ==> ((!c. Ac c ==> ~P c) <=> (!c. Ac c ==> ~Q c))`) THEN
  X_GEN_TAC `c:A` THEN DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "cD")
      (LABEL_TAC "cal")) THEN
  SUBGOAL_THEN `valuation D ((t:num |-> (c:A))
      ((0 |-> (al:A)) ((x:num |-> (u:A)) (v:num->A))))`
    (LABEL_TAC "vt") THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THEN
    FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;
                `(t:num |-> (c:A)) ((0 |-> (al:A))
                                    ((x:num |-> (u:A)) (v:num->A)))`;
                `t:num`;`s:num`;`y:num`;`p:form`] HOLDS_LACH_FORM) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THENL
     [USE_THEN "st" (ACCEPT_TAC o GSYM); USE_THEN "sy" (ACCEPT_TAC o GSYM)];
    DISCH_THEN SUBST1_TAC] THEN
  REWRITE_TAC[VALMOD_BASIC] THEN
  ASM_SIMP_TAC[HOLDS_VALMOD_STRIP1]);;

let COLL_L = prove
 (`!D (E:A->A->bool) p x y s t v a.
     model D E ZF_AX /\ (!u. u IN D ==> elmem D E u) /\
     valuation D v /\ a IN D /\
     ~(x = y) /\ ~(x = 0) /\ ~(y = 0) /\
     ~(s = 0) /\ ~(s = 2) /\ ~(s = 3) /\ ~(s = y) /\ ~(s = t) /\
     ~(t = 0) /\ ~(t = 2) /\ ~(t = 3) /\ ~(t = y) /\
     ~(0 IN FV p) /\ ~(s IN FV p) /\ ~(t IN FV p) /\
     (!u. u IN D /\ E u a
          ==> ?w. w IN D /\ holds D E ((y |-> w) ((x |-> u) v)) p)
     ==> ?b. b IN D /\
             !u. u IN D /\ E u a
                 ==> ?w. w IN D /\ E w b /\ holds D E
                     ((y |-> w) ((x |-> u) v)) p`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
             (CONJUNCTS_THEN2 (LABEL_TAC "vl")
              (CONJUNCTS_THEN2 (LABEL_TAC "vv")
               (CONJUNCTS_THEN2 (LABEL_TAC "aD")
                (CONJUNCTS_THEN2 (LABEL_TAC "xy")
                 (CONJUNCTS_THEN2 (LABEL_TAC "x0")
                  (CONJUNCTS_THEN2 (LABEL_TAC "y0")
                   (CONJUNCTS_THEN2 (LABEL_TAC "s0")
                    (CONJUNCTS_THEN2 (LABEL_TAC "s2")
                     (CONJUNCTS_THEN2 (LABEL_TAC "s3")
                      (CONJUNCTS_THEN2 (LABEL_TAC "sy")
                       (CONJUNCTS_THEN2 (LABEL_TAC "st")
                        (CONJUNCTS_THEN2 (LABEL_TAC "t0")
                         (CONJUNCTS_THEN2 (LABEL_TAC "t2")
                          (CONJUNCTS_THEN2 (LABEL_TAC "t3")
      (CONJUNCTS_THEN2 (LABEL_TAC "ty") (CONJUNCTS_THEN2 (LABEL_TAC "n0")
      (CONJUNCTS_THEN2 (LABEL_TAC "ns") (CONJUNCTS_THEN2 (LABEL_TAC "nt")
      (LABEL_TAC "tot")))))))))))))))))))) THEN
  (* semantics of lrank / lach at (0 |-> al)((x |-> u) v) *)
  SUBGOAL_THEN
   `!u al:A. u IN D /\ al IN D
             ==> (holds D (E:A->A->bool) ((0 |-> al) ((x |-> u) v))
                  (lrank_form s t y p) <=>
                  eordinal D E al /\ (?Y. Y IN D /\ elstage D E al Y /\
                                      ?w. w IN D /\ E w Y /\
                      holds D E ((y |-> w) ((x |-> u) v)) p) /\
                  (!c. c IN D /\ E c al ==> ~(?Y. Y IN D /\ elstage D E c Y /\
                      ?w. w IN D /\ E w Y /\ holds D E
                      ((y |-> w) ((x |-> u) v)) p)))`
   (LABEL_TAC "lrk") THENL
   [MAP_EVERY X_GEN_TAC [`u:A`;`al:A`] THEN STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`p:form`;`x:num`;`y:num`;
                  `s:num`;`t:num`;
                  `v:num->A`;`u:A`;`al:A`] HOLDS_LRANK_AT) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!u al:A. u IN D /\ al IN D
             ==> (holds D (E:A->A->bool) ((0 |-> al) ((x |-> u) v))
                  (lach_form 0 s y p) <=>
                  (?Y. Y IN D /\ elstage D E al Y /\ ?w. w IN D /\ E w Y /\
                   holds D E ((y |-> w) ((x |-> u) v)) p))`
   (LABEL_TAC "lch") THENL
   [MAP_EVERY X_GEN_TAC [`u:A`;`al:A`] THEN STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`p:form`;`x:num`;`y:num`;`s:num`;
                  `v:num->A`;`u:A`;`al:A`] HOLDS_LACH_AT) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  (* every u IN a has a least such ordinal *)
  SUBGOAL_THEN
   `!u:A. u IN D /\ E u a
          ==> ?al. al IN D /\
                   holds D (E:A->A->bool) ((0 |-> al) ((x |-> u) v))
                       (lrank_form s t y p)`
   (LABEL_TAC "least") THENL
   [X_GEN_TAC `u:A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "uD") (LABEL_TAC "ua")) THEN
    USE_THEN "tot" (MP_TAC o SPEC `u:A`) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `w0:A` (CONJUNCTS_THEN2 (LABEL_TAC "w0D")
        (LABEL_TAC "pw0"))) THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w0:A`] ELMEM_RANK) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      USE_THEN "vl" (MP_TAC o SPEC `w0:A`) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `a0:A` (CONJUNCTS_THEN2 (LABEL_TAC "a0D")
        (CONJUNCTS_THEN2 (LABEL_TAC "a0ord")
         (CONJUNCTS_THEN2 (X_CHOOSE_THEN `Y0:A`
                           (CONJUNCTS_THEN2 (LABEL_TAC "Y0D")
                            (CONJUNCTS_THEN2 (LABEL_TAC "lsY0")
        (LABEL_TAC "w0Y0")))) (K ALL_TAC))))) THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`lach_form 0 s y (p:form)`;
                  `(x:num |-> (u:A)) (v:num->A)`;`a0:A`] EORDINAL_LEAST) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THENL
      [MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
       USE_THEN "lch" (MP_TAC o SPECL [`u:A`;`a0:A`]) THEN
       ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                       DISCH_THEN SUBST1_TAC] THEN
       EXISTS_TAC `Y0:A` THEN REPEAT CONJ_TAC THEN
           TRY(FIRST_ASSUM ACCEPT_TAC) THEN
       EXISTS_TAC `w0:A` THEN REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC];
      ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `d:A` (CONJUNCTS_THEN2 (LABEL_TAC "dD")
        (CONJUNCTS_THEN2 (LABEL_TAC "dord")
         (CONJUNCTS_THEN2 (LABEL_TAC "dla") (LABEL_TAC "dmin"))))) THEN
    EXISTS_TAC `d:A` THEN CONJ_TAC THENL
        [USE_THEN "dD" ACCEPT_TAC; ALL_TAC] THEN
    USE_THEN "lrk" (MP_TAC o SPECL [`u:A`;`d:A`]) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN SUBST1_TAC] THEN
    CONJ_TAC THENL [USE_THEN "dord" ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL
     [USE_THEN "lch" (MP_TAC o SPECL [`u:A`;`d:A`]) THEN
      ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> USE_THEN "dla" (ACCEPT_TAC o EQ_MP th));
      X_GEN_TAC `c:A` THEN DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "cD")
          (LABEL_TAC "cd")) THEN
      USE_THEN "dmin" (MP_TAC o SPEC `c:A`) THEN
      ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      USE_THEN "lch" (MP_TAC o SPECL [`u:A`;`c:A`]) THEN
      ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th])];
    ALL_TAC] THEN
  (* uniqueness *)
  SUBGOAL_THEN
   `!u al al':A. u IN D /\ al IN D /\ al' IN D /\
                 holds D (E:A->A->bool) ((0 |-> al) ((x |-> u) v))
                     (lrank_form s t y p) /\
                 holds D (E:A->A->bool) ((0 |-> al') ((x |-> u) v))
                     (lrank_form s t y p)
                 ==> al' = al`
   (LABEL_TAC "uniq") THENL
   [MAP_EVERY X_GEN_TAC [`u:A`;`al:A`;`al':A`] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "uD")
               (CONJUNCTS_THEN2 (LABEL_TAC "alD")
                (CONJUNCTS_THEN2 (LABEL_TAC "al'D")
                 (CONJUNCTS_THEN2 (LABEL_TAC "h1") (LABEL_TAC "h2"))))) THEN
    USE_THEN "lrk" (MP_TAC o SPECL [`u:A`;`al:A`]) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "h1" (MP_TAC o EQ_MP th)) THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "o1")
               (CONJUNCTS_THEN2 (LABEL_TAC "la1") (LABEL_TAC "m1"))) THEN
    USE_THEN "lrk" (MP_TAC o SPECL [`u:A`;`al':A`]) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "h2" (MP_TAC o EQ_MP th)) THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "o2")
               (CONJUNCTS_THEN2 (LABEL_TAC "la2") (LABEL_TAC "m2"))) THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`al:A`;`al':A`]
           EORDINAL_TRICHOTOMY) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN ASSUME_TAC) THENL
     [USE_THEN "m2" (MP_TAC o SPEC `al:A`) THEN
      ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      USE_THEN "la1" (fun th -> REWRITE_TAC[th]);
      FIRST_X_ASSUM(ACCEPT_TAC o SYM o check (is_eq o concl));
      USE_THEN "m1" (MP_TAC o SPEC `al':A`) THEN
      ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      USE_THEN "la2" (fun th -> REWRITE_TAC[th])];
    ALL_TAC] THEN
  (* replacement: the set A of these least ordinals *)
  USE_THEN "modl" (MP_TAC o SPECL [`lrank_form s t y (p:form)`;`x:num`;`0`;
      `v:num->A`;`a:A`] o
                   MATCH_MP ZF_REPLACEMENT) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    X_GEN_TAC `u:A` THEN DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "uD")
        (LABEL_TAC "ua")) THEN
    USE_THEN "least" (MP_TAC o SPEC `u:A`) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `al:A` (CONJUNCTS_THEN2 (LABEL_TAC "alD")
        (LABEL_TAC "alr"))) THEN
    EXISTS_TAC `al:A` THEN CONJ_TAC THENL
        [USE_THEN "alD" ACCEPT_TAC; ALL_TAC] THEN
    X_GEN_TAC `al':A` THEN DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "al'D")
        (LABEL_TAC "al'r")) THEN
    USE_THEN "uniq" (MP_TAC o SPECL [`u:A`;`al:A`;`al':A`]) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `A0:A` (CONJUNCTS_THEN2 (LABEL_TAC "A0D")
      (LABEL_TAC "A0ch"))) THEN
  SUBGOAL_THEN `!al:A. al IN D /\ E al A0
      ==> eordinal D (E:A->A->bool) al` (LABEL_TAC "A0ord") THENL
   [X_GEN_TAC `al:A` THEN DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "alD")
       (LABEL_TAC "alA")) THEN
    USE_THEN "A0ch" (MP_TAC o SPEC `al:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "alA" (MP_TAC o EQ_MP th)) THEN
    DISCH_THEN(X_CHOOSE_THEN `u:A` (CONJUNCTS_THEN2 (LABEL_TAC "uD")
        (CONJUNCTS_THEN2 (LABEL_TAC "ua") (LABEL_TAC "ur")))) THEN
    USE_THEN "lrk" (MP_TAC o SPECL [`u:A`;`al:A`]) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "ur" (MP_TAC o EQ_MP th)) THEN
    DISCH_THEN(ACCEPT_TAC o CONJUNCT1);
    ALL_TAC] THEN
  (* lam = union A0, mu = esuc lam, Ymu = L_mu *)
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`A0:A`] EUNION_EXISTS) THEN
  ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `lam:A` (LABEL_TAC "lamu")) THEN
  SUBGOAL_THEN `(lam:A) IN D` (LABEL_TAC "lamD") THENL
   [USE_THEN "lamu" (ACCEPT_TAC o CONJUNCT1 o
                     REWRITE_RULE[eunion]); ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) lam` (LABEL_TAC "lamord") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`A0:A`;`lam:A`]
           EORDINAL_EUNION) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`lam:A`] ESUC_EXISTS) THEN
  ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `mu:A` (LABEL_TAC "musuc")) THEN
  SUBGOAL_THEN `(mu:A) IN D` (LABEL_TAC "muD") THENL
   [USE_THEN "musuc" (ACCEPT_TAC o MATCH_MP ESUC_IN); ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) mu` (LABEL_TAC "muord") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`lam:A`;`mu:A`] EORDINAL_ESUC) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`mu:A`] ELSTAGE_EXISTS) THEN
  ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `Ymu:A` (CONJUNCTS_THEN2 (LABEL_TAC "YmuD")
      (LABEL_TAC "lsmu"))) THEN
  EXISTS_TAC `Ymu:A` THEN CONJ_TAC THENL
      [USE_THEN "YmuD" ACCEPT_TAC; ALL_TAC] THEN
  X_GEN_TAC `u:A` THEN DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "uD")
      (LABEL_TAC "ua")) THEN
  USE_THEN "least" (MP_TAC o SPEC `u:A`) THEN
  ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `al:A` (CONJUNCTS_THEN2 (LABEL_TAC "alD")
      (LABEL_TAC "alr"))) THEN
  USE_THEN "lrk" (MP_TAC o SPECL [`u:A`;`al:A`]) THEN
  ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> USE_THEN "alr" (MP_TAC o EQ_MP th)) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "alord")
             (CONJUNCTS_THEN2 (X_CHOOSE_THEN `Y:A`
      (CONJUNCTS_THEN2 (LABEL_TAC "YD") (CONJUNCTS_THEN2 (LABEL_TAC "lsY")
      (X_CHOOSE_THEN `w:A` (CONJUNCTS_THEN2 (LABEL_TAC "wD")
      (CONJUNCTS_THEN2 (LABEL_TAC "wY") (LABEL_TAC "pw")))))))
      (K ALL_TAC))) THEN
  (* al IN A0, so al SUBSET lam, so al IN mu *)
  SUBGOAL_THEN `(E:A->A->bool) al A0` (LABEL_TAC "alA0") THENL
   [USE_THEN "A0ch" (MP_TAC o SPEC `al:A`) THEN
    ANTS_TAC THENL [USE_THEN "alD" ACCEPT_TAC;
                    DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
    EXISTS_TAC `u:A` THEN REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) al mu` (LABEL_TAC "almu") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`lam:A`;`mu:A`;`al:A`] ESUC_E) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN SUBST1_TAC] THEN
    ASM_CASES_TAC `al:A = lam` THENL [DISJ2_TAC THEN FIRST_ASSUM ACCEPT_TAC;
        DISJ1_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`lam:A`;`al:A`]
           EORDINAL_TRANS_SUBSET) THEN
    ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THENL
     [USE_THEN "alord" (ACCEPT_TAC o CONJUNCT1 o CONJUNCT2 o
                        REWRITE_RULE[eordinal]);
      REWRITE_TAC[esubset] THEN X_GEN_TAC `g:A` THEN
      DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "gD") (LABEL_TAC "gal")) THEN
      USE_THEN "lamu" (MP_TAC o SPEC `g:A` o CONJUNCT2 o
                       REWRITE_RULE[eunion]) THEN
      ANTS_TAC THENL [USE_THEN "gD" ACCEPT_TAC; DISCH_THEN SUBST1_TAC] THEN
      EXISTS_TAC `al:A` THEN REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC];
    ALL_TAC] THEN
  EXISTS_TAC `w:A` THEN REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`mu:A`;`al:A`;`Ymu:A`;`Y:A`;`w:A`]
         ELSTAGE_MONO) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                  DISCH_THEN ACCEPT_TAC]);;

let BVALF_HS_EX_LEAST = prove
 (`!n p D (E:A->A->bool) B leq w1 X v w0.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
          w1 IN D /\ X IN D /\
      valuation D v /\ (!i. hsname D E B w1 X (v i)) /\
      w0 IN D /\ E w0 B /\
      (!a. a IN D /\ hsname D E B w1 X a
           ==> erel D E leq (bvalf_HS D E B leq w1 X ((n |-> a) v) p) w0)
      ==> erel D E leq (bvalf_HS D E B leq w1 X v (?? n p)) w0`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  REWRITE_TAC[Exists_DEF] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w0:A`]
         EBALG_COMPL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `cw0:A`) THEN
  SUBGOAL_THEN `(cw0:A) IN D /\ (E:A->A->bool) cw0 B` STRIP_ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP ECOMPL_IN); ALL_TAC] THEN
  MP_TAC(ISPECL [`!! n (Not p)`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                 `X:A`;`v:num->A`]
    BVALF_HS_NOT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
  SUBGOAL_THEN `(bvalf_HS D (E:A->A->bool) B leq w1 X v (!! n (Not p))) IN D /\
                (E:A->A->bool) (bvalf_HS D E B leq w1 X v (!! n (Not p))) B`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL [`!! n (Not p)`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                     `w1:A`;`X:A`;`v:num->A`] BVALF_HS_SPEC) THEN
         ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`!! n (Not p)`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                     `w1:A`;`X:A`;`v:num->A`] BVALF_HS_IN_B) THEN
          ASM_SIMP_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN `(bvalf_HS D (E:A->A->bool) B leq w1 X v
                 (Not(!! n (Not p)))) IN D /\
                (E:A->A->bool) (bvalf_HS D E B leq w1 X v
                                (Not(!! n (Not p)))) B`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL [`Not(!! n (Not p))`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                     `leq:A`;`w1:A`;`X:A`;`v:num->A`] BVALF_HS_SPEC) THEN
         ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`Not(!! n (Not p))`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                     `leq:A`;`w1:A`;`X:A`;`v:num->A`] BVALF_HS_IN_B) THEN
          ASM_SIMP_TAC[]]; ALL_TAC] THEN
  MP_TAC(ISPECL [`!! n (Not p)`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                 `X:A`;`v:num->A`]
    BVALF_HS_SPEC) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o CONJUNCT2) THEN REWRITE_TAC[bval_HS] THEN
  DISCH_THEN(X_CHOOSE_THEN `S:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 (LABEL_TAC "Schar") ASSUME_TAC))) THEN
  SUBGOAL_THEN `elbound D (E:A->A->bool) B leq S cw0` ASSUME_TAC THENL
   [REWRITE_TAC[elbound] THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `zz:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `?a:A. a IN D /\ hsname D (E:A->A->bool) B w1 X a /\
                        bval_HS D E B leq w1 X ((n |-> a) v) (Not p) zz`
    (X_CHOOSE_THEN `a:A` STRIP_ASSUME_TAC) THENL
     [USE_THEN "Schar" (MP_TAC o SPEC `zz:A`) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN FIRST_ASSUM ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `valuation D ((n |-> (a:A)) (v:num->A)) /\
                  (!i. hsname D E B w1 X (((n |-> (a:A)) (v:num->A)) i))`
    STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC HSNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
    SUBGOAL_THEN `zz:A = bvalf_HS D (E:A->A->bool) B leq w1 X
        ((n |-> (a:A)) (v:num->A)) (Not p)`
    SUBST_ALL_TAC THENL
     [MATCH_MP_TAC BVALF_HS_EQ THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                   `leq:A`;`w1:A`;`X:A`;
      `(n |-> (a:A)) (v:num->A)`] BVALF_HS_NOT) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
    SUBGOAL_THEN `(bvalf_HS D (E:A->A->bool) B leq w1 X
                   ((n |-> (a:A)) (v:num->A)) p) IN D /\
                  (E:A->A->bool) (bvalf_HS D E B leq w1 X
                                  ((n |-> (a:A)) (v:num->A)) p) B`
    STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                       `X:A`;`(n |-> (a:A)) (v:num->A)`] BVALF_HS_SPEC) THEN
           ASM_SIMP_TAC[];
        MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                       `X:A`;`(n |-> (a:A)) (v:num->A)`] BVALF_HS_IN_B) THEN
            ASM_SIMP_TAC[]]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq
        (bvalf_HS D E B leq w1 X ((n |-> (a:A)) (v:num->A)) p) w0`
            ASSUME_TAC THENL
     [FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `bvalf_HS D (E:A->A->bool) B leq w1 X
          ((n |-> (a:A)) (v:num->A)) p`;`w0:A`;
      `bvalf_HS D (E:A->A->bool) B leq w1 X ((n |-> (a:A)) (v:num->A))
          (Not p)`;`cw0:A`]
      ECOMPL_ANTITONE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq cw0
      (bvalf_HS D E B leq w1 X v (!! n (Not p)))`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`S:A`;
      `bvalf_HS D (E:A->A->bool) B leq w1 X v (!! n (Not p))`;`cw0:A`]
          EGLB_GREATEST) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `ecompl D (E:A->A->bool) B leq cw0 w0` ASSUME_TAC THENL
   [MATCH_MP_TAC ECOMPL_SYM THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
    `cw0:A`;`bvalf_HS D (E:A->A->bool) B leq w1 X v (!! n (Not p))`;`w0:A`;
    `bvalf_HS D (E:A->A->bool) B leq w1 X v (Not(!! n (Not p)))`]
        ECOMPL_ANTITONE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]);;

(* H3.4b : HSVAL_ATTAIN -- a SET Is of HS names attaining every HS value   *)
(* [[p]]^HS_{(n|->a)v} (a HS).  Value set SS by separation (as in          *)
(* BVAL_HS_TOTAL); COLL_L along the bound formula ?0 ?6 ?7 (hsname && fp)   *)
(* (binding 0,6,7 discharges COLL_L's freshness side conditions -- the      *)
(* formula fp of BVAL_HS_DEFINABLE is only known semantically); Is = the HS  *)
(* members of the collected set.                                            *)
let HSVAL_ATTAIN = prove
 (`!n p D (E:A->A->bool) B leq w1 X v.
     model D E ZF_AX /\ (!u. u IN D ==> elmem D E u) /\
     ecba D E B leq /\ B IN D /\ leq IN D /\ w1 IN D /\ X IN D /\
     valuation D v /\ (!i. hsname D E B w1 X (v i))
     ==> ?Is. Is IN D /\ (!q. q IN D /\ E q Is ==> hsname D E B w1 X q) /\
             (!a. a IN D /\ hsname D E B w1 X a
                  ==> ?q. q IN D /\ E q Is /\
                          bvalf_HS D E B leq w1 X ((n |-> q) v) p =
                          bvalf_HS D E B leq w1 X ((n |-> a) v) p)`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
             (CONJUNCTS_THEN2 (LABEL_TAC "vl")
              (CONJUNCTS_THEN2 (LABEL_TAC "cba")
               (CONJUNCTS_THEN2 (LABEL_TAC "BD")
                (CONJUNCTS_THEN2 (LABEL_TAC "leqD")
                 (CONJUNCTS_THEN2 (LABEL_TAC "w1D")
                  (CONJUNCTS_THEN2 (LABEL_TAC "XD")
                   (CONJUNCTS_THEN2 (LABEL_TAC "vv")
                    (LABEL_TAC "hsv"))))))))) THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` (LABEL_TAC "vD") THENL
   [USE_THEN "vv" (ACCEPT_TAC o REWRITE_RULE[valuation]); ALL_TAC] THEN
  X_CHOOSE_TAC `fp:form` (ISPECL [`p:form`; `5`; `3`] BVAL_HS_DEFINABLE) THEN
  ABBREV_TAC `w0 = (9 |-> (X:A)) ((8 |-> (w1:A))
      ((2 |-> (B:A)) ((3 |-> (leq:A)) (\k. (v:num->A) (k - 32)))))` THEN
  SUBGOAL_THEN
   `valuation D (w0:num->A) /\ w0 2 = B /\ w0 3 = leq /\
    w0 8 = w1 /\ w0 9 = X /\
    (!i. w0 (32 + i) = (v:num->A) i)`
   (CONJUNCTS_THEN2 (LABEL_TAC "vw0") (CONJUNCTS_THEN2 (LABEL_TAC "w02")
     (CONJUNCTS_THEN2 (LABEL_TAC "w03") (CONJUNCTS_THEN2 (LABEL_TAC "w08")
       (CONJUNCTS_THEN2 (LABEL_TAC "w09") (LABEL_TAC "w0v")))))) THENL
   [EXPAND_TAC "w0" THEN REPEAT CONJ_TAC THENL
     [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]) THEN
      REWRITE_TAC[valuation] THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[VALMOD; ARITH_EQ];
      REWRITE_TAC[VALMOD; ARITH_EQ];
      REWRITE_TAC[VALMOD; ARITH_EQ];
      REWRITE_TAC[VALMOD; ARITH_EQ];
      GEN_TAC THEN
      SIMP_TAC[VALMOD_OTHER; ARITH_RULE `~(32 + i = 2) /\ ~(32 + i = 3) /\
                                         ~(32 + i = 8) /\ ~(32 + i = 9)`] THEN
      AP_TERM_TAC THEN ARITH_TAC];
    ALL_TAC] THEN
  (* semantics of hsname_form (32+n) && fp at any valuation agreeing with w0 *)
  SUBGOAL_THEN
   `!ww:num->A. valuation D ww /\ ww 2 = B /\ ww 3 = leq /\
       ww 8 = w1 /\ ww 9 = X /\
                (!i. ~(i = n) ==> ww (32 + i) = (v:num->A) i)
                ==> (holds D (E:A->A->bool) ww (hsname_form (32 + n) && fp) <=>
                     hsname D E B w1 X (ww (32 + n)) /\
                     bval_HS D E B leq w1 X ((n |-> ww (32 + n)) v) p (ww 5))`
   (LABEL_TAC "sem") THENL
   [X_GEN_TAC `ww:num->A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "vww")
               (CONJUNCTS_THEN2 (LABEL_TAC "ww2")
                (CONJUNCTS_THEN2 (LABEL_TAC "ww3")
                 (CONJUNCTS_THEN2 (LABEL_TAC "ww8")
                  (CONJUNCTS_THEN2 (LABEL_TAC "ww9") (LABEL_TAC "wwv")))))) THEN
    REWRITE_TAC[HOLDS_AND] THEN
    MATCH_MP_TAC(TAUT `(a <=> a') /\ (b <=> b') ==> (a /\ b <=> a' /\ b')`) THEN
    CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`ww:num->A`;`32 + n`]
             HOLDS_HSNAME_FORM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN ARITH_TAC;
                      DISCH_THEN SUBST1_TAC] THEN
      ASM_REWRITE_TAC[];
      FIRST_X_ASSUM(fun th -> MP_TAC(SPECL
          [`D:A->bool`; `E:A->A->bool`; `ww:num->A`] th) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN ARITH_TAC; ALL_TAC]) THEN
      DISCH_THEN SUBST1_TAC THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC BVAL_HS_FV THEN X_GEN_TAC `i:num` THEN DISCH_TAC THEN
      ASM_CASES_TAC `i:num = n` THEN ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER]];
    ALL_TAC] THEN
  (* the value set SS *)
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`] ZF_SEPARATION) THEN
  ANTS_TAC THENL [USE_THEN "modl" ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`?? (32 + n) (hsname_form (32 + n) && fp)`; `5`; `w0:num->A`; `B:A`]) THEN
  ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `SS:A` (CONJUNCTS_THEN2 (LABEL_TAC "SSD")
      (LABEL_TAC "SSch0"))) THEN
  SUBGOAL_THEN
   `!zz:A. zz IN D
           ==> ((E:A->A->bool) zz SS <=>
                ?a. a IN D /\ hsname D E B w1 X a /\
                    bval_HS D E B leq w1 X ((n |-> a) v) p zz)`
   (LABEL_TAC "SSch") THENL
   [X_GEN_TAC `zz:A` THEN DISCH_THEN(LABEL_TAC "zzD") THEN
    USE_THEN "SSch0" (MP_TAC o SPEC `zz:A`) THEN
    ANTS_TAC THENL [USE_THEN "zzD" ACCEPT_TAC; DISCH_THEN SUBST1_TAC] THEN
    REWRITE_TAC[HOLDS_EX] THEN
    EQ_TAC THENL
     [DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
        (X_CHOOSE_THEN `a:A` (CONJUNCTS_THEN2 (LABEL_TAC "aD")
                              (LABEL_TAC "ha")))) THEN
      USE_THEN "sem" (MP_TAC o SPEC `((32 + n) |-> (a:A))
                      ((5 |-> (zz:A)) (w0:num->A))`) THEN
      ANTS_TAC THENL
       [REPEAT CONJ_TAC THENL
         [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC) THEN
          FIRST_ASSUM ACCEPT_TAC;
          ASM_SIMP_TAC[VALMOD_OTHER; ARITH_RULE `~(2 = 32 + n) /\ ~(2 = 5)`];
          ASM_SIMP_TAC[VALMOD_OTHER; ARITH_RULE `~(3 = 32 + n) /\ ~(3 = 5)`];
          ASM_SIMP_TAC[VALMOD_OTHER; ARITH_RULE `~(8 = 32 + n) /\ ~(8 = 5)`];
          ASM_SIMP_TAC[VALMOD_OTHER; ARITH_RULE `~(9 = 32 + n) /\ ~(9 = 5)`];
          X_GEN_TAC `i:num` THEN DISCH_TAC THEN
          ASM_SIMP_TAC[VALMOD_OTHER; ARITH_RULE `~(i = n)
                       ==> ~(32 + i = 32 + n)`;
                       ARITH_RULE `~(32 + i = 5)`]];
        DISCH_THEN(fun th -> USE_THEN "ha" (MP_TAC o EQ_MP th))] THEN
      REWRITE_TAC[VALMOD_BASIC] THEN
      SIMP_TAC[VALMOD_OTHER; ARITH_RULE `~(5 = 32 + n)`; VALMOD_BASIC] THEN
      STRIP_TAC THEN EXISTS_TAC `a:A` THEN ASM_REWRITE_TAC[];
      DISCH_THEN(X_CHOOSE_THEN `a:A` (CONJUNCTS_THEN2 (LABEL_TAC "aD")
        (CONJUNCTS_THEN2 (LABEL_TAC "hsa") (LABEL_TAC "bva")))) THEN
      CONJ_TAC THENL
       [MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                       `leq:A`;`w1:A`;`X:A`;
                       `(n |-> (a:A)) (v:num->A)`;`zz:A`] BVAL_HS_IN_B) THEN
        DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN
        MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
        ALL_TAC] THEN
      EXISTS_TAC `a:A` THEN CONJ_TAC THENL
          [USE_THEN "aD" ACCEPT_TAC; ALL_TAC] THEN
      USE_THEN "sem" (MP_TAC o SPEC `((32 + n) |-> (a:A))
                      ((5 |-> (zz:A)) (w0:num->A))`) THEN
      ANTS_TAC THENL
       [REPEAT CONJ_TAC THENL
         [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC) THEN
          FIRST_ASSUM ACCEPT_TAC;
          ASM_SIMP_TAC[VALMOD_OTHER; ARITH_RULE `~(2 = 32 + n) /\ ~(2 = 5)`];
          ASM_SIMP_TAC[VALMOD_OTHER; ARITH_RULE `~(3 = 32 + n) /\ ~(3 = 5)`];
