(* ===================================================================== *)
(* H3.3 : GDISJ -- disjointification of a B-valued family over a          *)
(* well-ordered index set (generic Boolean algebra), and its countable    *)
(* support in the ccc RO algebra.  egw i y : y = h(i) /\ ~sup{h(j): j<i}.  *)
(* ===================================================================== *)
let egw = new_definition
 `egw D (E:A->A->bool) B leq Ix h ra i y <=>
    ?Pi. Pi IN D /\
         (!z. z IN D
              ==> (E z Pi <=> E z B /\
                    ?j. j IN D /\ E j Ix /\ erel D E ra j i /\
                        eapply D E h j z)) /\
    ?u. u IN D /\ elub D E B leq Pi u /\
    ?hi. hi IN D /\ eapply D E h i hi /\
    ?c. c IN D /\ ecompl D E B leq u c /\ emeet D E B leq hi c y`;;

let gw_form = new_definition
 `gw_form =
    ?? 10 ((!! 20 ((20 %% 10) <->
                   ((20 %% 2) &&
                    ?? 21 ((21 %% 4) && rel_form 6 21 0 &&
                           apply_form 5 21 20)))) &&
     ?? 11 (elub_form 2 3 10 11 &&
      ?? 12 (apply_form 5 0 12 &&
       ?? 13 (bcompl_form 3 2 11 13 && bmeet_form 3 2 12 13 1))))`;;

let HOLDS_GW_FORM = prove
 (`!D (E:A->A->bool) v.
     model D E ZF_AX /\ valuation D v
     ==> (holds D E v gw_form <=>
          egw D E (v 2) (v 3) (v 4) (v 5) (v 6) (v 0) (v 1))`,
  REPEAT GEN_TAC THEN DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
      (LABEL_TAC "vv")) THEN
  REWRITE_TAC[gw_form; egw; HOLDS_EX; HOLDS_AND] THEN
  MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s))
     ==> ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
  X_GEN_TAC `Pi:A` THEN DISCH_THEN(LABEL_TAC "PiD") THEN
  SUBGOAL_THEN `valuation D ((10 |-> (Pi:A)) (v:num->A))`
      (LABEL_TAC "v10") THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THEN
    FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  MATCH_MP_TAC(TAUT `(a <=> a') /\ (b <=> b') ==> (a /\ b <=> a' /\ b')`)
      THEN CONJ_TAC THENL
   [REWRITE_TAC[holds] THEN
    MATCH_MP_TAC(MESON[]
      `(!z:A. z IN D ==> (P z <=> Q z))
       ==> ((!z. z IN D ==> P z) <=> (!z. z IN D ==> Q z))`) THEN
    X_GEN_TAC `z:A` THEN DISCH_THEN(LABEL_TAC "zD") THEN
    SUBGOAL_THEN `valuation D ((20 |-> (z:A)) ((10 |-> (Pi:A)) (v:num->A)))`
        (LABEL_TAC "v20") THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THEN
      FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    REWRITE_TAC[HOLDS_IFF; HOLDS_AND; HOLDS_EX] THEN
    REWRITE_TAC[holds; VALMOD; ARITH_EQ] THEN
    MATCH_MP_TAC(TAUT `(b <=> b') ==> ((a <=> c /\ b) <=>
        (a <=> c /\ b'))`) THEN
    MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s))
     ==> ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
    X_GEN_TAC `j:A` THEN DISCH_THEN(LABEL_TAC "jD") THEN
    SUBGOAL_THEN `valuation D ((21 |-> (j:A))
        ((20 |-> (z:A)) ((10 |-> (Pi:A)) (v:num->A))))`
      (LABEL_TAC "v21") THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THEN
      FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_REL_FORM; HOLDS_APPLY_FORM; holds] THEN
    REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s))
     ==> ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
  X_GEN_TAC `u:A` THEN DISCH_THEN(LABEL_TAC "uD") THEN
  SUBGOAL_THEN `valuation D ((11 |-> (u:A)) ((10 |-> (Pi:A)) (v:num->A)))`
      (LABEL_TAC "v11") THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THEN
    FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  MATCH_MP_TAC(TAUT `(a <=> a') /\ (b <=> b') ==> (a /\ b <=> a' /\ b')`)
      THEN CONJ_TAC THENL
   [ASM_SIMP_TAC[HOLDS_ELUB_FORM] THEN
    REWRITE_TAC[VALMOD; ARITH_EQ]; ALL_TAC] THEN
  MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s))
     ==> ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
  X_GEN_TAC `hi:A` THEN DISCH_THEN(LABEL_TAC "hiD") THEN
  SUBGOAL_THEN `valuation D ((12 |-> (hi:A))
      ((11 |-> (u:A)) ((10 |-> (Pi:A)) (v:num->A))))`
    (LABEL_TAC "v12") THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THEN
    FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  MATCH_MP_TAC(TAUT `(a <=> a') /\ (b <=> b') ==> (a /\ b <=> a' /\ b')`)
      THEN CONJ_TAC THENL
   [ASM_SIMP_TAC[HOLDS_APPLY_FORM] THEN
    REWRITE_TAC[VALMOD; ARITH_EQ]; ALL_TAC] THEN
  MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s))
     ==> ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
  X_GEN_TAC `c:A` THEN DISCH_THEN(LABEL_TAC "cD") THEN
  SUBGOAL_THEN
   `valuation D ((13 |-> (c:A)) ((12 |-> (hi:A))
       ((11 |-> (u:A)) ((10 |-> (Pi:A)) (v:num->A)))))`
    (LABEL_TAC "v13") THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THEN
    FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  ASM_SIMP_TAC[HOLDS_BCOMPL_FORM; HOLDS_BMEET_FORM] THEN
      REWRITE_TAC[VALMOD; ARITH_EQ]);;

let BELOW_COMPL_BOT = prove
 (`!D (E:A->A->bool) p leq u c m.
     eporder D E p leq /\ ecompl D E p leq u c /\ m IN D /\ E m p /\
     erel D E leq m u /\ erel D E leq m c
     ==> ebot D E p leq m`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "po")
             (CONJUNCTS_THEN2 (MP_TAC o REWRITE_RULE[ecompl])
              (CONJUNCTS_THEN2 (LABEL_TAC "mD")
               (CONJUNCTS_THEN2 (LABEL_TAC "mp")
                (CONJUNCTS_THEN2 (LABEL_TAC "mu") (LABEL_TAC "mc")))))) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (CONJUNCTS_THEN2 (K ALL_TAC)
    (X_CHOOSE_THEN `z:A` (X_CHOOSE_THEN `uu:A` (CONJUNCTS_THEN2 (LABEL_TAC "bz")
      (CONJUNCTS_THEN2 (K ALL_TAC) (CONJUNCTS_THEN2 (LABEL_TAC "mz")
          (K ALL_TAC)))))))) THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m z` (LABEL_TAC "lez") THENL
   [USE_THEN "mz" (MP_TAC o last o CONJUNCTS o REWRITE_RULE[emeet]) THEN
    DISCH_THEN MATCH_MP_TAC THEN REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(m:A) = z` SUBST1_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`m:A`;`z:A`]
                 EPORDER_ANTISYM) THEN
    USE_THEN "bz" (fun th -> MP_TAC(REWRITE_RULE[ebot] th)) THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "zD")
               (CONJUNCTS_THEN2 (LABEL_TAC "zp") (LABEL_TAC "zle"))) THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    USE_THEN "zle" MATCH_MP_TAC THEN CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    USE_THEN "bz" ACCEPT_TAC]);;

let EGW_EXISTS = prove
 (`!D (E:A->A->bool) B leq Ix h ra i.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
     Ix IN D /\ h IN D /\ ra IN D /\
     (!i. i IN D /\ E i Ix ==> ?y. y IN D /\ E y B /\ eapply D E h i y) /\
     i IN D /\ E i Ix
     ==> ?y. y IN D /\ egw D E B leq Ix h ra i y`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
             (CONJUNCTS_THEN2 (LABEL_TAC "cba")
              (CONJUNCTS_THEN2 (LABEL_TAC "BD")
               (CONJUNCTS_THEN2 (LABEL_TAC "leqD")
                (CONJUNCTS_THEN2 (LABEL_TAC "IxD")
                 (CONJUNCTS_THEN2 (LABEL_TAC "hD")
                  (CONJUNCTS_THEN2 (LABEL_TAC "raD")
                   (CONJUNCTS_THEN2 (LABEL_TAC "htot")
                    (CONJUNCTS_THEN2 (LABEL_TAC "iD")
                     (LABEL_TAC "iIx")))))))))) THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` (LABEL_TAC "balg") THENL
   [USE_THEN "cba" (ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[ecba]); ALL_TAC] THEN
  USE_THEN "modl" (X_CHOOSE_TAC `v0:num->A` o MATCH_MP VALUATION_EXISTS o
                   MATCH_MP MODEL_NONEMPTY) THEN
  SUBGOAL_THEN
   `valuation D ((6 |-> (ra:A)) ((5 |-> (h:A))
       ((4 |-> (Ix:A)) ((0 |-> (i:A)) (v0:num->A)))))`
   (LABEL_TAC "vW") THENL
   [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC) THEN
    FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  USE_THEN "modl" (MP_TAC o SPECL
    [`?? 21 ((21 %% 4) && rel_form 6 21 0 && apply_form 5 21 20)`; `20`;
     `(6 |-> (ra:A)) ((5 |-> (h:A)) ((4 |-> (Ix:A))
         ((0 |-> (i:A)) (v0:num->A))))`; `B:A`] o
    MATCH_MP ZF_SEPARATION) THEN
  ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `Pi:A` (CONJUNCTS_THEN2 (LABEL_TAC "PiD")
      (LABEL_TAC "Pich0"))) THEN
  SUBGOAL_THEN
   `!z:A. z IN D
          ==> ((E:A->A->bool) z Pi <=> E z B /\
                ?j. j IN D /\ E j Ix /\ erel D E ra j i /\ eapply D E h j z)`
   (LABEL_TAC "Pich") THENL
   [X_GEN_TAC `z:A` THEN DISCH_THEN(LABEL_TAC "zD") THEN
    USE_THEN "Pich0" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [USE_THEN "zD" ACCEPT_TAC; DISCH_THEN SUBST1_TAC] THEN
