    SUBGOAL_THEN
     `valuation D ((21 |-> (j:A)) ((20 |-> (z:A)) ((6 |-> (ra:A)) ((5 |-> (h:A))
        ((4 |-> (Ix:A)) ((0 |-> (i:A)) (v0:num->A)))))))`
            (LABEL_TAC "v21") THENL
     [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC) THEN
      FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_REL_FORM; HOLDS_APPLY_FORM; holds] THEN
    REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) Pi B` (LABEL_TAC "PiB") THENL
   [REWRITE_TAC[esubset] THEN X_GEN_TAC `z:A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "zD") (LABEL_TAC "zPi")) THEN
    USE_THEN "Pich" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [USE_THEN "zD" ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "zPi" (MP_TAC o EQ_MP th)) THEN
