let EGW_UNIQUE = prove
 (`!D (E:A->A->bool) B leq Ix h ra i y y'.
     model D E ZF_AX /\ ecba D E B leq /\
     (!i y y'. i IN D /\ y IN D /\ y' IN D /\ eapply D E h i y /\
      eapply D E h i y' ==> y = y') /\
     i IN D /\ egw D E B leq Ix h ra i y /\ egw D E B leq Ix h ra i y'
     ==> y = y'`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
             (CONJUNCTS_THEN2 (LABEL_TAC "cba")
    (CONJUNCTS_THEN2 (LABEL_TAC "hfun") (CONJUNCTS_THEN2 (LABEL_TAC "iD")
     (CONJUNCTS_THEN2 (MP_TAC o REWRITE_RULE[egw])
      (MP_TAC o REWRITE_RULE[egw])))))) THEN
  DISCH_THEN(X_CHOOSE_THEN `Pi2:A` (CONJUNCTS_THEN2 (LABEL_TAC "PiD2")
      (CONJUNCTS_THEN2 (LABEL_TAC "Pich2")
       (X_CHOOSE_THEN `u2:A` (CONJUNCTS_THEN2 (LABEL_TAC "uD2")
      (CONJUNCTS_THEN2 (LABEL_TAC "lub2")
       (X_CHOOSE_THEN `hi2:A` (CONJUNCTS_THEN2 (LABEL_TAC "hiD2")
      (CONJUNCTS_THEN2 (LABEL_TAC "hih2")
       (X_CHOOSE_THEN `c2:A` (CONJUNCTS_THEN2 (LABEL_TAC "cD2")
      (CONJUNCTS_THEN2 (LABEL_TAC "cmp2") (LABEL_TAC "mt2"))))))))))))) THEN
  DISCH_THEN(X_CHOOSE_THEN `Pi1:A` (CONJUNCTS_THEN2 (LABEL_TAC "PiD1")
      (CONJUNCTS_THEN2 (LABEL_TAC "Pich1")
       (X_CHOOSE_THEN `u1:A` (CONJUNCTS_THEN2 (LABEL_TAC "uD1")
      (CONJUNCTS_THEN2 (LABEL_TAC "lub1")
       (X_CHOOSE_THEN `hi1:A` (CONJUNCTS_THEN2 (LABEL_TAC "hiD1")
      (CONJUNCTS_THEN2 (LABEL_TAC "hih1")
       (X_CHOOSE_THEN `c1:A` (CONJUNCTS_THEN2 (LABEL_TAC "cD1")
      (CONJUNCTS_THEN2 (LABEL_TAC "cmp1") (LABEL_TAC "mt1"))))))))))))) THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\ eporder D E B leq`
   (CONJUNCTS_THEN2 (LABEL_TAC "balg") (LABEL_TAC "po")) THENL
   [USE_THEN "cba" (fun th -> MESON_TAC[th; ECBA_IMP_BALG;
       EBALG_IMP_PORDER]); ALL_TAC] THEN
  SUBGOAL_THEN `(Pi1:A) = Pi2` SUBST_ALL_TAC THENL
   [USE_THEN "modl" (MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    X_GEN_TAC `z:A` THEN DISCH_THEN(LABEL_TAC "zD") THEN
    USE_THEN "Pich1" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [USE_THEN "zD" ACCEPT_TAC; DISCH_THEN SUBST1_TAC] THEN
    USE_THEN "Pich2" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [USE_THEN "zD" ACCEPT_TAC; DISCH_THEN SUBST1_TAC] THEN
    REFL_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(u1:A) = u2` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`Pi2:A`;
                         `u1:A`;`u2:A`] ELUB_UNIQUE) THEN
    REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(hi1:A) = hi2` SUBST_ALL_TAC THENL
   [USE_THEN "hfun" (MP_TAC o SPECL [`i:A`;`hi1:A`;`hi2:A`]) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `(c1:A) = c2` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`u2:A`;`c1:A`;
                         `c2:A`] ECOMPL_UNIQUE) THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    USE_THEN "lub2" (MP_TAC o REWRITE_RULE[elub; eubound]) THEN MESON_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`hi2:A`;`c2:A`;
                       `y:A`;`y':A`] EMEET_UNIQUE) THEN
  REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC);;

let gimg_form = new_definition
  `gimg_form = ?? 1 (gw_form && opair_form 0 1 63)`;;

let HOLDS_GIMG_FORM = prove
 (`!D (E:A->A->bool) v.
     model D E ZF_AX /\ valuation D v
     ==> (holds D E v gimg_form <=>
          ?y. y IN D /\ egw D E (v 2) (v 3) (v 4) (v 5) (v 6) (v 0) y /\
              eopair D E (v 0) y (v 63))`,
  REPEAT GEN_TAC THEN DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
      (LABEL_TAC "vv")) THEN
  REWRITE_TAC[gimg_form; HOLDS_EX; HOLDS_AND] THEN
  MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s))
     ==> ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
  X_GEN_TAC `y:A` THEN DISCH_THEN(LABEL_TAC "yD") THEN
  SUBGOAL_THEN `valuation D ((1 |-> (y:A)) (v:num->A))` (LABEL_TAC "v1") THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THEN
    FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  ASM_SIMP_TAC[HOLDS_GW_FORM; HOLDS_OPAIR_FORM] THEN
      REWRITE_TAC[VALMOD; ARITH_EQ]);;

let GDISJ_W = prove
 (`!D (E:A->A->bool) B leq Ix h ra.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
     Ix IN D /\ h IN D /\ ra IN D /\
     (!i. i IN D /\ E i Ix ==> ?y. y IN D /\ E y B /\ eapply D E h i y) /\
     (!i y y'. i IN D /\ y IN D /\ y' IN D /\ eapply D E h i y /\
      eapply D E h i y'
               ==> y = y') /\
     (!u u'. u IN D /\ u' IN D /\ erel D E ra u u' ==> ~(erel D E ra u' u)) /\
     (!z. z IN D /\ (!t. t IN D /\ E t z ==> E t Ix) /\ (?t. t IN D /\ E t z)
          ==> ?p0. p0 IN D /\ E p0 z /\
                   !q. q IN D /\ E q z /\ ~(q = p0) ==> erel D E ra p0 q)
     ==> ?g. g IN D /\
             (!i. i IN D /\ E i Ix ==> ?y. y IN D /\ eapply D E g i y) /\
             (!i y. i IN D /\ y IN D /\ eapply D E g i y
                    ==> E i Ix /\ egw D E B leq Ix h ra i y) /\
             (!i y y'. i IN D /\ y IN D /\ y' IN D /\
                       eapply D E g i y /\ eapply D E g i y' ==> y = y') /\
             (!i y hi. i IN D /\ y IN D /\ hi IN D /\
                       eapply D E g i y /\ eapply D E h i hi
                       ==> E y B /\ erel D E leq y hi) /\
             (!i j y y' m. i IN D /\ j IN D /\ y IN D /\ y' IN D /\ m IN D /\
                           ~(i = j) /\ eapply D E g i y /\ eapply D E g j y' /\
                           emeet D E B leq y y' m
                           ==> ebot D E B leq m) /\
             (!w. w IN D /\ E w B /\
                  (!i y. i IN D /\ y IN D /\ eapply D E g i y
                   ==> erel D E leq y w)
                  ==> (!i y. i IN D /\ E i Ix /\ y IN D /\ eapply D E h i y
                             ==> erel D E leq y w))`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
             (CONJUNCTS_THEN2 (LABEL_TAC "cba")
              (CONJUNCTS_THEN2 (LABEL_TAC "BD")
               (CONJUNCTS_THEN2 (LABEL_TAC "leqD")
                (CONJUNCTS_THEN2 (LABEL_TAC "IxD")
                 (CONJUNCTS_THEN2 (LABEL_TAC "hD")
                  (CONJUNCTS_THEN2 (LABEL_TAC "raD")
                   (CONJUNCTS_THEN2 (LABEL_TAC "htot")
                    (CONJUNCTS_THEN2 (LABEL_TAC "hfun")
                     (CONJUNCTS_THEN2 (LABEL_TAC "rasym")
                      (LABEL_TAC "raleast"))))))))))) THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\ eporder D E B leq`
   (CONJUNCTS_THEN2 (LABEL_TAC "balg") (LABEL_TAC "po")) THENL
   [USE_THEN "cba" (fun th -> MESON_TAC[th; ECBA_IMP_BALG;
       EBALG_IMP_PORDER]); ALL_TAC] THEN
  USE_THEN "modl" (X_CHOOSE_TAC `v0:num->A` o MATCH_MP VALUATION_EXISTS o
                   MATCH_MP MODEL_NONEMPTY) THEN
  SUBGOAL_THEN `valuation D ((6 |-> (ra:A))
      ((5 |-> (h:A)) ((4 |-> (Ix:A)) ((3 |-> (leq:A))
      ((2 |-> (B:A)) (v0:num->A))))))` (LABEL_TAC "vV") THENL
   [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC) THEN
    FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
   `!u out:A. u IN D /\ out IN D
              ==> (holds D (E:A->A->bool) ((63 |-> out)
                  ((0 |-> u) ((6 |-> (ra:A)) ((5 |-> (h:A))
                  ((4 |-> (Ix:A)) ((3 |-> (leq:A))
                                   ((2 |-> (B:A)) (v0:num->A))))))))
                     gimg_form <=>
                   ?y. y IN D /\ egw D E B leq Ix h ra u y /\
                       eopair D E u y out)`
   (LABEL_TAC "gimg") THENL
   [MAP_EVERY X_GEN_TAC [`u:A`;`out:A`] THEN STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;
                  `(63 |-> (out:A)) ((0 |-> (u:A))
                                     ((6 |-> (ra:A)) ((5 |-> (h:A))
                      ((4 |-> (Ix:A)) ((3 |-> (leq:A))
                                       ((2 |-> (B:A)) (v0:num->A)))))))`]
                      HOLDS_GIMG_FORM) THEN
    ANTS_TAC THENL
     [CONJ_TAC THENL [USE_THEN "modl" ACCEPT_TAC; ALL_TAC] THEN
      REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC) THEN
          FIRST_ASSUM ACCEPT_TAC;
      DISCH_THEN SUBST1_TAC] THEN
    REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`gimg_form`;`0`;`63`;
                `(6 |-> (ra:A)) ((5 |-> (h:A))
                                 ((4 |-> (Ix:A)) ((3 |-> (leq:A))
                    ((2 |-> (B:A)) (v0:num->A)))))`;`Ix:A`] EIMG_FAMILY) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THENL
     [ARITH_TAC;
      X_GEN_TAC `u:A` THEN DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "uD")
          (LABEL_TAC "uIx")) THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`Ix:A`;
                    `h:A`;`ra:A`;`u:A`]
        EGW_EXISTS) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `y:A` (CONJUNCTS_THEN2 (LABEL_TAC "yD")
          (LABEL_TAC "egy"))) THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`u:A`;`y:A`] EOPAIR_EXISTS) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `out:A` (LABEL_TAC "op")) THEN
      SUBGOAL_THEN `(out:A) IN D` (LABEL_TAC "outD") THENL
       [USE_THEN "op" (ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
      EXISTS_TAC `out:A` THEN CONJ_TAC THENL
          [USE_THEN "outD" ACCEPT_TAC; ALL_TAC] THEN
      CONJ_TAC THENL
       [USE_THEN "gimg" (MP_TAC o SPECL [`u:A`;`out:A`]) THEN
        ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                        DISCH_THEN SUBST1_TAC] THEN
        EXISTS_TAC `y:A` THEN REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
        ALL_TAC] THEN
      X_GEN_TAC `out':A` THEN DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "out'D")
          (LABEL_TAC "ho'")) THEN
      USE_THEN "gimg" (MP_TAC o SPECL [`u:A`;`out':A`]) THEN
      ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> USE_THEN "ho'" (MP_TAC o EQ_MP th)) THEN
      DISCH_THEN(X_CHOOSE_THEN `y':A` (CONJUNCTS_THEN2 (LABEL_TAC "y'D")
          (CONJUNCTS_THEN2 (LABEL_TAC "egy'") (LABEL_TAC "op'")))) THEN
      SUBGOAL_THEN `(y':A) = y` SUBST_ALL_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`Ix:A`;
                      `h:A`;`ra:A`;`u:A`;
                      `y':A`;`y:A`] EGW_UNIQUE) THEN
        ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                        DISCH_THEN ACCEPT_TAC];
        ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`u:A`;`y:A`;`out':A`;`out:A`]
             EOPAIR_UNIQUE) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN ACCEPT_TAC];
      MAP_EVERY X_GEN_TAC [`u:A`;`out:A`] THEN
      DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "uD")
                 (CONJUNCTS_THEN2 (LABEL_TAC "uIx")
        (CONJUNCTS_THEN2 (LABEL_TAC "outD") (LABEL_TAC "ho")))) THEN
      USE_THEN "gimg" (MP_TAC o SPECL [`u:A`;`out:A`]) THEN
      ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> USE_THEN "ho" (MP_TAC o EQ_MP th)) THEN
      DISCH_THEN(X_CHOOSE_THEN `y:A` (CONJUNCTS_THEN2 (LABEL_TAC "yD")
          (CONJUNCTS_THEN2 (LABEL_TAC "egy") (LABEL_TAC "op")))) THEN
      EXISTS_TAC `y:A` THEN CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `g:A` (CONJUNCTS_THEN2 (LABEL_TAC "gD")
      (CONJUNCTS_THEN2 (LABEL_TAC "gch")
       (CONJUNCTS_THEN2 (LABEL_TAC "ghead")
        (CONJUNCTS_THEN2 (LABEL_TAC "gfun") (LABEL_TAC "gtot")))))) THEN
  (* eapply g i y ==> i IN Ix /\ egw i y *)
  SUBGOAL_THEN
   `!i y:A. i IN D /\ y IN D /\ eapply D (E:A->A->bool) g i y
            ==> E i Ix /\ egw D E B leq Ix h ra i y`
   (LABEL_TAC "gsem") THENL
