    SUBGOAL_THEN `(mm:A) IN D /\ (E:A->A->bool) mm B /\ erel D E leq mm y0 /\
        erel D E leq mm cw`
     (CONJUNCTS_THEN2 (LABEL_TAC "mmD") (CONJUNCTS_THEN2 (LABEL_TAC "mmB")
       (CONJUNCTS_THEN2 (LABEL_TAC "mmy") (LABEL_TAC "mmc")))) THENL
     [USE_THEN "mmm" (fun th -> MESON_TAC[REWRITE_RULE[emeet]
         th]); ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq cw c0` (LABEL_TAC "cwc0") THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`u0:A`;
                    `w:A`;`c0:A`;`cw:A`]
        ECOMPL_ANTITONE) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq mm g0` (LABEL_TAC "mmg") THENL
     [USE_THEN "mt0" (MP_TAC o last o CONJUNCTS o REWRITE_RULE[emeet]) THEN
      DISCH_THEN MATCH_MP_TAC THEN REPEAT CONJ_TAC THEN
          TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mm:A`;
                           `cw:A`;`c0:A`] EPORDER_TRANS) THEN
      REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `ebot D (E:A->A->bool) B leq mm` (LABEL_TAC "mmbot") THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;
                           `cw:A`;`mm:A`] BELOW_COMPL_BOT) THEN
      REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mm:A`;
                           `g0:A`;`w:A`] EPORDER_TRANS) THEN
      REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
      ALL_TAC] THEN
    USE_THEN "nle0" MP_TAC THEN REWRITE_TAC[] THEN
    SUBGOAL_THEN `ecompl D (E:A->A->bool) B leq cw w` (LABEL_TAC "cww") THENL
     [MATCH_MP_TAC ECOMPL_SYM THEN REPEAT CONJ_TAC THEN
      FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`y0:A`;`cw:A`;
                  `w:A`;`mm:A`;`mm:A`]
      EMEET_BOT_COMPL) THEN
    ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mm:A`]
                 EPORDER_REFL) THEN
    REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  (* assemble *)
  EXISTS_TAC `g:A` THEN
  CONJ_TAC THENL [USE_THEN "gD" ACCEPT_TAC; ALL_TAC] THEN
  CONJ_TAC THENL
   [X_GEN_TAC `i:A` THEN DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "iD")
       (LABEL_TAC "iIx")) THEN
    USE_THEN "gtot" (MP_TAC o SPEC `i:A`) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `o1:A` (X_CHOOSE_THEN `z1:A`
        (CONJUNCTS_THEN2 (K ALL_TAC)
      (CONJUNCTS_THEN2 (LABEL_TAC "z1D") (CONJUNCTS_THEN2 (K ALL_TAC)
        (CONJUNCTS_THEN2 (K ALL_TAC) (LABEL_TAC "gz1"))))))) THEN
    EXISTS_TAC `z1:A` THEN CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  CONJ_TAC THENL [USE_THEN "gsem" ACCEPT_TAC; ALL_TAC] THEN
  CONJ_TAC THENL [USE_THEN "gfun" ACCEPT_TAC; ALL_TAC] THEN
  CONJ_TAC THENL [USE_THEN "gle" ACCEPT_TAC; ALL_TAC] THEN
  CONJ_TAC THENL [ALL_TAC; USE_THEN "gsup" ACCEPT_TAC] THEN
  MAP_EVERY X_GEN_TAC [`i:A`;`j:A`;`y:A`;`y':A`;`m:A`] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "iD")
             (CONJUNCTS_THEN2 (LABEL_TAC "jD")
              (CONJUNCTS_THEN2 (LABEL_TAC "yD")
               (CONJUNCTS_THEN2 (LABEL_TAC "y'D")
                (CONJUNCTS_THEN2 (LABEL_TAC "mD")
                 (CONJUNCTS_THEN2 (LABEL_TAC "ij")
                  (CONJUNCTS_THEN2 (LABEL_TAC "giy")
                   (CONJUNCTS_THEN2 (LABEL_TAC "gjy")
                    (LABEL_TAC "mt"))))))))) THEN
  SUBGOAL_THEN `(E:A->A->bool) i Ix /\
      E j Ix` (CONJUNCTS_THEN2 (LABEL_TAC "iIx") (LABEL_TAC "jIx")) THENL
   [CONJ_TAC THENL
     [USE_THEN "gsem" (MP_TAC o SPECL [`i:A`;`y:A`]);
      USE_THEN "gsem" (MP_TAC o SPECL [`j:A`;`y':A`])] THEN
    ANTS_TAC THEN TRY(REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC) THEN
    DISCH_THEN(ACCEPT_TAC o CONJUNCT1);
    ALL_TAC] THEN
  (* ra compares i and j: least element of the pair {i,j} *)
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`i:A`;`j:A`] EPAIR_EXISTS) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `pr:A` (LABEL_TAC "prp")) THEN
  SUBGOAL_THEN `(pr:A) IN D /\ (!w:A. w IN D
      ==> ((E:A->A->bool) w pr <=> w = i \/ w = j))`
   (CONJUNCTS_THEN2 (LABEL_TAC "prD") (LABEL_TAC "prch")) THENL
   [USE_THEN "prp" (ACCEPT_TAC o REWRITE_RULE[epair]); ALL_TAC] THEN
  USE_THEN "raleast" (MP_TAC o SPEC `pr:A`) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [USE_THEN "prD" ACCEPT_TAC;
      X_GEN_TAC `t:A` THEN DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "tD")
          (LABEL_TAC "tpr")) THEN
      USE_THEN "prch" (MP_TAC o SPEC `t:A`) THEN
      ANTS_TAC THENL [USE_THEN "tD" ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> USE_THEN "tpr" (MP_TAC o EQ_MP th)) THEN
      DISCH_THEN(DISJ_CASES_THEN SUBST1_TAC) THEN FIRST_ASSUM ACCEPT_TAC;
      EXISTS_TAC `i:A` THEN CONJ_TAC THENL
          [USE_THEN "iD" ACCEPT_TAC; ALL_TAC] THEN
      USE_THEN "prch" (MP_TAC o SPEC `i:A`) THEN
      ANTS_TAC THENL [USE_THEN "iD" ACCEPT_TAC; DISCH_THEN SUBST1_TAC] THEN
      REWRITE_TAC[]];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `p0:A` (CONJUNCTS_THEN2 (LABEL_TAC "p0D")
      (CONJUNCTS_THEN2 (LABEL_TAC "p0pr") (LABEL_TAC "p0least")))) THEN
  USE_THEN "prch" (MP_TAC o SPEC `p0:A`) THEN
  ANTS_TAC THENL [USE_THEN "p0D" ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> USE_THEN "p0pr" (MP_TAC o EQ_MP th)) THEN
  DISCH_THEN(DISJ_CASES_THEN SUBST_ALL_TAC) THENL
   [(* p0 = i : ra i j, so j is after i -- use dj1 with roles swapped *)
    USE_THEN "p0least" (MP_TAC o SPEC `j:A`) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THENL
       [USE_THEN "prch" (MP_TAC o SPEC `j:A`) THEN
        ANTS_TAC THENL [USE_THEN "jD" ACCEPT_TAC; DISCH_THEN SUBST1_TAC]
            THEN REWRITE_TAC[];
        USE_THEN "ij" (ACCEPT_TAC o GSYM)];
      DISCH_THEN(LABEL_TAC "rij")] THEN
    USE_THEN "dj1" (MP_TAC o SPECL [`j:A`;`i:A`;`y':A`;`y:A`;`m:A`]) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      USE_THEN "mt" (ACCEPT_TAC o MATCH_MP EMEET_SYM);
      DISCH_THEN ACCEPT_TAC];
    (* p0 = j : ra j i *)
    USE_THEN "p0least" (MP_TAC o SPEC `i:A`) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      USE_THEN "prch" (MP_TAC o SPEC `i:A`) THEN
      ANTS_TAC THENL [USE_THEN "iD" ACCEPT_TAC; DISCH_THEN SUBST1_TAC]
          THEN REWRITE_TAC[];
      DISCH_THEN(LABEL_TAC "rji")] THEN
    USE_THEN "dj1" (MP_TAC o SPECL [`i:A`;`j:A`;`y:A`;`y':A`;`m:A`]) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC]]);;

(* ######################################################################### *)
(* S5 / H3 (part 2) : SUPPORTS, VALUE GRAPH, SYMMETRIC MIXTURES             *)
(* H3.3b GDISJ_Q (a COUNTABLE subfamily with the same upper bounds, ccc);   *)
(* H3.6  esupp/nsupp_form ("e is a countable support of nm"), ESUPP_ELIM,   *)
(*       CSUPPORT_CHOICE (a countable set of HS names has ONE common        *)
(*       countable support: ECHOOSE_INJ_GEN + EGEN_UNION_CARD_LE);          *)
(* H3.5  HSVAL_GRAPH (the value graph q |-> [[p(q)]]^HS as a set);          *)
(* H3.7a PARAM_CSUPPORT (finitely many HS parameters, one support);         *)
(* H3.8a EGW_FIX (GDISJ weights are fixed when the family values are);      *)
(* H3.8b MIX_SYM (the V^B mixture of fixed names with fixed weights over an *)
(*       autN-invariant domain is fixed by autN).                           *)
(* ######################################################################### *)
(* ===================================================================== *)
(* H3.3b : GDISJ_Q -- in the ccc Cohen RO algebra a B-valued family over a *)
(* well-ordered index set has a COUNTABLE subfamily with the same upper     *)
(* bounds: Qs = {i | g_i <> bot} (GDISJ_W weights), {g_i | i IN Qs} is an    *)
(* antichain of B+ (COHEN_CBA_CCC + CCC_ANTICHAIN_DOM).                      *)
(* ===================================================================== *)
let GDISJ_Q = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X Ix h ra.
     hsbundle D E w1 om tw ii ci P leqp B inclB onebee X /\
     Ix IN D /\ h IN D /\ ra IN D /\
     (!i. i IN D /\ E i Ix ==> ?y. y IN D /\ E y B /\ eapply D E h i y) /\
     (!i y y'. i IN D /\ y IN D /\ y' IN D /\ eapply D E h i y /\
      eapply D E h i y'
               ==> y = y') /\
     (!u u'. u IN D /\ u' IN D /\ erel D E ra u u' ==> ~(erel D E ra u' u)) /\
     (!z. z IN D /\ (!t. t IN D /\ E t z ==> E t Ix) /\ (?t. t IN D /\ E t z)
          ==> ?p0. p0 IN D /\ E p0 z /\
                   !q. q IN D /\ E q z /\ ~(q = p0) ==> erel D E ra p0 q)
     ==> ?Qs. Qs IN D /\ esubset D E Qs Ix /\ (?k. einj D E k Qs om) /\
              (!w. w IN D /\ E w B /\
                   (!i y. i IN D /\ E i Qs /\ y IN D /\ eapply D E h i y
                          ==> erel D E inclB y w)
                   ==> (!i y. i IN D /\ E i Ix /\ y IN D /\ eapply D E h i y
                              ==> erel D E inclB y w))`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "hsb")
             (CONJUNCTS_THEN2 (LABEL_TAC "IxD")
              (CONJUNCTS_THEN2 (LABEL_TAC "hD")
               (CONJUNCTS_THEN2 (LABEL_TAC "raD")
                (CONJUNCTS_THEN2 (LABEL_TAC "htot")
                 (CONJUNCTS_THEN2 (LABEL_TAC "hfun")
                  (CONJUNCTS_THEN2 (LABEL_TAC "rasym")
                   (LABEL_TAC "raleast")))))))) THEN
  USE_THEN "hsb" (MP_TAC o MATCH_MP HSB_CBA) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "cba")
             (CONJUNCTS_THEN2 (LABEL_TAC "inclBD") (LABEL_TAC "leqpD"))) THEN
  USE_THEN "hsb" (MP_TAC o MATCH_MP HSB_FACTS) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "omD")
             (CONJUNCTS_THEN2 (LABEL_TAC "w1ord")
              (CONJUNCTS_THEN2 (LABEL_TAC "PD")
               (CONJUNCTS_THEN2 (LABEL_TAC "ciD")
                (CONJUNCTS_THEN2 (LABEL_TAC "iiD") (LABEL_TAC "omw1")))))) THEN
  USE_THEN "hsb" (MP_TAC o REWRITE_RULE[hsbundle]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
             (CONJUNCTS_THEN2 (LABEL_TAC "vl")
              (CONJUNCTS_THEN2 (LABEL_TAC "eom")
               (CONJUNCTS_THEN2 (LABEL_TAC "w1D")
                (CONJUNCTS_THEN2 (LABEL_TAC "w1card")
                 (CONJUNCTS_THEN2 (LABEL_TAC "omw1e")
                  (CONJUNCTS_THEN2 (LABEL_TAC "w1min")
                   (CONJUNCTS_THEN2 (LABEL_TAC "cr1")
                    (CONJUNCTS_THEN2 (LABEL_TAC "cr2")
                     (CONJUNCTS_THEN2 (LABEL_TAC "ftw")
                      (CONJUNCTS_THEN2 (LABEL_TAC "coh")
                       (CONJUNCTS_THEN2 (LABEL_TAC "leq")
                        (CONJUNCTS_THEN2 (LABEL_TAC "ros")
                         (CONJUNCTS_THEN2 (LABEL_TAC "inc")
                          (CONJUNCTS_THEN2 (LABEL_TAC "porder")
      (CONJUNCTS_THEN2 (LABEL_TAC "top")
       (CONJUNCTS_THEN2 (LABEL_TAC "oneD")
        (CONJUNCTS_THEN2 (LABEL_TAC "BD")
         (CONJUNCTS_THEN2 (LABEL_TAC "oneB")
          (CONJUNCTS_THEN2 (LABEL_TAC "XD")
           (CONJUNCTS_THEN2 (LABEL_TAC "ciX")
            (LABEL_TAC "PX")))))))))))))))))))))) THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B inclB /\ eporder D E B inclB`
   (CONJUNCTS_THEN2 (LABEL_TAC "balg") (LABEL_TAC "po")) THENL
   [USE_THEN "cba" (fun th -> MESON_TAC[th; ECBA_IMP_BALG;
       EBALG_IMP_PORDER]); ALL_TAC] THEN
  (* the empty set is the bottom of B *)
  USE_THEN "modl" (X_CHOOSE_THEN `z0:A` (LABEL_TAC "z0e") o MATCH_MP
                   EEMPTY_EXISTS) THEN
  SUBGOAL_THEN `(z0:A) IN D` (LABEL_TAC "z0D") THENL
   [USE_THEN "z0e" (ACCEPT_TAC o CONJUNCT1 o
                    REWRITE_RULE[eempty]); ALL_TAC] THEN
  SUBGOAL_THEN `ebot D (E:A->A->bool) B inclB z0` (LABEL_TAC "z0bot") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`B:A`;`inclB:A`;
                  `z0:A`] EBOT_ROSET) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  (* the weights *)
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`Ix:A`;`h:A`;
                `ra:A`] GDISJ_W) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `g:A` (CONJUNCTS_THEN2 (LABEL_TAC "gD")
      (CONJUNCTS_THEN2 (LABEL_TAC "gtot")
       (CONJUNCTS_THEN2 (LABEL_TAC "gsem")
        (CONJUNCTS_THEN2 (LABEL_TAC "gfun")
         (CONJUNCTS_THEN2 (LABEL_TAC "gle")
          (CONJUNCTS_THEN2 (LABEL_TAC "gdisj") (LABEL_TAC "gsup")))))))) THEN
  USE_THEN "modl" (X_CHOOSE_TAC `v0:num->A` o MATCH_MP VALUATION_EXISTS o
                   MATCH_MP MODEL_NONEMPTY) THEN
  SUBGOAL_THEN `valuation D ((7 |-> (g:A))
      ((3 |-> (inclB:A)) ((2 |-> (B:A)) (v0:num->A))))` (LABEL_TAC "vV0") THENL
   [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC) THEN
    FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  (* Qs = {i IN Ix | g_i <> bot} *)
  USE_THEN "modl" (MP_TAC o SPECL
    [`?? 30 (apply_form 7 0 30 && Not (bbot_form 3 2 30))`; `0`;
     `(7 |-> (g:A)) ((3 |-> (inclB:A)) ((2 |-> (B:A)) (v0:num->A)))`; `Ix:A`] o
    MATCH_MP ZF_SEPARATION) THEN
  ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `Qs:A` (CONJUNCTS_THEN2 (LABEL_TAC "QsD")
      (LABEL_TAC "Qsch0"))) THEN
  SUBGOAL_THEN
   `!i:A. i IN D
          ==> ((E:A->A->bool) i Qs <=>
               E i Ix /\ ?y. y IN D /\ eapply D E g i y /\ ~ebot D E B inclB y)`
   (LABEL_TAC "Qsch") THENL
   [X_GEN_TAC `i:A` THEN DISCH_THEN(LABEL_TAC "iD") THEN
    USE_THEN "Qsch0" (MP_TAC o SPEC `i:A`) THEN
    ANTS_TAC THENL [USE_THEN "iD" ACCEPT_TAC; DISCH_THEN SUBST1_TAC] THEN
    MATCH_MP_TAC(TAUT `(b <=> b') ==> (a /\ b <=> a /\ b')`) THEN
    REWRITE_TAC[HOLDS_EX; HOLDS_AND; HOLDS_NOT] THEN
    MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s))
     ==> ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
    X_GEN_TAC `y:A` THEN DISCH_THEN(LABEL_TAC "yD") THEN
    SUBGOAL_THEN `valuation D ((30 |-> (y:A))
        ((0 |-> (i:A)) ((7 |-> (g:A)) ((3 |-> (inclB:A))
        ((2 |-> (B:A)) (v0:num->A))))))` (LABEL_TAC "v30") THENL
     [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC) THEN
      FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    USE_THEN "v30" (fun vth -> USE_THEN "modl" (fun mth ->
      SIMP_TAC[vth; mth; HOLDS_APPLY_FORM; HOLDS_BBOT_FORM])) THEN
    REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) Qs Ix` (LABEL_TAC "QsIx") THENL
   [REWRITE_TAC[esubset] THEN X_GEN_TAC `i:A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "iD") (LABEL_TAC "iQ")) THEN
    USE_THEN "Qsch" (MP_TAC o SPEC `i:A`) THEN
    ANTS_TAC THENL [USE_THEN "iD" ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "iQ" (MP_TAC o EQ_MP th)) THEN
    DISCH_THEN(ACCEPT_TAC o CONJUNCT1);
    ALL_TAC] THEN
  (* the antichain Gs = { g_i | i IN Qs } and the injection c = g restricted *)
  (* to Qs                                                                   *)
  SUBGOAL_THEN `valuation D ((8 |-> (Qs:A))
      ((7 |-> (g:A)) ((3 |-> (inclB:A)) ((2 |-> (B:A)) (v0:num->A)))))`
      (LABEL_TAC "vV") THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THEN
    FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  USE_THEN "modl" (MP_TAC o SPECL
    [`?? 30 ((30 %% 8) && apply_form 7 30 0)`; `0`;
     `(8 |-> (Qs:A)) ((7 |-> (g:A)) ((3 |-> (inclB:A))
        ((2 |-> (B:A)) (v0:num->A))))`; `B:A`] o
    MATCH_MP ZF_SEPARATION) THEN
  ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `Gs:A` (CONJUNCTS_THEN2 (LABEL_TAC "GsD")
      (LABEL_TAC "Gsch0"))) THEN
  SUBGOAL_THEN
   `!y:A. y IN D
          ==> ((E:A->A->bool) y Gs <=> E y B /\ ?i. i IN D /\ E i Qs /\
               eapply D E g i y)`
   (LABEL_TAC "Gsch") THENL
   [X_GEN_TAC `y:A` THEN DISCH_THEN(LABEL_TAC "yD") THEN
    USE_THEN "Gsch0" (MP_TAC o SPEC `y:A`) THEN
    ANTS_TAC THENL [USE_THEN "yD" ACCEPT_TAC; DISCH_THEN SUBST1_TAC] THEN
    MATCH_MP_TAC(TAUT `(b <=> b') ==> (a /\ b <=> a /\ b')`) THEN
    REWRITE_TAC[HOLDS_EX; HOLDS_AND] THEN
    MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s))
     ==> ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
    X_GEN_TAC `i:A` THEN DISCH_THEN(LABEL_TAC "iD") THEN
    SUBGOAL_THEN `valuation D ((30 |-> (i:A))
        ((0 |-> (y:A)) ((8 |-> (Qs:A)) ((7 |-> (g:A))
        ((3 |-> (inclB:A)) ((2 |-> (B:A)) (v0:num->A)))))))`
        (LABEL_TAC "v30") THENL
