                             `t:A`] EMEET_ABSORB_LE) THEN
        SUBGOAL_THEN `(E:A->A->bool) t B` (LABEL_TAC "tB") THENL
         [USE_THEN "gsem" (MP_TAC o SPECL [`k:A`;`t:A`]) THEN
          ANTS_TAC THENL [REPEAT CONJ_TAC THEN
                          FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
          DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "kIx") (K ALL_TAC)) THEN
          USE_THEN "htot" (MP_TAC o SPEC `k:A`) THEN
          ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
          DISCH_THEN(X_CHOOSE_THEN `hk:A` (CONJUNCTS_THEN2 (LABEL_TAC "hkD")
            (CONJUNCTS_THEN2 (K ALL_TAC) (LABEL_TAC "hkh")))) THEN
          USE_THEN "gle" (MP_TAC o SPECL [`k:A`;`t:A`;`hk:A`]) THEN
          ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                          DISCH_THEN(ACCEPT_TAC o CONJUNCT1)];
          ALL_TAC] THEN
        REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
        MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`t:A`]
                     EPORDER_REFL) THEN
        REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
        ALL_TAC] THEN
      USE_THEN "Qsch" (MP_TAC o SPEC `k:A`) THEN
      ANTS_TAC THENL [USE_THEN "kD" ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> USE_THEN "kQ" (MP_TAC o EQ_MP th)) THEN
      DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
                 (X_CHOOSE_THEN `t0:A` (CONJUNCTS_THEN2
        (LABEL_TAC "t0D") (CONJUNCTS_THEN2 (LABEL_TAC "gkt0")
                           (LABEL_TAC "nb0"))))) THEN
      USE_THEN "nb0" MP_TAC THEN REWRITE_TAC[] THEN
      SUBGOAL_THEN `(t0:A) = t` (fun th -> REWRITE_TAC[th] THEN
          USE_THEN "tbot" ACCEPT_TAC) THEN
      USE_THEN "gfun" (MP_TAC o SPECL [`k:A`;`t0:A`;`t:A`]) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN ACCEPT_TAC]];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`bp:A`;`inclB:A`;`Qs:A`;`Gs:A`;
                `cq:A`] CCC_ANTICHAIN_DOM) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `om':A` (X_CHOOSE_THEN `kk:A`
      (CONJUNCTS_THEN2 (LABEL_TAC "eom'")
    (LABEL_TAC "ikk")))) THEN
  SUBGOAL_THEN `(om':A) = om` SUBST_ALL_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`om':A`;`om:A`] EOMEGA_UNIQUE) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  EXISTS_TAC `Qs:A` THEN
  CONJ_TAC THENL [USE_THEN "QsD" ACCEPT_TAC; ALL_TAC] THEN
  CONJ_TAC THENL [USE_THEN "QsIx" ACCEPT_TAC; ALL_TAC] THEN
  CONJ_TAC THENL [EXISTS_TAC `kk:A` THEN
                  USE_THEN "ikk" ACCEPT_TAC; ALL_TAC] THEN
  X_GEN_TAC `w:A` THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "wD")
             (CONJUNCTS_THEN2 (LABEL_TAC "wB") (LABEL_TAC "hQw"))) THEN
  USE_THEN "gsup" (MP_TAC o SPEC `w:A`) THEN
  ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
  CONJ_TAC THENL [USE_THEN "wD" ACCEPT_TAC; ALL_TAC] THEN
  CONJ_TAC THENL [USE_THEN "wB" ACCEPT_TAC; ALL_TAC] THEN
  MAP_EVERY X_GEN_TAC [`i:A`;`y:A`] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "iD")
             (CONJUNCTS_THEN2 (LABEL_TAC "yD") (LABEL_TAC "giy"))) THEN
  USE_THEN "gsem" (MP_TAC o SPECL [`i:A`;`y:A`]) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "iIx") (K ALL_TAC)) THEN
  USE_THEN "htot" (MP_TAC o SPEC `i:A`) THEN
  ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `hi:A` (CONJUNCTS_THEN2 (LABEL_TAC "hiD")
    (CONJUNCTS_THEN2 (LABEL_TAC "hiB") (LABEL_TAC "hih")))) THEN
  USE_THEN "gle" (MP_TAC o SPECL [`i:A`;`y:A`;`hi:A`]) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "yB") (LABEL_TAC "yhi")) THEN
  ASM_CASES_TAC `ebot D (E:A->A->bool) B inclB y` THENL
   [FIRST_X_ASSUM(MP_TAC o CONJUNCT2 o CONJUNCT2 o REWRITE_RULE[ebot] o
                  check (fun th -> concl th = `ebot D (E:A->A->bool) B
                         inclB y`)) THEN
    DISCH_THEN MATCH_MP_TAC THEN CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`y:A`;`hi:A`;
                       `w:A`] EPORDER_TRANS) THEN
  REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
  USE_THEN "hQw" MATCH_MP_TAC THEN
  EXISTS_TAC `i:A` THEN REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
  USE_THEN "Qsch" (MP_TAC o SPEC `i:A`) THEN
  ANTS_TAC THENL [USE_THEN "iD" ACCEPT_TAC; DISCH_THEN SUBST1_TAC] THEN
  CONJ_TAC THENL [USE_THEN "iIx" ACCEPT_TAC; ALL_TAC] THEN
  EXISTS_TAC `y:A` THEN REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC);;

(* ===================================================================== *)
(* H3.6a : esupp (the body of ehssym: "e is a countable support of nm"),   *)
(* its object formula nsupp_form, and the given-support versions of        *)
(* EHSSYM_ELIM / EHSSYM_ELIM_ALL (clones with e fixed).                     *)
(* ===================================================================== *)
let esupp = new_definition
 `esupp D (E:A->A->bool) B om P nm e <=>
    (?n. n IN D /\ E n om /\ ?f. ebij D E f n e) /\
    esubset D E e om /\
    (!s. s IN D /\ eperm D E om s /\ efixes D E s e
         ==> ?autB. autB IN D /\
               (?muci muP. muci IN D /\ muP IN D /\
                  (!u w. u IN D /\ w IN D
                         ==> (eapply D E muci u w <=> E u P /\
                              mucirel D E s u w)) /\
                  (!p q. p IN D /\ q IN D
                         ==> (eapply D E muP p q <=> E p P /\
                              muPrel D E muci p q)) /\
                  (!b c. b IN D /\ c IN D
                         ==> (eapply D E autB b c <=> E b B /\
                              muPrel D E muP b c))) /\
               eautn D E B autB nm nm)`;;

let EHSSYM_ESUPP = prove
 (`!D (E:A->A->bool) B om P nm.
     ehssym D E B om P nm <=> ?e. e IN D /\ esupp D E B om P nm e`,
  REWRITE_TAC[ehssym; esupp; GSYM CONJ_ASSOC]);;

let nsupp_form = new_definition
 `nsupp_form ie ix iom iP =
    finite_form ie iom && subset_form ie iom &&
    !! 42 ((permom_form 42 iom && fixes_form 42 ie) --> symfix_form 42 iP ix)`;;

let HOLDS_NSUPP_FORM = prove
 (`!D (E:A->A->bool) v ie ix iom iP.
      model D E ZF_AX /\ valuation D v /\
      ix < 30 /\ ~(ix = 3) /\ iP < 148 /\ ~(iP = 3) /\
      ~(iP = 42) /\ ~(iom = 42) /\ ~(ie = 42)
      ==> (holds D E v (nsupp_form ie ix iom iP) <=>
           esupp D E (v 2) (v iom) (v iP) (v ix) (v ie))`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[nsupp_form; esupp] THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN `~(ix = 42) /\ ~((2:num) = 42)` STRIP_ASSUME_TAC THENL
   [ASM_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[HOLDS_AND] THEN
  SUBGOAL_THEN
   `holds D E (v:num->A) (finite_form ie iom) <=>
    (?n. n IN D /\ E n (v iom) /\ ?f. ebij D E f n (v ie))`
  (LABEL_TAC "fin") THENL
   [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`;
                   `ie:num`; `iom:num`] HOLDS_FINITE_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN(fun th ->
        REWRITE_TAC[th])] THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `holds D E (v:num->A) (subset_form ie iom) <=>
    esubset D E (v ie) (v iom)`
  (LABEL_TAC "sub") THENL
   [REWRITE_TAC[HOLDS_SUBSET_FORM] THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `holds D E (v:num->A)
      (!! 42 ((permom_form 42 iom && fixes_form 42 ie)
              --> symfix_form 42 iP ix)) <=>
    (!s. s IN D /\ eperm D E (v iom) s /\ efixes D E s (v ie)
         ==> ?autB. autB IN D /\
               (?muci muP. muci IN D /\ muP IN D /\
                  (!u w. u IN D /\ w IN D
                         ==> (eapply D E muci u w <=>
                              E u (v iP) /\ mucirel D E s u w)) /\
                  (!p q. p IN D /\ q IN D
                         ==> (eapply D E muP p q <=>
                              E p (v iP) /\ muPrel D E muci p q)) /\
                  (!b c. b IN D /\ c IN D
                         ==> (eapply D E autB b c <=>
                              E b (v 2) /\ muPrel D E muP b c))) /\
               eautn D E (v 2) autB (v ix) (v ix))`
  (LABEL_TAC "fa") THENL
   [REWRITE_TAC[HOLDS_ALL] THEN
    MATCH_MP_TAC(MESON[]
     `(!s:A. s IN D ==> (R s <=> (B s /\ C s ==> G s)))
      ==> ((!s. s IN D ==> R s) <=> (!s. s IN D /\ B s /\ C s ==> G s))`) THEN
    X_GEN_TAC `s:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `valuation D ((42 |-> (s:A)) (v:num->A))`
    ASSUME_TAC THENL [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
        (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC)); ALL_TAC] THEN
    REWRITE_TAC[HOLDS_IMP; HOLDS_AND] THEN
    SUBGOAL_THEN
     `holds D E ((42 |-> (s:A)) (v:num->A)) (permom_form 42 iom) <=>
      eperm D E (v iom) s` SUBST1_TAC THENL
     [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`;
        `(42 |-> (s:A)) (v:num->A)`; `42`; `iom:num`]
        HOLDS_PERMOM_FORM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[];
                      DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `holds D E ((42 |-> (s:A)) (v:num->A)) (fixes_form 42 ie) <=>
      efixes D E s (v ie)` SUBST1_TAC THENL
     [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`;
        `(42 |-> (s:A)) (v:num->A)`; `42`; `ie:num`]
        HOLDS_FIXES_FORM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[];
                      DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `holds D E ((42 |-> (s:A)) (v:num->A)) (symfix_form 42 iP ix) <=>
      (?autB. autB IN D /\
          (?muci muP. muci IN D /\ muP IN D /\
             (!u w. u IN D /\ w IN D
                    ==> (eapply D E muci u w <=>
                         E u (v iP) /\ mucirel D E s u w)) /\
             (!p q. p IN D /\ q IN D
                    ==> (eapply D E muP p q <=>
                         E p (v iP) /\ muPrel D E muci p q)) /\
             (!b c. b IN D /\ c IN D
                    ==> (eapply D E autB b c <=>
                         E b (v 2) /\ muPrel D E muP b c))) /\
          eautn D E (v 2) autB (v ix) (v ix))` SUBST1_TAC THENL
     [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`;
        `(42 |-> (s:A)) (v:num->A)`; `42`; `iP:num`; `ix:num`]
        HOLDS_SYMFIX) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
        DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER];
      ALL_TAC] THEN
    REFL_TAC;
    ALL_TAC] THEN
  USE_THEN "fin" (fun a -> USE_THEN "sub" (fun b -> USE_THEN "fa" (fun c ->
    REWRITE_TAC[a; b; c]))));;

let ESUPP_ELIM = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X nm e.
      hsbundle D E w1 om tw ii ci P leqp B inclB onebee X /\
      e IN D /\ esupp D E B w1 X nm e
      ==> (?n. n IN D /\ E n w1 /\ ?f. ebij D E f n e) /\
              esubset D E e w1 /\
              (!s. s IN D /\ eperm D E w1 s /\ efixes D E s e
                   ==> ?muci muP autB.
                 muci IN D /\ muP IN D /\ autB IN D /\
                 ebij D E muci ci ci /\ ebij D E muP P P /\
                 ebij D E autB B B /\
                 (!u w. u IN D /\ w IN D
                        ==> (eapply D E muci u w <=>
                             E u ci /\ mucirel D E s u w)) /\
                 (!p q. p IN D /\ q IN D
                        ==> (eapply D E muP p q <=>
                             E p P /\ muPrel D E muci p q)) /\
                 (!b c. b IN D /\ c IN D
                        ==> (eapply D E autB b c <=>
                             E b B /\ muPrel D E muP b c)) /\
                 (!pa pb qa qb. pa IN D /\ pb IN D /\ qa IN D /\ qb IN D /\
                                eapply D E muP pa qa /\ eapply D E muP pb qb
                                ==> (erel D E leqp pa pb <=>
                                     erel D E leqp qa qb)) /\
                 (!a b ai bi. a IN D /\ b IN D /\ ai IN D /\ bi IN D /\
                              eapply D E autB a ai /\ eapply D E autB b bi
                              ==> (erel D E inclB a b <=>
                                   erel D E inclB ai bi)) /\
                 eautn D E B autB nm nm)`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (MP_TAC o REWRITE_RULE[hsbundle])
    (CONJUNCTS_THEN2 (LABEL_TAC "eD") (LABEL_TAC "hs"))) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
   (CONJUNCTS_THEN2 (LABEL_TAC "vl")
    (CONJUNCTS_THEN2 (LABEL_TAC "eom")
     (CONJUNCTS_THEN2 (LABEL_TAC "w1D")
      (CONJUNCTS_THEN2 (LABEL_TAC "w1card")
       (CONJUNCTS_THEN2 (LABEL_TAC "omw1")
        (CONJUNCTS_THEN2 (LABEL_TAC "w1min")
         (CONJUNCTS_THEN2 (LABEL_TAC "cr1")
          (CONJUNCTS_THEN2 (LABEL_TAC "cr2")
           (CONJUNCTS_THEN2 (LABEL_TAC "ftw")
            (CONJUNCTS_THEN2 (LABEL_TAC "coh")
             (CONJUNCTS_THEN2 (LABEL_TAC "leq")
              (CONJUNCTS_THEN2 (LABEL_TAC "ros")
               (CONJUNCTS_THEN2 (LABEL_TAC "inc")
                (CONJUNCTS_THEN2 (LABEL_TAC "porder")
                 (CONJUNCTS_THEN2 (LABEL_TAC "top")
                  (CONJUNCTS_THEN2 (LABEL_TAC "oneD")
                   (CONJUNCTS_THEN2 (LABEL_TAC "BD")
                    (CONJUNCTS_THEN2 (LABEL_TAC "oneB")
                     (CONJUNCTS_THEN2 (LABEL_TAC "XD")
                      (CONJUNCTS_THEN2 (LABEL_TAC "ciX")
                        (LABEL_TAC "PX")))))))))))))))))))))) THEN
  SUBGOAL_THEN
   `!p u. p IN D /\ E p P /\ u IN D /\ E u p ==> (E:A->A->bool) u ci`
   (LABEL_TAC "Pci") THENL
   [REPEAT GEN_TAC THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "pD")
               (CONJUNCTS_THEN2 (LABEL_TAC "pP")
      (CONJUNCTS_THEN2 (LABEL_TAC "uD") (LABEL_TAC "up")))) THEN
    USE_THEN "coh" (MP_TAC o SPEC `p:A` o CONJUNCT2 o
                    REWRITE_RULE[ecohenp]) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "pP" (MP_TAC o EQ_MP th)) THEN
    DISCH_THEN(MP_TAC o SPEC `u:A` o REWRITE_RULE[esubset] o CONJUNCT1) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!bb x. bb IN D /\ E bb B /\ x IN D /\ E x bb ==> (E:A->A->bool) x P`
   (LABEL_TAC "BP") THENL
   [REPEAT GEN_TAC THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "bbD")
               (CONJUNCTS_THEN2 (LABEL_TAC "bbB")
      (CONJUNCTS_THEN2 (LABEL_TAC "xD") (LABEL_TAC "xbb")))) THEN
    USE_THEN "ros" (MP_TAC o SPEC `bb:A` o CONJUNCT2 o
                    REWRITE_RULE[eroset]) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "bbB" (MP_TAC o EQ_MP th)) THEN
    DISCH_THEN(MP_TAC o SPEC `x:A` o REWRITE_RULE[esubset] o CONJUNCT1) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  USE_THEN "hs" (MP_TAC o REWRITE_RULE[esupp]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "efin")
             (CONJUNCTS_THEN2 (LABEL_TAC "esub")
      (LABEL_TAC "fall"))) THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "efin" ACCEPT_TAC; USE_THEN "esub" ACCEPT_TAC; ALL_TAC] THEN
  X_GEN_TAC `s:A` THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "sD")
             (CONJUNCTS_THEN2 (LABEL_TAC "sperm")
    (LABEL_TAC "sfix"))) THEN
  USE_THEN "fall" (MP_TAC o SPEC `s:A`) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `autB:A` (CONJUNCTS_THEN2 (LABEL_TAC "aD")
    (CONJUNCTS_THEN2 (X_CHOOSE_THEN `muci:A` (X_CHOOSE_THEN `muP:A`
      (CONJUNCTS_THEN2 (LABEL_TAC "mD") (CONJUNCTS_THEN2 (LABEL_TAC "PD")
        (CONJUNCTS_THEN2 (LABEL_TAC "mch") (CONJUNCTS_THEN2 (LABEL_TAC "Pch")
          (LABEL_TAC "ach")))))))
     (LABEL_TAC "fixnm")))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;
                `ii:A`;`ci:A`;`P:A`;
                `leqp:A`;`s:A`] PERM_MUP_BUNDLE) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `muci0:A` (X_CHOOSE_THEN `muP0:A`
    (CONJUNCTS_THEN2 (LABEL_TAC "m0D") (CONJUNCTS_THEN2 (LABEL_TAC "P0D")
     (CONJUNCTS_THEN2 (LABEL_TAC "bm0") (CONJUNCTS_THEN2 (LABEL_TAC "bP0")
      (CONJUNCTS_THEN2 (LABEL_TAC "mch0") (CONJUNCTS_THEN2 (LABEL_TAC "Pch0")
        (LABEL_TAC "quadP0"))))))))) THEN
  SUBGOAL_THEN
   `!b c. b IN D /\ c IN D
          ==> (eapply D (E:A->A->bool) autB b c <=> E b B /\
               muPrel D E muP0 b c)`
   (LABEL_TAC "ach0") THENL
   [MAP_EVERY X_GEN_TAC [`b:A`;`c:A`] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "bD") (LABEL_TAC "cD")) THEN
    USE_THEN "ach" (MP_TAC o SPECL [`b:A`;`c:A`]) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MATCH_MP_TAC(TAUT `(a ==> (b <=> c)) ==> (a /\ b <=> a /\ c)`) THEN
    DISCH_THEN(LABEL_TAC "bB") THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`ci:A`;`P:A`;`B:A`;`X:A`;`s:A`;
                  `muci:A`;`muP:A`;`muci0:A`;`muP0:A`;`b:A`;`c:A`]
      MUPREL_X_AGREE) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `ebij D (E:A->A->bool) autB B B` (LABEL_TAC "bA") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`B:A`;`muP0:A`;
                  `autB:A`] EAUTB_EBIJ) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!a b ai bi. a IN D /\ b IN D /\ ai IN D /\ bi IN D /\
                eapply D (E:A->A->bool) autB a ai /\ eapply D E autB b bi
                ==> (erel D E inclB a b <=> erel D E inclB ai bi)`
   (LABEL_TAC "quadB") THENL
   [MAP_EVERY X_GEN_TAC [`a:A`;`b:A`;`ai:A`;`bi:A`] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "a_D")
               (CONJUNCTS_THEN2 (LABEL_TAC "b_D")
      (CONJUNCTS_THEN2 (LABEL_TAC "ai_D") (CONJUNCTS_THEN2 (LABEL_TAC "bi_D")
        (CONJUNCTS_THEN2 (LABEL_TAC "aai") (LABEL_TAC "bbi")))))) THEN
    USE_THEN "ach0" (MP_TAC o SPECL [`a:A`;`ai:A`]) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "aai" (MP_TAC o EQ_MP th)) THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "aB") (LABEL_TAC "maai")) THEN
    USE_THEN "ach0" (MP_TAC o SPECL [`b:A`;`bi:A`]) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "bbi" (MP_TAC o EQ_MP th)) THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "bB") (LABEL_TAC "mbbi")) THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`B:A`;`inclB:A`;
                  `muP0:A`;`a:A`;`b:A`;`ai:A`;`bi:A`] EAUTB_ORDER) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`muci0:A`;`muP0:A`;`autB:A`] THEN
  REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC);;

let ESUPP_ELIM_ALL = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X nm e.
      hsbundle D E w1 om tw ii ci P leqp B inclB onebee X /\
      e IN D /\ esupp D E B w1 X nm e
      ==> (?n. n IN D /\ E n w1 /\ ?f. ebij D E f n e) /\
              esubset D E e w1 /\
              (!s. s IN D /\ eperm D E w1 s /\ efixes D E s e
                   ==> !muci muP autB.
                         muci IN D /\ muP IN D /\ autB IN D /\
                         (!u w. u IN D /\ w IN D
                                ==> (eapply D E muci u w <=>
                                     E u ci /\ mucirel D E s u w)) /\
                         (!p q. p IN D /\ q IN D
                                ==> (eapply D E muP p q <=>
                                     E p P /\ muPrel D E muci p q)) /\
                         (!b c. b IN D /\ c IN D
                                ==> (eapply D E autB b c <=>
                                     E b B /\ muPrel D E muP b c))
                         ==> eautn D E B autB nm nm)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  SUBGOAL_THEN `model D (E:A->A->bool) ZF_AX /\ (B:A) IN D`
   (CONJUNCTS_THEN2 (LABEL_TAC "modl") (LABEL_TAC "BD")) THENL
   [FIRST_ASSUM(MP_TAC o REWRITE_RULE[hsbundle] o CONJUNCT1) THEN MESON_TAC[];
    ALL_TAC] THEN
  FIRST_ASSUM(MP_TAC o MATCH_MP ESUPP_ELIM) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "efin")
             (CONJUNCTS_THEN2 (LABEL_TAC "esub")
      (LABEL_TAC "fall"))) THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "efin" ACCEPT_TAC; USE_THEN "esub" ACCEPT_TAC; ALL_TAC] THEN
  X_GEN_TAC `s:A` THEN DISCH_THEN(LABEL_TAC "sfx") THEN
  MAP_EVERY X_GEN_TAC [`muci:A`;`muP:A`;`autB:A`] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "mD") (CONJUNCTS_THEN2 (LABEL_TAC "PD")
    (CONJUNCTS_THEN2 (LABEL_TAC "aD") (CONJUNCTS_THEN2 (LABEL_TAC "mch")
      (CONJUNCTS_THEN2 (LABEL_TAC "Pch") (LABEL_TAC "ach")))))) THEN
  USE_THEN "fall" (MP_TAC o SPEC `s:A`) THEN
  ANTS_TAC THENL [USE_THEN "sfx" ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `muci0:A` (X_CHOOSE_THEN `muP0:A`
      (X_CHOOSE_THEN `autB0:A`
    (CONJUNCTS_THEN2 (K ALL_TAC) (CONJUNCTS_THEN2 (K ALL_TAC)
     (CONJUNCTS_THEN2 (LABEL_TAC "a0D") (CONJUNCTS_THEN2 (K ALL_TAC)
      (CONJUNCTS_THEN2 (K ALL_TAC) (CONJUNCTS_THEN2 (K ALL_TAC)
       (CONJUNCTS_THEN2 (LABEL_TAC "mch0") (CONJUNCTS_THEN2 (LABEL_TAC "Pch0")
        (CONJUNCTS_THEN2 (LABEL_TAC "ach0") (CONJUNCTS_THEN2 (K ALL_TAC)
         (CONJUNCTS_THEN2 (K ALL_TAC) (LABEL_TAC "fix0"))))))))))))))) THEN
  SUBGOAL_THEN
   `!c c'. c IN D /\ c' IN D
           ==> (eapply D (E:A->A->bool) autB0 c c' <=> eapply D E autB c c')`
   (LABEL_TAC "gr") THENL
   [MATCH_MP_TAC BUNDLE_AGREE THEN
    MAP_EVERY EXISTS_TAC [`ci:A`;`P:A`;`B:A`;`s:A`;`muci0:A`;`muP0:A`;
                          `muci:A`;`muP:A`] THEN
    REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB0:A`;
                `autB:A`;`nm:A`;`nm:A`]
    EAUTN_CONG) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN USE_THEN "fix0" ACCEPT_TAC);;

(* ===================================================================== *)
(* H3.6b : CSUPPORT_CHOICE -- a countable set of HS names has ONE common   *)
(* countable support: supports chosen by ECHOOSE_INJ_GEN along an ordinal *)
(* enumeration n ~ Qs (CSUPPORT_OF_INJ), countable union by              *)
(* EGEN_UNION_CARD_LE (kk = om), each support transported by             *)
(* ESUPP_ELIM_ALL.                                                        *)
(* ===================================================================== *)
let CSUPPORT_CHOICE = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X Qs k.
     hsbundle D E w1 om tw ii ci P leqp B inclB onebee X /\
     Qs IN D /\ einj D E k Qs om /\
     (!q. q IN D /\ E q Qs ==> hsname D E B w1 X q)
     ==> ?e. e IN D /\ (?n. n IN D /\ E n w1 /\ ?f. ebij D E f n e) /\
             esubset D E e w1 /\
             (!q. q IN D /\ E q Qs
                  ==> !s. s IN D /\ eperm D E w1 s /\ efixes D E s e
                          ==> !muci muP autB.
                            muci IN D /\ muP IN D /\ autB IN D /\
                            (!u w. u IN D /\ w IN D
                                   ==> (eapply D E muci u w <=>
                                        E u ci /\ mucirel D E s u w)) /\
                            (!p q. p IN D /\ q IN D
                                   ==> (eapply D E muP p q <=>
                                        E p P /\ muPrel D E muci p q)) /\
                            (!b c. b IN D /\ c IN D
                                   ==> (eapply D E autB b c <=>
                                        E b B /\ muPrel D E muP b c))
                            ==> eautn D E B autB q q)`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "hsb")
             (CONJUNCTS_THEN2 (LABEL_TAC "QsD")
              (CONJUNCTS_THEN2 (LABEL_TAC "ik") (LABEL_TAC "hsQ")))) THEN
  USE_THEN "hsb" (MP_TAC o MATCH_MP HSB_FACTS) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "omD")
             (CONJUNCTS_THEN2 (LABEL_TAC "w1ord")
              (CONJUNCTS_THEN2 (LABEL_TAC "PD")
               (CONJUNCTS_THEN2 (LABEL_TAC "ciD")
                (CONJUNCTS_THEN2 (LABEL_TAC "iiD") (LABEL_TAC "omw1")))))) THEN
  USE_THEN "hsb" (MP_TAC o REWRITE_RULE[hsbundle]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
             (CONJUNCTS_THEN2 (LABEL_TAC "vl")
              (CONJUNCTS_THEN2 (LABEL_TAC "eom")
               (CONJUNCTS_THEN2 (LABEL_TAC "w1D")
                (CONJUNCTS_THEN2 (LABEL_TAC "w1card")
                 (CONJUNCTS_THEN2 (LABEL_TAC "omw1e")
                  (CONJUNCTS_THEN2 (LABEL_TAC "w1min")
                   (CONJUNCTS_THEN2 (LABEL_TAC "cr1")
                    (CONJUNCTS_THEN2 (LABEL_TAC "cr2")
                     (CONJUNCTS_THEN2 (LABEL_TAC "ftw")
                      (CONJUNCTS_THEN2 (LABEL_TAC "coh")
                       (CONJUNCTS_THEN2 (LABEL_TAC "leq")
                        (CONJUNCTS_THEN2 (LABEL_TAC "ros")
                         (CONJUNCTS_THEN2 (LABEL_TAC "inc")
                          (CONJUNCTS_THEN2 (LABEL_TAC "porder")
      (CONJUNCTS_THEN2 (LABEL_TAC "top")
       (CONJUNCTS_THEN2 (LABEL_TAC "oneD")
        (CONJUNCTS_THEN2 (LABEL_TAC "BD")
         (CONJUNCTS_THEN2 (LABEL_TAC "oneB")
          (CONJUNCTS_THEN2 (LABEL_TAC "XD")
           (CONJUNCTS_THEN2 (LABEL_TAC "ciX")
            (LABEL_TAC "PX")))))))))))))))))))))) THEN
  (* enumerate Qs by an ordinal n IN w1 *)
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;
                `ii:A`;`ci:A`;`P:A`;
                `leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`Qs:A`;`k:A`]
                    CSUPPORT_OF_INJ) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `n:A` (CONJUNCTS_THEN2 (LABEL_TAC "nD")
      (CONJUNCTS_THEN2 (LABEL_TAC "nw1")
       (X_CHOOSE_THEN `f:A` (LABEL_TAC "fbij"))))) THEN
  SUBGOAL_THEN `(f:A) IN D` (LABEL_TAC "fD") THENL
   [USE_THEN "fbij" (ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[ebij]); ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) n` (LABEL_TAC "nord") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`n:A`] EORDINAL_MEMBER) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  (* Pw = P(w1), Cr = n x Pw *)
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`] EPOW_EXISTS) THEN
  ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `Pw:A` (MP_TAC o REWRITE_RULE[epow])) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "PwD") (LABEL_TAC "Pwch")) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`n:A`;`Pw:A`] ECROSS_EXISTS) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `Cr:A` (MP_TAC o REWRITE_RULE[ecross])) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "CrD") (LABEL_TAC "Crch")) THEN
  (* tt = { <b,e> IN Cr | e supports f(b) } *)
  USE_THEN "modl" (X_CHOOSE_TAC `v0:num->A` o MATCH_MP VALUATION_EXISTS o
                   MATCH_MP MODEL_NONEMPTY) THEN
  SUBGOAL_THEN `valuation D ((13 |-> (f:A))
      ((9 |-> (X:A)) ((8 |-> (w1:A)) ((2 |-> (B:A)) (v0:num->A)))))`
      (LABEL_TAC "vW1") THENL
   [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC) THEN
    FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  USE_THEN "modl" (MP_TAC o SPECL
    [`?? 10 (?? 11 (opair_form 10 11 0 &&
                    ?? 12 (apply_form 13 10 12 && nsupp_form 11 12 8 9)))`;
     `0`; `(13 |-> (f:A)) ((9 |-> (X:A))
                           ((8 |-> (w1:A)) ((2 |-> (B:A)) (v0:num->A))))`;
         `Cr:A`] o MATCH_MP ZF_SEPARATION) THEN
  ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `tt:A` (CONJUNCTS_THEN2 (LABEL_TAC "ttD")
      (LABEL_TAC "ttch0"))) THEN
  SUBGOAL_THEN
   `!p:A. p IN D
          ==> ((E:A->A->bool) p tt <=>
               E p Cr /\ ?b. b IN D /\ ?e. e IN D /\ eopair D E b e p /\
                     ?q. q IN D /\ eapply D E f b q /\ esupp D E B w1 X q e)`
   (LABEL_TAC "ttch") THENL
   [X_GEN_TAC `p:A` THEN DISCH_THEN(LABEL_TAC "pD") THEN
    USE_THEN "ttch0" (MP_TAC o SPEC `p:A`) THEN
    ANTS_TAC THENL [USE_THEN "pD" ACCEPT_TAC; DISCH_THEN SUBST1_TAC] THEN
    MATCH_MP_TAC(TAUT `(b <=> b') ==> (a /\ b <=> a /\ b')`) THEN
    REWRITE_TAC[HOLDS_EX; HOLDS_AND; GSYM CONJ_ASSOC] THEN
    MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s))
     ==> ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
    X_GEN_TAC `b:A` THEN DISCH_THEN(LABEL_TAC "bD") THEN
    MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s))
     ==> ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
    X_GEN_TAC `e:A` THEN DISCH_THEN(LABEL_TAC "eD") THEN
    SUBGOAL_THEN
     `valuation D ((11 |-> (e:A)) ((10 |-> (b:A))
         ((0 |-> (p:A)) ((13 |-> (f:A)) ((9 |-> (X:A))
         ((8 |-> (w1:A)) ((2 |-> (B:A)) (v0:num->A))))))))`
     (LABEL_TAC "v11") THENL
     [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC) THEN
      FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    MATCH_MP_TAC(TAUT `(a <=> a') /\ (b <=> b') ==> (a /\ b <=> a' /\ b')`)
        THEN CONJ_TAC THENL
     [USE_THEN "v11" (fun vth -> SIMP_TAC[vth; HOLDS_OPAIR_FORM]) THEN
      REWRITE_TAC[VALMOD; ARITH_EQ];
      ALL_TAC] THEN
    MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s))
     ==> ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
    X_GEN_TAC `q:A` THEN DISCH_THEN(LABEL_TAC "qD") THEN
    SUBGOAL_THEN
     `valuation D ((12 |-> (q:A)) ((11 |-> (e:A))
         ((10 |-> (b:A)) ((0 |-> (p:A)) ((13 |-> (f:A))
         ((9 |-> (X:A)) ((8 |-> (w1:A)) ((2 |-> (B:A)) (v0:num->A)))))))))`
     (LABEL_TAC "v12") THENL
     [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC) THEN
      FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    MATCH_MP_TAC(TAUT `(a <=> a') /\ (b <=> b') ==> (a /\ b <=> a' /\ b')`)
        THEN CONJ_TAC THENL
     [USE_THEN "v12" (fun vth -> SIMP_TAC[vth; HOLDS_APPLY_FORM]) THEN
      REWRITE_TAC[VALMOD; ARITH_EQ];
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;
      `(12 |-> (q:A)) ((11 |-> (e:A)) ((10 |-> (b:A))
          ((0 |-> (p:A)) ((13 |-> (f:A)) ((9 |-> (X:A))
          ((8 |-> (w1:A)) ((2 |-> (B:A)) (v0:num->A))))))))`;
      `11`;`12`;`8`;`9`] HOLDS_NSUPP_FORM) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN
                    TRY(FIRST_ASSUM ACCEPT_TAC) THEN ARITH_TAC;
                    DISCH_THEN SUBST1_TAC] THEN
    REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  (* the ECHOOSE form *)
  SUBGOAL_THEN
   `!p:A. p IN D
          ==> ((E:A->A->bool) p tt <=>
               ?b e. b IN D /\ e IN D /\ E b n /\ eopair D E b e p /\
                     (\b e. ?q. q IN D /\ eapply D E f b q /\
                      esupp D (E:A->A->bool) B w1 X q e) b e)`
   (LABEL_TAC "ttc") THENL
   [X_GEN_TAC `p:A` THEN DISCH_THEN(LABEL_TAC "pD") THEN
    USE_THEN "ttch" (MP_TAC o SPEC `p:A`) THEN
    ANTS_TAC THENL [USE_THEN "pD" ACCEPT_TAC; DISCH_THEN SUBST1_TAC] THEN
    BETA_TAC THEN EQ_TAC THENL
     [DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "pCr")
        (X_CHOOSE_THEN `b:A` (CONJUNCTS_THEN2 (LABEL_TAC "bD")
                              (X_CHOOSE_THEN `e:A`
          (CONJUNCTS_THEN2 (LABEL_TAC "eD") (CONJUNCTS_THEN2 (LABEL_TAC "op")
            (LABEL_TAC "qs"))))))) THEN
      USE_THEN "Crch" (MP_TAC o SPEC `p:A`) THEN
      ANTS_TAC THENL [USE_THEN "pD" ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> USE_THEN "pCr" (MP_TAC o EQ_MP th)) THEN
      DISCH_THEN(X_CHOOSE_THEN `u:A` (X_CHOOSE_THEN `w:A`
          (CONJUNCTS_THEN2 (LABEL_TAC "uD")
        (CONJUNCTS_THEN2 (LABEL_TAC "wD") (CONJUNCTS_THEN2 (LABEL_TAC "un")
          (CONJUNCTS_THEN2 (K ALL_TAC) (LABEL_TAC "op'"))))))) THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`b:A`;`e:A`;`u:A`;`w:A`;`p:A`]
             EOPAIR_INJ) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(CONJUNCTS_THEN2 SUBST_ALL_TAC SUBST_ALL_TAC) THEN
      MAP_EVERY EXISTS_TAC [`u:A`;`w:A`] THEN REPEAT CONJ_TAC THEN
          FIRST_ASSUM ACCEPT_TAC;
      DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `e:A`
          (CONJUNCTS_THEN2 (LABEL_TAC "bD")
        (CONJUNCTS_THEN2 (LABEL_TAC "eD") (CONJUNCTS_THEN2 (LABEL_TAC "bn")
          (CONJUNCTS_THEN2 (LABEL_TAC "op") (LABEL_TAC "qs"))))))) THEN
      CONJ_TAC THENL
       [USE_THEN "Crch" (MP_TAC o SPEC `p:A`) THEN
        ANTS_TAC THENL [USE_THEN "pD" ACCEPT_TAC; DISCH_THEN SUBST1_TAC] THEN
        MAP_EVERY EXISTS_TAC [`b:A`;`e:A`] THEN REPEAT CONJ_TAC THEN
            TRY(FIRST_ASSUM ACCEPT_TAC) THEN
        USE_THEN "Pwch" (MP_TAC o SPEC `e:A`) THEN
        ANTS_TAC THENL [USE_THEN "eD" ACCEPT_TAC; DISCH_THEN SUBST1_TAC] THEN
        USE_THEN "qs" (X_CHOOSE_THEN `q:A` (CONJUNCTS_THEN2 (K ALL_TAC)
          (CONJUNCTS_THEN2 (K ALL_TAC) (MP_TAC o REWRITE_RULE[esupp])))) THEN
        DISCH_THEN(ACCEPT_TAC o CONJUNCT1 o CONJUNCT2);
        EXISTS_TAC `b:A` THEN CONJ_TAC THENL
            [USE_THEN "bD" ACCEPT_TAC; ALL_TAC] THEN
        EXISTS_TAC `e:A` THEN REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC]];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`n:A`;`tt:A`] ESLICE_FAMILY_A) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ww:A` (CONJUNCTS_THEN2 (LABEL_TAC "wwD")
      (LABEL_TAC "wwch"))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`n:A`;`om:A`;`tt:A`;`ww:A`;
                `(\b e. ?q. q IN D /\ eapply D E f b q /\
                  esupp D (E:A->A->bool) B w1 X q e)`] ECHOOSE_INJ_GEN) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    X_GEN_TAC `m:A` THEN DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "mD")
        (LABEL_TAC "mn")) THEN
    USE_THEN "fbij" (MP_TAC o SPEC `m:A` o CONJUNCT1 o CONJUNCT2 o CONJUNCT2 o
                     REWRITE_RULE[ebij]) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
