  ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
  CONJ_TAC THENL [USE_THEN "sfix" ACCEPT_TAC; ALL_TAC] THEN
  REWRITE_TAC[esubset] THEN X_GEN_TAC `u:A` THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "uD") (LABEL_TAC "uz")) THEN
  USE_THEN "wunch" (MP_TAC o SPEC `u:A`) THEN
  ANTS_TAC THENL [USE_THEN "uD" ACCEPT_TAC; DISCH_THEN SUBST1_TAC] THEN
  MAP_EVERY EXISTS_TAC [`m:A`;`z:A`] THEN REPEAT CONJ_TAC THEN
      FIRST_ASSUM ACCEPT_TAC);;

(* ===================================================================== *)
(* H3.5 : HSVAL_GRAPH -- the value graph q |-> [[p(q)]]^HS over a set Is   *)
(* of HS names is an internal function h (separation over Is x B with the  *)
(* BVAL_HS_DEFINABLE formula; base valuation as in HSVAL_ATTAIN).          *)
(* ===================================================================== *)
let HSVAL_GRAPH = prove
 (`!n p D (E:A->A->bool) B leq w1 X v Is.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
         w1 IN D /\ X IN D /\
     valuation D v /\ (!i. hsname D E B w1 X (v i)) /\
     Is IN D /\ (!q. q IN D /\ E q Is ==> hsname D E B w1 X q)
     ==> ?h. h IN D /\
             (!q y. q IN D /\ y IN D /\ eapply D E h q y
                    ==> E q Is /\ y = bvalf_HS D E B leq w1 X
                        ((n |-> q) v) p) /\
             (!q. q IN D /\ E q Is
                  ==> eapply D E h q (bvalf_HS D E B leq w1 X
                                      ((n |-> q) v) p))`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
             (CONJUNCTS_THEN2 (LABEL_TAC "cba")
              (CONJUNCTS_THEN2 (LABEL_TAC "BD")
               (CONJUNCTS_THEN2 (LABEL_TAC "leqD")
                (CONJUNCTS_THEN2 (LABEL_TAC "w1D")
                 (CONJUNCTS_THEN2 (LABEL_TAC "XD")
                  (CONJUNCTS_THEN2 (LABEL_TAC "vv")
                   (CONJUNCTS_THEN2 (LABEL_TAC "hsv")
                    (CONJUNCTS_THEN2 (LABEL_TAC "IsD")
                     (LABEL_TAC "hsI")))))))))) THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` (LABEL_TAC "vD") THENL
   [USE_THEN "vv" (ACCEPT_TAC o REWRITE_RULE[valuation]); ALL_TAC] THEN
  X_CHOOSE_TAC `fp:form` (ISPECL [`p:form`; `5`; `3`] BVAL_HS_DEFINABLE) THEN
  ABBREV_TAC `w0 = (9 |-> (X:A)) ((8 |-> (w1:A))
      ((2 |-> (B:A)) ((3 |-> (leq:A)) (\k. (v:num->A) (k - 32)))))` THEN
  SUBGOAL_THEN
   `valuation D (w0:num->A) /\ w0 2 = B /\ w0 3 = leq /\
    w0 8 = w1 /\ w0 9 = X /\
    (!i. w0 (32 + i) = (v:num->A) i)`
   (CONJUNCTS_THEN2 (LABEL_TAC "vw0") (CONJUNCTS_THEN2 (LABEL_TAC "w02")
     (CONJUNCTS_THEN2 (LABEL_TAC "w03") (CONJUNCTS_THEN2 (LABEL_TAC "w08")
       (CONJUNCTS_THEN2 (LABEL_TAC "w09") (LABEL_TAC "w0v")))))) THENL
   [EXPAND_TAC "w0" THEN REPEAT CONJ_TAC THENL
     [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]) THEN
      REWRITE_TAC[valuation] THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[VALMOD; ARITH_EQ];
      REWRITE_TAC[VALMOD; ARITH_EQ];
      REWRITE_TAC[VALMOD; ARITH_EQ];
      REWRITE_TAC[VALMOD; ARITH_EQ];
      GEN_TAC THEN
      SIMP_TAC[VALMOD_OTHER; ARITH_RULE `~(32 + i = 2) /\ ~(32 + i = 3) /\
                                         ~(32 + i = 8) /\ ~(32 + i = 9)`] THEN
      AP_TERM_TAC THEN ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!ww:num->A. valuation D ww /\ ww 2 = B /\ ww 3 = leq /\
       ww 8 = w1 /\ ww 9 = X /\
                (!i. ~(i = n) ==> ww (32 + i) = (v:num->A) i)
                ==> (holds D (E:A->A->bool) ww fp <=>
                     bval_HS D E B leq w1 X ((n |-> ww (32 + n)) v) p (ww 5))`
   (LABEL_TAC "sem") THENL
   [X_GEN_TAC `ww:num->A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "vww")
               (CONJUNCTS_THEN2 (LABEL_TAC "ww2")
                (CONJUNCTS_THEN2 (LABEL_TAC "ww3")
                 (CONJUNCTS_THEN2 (LABEL_TAC "ww8")
                  (CONJUNCTS_THEN2 (LABEL_TAC "ww9") (LABEL_TAC "wwv")))))) THEN
    FIRST_X_ASSUM(fun th -> MP_TAC(SPECL
        [`D:A->bool`; `E:A->A->bool`; `ww:num->A`] th) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN ARITH_TAC; ALL_TAC]) THEN
    DISCH_THEN SUBST1_TAC THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC BVAL_HS_FV THEN X_GEN_TAC `i:num` THEN DISCH_TAC THEN
    ASM_CASES_TAC `i:num = n` THEN ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`Is:A`;`B:A`] ECROSS_EXISTS) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `Cr:A` (MP_TAC o REWRITE_RULE[ecross])) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "CrD") (LABEL_TAC "Crch")) THEN
  USE_THEN "modl" (MP_TAC o SPECL
    [`?? (32 + n) (?? 5 (opair_form (32 + n) 5 0 && fp))`; `0`;
     `w0:num->A`; `Cr:A`] o
    MATCH_MP ZF_SEPARATION) THEN
  ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `h:A` (CONJUNCTS_THEN2 (LABEL_TAC "hD")
      (LABEL_TAC "hch0"))) THEN
  SUBGOAL_THEN
   `!z:A. z IN D
          ==> ((E:A->A->bool) z h <=>
               E z Cr /\ ?q. q IN D /\ ?y. y IN D /\ eopair D E q y z /\
                             bval_HS D E B leq w1 X ((n |-> q) v) p y)`
   (LABEL_TAC "hch") THENL
   [X_GEN_TAC `z:A` THEN DISCH_THEN(LABEL_TAC "zD") THEN
    USE_THEN "hch0" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [USE_THEN "zD" ACCEPT_TAC; DISCH_THEN SUBST1_TAC] THEN
    MATCH_MP_TAC(TAUT `(b <=> b') ==> (a /\ b <=> a /\ b')`) THEN
    REWRITE_TAC[HOLDS_EX; HOLDS_AND] THEN
    MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s))
     ==> ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
    X_GEN_TAC `q:A` THEN DISCH_THEN(LABEL_TAC "qD") THEN
    MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s))
     ==> ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
    X_GEN_TAC `y:A` THEN DISCH_THEN(LABEL_TAC "yD") THEN
    SUBGOAL_THEN `valuation D ((5 |-> (y:A))
        (((32 + n) |-> (q:A)) ((0 |-> (z:A)) (w0:num->A))))`
        (LABEL_TAC "vy") THENL
     [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC) THEN
      FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    MATCH_MP_TAC(TAUT `(a <=> a') /\ (b <=> b') ==> (a /\ b <=> a' /\ b')`)
        THEN CONJ_TAC THENL
     [USE_THEN "vy" (fun vth -> SIMP_TAC[vth; HOLDS_OPAIR_FORM]) THEN
      SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER;
               ARITH_RULE `~(32 + n = 5) /\ ~(0 = 5) /\ ~(0 = 32 + n)`];
      ALL_TAC] THEN
    USE_THEN "sem" (MP_TAC o SPEC `(5 |-> (y:A))
                    (((32 + n) |-> (q:A)) ((0 |-> (z:A)) (w0:num->A)))`) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THENL
       [USE_THEN "vy" ACCEPT_TAC;
        ASM_SIMP_TAC[VALMOD_OTHER; ARITH_RULE `~(2 = 5) /\
                     ~(2 = 32 + n) /\ ~(2 = 0)`];
        ASM_SIMP_TAC[VALMOD_OTHER; ARITH_RULE `~(3 = 5) /\
                     ~(3 = 32 + n) /\ ~(3 = 0)`];
        ASM_SIMP_TAC[VALMOD_OTHER; ARITH_RULE `~(8 = 5) /\
                     ~(8 = 32 + n) /\ ~(8 = 0)`];
        ASM_SIMP_TAC[VALMOD_OTHER; ARITH_RULE `~(9 = 5) /\
                     ~(9 = 32 + n) /\ ~(9 = 0)`];
        X_GEN_TAC `i:num` THEN DISCH_TAC THEN
        ASM_SIMP_TAC[VALMOD_OTHER; ARITH_RULE `~(i = n) ==> ~(32 + i = 32 + n)`;
                     ARITH_RULE `~(32 + i = 5) /\ ~(32 + i = 0)`]];
      DISCH_THEN SUBST1_TAC] THEN
    SIMP_TAC[VALMOD_OTHER; VALMOD_BASIC; ARITH_RULE `~(32 + n = 5)`];
    ALL_TAC] THEN
  EXISTS_TAC `h:A` THEN CONJ_TAC THENL [USE_THEN "hD" ACCEPT_TAC; ALL_TAC] THEN
  CONJ_TAC THENL
   [MAP_EVERY X_GEN_TAC [`q:A`;`y:A`] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "qD")
               (CONJUNCTS_THEN2 (LABEL_TAC "yD")
      (MP_TAC o REWRITE_RULE[eapply]))) THEN
    DISCH_THEN(X_CHOOSE_THEN `z:A` (CONJUNCTS_THEN2 (LABEL_TAC "op")
        (LABEL_TAC "zh"))) THEN
    SUBGOAL_THEN `(z:A) IN D` (LABEL_TAC "zD") THENL
     [USE_THEN "op" (ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
    USE_THEN "hch" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [USE_THEN "zD" ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "zh" (MP_TAC o EQ_MP th)) THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "zCr") (X_CHOOSE_THEN `q':A`
      (CONJUNCTS_THEN2 (LABEL_TAC "q'D") (X_CHOOSE_THEN `y':A`
        (CONJUNCTS_THEN2 (LABEL_TAC "y'D") (CONJUNCTS_THEN2 (LABEL_TAC "op'")
          (LABEL_TAC "bv"))))))) THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`q:A`;`y:A`;`q':A`;`y':A`;`z:A`]
           EOPAIR_INJ) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (SUBST_ALL_TAC o SYM) (SUBST_ALL_TAC o SYM)) THEN
    SUBGOAL_THEN `(E:A->A->bool) q Is` (LABEL_TAC "qI") THENL
     [USE_THEN "Crch" (MP_TAC o SPEC `z:A`) THEN
      ANTS_TAC THENL [USE_THEN "zD" ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> USE_THEN "zCr" (MP_TAC o EQ_MP th)) THEN
      DISCH_THEN(X_CHOOSE_THEN `u:A` (X_CHOOSE_THEN `w:A`
          (CONJUNCTS_THEN2 (LABEL_TAC "uD")
        (CONJUNCTS_THEN2 (LABEL_TAC "wD") (CONJUNCTS_THEN2 (LABEL_TAC "uI")
          (CONJUNCTS_THEN2 (K ALL_TAC) (LABEL_TAC "op''"))))))) THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`q:A`;`y:A`;`u:A`;`w:A`;`z:A`]
             EOPAIR_INJ) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(SUBST1_TAC o CONJUNCT1) THEN USE_THEN "uI" ACCEPT_TAC;
      ALL_TAC] THEN
    CONJ_TAC THENL [USE_THEN "qI" ACCEPT_TAC; ALL_TAC] THEN
    USE_THEN "hsI" (MP_TAC o SPEC `q:A`) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN(LABEL_TAC "hsq")] THEN
    SUBGOAL_THEN `valuation D ((n |-> (q:A)) (v:num->A)) /\
                  (!i. hsname D (E:A->A->bool) B w1 X (((n |-> (q:A)) v) i))`
      (CONJUNCTS_THEN2 (LABEL_TAC "vnq") (LABEL_TAC "hsnq")) THENL
     [CONJ_TAC THENL
       [MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
        MATCH_MP_TAC HSNAMEVAL_VALMOD THEN CONJ_TAC THEN
            FIRST_ASSUM ACCEPT_TAC];
      ALL_TAC] THEN
    MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                   `leq:A`;`w1:A`;`X:A`;
                   `(n |-> (q:A)) (v:num->A)`] BVALF_HS_SPEC) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "bfD") (LABEL_TAC "bfsp")) THEN
    MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                   `leq:A`;`w1:A`;`X:A`;
                   `(n |-> (q:A)) (v:num->A)`; `y:A`;
                       `bvalf_HS D (E:A->A->bool) B leq w1 X
                       ((n |-> (q:A)) (v:num->A)) p`] BVAL_HS_UNIQUE) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  X_GEN_TAC `q:A` THEN DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "qD")
      (LABEL_TAC "qI")) THEN
  USE_THEN "hsI" (MP_TAC o SPEC `q:A`) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN(LABEL_TAC "hsq")] THEN
    SUBGOAL_THEN `valuation D ((n |-> (q:A)) (v:num->A)) /\
                  (!i. hsname D (E:A->A->bool) B w1 X (((n |-> (q:A)) v) i))`
      (CONJUNCTS_THEN2 (LABEL_TAC "vnq") (LABEL_TAC "hsnq")) THENL
     [CONJ_TAC THENL
       [MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
        MATCH_MP_TAC HSNAMEVAL_VALMOD THEN CONJ_TAC THEN
            FIRST_ASSUM ACCEPT_TAC];
      ALL_TAC] THEN
    MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                   `leq:A`;`w1:A`;`X:A`;
                   `(n |-> (q:A)) (v:num->A)`] BVALF_HS_SPEC) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "bfD") (LABEL_TAC "bfsp")) THEN
  MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;`X:A`;
                 `(n |-> (q:A)) (v:num->A)`] BVALF_HS_IN_B) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                  DISCH_THEN(LABEL_TAC "bfB")] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`q:A`;
                `bvalf_HS D (E:A->A->bool) B leq w1 X ((n |-> (q:A)) (v:num->A))
      p`] EOPAIR_EXISTS) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `z:A` (LABEL_TAC "op")) THEN
  SUBGOAL_THEN `(z:A) IN D` (LABEL_TAC "zD") THENL
   [USE_THEN "op" (ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
  REWRITE_TAC[eapply] THEN EXISTS_TAC `z:A` THEN
  CONJ_TAC THENL [USE_THEN "op" ACCEPT_TAC; ALL_TAC] THEN
  USE_THEN "hch" (MP_TAC o SPEC `z:A`) THEN
  ANTS_TAC THENL [USE_THEN "zD" ACCEPT_TAC; DISCH_THEN SUBST1_TAC] THEN
  CONJ_TAC THENL
   [USE_THEN "Crch" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [USE_THEN "zD" ACCEPT_TAC; DISCH_THEN SUBST1_TAC] THEN
    MAP_EVERY EXISTS_TAC [`q:A`; `bvalf_HS D (E:A->A->bool) B leq w1 X
                          ((n |-> (q:A)) (v:num->A)) p`] THEN
    REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    EXISTS_TAC `q:A` THEN CONJ_TAC THENL
        [USE_THEN "qD" ACCEPT_TAC; ALL_TAC] THEN
    EXISTS_TAC `bvalf_HS D (E:A->A->bool) B leq w1 X ((n |-> (q:A)) (v:num->A))
        p` THEN REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC]);;

(* ===================================================================== *)
(* H3.7a : PARAM_CSUPPORT -- finitely many HS parameters v i (i IN fv)     *)
(* have ONE common countable support (induction on the finite index set:  *)
(* CSUPPORT_EMPTY, HSNAME_SYM + EHSSYM_ELIM_ALL, CSUPPORT_UNION).          *)
(* ===================================================================== *)
let PARAM_CSUPPORT = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X (v:num->A).
     hsbundle D E w1 om tw ii ci P leqp B inclB onebee X /\
     (!i. v i IN D) /\ (!i. hsname D E B w1 X (v i))
     ==> !fv:num->bool.
           FINITE fv
           ==> ?e. e IN D /\ (?n. n IN D /\ E n w1 /\ ?f. ebij D E f n e) /\
                   esubset D E e w1 /\
                   (!s. s IN D /\ eperm D E w1 s /\ efixes D E s e
                        ==> !muci muP autB.
                            muci IN D /\ muP IN D /\ autB IN D /\
                            (!u w. u IN D /\ w IN D
                                   ==> (eapply D E muci u w <=>
                                        E u ci /\ mucirel D E s u w)) /\
                            (!p q. p IN D /\ q IN D
                                   ==> (eapply D E muP p q <=>
                                        E p P /\ muPrel D E muci p q)) /\
                            (!b c. b IN D /\ c IN D
                                   ==> (eapply D E autB b c <=>
                                        E b B /\ muPrel D E muP b c))
                            ==> !i. i IN fv ==> eautn D E B autB (v i) (v i))`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "hsb")
             (CONJUNCTS_THEN2 (LABEL_TAC "vD") (LABEL_TAC "hsv"))) THEN
  SUBGOAL_THEN `model D (E:A->A->bool) ZF_AX /\ (B:A) IN D /\
      (w1:A) IN D /\ (X:A) IN D`
   (CONJUNCTS_THEN2 (LABEL_TAC "modl") (CONJUNCTS_THEN2 (LABEL_TAC "BD")
     (CONJUNCTS_THEN2 (LABEL_TAC "w1D") (LABEL_TAC "XD")))) THENL
   [USE_THEN "hsb" (MP_TAC o REWRITE_RULE[hsbundle]) THEN
    MESON_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC FINITE_INDUCT_STRONG THEN CONJ_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;`ii:A`;`ci:A`;
                  `P:A`;`leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`]
       CSUPPORT_EMPTY) THEN
    ANTS_TAC THENL [USE_THEN "hsb" ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `e:A` (CONJUNCTS_THEN2 (LABEL_TAC "eD")
        (CONJUNCTS_THEN2 (K ALL_TAC)
      (CONJUNCTS_THEN2 (LABEL_TAC "efin") (LABEL_TAC "esub"))))) THEN
    EXISTS_TAC `e:A` THEN REPEAT CONJ_TAC THENL
     [USE_THEN "eD" ACCEPT_TAC; USE_THEN "efin" ACCEPT_TAC;
      USE_THEN "esub" ACCEPT_TAC;
      REWRITE_TAC[NOT_IN_EMPTY]];
    ALL_TAC] THEN
  MAP_EVERY X_GEN_TAC [`x:num`; `fv:num->bool`] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (X_CHOOSE_THEN `e1:A`
      (CONJUNCTS_THEN2 (LABEL_TAC "e1D")
    (CONJUNCTS_THEN2 (LABEL_TAC "e1fin") (CONJUNCTS_THEN2 (LABEL_TAC "e1sub")
      (LABEL_TAC "e1fix"))))) (K ALL_TAC)) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;`(v:num->A) x`]
         HSNAME_SYM) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN FIRST [FIRST_ASSUM ACCEPT_TAC;
                                USE_THEN "vD" (ACCEPT_TAC o SPEC `x:num`);
                                USE_THEN "hsv" (ACCEPT_TAC o SPEC `x:num`)];
    DISCH_THEN(LABEL_TAC "symx")] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;`ii:A`;`ci:A`;
                `P:A`;`leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`(v:num->A) x`]
      EHSSYM_ELIM_ALL) THEN
  ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ex:A` (CONJUNCTS_THEN2 (LABEL_TAC "exD")
    (CONJUNCTS_THEN2 (LABEL_TAC "exfin") (CONJUNCTS_THEN2 (LABEL_TAC "exsub")
      (LABEL_TAC "exfix"))))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;`ii:A`;`ci:A`;
                `P:A`;`leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`e1:A`;`ex:A`]
      CSUPPORT_UNION) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `e:A` (CONJUNCTS_THEN2 (LABEL_TAC "eD")
    (CONJUNCTS_THEN2 (LABEL_TAC "efin") (CONJUNCTS_THEN2 (LABEL_TAC "esub")
      (CONJUNCTS_THEN2 (LABEL_TAC "e1e") (LABEL_TAC "exe")))))) THEN
  EXISTS_TAC `e:A` THEN REPEAT CONJ_TAC THENL
   [USE_THEN "eD" ACCEPT_TAC; USE_THEN "efin" ACCEPT_TAC;
    USE_THEN "esub" ACCEPT_TAC;
    ALL_TAC] THEN
  X_GEN_TAC `s:A` THEN DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "sD")
    (CONJUNCTS_THEN2 (LABEL_TAC "sperm") (LABEL_TAC "sfix"))) THEN
  MAP_EVERY X_GEN_TAC [`muci:A`;`muP:A`;`autB:A`] THEN
      DISCH_THEN(LABEL_TAC "chars") THEN
  X_GEN_TAC `i:num` THEN REWRITE_TAC[IN_INSERT] THEN
  DISCH_THEN(DISJ_CASES_THEN2 SUBST1_TAC (LABEL_TAC "ifv")) THENL
   [USE_THEN "exfix" (MP_TAC o SPEC `s:A`) THEN
       ANTS_TAC THENL
        [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
         MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`s:A`;`e:A`;`ex:A`]
                EFIXES_SUBSET) THEN
         ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                         DISCH_THEN ACCEPT_TAC];
         ALL_TAC] THEN
       DISCH_THEN(MP_TAC o SPECL [`muci:A`;`muP:A`;`autB:A`]) THEN
       ANTS_TAC THENL [USE_THEN "chars" ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    USE_THEN "e1fix" (MP_TAC o SPEC `s:A`) THEN
       ANTS_TAC THENL
        [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
         MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`s:A`;`e:A`;`e1:A`]
                EFIXES_SUBSET) THEN
         ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                         DISCH_THEN ACCEPT_TAC];
         ALL_TAC] THEN
       DISCH_THEN(MP_TAC o SPECL [`muci:A`;`muP:A`;`autB:A`]) THEN
       ANTS_TAC THENL [USE_THEN "chars" ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPEC `i:num`) THEN
    ANTS_TAC THENL [USE_THEN "ifv" ACCEPT_TAC; DISCH_THEN ACCEPT_TAC]]);;

(* ===================================================================== *)
(* H3.8a : EGW_FIX -- a GDISJ weight y = h(i) /\ ~lub{h(j) : j <ra i}  is  *)
(* fixed by autB whenever every value of h is (EAUTB_LUB/COMPL/MEET).      *)
(* ===================================================================== *)
let EGW_FIX = prove
 (`!D (E:A->A->bool) B inclB autB Ix h ra i y.
     model D E ZF_AX /\ ecba D E B inclB /\ B IN D /\ inclB IN D /\
     ebij D E autB B B /\
     (!a b ai bi. a IN D /\ b IN D /\ ai IN D /\ bi IN D /\
                  eapply D E autB a ai /\ eapply D E autB b bi
                  ==> (erel D E inclB a b <=> erel D E inclB ai bi)) /\
     (!j z. j IN D /\ E j Ix /\ z IN D /\ eapply D E h j z
            ==> E z B /\ eapply D E autB z z) /\
     i IN D /\ E i Ix /\ y IN D /\ egw D E B inclB Ix h ra i y
     ==> eapply D E autB y y`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
             (CONJUNCTS_THEN2 (LABEL_TAC "cba")
              (CONJUNCTS_THEN2 (LABEL_TAC "BD")
               (CONJUNCTS_THEN2 (LABEL_TAC "inclD")
                (CONJUNCTS_THEN2 (LABEL_TAC "bij")
                 (CONJUNCTS_THEN2 (LABEL_TAC "pres")
                  (CONJUNCTS_THEN2 (LABEL_TAC "hfix")
                   (CONJUNCTS_THEN2 (LABEL_TAC "iD")
                    (CONJUNCTS_THEN2 (LABEL_TAC "iIx")
                     (CONJUNCTS_THEN2 (LABEL_TAC "yD")
                      (MP_TAC o REWRITE_RULE[egw]))))))))))) THEN
  DISCH_THEN(X_CHOOSE_THEN `Pi:A` (CONJUNCTS_THEN2 (LABEL_TAC "PiD")
      (CONJUNCTS_THEN2 (LABEL_TAC "Pich")
       (X_CHOOSE_THEN `u:A` (CONJUNCTS_THEN2 (LABEL_TAC "uD")
      (CONJUNCTS_THEN2 (LABEL_TAC "ulub")
       (X_CHOOSE_THEN `hi:A` (CONJUNCTS_THEN2 (LABEL_TAC "hiD")
      (CONJUNCTS_THEN2 (LABEL_TAC "hih")
       (X_CHOOSE_THEN `c:A` (CONJUNCTS_THEN2 (LABEL_TAC "cD")
      (CONJUNCTS_THEN2 (LABEL_TAC "ccompl") (LABEL_TAC "ymeet"))))))))))))) THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B inclB /\ eporder D E B inclB`
   (CONJUNCTS_THEN2 (LABEL_TAC "balg") (LABEL_TAC "pord")) THENL
   [USE_THEN "cba" (fun th -> let b = MATCH_MP ECBA_IMP_BALG th in
      ACCEPT_TAC(CONJ b (MATCH_MP EBALG_IMP_PORDER b)));
    ALL_TAC] THEN
  USE_THEN "bij" (fun th -> let cs = CONJUNCTS(REWRITE_RULE[ebij] th) in
    LABEL_TAC "autBD" (el 0 cs) THEN LABEL_TAC "bijtot" (el 2 cs) THEN
    LABEL_TAC "bijsv" (el 3 cs)) THEN
  USE_THEN "hfix" (MP_TAC o SPECL [`i:A`;`hi:A`]) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "hiB") (LABEL_TAC "hifix")) THEN
  (* the lub u is fixed *)
  SUBGOAL_THEN `(E:A->A->bool) u B` (LABEL_TAC "uB") THENL
   [USE_THEN "ulub" (ACCEPT_TAC o CONJUNCT2 o MATCH_MP ELUB_IN); ALL_TAC] THEN
  USE_THEN "bijtot" (MP_TAC o SPEC `u:A`) THEN
  ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ui:A` (CONJUNCTS_THEN2 (LABEL_TAC "uiD")
    (CONJUNCTS_THEN2 (K ALL_TAC) (LABEL_TAC "aui")))) THEN
  SUBGOAL_THEN `muPrel D (E:A->A->bool) autB Pi Pi` (LABEL_TAC "mP") THENL
   [REWRITE_TAC[muPrel] THEN CONJ_TAC THENL
    [USE_THEN "PiD" ACCEPT_TAC; ALL_TAC] THEN
    X_GEN_TAC `yy:A` THEN DISCH_THEN(LABEL_TAC "yyD") THEN EQ_TAC THENL
     [DISCH_THEN(LABEL_TAC "yyP") THEN EXISTS_TAC `yy:A` THEN
      REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      USE_THEN "Pich" (MP_TAC o SPEC `yy:A`) THEN
      ANTS_TAC THENL [USE_THEN "yyD" ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> USE_THEN "yyP" (MP_TAC o EQ_MP th)) THEN
      DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (X_CHOOSE_THEN `j:A`
        (CONJUNCTS_THEN2 (LABEL_TAC "jD") (CONJUNCTS_THEN2 (LABEL_TAC "jIx")
          (CONJUNCTS_THEN2 (K ALL_TAC) (LABEL_TAC "hj")))))) THEN
      USE_THEN "hfix" (MP_TAC o SPECL [`j:A`;`yy:A`]) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN(ACCEPT_TAC o CONJUNCT2)];
      DISCH_THEN(X_CHOOSE_THEN `x:A` (CONJUNCTS_THEN2 (LABEL_TAC "xD")
        (CONJUNCTS_THEN2 (LABEL_TAC "xP") (LABEL_TAC "axy")))) THEN
      USE_THEN "Pich" (MP_TAC o SPEC `x:A`) THEN
      ANTS_TAC THENL [USE_THEN "xD" ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> USE_THEN "xP" (MP_TAC o EQ_MP th)) THEN
      DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (X_CHOOSE_THEN `j:A`
        (CONJUNCTS_THEN2 (LABEL_TAC "jD") (CONJUNCTS_THEN2 (LABEL_TAC "jIx")
          (CONJUNCTS_THEN2 (K ALL_TAC) (LABEL_TAC "hj")))))) THEN
      USE_THEN "hfix" (MP_TAC o SPECL [`j:A`;`x:A`]) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (LABEL_TAC "axx")) THEN
      SUBGOAL_THEN `yy:A = x` SUBST1_TAC THENL
       [USE_THEN "bijsv" (MP_TAC o SPECL [`x:A`;`yy:A`;`x:A`]) THEN
        ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                        DISCH_THEN ACCEPT_TAC];
        USE_THEN "xP" ACCEPT_TAC]];
    ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) Pi B` (LABEL_TAC "PiB") THENL
   [REWRITE_TAC[esubset] THEN X_GEN_TAC `yy:A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "yyD") (LABEL_TAC "yyP")) THEN
    USE_THEN "Pich" (MP_TAC o SPEC `yy:A`) THEN
    ANTS_TAC THENL [USE_THEN "yyD" ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "yyP" (MP_TAC o EQ_MP th)) THEN
    DISCH_THEN(ACCEPT_TAC o CONJUNCT1);
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`autB:A`;`Pi:A`;
                `Pi:A`;`u:A`;`ui:A`]
    EAUTB_LUB) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                  DISCH_THEN(LABEL_TAC "uilub")] THEN
  SUBGOAL_THEN `ui:A = u` SUBST_ALL_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`Pi:A`;`ui:A`;
                  `u:A`] ELUB_UNIQUE) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  (* the complement c is fixed *)
  SUBGOAL_THEN `(E:A->A->bool) c B` (LABEL_TAC "cB") THENL
   [USE_THEN "ccompl" (ACCEPT_TAC o CONJUNCT2 o MATCH_MP
                       ECOMPL_IN); ALL_TAC] THEN
  USE_THEN "bijtot" (MP_TAC o SPEC `c:A`) THEN
  ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ci:A` (CONJUNCTS_THEN2 (LABEL_TAC "ciD")
    (CONJUNCTS_THEN2 (K ALL_TAC) (LABEL_TAC "aci")))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`autB:A`;`u:A`;
                `c:A`;`u:A`;`ci:A`]
    EAUTB_COMPL) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                  DISCH_THEN(LABEL_TAC "cicompl")] THEN
  SUBGOAL_THEN `ci:A = c` SUBST_ALL_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`u:A`;`ci:A`;`c:A`]
           ECOMPL_UNIQUE) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  (* the meet y is fixed *)
  SUBGOAL_THEN `(E:A->A->bool) y B` (LABEL_TAC "yB") THENL
   [USE_THEN "ymeet" (ACCEPT_TAC o CONJUNCT2 o MATCH_MP EMEET_IN); ALL_TAC] THEN
  USE_THEN "bijtot" (MP_TAC o SPEC `y:A`) THEN
  ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `yi:A` (CONJUNCTS_THEN2 (LABEL_TAC "yiD")
    (CONJUNCTS_THEN2 (K ALL_TAC) (LABEL_TAC "ayi")))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`autB:A`;
                `hi:A`;`c:A`;`y:A`;
                `hi:A`;`c:A`;`yi:A`] EAUTB_MEET) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                  DISCH_THEN(LABEL_TAC "yimeet")] THEN
  SUBGOAL_THEN `yi:A = y` (fun th -> USE_THEN "ayi"
      (ACCEPT_TAC o REWRITE_RULE[th])) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`hi:A`;`c:A`;`yi:A`;
                `y:A`] EMEET_UNIQUE) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                  DISCH_THEN ACCEPT_TAC]);;

(* ===================================================================== *)
(* H3.8b : MIX_SYM -- the V^B mixture c over dd with weight graph g and    *)
(* domain W is FIXED by autN when every q IN dd is fixed, every weight is  *)
(* fixed, and W is autN-invariant (both ways).  Core: autB(c(x)) =         *)
(* c(autN x) via the section sets VS (MIX_APPLY_DEST + EAUTB_LUB/MEET +    *)
(* AUTN_MEM/AUTN_APPLY/AUTN_INJ); then extensionality on autN(c) = c.      *)
(* ===================================================================== *)
let MIX_SYM = prove
 (`!D (E:A->A->bool) B inclB autB dd g W v c.
     model D E ZF_AX /\ ecba D E B inclB /\ B IN D /\ inclB IN D /\
     ebij D E autB B B /\
     (!a b ai bi. a IN D /\ b IN D /\ ai IN D /\ bi IN D /\
                  eapply D E autB a ai /\ eapply D E autB b bi
                  ==> (erel D E inclB a b <=> erel D E inclB ai bi)) /\
     dd IN D /\ g IN D /\ W IN D /\
     valuation D v /\ v 1 = inclB /\ v 2 = B /\ v 5 = dd /\ v 15 = g /\
     c IN D /\ bname D E B c /\
     (!w. w IN D ==> (E w c <=>
             ?p. p IN D /\ E p W /\
                 holds D E ((20 |-> w)((16 |-> p) v)) phi_mixval)) /\
     (!q. q IN D /\ E q dd ==> bname D E B q /\ eautn D E B autB q q) /\
     (!q w. q IN D /\ E q dd /\ w IN D /\ eapply D E g q w
            ==> E w B /\ eapply D E autB w w) /\
     (!u. u IN D /\ E u W ==> ?u'. u' IN D /\ E u' W /\
      eautn D E B autB u u') /\
     (!u'. u' IN D /\ E u' W ==> ?u. u IN D /\ E u W /\ eautn D E B autB u u')
     ==> eautn D E B autB c c`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
             (CONJUNCTS_THEN2 (LABEL_TAC "cba")
              (CONJUNCTS_THEN2 (LABEL_TAC "BD")
               (CONJUNCTS_THEN2 (LABEL_TAC "inclD")
                (CONJUNCTS_THEN2 (LABEL_TAC "bij")
                 (CONJUNCTS_THEN2 (LABEL_TAC "pres")
                  (CONJUNCTS_THEN2 (LABEL_TAC "ddD")
                   (CONJUNCTS_THEN2 (LABEL_TAC "gD")
                    (CONJUNCTS_THEN2 (LABEL_TAC "WD")
                     (CONJUNCTS_THEN2 (LABEL_TAC "vv")
                      (CONJUNCTS_THEN2 (LABEL_TAC "v1")
                       (CONJUNCTS_THEN2 (LABEL_TAC "v2")
                        (CONJUNCTS_THEN2 (LABEL_TAC "v5")
                         (CONJUNCTS_THEN2 (LABEL_TAC "v15")
                          (CONJUNCTS_THEN2 (LABEL_TAC "cD")
      (CONJUNCTS_THEN2 (LABEL_TAC "bnc")
       (CONJUNCTS_THEN2 (LABEL_TAC "cch")
        (CONJUNCTS_THEN2 (LABEL_TAC "ddfix")
         (CONJUNCTS_THEN2 (LABEL_TAC "gfix")
          (CONJUNCTS_THEN2 (LABEL_TAC "Wfwd")
           (LABEL_TAC "Wbwd"))))))))))))))))))))) THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B inclB /\ eporder D E B inclB`
   (CONJUNCTS_THEN2 (LABEL_TAC "balg") (LABEL_TAC "pord")) THENL
   [USE_THEN "cba" (fun th -> let b = MATCH_MP ECBA_IMP_BALG th in
      ACCEPT_TAC(CONJ b (MATCH_MP EBALG_IMP_PORDER b)));
    ALL_TAC] THEN
  USE_THEN "bij" (fun th -> let cs = CONJUNCTS(REWRITE_RULE[ebij] th) in
    LABEL_TAC "autBD" (el 0 cs) THEN LABEL_TAC "bijtot" (el 2 cs) THEN
    LABEL_TAC "bijsv" (el 3 cs)) THEN
  (* (a) pointwise equivariance of the mixture values *)
  SUBGOAL_THEN
   `!x x' ax ax'. x IN D /\ x' IN D /\ ax IN D /\ ax' IN D /\
                  eautn D (E:A->A->bool) B autB x x' /\
                  eapply D E c x ax /\ eapply D E c x' ax'
                  ==> eapply D E autB ax ax'`
   (LABEL_TAC "equiv") THENL
   [MAP_EVERY X_GEN_TAC [`x:A`;`x':A`;`ax:A`;`ax':A`] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "xD")
               (CONJUNCTS_THEN2 (LABEL_TAC "x'D")
                (CONJUNCTS_THEN2 (LABEL_TAC "axD")
                 (CONJUNCTS_THEN2 (LABEL_TAC "ax'D")
                  (CONJUNCTS_THEN2 (LABEL_TAC "axx'")
                   (CONJUNCTS_THEN2 (LABEL_TAC "cxa")
                    (LABEL_TAC "cxa'"))))))) THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`dd:A`;`g:A`;`W:A`;
                  `v:num->A`;`c:A`;`x:A`;`ax:A`] MIX_APPLY_DEST) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `VS:A` (CONJUNCTS_THEN2 (LABEL_TAC "VSD")
        (CONJUNCTS_THEN2 (LABEL_TAC "VSch") (LABEL_TAC "VSlub")))) THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`dd:A`;`g:A`;`W:A`;
                  `v:num->A`;`c:A`;`x':A`;`ax':A`] MIX_APPLY_DEST) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `VS':A` (CONJUNCTS_THEN2 (LABEL_TAC "VS'D")
        (CONJUNCTS_THEN2 (LABEL_TAC "VS'ch") (LABEL_TAC "VS'lub")))) THEN
    SUBGOAL_THEN `(E:A->A->bool) ax B` (LABEL_TAC "axB") THENL
     [USE_THEN "VSlub" (ACCEPT_TAC o CONJUNCT2 o MATCH_MP
                        ELUB_IN); ALL_TAC] THEN
    USE_THEN "bijtot" (MP_TAC o SPEC `ax:A`) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `axi:A` (CONJUNCTS_THEN2 (LABEL_TAC "axiD")
      (CONJUNCTS_THEN2 (K ALL_TAC) (LABEL_TAC "aaxi")))) THEN
    SUBGOAL_THEN `esubset D (E:A->A->bool) VS B` (LABEL_TAC "VSB") THENL
     [REWRITE_TAC[esubset] THEN X_GEN_TAC `b:A` THEN
      DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "bD") (LABEL_TAC "bVS")) THEN
      USE_THEN "VSch" (MP_TAC o SPEC `b:A`) THEN
      ANTS_TAC THENL [USE_THEN "bD" ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> USE_THEN "bVS" (MP_TAC o EQ_MP th)) THEN
      DISCH_THEN(X_CHOOSE_THEN `a9:A` (X_CHOOSE_THEN `a10:A`
          (X_CHOOSE_THEN `a11:A` (X_CHOOSE_THEN `a12:A`
          (X_CHOOSE_THEN `a13:A` (CONJUNCTS_THEN2 (LABEL_TAC "a9D")
          (CONJUNCTS_THEN2 (LABEL_TAC "a10D")
           (CONJUNCTS_THEN2 (LABEL_TAC "a11D")
            (CONJUNCTS_THEN2 (LABEL_TAC "a12D")
             (CONJUNCTS_THEN2 (LABEL_TAC "a13D")
              (CONJUNCTS_THEN2 (LABEL_TAC "a9dd")
               (CONJUNCTS_THEN2 (LABEL_TAC "op1")
                (CONJUNCTS_THEN2 (LABEL_TAC "a11g")
                 (CONJUNCTS_THEN2 (LABEL_TAC "op2")
                  (CONJUNCTS_THEN2 (LABEL_TAC "a13a9")
                   (LABEL_TAC "mt")))))))))))))))) THEN
      USE_THEN "mt" (ACCEPT_TAC o CONJUNCT2 o MATCH_MP EMEET_IN);
      ALL_TAC] THEN
    SUBGOAL_THEN `muPrel D (E:A->A->bool) autB VS VS'` (LABEL_TAC "mP") THENL
     [REWRITE_TAC[muPrel] THEN CONJ_TAC THENL
      [USE_THEN "VS'D" ACCEPT_TAC; ALL_TAC] THEN
      X_GEN_TAC `yy:A` THEN DISCH_THEN(LABEL_TAC "yyD") THEN
      USE_THEN "VS'ch" (MP_TAC o SPEC `yy:A`) THEN
      ANTS_TAC THENL [USE_THEN "yyD" ACCEPT_TAC; DISCH_THEN SUBST1_TAC] THEN
