(*       MAXPRIN_ALL_HS (the HS maximum principle);                         *)
(* H3.10 qrep_HS / qdom_HS + LOS_HS (Los for the HS quotient, ANY U);       *)
(* H4.0  QVAL_LIFT_HS / QSAT_AX_HS / QDOM_HS_NONEMPTY (quotient bridge);    *)
(* H4.1  connective-TOP layer for bvalf_HS;                                 *)
(* H4.2  HSNAME_DOM (members of HS names).                                  *)
(* ######################################################################### *)
(* ===================================================================== *)
(* H3.8c : MIX_HS_EXISTS -- the V^B mixture over a set Qs of HS names with *)
(* weight graph g is an HS name, provided every bundle fixing a countable  *)
(* support e fixes each q IN Qs and each weight.  Domain W = U dom(q),     *)
(* carved from the stage set w of HSNAME_BOUND(Qs); c lies in that stage  *)
(* (HSSTAGE_INTRO); bname c via BNAME_BOUND(W) + MIX_BNAME; symmetry via   *)
(* EHSSYM_INTRO + MIX_SYM.                                                 *)
(* ===================================================================== *)
let MIX_HS_EXISTS = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X Qs g e.
     hsbundle D E w1 om tw ii ci P leqp B inclB onebee X /\
     Qs IN D /\ (!q. q IN D /\ E q Qs ==> hsname D E B w1 X q) /\
     g IN D /\
     (!q w. q IN D /\ E q Qs /\ w IN D /\ eapply D E g q w ==> E w B) /\
     e IN D /\ (?n. n IN D /\ E n w1 /\ ?f. ebij D E f n e) /\
         esubset D E e w1 /\
     (!s. s IN D /\ eperm D E w1 s /\ efixes D E s e
          ==> !muci muP autB. pbundle D E ci P leqp B inclB s muci muP autB
              ==> (!q. q IN D /\ E q Qs ==> eautn D E B autB q q) /\
                  (!q w. q IN D /\ E q Qs /\ w IN D /\ eapply D E g q w
                         ==> eapply D E autB w w))
     ==> ?c W vm. c IN D /\ hsname D E B w1 X c /\ bname D E B c /\ W IN D /\
                  valuation D vm /\ vm 1 = inclB /\ vm 2 = B /\
                      vm 5 = Qs /\ vm 15 = g /\
                  (!w. w IN D ==> (E w c <=>
                         ?p. p IN D /\ E p W /\
                             holds D E ((20 |-> w)((16 |-> p) vm))
                                 phi_mixval)) /\
                  (!q' u'. q' IN D /\ E q' Qs /\ eindom D E q' u' ==> E u' W)`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "hsb")
             (CONJUNCTS_THEN2 (LABEL_TAC "QsD")
              (CONJUNCTS_THEN2 (LABEL_TAC "hsQ")
               (CONJUNCTS_THEN2 (LABEL_TAC "gD")
                (CONJUNCTS_THEN2 (LABEL_TAC "gB")
                 (CONJUNCTS_THEN2 (LABEL_TAC "eD")
                  (CONJUNCTS_THEN2 (LABEL_TAC "efin")
                   (CONJUNCTS_THEN2 (LABEL_TAC "esub")
                    (LABEL_TAC "efix"))))))))) THEN
  USE_THEN "hsb" (MP_TAC o MATCH_MP HSB_FACTS) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "omD")
             (CONJUNCTS_THEN2 (LABEL_TAC "w1ord")
              (CONJUNCTS_THEN2 (LABEL_TAC "PD")
               (CONJUNCTS_THEN2 (LABEL_TAC "ciD")
                (CONJUNCTS_THEN2 (LABEL_TAC "iiD") (LABEL_TAC "omw1")))))) THEN
  USE_THEN "hsb" (MP_TAC o MATCH_MP HSB_CBA) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "cba")
             (CONJUNCTS_THEN2 (LABEL_TAC "inclD") (LABEL_TAC "leqpD"))) THEN
  USE_THEN "hsb" (MP_TAC o REWRITE_RULE[hsbundle]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
             (CONJUNCTS_THEN2 (LABEL_TAC "vl")
              (CONJUNCTS_THEN2 (LABEL_TAC "eom")
               (CONJUNCTS_THEN2 (LABEL_TAC "w1D")
                (CONJUNCTS_THEN2 (LABEL_TAC "w1card")
                 (CONJUNCTS_THEN2 (LABEL_TAC "omw1e")
                  (CONJUNCTS_THEN2 (LABEL_TAC "w1min")
                   (CONJUNCTS_THEN2 (LABEL_TAC "cr1")
                    (CONJUNCTS_THEN2 (LABEL_TAC "cr2")
                     (CONJUNCTS_THEN2 (LABEL_TAC "ftw")
                      (CONJUNCTS_THEN2 (LABEL_TAC "coh")
                       (CONJUNCTS_THEN2 (LABEL_TAC "leq")
                        (CONJUNCTS_THEN2 (LABEL_TAC "ros")
                         (CONJUNCTS_THEN2 (LABEL_TAC "inc")
                          (CONJUNCTS_THEN2 (LABEL_TAC "porder")
      (CONJUNCTS_THEN2 (LABEL_TAC "top")
       (CONJUNCTS_THEN2 (LABEL_TAC "oneD")
        (CONJUNCTS_THEN2 (LABEL_TAC "BD")
         (CONJUNCTS_THEN2 (LABEL_TAC "oneB")
          (CONJUNCTS_THEN2 (LABEL_TAC "XD")
           (CONJUNCTS_THEN2 (LABEL_TAC "ciX")
            (LABEL_TAC "PX")))))))))))))))))))))) THEN
  (* Qs inside one HS stage; its stage-domain set w *)
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;`Qs:A`]
         HSNAME_BOUND) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `c0:A` (X_CHOOSE_THEN `yc0:A`
      (CONJUNCTS_THEN2 (LABEL_TAC "c0D")
       (CONJUNCTS_THEN2 (LABEL_TAC "yc0D")
        (CONJUNCTS_THEN2 (LABEL_TAC "c0ord")
         (CONJUNCTS_THEN2 (LABEL_TAC "hsc0") (LABEL_TAC "bnd"))))))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;`c0:A`;`yc0:A`]
         HSSTAGE_CHAR) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `w:A` (CONJUNCTS_THEN2 (LABEL_TAC "wD")
      (CONJUNCTS_THEN2 (LABEL_TAC "wch") (LABEL_TAC "wfuns")))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w:A`] EBNFUNS_EXISTS) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `fw:A` (LABEL_TAC "fwch")) THEN
  SUBGOAL_THEN
   `!q u. q IN D /\ E q Qs /\ eindom D (E:A->A->bool) q u ==> u IN D /\ E u w`
   (LABEL_TAC "domq") THENL
   [MAP_EVERY X_GEN_TAC [`q:A`;`u:A`] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "qD")
               (CONJUNCTS_THEN2 (LABEL_TAC "qQ")
                (MP_TAC o REWRITE_RULE[eindom]))) THEN
    DISCH_THEN(X_CHOOSE_THEN `y:A` (CONJUNCTS_THEN2 (LABEL_TAC "yD")
      (MP_TAC o REWRITE_RULE[eapply]))) THEN
    DISCH_THEN(X_CHOOSE_THEN `z:A` (CONJUNCTS_THEN2 (LABEL_TAC "op")
        (LABEL_TAC "zq"))) THEN
    SUBGOAL_THEN `(z:A) IN D` (LABEL_TAC "zD") THENL
     [USE_THEN "op" (ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
    USE_THEN "bnd" (MP_TAC o SPEC `q:A`) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN(LABEL_TAC "qyc0")] THEN
    USE_THEN "wfuns" (MP_TAC o SPEC `q:A` o CONJUNCT2 o
                      REWRITE_RULE[ehsfuns]) THEN
    ANTS_TAC THENL [USE_THEN "qD" ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "qyc0" (MP_TAC o EQ_MP th)) THEN
    REWRITE_TAC[ehsmem; ebnmem] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (CONJUNCTS_THEN2 (K ALL_TAC)
        (X_CHOOSE_THEN `cr:A`
      (CONJUNCTS_THEN2 (LABEL_TAC "crD") (CONJUNCTS_THEN2 (LABEL_TAC "crx")
        (LABEL_TAC "qcr"))))) (K ALL_TAC)) THEN
    SUBGOAL_THEN `(E:A->A->bool) z cr` (LABEL_TAC "zcr") THENL
     [USE_THEN "qcr" (MP_TAC o SPEC `z:A` o REWRITE_RULE[esubset]) THEN
      ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`B:A`;`cr:A`;`z:A`]
           ECROSS_MEMBER) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "zcr" (MP_TAC o EQ_MP th)) THEN
    DISCH_THEN(X_CHOOSE_THEN `u0:A` (X_CHOOSE_THEN `w0:A`
        (CONJUNCTS_THEN2 (LABEL_TAC "u0D")
      (CONJUNCTS_THEN2 (LABEL_TAC "w0D") (CONJUNCTS_THEN2 (LABEL_TAC "u0w")
        (CONJUNCTS_THEN2 (K ALL_TAC) (LABEL_TAC "op0"))))))) THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`u:A`;`y:A`;`z:A`;`u0:A`;`w0:A`]
           EOPAIR_FST_DET) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN SUBST1_TAC THEN CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  (* W = the union of the domains of the q IN Qs *)
  USE_THEN "modl" (X_CHOOSE_TAC `v0:num->A` o MATCH_MP VALUATION_EXISTS o
                   MATCH_MP MODEL_NONEMPTY) THEN
  USE_THEN "modl" (MP_TAC o SPECL
    [`?? 21 ((21 %% 14) && ?? 22 (apply_form 21 0 22))`; `0`;
     `(14 |-> (Qs:A)) (v0:num->A)`; `w:A`] o MATCH_MP ZF_SEPARATION) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL [MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THEN
                    FIRST_ASSUM ACCEPT_TAC;
                    USE_THEN "wD" ACCEPT_TAC];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `W:A` (CONJUNCTS_THEN2 (LABEL_TAC "WD")
      (LABEL_TAC "Wch0"))) THEN
  SUBGOAL_THEN
   `!u:A. u IN D ==> ((E:A->A->bool) u W <=> ?q. q IN D /\ E q Qs /\
                      eindom D E q u)`
   (LABEL_TAC "Wch") THENL
   [X_GEN_TAC `u:A` THEN DISCH_THEN(LABEL_TAC "uD") THEN
    USE_THEN "Wch0" (MP_TAC o SPEC `u:A`) THEN
    ANTS_TAC THENL [USE_THEN "uD" ACCEPT_TAC; DISCH_THEN SUBST1_TAC] THEN
    SUBGOAL_THEN
     `holds D (E:A->A->bool) ((0 |-> (u:A)) ((14 |-> (Qs:A)) (v0:num->A)))
        (?? 21 ((21 %% 14) && ?? 22 (apply_form 21 0 22))) <=>
      ?q. q IN D /\ E q Qs /\ eindom D E q u`
     SUBST1_TAC THENL
     [REWRITE_TAC[HOLDS_EX; HOLDS_AND; eindom] THEN
      MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s))
     ==> ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
      X_GEN_TAC `q:A` THEN DISCH_THEN(LABEL_TAC "qD") THEN
      MATCH_MP_TAC(TAUT `(a <=> a') /\ (b <=> b') ==> (a /\ b <=> a' /\ b')`)
          THEN CONJ_TAC THENL
       [REWRITE_TAC[holds; VALMOD; ARITH_EQ]; ALL_TAC] THEN
      MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s))
     ==> ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
      X_GEN_TAC `y:A` THEN DISCH_THEN(LABEL_TAC "yD") THEN
      SUBGOAL_THEN
       `valuation D ((22 |-> (y:A)) ((21 |-> (q:A))
           ((0 |-> (u:A)) ((14 |-> (Qs:A)) (v0:num->A)))))`
       (LABEL_TAC "v22") THENL
       [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC) THEN
        FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      USE_THEN "v22" (fun vth -> SIMP_TAC[vth; HOLDS_APPLY_FORM]) THEN
      REWRITE_TAC[VALMOD; ARITH_EQ];
      ALL_TAC] THEN
    EQ_TAC THENL [DISCH_THEN(ACCEPT_TAC o CONJUNCT2); ALL_TAC] THEN
    DISCH_THEN(fun th -> CONJ_TAC THENL [ALL_TAC; ACCEPT_TAC th] THEN
      X_CHOOSE_THEN `q:A` (CONJUNCTS_THEN2 (LABEL_TAC "qD")
                           (CONJUNCTS_THEN2 (LABEL_TAC "qQ")
        (LABEL_TAC "qu"))) th) THEN
    USE_THEN "domq" (MP_TAC o SPECL [`q:A`;`u:A`]) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN(ACCEPT_TAC o CONJUNCT2)];
    ALL_TAC] THEN
  (* members of W are HS names (hence B-names) *)
  SUBGOAL_THEN `!u. u IN D /\ (E:A->A->bool) u W
      ==> hsname D E B w1 X u /\ bname D E B u`
   (LABEL_TAC "Whs") THENL
   [X_GEN_TAC `u:A` THEN DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "uD")
       (LABEL_TAC "uW")) THEN
    USE_THEN "Wch" (MP_TAC o SPEC `u:A`) THEN
    ANTS_TAC THENL [USE_THEN "uD" ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "uW" (MP_TAC o EQ_MP th)) THEN
    DISCH_THEN(X_CHOOSE_THEN `q:A` (CONJUNCTS_THEN2 (LABEL_TAC "qD")
        (CONJUNCTS_THEN2 (LABEL_TAC "qQ")
      (LABEL_TAC "qu")))) THEN
    USE_THEN "domq" (MP_TAC o SPECL [`q:A`;`u:A`]) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (LABEL_TAC "uw")) THEN
    USE_THEN "wch" (MP_TAC o SPEC `u:A`) THEN
    ANTS_TAC THENL [USE_THEN "uD" ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "uw" (MP_TAC o EQ_MP th)) THEN
    DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `z:A`
        (CONJUNCTS_THEN2 (LABEL_TAC "bD")
      (CONJUNCTS_THEN2 (LABEL_TAC "zD") (CONJUNCTS_THEN2 (LABEL_TAC "bc0")
        (CONJUNCTS_THEN2 (LABEL_TAC "hsbz") (LABEL_TAC "uz"))))))) THEN
    SUBGOAL_THEN `eordinal D (E:A->A->bool) b` (LABEL_TAC "bord") THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`c0:A`;`b:A`]
             EORDINAL_MEMBER) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `hsname D (E:A->A->bool) B w1 X u` (LABEL_TAC "hsu") THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;`b:A`;`z:A`;
                    `u:A`] HSNAME_STAGE) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    CONJ_TAC THENL [USE_THEN "hsu" ACCEPT_TAC; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;`u:A`]
           HSNAME_BNAME) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  (* a B-name stage above W, for MIX_BNAME *)
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`W:A`] BNAME_BOUND) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    X_GEN_TAC `u:A` THEN DISCH_TAC THEN
    USE_THEN "Whs" (MP_TAC o SPEC `u:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; DISCH_THEN(ACCEPT_TAC o CONJUNCT2)];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `c1:A` (X_CHOOSE_THEN `yc1:A`
      (CONJUNCTS_THEN2 (LABEL_TAC "c1D")
       (CONJUNCTS_THEN2 (LABEL_TAC "yc1D")
        (CONJUNCTS_THEN2 (LABEL_TAC "c1ord")
         (CONJUNCTS_THEN2 (LABEL_TAC "bnc1") (LABEL_TAC "bnd1"))))))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`c1:A`] ESUC_EXISTS) THEN
  ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `lam:A` (LABEL_TAC "lsuc")) THEN
  SUBGOAL_THEN `(lam:A) IN D` (LABEL_TAC "lamD") THENL
   [USE_THEN "lsuc" (ACCEPT_TAC o MATCH_MP ESUC_IN); ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) lam` (LABEL_TAC "lamord") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`c1:A`;`lam:A`] EORDINAL_ESUC) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) c1 lam` (LABEL_TAC "c1lam") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`c1:A`;`lam:A`] ESUC_MEMBER) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`lam:A`] EBNSTAGE_EXISTS) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ddl:A` (CONJUNCTS_THEN2 (LABEL_TAC "ddlD")
      (LABEL_TAC "bnl"))) THEN
  (* the mixing valuation and the mixture *)
  ABBREV_TAC `vm = (15 |-> (g:A)) ((5 |-> (Qs:A))
      ((2 |-> (B:A)) ((1 |-> (inclB:A)) (v0:num->A))))` THEN
  SUBGOAL_THEN
   `valuation D (vm:num->A) /\ vm 1 = inclB /\ vm 2 = B /\
       vm 5 = Qs /\ vm 15 = g`
   (CONJUNCTS_THEN2 (LABEL_TAC "vmv") (CONJUNCTS_THEN2 (LABEL_TAC "vm1")
     (CONJUNCTS_THEN2 (LABEL_TAC "vm2")
      (CONJUNCTS_THEN2 (LABEL_TAC "vm5") (LABEL_TAC "vm15"))))) THENL
   [EXPAND_TAC "vm" THEN REPEAT CONJ_TAC THENL
     [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC) THEN
      FIRST_ASSUM ACCEPT_TAC;
      REWRITE_TAC[VALMOD; ARITH_EQ]; REWRITE_TAC[VALMOD; ARITH_EQ];
      REWRITE_TAC[VALMOD; ARITH_EQ]; REWRITE_TAC[VALMOD; ARITH_EQ]];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`W:A`;`vm:num->A`]
