(* ===================================================================== *)
(* H3.8d : MAXPRIN_EX_HS_CORE -- the HS maximum principle, given ONE       *)
(* countable support ep of all parameters v i.  Witness = the symmetric    *)
(* mixture (MIX_HS_EXISTS) over the countable subfamily Qs (GDISJ_Q) of    *)
(* the attaining set Is (HSVAL_ATTAIN), with GDISJ_W weights; supports by  *)
(* CSUPPORT_CHOICE + CSUPPORT_UNION; weights fixed by SYM_BVALF_HS_PERM +  *)
(* EGW_FIX; [[p(c)]] >= each weight by MIX_EQ_GE + Leibniz.              *)
(* ===================================================================== *)
let MAXPRIN_EX_HS_CORE = prove
 (`!n p D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X v ep.
     hsbundle D E w1 om tw ii ci P leqp B inclB onebee X /\
     valuation D v /\ (!i. hsname D E B w1 X (v i)) /\
     ep IN D /\ (?nn. nn IN D /\ E nn w1 /\ ?f. ebij D E f nn ep) /\
         esubset D E ep w1 /\
     (!s. s IN D /\ eperm D E w1 s /\ efixes D E s ep
          ==> !muci muP autB. pbundle D E ci P leqp B inclB s muci muP autB
              ==> !i. eautn D E B autB (v i) (v i))
     ==> ?a. a IN D /\ hsname D E B w1 X a /\
             bvalf_HS D E B inclB w1 X ((n |-> a) v) p =
             bvalf_HS D E B inclB w1 X v (?? n p)`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "hsb")
             (CONJUNCTS_THEN2 (LABEL_TAC "vv")
              (CONJUNCTS_THEN2 (LABEL_TAC "hsv")
               (CONJUNCTS_THEN2 (LABEL_TAC "epD")
                (CONJUNCTS_THEN2 (LABEL_TAC "epfin")
                 (CONJUNCTS_THEN2 (LABEL_TAC "epsub")
                  (LABEL_TAC "epfix"))))))) THEN
  USE_THEN "hsb" (MP_TAC o MATCH_MP HSB_FACTS) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "omD")
             (CONJUNCTS_THEN2 (LABEL_TAC "w1ord")
              (CONJUNCTS_THEN2 (LABEL_TAC "PD")
               (CONJUNCTS_THEN2 (LABEL_TAC "ciD")
                (CONJUNCTS_THEN2 (LABEL_TAC "iiD") (LABEL_TAC "omw1")))))) THEN
  USE_THEN "hsb" (MP_TAC o MATCH_MP HSB_CBA) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "cba")
             (CONJUNCTS_THEN2 (LABEL_TAC "inclD") (LABEL_TAC "leqpD"))) THEN
  USE_THEN "hsb" (MP_TAC o REWRITE_RULE[hsbundle]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
             (CONJUNCTS_THEN2 (LABEL_TAC "vl")
              (CONJUNCTS_THEN2 (LABEL_TAC "eom")
               (CONJUNCTS_THEN2 (LABEL_TAC "w1D")
                (CONJUNCTS_THEN2 (LABEL_TAC "w1card")
                 (CONJUNCTS_THEN2 (LABEL_TAC "omw1e")
                  (CONJUNCTS_THEN2 (LABEL_TAC "w1min")
                   (CONJUNCTS_THEN2 (LABEL_TAC "cr1")
                    (CONJUNCTS_THEN2 (LABEL_TAC "cr2")
                     (CONJUNCTS_THEN2 (LABEL_TAC "ftw")
                      (CONJUNCTS_THEN2 (LABEL_TAC "coh")
                       (CONJUNCTS_THEN2 (LABEL_TAC "leq")
                        (CONJUNCTS_THEN2 (LABEL_TAC "ros")
                         (CONJUNCTS_THEN2 (LABEL_TAC "inc")
                          (CONJUNCTS_THEN2 (LABEL_TAC "porder")
      (CONJUNCTS_THEN2 (LABEL_TAC "top")
       (CONJUNCTS_THEN2 (LABEL_TAC "oneD")
        (CONJUNCTS_THEN2 (LABEL_TAC "BD")
         (CONJUNCTS_THEN2 (LABEL_TAC "oneB")
          (CONJUNCTS_THEN2 (LABEL_TAC "XD")
           (CONJUNCTS_THEN2 (LABEL_TAC "ciX")
            (LABEL_TAC "PX")))))))))))))))))))))) THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B inclB /\ eporder D E B inclB`
   (CONJUNCTS_THEN2 (LABEL_TAC "balg") (LABEL_TAC "pord")) THENL
   [USE_THEN "cba" (fun th -> let b = MATCH_MP ECBA_IMP_BALG th in
      ACCEPT_TAC(CONJ b (MATCH_MP EBALG_IMP_PORDER b)));
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!a. a IN D /\ hsname D (E:A->A->bool) B w1 X a
        ==> valuation D ((n |-> a) (v:num->A)) /\
            (!i. hsname D E B w1 X (((n |-> a) v) i))`
   (LABEL_TAC "vna") THENL
   [X_GEN_TAC `a:A` THEN DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "aD")
       (LABEL_TAC "hsa")) THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
      MATCH_MP_TAC HSNAMEVAL_VALMOD THEN CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!a. a IN D /\ hsname D (E:A->A->bool) B w1 X a
        ==> bvalf_HS D (E:A->A->bool) B inclB w1 X ((n |-> (a:A)) (v:num->A)) p
            IN D /\ E (bvalf_HS D (E:A->A->bool) B inclB w1 X
                       ((n |-> (a:A)) (v:num->A)) p) B`
   (LABEL_TAC "bfa") THENL
   [X_GEN_TAC `a:A` THEN DISCH_TAC THEN
    USE_THEN "vna" (MP_TAC o SPEC `a:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "va") (LABEL_TAC "hva"))
        THEN CONJ_TAC THENL
     [MP_TAC(SPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                    `inclB:A`;`w1:A`;`X:A`;
                    `(n |-> (a:A)) (v:num->A)`] BVALF_HS_IND) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN ACCEPT_TAC];
