                  `c:A`;`q:A`;`wq:A`;`zcq:A`] MIX_EQ_GE) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      MAP_EVERY X_GEN_TAC [`q':A`;`w':A`;`mm:A`] THEN
      DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "q'D")
                 (CONJUNCTS_THEN2 (LABEL_TAC "q'Q")
                  (CONJUNCTS_THEN2 (LABEL_TAC "q'ne")
                   (CONJUNCTS_THEN2 (LABEL_TAC "w'D")
                    (CONJUNCTS_THEN2 (LABEL_TAC "gq'w'")
                     (LABEL_TAC "mmeet")))))) THEN
      USE_THEN "gdisj" (MP_TAC o SPECL [`q:A`;`q':A`;`wq:A`;`w':A`;`mm:A`]) THEN
      ANTS_TAC THENL
       [REPEAT CONJ_TAC THEN
        FIRST [FIRST_ASSUM ACCEPT_TAC;
               USE_THEN "mmeet" (ACCEPT_TAC o CONJUNCT1 o MATCH_MP EMEET_IN);
               USE_THEN "q'ne" (ACCEPT_TAC o GSYM)];
        DISCH_THEN ACCEPT_TAC];
      DISCH_THEN(LABEL_TAC "wqz")] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`c:A`;`q:A`;
                  `zcq:A`] EBV_EQ_SYM) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN(LABEL_TAC "eqqc")] THEN
    MP_TAC(SPECL [`n:num`;`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;
                  `w1:A`;`X:A`;`v:num->A`;`q:A`;`c:A`;`wq:A`;`zcq:A`]
        MAXPRIN_LEIBNIZ_STEP_HS) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  (* [[?? n p]] <= [[p(c)]] *)
  SUBGOAL_THEN `erel D (E:A->A->bool) inclB
      (bvalf_HS D (E:A->A->bool) B inclB w1 X (v:num->A) (?? n p))
      (bvalf_HS D (E:A->A->bool) B inclB w1 X ((n |-> (c:A)) (v:num->A)) p)`
      (LABEL_TAC "ge") THENL
   [MP_TAC(SPECL [`n:num`;`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;
                  `w1:A`;`X:A`;`v:num->A`;`bvalf_HS D (E:A->A->bool) B inclB w1
       X ((n |-> (c:A)) (v:num->A)) p`] BVALF_HS_EX_LEAST) THEN
    ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    X_GEN_TAC `a:A` THEN DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "aD")
        (LABEL_TAC "hsa")) THEN
    USE_THEN "attain" (MP_TAC o SPEC `a:A`) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `q:A` (CONJUNCTS_THEN2 (LABEL_TAC "qD")
      (CONJUNCTS_THEN2 (LABEL_TAC "qI") (LABEL_TAC "qeq")))) THEN
    USE_THEN "qeq" (fun th -> REWRITE_TAC[GSYM th]) THEN
    USE_THEN "hsI" (MP_TAC o SPEC `q:A`) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN(LABEL_TAC "hsq")] THEN
    USE_THEN "bfa" (MP_TAC o SPEC `q:A`) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "pqD") (LABEL_TAC "pqB")) THEN
    USE_THEN "hval" (MP_TAC o SPEC `q:A`) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN(LABEL_TAC "hq")] THEN
    USE_THEN "Qsup" (MP_TAC o SPEC `bvalf_HS D (E:A->A->bool) B inclB w1 X
                     ((n |-> (c:A)) (v:num->A)) p`) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      USE_THEN "gsup" (MP_TAC o SPEC `bvalf_HS D (E:A->A->bool) B inclB w1 X
                       ((n |-> (c:A)) (v:num->A)) p`) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPECL [`q:A`; `bvalf_HS D (E:A->A->bool) B inclB w1 X
        ((n |-> (q:A)) (v:num->A)) p`]) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  (* [[p(c)]] <= [[?? n p]] *)
  SUBGOAL_THEN `erel D (E:A->A->bool) inclB
      (bvalf_HS D (E:A->A->bool) B inclB w1 X ((n |-> (c:A)) (v:num->A)) p)
      (bvalf_HS D (E:A->A->bool) B inclB w1 X (v:num->A) (?? n p))`
      (LABEL_TAC "le") THENL
   [MP_TAC(SPECL [`n:num`;`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;
                  `w1:A`;`X:A`;`v:num->A`;`c:A`] BVALF_HS_EX_UB) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `(bvalf_HS D (E:A->A->bool) B inclB w1 X (v:num->A) (?? n p)) IN
      D /\ (E:A->A->bool) (bvalf_HS D (E:A->A->bool) B inclB w1 X
      (v:num->A) (?? n p)) B`
   (CONJUNCTS_THEN2 (LABEL_TAC "rD") (LABEL_TAC "rB")) THENL
   [CONJ_TAC THENL
     [MP_TAC(SPECL [`?? n p`;`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;
                    `X:A`;`v:num->A`]
        BVALF_HS_IND) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN ACCEPT_TAC];
      MP_TAC(SPECL [`?? n p`;`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;
                    `X:A`;`v:num->A`]
        BVALF_HS_IN_B) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN ACCEPT_TAC]];
    ALL_TAC] THEN
  EXISTS_TAC `c:A` THEN REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;
                `bvalf_HS D (E:A->A->bool) B inclB w1 X
      ((n |-> (c:A)) (v:num->A)) p`;`bvalf_HS D (E:A->A->bool) B inclB w1 X
      (v:num->A) (?? n p)`] EPORDER_ANTISYM) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                  DISCH_THEN ACCEPT_TAC]);;

(* ===================================================================== *)
(* H3.9a : MAXPRIN_EX_HS -- the HS MAXIMUM PRINCIPLE: for every formula,   *)
(* slot n and HS valuation v there is an HS name a with                   *)
(*   [[p]]^HS_{(n|->a)v} = [[?? n p]]^HS_v.                                *)
(* Parameters outside FV(?? n p) are replaced by a check name (fixed by    *)
(* every autN: EAUT_CHECK) without changing either side (BVALF_HS_FV_CONG);*)
(* the finitely many others get one countable support (PARAM_CSUPPORT);    *)
(* then MAXPRIN_EX_HS_CORE.                                                *)
(* ===================================================================== *)
let MAXPRIN_EX_HS = prove
 (`!n p D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X v.
     hsbundle D E w1 om tw ii ci P leqp B inclB onebee X /\
     valuation D v /\ (!i. hsname D E B w1 X (v i))
     ==> ?a. a IN D /\ hsname D E B w1 X a /\
             bvalf_HS D E B inclB w1 X ((n |-> a) v) p =
             bvalf_HS D E B inclB w1 X v (?? n p)`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "hsb")
             (CONJUNCTS_THEN2 (LABEL_TAC "vv") (LABEL_TAC "hsv"))) THEN
  USE_THEN "hsb" (MP_TAC o MATCH_MP HSB_FACTS) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "omD")
             (CONJUNCTS_THEN2 (LABEL_TAC "w1ord")
              (CONJUNCTS_THEN2 (LABEL_TAC "PD")
               (CONJUNCTS_THEN2 (LABEL_TAC "ciD")
                (CONJUNCTS_THEN2 (LABEL_TAC "iiD") (LABEL_TAC "omw1")))))) THEN
  USE_THEN "hsb" (MP_TAC o MATCH_MP HSB_CBA) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "cba")
             (CONJUNCTS_THEN2 (LABEL_TAC "inclD") (LABEL_TAC "leqpD"))) THEN
  USE_THEN "hsb" (MP_TAC o REWRITE_RULE[hsbundle]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
             (CONJUNCTS_THEN2 (LABEL_TAC "vl")
              (CONJUNCTS_THEN2 (LABEL_TAC "eom")
               (CONJUNCTS_THEN2 (LABEL_TAC "w1D")
                (CONJUNCTS_THEN2 (LABEL_TAC "w1card")
                 (CONJUNCTS_THEN2 (LABEL_TAC "omw1e")
                  (CONJUNCTS_THEN2 (LABEL_TAC "w1min")
                   (CONJUNCTS_THEN2 (LABEL_TAC "cr1")
                    (CONJUNCTS_THEN2 (LABEL_TAC "cr2")
                     (CONJUNCTS_THEN2 (LABEL_TAC "ftw")
                      (CONJUNCTS_THEN2 (LABEL_TAC "coh")
                       (CONJUNCTS_THEN2 (LABEL_TAC "leq")
                        (CONJUNCTS_THEN2 (LABEL_TAC "ros")
                         (CONJUNCTS_THEN2 (LABEL_TAC "inc")
                          (CONJUNCTS_THEN2 (LABEL_TAC "porder")
      (CONJUNCTS_THEN2 (LABEL_TAC "top")
       (CONJUNCTS_THEN2 (LABEL_TAC "oneD")
        (CONJUNCTS_THEN2 (LABEL_TAC "BD")
         (CONJUNCTS_THEN2 (LABEL_TAC "oneB")
          (CONJUNCTS_THEN2 (LABEL_TAC "XD")
           (CONJUNCTS_THEN2 (LABEL_TAC "ciX")
            (LABEL_TAC "PX")))))))))))))))))))))) THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` (LABEL_TAC "vD") THENL
   [USE_THEN "vv" (ACCEPT_TAC o REWRITE_RULE[valuation]); ALL_TAC] THEN
  (* a check name vk: HS and fixed by every automorphism *)
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`om:A`]
         ECHECK_EXHAUSTION) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `vk:A` (LABEL_TAC "chk")) THEN
  SUBGOAL_THEN `(vk:A) IN D` (LABEL_TAC "vkD") THENL
   [USE_THEN "chk" (ACCEPT_TAC o CONJUNCT2 o MATCH_MP ECHECK_IMP); ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;`ii:A`;`ci:A`;
                `P:A`;`leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`om:A`;
      `vk:A`] HS_CHECK) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                  DISCH_THEN(LABEL_TAC "hsk")] THEN
  (* the cleaned valuation *)
  ABBREV_TAC `v' = \i. if i IN FV (?? n p) then (v:num->A) i else vk` THEN
  SUBGOAL_THEN
   `valuation D (v':num->A) /\ (!i. v' i IN D) /\
       (!i. hsname D (E:A->A->bool) B w1 X (v' i))`
   (CONJUNCTS_THEN2 (LABEL_TAC "vv'") (CONJUNCTS_THEN2 (LABEL_TAC "v'D")
       (LABEL_TAC "hsv'"))) THENL
   [EXPAND_TAC "v'" THEN REWRITE_TAC[valuation] THEN BETA_TAC THEN
    REPEAT CONJ_TAC THEN GEN_TAC THEN COND_CASES_TAC THEN
    FIRST [FIRST_ASSUM ACCEPT_TAC; FIRST_ASSUM MATCH_ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `!i. i IN FV (?? n p) ==> (v':num->A) i = v i`
      (LABEL_TAC "v'eq") THENL
   [EXPAND_TAC "v'" THEN GEN_TAC THEN DISCH_THEN(fun th -> BETA_TAC THEN
       REWRITE_TAC[th]);
    ALL_TAC] THEN
  SUBGOAL_THEN `!i. ~(i IN FV (?? n p))
      ==> (v':num->A) i = vk` (LABEL_TAC "v'out") THENL
   [EXPAND_TAC "v'" THEN GEN_TAC THEN DISCH_THEN(fun th -> BETA_TAC THEN
       REWRITE_TAC[th]);
    ALL_TAC] THEN
  (* one countable support for the finitely many genuine parameters *)
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;`ii:A`;`ci:A`;
                `P:A`;`leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`v':num->A`]
      PARAM_CSUPPORT) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `FV (?? n p)`) THEN REWRITE_TAC[FV_FINITE] THEN
  DISCH_THEN(X_CHOOSE_THEN `e:A` (CONJUNCTS_THEN2 (LABEL_TAC "eD")
      (CONJUNCTS_THEN2 (LABEL_TAC "efin")
       (CONJUNCTS_THEN2 (LABEL_TAC "esub") (LABEL_TAC "efix"))))) THEN
  MP_TAC(SPECL [`n:num`;`p:form`;`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;
                `tw:A`;`ii:A`;`ci:A`;`P:A`;`leqp:A`;`B:A`;`inclB:A`;`onebee:A`;
      `X:A`;`v':num->A`;`e:A`] MAXPRIN_EX_HS_CORE) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    X_GEN_TAC `s:A` THEN DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "sD")
      (CONJUNCTS_THEN2 (LABEL_TAC "sperm") (LABEL_TAC "sfix"))) THEN
    MAP_EVERY X_GEN_TAC [`muci:A`;`muP:A`;`autB:A`] THEN
        DISCH_THEN(LABEL_TAC "pb") THEN
    USE_THEN "pb" (fun th -> let cs = CONJUNCTS(REWRITE_RULE[pbundle] th) in
      LABEL_TAC "mucD" (el 0 cs) THEN LABEL_TAC "muPD" (el 1 cs) THEN
      LABEL_TAC "autBD" (el 2 cs) THEN LABEL_TAC "bijB" (el 5 cs) THEN
      LABEL_TAC "mch" (el 6 cs) THEN LABEL_TAC "Pch" (el 7 cs) THEN
      LABEL_TAC "ach" (el 8 cs) THEN LABEL_TAC "presB" (el 10 cs)) THEN
    X_GEN_TAC `i:num` THEN ASM_CASES_TAC `(i:num) IN FV (?? n p)` THENL
     [USE_THEN "efix" (MP_TAC o SPEC `s:A`) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(MP_TAC o SPECL [`muci:A`;`muP:A`;`autB:A`]) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(MP_TAC o SPEC `i:num`) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; DISCH_THEN ACCEPT_TAC];
      USE_THEN "v'out" (MP_TAC o SPEC `i:num`) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; DISCH_THEN SUBST1_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;`inclB:A`;
                    `autB:A`;`om:A`;`vk:A`]
        EAUT_CHECK) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN ACCEPT_TAC]];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `a:A` (CONJUNCTS_THEN2 (LABEL_TAC "aD")
    (CONJUNCTS_THEN2 (LABEL_TAC "hsa") (LABEL_TAC "aeq")))) THEN
  EXISTS_TAC `a:A` THEN REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
  SUBGOAL_THEN
   `bvalf_HS D (E:A->A->bool) B inclB w1 X ((n |-> (a:A)) (v:num->A)) p =
    bvalf_HS D E B inclB w1 X ((n |-> a) (v':num->A)) p`
   SUBST1_TAC THENL
   [MATCH_MP_TAC BVALF_HS_FV_CONG THEN REPEAT CONJ_TAC THEN
    FIRST [FIRST_ASSUM ACCEPT_TAC;
           MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THEN
               FIRST_ASSUM ACCEPT_TAC;
           MATCH_MP_TAC HSNAMEVAL_VALMOD THEN CONJ_TAC THEN
               FIRST_ASSUM ACCEPT_TAC;
           ALL_TAC] THEN
    X_GEN_TAC `i:num` THEN DISCH_TAC THEN REWRITE_TAC[VALMOD] THEN
        COND_CASES_TAC THEN
    REWRITE_TAC[] THEN CONV_TAC SYM_CONV THEN USE_THEN "v'eq" MATCH_MP_TAC THEN
    REWRITE_TAC[FV_CLAUSES; IN_DELETE] THEN CONJ_TAC THEN
        FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  USE_THEN "aeq" SUBST1_TAC THEN
  MATCH_MP_TAC BVALF_HS_FV_CONG THEN REPEAT CONJ_TAC THEN
    FIRST [FIRST_ASSUM ACCEPT_TAC;
           MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THEN
               FIRST_ASSUM ACCEPT_TAC;
           MATCH_MP_TAC HSNAMEVAL_VALMOD THEN CONJ_TAC THEN
               FIRST_ASSUM ACCEPT_TAC;
           ALL_TAC] THEN
  USE_THEN "v'eq" ACCEPT_TAC);;

(* ===================================================================== *)
(* H3.9b : BVALF_HS_ALL_CONG (pointwise-equal bodies give equal [[!! n .]])*)
(* and MAXPRIN_ALL_HS (the universal HS maximum principle, dual of        *)
(* MAXPRIN_EX_HS via De Morgan) -- clones of BVALF_ALL_CONG / MAXPRIN_ALL. *)
(* ===================================================================== *)
let BVALF_HS_ALL_CONG = prove
 (`!n p q D (E:A->A->bool) B leq w1 X v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
          w1 IN D /\ X IN D /\
      valuation D v /\ (!i. hsname D E B w1 X (v i)) /\
      (!c. c IN D /\ hsname D E B w1 X c
           ==> bvalf_HS D E B leq w1 X ((n |-> c) v) p = bvalf_HS D E B leq w1 X
               ((n |-> c) v) q)
      ==> bvalf_HS D E B leq w1 X v (!! n p) = bvalf_HS D E B leq
          w1 X v (!! n q)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN
   `(bvalf_HS D (E:A->A->bool) B leq w1 X v (!! n p)) IN D /\
    (E:A->A->bool) (bvalf_HS D E B leq w1 X v (!! n p)) B /\
    (bvalf_HS D (E:A->A->bool) B leq w1 X v (!! n q)) IN D /\
    (E:A->A->bool) (bvalf_HS D E B leq w1 X v (!! n q)) B`
   STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THENL
     [MP_TAC(ISPECL [`!! n p`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                     `X:A`;`v:num->A`]
        BVALF_HS_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`!! n p`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                     `X:A`;`v:num->A`]
        BVALF_HS_IN_B) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`!! n q`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                     `X:A`;`v:num->A`]
        BVALF_HS_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`!! n q`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                     `X:A`;`v:num->A`]
        BVALF_HS_IN_B) THEN ASM_SIMP_TAC[]];
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
    `bvalf_HS D (E:A->A->bool) B leq w1 X v (!! n p)`;
    `bvalf_HS D (E:A->A->bool) B leq w1 X v (!! n q)`] EPORDER_ANTISYM) THEN
  ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [MATCH_MP_TAC(ISPECL [`n:num`;`q:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                         `leq:A`;`w1:A`;`X:A`;
      `v:num->A`; `bvalf_HS D (E:A->A->bool) B leq w1 X v (!! n p)`]
          BVALF_HS_ALL_GLB) THEN
    ASM_REWRITE_TAC[] THEN X_GEN_TAC `c:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `bvalf_HS D (E:A->A->bool) B leq w1 X ((n |-> c) v) p =
                  bvalf_HS D E B leq w1 X ((n |-> c) v) q`
                      (SUBST1_TAC o SYM) THENL
     [FIRST_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL [`n:num`;`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                         `leq:A`;`w1:A`;`X:A`;
      `v:num->A`;`c:A`] BVALF_HS_ALL_LB) THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC(ISPECL [`n:num`;`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                         `leq:A`;`w1:A`;`X:A`;
      `v:num->A`; `bvalf_HS D (E:A->A->bool) B leq w1 X v (!! n q)`]
          BVALF_HS_ALL_GLB) THEN
    ASM_REWRITE_TAC[] THEN X_GEN_TAC `c:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `bvalf_HS D (E:A->A->bool) B leq w1 X ((n |-> c) v) p =
                  bvalf_HS D E B leq w1 X ((n |-> c) v) q` SUBST1_TAC THENL
     [FIRST_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL [`n:num`;`q:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                         `leq:A`;`w1:A`;`X:A`;
      `v:num->A`;`c:A`] BVALF_HS_ALL_LB) THEN ASM_REWRITE_TAC[]]);;

let MAXPRIN_ALL_HS = prove
 (`!n p D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X v.
     hsbundle D E w1 om tw ii ci P leqp B inclB onebee X /\
     valuation D v /\ (!i. hsname D E B w1 X (v i))
     ==> ?a. a IN D /\ hsname D E B w1 X a /\
             bvalf_HS D E B inclB w1 X ((n |-> (a:A)) (v:num->A)) p =
             bvalf_HS D E B inclB w1 X v (!! n p)`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "hsb")
             (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC)) THEN
  USE_THEN "hsb" (fun th -> let cs = CONJUNCTS(REWRITE_RULE[hsbundle] th)
                            and cb = CONJUNCTS(MATCH_MP HSB_CBA th) in
    MAP_EVERY ASSUME_TAC [el 0 cs; el 1 cs; el 3 cs; el 17 cs; el 19 cs;
                          el 0 cb; el 1 cb]) THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B inclB /\
      eporder D (E:A->A->bool) B inclB`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  (* --- MAXPRIN_EX on (Not p): witness a with [[Not p (a)]] = [[?? n (Not *)
  (* p)]] ---                                                              *)
  MP_TAC(ISPECL [`n:num`;`Not p`;`D:A->bool`;`E:A->A->bool`;`w1:A`;
                 `om:A`;`tw:A`;`ii:A`;
                 `ci:A`;`P:A`;`leqp:A`;`B:A`;`inclB:A`;`onebee:A`;
                     `X:A`;`v:num->A`]
    MAXPRIN_EX_HS) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `a:A` (CONJUNCTS_THEN2 (LABEL_TAC "aD")
    (CONJUNCTS_THEN2 (LABEL_TAC "bna") (LABEL_TAC "e1")))) THEN
  EXISTS_TAC `a:A` THEN ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `valuation D ((n |-> (a:A)) (v:num->A)) /\
                (!i. hsname D (E:A->A->bool) B w1 X
                 (((n |-> (a:A)) (v:num->A)) i))`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC HSNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  (* --- ecompl [[p(a)]] [[Not p (a)]] --- *)
  MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;
                 `X:A`;`(n |-> (a:A)) (v:num->A)`]
    BVALF_HS_NOT) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(LABEL_TAC "cPA") THEN
  (* --- ecompl [[!! n (Not(Not p))]] [[?? n (Not p)]] --- *)
  SUBGOAL_THEN `ecompl D (E:A->A->bool) B inclB
     (bvalf_HS D E B inclB w1 X v (!! n (Not(Not p))))
     (bvalf_HS D E B inclB w1 X v (?? n (Not p)))` (LABEL_TAC "cAllnnp") THENL
   [SUBGOAL_THEN `(?? n (Not p)) = Not(!! n (Not(Not p)))` SUBST1_TAC THENL
     [REWRITE_TAC[Exists_DEF]; ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL [`!! n (Not(Not p))`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                         `inclB:A`;`w1:A`;`X:A`;
      `v:num->A`] BVALF_HS_NOT) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* --- [[!! n (Not(Not p))]] = [[!! n p]] (BVALF_HS_ALL_CONG + double *)
  (* negation) ---                                                      *)
  SUBGOAL_THEN `bvalf_HS D (E:A->A->bool) B inclB w1 X v (!! n (Not(Not p))) =
                bvalf_HS D E B inclB w1 X v (!! n p)` (LABEL_TAC "alleq") THENL
   [MATCH_MP_TAC(ISPECL [`n:num`;`Not(Not p)`;`p:form`;
                         `D:A->bool`;`E:A->A->bool`;
      `B:A`;`inclB:A`;`w1:A`;`X:A`;`v:num->A`] BVALF_HS_ALL_CONG) THEN
    ASM_REWRITE_TAC[] THEN X_GEN_TAC `c:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((n |-> (c:A)) (v:num->A)) /\
                  (!i. hsname D (E:A->A->bool) B w1 X
                   (((n |-> (c:A)) (v:num->A)) i))`
      STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC HSNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
    MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;
                   `X:A`;`(n |-> (c:A)) (v:num->A)`]
      BVALF_HS_NOT) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC]
          THEN DISCH_TAC THEN
    MP_TAC(ISPECL [`Not p`;`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;
                   `X:A`;`(n |-> (c:A)) (v:num->A)`]
      BVALF_HS_NOT) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC]
          THEN DISCH_TAC THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;
       `bvalf_HS D (E:A->A->bool) B inclB w1 X ((n |-> (c:A)) (v:num->A)) p`;
       `bvalf_HS D (E:A->A->bool) B inclB w1 X
           ((n |-> (c:A)) (v:num->A)) (Not p)`;
       `bvalf_HS D (E:A->A->bool) B inclB w1 X ((n |-> (c:A)) (v:num->A))
           (Not(Not p))`] ECOMPL_INVOL) THEN
    ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;
                     `X:A`;`(n |-> (c:A)) (v:num->A)`]
        BVALF_HS_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;
                     `X:A`;`(n |-> (c:A)) (v:num->A)`]
        BVALF_HS_IN_B) THEN ASM_SIMP_TAC[]];
    ALL_TAC] THEN
  (* --- membership facts for PA, ALLP, EXNP --- *)
  SUBGOAL_THEN
   `(bvalf_HS D (E:A->A->bool) B inclB w1 X
     ((n |-> (a:A)) (v:num->A)) p) IN D /\
    (E:A->A->bool) (bvalf_HS D E B inclB w1 X ((n |-> (a:A)) (v:num->A)) p) B /\
    (bvalf_HS D (E:A->A->bool) B inclB w1 X v (!! n p)) IN D /\
    (E:A->A->bool) (bvalf_HS D E B inclB w1 X v (!! n p)) B /\
    (bvalf_HS D (E:A->A->bool) B inclB w1 X v (?? n (Not p))) IN D /\
    (E:A->A->bool) (bvalf_HS D E B inclB w1 X v (?? n (Not p))) B`
   STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THENL
     [MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;
                     `X:A`;`(n |-> (a:A)) (v:num->A)`]
        BVALF_HS_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;
                     `X:A`;`(n |-> (a:A)) (v:num->A)`]
        BVALF_HS_IN_B) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`!! n p`;`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;
                     `X:A`;`v:num->A`]
        BVALF_HS_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`!! n p`;`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;
                     `X:A`;`v:num->A`]
        BVALF_HS_IN_B) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`?? n (Not p)`;`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;
                     `w1:A`;`X:A`;`v:num->A`]
        BVALF_HS_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`?? n (Not p)`;`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;
                     `w1:A`;`X:A`;`v:num->A`]
        BVALF_HS_IN_B) THEN ASM_SIMP_TAC[]];
    ALL_TAC] THEN
  (* --- ecompl [[p(a)]] [[?? n (Not p)]]  (from cPA + e1) --- *)
  SUBGOAL_THEN `ecompl D (E:A->A->bool) B inclB
     (bvalf_HS D E B inclB w1 X ((n |-> (a:A)) (v:num->A)) p)
         (bvalf_HS D E B inclB w1 X v (?? n (Not p)))`
   (LABEL_TAC "cPAex") THENL
   [USE_THEN "cPA" (fun cth -> USE_THEN "e1" (fun eth ->
      ACCEPT_TAC(REWRITE_RULE[eth] cth))); ALL_TAC] THEN
  (* --- ecompl [[!! n p]] [[?? n (Not p)]]  (from cAllnnp + alleq) --- *)
  SUBGOAL_THEN `ecompl D (E:A->A->bool) B inclB
     (bvalf_HS D E B inclB w1 X v (!! n p))
         (bvalf_HS D E B inclB w1 X v (?? n (Not p)))`
   (LABEL_TAC "cAllex") THENL
   [USE_THEN "cAllnnp" (fun cth -> USE_THEN "alleq" (fun eth ->
      ACCEPT_TAC(REWRITE_RULE[eth] cth))); ALL_TAC] THEN
  (* --- symmetrise both to base [[?? n (Not p)]], then ECOMPL_UNIQUE --- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;
     `bvalf_HS D (E:A->A->bool) B inclB w1 X ((n |-> (a:A)) (v:num->A)) p`;
     `bvalf_HS D (E:A->A->bool) B inclB w1 X v (?? n (Not p))`] ECOMPL_SYM) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;
     `bvalf_HS D (E:A->A->bool) B inclB w1 X v (!! n p)`;
     `bvalf_HS D (E:A->A->bool) B inclB w1 X v (?? n (Not p))`] ECOMPL_SYM) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;
     `bvalf_HS D (E:A->A->bool) B inclB w1 X v (?? n (Not p))`;
     `bvalf_HS D (E:A->A->bool) B inclB w1 X ((n |-> (a:A)) (v:num->A)) p`;
     `bvalf_HS D (E:A->A->bool) B inclB w1 X v (!! n p)`] ECOMPL_UNIQUE) THEN
  ASM_REWRITE_TAC[]);;

(* ===================================================================== *)
(* H3.10 : the HS ultrafilter quotient and LOS_HS.  Representatives are   *)
(* chosen among HS names (qrep_HS / qdom_HS); membership is the V^B qmem  *)
(* (umem: atomic Boolean values are those of V^B).  Bridges to the V^B    *)
(* usim/umem congruences via HSNAME_BNAME.                                *)
(* ===================================================================== *)
let qrep_HS = new_definition
  `qrep_HS D (E:A->A->bool) B leq w1 X U a =
     (@b. b IN D /\ hsname D E B w1 X b /\ usim D E B leq U a b)`;;

let qdom_HS = new_definition
  `qdom_HS D (E:A->A->bool) B leq w1 X U u <=>
     ?a. a IN D /\ hsname D E B w1 X a /\ u = qrep_HS D E B leq w1 X U a`;;

let QREP_HS_SPEC = prove
 (`!D (E:A->A->bool) B leq w1 X U a.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
          w1 IN D /\ X IN D /\
      eultra D E B leq U /\ a IN D /\ hsname D E B w1 X a
      ==> (qrep_HS D E B leq w1 X U a) IN D /\
          hsname D E B w1 X (qrep_HS D E B leq w1 X U a) /\
          usim D E B leq U a (qrep_HS D E B leq w1 X U a)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `?b:A. b IN D /\ hsname D E B w1 X b /\ usim D E B leq U a b`
    (MP_TAC o SELECT_RULE) THENL
   [EXISTS_TAC `a:A` THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC USIM_REFL THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
        ASM_REWRITE_TAC[];
    REWRITE_TAC[GSYM qrep_HS] THEN DISCH_THEN ACCEPT_TAC]);;

let QREP_HS_EQ = prove
 (`!D (E:A->A->bool) B leq w1 X U a c.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
          w1 IN D /\ X IN D /\
      eultra D E B leq U /\ a IN D /\ c IN D /\
      hsname D E B w1 X a /\ hsname D E B w1 X c
      ==> (usim D E B leq U a c <=>
           qrep_HS D E B leq w1 X U a = qrep_HS D E B leq w1 X U c)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `!x:A. x IN D /\ hsname D E B w1 X x
      ==> bname D E B x` (LABEL_TAC "hb") THENL
   [REPEAT STRIP_TAC THEN MATCH_MP_TAC HSNAME_BNAME THEN
    MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B a /\
      bname D E B c` STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN USE_THEN "hb" MATCH_MP_TAC THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  EQ_TAC THENL
   [DISCH_TAC THEN REWRITE_TAC[qrep_HS] THEN MATCH_MP_TAC SELECT_SIM_EQ THEN
    X_GEN_TAC `x:A` THEN
    ASM_CASES_TAC `(x:A) IN D` THEN ASM_REWRITE_TAC[] THEN
    ASM_CASES_TAC `hsname D (E:A->A->bool) B w1 X x` THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `bname D (E:A->A->bool) B x` ASSUME_TAC THENL
     [USE_THEN "hb" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    EQ_TAC THEN DISCH_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`U:A`;
        `c:A`;`a:A`;`x:A`] USIM_TRANS) THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`U:A`;
        `a:A`;`c:A`] USIM_SYM) THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`U:A`;
        `a:A`;`c:A`;`x:A`] USIM_TRANS) THEN ASM_REWRITE_TAC[]];
    DISCH_THEN(LABEL_TAC "qeq") THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                   `X:A`;`U:A`;`a:A`]
      QREP_HS_SPEC) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "raD")
               (CONJUNCTS_THEN2 (LABEL_TAC "hra")
      (LABEL_TAC "sra"))) THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                   `X:A`;`U:A`;`c:A`]
      QREP_HS_SPEC) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "rcD")
               (CONJUNCTS_THEN2 (LABEL_TAC "hrc")
      (LABEL_TAC "src"))) THEN
    SUBGOAL_THEN `bname D (E:A->A->bool) B
        (qrep_HS D (E:A->A->bool) B leq w1 X U c)` (LABEL_TAC "brc") THENL
     [USE_THEN "hb" MATCH_MP_TAC THEN CONJ_TAC THEN
      FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    USE_THEN "sra" (MP_TAC o REWRITE_RULE[ASSUME `qrep_HS D (E:A->A->bool) B leq
        w1 X U a = qrep_HS D (E:A->A->bool) B leq w1 X U c`]) THEN
    DISCH_THEN(LABEL_TAC "sra'") THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`U:A`;
      `a:A`;`qrep_HS D (E:A->A->bool) B leq w1 X U c`;`c:A`] USIM_TRANS) THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`U:A`;
      `c:A`;`qrep_HS D (E:A->A->bool) B leq w1 X U c`] USIM_SYM) THEN
    REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC]);;

let UMEM_QREP_HS = prove
 (`!D (E:A->A->bool) B leq w1 X U a b.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
         w1 IN D /\ X IN D /\
     eultra D E B leq U /\ a IN D /\ b IN D /\ hsname D E B w1 X a /\
         hsname D E B w1 X b
     ==> (umem D E B leq U (qrep_HS D E B leq w1 X U a)
          (qrep_HS D E B leq w1 X U b) <=>
          umem D E B leq U a b)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `!x:A. x IN D /\ hsname D E B w1 X x
      ==> bname D E B x` (LABEL_TAC "hb") THENL
   [REPEAT STRIP_TAC THEN MATCH_MP_TAC HSNAME_BNAME THEN
    MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;`X:A`;`U:A`;
                 `a:A`] QREP_HS_SPEC) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;`X:A`;`U:A`;
                 `b:A`] QREP_HS_SPEC) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `bname D (E:A->A->bool) B a /\ bname D E B b /\
    bname D E B (qrep_HS D (E:A->A->bool) B leq w1 X U a) /\
        bname D E B (qrep_HS D (E:A->A->bool) B leq w1 X U b)`
   STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THEN USE_THEN "hb" MATCH_MP_TAC THEN CONJ_TAC THEN
    FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  EQ_TAC THEN DISCH_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`U:A`;
      `a:A`;`qrep_HS D (E:A->A->bool) B leq w1 X U b`;`b:A`] UMEM_CONG_R) THEN
    ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`U:A`;
        `b:A`;`qrep_HS D (E:A->A->bool) B leq w1 X U b`] USIM_SYM) THEN
            ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`U:A`;
      `qrep_HS D (E:A->A->bool) B leq w1 X U a`;`a:A`;
          `qrep_HS D (E:A->A->bool) B leq w1 X U b`] UMEM_CONG_L) THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`U:A`;
      `a:A`;`qrep_HS D (E:A->A->bool) B leq w1 X U a`] USIM_SYM) THEN
          ASM_REWRITE_TAC[];
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`U:A`;
      `qrep_HS D (E:A->A->bool) B leq w1 X U a`;`b:A`;
          `qrep_HS D (E:A->A->bool) B leq w1 X U b`] UMEM_CONG_R) THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`U:A`;
      `a:A`;`qrep_HS D (E:A->A->bool) B leq w1 X U a`;`b:A`] UMEM_CONG_L) THEN
    ASM_REWRITE_TAC[]]);;

let QDOM_HS_FORALL = prove
 (`!D (E:A->A->bool) B leq w1 X U (P:A->bool).
     (!a. a IN qdom_HS D E B leq w1 X U ==> P a) <=>
     (!c. c IN D /\ hsname D E B w1 X c ==> P (qrep_HS D E B leq w1 X U c))`,
  REPEAT GEN_TAC THEN REWRITE_TAC[IN; qdom_HS] THEN EQ_TAC THEN DISCH_TAC THENL
   [X_GEN_TAC `c:A` THEN STRIP_TAC THEN FIRST_X_ASSUM MATCH_MP_TAC THEN
    EXISTS_TAC `c:A` THEN ASM_REWRITE_TAC[];
    X_GEN_TAC `a:A` THEN DISCH_THEN(X_CHOOSE_THEN `c:A` STRIP_ASSUME_TAC) THEN
    ASM_REWRITE_TAC[] THEN FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]]);;

let QREP_HS_PUSH = prove
 (`!D (E:A->A->bool) B leq w1 X U n c (v:num->A).
     (n |-> qrep_HS D E B leq w1 X U c) (\i. qrep_HS D E B leq w1 X U (v i)) =
     (\i. qrep_HS D E B leq w1 X U (((n |-> c) v) i))`,
  REPEAT GEN_TAC THEN REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `i:num` THEN
  ASM_CASES_TAC `i:num = n` THEN ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER]);;

let UBIG_BVALF_HS = prove
 (`!p D (E:A->A->bool) B leq w1 X U v.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
         w1 IN D /\ X IN D /\
     valuation D v /\ (!i. hsname D E B w1 X (v i))
     ==> (ubig D E U (bvalf_HS D E B leq w1 X v p) <=>
          E (bvalf_HS D E B leq w1 X v p) U)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(bvalf_HS D (E:A->A->bool) B leq w1 X v p) IN D`
      ASSUME_TAC THENL
   [MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                   `X:A`;`v:num->A`]
      BVALF_HS_SPEC) THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
  ASM_REWRITE_TAC[ubig]);;

let UMEM_BVALF_HS = prove
 (`!i j D (E:A->A->bool) B leq w1 X U v.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
         w1 IN D /\ X IN D /\
     valuation D v /\ (!k. hsname D E B w1 X (v k))
     ==> (umem D E B leq U (v i) (v j) <=>
          ubig D E U (bvalf_HS D E B leq w1 X v (i %% j)))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[umem] THEN
  SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq (v i) (v j)
      (bvalf_HS D E B leq w1 X v (i %% j))`
    ASSUME_TAC THENL [MATCH_MP_TAC BVALF_HS_MEM THEN
                      ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(v:num->A) i IN D /\ (v:num->A) j IN D /\
                (bvalf_HS D (E:A->A->bool) B leq w1 X v (i %% j)) IN D`
                    STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THENL
     [ASM_MESON_TAC[valuation]; ASM_MESON_TAC[valuation];
      MP_TAC(ISPECL [`(i:num) %% j`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                     `w1:A`;`X:A`;`v:num->A`]
        BVALF_HS_SPEC) THEN ASM_SIMP_TAC[]]; ALL_TAC] THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `z:A = bvalf_HS D (E:A->A->bool) B leq w1 X v (i %% j)`
        SUBST_ALL_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;
                           `leq:A`;`(v:num->A) i`;
        `(v:num->A) j`;`z:A`;`bvalf_HS D (E:A->A->bool) B leq w1 X v (i %% j)`]
            EBV_IN_UNIQUE) THEN
      ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[ubig]; ALL_TAC] THEN
    ASM_REWRITE_TAC[];
    DISCH_TAC THEN EXISTS_TAC `bvalf_HS D (E:A->A->bool) B leq w1 X
        v (i %% j)` THEN
    ASM_REWRITE_TAC[]]);;

let USIM_BVALF_HS = prove
 (`!i j D (E:A->A->bool) B leq w1 X U v.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
         w1 IN D /\ X IN D /\
     valuation D v /\ (!k. hsname D E B w1 X (v k))
     ==> (usim D E B leq U (v i) (v j) <=>
          ubig D E U (bvalf_HS D E B leq w1 X v (Eq i j)))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[usim] THEN
  SUBGOAL_THEN `ebv_eq D (E:A->A->bool) B leq (v i) (v j)
      (bvalf_HS D E B leq w1 X v (Eq i j))`
    ASSUME_TAC THENL [MATCH_MP_TAC BVALF_HS_EQ2 THEN
                      ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(v:num->A) i IN D /\ (v:num->A) j IN D /\
                (bvalf_HS D (E:A->A->bool) B leq w1 X v (Eq i j)) IN D`
                    STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THENL
     [ASM_MESON_TAC[valuation]; ASM_MESON_TAC[valuation];
      MP_TAC(ISPECL [`Eq i j`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                     `X:A`;`v:num->A`]
        BVALF_HS_SPEC) THEN ASM_SIMP_TAC[]]; ALL_TAC] THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `z:A = bvalf_HS D (E:A->A->bool) B leq w1 X v (Eq i j)`
        SUBST_ALL_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;
                           `leq:A`;`(v:num->A) i`;
        `(v:num->A) j`;`z:A`;`bvalf_HS D (E:A->A->bool) B leq w1 X v (Eq i j)`]
            EBV_EQ_UNIQUE) THEN
      ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[ubig]; ALL_TAC] THEN
    ASM_REWRITE_TAC[];
    DISCH_TAC THEN EXISTS_TAC `bvalf_HS D (E:A->A->bool) B leq w1 X
        v (Eq i j)` THEN
    ASM_REWRITE_TAC[]]);;

let LOS_HS = prove
 (`!phi. !D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X U v.
      hsbundle D E w1 om tw ii ci P leqp B inclB onebee X /\
      eultra D E B inclB U /\ valuation D v /\ (!i. hsname D E B w1 X (v i))
      ==> (holds (qdom_HS D E B inclB w1 X U) (qmem D E B inclB U)
                 (\i. qrep_HS D E B inclB w1 X U (v i)) phi
           <=> ubig D E U (bvalf_HS D E B inclB w1 X v phi))`,
  MATCH_MP_TAC form_INDUCT THEN REPEAT CONJ_TAC THENL
  [(* ---------- False ---------- *)
   REPEAT GEN_TAC THEN TRY BETA_TAC THEN REPEAT GEN_TAC THEN STRIP_TAC THEN
   FIRST_ASSUM(fun th -> let cs = CONJUNCTS(REWRITE_RULE[hsbundle] th)
                         and cb = CONJUNCTS(MATCH_MP HSB_CBA th) in
     MAP_EVERY ASSUME_TAC [el 0 cs; el 1 cs; el 3 cs; el 17 cs; el 19 cs;
                           el 0 cb; el 1 cb]) THEN
   REWRITE_TAC[holds] THEN
   SUBGOAL_THEN `ebot D (E:A->A->bool) B inclB
       (bvalf_HS D E B inclB w1 X v False)` ASSUME_TAC THENL
    [MATCH_MP_TAC BVALF_HS_FALSE THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
   SUBGOAL_THEN `~((E:A->A->bool) (bvalf_HS D E B inclB w1 X v False) U)`
       ASSUME_TAC THENL
    [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`U:A`;
       `bvalf_HS D (E:A->A->bool) B inclB w1 X v False`] EULTRA_NOT_BOT) THEN
           ASM_REWRITE_TAC[];
     ALL_TAC] THEN
   ASM_REWRITE_TAC[ubig];
   (* ---------- i %% j ---------- *)
   REPEAT GEN_TAC THEN TRY BETA_TAC THEN REPEAT GEN_TAC THEN STRIP_TAC THEN
   FIRST_ASSUM(fun th -> let cs = CONJUNCTS(REWRITE_RULE[hsbundle] th)
                         and cb = CONJUNCTS(MATCH_MP HSB_CBA th) in
     MAP_EVERY ASSUME_TAC [el 0 cs; el 1 cs; el 3 cs; el 17 cs; el 19 cs;
                           el 0 cb; el 1 cb]) THEN
   REWRITE_TAC[holds; qmem] THEN BETA_TAC THEN
   SUBGOAL_THEN `(v:num->A) a0 IN D /\ (v:num->A) a1 IN D /\
                 hsname D (E:A->A->bool) B w1 X (v a0) /\
                     hsname D E B w1 X (v a1)`
     STRIP_ASSUME_TAC THENL [REPEAT CONJ_TAC THEN
                             ASM_MESON_TAC[valuation]; ALL_TAC] THEN
   SUBGOAL_THEN
     `umem D (E:A->A->bool) B inclB U (qrep_HS D E B inclB w1 X U
         ((v:num->A) a0)) (qrep_HS D E B inclB w1 X U (v a1)) <=>
      umem D E B inclB U (v a0) (v a1)` SUBST1_TAC THENL
    [MATCH_MP_TAC UMEM_QREP_HS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
   MATCH_MP_TAC(ISPECL [`a0:num`;`a1:num`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                        `inclB:A`;`w1:A`;`X:A`;
     `U:A`;`v:num->A`] UMEM_BVALF_HS) THEN ASM_REWRITE_TAC[];
   (* ---------- Eq i j ---------- *)
   REPEAT GEN_TAC THEN TRY BETA_TAC THEN REPEAT GEN_TAC THEN STRIP_TAC THEN
   FIRST_ASSUM(fun th -> let cs = CONJUNCTS(REWRITE_RULE[hsbundle] th)
                         and cb = CONJUNCTS(MATCH_MP HSB_CBA th) in
     MAP_EVERY ASSUME_TAC [el 0 cs; el 1 cs; el 3 cs; el 17 cs; el 19 cs;
                           el 0 cb; el 1 cb]) THEN
   REWRITE_TAC[holds] THEN BETA_TAC THEN
   SUBGOAL_THEN `(v:num->A) a0 IN D /\ (v:num->A) a1 IN D /\
                 hsname D (E:A->A->bool) B w1 X (v a0) /\
                     hsname D E B w1 X (v a1)`
     STRIP_ASSUME_TAC THENL [REPEAT CONJ_TAC THEN
                             ASM_MESON_TAC[valuation]; ALL_TAC] THEN
   MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;`X:A`;`U:A`;
     `(v:num->A) a0`;`(v:num->A) a1`] QREP_HS_EQ) THEN ASM_REWRITE_TAC[] THEN
   DISCH_THEN(SUBST1_TAC o SYM) THEN
   MATCH_MP_TAC(ISPECL [`a0:num`;`a1:num`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                        `inclB:A`;`w1:A`;`X:A`;
     `U:A`;`v:num->A`] USIM_BVALF_HS) THEN ASM_REWRITE_TAC[];
   (* ---------- a0 --> a1 ---------- *)
   REPEAT GEN_TAC THEN TRY BETA_TAC THEN
   DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "ih0") (LABEL_TAC "ih1")) THEN
   REPEAT GEN_TAC THEN STRIP_TAC THEN
   FIRST_ASSUM(fun th -> let cs = CONJUNCTS(REWRITE_RULE[hsbundle] th)
                         and cb = CONJUNCTS(MATCH_MP HSB_CBA th) in
     MAP_EVERY ASSUME_TAC [el 0 cs; el 1 cs; el 3 cs; el 17 cs; el 19 cs;
                           el 0 cb; el 1 cb]) THEN REWRITE_TAC[holds] THEN
   SUBGOAL_THEN `holds (qdom_HS D E B inclB w1 X U) (qmem D E B inclB U)
                       (\i. qrep_HS D (E:A->A->bool) B inclB w1 X U (v i)) a0
                 <=> ubig D E U (bvalf_HS D E B inclB w1 X v a0)`
                     SUBST1_TAC THENL
    [USE_THEN "ih0" (fun ith -> MATCH_MP_TAC(ISPECL
        [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;`ii:A`;`ci:A`;`P:A`;
         `leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`U:A`;`v:num->A`] ith)) THEN
     ASM_REWRITE_TAC[]; ALL_TAC] THEN
   SUBGOAL_THEN `holds (qdom_HS D E B inclB w1 X U) (qmem D E B inclB U)
                       (\i. qrep_HS D (E:A->A->bool) B inclB w1 X U (v i)) a1
                 <=> ubig D E U (bvalf_HS D E B inclB w1 X v a1)`
                     SUBST1_TAC THENL
    [USE_THEN "ih1" (fun ith -> MATCH_MP_TAC(ISPECL
        [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;`ii:A`;`ci:A`;`P:A`;
         `leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`U:A`;`v:num->A`] ith)) THEN
     ASM_REWRITE_TAC[]; ALL_TAC] THEN
   SUBGOAL_THEN
    `(bvalf_HS D (E:A->A->bool) B inclB w1 X v a0) IN D /\
        E (bvalf_HS D E B inclB w1 X v a0) B /\
     (bvalf_HS D (E:A->A->bool) B inclB w1 X v a1) IN D /\
         E (bvalf_HS D E B inclB w1 X v a1) B /\
     (bvalf_HS D (E:A->A->bool) B inclB w1 X v (a0 --> a1)) IN D /\
     E (bvalf_HS D E B inclB w1 X v (a0 --> a1)) B`
    STRIP_ASSUME_TAC THENL
    [REPEAT CONJ_TAC THENL
      [MP_TAC(ISPECL [`a0:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;
                      `w1:A`;`X:A`;`v:num->A`]
         BVALF_HS_SPEC) THEN ASM_SIMP_TAC[];
       MP_TAC(ISPECL [`a0:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;
                      `w1:A`;`X:A`;`v:num->A`]
         BVALF_HS_IN_B) THEN ASM_SIMP_TAC[];
       MP_TAC(ISPECL [`a1:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;
                      `w1:A`;`X:A`;`v:num->A`]
         BVALF_HS_SPEC) THEN ASM_SIMP_TAC[];
       MP_TAC(ISPECL [`a1:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;
                      `w1:A`;`X:A`;`v:num->A`]
         BVALF_HS_IN_B) THEN ASM_SIMP_TAC[];
       MP_TAC(ISPECL [`a0 --> a1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;
                      `w1:A`;`X:A`;`v:num->A`]
         BVALF_HS_SPEC) THEN ASM_SIMP_TAC[];
       MP_TAC(ISPECL [`a0 --> a1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;
                      `w1:A`;`X:A`;`v:num->A`]
         BVALF_HS_IN_B) THEN ASM_SIMP_TAC[]]; ALL_TAC] THEN
   SUBGOAL_THEN `ubig D (E:A->A->bool) U (bvalf_HS D E B inclB w1 X v a0) <=>
                 E (bvalf_HS D E B inclB w1 X v a0) U` SUBST1_TAC THENL
    [MATCH_MP_TAC UBIG_BVALF_HS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
   SUBGOAL_THEN `ubig D (E:A->A->bool) U (bvalf_HS D E B inclB w1 X v a1) <=>
                 E (bvalf_HS D E B inclB w1 X v a1) U` SUBST1_TAC THENL
    [MATCH_MP_TAC UBIG_BVALF_HS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
   SUBGOAL_THEN `ubig D (E:A->A->bool) U
       (bvalf_HS D E B inclB w1 X v (a0 --> a1)) <=>
                 E (bvalf_HS D E B inclB w1 X v (a0 --> a1)) U` SUBST1_TAC THENL
    [MATCH_MP_TAC UBIG_BVALF_HS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
   CONV_TAC SYM_CONV THEN
   MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`U:A`;
     `bvalf_HS D (E:A->A->bool) B inclB w1 X v a0`;
         `bvalf_HS D (E:A->A->bool) B inclB w1 X v a1`;
     `bvalf_HS D (E:A->A->bool) B inclB w1 X v (a0 --> a1)`] EULTRA_IMP) THEN
   ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
    [ASM_MESON_TAC[ECBA_IMP_BALG];
     MATCH_MP_TAC BVALF_HS_IMP THEN ASM_REWRITE_TAC[]];
   (* ---------- !! a0 a1 ---------- *)
   REPEAT GEN_TAC THEN TRY BETA_TAC THEN DISCH_THEN(LABEL_TAC "ih") THEN
   REPEAT GEN_TAC THEN STRIP_TAC THEN
   FIRST_ASSUM(fun th -> let cs = CONJUNCTS(REWRITE_RULE[hsbundle] th)
                         and cb = CONJUNCTS(MATCH_MP HSB_CBA th) in
     MAP_EVERY ASSUME_TAC [el 0 cs; el 1 cs; el 3 cs; el 17 cs; el 19 cs;
                           el 0 cb; el 1 cb]) THEN REWRITE_TAC[holds] THEN
   ONCE_REWRITE_TAC[QDOM_HS_FORALL] THEN ONCE_REWRITE_TAC[QREP_HS_PUSH] THEN
   SUBGOAL_THEN `ubig D (E:A->A->bool) U
       (bvalf_HS D E B inclB w1 X v (!! a0 a1)) <=>
                 E (bvalf_HS D E B inclB w1 X v (!! a0 a1)) U` SUBST1_TAC THENL
    [MATCH_MP_TAC UBIG_BVALF_HS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
   EQ_TAC THENL
    [(* ==> : maximum principle *)
     DISCH_THEN(LABEL_TAC "H") THEN
     MP_TAC(ISPECL [`a0:num`;`a1:form`;`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;
                    `tw:A`;`ii:A`;`ci:A`;`P:A`;`leqp:A`;`B:A`;`inclB:A`;
         `onebee:A`;`X:A`;`v:num->A`]
       MAXPRIN_ALL_HS) THEN ASM_REWRITE_TAC[] THEN
     DISCH_THEN(X_CHOOSE_THEN `a:A` (CONJUNCTS_THEN2 (LABEL_TAC "aD")
       (CONJUNCTS_THEN2 (LABEL_TAC "bna") (LABEL_TAC "eqm")))) THEN
     SUBGOAL_THEN `valuation D ((a0 |-> (a:A)) (v:num->A)) /\
                   (!i. hsname D (E:A->A->bool) B w1 X (((a0 |-> a) v) i))`
       STRIP_ASSUME_TAC THENL
      [CONJ_TAC THENL
        [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
         MATCH_MP_TAC HSNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
     SUBGOAL_THEN `holds (qdom_HS D E B inclB w1 X U) (qmem D E B inclB U)
                         (\i. qrep_HS D (E:A->A->bool) B inclB w1 X U
                          (((a0 |-> (a:A)) v) i)) a1`
       (LABEL_TAC "hlds") THENL
      [USE_THEN "H" (fun th -> MP_TAC(SPEC `a:A` th)) THEN
       ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
     SUBGOAL_THEN `ubig D (E:A->A->bool) U
         (bvalf_HS D E B inclB w1 X ((a0 |-> (a:A)) v) a1)`
       MP_TAC THENL
      [SUBGOAL_THEN
         `holds (qdom_HS D E B inclB w1 X U) (qmem D E B inclB U)
                (\i. qrep_HS D (E:A->A->bool) B inclB w1 X U
                 (((a0 |-> (a:A)) v) i)) a1
          <=> ubig D E U (bvalf_HS D E B inclB w1 X ((a0 |-> (a:A)) v) a1)`
         MP_TAC THENL
        [USE_THEN "ih" (fun ith ->
           MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;
                                `ii:A`;`ci:A`;`P:A`;`leqp:A`;`B:A`;`inclB:A`;
               `onebee:A`;`X:A`;`U:A`;
             `(a0 |-> (a:A)) (v:num->A)`] ith)) THEN
                 ASM_REWRITE_TAC[]; ALL_TAC] THEN
       USE_THEN "hlds" (fun h -> DISCH_THEN(fun iff ->
           ACCEPT_TAC(EQ_MP iff h)));
       ALL_TAC] THEN
     REWRITE_TAC[ubig] THEN USE_THEN "eqm" SUBST1_TAC THEN
     STRIP_TAC THEN ASM_REWRITE_TAC[];
     (* <== : lower-bound + upward closure *)
     DISCH_TAC THEN X_GEN_TAC `c:A` THEN STRIP_TAC THEN
     SUBGOAL_THEN `valuation D ((a0 |-> (c:A)) (v:num->A)) /\
                   (!i. hsname D (E:A->A->bool) B w1 X (((a0 |-> c) v) i))`
       STRIP_ASSUME_TAC THENL
      [CONJ_TAC THENL
        [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
         MATCH_MP_TAC HSNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
     SUBGOAL_THEN `holds (qdom_HS D E B inclB w1 X U) (qmem D E B inclB U)
                         (\i. qrep_HS D (E:A->A->bool) B inclB w1 X U
                          (((a0 |-> (c:A)) v) i)) a1
                   <=> ubig D E U (bvalf_HS D E B inclB w1 X ((a0 |-> c) v) a1)`
                       SUBST1_TAC THENL
      [USE_THEN "ih" (fun ith ->
         MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;
                              `ii:A`;`ci:A`;`P:A`;`leqp:A`;`B:A`;`inclB:A`;
             `onebee:A`;`X:A`;`U:A`;
             `(a0 |-> (c:A)) (v:num->A)`] ith)) THEN
                 ASM_REWRITE_TAC[]; ALL_TAC] THEN
     REWRITE_TAC[ubig] THEN CONJ_TAC THENL
      [MP_TAC(ISPECL [`a1:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;
                      `w1:A`;`X:A`;`(a0 |-> (c:A)) (v:num->A)`]
         BVALF_HS_SPEC) THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
     MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`U:A`;
       `bvalf_HS D (E:A->A->bool) B inclB w1 X v (!! a0 a1)`;
       `bvalf_HS D (E:A->A->bool) B inclB w1 X ((a0 |-> (c:A)) v) a1`]
           EULTRA_UP) THEN
     ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
      [MP_TAC(ISPECL [`!! a0 a1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;
                      `w1:A`;`X:A`;`v:num->A`]
         BVALF_HS_SPEC) THEN ASM_SIMP_TAC[];
       MP_TAC(ISPECL [`a1:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;
                      `w1:A`;`X:A`;`(a0 |-> (c:A)) (v:num->A)`]
         BVALF_HS_SPEC) THEN ASM_SIMP_TAC[];
       MP_TAC(ISPECL [`a1:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;
                      `w1:A`;`X:A`;`(a0 |-> (c:A)) (v:num->A)`]
         BVALF_HS_IN_B) THEN ASM_SIMP_TAC[];
       MATCH_MP_TAC(ISPECL [`a0:num`;`a1:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                            `inclB:A`;`w1:A`;`X:A`;
         `v:num->A`;`c:A`] BVALF_HS_ALL_LB) THEN ASM_REWRITE_TAC[]]]]);;

(* ===================================================================== *)
(* H4.0 : the HS-quotient bridge.  QVAL_LIFT_HS (a quotient valuation is   *)
(* the image of an HS valuation), QSAT_AX_HS (an axiom with value TOP at   *)
(* every HS valuation holds in qdom_HS / qmem, via LOS_HS), and            *)
(* QDOM_HS_NONEMPTY (via an HS check name).                                *)
(* ===================================================================== *)
let QVAL_LIFT_HS = prove
 (`!D (E:A->A->bool) B leq w1 X U v.
      valuation (qdom_HS D E B leq w1 X U) v
      ==> ?c. valuation D c /\ (!i. hsname D E B w1 X (c i)) /\
              (!i. (v:num->A) i = qrep_HS D E B leq w1 X U (c i))`,
  REPEAT GEN_TAC THEN REWRITE_TAC[valuation] THEN DISCH_TAC THEN
  SUBGOAL_THEN
   `!i:num. ?a:A. a IN D /\ hsname D (E:A->A->bool) B w1 X a /\
                  (v:num->A) i = qrep_HS D E B leq w1 X U a`
   MP_TAC THENL
   [X_GEN_TAC `i:num` THEN FIRST_ASSUM(MP_TAC o SPEC `i:num`) THEN
    REWRITE_TAC[IN; qdom_HS] THEN DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  REWRITE_TAC[SKOLEM_THM] THEN
  DISCH_THEN(X_CHOOSE_THEN `c:num->A` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `c:num->A` THEN REWRITE_TAC[valuation] THEN ASM_MESON_TAC[]);;

let QSAT_AX_HS = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X U phi.
      hsbundle D E w1 om tw ii ci P leqp B inclB onebee X /\
      eultra D E B inclB U /\
      (!c. valuation D c /\ (!i. hsname D E B w1 X (c i))
           ==> etop D E B inclB (bvalf_HS D E B inclB w1 X c phi))
      ==> !v. valuation (qdom_HS D E B inclB w1 X U) v
              ==> holds (qdom_HS D E B inclB w1 X U)
                  (qmem D E B inclB U) v phi`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_ASSUM(fun th -> let cs = CONJUNCTS(REWRITE_RULE[hsbundle] th)
                        and cb = CONJUNCTS(MATCH_MP HSB_CBA th) in
    MAP_EVERY ASSUME_TAC [el 0 cs; el 1 cs; el 3 cs; el 15 cs;
                          el 16 cs; el 17 cs;
                          el 18 cs; el 19 cs; el 14 cs; el 0 cb; el 1 cb]) THEN
  X_GEN_TAC `v:num->A` THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;`X:A`;
                 `U:A`;`v:num->A`]
    QVAL_LIFT_HS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `c:num->A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `v:num->A = \i. qrep_HS D (E:A->A->bool) B inclB w1 X U (c i)`
    SUBST_ALL_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN BETA_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`phi:form`;`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;
                 `ii:A`;`ci:A`;`P:A`;`leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;
      `U:A`;`c:num->A`] LOS_HS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
  REWRITE_TAC[ubig] THEN
  SUBGOAL_THEN `etop D (E:A->A->bool) B inclB (bvalf_HS D E B inclB w1 X c phi)`
    ASSUME_TAC THENL
   [FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  CONJ_TAC THENL
   [ASM_MESON_TAC[ETOP_IN];
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`U:A`;
      `bvalf_HS D (E:A->A->bool) B inclB w1 X c phi`] EULTRA_TOP) THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[EBALG_IMP_PORDER; ECBA_IMP_BALG]]);;

let QDOM_HS_NONEMPTY = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X U.
      hsbundle D E w1 om tw ii ci P leqp B inclB onebee X /\
      eultra D E B inclB U
      ==> ~(qdom_HS D E B inclB w1 X U = {})`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_ASSUM(fun th -> let cs = CONJUNCTS(REWRITE_RULE[hsbundle] th)
                        and cb = CONJUNCTS(MATCH_MP HSB_CBA th) in
    MAP_EVERY ASSUME_TAC [el 0 cs; el 1 cs; el 3 cs; el 15 cs;
                          el 16 cs; el 17 cs;
                          el 18 cs; el 19 cs; el 14 cs; el 0 cb; el 1 cb]) THEN
  FIRST_ASSUM(fun th -> ASSUME_TAC(CONJUNCT1(MATCH_MP HSB_FACTS th))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`om:A`]
         ECHECK_EXHAUSTION) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `vk:A` (LABEL_TAC "chk")) THEN
  SUBGOAL_THEN `(vk:A) IN D` (LABEL_TAC "vkD") THENL
   [USE_THEN "chk" (ACCEPT_TAC o CONJUNCT2 o MATCH_MP ECHECK_IMP); ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;`ii:A`;`ci:A`;
                `P:A`;`leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`om:A`;
      `vk:A`] HS_CHECK) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN(LABEL_TAC "hsk")] THEN
  REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN] THEN
  EXISTS_TAC `qrep_HS D (E:A->A->bool) B inclB w1 X U vk` THEN
  REWRITE_TAC[qdom_HS] THEN EXISTS_TAC `vk:A` THEN ASM_REWRITE_TAC[]);;

(* ===================================================================== *)
(* H4.1 : connective-TOP layer for bvalf_HS (clones of godel_forcing.ml):   *)
(* ALL/IMP/NOT/AND/OR/IFF/FORALLMEM/EX/EXISTSMEM value characterizations. *)
(* ===================================================================== *)
let BVALF_HS_ALL_TOP = prove
 (`!n p D (E:A->A->bool) B leq w1 X v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
          w1 IN D /\ X IN D /\
      valuation D v /\ (!i. hsname D E B w1 X (v i))
      ==> (etop D E B leq (bvalf_HS D (E:A->A->bool) B leq w1 X v (!! n p)) <=>
           (!a. a IN D /\ hsname D E B w1 X a
                ==> etop D E B leq (bvalf_HS D (E:A->A->bool) B leq w1 X
                                    ((n |-> (a:A)) (v:num->A)) p)))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[elattice] o CONJUNCT1 o
      REWRITE_RULE[ebalg] o CONJUNCT1 o REWRITE_RULE[ecba]); ALL_TAC] THEN
  SUBGOAL_THEN `?t. etop D (E:A->A->bool) B leq t` ASSUME_TAC THENL
   [MATCH_MP_TAC EBALG_TOP THEN
    FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[ecba]); ALL_TAC] THEN
  MP_TAC(ISPECL [`!! n p`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                 `X:A`;`v:num->A`]
    BVALF_HS_SPEC) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[bval_HS] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
             (X_CHOOSE_THEN `sv:A` STRIP_ASSUME_TAC)) THEN
  (* sv IN D, membership !zz., eglb sv (bvalf_HS(!!n p)) *)
  SUBGOAL_THEN `esubset D (E:A->A->bool) sv B` ASSUME_TAC THENL
   [REWRITE_TAC[esubset] THEN X_GEN_TAC `zz:A` THEN STRIP_TAC THEN
    FIRST_X_ASSUM(fun th -> MP_TAC(SPEC `zz:A` th) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC]) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `a:A` STRIP_ASSUME_TAC) THEN
    MATCH_MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                         `leq:A`;`w1:A`;`X:A`;
      `(n |-> (a:A)) (v:num->A)`;`zz:A`] BVAL_HS_IN_B) THEN
    ASM_REWRITE_TAC[] THEN MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`sv:A`;
    `bvalf_HS D (E:A->A->bool) B leq w1 X v (!! n p)`] EGLB_TOP) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
  EQ_TAC THENL
   [DISCH_TAC THEN X_GEN_TAC `a:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `!i. hsname D E B w1 X (((n |-> (a:A)) (v:num->A)) i)`
        ASSUME_TAC THENL
     [MATCH_MP_TAC HSNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    FIRST_X_ASSUM MATCH_MP_TAC THEN
    MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                   `X:A`;`(n |-> (a:A)) (v:num->A)`]
      BVALF_HS_SPEC) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN MATCH_MP_TAC VALUATION_VALMOD THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
    FIRST_X_ASSUM(fun th -> MP_TAC(SPEC `bvalf_HS D (E:A->A->bool) B leq w1 X
        ((n |-> (a:A)) (v:num->A)) p` th) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC]) THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MAP_EVERY EXISTS_TAC [`a:A`] THEN ASM_REWRITE_TAC[];
    DISCH_TAC THEN X_GEN_TAC `w:A` THEN STRIP_TAC THEN
    FIRST_X_ASSUM(fun th ->
      if is_forall(concl th) && mem `sv:A` (frees(concl th))
      then (MP_TAC(SPEC `w:A` th) THEN
            ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC])
      else failwith "skip") THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `a:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `!i. hsname D E B w1 X (((n |-> (a:A)) (v:num->A)) i)`
        ASSUME_TAC THENL
     [MATCH_MP_TAC HSNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `w:A = bvalf_HS D (E:A->A->bool) B leq w1 X
        ((n |-> (a:A)) (v:num->A)) p` SUBST1_TAC THENL
     [MATCH_MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                           `leq:A`;`w1:A`;`X:A`;
        `(n |-> (a:A)) (v:num->A)`;`w:A`] BVALF_HS_EQ) THEN
      ASM_REWRITE_TAC[] THEN MATCH_MP_TAC VALUATION_VALMOD THEN
          ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]]);;

let BVALF_HS_IMP_TOP = prove
 (`!p q D (E:A->A->bool) B leq w1 X v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
          w1 IN D /\ X IN D /\
      valuation D v /\ (!i. hsname D E B w1 X (v i))
      ==> (etop D E B leq (bvalf_HS D E B leq w1 X v (p --> q)) <=>
           erel D E leq (bvalf_HS D E B leq w1 X v p)
               (bvalf_HS D E B leq w1 X v q))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[ecba]); ALL_TAC] THEN
  MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                 `X:A`;`v:num->A`]
    BVALF_HS_SPEC) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  STRIP_TAC THEN
  MP_TAC(ISPECL [`q:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                 `X:A`;`v:num->A`]
    BVALF_HS_SPEC) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  STRIP_TAC THEN
  MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                 `X:A`;`v:num->A`]
    BVALF_HS_IN_B) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC]
        THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`q:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                 `X:A`;`v:num->A`]
    BVALF_HS_IN_B) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC]
        THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`p:form`;`q:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                 `w1:A`;`X:A`;`v:num->A`]
    BVALF_HS_IMP) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC]
        THEN DISCH_TAC THEN
  MATCH_MP_TAC EBIMP_TOP THEN ASM_REWRITE_TAC[]);;

let BVALF_HS_NOT_TOP = prove
 (`!p D (E:A->A->bool) B leq w1 X v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
          w1 IN D /\ X IN D /\
      valuation D v /\ (!i. hsname D E B w1 X (v i))
      ==> (etop D E B leq (bvalf_HS D E B leq w1 X v (Not p)) <=>
           ebot D E B leq (bvalf_HS D E B leq w1 X v p))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[ecba]); ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                 `X:A`;`v:num->A`]
    BVALF_HS_SPEC) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  STRIP_TAC THEN
  MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                 `X:A`;`v:num->A`]
    BVALF_HS_IN_B) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC]
        THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                 `X:A`;`v:num->A`]
    BVALF_HS_NOT) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC]
        THEN DISCH_TAC THEN
  MATCH_MP_TAC ECOMPL_TOP_BOT THEN ASM_REWRITE_TAC[]);;

let BVALF_HS_IMP_BOT = prove
 (`!p q D (E:A->A->bool) B leq w1 X v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
          w1 IN D /\ X IN D /\
      valuation D v /\ (!i. hsname D E B w1 X (v i))
      ==> (ebot D E B leq (bvalf_HS D E B leq w1 X v (p --> q)) <=>
           etop D E B leq (bvalf_HS D E B leq w1 X v p) /\
           ebot D E B leq (bvalf_HS D E B leq w1 X v q))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[ecba]); ALL_TAC] THEN
  MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                 `X:A`;`v:num->A`]
    BVALF_HS_SPEC) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC]
        THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`q:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                 `X:A`;`v:num->A`]
    BVALF_HS_SPEC) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC]
        THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                 `X:A`;`v:num->A`]
    BVALF_HS_IN_B) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC]
        THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`q:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                 `X:A`;`v:num->A`]
    BVALF_HS_IN_B) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC]
        THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`p:form`;`q:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                 `w1:A`;`X:A`;`v:num->A`]
    BVALF_HS_IMP) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC]
        THEN DISCH_TAC THEN
  MATCH_MP_TAC EBIMP_BOT THEN ASM_REWRITE_TAC[]);;

let BVALF_HS_NOT_BOT = prove
 (`!p D (E:A->A->bool) B leq w1 X v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
          w1 IN D /\ X IN D /\
      valuation D v /\ (!i. hsname D E B w1 X (v i))
      ==> (ebot D E B leq (bvalf_HS D E B leq w1 X v (Not p)) <=>
           etop D E B leq (bvalf_HS D E B leq w1 X v p))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[ecba]); ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
