let BVALF_HS_FORALLMEM_TOP = prove
 (`!x y p D (E:A->A->bool) B leq w1 X v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
          w1 IN D /\ X IN D /\
      valuation D v /\ (!i. hsname D E B w1 X (v i))
      ==> (etop D E B leq (bvalf_HS D E B leq w1 X v (!!- x y p)) <=>
           (!a. a IN D /\ hsname D E B w1 X a
                ==> erel D E leq
                      (bvalf_HS D E B leq w1 X ((x |-> a) v) (x %% y))
                      (bvalf_HS D E B leq w1 X ((x |-> a) v) p)))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[Forallmem_DEF] THEN
  MP_TAC(ISPECL [`x:num`; `(x %% y) --> p`; `D:A->bool`;`E:A->A->bool`;`B:A`;
                 `leq:A`;`w1:A`;`X:A`;`v:num->A`] BVALF_HS_ALL_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MATCH_MP_TAC FORALL_IMP_CONG THEN
  X_GEN_TAC `a:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((x |-> (a:A)) v)` ASSUME_TAC THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `!i. hsname D E B w1 X (((x |-> (a:A)) (v:num->A)) i)`
      ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC BVALF_HS_IMP_TOP THEN ASM_REWRITE_TAC[]);;

