        THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`Not p`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                 `X:A`;`v:num->A`]
    BVALF_HS_IN_B) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC]
