                 `X:A`;`v:num->A`]
    BVALF_HS_IN_B) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC]
        THEN DISCH_TAC THEN
  (* ecompl (bvalf_HS p) (bvalf_HS (Not p)) *)
  MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                 `X:A`;`v:num->A`]
    BVALF_HS_NOT) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC]
        THEN DISCH_TAC THEN
  (* ecompl (bvalf_HS (p-->Not q)) (bvalf_HS (Not(p-->Not q))) *)
  MP_TAC(ISPECL [`p --> Not q`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                 `X:A`;`v:num->A`]
    BVALF_HS_NOT) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC]
        THEN DISCH_TAC THEN
  (* ebimp (bvalf_HS p) (bvalf_HS (Not q)) (bvalf_HS (p-->Not q)) *)
  MP_TAC(ISPECL [`p:form`;`Not q`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                 `w1:A`;`X:A`;`v:num->A`]
    BVALF_HS_IMP) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[ebimp] THEN
  DISCH_THEN(X_CHOOSE_THEN `c:A` STRIP_ASSUME_TAC) THEN
  (* c = bvalf_HS(Not p) via ECOMPL_UNIQUE *)
  SUBGOAL_THEN `c:A = bvalf_HS D (E:A->A->bool) B leq w1 X v (Not p)`
      SUBST_ALL_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `bvalf_HS D (E:A->A->bool) B leq w1 X v p`;`c:A`;
      `bvalf_HS D (E:A->A->bool) B leq w1 X v (Not p)`] ECOMPL_UNIQUE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* erel (bvalf_HS(Not p)) (bvalf_HS(p-->Not q)) via EJOIN_GE *)
  SUBGOAL_THEN
   `erel D E leq (bvalf_HS D (E:A->A->bool) B leq w1 X v (Not p))
                 (bvalf_HS D E B leq w1 X v (p --> Not q))` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o MATCH_MP EJOIN_GE); ALL_TAC] THEN
  (* ecompl (bvalf_HS(Not p)) (bvalf_HS p) via ECOMPL_SYM *)
  SUBGOAL_THEN
   `ecompl D (E:A->A->bool) B leq (bvalf_HS D E B leq w1 X v (Not p))
       (bvalf_HS D E B leq w1 X v p)`
  ASSUME_TAC THENL
   [MATCH_MP_TAC ECOMPL_SYM THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
    `bvalf_HS D (E:A->A->bool) B leq w1 X v (Not p)`;
    `bvalf_HS D (E:A->A->bool) B leq w1 X v (p --> Not q)`;
    `bvalf_HS D (E:A->A->bool) B leq w1 X v p`;
    `bvalf_HS D (E:A->A->bool) B leq w1 X v (Not(p --> Not q))`]
        ECOMPL_ANTITONE) THEN
  ASM_REWRITE_TAC[]);;

