let BVALF_HS_EX_TOP = prove
 (`!n p D (E:A->A->bool) B leq w1 X v a.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
          w1 IN D /\ X IN D /\
      valuation D v /\ (!i. hsname D E B w1 X (v i)) /\ a IN D /\
          hsname D E B w1 X a /\
      etop D E B leq (bvalf_HS D E B leq w1 X ((n |-> a) v) p)
      ==> etop D E B leq (bvalf_HS D E B leq w1 X v (?? n p))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((n |-> (a:A)) (v:num->A)) /\
                (!i. hsname D E B w1 X (((n |-> (a:A)) (v:num->A)) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC HSNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  REWRITE_TAC[Exists_DEF] THEN
  MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;`X:A`;
    `(n |-> (a:A)) (v:num->A)`] BVALF_HS_NOT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`!! n (Not p)`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                 `X:A`;`v:num->A`]
    BVALF_HS_NOT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
  ABBREV_TAC `pa = bvalf_HS D (E:A->A->bool) B leq w1 X
      ((n |-> (a:A)) (v:num->A)) p` THEN
  ABBREV_TAC `npa = bvalf_HS D (E:A->A->bool) B leq w1 X
      ((n |-> (a:A)) (v:num->A)) (Not p)` THEN
  ABBREV_TAC `glb = bvalf_HS D (E:A->A->bool) B leq w1 X (v:num->A)
      (!! n (Not p))` THEN
  ABBREV_TAC `cc = bvalf_HS D (E:A->A->bool) B leq w1 X (v:num->A)
      (Not(!! n (Not p)))` THEN
  SUBGOAL_THEN `(pa:A) IN D /\ (E:A->A->bool) pa B` STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "pa" THEN CONJ_TAC THENL
     [MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                     `X:A`;`(n |-> (a:A)) (v:num->A)`] BVALF_HS_SPEC) THEN
         ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                     `X:A`;`(n |-> (a:A)) (v:num->A)`] BVALF_HS_IN_B) THEN
          ASM_SIMP_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN `(npa:A) IN D /\ (E:A->A->bool) npa B` STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "npa" THEN CONJ_TAC THENL
     [MP_TAC(ISPECL [`Not p`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                     `X:A`;`(n |-> (a:A)) (v:num->A)`] BVALF_HS_SPEC) THEN
         ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`Not p`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                     `X:A`;`(n |-> (a:A)) (v:num->A)`] BVALF_HS_IN_B) THEN
          ASM_SIMP_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN `(glb:A) IN D /\ (E:A->A->bool) glb B` STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "glb" THEN CONJ_TAC THENL
     [MP_TAC(ISPECL [`!! n (Not p)`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                     `w1:A`;`X:A`;`v:num->A`] BVALF_HS_SPEC) THEN
         ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`!! n (Not p)`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                     `w1:A`;`X:A`;`v:num->A`] BVALF_HS_IN_B) THEN
          ASM_SIMP_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN `ecompl D (E:A->A->bool) B leq npa pa` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`pa:A`;`npa:A`]
           ECOMPL_SYM) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `ebot D (E:A->A->bool) B leq npa` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`npa:A`;`pa:A`]
           ECOMPL_TOP_BOT) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq glb npa` ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["glb";"npa"] THEN
    MP_TAC(ISPECL [`n:num`;`Not p`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                   `w1:A`;`X:A`;`v:num->A`;`a:A`] BVALF_HS_ALL_LB) THEN
    ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq npa glb` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`npa:A`;
                   `glb:A`] EBOT_LE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `ebot D (E:A->A->bool) B leq glb` ASSUME_TAC THENL
   [SUBGOAL_THEN `glb:A = npa` (fun th -> ASM_REWRITE_TAC[th]) THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`glb:A`;`npa:A`]
           EPORDER_ANTISYM) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`glb:A`;`cc:A`]
         ECOMPL_TOP_BOT) THEN
  ASM_REWRITE_TAC[]);;

let BVALF_HS_EXISTSMEM_TOP = prove
 (`!x y p D (E:A->A->bool) B leq w1 X v a.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
          w1 IN D /\ X IN D /\
      valuation D v /\ (!i. hsname D E B w1 X (v i)) /\ a IN D /\
          hsname D E B w1 X a /\
      etop D E B leq (bvalf_HS D E B leq w1 X ((x |-> a) v) (x %% y)) /\
      etop D E B leq (bvalf_HS D E B leq w1 X ((x |-> a) v) p)
      ==> etop D E B leq (bvalf_HS D E B leq w1 X v (??- x y p))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((x |-> (a:A)) (v:num->A)) /\
                (!i. hsname D E B w1 X (((x |-> (a:A)) (v:num->A)) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC HSNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  REWRITE_TAC[Existsmem_DEF] THEN
  MP_TAC(ISPECL [`x:num`;`(x %% y) && p`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                 `leq:A`;`w1:A`;`X:A`;
    `v:num->A`;`a:A`] BVALF_HS_EX_TOP) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    MP_TAC(ISPECL [`x %% y`;`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                   `leq:A`;`w1:A`;`X:A`;
      `(x |-> (a:A)) (v:num->A)`] BVALF_HS_AND_TOP) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
    DISCH_THEN ACCEPT_TAC]);;

(* ===================================================================== *)
(* H4.2 : members of HS names.  HSNAME_DOM: the domain elements of an HS  *)
(* name are HS names (HSSTAGE_CHAR + ehsfuns).                             *)
(* ===================================================================== *)

let HSNAME_DOM = prove
 (`!D (E:A->A->bool) B w1 X x u.
     model D E ZF_AX /\ B IN D /\ w1 IN D /\ X IN D /\
     x IN D /\ hsname D E B w1 X x /\ eindom D E x u
     ==> u IN D /\ hsname D E B w1 X u`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
             (CONJUNCTS_THEN2 (LABEL_TAC "BD")
              (CONJUNCTS_THEN2 (LABEL_TAC "w1D")
               (CONJUNCTS_THEN2 (LABEL_TAC "XD")
                (CONJUNCTS_THEN2 (LABEL_TAC "xD")
                 (CONJUNCTS_THEN2 (LABEL_TAC "hsx")
                  (MP_TAC o REWRITE_RULE[eindom]))))))) THEN
  DISCH_THEN(X_CHOOSE_THEN `c:A` (CONJUNCTS_THEN2 (LABEL_TAC "cD")
      (MP_TAC o REWRITE_RULE[eapply]))) THEN
  DISCH_THEN(X_CHOOSE_THEN `z:A` (CONJUNCTS_THEN2 (LABEL_TAC "op")
      (LABEL_TAC "zx"))) THEN
  SUBGOAL_THEN `(z:A) IN D` (LABEL_TAC "zD") THENL
   [USE_THEN "op" (ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
  SUBGOAL_THEN `?a y. a IN D /\ y IN D /\ eordinal D (E:A->A->bool) a /\
                      hsstage D E B w1 X a y /\ E x y`
   (X_CHOOSE_THEN `a:A` (X_CHOOSE_THEN `y:A` (CONJUNCTS_THEN2 (LABEL_TAC "aD")
     (CONJUNCTS_THEN2 (LABEL_TAC "yD") (CONJUNCTS_THEN2 (LABEL_TAC "aord")
       (CONJUNCTS_THEN2 (LABEL_TAC "hsay") (LABEL_TAC "xy"))))))) THENL
   [USE_THEN "hsx" (ACCEPT_TAC o REWRITE_RULE[hsname]); ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;`a:A`;`y:A`]
         HSSTAGE_CHAR) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `w:A` (CONJUNCTS_THEN2 (LABEL_TAC "wD")
      (CONJUNCTS_THEN2 (LABEL_TAC "wch") (LABEL_TAC "wfuns")))) THEN
  USE_THEN "wfuns" (MP_TAC o SPEC `x:A` o CONJUNCT2 o
                    REWRITE_RULE[ehsfuns]) THEN
  ANTS_TAC THENL [USE_THEN "xD" ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> USE_THEN "xy" (MP_TAC o EQ_MP th)) THEN
  REWRITE_TAC[ehsmem; ebnmem] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (CONJUNCTS_THEN2 (LABEL_TAC "isfx")
      (X_CHOOSE_THEN `cr:A`
    (CONJUNCTS_THEN2 (LABEL_TAC "crD") (CONJUNCTS_THEN2 (LABEL_TAC "crx")
      (LABEL_TAC "xcr"))))) (K ALL_TAC)) THEN
  (* any member z0 of x is <u0,w0> with u0 IN w (an HS name) and w0 IN B *)
  SUBGOAL_THEN
   `!z0. z0 IN D /\ (E:A->A->bool) z0 x
        ==> ?u0 w0. u0 IN D /\ w0 IN D /\ E u0 w /\ E w0 B /\
            eopair D E u0 w0 z0 /\
                    hsname D E B w1 X u0`
   (LABEL_TAC "mem") THENL
   [X_GEN_TAC `z0:A` THEN DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "z0D")
       (LABEL_TAC "z0x")) THEN
    SUBGOAL_THEN `(E:A->A->bool) z0 cr` (LABEL_TAC "zcr") THENL
     [USE_THEN "xcr" (MP_TAC o SPEC `z0:A` o REWRITE_RULE[esubset]) THEN
      ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`B:A`;`cr:A`;`z0:A`]
           ECROSS_MEMBER) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "zcr" (MP_TAC o EQ_MP th)) THEN
    DISCH_THEN(X_CHOOSE_THEN `u0:A` (X_CHOOSE_THEN `w0:A`
        (CONJUNCTS_THEN2 (LABEL_TAC "u0D")
      (CONJUNCTS_THEN2 (LABEL_TAC "w0D") (CONJUNCTS_THEN2 (LABEL_TAC "u0w")
        (CONJUNCTS_THEN2 (LABEL_TAC "w0B") (LABEL_TAC "op0"))))))) THEN
    MAP_EVERY EXISTS_TAC [`u0:A`;`w0:A`] THEN REPEAT CONJ_TAC THEN
        TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    USE_THEN "wch" (MP_TAC o SPEC `u0:A`) THEN
    ANTS_TAC THENL [USE_THEN "u0D" ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "u0w" (MP_TAC o EQ_MP th)) THEN
    DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `zb:A`
        (CONJUNCTS_THEN2 (LABEL_TAC "bD")
      (CONJUNCTS_THEN2 (LABEL_TAC "zbD") (CONJUNCTS_THEN2 (LABEL_TAC "ba")
        (CONJUNCTS_THEN2 (LABEL_TAC "hsbz") (LABEL_TAC "u0zb"))))))) THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;`b:A`;`zb:A`;
                  `u0:A`] HSNAME_STAGE) THEN
    ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`a:A`;`b:A`] EORDINAL_MEMBER) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  USE_THEN "mem" (MP_TAC o SPEC `z:A`) THEN
  ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `u0:A` (X_CHOOSE_THEN `w0:A`
      (CONJUNCTS_THEN2 (LABEL_TAC "u0D")
    (CONJUNCTS_THEN2 (LABEL_TAC "w0D") (CONJUNCTS_THEN2 (K ALL_TAC)
      (CONJUNCTS_THEN2 (LABEL_TAC "w0B")
       (CONJUNCTS_THEN2 (LABEL_TAC "op0") (LABEL_TAC "hsu0")))))))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`u:A`;`c:A`;`z:A`;`u0:A`;`w0:A`]
         EOPAIR_FST_DET) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC);;

(* ######################################################################### *)
(* S4 / H4 (part 1) : HS |= ZF -- EXTENSIONALITY, PAIRING, INFINITY,        *)
(* FOUNDATION, SEPARATION; union-name symmetry.                             *)
(* HS versions of the V^B axiom proofs of godel_forcing.ml: quantifiers    *)
(* over HS names, bname facts for generic V^B lemmas re-derived by         *)
(* HSNAME_BNAME, domain elements HS by                                     *)
(* HSNAME_DOM, check names HS by HS_CHECK, separation name HS by            *)
(* SEP_SYM + HS_SEPNAME (supports + HSSTAGE_INTRO in aa's own stage).       *)
(* ######################################################################### *)
(* ===================================================================== *)
(* H4.3 : BVALF_HS_EXTENSIONALITY -- [[extensionality_ax]]^HS = TOP.       *)
(* Clone of BVALF_EXTENSIONALITY; the specialisations z IN dom a0 / dom a1 *)
(* are HS names by HSNAME_DOM (the stage w stays a B-name stage).          *)
(* ===================================================================== *)
let BVALF_HS_EXTENSIONALITY = prove
 (`!D (E:A->A->bool) B leq w1 X v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
          w1 IN D /\ X IN D /\
      valuation D v /\ (!i. hsname D E B w1 X (v i))
      ==> etop D E B leq (bvalf_HS D E B leq w1 X v extensionality_ax)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER; ECBA_IMP_BALG]; ALL_TAC] THEN
  REWRITE_TAC[extensionality_ax] THEN
  MP_TAC(ISPECL [`0`; `!! 1 ((!! 2 ((2 %% 0) <-> (2 %% 1))) --> Eq 0 1)`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;`X:A`;`v:num->A`]
        BVALF_HS_ALL_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  X_GEN_TAC `a0:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((0 |-> (a0:A)) (v:num->A)) /\
                (!i. hsname D E B w1 X (((0 |-> (a0:A)) (v:num->A)) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC HSNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  MP_TAC(ISPECL [`1`; `(!! 2 ((2 %% 0) <-> (2 %% 1))) --> Eq 0 1`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;`X:A`;
        `(0 |-> (a0:A)) (v:num->A)`]
    BVALF_HS_ALL_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  X_GEN_TAC `a1:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((1 |-> (a1:A)) ((0 |-> (a0:A)) (v:num->A))) /\
                (!i. hsname D E B w1 X (((1 |-> (a1:A))
                    ((0 |-> (a0:A)) (v:num->A))) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC HSNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  ABBREV_TAC `v01 = (1 |-> (a1:A)) ((0 |-> (a0:A)) (v:num->A))` THEN
  SUBGOAL_THEN `(v01:num->A) 0 = a0 /\
      (v01:num->A) 1 = a1` STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "v01" THEN SIMP_TAC[VALMOD_OTHER; VALMOD_BASIC;
       ARITH_EQ]; ALL_TAC] THEN
  MP_TAC(ISPECL [`!! 2 ((2 %% 0) <-> (2 %% 1))`; `Eq 0 1`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;`X:A`;`v01:num->A`]
        BVALF_HS_IMP_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  ABBREV_TAC `w0 = bvalf_HS D (E:A->A->bool) B leq w1 X (v01:num->A)
      (!! 2 ((2 %% 0) <-> (2 %% 1)))` THEN
  ABBREV_TAC `zeq = bvalf_HS D (E:A->A->bool) B leq w1 X
      (v01:num->A) (Eq 0 1)` THEN
  (* zeq = [[a0=a1]] *)
  SUBGOAL_THEN `ebv_eq D (E:A->A->bool) B leq a0 a1 zeq` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`0`;`1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                   `X:A`;`v01:num->A`]
      BVALF_HS_EQ2) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* w0 IN D, E w0 B *)
  SUBGOAL_THEN `(w0:A) IN D /\ (E:A->A->bool) w0 B` STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "w0" THEN CONJ_TAC THENL
     [MP_TAC(ISPECL [`!! 2 ((2 %% 0) <-> (2 %% 1))`;`D:A->bool`;`E:A->A->bool`;
        `B:A`;`leq:A`;`w1:A`;`X:A`;`v01:num->A`] BVALF_HS_SPEC) THEN
            ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`!! 2 ((2 %% 0) <-> (2 %% 1))`;`D:A->bool`;`E:A->A->bool`;
        `B:A`;`leq:A`;`w1:A`;`X:A`;`v01:num->A`] BVALF_HS_IN_B) THEN
            ASM_SIMP_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN `(zeq:A) IN D` ASSUME_TAC THENL
   [EXPAND_TAC "zeq" THEN
    MP_TAC(ISPECL [`Eq 0 1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                   `X:A`;`v01:num->A`]
      BVALF_HS_SPEC) THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
  (* common stage for a0,a1 *)
  SUBGOAL_THEN `bname D (E:A->A->bool) B a0 /\
      bname D E B a1` STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN MATCH_MP_TAC HSNAME_BNAME THEN
    MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`a0:A`;`a1:A`]
         BNAME_DIRECTED) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `ao:A` (X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `!zt. zt IN D /\ E zt w
      ==> bname D (E:A->A->bool) B zt` ASSUME_TAC THENL
   [REPEAT STRIP_TAC THEN MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;
      `ao:A`;`w:A`;`zt:A`] BNAME_STAGE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`]
         EBVATT_EXISTS) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN EXISTS_TAC `a0:A` THEN
