       [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                       `y:A`;`a1:A`;`t0:A`;
          `iny1:A`] EBV_IN_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `erel D (E:A->A->bool) leq qy iny1` ASSUME_TAC THENL
       [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                       `ao:A`;`w:A`;`sIN:A`;
          `sEQ:A`;`y:A`;`a1:A`;`qy:A`;`iny1:A`] EBV_IN_MEMBER) THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) qy B` ASSUME_TAC THENL
       [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`a1:A`;`y:A`;`qy:A`]
          BNAME_APPLY_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `erel D (E:A->A->bool) leq impvy c` ASSUME_TAC THENL
       [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`qy:A`;`iny1:A`;
          `iny0:A`;`c:A`;`impvy:A`] EBIMP_ANT) THEN
        ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
        FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[ecba]); ALL_TAC] THEN
      SUBGOAL_THEN `(impvy:A) IN D /\ (E:A->A->bool) impvy B`
          STRIP_ASSUME_TAC THENL
       [EXPAND_TAC "impvy" THEN CONJ_TAC THENL
         [MP_TAC(ISPECL [`(2 %% 1) --> (2 %% 0)`;`D:A->bool`;`E:A->A->bool`;
                         `B:A`;`leq:A`;`w1:A`;`X:A`;
             `(2 |-> (y:A)) (v01:num->A)`] BVALF_HS_SPEC) THEN ASM_SIMP_TAC[];
          MP_TAC(ISPECL [`(2 %% 1) --> (2 %% 0)`;`D:A->bool`;`E:A->A->bool`;
                         `B:A`;`leq:A`;`w1:A`;`X:A`;
              `(2 |-> (y:A)) (v01:num->A)`] BVALF_HS_IN_B) THEN
              ASM_SIMP_TAC[]]; ALL_TAC] THEN
      SUBGOAL_THEN `(bvalf_HS D (E:A->A->bool) B leq w1 X
                     ((2 |-> (y:A)) (v01:num->A)) ((2 %% 0) <-> (2 %% 1))) IN D
          /\ (E:A->A->bool) (bvalf_HS D (E:A->A->bool) B leq w1 X
                             ((2 |-> (y:A)) (v01:num->A))
          ((2 %% 0) <-> (2 %% 1))) B` STRIP_ASSUME_TAC THENL
       [CONJ_TAC THENL
         [MP_TAC(ISPECL [`(2 %% 0) <-> (2 %% 1)`;`D:A->bool`;`E:A->A->bool`;
                         `B:A`;`leq:A`;`w1:A`;`X:A`;
             `(2 |-> (y:A)) (v01:num->A)`] BVALF_HS_SPEC) THEN ASM_SIMP_TAC[];
          MP_TAC(ISPECL [`(2 %% 0) <-> (2 %% 1)`;`D:A->bool`;`E:A->A->bool`;
                         `B:A`;`leq:A`;`w1:A`;`X:A`;
              `(2 |-> (y:A)) (v01:num->A)`] BVALF_HS_IN_B) THEN
              ASM_SIMP_TAC[]]; ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) c B` ASSUME_TAC THENL
       [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`qy:A`;`iny0:A`;
                       `c:A`] EBIMP_IN) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN
        `erel D (E:A->A->bool) leq w0 (bvalf_HS D (E:A->A->bool) B leq w1 X
            ((2 |-> (y:A)) (v01:num->A)) ((2 %% 0) <-> (2 %% 1)))`
      ASSUME_TAC THENL
       [EXPAND_TAC "w0" THEN
        MP_TAC(ISPECL [`2`;`(2 %% 0) <-> (2 %% 1)`;`D:A->bool`;
                       `E:A->A->bool`;`B:A`;
          `leq:A`;`w1:A`;`X:A`;`v01:num->A`;`y:A`] BVALF_HS_ALL_LB) THEN
              ASM_SIMP_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN
        `erel D (E:A->A->bool) leq
           (bvalf_HS D (E:A->A->bool) B leq w1 X ((2 |-> (y:A)) (v01:num->A))
            ((2 %% 0) <-> (2 %% 1)))
           impvy`
      ASSUME_TAC THENL
       [EXPAND_TAC "impvy" THEN REWRITE_TAC[Iff_DEF] THEN
        MP_TAC(ISPECL [`(2 %% 0) --> (2 %% 1)`;`(2 %% 1) -->
                       (2 %% 0)`;`D:A->bool`;
          `E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;`X:A`;
              `(2 |-> (y:A)) (v01:num->A)`] BVALF_HS_AND_LE_R) THEN
        ASM_SIMP_TAC[]; ALL_TAC] THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w0:A`;
        `bvalf_HS D (E:A->A->bool) B leq w1 X ((2 |-> (y:A)) (v01:num->A))
            ((2 %% 0) <-> (2 %% 1))`;
        `impvy:A`] EPORDER_TRANS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w0:A`;`impvy:A`;
        `c:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[]];
    DISCH_THEN ACCEPT_TAC]);;

(* ===================================================================== *)
(* H4.4 : PAIRING.  HS_UPAIRNAME_EXISTS: the pair name {<a,1>,<b,1>} of    *)
(* two HS names is HS (HS_UPN) with exactly EUPAIRNAME_EXISTS's            *)
(* interface; BVALF_HS_PAIRING: [[pairing_ax]]^HS = TOP (clone).           *)
(* ===================================================================== *)
let HS_UPAIRNAME_EXISTS = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X a b.
     hsbundle D E w1 om tw ii ci P leqp B inclB onebee X /\
     a IN D /\ b IN D /\ hsname D E B w1 X a /\ hsname D E B w1 X b
     ==> ?up top. up IN D /\ hsname D E B w1 X up /\ bname D E B up /\
                  top IN D /\ etop D E B inclB top /\
                  eapply D E up a top /\ eapply D E up b top /\
                  (!t q. t IN D /\ q IN D /\ eapply D E up t q
                   ==> t = a \/ t = b)`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "hsb")
             (CONJUNCTS_THEN2 (LABEL_TAC "aD")
              (CONJUNCTS_THEN2 (LABEL_TAC "bD")
               (CONJUNCTS_THEN2 (LABEL_TAC "hsa") (LABEL_TAC "hsbb"))))) THEN
  USE_THEN "hsb" (MP_TAC o REWRITE_RULE[hsbundle]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
             (CONJUNCTS_THEN2 (LABEL_TAC "vl")
              (CONJUNCTS_THEN2 (LABEL_TAC "eom")
               (CONJUNCTS_THEN2 (LABEL_TAC "w1D")
                (CONJUNCTS_THEN2 (LABEL_TAC "w1card")
                 (CONJUNCTS_THEN2 (LABEL_TAC "omw1e")
                  (CONJUNCTS_THEN2 (LABEL_TAC "w1min")
                   (CONJUNCTS_THEN2 (LABEL_TAC "cr1")
                    (CONJUNCTS_THEN2 (LABEL_TAC "cr2")
                     (CONJUNCTS_THEN2 (LABEL_TAC "ftw")
                      (CONJUNCTS_THEN2 (LABEL_TAC "coh")
                       (CONJUNCTS_THEN2 (LABEL_TAC "leq")
                        (CONJUNCTS_THEN2 (LABEL_TAC "ros")
                         (CONJUNCTS_THEN2 (LABEL_TAC "inc")
                          (CONJUNCTS_THEN2 (LABEL_TAC "porder")
      (CONJUNCTS_THEN2 (LABEL_TAC "top")
       (CONJUNCTS_THEN2 (LABEL_TAC "oneD")
        (CONJUNCTS_THEN2 (LABEL_TAC "BD")
         (CONJUNCTS_THEN2 (LABEL_TAC "oneB")
          (CONJUNCTS_THEN2 (LABEL_TAC "XD")
           (CONJUNCTS_THEN2 (LABEL_TAC "ciX")
            (LABEL_TAC "PX")))))))))))))))))))))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`a:A`;`b:A`;`onebee:A`]
         UPN_EXISTS) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `up:A` (CONJUNCTS_THEN2 (LABEL_TAC "upD")
      (LABEL_TAC "upch"))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;`ii:A`;`ci:A`;
                `P:A`;`leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`a:A`;`b:A`;
      `up:A`] HS_UPN) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                  DISCH_THEN(LABEL_TAC "hsup")] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B up` (LABEL_TAC "bnup") THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`up:A`;`onebee:A`] THEN
  REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THENL
   [REWRITE_TAC[eapply] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`a:A`;`onebee:A`]
           EOPAIR_EXISTS) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `z:A` (LABEL_TAC "opz")) THEN
    EXISTS_TAC `z:A` THEN CONJ_TAC THENL
        [USE_THEN "opz" ACCEPT_TAC; ALL_TAC] THEN
    USE_THEN "upch" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [USE_THEN "opz" (ACCEPT_TAC o MATCH_MP
        EOPAIR_IN); ALL_TAC] THEN
    DISCH_THEN SUBST1_TAC THEN DISJ1_TAC THEN USE_THEN "opz" ACCEPT_TAC;
    REWRITE_TAC[eapply] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`b:A`;`onebee:A`]
           EOPAIR_EXISTS) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `z:A` (LABEL_TAC "opz")) THEN
    EXISTS_TAC `z:A` THEN CONJ_TAC THENL
        [USE_THEN "opz" ACCEPT_TAC; ALL_TAC] THEN
    USE_THEN "upch" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [USE_THEN "opz" (ACCEPT_TAC o MATCH_MP
        EOPAIR_IN); ALL_TAC] THEN
    DISCH_THEN SUBST1_TAC THEN DISJ2_TAC THEN USE_THEN "opz" ACCEPT_TAC;
    MAP_EVERY X_GEN_TAC [`t:A`;`q:A`] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "tD")
               (CONJUNCTS_THEN2 (LABEL_TAC "qD")
      (MP_TAC o REWRITE_RULE[eapply]))) THEN
    DISCH_THEN(X_CHOOSE_THEN `z:A` (CONJUNCTS_THEN2 (LABEL_TAC "opz")
        (LABEL_TAC "zup"))) THEN
    SUBGOAL_THEN `(z:A) IN D` (LABEL_TAC "zD") THENL
     [USE_THEN "opz" (ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
    USE_THEN "upch" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [USE_THEN "zD" ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "zup" (MP_TAC o EQ_MP th)) THEN
    DISCH_THEN(DISJ_CASES_THEN (LABEL_TAC "opz'")) THENL
     [DISJ1_TAC THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`t:A`;`q:A`;`a:A`;`onebee:A`;
                    `z:A`] EOPAIR_INJ) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN(ACCEPT_TAC o CONJUNCT1)];
      DISJ2_TAC THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`t:A`;`q:A`;`b:A`;`onebee:A`;
                    `z:A`] EOPAIR_INJ) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN(ACCEPT_TAC o CONJUNCT1)]]]);;

let BVALF_HS_PAIRING = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X v.
      hsbundle D E w1 om tw ii ci P leqp B inclB onebee X /\
      valuation D v /\ (!i. hsname D E B w1 X (v i))
      ==> etop D E B inclB (bvalf_HS D E B inclB w1 X v pairing_ax)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_ASSUM(fun th -> let cs = CONJUNCTS(REWRITE_RULE[hsbundle] th)
                        and cb = CONJUNCTS(MATCH_MP HSB_CBA th) in
    MAP_EVERY ASSUME_TAC [el 0 cs; el 1 cs; el 3 cs; el 17 cs; el 19 cs;
                          el 0 cb; el 1 cb]) THEN
  REWRITE_TAC[pairing_ax] THEN
  MP_TAC(ISPECL [`0`; `!! 1 (?? 2 (!! 3 ((3 %% 2) <-> Eq 3 0 || Eq 3 1)))`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;`X:A`;`v:num->A`]
        BVALF_HS_ALL_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  X_GEN_TAC `a0:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((0 |-> (a0:A)) (v:num->A)) /\
                (!i. hsname D E B w1 X (((0 |-> (a0:A)) (v:num->A)) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC HSNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  MP_TAC(ISPECL [`1`; `?? 2 (!! 3 ((3 %% 2) <-> Eq 3 0 || Eq 3 1))`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;`X:A`;
        `(0 |-> (a0:A)) (v:num->A)`] BVALF_HS_ALL_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  X_GEN_TAC `a1:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((1 |-> (a1:A)) ((0 |-> (a0:A)) (v:num->A))) /\
                (!i. hsname D E B w1 X (((1 |-> (a1:A))
                    ((0 |-> (a0:A)) (v:num->A))) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC HSNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  ABBREV_TAC `v01 = (1 |-> (a1:A)) ((0 |-> (a0:A)) (v:num->A))` THEN
  (* witness: the pair-name of a0,a1 *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;`ii:A`;`ci:A`;
                 `P:A`;`leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`a0:A`;`a1:A`]
      HS_UPAIRNAME_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `up:A` (X_CHOOSE_THEN `top:A` STRIP_ASSUME_TAC)) THEN
  MATCH_MP_TAC(ISPECL [`2`; `!! 3 ((3 %% 2) <-> Eq 3 0 || Eq 3 1)`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;`X:A`;`v01:num->A`;`up:A`]
        BVALF_HS_EX_TOP) THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `valuation D ((2 |-> (up:A)) (v01:num->A)) /\
                (!i. hsname D E B w1 X (((2 |-> (up:A)) (v01:num->A)) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC HSNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  MP_TAC(ISPECL [`3`; `(3 %% 2) <-> Eq 3 0 || Eq 3 1`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;`X:A`;
        `(2 |-> (up:A)) (v01:num->A)`] BVALF_HS_ALL_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  X_GEN_TAC `w:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((3 |-> (w:A)) ((2 |-> (up:A)) (v01:num->A))) /\
                (!i. hsname D E B w1 X (((3 |-> (w:A))
                    ((2 |-> (up:A)) (v01:num->A))) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC HSNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  ABBREV_TAC `vv = (3 |-> (w:A)) ((2 |-> (up:A)) (v01:num->A))` THEN
  SUBGOAL_THEN `(vv:num->A) 0 = a0 /\ (vv:num->A) 1 = a1 /\
      (vv:num->A) 2 = up /\ (vv:num->A) 3 = w`
  STRIP_ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["vv";"v01"] THEN
    SIMP_TAC[VALMOD_OTHER; VALMOD_BASIC; ARITH_EQ]; ALL_TAC] THEN
  MP_TAC(ISPECL [`3 %% 2`; `Eq 3 0 || Eq 3 1`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;`X:A`;`vv:num->A`]
        BVALF_HS_IFF_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  (* now goal: bvalf_HS vv (3%%2) = bvalf_HS vv (Eq 3 0 || Eq 3 1) *)
  ABBREV_TAC `zin = bvalf_HS D (E:A->A->bool) B inclB w1 X
      (vv:num->A) (3 %% 2)` THEN
  ABBREV_TAC `za = bvalf_HS D (E:A->A->bool) B inclB w1 X
      (vv:num->A) (Eq 3 0)` THEN
  ABBREV_TAC `zb = bvalf_HS D (E:A->A->bool) B inclB w1 X
      (vv:num->A) (Eq 3 1)` THEN
  ABBREV_TAC `zj = bvalf_HS D (E:A->A->bool) B inclB w1 X (vv:num->A)
      (Eq 3 0 || Eq 3 1)` THEN
  SUBGOAL_THEN `ebv_in D (E:A->A->bool) B inclB w up zin` ASSUME_TAC THENL
   [EXPAND_TAC "zin" THEN
    MP_TAC(ISPECL [`3`;`2`;`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;
                   `X:A`;`vv:num->A`] BVALF_HS_MEM) THEN
    ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `ebv_eq D (E:A->A->bool) B inclB w a0 za` ASSUME_TAC THENL
   [EXPAND_TAC "za" THEN
    MP_TAC(ISPECL [`3`;`0`;`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;
                   `X:A`;`vv:num->A`] BVALF_HS_EQ2) THEN
    ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `ebv_eq D (E:A->A->bool) B inclB w a1 zb` ASSUME_TAC THENL
   [EXPAND_TAC "zb" THEN
    MP_TAC(ISPECL [`3`;`1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;
                   `X:A`;`vv:num->A`] BVALF_HS_EQ2) THEN
    ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `ejoin D (E:A->A->bool) B inclB za zb zj` ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["za";"zb";"zj"] THEN
    MP_TAC(ISPECL [`Eq 3 0`;`Eq 3 1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;
                   `w1:A`;`X:A`;`vv:num->A`] BVALF_HS_OR) THEN
    ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(zin:A) IN D` ASSUME_TAC THENL
   [EXPAND_TAC "zin" THEN
    MP_TAC(ISPECL [`3 %% 2`;`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;
                   `X:A`;`vv:num->A`] BVALF_HS_SPEC) THEN
        ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(za:A) IN D` ASSUME_TAC THENL
   [EXPAND_TAC "za" THEN
    MP_TAC(ISPECL [`Eq 3 0`;`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;
                   `X:A`;`vv:num->A`] BVALF_HS_SPEC) THEN
        ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(zb:A) IN D` ASSUME_TAC THENL
   [EXPAND_TAC "zb" THEN
    MP_TAC(ISPECL [`Eq 3 1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;
                   `X:A`;`vv:num->A`] BVALF_HS_SPEC) THEN
        ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B a0 /\ bname D E B a1 /\ bname D E B w`
    STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THEN MATCH_MP_TAC HSNAME_BNAME THEN
    MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`a0:A`;
                 `a1:A`;`up:A`;`top:A`;
    `w:A`;`zin:A`;`za:A`;`zb:A`;`zj:A`] EBV_IN_UPAIR) THEN
  ASM_REWRITE_TAC[]);;

(* H4.5 : BVALF_HS_AND_MEET (clone): [[p && q]]^HS is the meet. *)
let BVALF_HS_AND_MEET = prove
 (`!p q D (E:A->A->bool) B leq w1 X v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
          w1 IN D /\ X IN D /\
      valuation D v /\ (!i. hsname D E B w1 X (v i))
      ==> emeet D E B leq (bvalf_HS D E B leq w1 X v p)
          (bvalf_HS D E B leq w1 X v q)
                          (bvalf_HS D E B leq w1 X v (p && q))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(bvalf_HS D (E:A->A->bool) B leq w1 X v p) IN D /\
                (E:A->A->bool) (bvalf_HS D E B leq w1 X v p) B`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                     `X:A`;`v:num->A`] BVALF_HS_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                     `X:A`;`v:num->A`] BVALF_HS_IN_B) THEN
          ASM_SIMP_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN `(bvalf_HS D (E:A->A->bool) B leq w1 X v q) IN D /\
                (E:A->A->bool) (bvalf_HS D E B leq w1 X v q) B`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL [`q:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                     `X:A`;`v:num->A`] BVALF_HS_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`q:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                     `X:A`;`v:num->A`] BVALF_HS_IN_B) THEN
          ASM_SIMP_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN `(bvalf_HS D (E:A->A->bool) B leq w1 X v (p && q)) IN D /\
                (E:A->A->bool) (bvalf_HS D E B leq w1 X v (p && q)) B`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL [`p && q`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                     `X:A`;`v:num->A`] BVALF_HS_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`p && q`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                     `X:A`;`v:num->A`] BVALF_HS_IN_B) THEN
          ASM_SIMP_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN `(bvalf_HS D (E:A->A->bool) B leq w1 X v (p --> Not q)) IN D /\
                (E:A->A->bool) (bvalf_HS D E B leq w1 X v (p --> Not q)) B`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL [`p --> Not q`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                     `w1:A`;`X:A`;`v:num->A`] BVALF_HS_SPEC) THEN
         ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`p --> Not q`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                     `w1:A`;`X:A`;`v:num->A`] BVALF_HS_IN_B) THEN
          ASM_SIMP_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq (bvalf_HS D E B leq w1 X v (p && q))
      (bvalf_HS D E B leq w1 X v p)` ASSUME_TAC THENL
   [MATCH_MP_TAC BVALF_HS_AND_LE_L THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq (bvalf_HS D E B leq w1 X v (p && q))
      (bvalf_HS D E B leq w1 X v q)` ASSUME_TAC THENL
   [MATCH_MP_TAC BVALF_HS_AND_LE_R THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `ecompl D (E:A->A->bool) B leq (bvalf_HS D E B leq w1 X v q)
      (bvalf_HS D E B leq w1 X v (Not q))` ASSUME_TAC THENL
   [MATCH_MP_TAC BVALF_HS_NOT THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `ecompl D (E:A->A->bool) B leq
      (bvalf_HS D E B leq w1 X v (p --> Not q))
      (bvalf_HS D E B leq w1 X v (Not(p --> Not q)))` ASSUME_TAC THENL
   [MATCH_MP_TAC BVALF_HS_NOT THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`p:form`;`Not q`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                 `w1:A`;`X:A`;`v:num->A`] BVALF_HS_IMP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[ebimp] THEN
  DISCH_THEN(X_CHOOSE_THEN `c:A` STRIP_ASSUME_TAC) THEN
  REWRITE_TAC[emeet] THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `w:A` THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`]
         EBALG_COMPL) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `cw:A`) THEN
  SUBGOAL_THEN `(cw:A) IN D /\ (E:A->A->bool) cw B` STRIP_ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP ECOMPL_IN); ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq c cw` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;
      `bvalf_HS D (E:A->A->bool) B leq w1 X v p`;`cw:A`;`c:A`]
          ECOMPL_ANTITONE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq (bvalf_HS D E B leq w1 X v (Not q))
      cw` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;
      `bvalf_HS D (E:A->A->bool) B leq w1 X v q`;`cw:A`;
          `bvalf_HS D (E:A->A->bool) B leq w1 X v (Not q)`]
          ECOMPL_ANTITONE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq
      (bvalf_HS D E B leq w1 X v (p --> Not q)) cw` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;
      `bvalf_HS D (E:A->A->bool) B leq w1 X v (Not q)`;
          `bvalf_HS D (E:A->A->bool) B leq w1 X v (p --> Not q)`;`cw:A`]
          EJOIN_LEAST) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `ecompl D (E:A->A->bool) B leq cw w` ASSUME_TAC THENL
   [MATCH_MP_TAC ECOMPL_SYM THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `bvalf_HS D (E:A->A->bool) B leq w1 X v (p && q) =
                bvalf_HS D E B leq w1 X v (Not(p --> Not q))`
  (fun th -> REWRITE_TAC[th]) THENL [REWRITE_TAC[And_DEF]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
    `bvalf_HS D (E:A->A->bool) B leq w1 X v (p --> Not q)`;`cw:A`;
    `bvalf_HS D (E:A->A->bool) B leq w1 X v (Not(p --> Not q))`;`w:A`]
        ECOMPL_ANTITONE) THEN
  ASM_REWRITE_TAC[]);;

(* ===================================================================== *)
(* H4.6 : INFINITY.  Clones of INF_SUCC_PERB / INF_SUCC_PERC /             *)
(* BVALF_INF_SUCC / BVALF_INF_EMPTY / BVALF_INFINITY; check names are HS   *)
(* (HS_CHECK, hence the hsbundle hypothesis on the three builders);        *)
(* bname facts for generic V^B lemmas re-derived by HSNAME_BNAME.          *)
(* ===================================================================== *)
let INF_SUCC_PERB_HS = prove
 (`!D (E:A->A->bool) B leq w1 X onebee a b c sc cv scv eac w.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
          w1 IN D /\ X IN D /\
      onebee IN D /\ E onebee B /\ etop D E B leq onebee /\
      a IN D /\ hsname D E B w1 X a /\ b IN D /\ hsname D E B w1 X b /\
      c IN D /\ sc IN D /\ esuc D E c sc /\
      echeck D E onebee c cv /\ echeck D E onebee sc scv /\
      cv IN D /\ scv IN D /\ hsname D E B w1 X cv /\ hsname D E B w1 X scv /\
      eac IN D /\ ebv_eq D E B leq a cv eac /\
      valuation D w /\ (!i. hsname D E B w1 X (w i)) /\
      w 1 = a /\ w 2 = scv /\ w 3 = b
      ==> erel D E leq eac
            (bvalf_HS D E B leq w1 X w ((3 %% 2) <-> (3 %% 1) || Eq 3 1))`,
  let insimp p =
    MP_TAC(ISPECL [p;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                   `X:A`;`w:num->A`]
                  BVALF_HS_SPEC) THEN ASM_SIMP_TAC[] in
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (a:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (b:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (cv:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (scv:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `!i:num. bname D (E:A->A->bool) B (((w):num->A) i)`
      ASSUME_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC HSNAME_BNAME THEN
    MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[valuation]; ALL_TAC]) THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  (* successor characterization  E dd sc <=> E dd c \/ dd = c *)
  SUBGOAL_THEN `!dd:A. dd IN D ==> ((E:A->A->bool) dd sc <=> E dd c \/ dd = c)`
  ASSUME_TAC THENL
   [UNDISCH_TAC `esuc D (E:A->A->bool) c sc` THEN ASM_SIMP_TAC[ESUC_ALT] THEN
    STRIP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* atomic Boolean values, folded to b,a,scv via w 1=a,w 2=scv,w 3=b *)
  MP_TAC(ISPECL [`3`;`2`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                 `X:A`;`w:num->A`]
    BVALF_HS_MEM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN ASM_REWRITE_TAC[] THEN
  DISCH_TAC THEN
  MP_TAC(ISPECL [`3`;`1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                 `X:A`;`w:num->A`]
    BVALF_HS_MEM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN ASM_REWRITE_TAC[] THEN
  DISCH_TAC THEN
  MP_TAC(ISPECL [`3`;`1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                 `X:A`;`w:num->A`]
    BVALF_HS_EQ2) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN ASM_REWRITE_TAC[] THEN
  DISCH_TAC THEN
  MP_TAC(ISPECL [`3 %% 1`;`Eq 3 1`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                 `leq:A`;`w1:A`;`X:A`;
    `w:num->A`] BVALF_HS_OR) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`3 %% 2`;`(3 %% 1) || Eq 3 1`;`D:A->bool`;`E:A->A->bool`;`B:A`;
    `leq:A`;`w1:A`;`X:A`;`w:num->A`] BVALF_HS_IMP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`(3 %% 1) || Eq 3 1`;`3 %% 2`;`D:A->bool`;`E:A->A->bool`;`B:A`;
    `leq:A`;`w1:A`;`X:A`;`w:num->A`] BVALF_HS_IMP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`(3 %% 2) --> (3 %% 1) || Eq 3 1`;
    `((3 %% 1) || Eq 3 1) --> (3 %% 2)`;`D:A->bool`;`E:A->A->bool`;`B:A`;
    `leq:A`;`w1:A`;`X:A`;`w:num->A`] BVALF_HS_AND_MEET) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
  (* zbc = [[b IN cv]], ebcv = [[b = cv]] *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`b:A`;`cv:A`]
    EBV_IN_VAL_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `zbc:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`b:A`;`cv:A`]
    EBV_EQ_VAL_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ebcv:A` STRIP_ASSUME_TAC) THEN
  (* j0 = zbc \/ ebcv *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zbc:A`;`ebcv:A`]
    EBALG_JOIN) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `j0:A`) THEN
  SUBGOAL_THEN `(j0:A) IN D /\ (E:A->A->bool) j0 B` STRIP_ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EJOIN_IN); ALL_TAC] THEN
  (* IN D for all the bvalf_HS values -- MUST precede the successor equation,
     since ECHECK_IN_SUCC requires z IN D = bvalf_HS w (3 %% 2) IN D *)
  SUBGOAL_THEN
   `(bvalf_HS D (E:A->A->bool) B leq w1 X w (3 %% 2)) IN D /\
    (bvalf_HS D (E:A->A->bool) B leq w1 X w (3 %% 1)) IN D /\
    (bvalf_HS D (E:A->A->bool) B leq w1 X w (Eq 3 1)) IN D /\
    (bvalf_HS D (E:A->A->bool) B leq w1 X w ((3 %% 1) || Eq 3 1)) IN D /\
    (bvalf_HS D (E:A->A->bool) B leq w1 X w
     ((3 %% 2) --> (3 %% 1) || Eq 3 1)) IN D /\
    (bvalf_HS D (E:A->A->bool) B leq w1 X w
     (((3 %% 1) || Eq 3 1) --> (3 %% 2))) IN D /\
    (bvalf_HS D (E:A->A->bool) B leq w1 X w
       (((3 %% 2) --> (3 %% 1) || Eq 3 1) &&
        (((3 %% 1) || Eq 3 1) --> (3 %% 2)))) IN D`
   STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THENL
     [insimp `3 %% 2`; insimp `3 %% 1`; insimp `Eq 3 1`;
      insimp `(3 %% 1) || Eq 3 1`;
      insimp `(3 %% 2) --> (3 %% 1) || Eq 3 1`;
      insimp `((3 %% 1) || Eq 3 1) --> (3 %% 2)`;
      insimp `((3 %% 2) --> (3 %% 1) || Eq 3 1) &&
              (((3 %% 1) || Eq 3 1) --> (3 %% 2))`];
    ALL_TAC] THEN
  (* successor value equation  [[b IN sc^]] = j0 *)
  SUBGOAL_THEN `(bvalf_HS D (E:A->A->bool) B leq w1 X w (3 %% 2)) = j0`
      ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
      `c:A`;`cv:A`;`sc:A`;`scv:A`;`b:A`;
      `bvalf_HS D (E:A->A->bool) B leq w1 X w (3 %% 2)`;`zbc:A`;`ebcv:A`;`j0:A`]
      ECHECK_IN_SUCC) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `ejoin D (E:A->A->bool) B leq zbc ebcv (bvalf_HS D E B leq w1 X w (3 %% 2))`
  ASSUME_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* assemble via EBV_SUCC_BICOND *)
  REWRITE_TAC[Iff_DEF] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
    `a:A`;`b:A`;`cv:A`;`scv:A`;`eac:A`;
    `bvalf_HS D (E:A->A->bool) B leq w1 X w (3 %% 2)`;`zbc:A`;`ebcv:A`;
    `bvalf_HS D (E:A->A->bool) B leq w1 X w (3 %% 1)`;
    `bvalf_HS D (E:A->A->bool) B leq w1 X w (Eq 3 1)`;
    `bvalf_HS D (E:A->A->bool) B leq w1 X w ((3 %% 1) || Eq 3 1)`;
    `bvalf_HS D (E:A->A->bool) B leq w1 X w ((3 %% 2) --> (3 %% 1) || Eq 3 1)`;
    `bvalf_HS D (E:A->A->bool) B leq w1 X w
        (((3 %% 1) || Eq 3 1) --> (3 %% 2))`;
    `bvalf_HS D (E:A->A->bool) B leq w1 X w
       (((3 %% 2) --> (3 %% 1) || Eq 3 1) &&
        (((3 %% 1) || Eq 3 1) --> (3 %% 2)))`]
    EBV_SUCC_BICOND) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]);;

let INF_SUCC_PERC_HS = prove
 (`!D (E:A->A->bool) B leq w1 X onebee om vom a c sc cv scv eac u.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
          w1 IN D /\ X IN D /\
      onebee IN D /\ E onebee B /\ etop D E B leq onebee /\
      eomega D E om /\ echeck D E onebee om vom /\
      a IN D /\ hsname D E B w1 X a /\
      c IN D /\ E c om /\ esuc D E c sc /\
      echeck D E onebee c cv /\ echeck D E onebee sc scv /\
      cv IN D /\ scv IN D /\ hsname D E B w1 X cv /\ hsname D E B w1 X scv /\
      eac IN D /\ ebv_eq D E B leq a cv eac /\
      valuation D u /\ (!i. hsname D E B w1 X (u i)) /\ u 0 = vom /\ u 1 = a
      ==> erel D E leq eac
            (bvalf_HS D E B leq w1 X u (??- 2 0
                (!! 3 ((3 %% 2) <-> (3 %% 1) || Eq 3 1))))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (a:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (cv:A)` ASSUME_TAC THENL
