      MP_TAC(ISPECL [`(2 %% 0) && (!! 3 ((3 %% 2) <-> (3 %% 1) || Eq 3 1))`;
        `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;`X:A`;
            `(2 |-> (scv:A)) u`] BVALF_HS_IN_B) THEN
      ASM_SIMP_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN
    `erel D (E:A->A->bool) leq eac
       (bvalf_HS D E B leq w1 X ((2 |-> scv) u)
          ((2 %% 0) && (!! 3 ((3 %% 2) <-> (3 %% 1) || Eq 3 1))))`
  ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `bvalf_HS D (E:A->A->bool) B leq w1 X ((2 |-> scv) u) (2 %% 0)`;
      `bvalf_HS D (E:A->A->bool) B leq w1 X ((2 |-> scv) u)
         (!! 3 ((3 %% 2) <-> (3 %% 1) || Eq 3 1))`;
      `bvalf_HS D (E:A->A->bool) B leq w1 X ((2 |-> scv) u)
         ((2 %% 0) && (!! 3 ((3 %% 2) <-> (3 %% 1) || Eq 3 1)))`;
