let BVALF_HS_INF_SUCC = prove
 (`!D (E:A->A->bool) B leq w1 X onebee om vom v tw ii ci P leqp.
      hsbundle D E w1 om tw ii ci P leqp B leq onebee X /\ model D E ZF_AX /\
          ecba D E B leq /\ B IN D /\ leq IN D /\ w1 IN D /\ X IN D /\
      onebee IN D /\ E onebee B /\ etop D E B leq onebee /\
      (!u. u IN D ==> elmem D E u) /\
      eomega D E om /\ echeck D E onebee om vom /\
      valuation D v /\ (!i. hsname D E B w1 X (v i)) /\ v 0 = vom
      ==> etop D E B leq
            (bvalf_HS D E B leq w1 X v
               (!!- 1 0 (??- 2 0 (!! 3 ((3 %% 2) <-> (3 %% 1) || Eq 3 1)))))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  TRY(SUBGOAL_THEN `!i:num. bname D (E:A->A->bool) B (((v):num->A) i)`
      ASSUME_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC HSNAME_BNAME THEN
    MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[valuation]; ALL_TAC]) THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  MP_TAC(ISPECL [`1`;`0`;`??- 2 0 (!! 3 ((3 %% 2) <-> (3 %% 1) || Eq 3 1))`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;`X:A`;`v:num->A`]
        BVALF_HS_FORALLMEM_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  X_GEN_TAC `a:A` THEN STRIP_TAC THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (a:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  
  SUBGOAL_THEN `valuation D ((1 |-> (a:A)) v) /\
                (!i. hsname D E B w1 X (((1 |-> (a:A)) v) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC HSNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  TRY(SUBGOAL_THEN `!i:num. bname D (E:A->A->bool) B
      ((((1 |-> (a:A)) v):num->A) i)` ASSUME_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC HSNAME_BNAME THEN
    MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[valuation]; ALL_TAC]) THEN
  SUBGOAL_THEN `((1 |-> (a:A)) v) 0 = vom /\ ((1 |-> (a:A)) v) 1 = a`
  STRIP_ASSUME_TAC THENL
   [ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
  SUBGOAL_THEN
    `ebv_in D (E:A->A->bool) B leq a vom
        (bvalf_HS D E B leq w1 X ((1 |-> a) v) (1 %% 0))`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL [`1`;`0`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                   `X:A`;`(1 |-> (a:A)) v`]
      BVALF_HS_MEM) THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(bvalf_HS D (E:A->A->bool) B leq w1 X ((1 |-> a) v)
                 (1 %% 0)) IN D`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL [`1 %% 0`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                   `X:A`;`(1 |-> (a:A)) v`]
      BVALF_HS_SPEC) THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `(bvalf_HS D (E:A->A->bool) B leq w1 X ((1 |-> a) v)
        (??- 2 0 (!! 3 ((3 %% 2) <-> (3 %% 1) || Eq 3 1)))) IN D /\
     (E:A->A->bool) (bvalf_HS D E B leq w1 X ((1 |-> a) v)
        (??- 2 0 (!! 3 ((3 %% 2) <-> (3 %% 1) || Eq 3 1)))) B`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL [`??- 2 0 (!! 3 ((3 %% 2) <-> (3 %% 1) || Eq 3 1))`;
        `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;`X:A`;`(1 |-> (a:A)) v`]
            BVALF_HS_SPEC) THEN
      ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`??- 2 0 (!! 3 ((3 %% 2) <-> (3 %% 1) || Eq 3 1))`;
        `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;`X:A`;`(1 |-> (a:A)) v`]
            BVALF_HS_IN_B) THEN
      ASM_SIMP_TAC[]]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                       `onebee:A`;`om:A`;`vom:A`;
    `a:A`;
    `bvalf_HS D (E:A->A->bool) B leq w1 X ((1 |-> a) v) (1 %% 0)`;
    `bvalf_HS D (E:A->A->bool) B leq w1 X ((1 |-> a) v)
       (??- 2 0 (!! 3 ((3 %% 2) <-> (3 %% 1) || Eq 3 1)))`]
    ECHECK_IN_LE_SUP) THEN
  ASM_REWRITE_TAC[] THEN
  MAP_EVERY X_GEN_TAC [`c:A`;`vc:A`;`ec:A`] THEN STRIP_TAC THEN
  SUBGOAL_THEN `c IN D /\ (vc:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  SUBGOAL_THEN `hsname D (E:A->A->bool) B w1 X vc` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;
                         `ii:A`;`ci:A`;`P:A`;
      `leqp:A`;`B:A`;`leq:A`;`onebee:A`;`X:A`;`c:A`;`vc:A`] HS_CHECK) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (vc:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  SUBGOAL_THEN `?sc:A. esuc D (E:A->A->bool) c sc` (X_CHOOSE_TAC `sc:A`) THENL
   [MATCH_MP_TAC ESUC_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(sc:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `?scv:A. echeck D (E:A->A->bool) onebee sc scv`
      (X_CHOOSE_TAC `scv:A`) THENL
   [MATCH_MP_TAC ECHECK_EXHAUSTION THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(scv:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  SUBGOAL_THEN `hsname D (E:A->A->bool) B w1 X scv` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;
                         `ii:A`;`ci:A`;`P:A`;
      `leqp:A`;`B:A`;`leq:A`;`onebee:A`;`X:A`;`sc:A`;`scv:A`] HS_CHECK) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (scv:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;`X:A`;
                       `onebee:A`;`om:A`;`vom:A`;
    `a:A`;`c:A`;`sc:A`;`vc:A`;`scv:A`;`ec:A`;`(1 |-> (a:A)) v`]
        INF_SUCC_PERC_HS) THEN
  ASM_REWRITE_TAC[]);;

let BVALF_HS_INF_EMPTY = prove
 (`!D (E:A->A->bool) B leq w1 X onebee om vom v tw ii ci P leqp.
      hsbundle D E w1 om tw ii ci P leqp B leq onebee X /\ model D E ZF_AX /\
          ecba D E B leq /\ B IN D /\ leq IN D /\ w1 IN D /\ X IN D /\
      onebee IN D /\ E onebee B /\ etop D E B leq onebee /\
      (!u. u IN D ==> elmem D E u) /\
      eomega D E om /\ echeck D E onebee om vom /\
      valuation D v /\ (!i. hsname D E B w1 X (v i)) /\ v 0 = vom
      ==> etop D E B leq
            (bvalf_HS D E B leq w1 X v (??- 1 0 (!! 2 (Not(2 %% 1)))))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  TRY(SUBGOAL_THEN `!i:num. bname D (E:A->A->bool) B (((v):num->A) i)`
      ASSUME_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC HSNAME_BNAME THEN
    MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[valuation]; ALL_TAC]) THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `?emp:A. eempty D (E:A->A->bool) emp`
      (X_CHOOSE_TAC `emp:A`) THENL
   [MATCH_MP_TAC EEMPTY_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(emp:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EEMPTY_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `!c:A. c IN D ==> ~((E:A->A->bool) c emp)` ASSUME_TAC THENL
   [ASM_MESON_TAC[eempty]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) emp om` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`om:A`;`emp:A`]
                 EOMEGA_EMPTY) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `?vemp:A. echeck D (E:A->A->bool) onebee emp vemp`
      (X_CHOOSE_TAC `vemp:A`) THENL
   [MATCH_MP_TAC ECHECK_EXHAUSTION THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(vemp:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  SUBGOAL_THEN `hsname D (E:A->A->bool) B w1 X vemp` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;
                         `ii:A`;`ci:A`;`P:A`;
      `leqp:A`;`B:A`;`leq:A`;`onebee:A`;`X:A`;`emp:A`;`vemp:A`] HS_CHECK) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (vemp:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  SUBGOAL_THEN `valuation D ((1 |-> (vemp:A)) v) /\
                (!i. hsname D E B w1 X (((1 |-> (vemp:A)) v) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC HSNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  TRY(SUBGOAL_THEN `!i:num. bname D (E:A->A->bool) B
      ((((1 |-> (vemp:A)) v):num->A) i)` ASSUME_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC HSNAME_BNAME THEN
    MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[valuation]; ALL_TAC]) THEN
  SUBGOAL_THEN `((1 |-> (vemp:A)) v) 0 = vom /\ ((1 |-> (vemp:A)) v) 1 = vemp`
  STRIP_ASSUME_TAC THENL
   [ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`1`;`0`;`!! 2 (Not(2 %% 1))`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;`X:A`;`v:num->A`;`vemp:A`]
    BVALF_HS_EXISTSMEM_TOP) THEN
  ASM_REWRITE_TAC[] THEN
  CONJ_TAC THENL
   [SUBGOAL_THEN
      `ebv_in D (E:A->A->bool) B leq vemp vom
          (bvalf_HS D E B leq w1 X ((1 |-> vemp) v) (1 %% 0))`
    ASSUME_TAC THENL
     [MP_TAC(ISPECL [`1`;`0`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                     `X:A`;`(1 |-> (vemp:A)) v`]
        BVALF_HS_MEM) THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(bvalf_HS D (E:A->A->bool) B leq w1 X ((1 |-> vemp) v)
                   (1 %% 0)) IN D`
    ASSUME_TAC THENL
     [MP_TAC(ISPECL [`1 %% 0`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                     `X:A`;`(1 |-> (vemp:A)) v`]
        BVALF_HS_SPEC) THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                         `onebee:A`;`emp:A`;`om:A`;
      `vemp:A`;`vom:A`;`bvalf_HS D (E:A->A->bool) B leq w1 X
          ((1 |-> vemp) v) (1 %% 0)`]
      ECHECK_IN_TOP) THEN ASM_REWRITE_TAC[];
    MP_TAC(ISPECL [`2`;`Not(2 %% 1)`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                   `leq:A`;`w1:A`;`X:A`;
      `(1 |-> (vemp:A)) v`] BVALF_HS_ALL_TOP) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    X_GEN_TAC `bb:A` THEN STRIP_TAC THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (bb:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  
    SUBGOAL_THEN `valuation D ((2 |-> (bb:A)) ((1 |-> vemp) v)) /\
                  (!i. hsname D E B w1 X (((2 |-> (bb:A)) ((1 |-> vemp) v)) i))`
    STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC HSNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
    TRY(SUBGOAL_THEN `!i:num. bname D (E:A->A->bool) B
        ((((2 |-> (bb:A)) ((1 |-> vemp) v)):num->A) i)` ASSUME_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC HSNAME_BNAME THEN
    MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[valuation]; ALL_TAC]) THEN
  SUBGOAL_THEN `((2 |-> (bb:A)) ((1 |-> vemp) v)) 1 = vemp /\
                  ((2 |-> (bb:A)) ((1 |-> vemp) v)) 2 = bb`
    STRIP_ASSUME_TAC THENL
     [ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
    MP_TAC(ISPECL [`2 %% 1`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                   `leq:A`;`w1:A`;`X:A`;
      `(2 |-> (bb:A)) ((1 |-> vemp) v)`] BVALF_HS_NOT_TOP) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    SUBGOAL_THEN
      `ebv_in D (E:A->A->bool) B leq bb vemp
         (bvalf_HS D E B leq w1 X ((2 |-> bb) ((1 |-> vemp) v)) (2 %% 1))`
    ASSUME_TAC THENL
     [MP_TAC(ISPECL [`2`;`1`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                     `leq:A`;`w1:A`;`X:A`;
        `(2 |-> (bb:A)) ((1 |-> vemp) v)`] BVALF_HS_MEM) THEN
            ASM_SIMP_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(bvalf_HS D (E:A->A->bool) B leq w1 X
                   ((2 |-> bb) ((1 |-> vemp) v)) (2 %% 1)) IN D`
    ASSUME_TAC THENL
     [MP_TAC(ISPECL [`2 %% 1`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                     `leq:A`;`w1:A`;`X:A`;
        `(2 |-> (bb:A)) ((1 |-> vemp) v)`] BVALF_HS_SPEC) THEN
            ASM_SIMP_TAC[]; ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
                         `emp:A`;`vemp:A`;
      `bb:A`;`bvalf_HS D (E:A->A->bool) B leq w1 X
          ((2 |-> bb) ((1 |-> vemp) v)) (2 %% 1)`]
      ECHECK_IN_EMPTY) THEN ASM_REWRITE_TAC[]]);;

let BVALF_HS_INFINITY = prove
 (`!D (E:A->A->bool) B leq w1 X onebee om vom v tw ii ci P leqp.
      hsbundle D E w1 om tw ii ci P leqp B leq onebee X /\ model D E ZF_AX /\
          ecba D E B leq /\ B IN D /\ leq IN D /\ w1 IN D /\ X IN D /\
      onebee IN D /\ E onebee B /\ etop D E B leq onebee /\
      (!u. u IN D ==> elmem D E u) /\
      eomega D E om /\ echeck D E onebee om vom /\
      valuation D v /\ (!i. hsname D E B w1 X (v i))
      ==> etop D E B leq (bvalf_HS D E B leq w1 X v infinity_ax)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  TRY(SUBGOAL_THEN `!i:num. bname D (E:A->A->bool) B (((v):num->A) i)`
      ASSUME_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC HSNAME_BNAME THEN
    MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[valuation]; ALL_TAC]) THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(om:A) IN D /\ (vom:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  SUBGOAL_THEN `hsname D (E:A->A->bool) B w1 X vom` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;
                         `ii:A`;`ci:A`;`P:A`;
      `leqp:A`;`B:A`;`leq:A`;`onebee:A`;`X:A`;`om:A`;`vom:A`] HS_CHECK) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (vom:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  REWRITE_TAC[infinity_ax] THEN
  MATCH_MP_TAC(ISPECL [`0`;
    `(??- 1 0 (!! 2 (Not(2 %% 1)))) &&
     (!!- 1 0 (??- 2 0 (!! 3 ((3 %% 2) <-> (3 %% 1) || Eq 3 1))))`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;`X:A`;`v:num->A`;`vom:A`]
    BVALF_HS_EX_TOP) THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `valuation D ((0 |-> (vom:A)) v) /\
                (!i. hsname D E B w1 X (((0 |-> (vom:A)) v) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC HSNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  TRY(SUBGOAL_THEN `!i:num. bname D (E:A->A->bool) B
      ((((0 |-> (vom:A)) v):num->A) i)` ASSUME_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC HSNAME_BNAME THEN
    MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[valuation]; ALL_TAC]) THEN
  SUBGOAL_THEN `((0 |-> (vom:A)) v) 0 = vom`
  ASSUME_TAC THENL
   [ASM_SIMP_TAC[VALMOD_BASIC]; ALL_TAC] THEN
  MP_TAC(ISPECL [`??- 1 0 (!! 2 (Not(2 %% 1)))`;
    `!!- 1 0 (??- 2 0 (!! 3 ((3 %% 2) <-> (3 %% 1) || Eq 3 1)))`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;`X:A`;`(0 |-> (vom:A)) v`]
        BVALF_HS_AND_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;`X:A`;
                         `onebee:A`;`om:A`;`vom:A`;
      `(0 |-> (vom:A)) v`;`tw:A`;`ii:A`;`ci:A`;`P:A`;`leqp:A`]
          BVALF_HS_INF_EMPTY) THEN
    ASM_REWRITE_TAC[];
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;`X:A`;
                         `onebee:A`;`om:A`;`vom:A`;
      `(0 |-> (vom:A)) v`;`tw:A`;`ii:A`;`ci:A`;`P:A`;`leqp:A`]
          BVALF_HS_INF_SUCC) THEN
    ASM_REWRITE_TAC[]]);;

(* ===================================================================== *)
(* H4.7 : FOUNDATION.  The least-B-name-rank bad-name argument works      *)
(* verbatim for HS names (HS names are bnames; domain elements of HS names *)
(* are HS by HSNAME_DOM); only "bad" now requires hsname (hsname_form 1 in *)
(* found_bad_form_HS, slots 8,9 := w1,X).                                  *)
(* ===================================================================== *)
let FOUND_ZBU0_CG_HS = prove
 (`!D (E:A->A->bool) B leq w1 X c aa u0 b zbu0 zba g cg vv.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
          w1 IN D /\ X IN D /\
      c IN D /\ E c B /\ aa IN D /\ u0 IN D /\ b IN D /\
      hsname D E B w1 X aa /\ hsname D E B w1 X u0 /\ hsname D E B w1 X b /\
      valuation D vv /\ (!i. hsname D E B w1 X (vv i)) /\ vv 0 = aa /\
      zbu0 IN D /\ zba IN D /\ g IN D /\ cg IN D /\
      ebv_in D E B leq b u0 zbu0 /\ ebv_in D E B leq b aa zba /\
      emeet D E B leq c zba g /\ ecompl D E B leq g cg /\
      (!y. y IN D /\ hsname D E B w1 X y /\ eindom D E u0 y
           ==> erel D E leq c (bvalf_HS D E B leq w1 X ((1 |-> y) vv)
                               (Not(1 %% 0))))
      ==> erel D E leq zbu0 cg`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (aa:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (u0:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (b:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (y:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `!i:num. bname D (E:A->A->bool) B (((vv):num->A) i)`
      ASSUME_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC HSNAME_BNAME THEN
    MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[valuation]; ALL_TAC]) THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) cg B` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECOMPL_IN]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`b:A`;`u0:A`;
                       `zbu0:A`;`cg:A`]
    EBV_IN_LE_V) THEN
  ASM_REWRITE_TAC[] THEN
  MAP_EVERY X_GEN_TAC [`yv:A`;`qyv:A`;`eyv:A`;`ccv:A`] THEN STRIP_TAC THEN
  SUBGOAL_THEN `eindom D (E:A->A->bool) u0 yv` ASSUME_TAC THENL
   [REWRITE_TAC[eindom] THEN EXISTS_TAC `qyv:A` THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `hsname D (E:A->A->bool) B w1 X yv` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;`u0:A`;`yv:A`]
           HSNAME_DOM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN(ACCEPT_TAC o
        CONJUNCT2)]; ALL_TAC] THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (yv:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  SUBGOAL_THEN `valuation D ((1 |-> (yv:A)) vv) /\
      (!i. hsname D E B w1 X (((1 |-> (yv:A)) vv) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC HSNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  TRY(SUBGOAL_THEN `!i:num. bname D (E:A->A->bool) B
      ((((1 |-> (yv:A)) vv):num->A) i)` ASSUME_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC HSNAME_BNAME THEN
    MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[valuation]; ALL_TAC]) THEN
  SUBGOAL_THEN `((1 |-> (yv:A)) vv) 1 = yv /\ ((1 |-> (yv:A)) vv) 0 = aa`
  STRIP_ASSUME_TAC THENL
   [ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
  SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq yv aa
                  (bvalf_HS D E B leq w1 X ((1 |-> (yv:A)) vv) (1 %% 0))`
                      ASSUME_TAC THENL
   [MP_TAC(ISPECL [`1`;`0`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                   `X:A`;`(1 |-> (yv:A)) vv`]
      BVALF_HS_MEM) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(bvalf_HS D (E:A->A->bool) B leq w1 X ((1 |-> (yv:A)) vv)
                 (1 %% 0)) IN D`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL [`1 %% 0`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                   `X:A`;`(1 |-> (yv:A)) vv`]
      BVALF_HS_SPEC) THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(bvalf_HS D (E:A->A->bool) B leq w1 X ((1 |-> (yv:A)) vv)
                 (Not(1 %% 0))) IN D`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL [`Not(1 %% 0)`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                   `w1:A`;`X:A`;`(1 |-> (yv:A)) vv`]
      BVALF_HS_SPEC) THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `ecompl D (E:A->A->bool) B leq
                  (bvalf_HS D E B leq w1 X ((1 |-> (yv:A)) vv) (1 %% 0))
                  (bvalf_HS D E B leq w1 X ((1 |-> (yv:A)) vv) (Not(1 %% 0)))`
                      ASSUME_TAC THENL
   [MP_TAC(ISPECL [`1 %% 0`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                   `X:A`;`(1 |-> (yv:A)) vv`]
      BVALF_HS_NOT) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq c
                  (bvalf_HS D E B leq w1 X ((1 |-> (yv:A)) vv) (Not(1 %% 0)))`
                      ASSUME_TAC THENL
   [FIRST_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`] EBALG_BOT) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `bot:A`) THEN
  SUBGOAL_THEN `(bot:A) IN D` ASSUME_TAC THENL
      [ASM_MESON_TAC[EBOT_IN]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;
                       `b:A`;`aa:A`;`u0:A`;
    `yv:A`;`qyv:A`;`eyv:A`;`ccv:A`;`zba:A`;
    `bvalf_HS D (E:A->A->bool) B leq w1 X ((1 |-> (yv:A)) vv)
        (1 %% 0)`;`g:A`;`cg:A`;
    `bvalf_HS D (E:A->A->bool) B leq w1 X ((1 |-> (yv:A)) vv) (Not(1 %% 0))`;
