let FOUND_BADEQ_HS = prove
 (`!D (E:A->A->bool) B leq w1 X c aa b vv.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
          w1 IN D /\ X IN D /\
      c IN D /\ E c B /\ aa IN D /\ b IN D /\
      hsname D E B w1 X aa /\ hsname D E B w1 X b /\
      valuation D vv /\ (!i. hsname D E B w1 X (vv i)) /\ vv 0 = aa
      ==> (~(erel D E leq c (bvalf_HS D E B leq w1 X ((1 |-> b) vv)
                             (Not(1 %% 0)))) <=>
           (?z20 z21 z24. z20 IN D /\ z21 IN D /\ z24 IN D /\
              ebv_in D E B leq b aa z20 /\
              ecompl D E B leq z20 z21 /\
              ebimp D E B leq c z21 z24 /\
              ~etop D E B leq z24))`,
