   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC HSNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  TRY(SUBGOAL_THEN `!i:num. bname D (E:A->A->bool) B
      ((((1 |-> (b:A)) vv):num->A) i)` ASSUME_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC HSNAME_BNAME THEN
    MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[valuation]; ALL_TAC]) THEN
  SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq b aa
                  (bvalf_HS D E B leq w1 X ((1 |-> (b:A)) vv) (1 %% 0))`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL [`1`;`0`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                   `X:A`;`(1 |-> (b:A)) vv`]
      BVALF_HS_MEM) THEN ASM_REWRITE_TAC[] THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
  SUBGOAL_THEN `(bvalf_HS D (E:A->A->bool) B leq w1 X ((1 |-> (b:A)) vv)
                 (1 %% 0)) IN D /\
                (E:A->A->bool) (bvalf_HS D E B leq w1 X
                                ((1 |-> (b:A)) vv) (1 %% 0)) B`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL [`(1 %% 0)`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                     `X:A`;`(1 |-> (b:A)) vv`]
        BVALF_HS_SPEC) THEN ASM_REWRITE_TAC[] THEN
            DISCH_THEN(ACCEPT_TAC o CONJUNCT1);
      MATCH_MP_TAC(ISPECL [`(1 %% 0)`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                           `w1:A`;`X:A`;`(1 |-> (b:A)) vv`]
        BVALF_HS_IN_B) THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
