                  (bvalf_HS D E B leq w1 X ((1 |-> (b:A)) vv) (1 %% 0))
                  (bvalf_HS D E B leq w1 X ((1 |-> (b:A)) vv) (Not(1 %% 0)))`
  ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`(1 %% 0)`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                         `w1:A`;`X:A`;`(1 |-> (b:A)) vv`]
      BVALF_HS_NOT) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(bvalf_HS D (E:A->A->bool) B leq w1 X ((1 |-> (b:A)) vv)
                 (Not(1 %% 0))) IN D /\
                (E:A->A->bool) (bvalf_HS D E B leq w1 X ((1 |-> (b:A)) vv)
