  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL [`(Not(1 %% 0))`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                     `w1:A`;`X:A`;`(1 |-> (b:A)) vv`]
        BVALF_HS_SPEC) THEN ASM_REWRITE_TAC[] THEN
            DISCH_THEN(ACCEPT_TAC o CONJUNCT1);
