        BVALF_HS_IN_B) THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;
    `bvalf_HS D E B leq w1 X ((1 |-> (b:A)) vv) (Not(1 %% 0))`]
