      `bvalf_HS D E B leq w1 X ((1 |-> (b:A)) vv) (Not(1 %% 0))`;`z24:A`] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `z20:A` (X_CHOOSE_THEN `z21:A`
