    SUBGOAL_THEN `z21:A = bvalf_HS D E B leq w1 X
        ((1 |-> (b:A)) vv) (Not(1 %% 0))`
    SUBST_ALL_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `bvalf_HS D E B leq w1 X ((1 |-> (b:A)) vv) (1 %% 0)`;`z21:A`;
        `bvalf_HS D E B leq w1 X ((1 |-> (b:A)) vv) (Not(1 %% 0))`]
            ECOMPL_UNIQUE) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
     `etop D (E:A->A->bool) B leq z24' <=>
