    ASM_MESON_TAC[]]);;

let found_bad_form_HS = new_definition
  `found_bad_form_HS =
     ?? 1 (instage_bn_form && hsname_form 1 && found_val_form)`;;

let HOLDS_FOUND_BAD_FORM_HS = prove
 (`!D (E:A->A->bool) v.
      model D E ZF_AX /\ valuation D v
      ==> (holds D E v found_bad_form_HS <=>
           ?a. a IN D /\ (?y. y IN D /\ ebnstage D E (v 2) (v 0) y /\ E a y) /\
               hsname D E (v 2) (v 8) (v 9) a /\
               (?z20 z21 z24. z20 IN D /\ z21 IN D /\ z24 IN D /\
                  ebv_in D E (v 2) (v 5) a (v 6) z20 /\
                  ecompl D E (v 2) (v 5) z20 z21 /\
                  ebimp D E (v 2) (v 5) (v 7) z21 z24 /\
                  ~etop D E (v 2) (v 5) z24))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[found_bad_form_HS] THEN
  REWRITE_TAC[HOLDS_EX] THEN
  MATCH_MP_TAC EXISTS_AND_CONG THEN
  X_GEN_TAC `a:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `valuation D ((1 |-> (a:A)) (v:num->A))` ASSUME_TAC THENL
   [REPEAT(FIRST_ASSUM ACCEPT_TAC ORELSE
           (MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC)); ALL_TAC] THEN
  REWRITE_TAC[HOLDS_AND] THEN
  MATCH_MP_TAC(TAUT
    `(a <=> a') /\ (b <=> b') /\ (c <=> c')
     ==> (a /\ b /\ c <=> a' /\ b' /\ c')`) THEN
  REPEAT CONJ_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`(1 |-> (a:A)) (v:num->A)`]
      HOLDS_INSTAGE_BN_FORM) THEN ASM_REWRITE_TAC[] THEN
          DISCH_THEN SUBST1_TAC THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ];
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`(1 |-> (a:A)) (v:num->A)`;`1`]
      HOLDS_HSNAME_FORM) THEN ANTS_TAC THENL
          [ASM_REWRITE_TAC[] THEN ARITH_TAC; ALL_TAC] THEN
    DISCH_THEN SUBST1_TAC THEN ASM_SIMP_TAC[VALMOD_BASIC;
        VALMOD_OTHER; ARITH_EQ];
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`(1 |-> (a:A)) (v:num->A)`]
      HOLDS_FOUND_VAL_FORM) THEN ASM_REWRITE_TAC[] THEN
          DISCH_THEN SUBST1_TAC THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]]);;

let FOUND_KEY_HS = prove
 (`!D (E:A->A->bool) B leq w1 X c aa vv.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
          w1 IN D /\ X IN D /\
      c IN D /\ E c B /\ aa IN D /\ hsname D E B w1 X aa /\
      valuation D vv /\ (!i. hsname D E B w1 X (vv i)) /\ vv 0 = aa /\
      c = bvalf_HS D E B leq w1 X vv found_cform
      ==> !u. u IN D /\ hsname D E B w1 X u
              ==> erel D E leq c (bvalf_HS D E B leq w1 X ((1 |-> u) vv)
                                  (Not(1 %% 0)))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (aa:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (u:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
