    MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[valuation]; ALL_TAC]) THEN
  UNDISCH_TAC `(c:A) = bvalf_HS D (E:A->A->bool) B leq w1 X vv found_cform` THEN
  DISCH_THEN(ASSUME_TAC o SYM) THEN
  ABBREV_TAC `wv = (7 |-> (c:A)) ((6 |-> (aa:A))
      ((5 |-> (leq:A)) ((9 |-> (X:A)) ((8 |-> (w1:A))
      ((2 |-> (B:A)) vv)))))` THEN
  SUBGOAL_THEN `valuation D (wv:num->A) /\ (wv:num->A) 2 = B /\
      (wv:num->A) 5 = leq /\
                (wv:num->A) 6 = aa /\ (wv:num->A) 7 = c /\ (wv:num->A) 8 = w1 /\
                    (wv:num->A) 9 = X`
