    REWRITE_TAC[found_cform] THEN
    MATCH_MP_TAC(ISPECL [`1`; `Not(1 %% 0 && !!- 2 1 (Not(2 %% 0)))`;
      `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;`X:A`;`vv:num->A`;`a0:A`]
          BVALF_HS_ALL_LB) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `~(erel D (E:A->A->bool) leq c
                  (bvalf_HS D E B leq w1 X ((1 |-> a0) vv) (Not(1 %% 0))))`
      ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;`X:A`;`c:A`;
                   `aa:A`;`a0:A`;`vv:num->A`] FOUND_BADEQ_HS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MAP_EVERY EXISTS_TAC [`z20:A`;`z21:A`;`z24:A`] THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq c
      (bvalf_HS D E B leq w1 X ((1 |-> a0) vv) (Not(1 %% 0)))` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;`X:A`;
                         `c:A`;`aa:A`;`a0:A`;`vv:num->A`] FOUND_STEP_HS) THEN
    ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `yy:A` THEN STRIP_TAC THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (yy:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
   REFUTE_THEN ASSUME_TAC THEN
    UNDISCH_TAC `eindom D (E:A->A->bool) a0 yy` THEN REWRITE_TAC[eindom] THEN
    DISCH_THEN(X_CHOOSE_THEN `qy:A` STRIP_ASSUME_TAC) THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`a0:A`;`yy:A`;`qy:A`;
                   `ra0:A`] EBNRANK_APPLY_LT) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `ry:A` STRIP_ASSUME_TAC o CONJUNCT2) THEN
    SUBGOAL_THEN `(ry:A) IN D /\ eordinal D (E:A->A->bool) ry`
        STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EBNRANK_IN; EBNRANK_ORDINAL]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) (ry:A) d` ASSUME_TAC THENL
     [UNDISCH_TAC `(E:A->A->bool) (ra0:A) d \/ ra0 = d` THEN STRIP_TAC THENL
       [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`d:A`;`ry:A`;`ra0:A`]
                     EORDINAL_TRANS_E) THEN
        ASM_REWRITE_TAC[];
        ASM_MESON_TAC[]]; ALL_TAC] THEN
    SUBGOAL_THEN `holds D (E:A->A->bool) ((0 |-> ry) (wv:num->A))
        found_bad_form_HS` ASSUME_TAC THENL
     [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`(0 |-> ry) (wv:num->A)`]
             HOLDS_FOUND_BAD_FORM_HS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN MATCH_MP_TAC VALUATION_VALMOD THEN
                      ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN SUBST1_TAC THEN ASM_SIMP_TAC[VALMOD_BASIC;
          VALMOD_OTHER; ARITH_EQ] THEN
      EXISTS_TAC `yy:A` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
       [UNDISCH_TAC `ebnrank D (E:A->A->bool) B yy ry` THEN
        REWRITE_TAC[ebnrank] THEN MESON_TAC[];
        MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;`X:A`;
                       `c:A`;`aa:A`;`yy:A`;`vv:num->A`] FOUND_BADEQ_HS) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
            ASM_REWRITE_TAC[]]; ALL_TAC] THEN
    USE_THEN "min" (fun th -> MP_TAC(MATCH_MP th
        (CONJ (ASSUME `(ry:A) IN D`) (ASSUME `(E:A->A->bool) ry d`)))) THEN
    REWRITE_TAC[ASSUME `holds D (E:A->A->bool) ((0 |-> ry) (wv:num->A))
                found_bad_form_HS`]; ALL_TAC] THEN
  UNDISCH_TAC `~(erel D (E:A->A->bool) leq c
                 (bvalf_HS D E B leq w1 X ((1 |-> a0) vv) (Not(1 %% 0))))` THEN
  ASM_REWRITE_TAC[]);;

let BVALF_HS_FOUNDATION = prove
 (`!D (E:A->A->bool) B leq w1 X v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
          w1 IN D /\ X IN D /\
      valuation D v /\ (!i. hsname D E B w1 X (v i))
      ==> etop D E B leq (bvalf_HS D E B leq w1 X v foundation_ax)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  TRY(SUBGOAL_THEN `!i:num. bname D (E:A->A->bool) B (((v):num->A) i)`
      ASSUME_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC HSNAME_BNAME THEN
    MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[valuation]; ALL_TAC]) THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  REWRITE_TAC[foundation_ax; Existsmem_DEF; Exists_DEF; GSYM found_cform] THEN
  MP_TAC(ISPECL [`0`; `Not(!! 1 (Not(1 %% 0))) --> Not found_cform`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;`X:A`;`v:num->A`]
        BVALF_HS_ALL_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN
  X_GEN_TAC `aa:A` THEN STRIP_TAC THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (aa:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  
  ABBREV_TAC `w = (0 |-> (aa:A)) v` THEN
  SUBGOAL_THEN `valuation D (w:num->A) /\
      (!i. hsname D (E:A->A->bool) B w1 X ((w:num->A) i)) /\
                (w:num->A) 0 = aa`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "w" THEN REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC HSNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[];
      ASM_SIMP_TAC[VALMOD_BASIC]]; ALL_TAC] THEN
  MP_TAC(ISPECL [`Not(!! 1 (Not(1 %% 0)))`; `Not found_cform`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;`X:A`;`w:num->A`]
        BVALF_HS_IMP_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN
  SUBGOAL_THEN `(bvalf_HS D (E:A->A->bool) B leq w1 X (w:num->A)
                 found_cform) IN D`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL[`found_cform`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                  `X:A`;`w:num->A`] BVALF_HS_SPEC) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(ACCEPT_TAC o CONJUNCT1); ALL_TAC] THEN
  SUBGOAL_THEN `E (bvalf_HS D (E:A->A->bool) B leq w1 X (w:num->A)
                   found_cform) B`
  ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`found_cform`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                        `w1:A`;`X:A`;`w:num->A`] BVALF_HS_IN_B) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(bvalf_HS D (E:A->A->bool) B leq w1 X (w:num->A)
                 (!! 1 (Not(1 %% 0)))) IN D`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL[`!! 1 (Not(1 %% 0))`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                  `w1:A`;`X:A`;`w:num->A`] BVALF_HS_SPEC) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(ACCEPT_TAC o CONJUNCT1); ALL_TAC] THEN
  SUBGOAL_THEN `E (bvalf_HS D (E:A->A->bool) B leq w1 X (w:num->A)
                   (!! 1 (Not(1 %% 0)))) B`
  ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`!! 1 (Not(1 %% 0))`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                        `leq:A`;`w1:A`;`X:A`;`w:num->A`] BVALF_HS_IN_B) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `ecompl D (E:A->A->bool) B leq
      (bvalf_HS D E B leq w1 X (w:num->A) found_cform)
      (bvalf_HS D E B leq w1 X (w:num->A) (Not found_cform))`
  ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`found_cform`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                        `w1:A`;`X:A`;`w:num->A`] BVALF_HS_NOT) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `ecompl D (E:A->A->bool) B leq
      (bvalf_HS D E B leq w1 X (w:num->A) (!! 1 (Not(1 %% 0))))
      (bvalf_HS D E B leq w1 X (w:num->A) (Not(!! 1 (Not(1 %% 0)))))`
  ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`!! 1 (Not(1 %% 0))`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                        `leq:A`;`w1:A`;`X:A`;`w:num->A`] BVALF_HS_NOT) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq
      (bvalf_HS D E B leq w1 X (w:num->A) found_cform)
      (bvalf_HS D E B leq w1 X (w:num->A) (!! 1 (Not(1 %% 0))))`
  ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`1`; `Not(1 %% 0)`;
      `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;`X:A`;`w:num->A`;
      `bvalf_HS D E B leq w1 X (w:num->A) found_cform`] BVALF_HS_ALL_GLB) THEN
    ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `u:A` THEN STRIP_TAC THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (u:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;`X:A`;
      `bvalf_HS D E B leq w1 X (w:num->A) found_cform`;`aa:A`;`w:num->A`]
          FOUND_KEY_HS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPEC `u:A`) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
    `bvalf_HS D E B leq w1 X (w:num->A) found_cform`;
    `bvalf_HS D E B leq w1 X (w:num->A) (!! 1 (Not(1 %% 0)))`;
    `bvalf_HS D E B leq w1 X (w:num->A) (Not found_cform)`;
    `bvalf_HS D E B leq w1 X (w:num->A) (Not(!! 1 (Not(1 %% 0))))`]
        ECOMPL_ANTITONE) THEN
  ASM_REWRITE_TAC[]);;

(* ===================================================================== *)
(* H4.8a : SEPARATION, the separation name.  Clones of EBV_IN_SEP_LE/_GE /  *)
(* EBV_IN_SEP / ESEPNAME_RAW / ESEPNAME_EXISTS with bval_HS (base valuation *)
(* carries w1,X at slots 8,9 for BVAL_HS_DEFINABLE); ESEPNAME_BNAME_HS     *)
(* (bname of the HS separation name, bval -> bval_HS only).                *)
(* ===================================================================== *)
let EBV_IN_SEP_LE_HS = prove
 (`!D (E:A->A->bool) B leq w1 X v p x aa tt sn zin zia rhs.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
          w1 IN D /\ X IN D /\
      valuation D v /\ (!i. hsname D E B w1 X (v i)) /\
      aa IN D /\ tt IN D /\ sn IN D /\
      hsname D E B w1 X aa /\ hsname D E B w1 X tt /\ hsname D E B w1 X sn /\
      eisfun D E sn /\
      (!w. w IN D ==> (eindom D E sn w <=> eindom D E aa w)) /\
      (!w q m. w IN D /\ q IN D /\ eindom D E aa w /\ eapply D E aa w q /\
               emeet D E B leq q (bvalf_HS D E B leq w1 X ((x |-> w) v) p) m
               ==> eapply D E sn w m) /\
      zin IN D /\ zia IN D /\
      ebv_in D E B leq tt sn zin /\
      ebv_in D E B leq tt aa zia /\
      emeet D E B leq zia (bvalf_HS D E B leq w1 X ((x |-> tt) v) p) rhs
      ==> erel D E leq zin rhs`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (aa:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (tt:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (sn:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `!i:num. bname D (E:A->A->bool) B (((v):num->A) i)`
      ASSUME_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC HSNAME_BNAME THEN
    MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[valuation]; ALL_TAC]) THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((x |-> tt) (v:num->A))` ASSUME_TAC THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `!i. hsname D (E:A->A->bool) B w1 X (((x |-> tt) (v:num->A)) i)`
      ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;`x:num`;
                         `tt:A`;`v:num->A`]
      HSNAMEVAL_VALMOD) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) (bvalf_HS D E B leq w1 X ((x |-> tt) v) p) B`
      ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                         `leq:A`;`w1:A`;`X:A`;
      `(x |-> tt) (v:num->A)`] BVALF_HS_IN_B) THEN
          ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(bvalf_HS D (E:A->A->bool) B leq w1 X ((x |-> tt) v) p) IN D`
      ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                         `leq:A`;`w1:A`;`X:A`;
      `(x |-> tt) (v:num->A)`] BVALF_HS_IND) THEN
          ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(rhs:A) IN D /\ (E:A->A->bool) rhs B` STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zia:A`;
      `bvalf_HS D (E:A->A->bool) B leq w1 X ((x |-> tt) v) p`;
          `rhs:A`] EMEET_IN) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`tt:A`;`sn:A`;
    `zin:A`;`rhs:A`] EBV_IN_LE_V) THEN
  ASM_REWRITE_TAC[] THEN
  MAP_EVERY X_GEN_TAC [`y:A`;`qy:A`;`ey:A`;`c:A`] THEN STRIP_TAC THEN
  SUBGOAL_THEN `eindom D (E:A->A->bool) sn y` ASSUME_TAC THENL
   [REWRITE_TAC[eindom] THEN EXISTS_TAC `qy:A` THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `eindom D (E:A->A->bool) aa y` ASSUME_TAC THENL
   [UNDISCH_TAC `!w:A. w IN D ==> (eindom D (E:A->A->bool) sn w <=>
       eindom D E aa w)` THEN
    UNDISCH_TAC `eindom D (E:A->A->bool) sn y` THEN
    UNDISCH_TAC `(y:A) IN D` THEN MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `?q0:A. q0 IN D /\ eapply D (E:A->A->bool) aa y q0`
    (X_CHOOSE_THEN `q0:A` STRIP_ASSUME_TAC) THENL
   [UNDISCH_TAC `eindom D (E:A->A->bool) aa y` THEN REWRITE_TAC[eindom] THEN
    MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `hsname D (E:A->A->bool) B w1 X y` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;`aa:A`;`y:A`]
           HSNAME_DOM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN(ACCEPT_TAC o
        CONJUNCT2)]; ALL_TAC] THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (y:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  SUBGOAL_THEN `(E:A->A->bool) q0 B` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`aa:A`;`y:A`;`q0:A`]
      BNAME_APPLY_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((x |-> y) (v:num->A))` ASSUME_TAC THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `!i. hsname D (E:A->A->bool) B w1 X (((x |-> y) (v:num->A)) i)`
      ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;`x:num`;
                         `y:A`;`v:num->A`]
      HSNAMEVAL_VALMOD) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) (bvalf_HS D E B leq w1 X ((x |-> y) v) p) B`
      ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                         `leq:A`;`w1:A`;`X:A`;
      `(x |-> y) (v:num->A)`] BVALF_HS_IN_B) THEN
          ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(bvalf_HS D (E:A->A->bool) B leq w1 X ((x |-> y) v) p) IN D`
      ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                         `leq:A`;`w1:A`;`X:A`;
      `(x |-> y) (v:num->A)`] BVALF_HS_IND) THEN
          ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`q0:A`;
    `bvalf_HS D (E:A->A->bool) B leq w1 X ((x |-> y) v) p`] EBALG_MEET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `mprime:A`) THEN
  SUBGOAL_THEN `(mprime:A) IN D /\ (E:A->A->bool) mprime B`
      STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`q0:A`;
      `bvalf_HS D (E:A->A->bool) B leq w1 X ((x |-> y) v) p`;
          `mprime:A`] EMEET_IN) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `eapply D (E:A->A->bool) sn y mprime` ASSUME_TAC THENL
