        eapply D E aa w q /\ emeet D E B leq q
            (bvalf_HS D E B leq w1 X ((x |-> w) v) p) m
        ==> eapply D E sn w m` THEN
    DISCH_THEN(MATCH_MP_TAC o SPECL [`y:A`;`q0:A`;`mprime:A`]) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `qy:A = mprime` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`sn:A`;`y:A`;
                         `qy:A`;`mprime:A`]
      EAPPLY_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) ey B` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`tt:A`;`y:A`;
      `ey:A`] EBV_EQ_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) c B` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                   `mprime:A`;`ey:A`;`c:A`]
      EMEET_IN) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) zia B` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`tt:A`;`aa:A`;
      `zia:A`] EBV_IN_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq c mprime /\ erel D E leq c ey`
  STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                   `mprime:A`;`ey:A`;`c:A`]
      EMEET_LE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mprime q0 /\
                erel D E leq mprime (bvalf_HS D E B leq w1 X ((x |-> y) v) p)`
  STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`q0:A`;
      `bvalf_HS D (E:A->A->bool) B leq w1 X ((x |-> y) v) p`;
          `mprime:A`] EMEET_LE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq c q0` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                         `c:A`;`mprime:A`;
      `q0:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq c
      (bvalf_HS D E B leq w1 X ((x |-> y) v) p)`
  ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                         `c:A`;`mprime:A`;
      `bvalf_HS D (E:A->A->bool) B leq w1 X ((x |-> y) v) p`]
          EPORDER_TRANS) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`q0:A`;`ey:A`]
    EBALG_MEET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `aterm:A`) THEN
  SUBGOAL_THEN `(aterm:A) IN D /\ (E:A->A->bool) aterm B` STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`q0:A`;
                   `ey:A`;`aterm:A`]
      EMEET_IN) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq c aterm` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`q0:A`;`ey:A`;
      `aterm:A`;`c:A`] EMEET_GREATEST) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq aterm zia` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`tt:A`;`aa:A`;
      `zia:A`;`y:A`;`q0:A`;`ey:A`;`aterm:A`] EBV_IN_GE_TERM_V) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq c zia` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                         `c:A`;`aterm:A`;
      `zia:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ey:A`;
    `bvalf_HS D (E:A->A->bool) B leq w1 X ((x |-> y) v) p`] EBALG_MEET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `pterm:A`) THEN
  SUBGOAL_THEN `(pterm:A) IN D /\ (E:A->A->bool) pterm B` STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ey:A`;
      `bvalf_HS D (E:A->A->bool) B leq w1 X ((x |-> y) v) p`;
          `pterm:A`] EMEET_IN) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq c pterm` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ey:A`;
      `bvalf_HS D (E:A->A->bool) B leq w1 X ((x |-> y) v) p`;`pterm:A`;`c:A`]
      EMEET_GREATEST) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `ebv_eq D (E:A->A->bool) B leq y tt ey` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`tt:A`;`y:A`;
      `ey:A`] EBV_EQ_SYM) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
