    EBIMP_LE_IMP) THEN
  ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`qy:A`;
    `bvalf_HS D (E:A->A->bool) B leq w1 X ((x |-> y) v) p`] EBALG_MEET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `snw:A`) THEN
