      `bvalf_HS D (E:A->A->bool) B leq w1 X ((x |-> y) v) p`;
          `snw:A`] EMEET_IN) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `eapply D (E:A->A->bool) sn y snw` ASSUME_TAC THENL
