  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`snw:A`;`ey:A`]
    EBALG_MEET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `msn:A`) THEN
  SUBGOAL_THEN `(msn:A) IN D /\ (E:A->A->bool) msn B` STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                   `snw:A`;`ey:A`;`msn:A`]
      EMEET_IN) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq msn zin` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`tt:A`;`sn:A`;
      `zin:A`;`y:A`;`snw:A`;`ey:A`;`msn:A`] EBV_IN_GE_TERM_V) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ey:A`;
    `bvalf_HS D (E:A->A->bool) B leq w1 X ((x |-> tt) v) p`] EBALG_MEET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `eypt:A`) THEN
  SUBGOAL_THEN `(eypt:A) IN D /\ (E:A->A->bool) eypt B` STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ey:A`;
      `bvalf_HS D (E:A->A->bool) B leq w1 X ((x |-> tt) v) p`;
          `eypt:A`] EMEET_IN) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq eypt
                  (bvalf_HS D E B leq w1 X ((x |-> y) v) p)` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                         `leq:A`;`w1:A`;`X:A`;
      `v:num->A`;`x:num`;`tt:A`;`y:A`;`ey:A`;`eypt:A`] BVAL_SUBST_CONG_HS) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq dm c /\
                erel D E leq dm (bvalf_HS D E B leq w1 X ((x |-> tt) v) p)`
  STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;
      `bvalf_HS D (E:A->A->bool) B leq w1 X ((x |-> tt) v) p`;
          `dm:A`] EMEET_LE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq c qy /\ erel D E leq c ey`
  STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`qy:A`;`ey:A`;`c:A`]
      EMEET_LE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq dm qy` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`dm:A`;`c:A`;
      `qy:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq dm ey` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`dm:A`;`c:A`;
      `ey:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq dm eypt` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ey:A`;
      `bvalf_HS D (E:A->A->bool) B leq w1 X ((x |-> tt) v) p`;`eypt:A`;`dm:A`]
      EMEET_GREATEST) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq dm
      (bvalf_HS D E B leq w1 X ((x |-> y) v) p)`
  ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                         `dm:A`;`eypt:A`;
      `bvalf_HS D (E:A->A->bool) B leq w1 X ((x |-> y) v) p`]
          EPORDER_TRANS) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq dm snw` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`qy:A`;
      `bvalf_HS D (E:A->A->bool) B leq w1 X ((x |-> y) v) p`;`snw:A`;`dm:A`]
      EMEET_GREATEST) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq dm msn` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;
                         `leq:A`;`snw:A`;`ey:A`;
      `msn:A`;`dm:A`] EMEET_GREATEST) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`dm:A`;`msn:A`;
    `zin:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[]);;

let EBV_IN_SEP_HS = prove
 (`!D (E:A->A->bool) B leq w1 X v p x aa tt sn zin zia rhs.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
          w1 IN D /\ X IN D /\
      valuation D v /\ (!i. hsname D E B w1 X (v i)) /\
      aa IN D /\ tt IN D /\ sn IN D /\
      hsname D E B w1 X aa /\ hsname D E B w1 X tt /\ hsname D E B w1 X sn /\
      eisfun D E sn /\
      (!w. w IN D ==> (eindom D E sn w <=> eindom D E aa w)) /\
      (!w q m. w IN D /\ q IN D /\ eindom D E aa w /\ eapply D E aa w q /\
               emeet D E B leq q (bvalf_HS D E B leq w1 X ((x |-> w) v) p) m
               ==> eapply D E sn w m) /\
      zin IN D /\ zia IN D /\
      ebv_in D E B leq tt sn zin /\
      ebv_in D E B leq tt aa zia /\
      emeet D E B leq zia (bvalf_HS D E B leq w1 X ((x |-> tt) v) p) rhs
      ==> zin = rhs`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (aa:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (tt:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (sn:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `!i:num. bname D (E:A->A->bool) B (((v):num->A) i)`
      ASSUME_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC HSNAME_BNAME THEN
    MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[valuation]; ALL_TAC]) THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((x |-> tt) (v:num->A))` ASSUME_TAC THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `!i. hsname D (E:A->A->bool) B w1 X (((x |-> tt) (v:num->A)) i)`
      ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;`x:num`;
                         `tt:A`;`v:num->A`]
      HSNAMEVAL_VALMOD) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) (bvalf_HS D E B leq w1 X ((x |-> tt) v) p) B`
      ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                         `leq:A`;`w1:A`;`X:A`;
      `(x |-> tt) (v:num->A)`] BVALF_HS_IN_B) THEN
          ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(rhs:A) IN D /\ (E:A->A->bool) rhs B` STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zia:A`;
      `bvalf_HS D (E:A->A->bool) B leq w1 X ((x |-> tt) v) p`;
          `rhs:A`] EMEET_IN) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) zin B` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`tt:A`;`sn:A`;
      `zin:A`] EBV_IN_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zin:A`;`rhs:A`]
    EPORDER_ANTISYM) THEN
  ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;`X:A`;
                         `v:num->A`;`p:form`;
      `x:num`;`aa:A`;`tt:A`;`sn:A`;`zin:A`;`zia:A`;`rhs:A`]
          EBV_IN_SEP_LE_HS) THEN
    ASM_REWRITE_TAC[];
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;`X:A`;
                         `v:num->A`;`p:form`;
      `x:num`;`aa:A`;`tt:A`;`sn:A`;`zin:A`;`zia:A`;`rhs:A`]
          EBV_IN_SEP_GE_HS) THEN
    ASM_REWRITE_TAC[]]);;

let ESEPNAME_RAW_HS = prove
 (`!D (E:A->A->bool) B leq w1 X v p x aa.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
          w1 IN D /\ X IN D /\
      valuation D v /\ (!i. hsname D E B w1 X (v i)) /\
      aa IN D /\ hsname D E B w1 X aa
      ==> ?sn. sn IN D /\
               (!z. z IN D
                    ==> (E z sn <=>
                         ?w q e m. w IN D /\ q IN D /\ e IN D /\ m IN D /\
                                   eapply D E aa w q /\
                                   bval_HS D E B leq w1 X ((x |-> w) v) p e /\
                                   emeet D E B leq q e m /\
                                   eopair D (E:A->A->bool) w m z))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (aa:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `!i:num. bname D (E:A->A->bool) B (((v):num->A) i)`
      ASSUME_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC HSNAME_BNAME THEN
    MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[valuation]; ALL_TAC]) THEN
  SUBGOAL_THEN `!xx. (v:num->A) xx IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  X_CHOOSE_THEN `fp:form` (LABEL_TAC "fpdef")
    (ISPECL [`p:form`; `5`; `1`] BVAL_HS_DEFINABLE) THEN
  ABBREV_TAC `vP = (9 |-> (X:A)) ((8 |-> (w1:A))
      ((2 |-> (B:A)) ((1 |-> (leq:A)) (\k. (v:num->A) (k - 32)))))` THEN
  SUBGOAL_THEN
   `valuation D (vP:num->A) /\ (vP:num->A) 1 = leq /\ (vP:num->A) 2 = B /\
    (vP:num->A) 8 = w1 /\ (vP:num->A) 9 = X /\
    (!i. (vP:num->A) (32 + i) = (v:num->A) i)`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vP" THEN REPEAT CONJ_TAC THENL
     [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]) THEN
      REWRITE_TAC[valuation] THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[VALMOD; ARITH_EQ]; REWRITE_TAC[VALMOD; ARITH_EQ];
      REWRITE_TAC[VALMOD; ARITH_EQ]; REWRITE_TAC[VALMOD; ARITH_EQ];
      GEN_TAC THEN
      SIMP_TAC[VALMOD_OTHER; ARITH_RULE `~(32 + i = 9) /\ ~(32 + i = 8) /\
                                         ~(32 + i = 2) /\ ~(32 + i = 1)`] THEN
      AP_TERM_TAC THEN ARITH_TAC];
    ALL_TAC] THEN
  (* ---- the bridge hrk ---- *)
  SUBGOAL_THEN
   `!el ot:A. el IN D /\ ot IN D
      ==> (holds D E ((3 |-> ot) ((0 |-> el) (vP:num->A)))
             (?? (32 + x) (?? 4 (?? 5 (?? 6
                (opair_form (32 + x) 4 0 && fp && bmeet_form 1 2 4 5 6 &&
                 opair_form (32 + x) 6 3))))) <=>
           ?w. w IN D /\ ?q. q IN D /\ ?e. e IN D /\ ?m. m IN D /\
               eopair D E w q el /\
               bval_HS D E B leq w1 X ((x |-> w) v) p e /\
               emeet D E B leq q e m /\
               eopair D (E:A->A->bool) w m ot)`
   (LABEL_TAC "hrk") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    REWRITE_TAC[HOLDS_EX] THEN
    MATCH_MP_TAC EXISTS_AND_CONG THEN X_GEN_TAC `w:A` THEN DISCH_TAC THEN
    MATCH_MP_TAC EXISTS_AND_CONG THEN X_GEN_TAC `q:A` THEN DISCH_TAC THEN
    MATCH_MP_TAC EXISTS_AND_CONG THEN X_GEN_TAC `e:A` THEN DISCH_TAC THEN
    MATCH_MP_TAC EXISTS_AND_CONG THEN X_GEN_TAC `m:A` THEN DISCH_TAC THEN
    ABBREV_TAC
     `Vp = (6 |-> (m:A)) ((5 |-> (e:A)) ((4 |-> (q:A)) (((32 + x) |-> (w:A))
           ((3 |-> (ot:A)) ((0 |-> (el:A)) (vP:num->A))))))` THEN
    SUBGOAL_THEN
     `valuation D (Vp:num->A) /\
      (Vp:num->A) (32 + x) = w /\ Vp 4 = q /\ Vp 0 = el /\ Vp 2 = B /\
      Vp 1 = leq /\ Vp 8 = w1 /\ Vp 9 = X /\ Vp 5 = e /\
          Vp 6 = m /\ Vp 3 = ot /\
      (!i. (Vp:num->A) (32 + i) = ((x |-> w) (v:num->A)) i)`
    STRIP_ASSUME_TAC THENL
     [EXPAND_TAC "Vp" THEN REPEAT CONJ_TAC THENL
       [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]);
        SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER;
          ARITH_RULE `~(32 + x = 6) /\ ~(32 + x = 5) /\ ~(32 + x = 4)`];
        SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ];
        SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ;
          ARITH_RULE `~(0 = 32 + x)`];
        SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ;
          ARITH_RULE `~(2 = 32 + x)`] THEN ASM_REWRITE_TAC[];
        SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ;
          ARITH_RULE `~(1 = 32 + x)`] THEN ASM_REWRITE_TAC[];
        SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ;
          ARITH_RULE `~(8 = 32 + x)`] THEN ASM_REWRITE_TAC[];
        SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ;
          ARITH_RULE `~(9 = 32 + x)`] THEN ASM_REWRITE_TAC[];
        SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ];
        SIMP_TAC[VALMOD_BASIC];
        SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ;
          ARITH_RULE `~(3 = 32 + x)`];
        GEN_TAC THEN ASM_CASES_TAC `i:num = x` THEN
        ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ;
          ARITH_RULE `~(32 + i = 6) /\ ~(32 + i = 5) /\ ~(32 + i = 4) /\
                      ~(32 + i = 3) /\ ~(32 + i = 0)`;
          ARITH_RULE `~(i = x) ==> ~(32 + i = 32 + x)`]];
      ALL_TAC] THEN
    REWRITE_TAC[HOLDS_AND] THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `Vp:num->A`;
      `32 + x`; `4`; `0`] HOLDS_OPAIR_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `Vp:num->A`;
      `32 + x`; `6`; `3`] HOLDS_OPAIR_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `Vp:num->A`;
      `1`; `2`; `4`; `5`; `6`] HOLDS_BMEET_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "fpdef" (MP_TAC o SPECL
      [`D:A->bool`; `E:A->A->bool`; `Vp:num->A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN ARITH_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    SUBGOAL_THEN
     `bval_HS D E B leq w1 X (\i. (Vp:num->A) (32 + i)) p e <=>
      bval_HS D E B leq w1 X ((x |-> w) (v:num->A)) p e`
     (fun th -> REWRITE_TAC[th]) THENL
     [MATCH_MP_TAC BVAL_HS_FV THEN X_GEN_TAC `i:num` THEN DISCH_TAC THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[ETA_AX];
    ALL_TAC] THEN
  (* ---- apply replacement ---- *)
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_REPLACEMENT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`?? (32 + x) (?? 4 (?? 5 (?? 6
        (opair_form (32 + x) 4 0 && fp && bmeet_form 1 2 4 5 6 &&
         opair_form (32 + x) 6 3))))`;
     `0`; `3`; `vP:num->A`; `aa:A`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[ARITH_EQ] THEN
    X_GEN_TAC `u:A` THEN STRIP_TAC THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (u:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `aa:A`; `u:A`]
      BNAME_MEM_PAIR) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `w:A` (X_CHOOSE_THEN `q:A` STRIP_ASSUME_TAC)) THEN
    SUBGOAL_THEN `eapply D (E:A->A->bool) aa w q` ASSUME_TAC THENL
     [REWRITE_TAC[eapply] THEN EXISTS_TAC `u:A` THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `eindom D (E:A->A->bool) aa w` ASSUME_TAC THENL
     [REWRITE_TAC[eindom] THEN EXISTS_TAC `q:A` THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `hsname D (E:A->A->bool) B w1 X w` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;`aa:A`;`w:A`]
           HSNAME_DOM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN(ACCEPT_TAC o
        CONJUNCT2)]; ALL_TAC] THEN
    TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (w:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  SUBGOAL_THEN
     `valuation D ((x |-> w) (v:num->A)) /\
      (!i. hsname D (E:A->A->bool) B w1 X (((x |-> w) (v:num->A)) i))`
    STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC HSNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
    MP_TAC(ISPECL [`p:form`; `D:A->bool`; `E:A->A->bool`; `B:A`;
                   `leq:A`;`w1:A`;`X:A`;
      `(x |-> w) (v:num->A)`] BVAL_HS_TOTAL) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `e:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(E:A->A->bool) e B` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL [`p:form`; `D:A->bool`; `E:A->A->bool`; `B:A`;
                           `leq:A`;`w1:A`;`X:A`;
        `(x |-> w) (v:num->A)`; `e:A`] BVAL_HS_IN_B) THEN
            ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `q:A`; `e:A`]
      EBALG_MEET) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `m:A`) THEN
    SUBGOAL_THEN `(m:A) IN D /\ (E:A->A->bool) m B` STRIP_ASSUME_TAC THENL
     [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`;
                     `q:A`; `e:A`; `m:A`]
        EMEET_IN) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `w:A`; `m:A`]
           EOPAIR_EXISTS) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `z:A`) THEN
    SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
     [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
    EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `z':A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC MP_TAC) THEN
    USE_THEN "hrk" (MP_TAC o SPECL [`u:A`; `z':A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    DISCH_THEN(X_CHOOSE_THEN `w2:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (X_CHOOSE_THEN `q2:A` (CONJUNCTS_THEN2 ASSUME_TAC
       (X_CHOOSE_THEN `e2:A` (CONJUNCTS_THEN2 ASSUME_TAC
        (X_CHOOSE_THEN `m2:A` STRIP_ASSUME_TAC))))))) THEN
    SUBGOAL_THEN `(w2:A) = w /\ (q2:A) = q` STRIP_ASSUME_TAC THENL
     [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `w2:A`; `q2:A`;
                     `w:A`; `q:A`; `u:A`]
        EOPAIR_INJ) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    REPEAT(FIRST_X_ASSUM(SUBST_ALL_TAC o check (fun th ->
      (is_eq (concl th)) && (rand(concl th) = `w:A` ||
                             rand(concl th) = `q:A`)))) THEN
    SUBGOAL_THEN `(e2:A) = e` SUBST_ALL_TAC THENL
     [MP_TAC(ISPECL [`p:form`; `D:A->bool`; `E:A->A->bool`; `B:A`;
                     `leq:A`;`w1:A`;`X:A`;
        `(x |-> w) (v:num->A)`; `e2:A`; `e:A`] BVAL_HS_UNIQUE) THEN
            ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `(m2:A) = m` SUBST_ALL_TAC THENL
     [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `q:A`; `e:A`;
        `m2:A`; `m:A`] EMEET_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `w:A`; `m:A`; `z':A`; `z:A`]
      EOPAIR_UNIQUE) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `sn:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (LABEL_TAC "raw"))) THEN
  EXISTS_TAC `sn:A` THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `z:A` THEN DISCH_TAC THEN
  USE_THEN "raw" (fun th ->
    REWRITE_TAC[MATCH_MP th (ASSUME `(z:A) IN D`)]) THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `u:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC MP_TAC))) THEN
    USE_THEN "hrk" (MP_TAC o SPECL [`u:A`; `z:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    DISCH_THEN(X_CHOOSE_THEN `w:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (X_CHOOSE_THEN `q:A` (CONJUNCTS_THEN2 ASSUME_TAC
       (X_CHOOSE_THEN `e:A` (CONJUNCTS_THEN2 ASSUME_TAC
        (X_CHOOSE_THEN `m:A` STRIP_ASSUME_TAC))))))) THEN
    MAP_EVERY EXISTS_TAC [`w:A`; `q:A`; `e:A`; `m:A`] THEN
        ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[eapply] THEN EXISTS_TAC `u:A` THEN ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `w:A` (X_CHOOSE_THEN `q:A` (X_CHOOSE_THEN `e:A`
      (X_CHOOSE_THEN `m:A` STRIP_ASSUME_TAC)))) THEN
    UNDISCH_TAC `eapply D (E:A->A->bool) aa w q` THEN REWRITE_TAC[eapply] THEN
    DISCH_THEN(X_CHOOSE_THEN `u:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(u:A) IN D` ASSUME_TAC THENL
     [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
    EXISTS_TAC `u:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "hrk" (MP_TAC o SPECL [`u:A`; `z:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `q:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `e:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `m:A` THEN ASM_REWRITE_TAC[]]);;

let ESEPNAME_EXISTS_HS = prove
 (`!D (E:A->A->bool) B leq w1 X v p x aa.
        model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
            w1 IN D /\ X IN D /\
        valuation D v /\ (!i. hsname D E B w1 X (v i)) /\
        aa IN D /\ hsname D E B w1 X aa
        ==> ?sn. sn IN D /\ eisfun D E sn /\
                 (!w. w IN D ==> (eindom D E sn w <=> eindom D E aa w)) /\
                 (!w q m. w IN D /\ q IN D /\ eindom D E aa w /\
                          eapply D E aa w q /\
                          emeet D E B leq q (bvalf_HS D E B leq w1 X
                                             ((x |-> w) v) p) m
                          ==> eapply D E sn w m) /\
                 (!z. z IN D
                      ==> (E z sn <=>
                           ?w q e m. w IN D /\ q IN D /\ e IN D /\ m IN D /\
                                     eapply D E aa w q /\
                                     bval_HS D E B leq w1 X ((x |-> w) v) p e /\
                                     emeet D E B leq q e m /\
                                     eopair D (E:A->A->bool) w m z))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (aa:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `!i:num. bname D (E:A->A->bool) B (((v):num->A) i)`
      ASSUME_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC HSNAME_BNAME THEN
    MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[valuation]; ALL_TAC]) THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `eisfun D (E:A->A->bool) aa` (LABEL_TAC "aisf") THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`aa:A`]
                 BNAME_ISFUN) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;`X:A`;
                 `v:num->A`;`p:form`;
    `x:num`;`aa:A`] ESEPNAME_RAW_HS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `sn:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (LABEL_TAC "raw"))) THEN
  SUBGOAL_THEN
   `!w:A. w IN D /\ eindom D (E:A->A->bool) aa w
          ==> hsname D E B w1 X w /\
              valuation D ((x |-> w) (v:num->A)) /\
              (!i. hsname D E B w1 X (((x |-> w) (v:num->A)) i)) /\
              (bvalf_HS D E B leq w1 X ((x |-> w) v) p) IN D /\
              E (bvalf_HS D E B leq w1 X ((x |-> w) v) p) B /\
              bval_HS D E B leq w1 X ((x |-> w) v) p
                  (bvalf_HS D E B leq w1 X ((x |-> w) v) p)`
   (LABEL_TAC "wprops") THENL
   [X_GEN_TAC `w:A` THEN STRIP_TAC THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (w:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  
    SUBGOAL_THEN `hsname D (E:A->A->bool) B w1 X w` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;`aa:A`;`w:A`]
           HSNAME_DOM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN(ACCEPT_TAC o
        CONJUNCT2)]; ALL_TAC] THEN
    TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (w:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  SUBGOAL_THEN
     `valuation D ((x |-> w) (v:num->A)) /\
      (!i. hsname D (E:A->A->bool) B w1 X (((x |-> w) (v:num->A)) i))`
    STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC HSNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                     `leq:A`;`w1:A`;`X:A`;
        `(x |-> w) (v:num->A)`] BVALF_HS_SPEC) THEN ASM_SIMP_TAC[];
      CONJ_TAC THENL
       [MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                       `leq:A`;`w1:A`;`X:A`;
          `(x |-> w) (v:num->A)`] BVALF_HS_IN_B) THEN ASM_SIMP_TAC[];
        MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                       `leq:A`;`w1:A`;`X:A`;
          `(x |-> w) (v:num->A)`] BVALF_HS_SPEC) THEN ASM_SIMP_TAC[]]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!w q m. w IN D /\ q IN D /\ eindom D (E:A->A->bool) aa w /\
            eapply D E aa w q /\
            emeet D E B leq q (bvalf_HS D E B leq w1 X ((x |-> w) v) p) m
            ==> eapply D E sn w m`
   (LABEL_TAC "link") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    USE_THEN "wprops" (MP_TAC o SPEC `w:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN STRIP_TAC THEN
    SUBGOAL_THEN `(m:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`m:A`] EOPAIR_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_TAC `z:A`) THEN
    SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
     [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
    REWRITE_TAC[eapply] THEN EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "raw" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MAP_EVERY EXISTS_TAC [`w:A`;`q:A`;
      `bvalf_HS D (E:A->A->bool) B leq w1 X ((x |-> w) v) p`;`m:A`] THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  EXISTS_TAC `sn:A` THEN REPEAT CONJ_TAC THENL
   [FIRST_ASSUM ACCEPT_TAC;
    REWRITE_TAC[eisfun] THEN REPEAT CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      X_GEN_TAC `z:A` THEN STRIP_TAC THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (z:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  
      USE_THEN "raw" (MP_TAC o SPEC `z:A`) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) z sn`))) THEN
      DISCH_THEN(X_CHOOSE_THEN `w:A` (X_CHOOSE_THEN `q:A`
        (X_CHOOSE_THEN `e:A` (X_CHOOSE_THEN `m:A` STRIP_ASSUME_TAC)))) THEN
      MAP_EVERY EXISTS_TAC [`w:A`;`m:A`] THEN ASM_REWRITE_TAC[];
      REPEAT GEN_TAC THEN STRIP_TAC THEN
      SUBGOAL_THEN `(z:A) IN D /\ (z':A) IN D` STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      SUBGOAL_THEN
       `?ww1 q1 e1 m1. ww1 IN D /\ q1 IN D /\ e1 IN D /\ m1 IN D /\
                      eapply D (E:A->A->bool) aa ww1 q1 /\
                      bval_HS D E B leq w1 X ((x |-> ww1) v) p e1 /\
                      emeet D E B leq q1 e1 m1 /\ eopair D E ww1 m1 z`
      STRIP_ASSUME_TAC THENL
       [USE_THEN "raw" (fun th -> ACCEPT_TAC(EQ_MP
          (MATCH_MP th (ASSUME `(z:A) IN D`)) (ASSUME `(E:A->A->bool) z sn`)));
        ALL_TAC] THEN
      SUBGOAL_THEN
       `?w2 q2 e2 m2. w2 IN D /\ q2 IN D /\ e2 IN D /\ m2 IN D /\
                      eapply D (E:A->A->bool) aa w2 q2 /\
                      bval_HS D E B leq w1 X ((x |-> w2) v) p e2 /\
                      emeet D E B leq q2 e2 m2 /\ eopair D E w2 m2 z'`
      STRIP_ASSUME_TAC THENL
       [USE_THEN "raw" (fun th -> ACCEPT_TAC(EQ_MP
          (MATCH_MP th (ASSUME `(z':A) IN D`))
              (ASSUME `(E:A->A->bool) z' sn`)));
        ALL_TAC] THEN
      SUBGOAL_THEN `(u:A) = ww1 /\ (w:A) = m1` STRIP_ASSUME_TAC THENL
       [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`u:A`;`w:A`;
                       `ww1:A`;`m1:A`;`z:A`]
          EOPAIR_INJ) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `(u:A) = w2 /\ (w':A) = m2` STRIP_ASSUME_TAC THENL
       [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`u:A`;`w':A`;
                       `w2:A`;`m2:A`;`z':A`]
          EOPAIR_INJ) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `(w2:A) = ww1` SUBST_ALL_TAC THENL
       [ASM_MESON_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `valuation D ((x |-> ww1) (v:num->A))` ASSUME_TAC THENL
       [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `(q2:A) = q1` SUBST_ALL_TAC THENL
       [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`aa:A`;`ww1:A`;`q2:A`;`q1:A`]
          EAPPLY_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `(e2:A) = e1` SUBST_ALL_TAC THENL
       [MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                       `leq:A`;`w1:A`;`X:A`;
          `(x |-> ww1) (v:num->A)`;`e2:A`;`e1:A`] BVAL_HS_UNIQUE) THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `(m2:A) = m1` SUBST_ALL_TAC THENL
       [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`q1:A`;`e1:A`;
          `m2:A`;`m1:A`] EMEET_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      ASM_REWRITE_TAC[]];
    X_GEN_TAC `w:A` THEN DISCH_TAC THEN REWRITE_TAC[eindom] THEN EQ_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `mm:A` (CONJUNCTS_THEN2 ASSUME_TAC
        (MP_TAC o REWRITE_RULE[eapply]))) THEN
      DISCH_THEN(X_CHOOSE_THEN `z:A` (CONJUNCTS_THEN2 ASSUME_TAC
          ASSUME_TAC)) THEN
      SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
       [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
      SUBGOAL_THEN
       `?ww1 q1 e1 m1. ww1 IN D /\ q1 IN D /\ e1 IN D /\ m1 IN D /\
                      eapply D (E:A->A->bool) aa ww1 q1 /\
                      bval_HS D E B leq w1 X ((x |-> ww1) v) p e1 /\
                      emeet D E B leq q1 e1 m1 /\ eopair D E ww1 m1 z`
      STRIP_ASSUME_TAC THENL
       [USE_THEN "raw" (fun th -> ACCEPT_TAC(EQ_MP
          (MATCH_MP th (ASSUME `(z:A) IN D`)) (ASSUME `(E:A->A->bool) z sn`)));
        ALL_TAC] THEN
      SUBGOAL_THEN `(w:A) = ww1 /\ (mm:A) = m1` STRIP_ASSUME_TAC THENL
       [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`mm:A`;
                       `ww1:A`;`m1:A`;`z:A`]
          EOPAIR_INJ) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      EXISTS_TAC `q1:A` THEN ASM_REWRITE_TAC[];
      DISCH_THEN(X_CHOOSE_THEN `q:A` (CONJUNCTS_THEN2 ASSUME_TAC
          ASSUME_TAC)) THEN
      SUBGOAL_THEN `eindom D (E:A->A->bool) aa w` ASSUME_TAC THENL
       [REWRITE_TAC[eindom] THEN EXISTS_TAC `q:A` THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      USE_THEN "wprops" (MP_TAC o SPEC `w:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN STRIP_TAC THEN
      SUBGOAL_THEN `(E:A->A->bool) q B` ASSUME_TAC THENL
       [UNDISCH_TAC `eapply D (E:A->A->bool) aa w q` THEN
        REWRITE_TAC[eapply] THEN
        DISCH_THEN(X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC) THEN
        SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
         [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
        MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`aa:A`;`z:A`]
          BNAME_MEM_PAIR) THEN
        ASM_REWRITE_TAC[] THEN
        DISCH_THEN(X_CHOOSE_THEN `w'':A` (X_CHOOSE_THEN `q'':A`
            STRIP_ASSUME_TAC)) THEN
        SUBGOAL_THEN `(w:A) = w'' /\ (q:A) = q''` STRIP_ASSUME_TAC THENL
         [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`q:A`;
                         `w'':A`;`q'':A`;`z:A`]
            EOPAIR_INJ) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
        ASM_MESON_TAC[]; ALL_TAC] THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`q:A`;
        `bvalf_HS D (E:A->A->bool) B leq w1 X ((x |-> w) v) p`] EBALG_MEET) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_TAC `m:A`) THEN
      SUBGOAL_THEN `(m:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
      EXISTS_TAC `m:A` THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "link" (MATCH_MP_TAC o SPECL [`w:A`;`q:A`;`m:A`]) THEN
      ASM_REWRITE_TAC[]];
    USE_THEN "link" ACCEPT_TAC;
    USE_THEN "raw" ACCEPT_TAC]);;

let ESEPNAME_BNAME_HS = prove
 (`!D (E:A->A->bool) B leq w1 X v p x aa sn.
        model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
        aa IN D /\ bname D E B aa /\
        sn IN D /\ eisfun D E sn /\
        (!z. z IN D
             ==> (E z sn <=>
                  ?w q e m. w IN D /\ q IN D /\ e IN D /\ m IN D /\
                            eapply D E aa w q /\
                            bval_HS D E B leq w1 X ((x |-> w) v) p e /\
                            emeet D E B leq q e m /\
                            eopair D (E:A->A->bool) w m z))
        ==> bname D E B sn`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
             (CONJUNCTS_THEN2 (LABEL_TAC "ecba")
    (CONJUNCTS_THEN2 (LABEL_TAC "BD") (CONJUNCTS_THEN2 (LABEL_TAC "leqD")
     (CONJUNCTS_THEN2 (LABEL_TAC "aaD") (CONJUNCTS_THEN2 (LABEL_TAC "bnaa")
      (CONJUNCTS_THEN2 (LABEL_TAC "snD") (CONJUNCTS_THEN2 (LABEL_TAC "isf")
       (LABEL_TAC "snch"))))))))) THEN
  USE_THEN "bnaa" (X_CHOOSE_THEN `ax:A`
                   (X_CHOOSE_THEN `yx:A` STRIP_ASSUME_TAC) o
                  REWRITE_RULE[bname]) THEN
  SUBGOAL_THEN `!wi:A. wi IN D /\ eindom D (E:A->A->bool) aa wi ==> E wi yx`
   (LABEL_TAC "Wsub") THENL
   [X_GEN_TAC `wi:A` THEN STRIP_TAC THEN
    UNDISCH_TAC `eindom D (E:A->A->bool) aa wi` THEN REWRITE_TAC[eindom] THEN
    DISCH_THEN(X_CHOOSE_THEN `qw:A` STRIP_ASSUME_TAC) THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`ax:A`;`yx:A`;`aa:A`;
      `wi:A`;`qw:A`] STAGE_DOM_CLOSED) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`ax:A`] ESUC_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `sa:A`) THEN
  SUBGOAL_THEN `(sa:A) IN D /\ eordinal D (E:A->A->bool) sa /\
      (E:A->A->bool) ax sa`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_IN; EORDINAL_ESUC; ESUC_MEMBER]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`sa:A`] EBNSTAGE_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_THEN `ysa:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`sa:A`;`ysa:A`]
         EBNSTAGE_CHAR) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ww1:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 (LABEL_TAC "w1ch") ASSUME_TAC))) THEN
  SUBGOAL_THEN `!u:A. u IN D /\ (E:A->A->bool) u yx
      ==> E u ww1` (LABEL_TAC "Ysub") THENL
   [X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    USE_THEN "w1ch" (MP_TAC o SPEC `u:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MAP_EVERY EXISTS_TAC [`ax:A`;`yx:A`] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`ww1:A`;`B:A`] ECROSS_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `cr:A` (LABEL_TAC "cr")) THEN
  SUBGOAL_THEN `(cr:A) IN D` ASSUME_TAC THENL
   [USE_THEN "cr" (MP_TAC o REWRITE_RULE[ecross]) THEN SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) sn cr` ASSUME_TAC THENL
   [REWRITE_TAC[esubset] THEN X_GEN_TAC `z:A` THEN STRIP_TAC THEN
    USE_THEN "cr" (MP_TAC o SPEC `z:A` o CONJUNCT2 o REWRITE_RULE[ecross]) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "snch" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) z sn`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `wi:A` (X_CHOOSE_THEN `qi:A`
      (X_CHOOSE_THEN `ei:A` (X_CHOOSE_THEN `mi:A` STRIP_ASSUME_TAC)))) THEN
    SUBGOAL_THEN `eindom D (E:A->A->bool) aa wi` ASSUME_TAC THENL
     [REWRITE_TAC[eindom] THEN EXISTS_TAC `qi:A` THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) wi ww1` ASSUME_TAC THENL
     [USE_THEN "Ysub" MATCH_MP_TAC THEN CONJ_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC;
        USE_THEN "Wsub" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) mi B` ASSUME_TAC THENL
     [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`wi:A`;`mi:A`] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `ebnmem D (E:A->A->bool) B ww1 sn` ASSUME_TAC THENL
   [REWRITE_TAC[ebnmem] THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `cr:A` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) sn ysa` ASSUME_TAC THENL
   [UNDISCH_TAC `ebnfuns D (E:A->A->bool) B ww1 ysa` THEN
    REWRITE_TAC[ebnfuns] THEN
    DISCH_THEN(MP_TAC o SPEC `sn:A` o CONJUNCT2) THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[bname] THEN MAP_EVERY EXISTS_TAC [`sa:A`;`ysa:A`] THEN
  ASM_REWRITE_TAC[]);;

(* ===================================================================== *)
(* H4.8b : SEPARATION, symmetry of the separation name.  BVALF_HS_EQUIV:   *)
(* autB maps [[p]]^HS_{(x|->w)v} to [[p]]^HS_{(x|->w')v} when eautn w w'   *)
(* and the other FREE parameters are fixed (SYM_BVALF_HS_PERM on a chosen  *)
(* image valuation + BVALF_HS_FV_CONG).  SEP_SYM: the separation name of   *)
(* a fixed aa is fixed.  HS_SEPNAME: the separation name is an HS name.    *)
(* ===================================================================== *)
let BVALF_HS_EQUIV = prove
 (`!p D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X s muci
  muP autB v x w w'.
     hsbundle D E w1 om tw ii ci P leqp B inclB onebee X /\
     s IN D /\ eperm D E w1 s /\ pbundle D E ci P leqp B inclB s
         muci muP autB /\
     valuation D v /\ (!i. hsname D E B w1 X (v i)) /\
     (!i. i IN FV p /\ ~(i = x) ==> eautn D E B autB (v i) (v i)) /\
     w IN D /\ hsname D E B w1 X w /\ eautn D E B autB w w'
     ==> eapply D E autB (bvalf_HS D E B inclB w1 X ((x |-> w) v) p)
                         (bvalf_HS D E B inclB w1 X ((x |-> w') v) p)`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "hsb")
             (CONJUNCTS_THEN2 (LABEL_TAC "sD")
              (CONJUNCTS_THEN2 (LABEL_TAC "sperm")
               (CONJUNCTS_THEN2 (LABEL_TAC "pb")
                (CONJUNCTS_THEN2 (LABEL_TAC "vv")
                 (CONJUNCTS_THEN2 (LABEL_TAC "hsv")
                  (CONJUNCTS_THEN2 (LABEL_TAC "vfix")
                   (CONJUNCTS_THEN2 (LABEL_TAC "wD")
                    (CONJUNCTS_THEN2 (LABEL_TAC "hsw")
                     (LABEL_TAC "aww'")))))))))) THEN
  USE_THEN "hsb" (MP_TAC o MATCH_MP HSB_CBA) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "cba")
             (CONJUNCTS_THEN2 (LABEL_TAC "inclD") (LABEL_TAC "leqpD"))) THEN
  USE_THEN "hsb" (MP_TAC o REWRITE_RULE[hsbundle]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
             (CONJUNCTS_THEN2 (LABEL_TAC "vl")
              (CONJUNCTS_THEN2 (LABEL_TAC "eom")
               (CONJUNCTS_THEN2 (LABEL_TAC "w1D")
                (CONJUNCTS_THEN2 (LABEL_TAC "w1card")
                 (CONJUNCTS_THEN2 (LABEL_TAC "omw1e")
                  (CONJUNCTS_THEN2 (LABEL_TAC "w1min")
                   (CONJUNCTS_THEN2 (LABEL_TAC "cr1")
                    (CONJUNCTS_THEN2 (LABEL_TAC "cr2")
                     (CONJUNCTS_THEN2 (LABEL_TAC "ftw")
                      (CONJUNCTS_THEN2 (LABEL_TAC "coh")
                       (CONJUNCTS_THEN2 (LABEL_TAC "leq")
                        (CONJUNCTS_THEN2 (LABEL_TAC "ros")
                         (CONJUNCTS_THEN2 (LABEL_TAC "inc")
                          (CONJUNCTS_THEN2 (LABEL_TAC "porder")
      (CONJUNCTS_THEN2 (LABEL_TAC "top")
       (CONJUNCTS_THEN2 (LABEL_TAC "oneD")
        (CONJUNCTS_THEN2 (LABEL_TAC "BD")
         (CONJUNCTS_THEN2 (LABEL_TAC "oneB")
          (CONJUNCTS_THEN2 (LABEL_TAC "XD")
           (CONJUNCTS_THEN2 (LABEL_TAC "ciX")
            (LABEL_TAC "PX")))))))))))))))))))))) THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B inclB /\ eporder D E B inclB`
   (CONJUNCTS_THEN2 (LABEL_TAC "balg") (LABEL_TAC "pord")) THENL
   [USE_THEN "cba" (fun th -> let b = MATCH_MP ECBA_IMP_BALG th in
      ACCEPT_TAC(CONJ b (MATCH_MP EBALG_IMP_PORDER b)));
    ALL_TAC] THEN
  USE_THEN "pb" (fun th -> let cs = CONJUNCTS(REWRITE_RULE[pbundle] th) in
    LABEL_TAC "autBD" (el 2 cs) THEN LABEL_TAC "bijB" (el 5 cs) THEN
    LABEL_TAC "presB" (el 10 cs)) THEN
  USE_THEN "bijB" (fun th -> let cs = CONJUNCTS(REWRITE_RULE[ebij] th) in
    LABEL_TAC "bijtot" (el 2 cs) THEN LABEL_TAC "bijsv" (el 3 cs)) THEN
  SUBGOAL_THEN `(w':A) IN D` (LABEL_TAC "w'D") THENL
   [USE_THEN "aww'" (ACCEPT_TAC o CONJUNCT2 o MATCH_MP AUTN_IMP); ALL_TAC] THEN
  SUBGOAL_THEN `hsname D (E:A->A->bool) B w1 X w'` (LABEL_TAC "hsw'") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;`ii:A`;`ci:A`;
                  `P:A`;`leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`s:A`;
       `muci:A`;`muP:A`;`autB:A`;`w:A`;`w':A`] AUTN_HS) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `!i. ?y. y IN D /\ eautn D (E:A->A->bool) B autB ((v:num->A) i)
      y` (LABEL_TAC "tot") THENL
   [X_GEN_TAC `i:num` THEN MATCH_MP_TAC AUTN_TOTAL THEN REPEAT CONJ_TAC THEN
    TRY(FIRST_ASSUM ACCEPT_TAC) THENL
     [USE_THEN "vv" (ACCEPT_TAC o SPEC `i:num` o REWRITE_RULE[valuation]);
      MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
      REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THENL
       [USE_THEN "vv" (ACCEPT_TAC o SPEC `i:num` o REWRITE_RULE[valuation]);
        USE_THEN "hsv" (ACCEPT_TAC o SPEC `i:num`)]];
    ALL_TAC] THEN
  ABBREV_TAC `vi = \i. if i = x then (w':A) else @y. y IN D /\
      eautn D (E:A->A->bool) B autB ((v:num->A) i) y` THEN
  SUBGOAL_THEN
   `!i. ~(i = x) ==> (vi:num->A) i IN D /\
       eautn D (E:A->A->bool) B autB ((v:num->A) i) (vi i)`
   (LABEL_TAC "visel") THENL
   [X_GEN_TAC `i:num` THEN DISCH_TAC THEN EXPAND_TAC "vi" THEN BETA_TAC THEN
    ASM_REWRITE_TAC[] THEN CONV_TAC SELECT_CONV THEN
        USE_THEN "tot" (ACCEPT_TAC o SPEC `i:num`);
    ALL_TAC] THEN
  SUBGOAL_THEN `(vi:num->A) x = w'` (LABEL_TAC "vix") THENL
   [EXPAND_TAC "vi" THEN REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D (vi:num->A)` (LABEL_TAC "vvi") THENL
   [REWRITE_TAC[valuation] THEN X_GEN_TAC `i:num` THEN
    ASM_CASES_TAC `i:num = x` THENL
     [ASM_REWRITE_TAC[] THEN USE_THEN "w'D" ACCEPT_TAC;
      USE_THEN "visel" (MP_TAC o SPEC `i:num`) THEN ANTS_TAC THENL
          [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(ACCEPT_TAC o CONJUNCT1)];
    ALL_TAC] THEN
  SUBGOAL_THEN `!i. eautn D (E:A->A->bool) B autB (((x |-> (w:A)) (v:num->A)) i)
      ((vi:num->A) i)`
   (LABEL_TAC "vvrel") THENL
   [X_GEN_TAC `i:num` THEN REWRITE_TAC[VALMOD] THEN COND_CASES_TAC THENL
     [ASM_REWRITE_TAC[] THEN USE_THEN "aww'" ACCEPT_TAC;
      USE_THEN "visel" (MP_TAC o SPEC `i:num`) THEN ANTS_TAC THENL
          [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(ACCEPT_TAC o CONJUNCT2)];
    ALL_TAC] THEN
  SUBGOAL_THEN `!i. hsname D (E:A->A->bool) B w1 X ((vi:num->A) i)`
      (LABEL_TAC "hsvi") THENL
   [X_GEN_TAC `i:num` THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;`ii:A`;`ci:A`;
                  `P:A`;`leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`s:A`;
        `muci:A`;`muP:A`;`autB:A`;`((x |-> (w:A)) (v:num->A)) i`;
        `(vi:num->A) i`] AUTN_HS) THEN
    ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THENL
     [REWRITE_TAC[VALMOD] THEN COND_CASES_TAC THEN
      TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      USE_THEN "vv" (ACCEPT_TAC o SPEC `i:num` o REWRITE_RULE[valuation]);
      REWRITE_TAC[VALMOD] THEN COND_CASES_TAC THEN
          TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      USE_THEN "hsv" (ACCEPT_TAC o SPEC `i:num`);
      USE_THEN "vvrel" (ACCEPT_TAC o SPEC `i:num`)];
    ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((x |-> (w:A)) (v:num->A)) /\
                  (!i. hsname D (E:A->A->bool) B w1 X (((x |-> (w:A)) v) i))`
     (CONJUNCTS_THEN2 (LABEL_TAC "vw") (LABEL_TAC "hvw")) THENL
     [CONJ_TAC THENL
       [MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
        MATCH_MP_TAC HSNAMEVAL_VALMOD THEN CONJ_TAC THEN
            FIRST_ASSUM ACCEPT_TAC];
      ALL_TAC] THEN
  MP_TAC(SPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;`ii:A`;
                `ci:A`;`P:A`;`leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`s:A`;
      `muci:A`;`muP:A`;`autB:A`;`(x |-> (w:A)) (v:num->A)`;`vi:num->A`]
      SYM_BVALF_HS_PERM) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  MATCH_MP_TAC(MESON[] `(b:A) = c ==> eapply D E autB a b
               ==> eapply D E autB a c`) THEN
  MATCH_MP_TAC BVALF_HS_FV_CONG THEN REPEAT CONJ_TAC THEN
  FIRST [FIRST_ASSUM ACCEPT_TAC;
         MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THEN
             FIRST_ASSUM ACCEPT_TAC;
         MATCH_MP_TAC HSNAMEVAL_VALMOD THEN CONJ_TAC THEN
             FIRST_ASSUM ACCEPT_TAC;
         ALL_TAC] THEN
  X_GEN_TAC `i:num` THEN DISCH_TAC THEN REWRITE_TAC[VALMOD] THEN
      COND_CASES_TAC THENL
   [ASM_REWRITE_TAC[] THEN USE_THEN "vix" ACCEPT_TAC; ALL_TAC] THEN
  USE_THEN "visel" (MP_TAC o SPEC `i:num`) THEN ANTS_TAC THENL
      [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "viD") (LABEL_TAC "avi")) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`(v:num->A) i`;
                `(vi:num->A) i`;`(v:num->A) i`] AUTN_SV) THEN
  ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
  REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
  USE_THEN "vfix" MATCH_MP_TAC THEN CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC);;

let SEP_SYM = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X s muci muP
  autB v p x aa sn.
     hsbundle D E w1 om tw ii ci P leqp B inclB onebee X /\
     s IN D /\ eperm D E w1 s /\ pbundle D E ci P leqp B inclB s
         muci muP autB /\
     valuation D v /\ (!i. hsname D E B w1 X (v i)) /\
     (!i. i IN FV p /\ ~(i = x) ==> eautn D E B autB (v i) (v i)) /\
     aa IN D /\ hsname D E B w1 X aa /\ eautn D E B autB aa aa /\
     sn IN D /\ bname D E B sn /\
     (!z. z IN D ==> (E z sn <=>
                 ?w q e m. w IN D /\ q IN D /\ e IN D /\ m IN D /\
                           eapply D E aa w q /\
                           bval_HS D E B inclB w1 X ((x |-> w) v) p e /\
                           emeet D E B inclB q e m /\
                           eopair D (E:A->A->bool) w m z))
     ==> eautn D E B autB sn sn`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "hsb")
             (CONJUNCTS_THEN2 (LABEL_TAC "sD")
              (CONJUNCTS_THEN2 (LABEL_TAC "sperm")
               (CONJUNCTS_THEN2 (LABEL_TAC "pb")
                (CONJUNCTS_THEN2 (LABEL_TAC "vv")
                 (CONJUNCTS_THEN2 (LABEL_TAC "hsv")
                  (CONJUNCTS_THEN2 (LABEL_TAC "vfix")
                   (CONJUNCTS_THEN2 (LABEL_TAC "aaD")
                    (CONJUNCTS_THEN2 (LABEL_TAC "hsaa")
                     (CONJUNCTS_THEN2 (LABEL_TAC "faa")
                      (CONJUNCTS_THEN2 (LABEL_TAC "snD")
                       (CONJUNCTS_THEN2 (LABEL_TAC "bnsn")
                        (LABEL_TAC "snch"))))))))))))) THEN
  USE_THEN "hsb" (MP_TAC o MATCH_MP HSB_CBA) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "cba")
             (CONJUNCTS_THEN2 (LABEL_TAC "inclD") (LABEL_TAC "leqpD"))) THEN
  USE_THEN "hsb" (MP_TAC o REWRITE_RULE[hsbundle]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
             (CONJUNCTS_THEN2 (LABEL_TAC "vl")
              (CONJUNCTS_THEN2 (LABEL_TAC "eom")
               (CONJUNCTS_THEN2 (LABEL_TAC "w1D")
                (CONJUNCTS_THEN2 (LABEL_TAC "w1card")
                 (CONJUNCTS_THEN2 (LABEL_TAC "omw1e")
                  (CONJUNCTS_THEN2 (LABEL_TAC "w1min")
                   (CONJUNCTS_THEN2 (LABEL_TAC "cr1")
                    (CONJUNCTS_THEN2 (LABEL_TAC "cr2")
                     (CONJUNCTS_THEN2 (LABEL_TAC "ftw")
                      (CONJUNCTS_THEN2 (LABEL_TAC "coh")
                       (CONJUNCTS_THEN2 (LABEL_TAC "leq")
                        (CONJUNCTS_THEN2 (LABEL_TAC "ros")
                         (CONJUNCTS_THEN2 (LABEL_TAC "inc")
                          (CONJUNCTS_THEN2 (LABEL_TAC "porder")
      (CONJUNCTS_THEN2 (LABEL_TAC "top")
       (CONJUNCTS_THEN2 (LABEL_TAC "oneD")
        (CONJUNCTS_THEN2 (LABEL_TAC "BD")
         (CONJUNCTS_THEN2 (LABEL_TAC "oneB")
          (CONJUNCTS_THEN2 (LABEL_TAC "XD")
           (CONJUNCTS_THEN2 (LABEL_TAC "ciX")
            (LABEL_TAC "PX")))))))))))))))))))))) THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B inclB /\ eporder D E B inclB`
   (CONJUNCTS_THEN2 (LABEL_TAC "balg") (LABEL_TAC "pord")) THENL
   [USE_THEN "cba" (fun th -> let b = MATCH_MP ECBA_IMP_BALG th in
      ACCEPT_TAC(CONJ b (MATCH_MP EBALG_IMP_PORDER b)));
    ALL_TAC] THEN
  USE_THEN "pb" (fun th -> let cs = CONJUNCTS(REWRITE_RULE[pbundle] th) in
    LABEL_TAC "autBD" (el 2 cs) THEN LABEL_TAC "bijB" (el 5 cs) THEN
