       (CONJUNCTS_THEN2 (LABEL_TAC "easub") (LABEL_TAC "eafix"))))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;`ii:A`;`ci:A`;
                `P:A`;`leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`v:num->A`]
      PARAM_CSUPPORT) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    USE_THEN "vv" (ACCEPT_TAC o REWRITE_RULE[valuation]);
    ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `FV p`) THEN REWRITE_TAC[FV_FINITE] THEN
