        (CONJUNCTS_THEN2 (LABEL_TAC "eae") (LABEL_TAC "epe")))))) THEN
  SUBGOAL_THEN `ehssym D (E:A->A->bool) B w1 X sn` (LABEL_TAC "symsn") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;`ii:A`;`ci:A`;
                  `P:A`;`leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`sn:A`;`e:A`]
       EHSSYM_INTRO) THEN
    ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    X_GEN_TAC `s:A` THEN DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "sD")
      (CONJUNCTS_THEN2 (LABEL_TAC "sperm") (LABEL_TAC "sfix"))) THEN
    MAP_EVERY X_GEN_TAC [`muci:A`;`muP:A`;`autB:A`] THEN
    DISCH_THEN(fun th ->
      SUBGOAL_THEN `pbundle D (E:A->A->bool) ci P leqp B inclB s muci muP autB`
          (LABEL_TAC "pb")
      THENL [REWRITE_TAC[pbundle] THEN ACCEPT_TAC th; ALL_TAC]) THEN
    USE_THEN "pb" (fun th -> let cs = CONJUNCTS(REWRITE_RULE[pbundle] th) in
      LABEL_TAC "mucD" (el 0 cs) THEN LABEL_TAC "muPD" (el 1 cs) THEN
      LABEL_TAC "autBD" (el 2 cs) THEN LABEL_TAC "mch" (el 6 cs) THEN
      LABEL_TAC "Pch" (el 7 cs) THEN LABEL_TAC "ach" (el 8 cs)) THEN
    SUBGOAL_THEN `eautn D (E:A->A->bool) B autB aa aa` (LABEL_TAC "faa") THENL
     [USE_THEN "eafix" (MP_TAC o SPEC `s:A`) THEN
      ANTS_TAC THENL
       [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
        MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`s:A`;`e:A`;`ea:A`]
               EFIXES_SUBSET) THEN
        ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                        DISCH_THEN ACCEPT_TAC];
        ALL_TAC] THEN
      DISCH_THEN(MP_TAC o SPECL [`muci:A`;`muP:A`;`autB:A`]) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `!i. i IN FV p /\ ~(i = x)
        ==> eautn D (E:A->A->bool) B autB ((v:num->A) i) (v i)`
     (LABEL_TAC "vfix") THENL
     [X_GEN_TAC `i:num` THEN DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "ifv")
         (K ALL_TAC)) THEN
      USE_THEN "epfix" (MP_TAC o SPEC `s:A`) THEN
      ANTS_TAC THENL
       [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
        MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`s:A`;`e:A`;`ep:A`]
               EFIXES_SUBSET) THEN
        ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                        DISCH_THEN ACCEPT_TAC];
        ALL_TAC] THEN
      DISCH_THEN(MP_TAC o SPECL [`muci:A`;`muP:A`;`autB:A`]) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(MP_TAC o SPEC `i:num`) THEN
      ANTS_TAC THENL [USE_THEN "ifv" ACCEPT_TAC; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;`ii:A`;`ci:A`;
                  `P:A`;`leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`s:A`;
        `muci:A`;`muP:A`;`autB:A`;`v:num->A`;`p:form`;`x:num`;
                  `aa:A`;`sn:A`] SEP_SYM) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  (* sn lies in aa's own HS stage *)
  SUBGOAL_THEN `?a y. a IN D /\ y IN D /\ eordinal D (E:A->A->bool) a /\
                      hsstage D E B w1 X a y /\ E aa y`
   (X_CHOOSE_THEN `a:A` (X_CHOOSE_THEN `y:A` (CONJUNCTS_THEN2 (LABEL_TAC "aD")
     (CONJUNCTS_THEN2 (LABEL_TAC "yD") (CONJUNCTS_THEN2 (LABEL_TAC "aord")
       (CONJUNCTS_THEN2 (LABEL_TAC "hsay") (LABEL_TAC "aay"))))))) THENL
   [USE_THEN "hsaa" (ACCEPT_TAC o REWRITE_RULE[hsname]); ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;`a:A`;`y:A`]
         HSSTAGE_CHAR) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `w:A` (CONJUNCTS_THEN2 (LABEL_TAC "wD")
      (CONJUNCTS_THEN2 (LABEL_TAC "wch") (LABEL_TAC "wfuns")))) THEN
  USE_THEN "wfuns" (MP_TAC o SPEC `aa:A` o CONJUNCT2 o
                    REWRITE_RULE[ehsfuns]) THEN
  ANTS_TAC THENL [USE_THEN "aaD" ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> USE_THEN "aay" (MP_TAC o EQ_MP th)) THEN
  REWRITE_TAC[ehsmem; ebnmem] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (CONJUNCTS_THEN2 (K ALL_TAC) (X_CHOOSE_THEN `cr:A`
    (CONJUNCTS_THEN2 (LABEL_TAC "crD") (CONJUNCTS_THEN2 (LABEL_TAC "crx")
      (LABEL_TAC "aacr"))))) (K ALL_TAC)) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;`sn:A`;`a:A`;
                `y:A`] HSSTAGE_INTRO) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    X_GEN_TAC `z:A` THEN DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "zD")
        (LABEL_TAC "zsn")) THEN
    USE_THEN "snch" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [USE_THEN "zD" ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "zsn" (MP_TAC o EQ_MP th)) THEN
    DISCH_THEN(X_CHOOSE_THEN `w0:A` (X_CHOOSE_THEN `q:A`
        (X_CHOOSE_THEN `e0:A` (X_CHOOSE_THEN `m:A`
        (CONJUNCTS_THEN2 (LABEL_TAC "w0D")
         (CONJUNCTS_THEN2 (LABEL_TAC "qD")
          (CONJUNCTS_THEN2 (LABEL_TAC "e0D")
           (CONJUNCTS_THEN2 (LABEL_TAC "mD")
            (CONJUNCTS_THEN2 (LABEL_TAC "aw0q")
             (CONJUNCTS_THEN2 (LABEL_TAC "bve")
              (CONJUNCTS_THEN2 (LABEL_TAC "mmt")
               (LABEL_TAC "opw")))))))))))) THEN
    USE_THEN "aw0q" (MP_TAC o REWRITE_RULE[eapply]) THEN
    DISCH_THEN(X_CHOOSE_THEN `zz:A` (CONJUNCTS_THEN2 (LABEL_TAC "opzz")
        (LABEL_TAC "zzaa"))) THEN
    SUBGOAL_THEN `(zz:A) IN D` (LABEL_TAC "zzD") THENL
     [USE_THEN "opzz" (ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) zz cr` (LABEL_TAC "zzcr") THENL
     [USE_THEN "aacr" (MP_TAC o SPEC `zz:A` o REWRITE_RULE[esubset]) THEN
      ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`B:A`;`cr:A`;`zz:A`]
           ECROSS_MEMBER) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "zzcr" (MP_TAC o EQ_MP th)) THEN
    DISCH_THEN(X_CHOOSE_THEN `u0:A` (X_CHOOSE_THEN `c0:A`
        (CONJUNCTS_THEN2 (LABEL_TAC "u0D")
      (CONJUNCTS_THEN2 (LABEL_TAC "c0D") (CONJUNCTS_THEN2 (LABEL_TAC "u0w")
        (CONJUNCTS_THEN2 (K ALL_TAC) (LABEL_TAC "op0"))))))) THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w0:A`;`q:A`;`zz:A`;`u0:A`;`c0:A`]
           EOPAIR_FST_DET) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN SUBST_ALL_TAC THEN
    MAP_EVERY EXISTS_TAC [`u0:A`;`m:A`] THEN REPEAT CONJ_TAC THEN
        TRY(FIRST_ASSUM ACCEPT_TAC) THENL
     [USE_THEN "mmt" (ACCEPT_TAC o CONJUNCT2 o MATCH_MP EMEET_IN);
      USE_THEN "wch" (MP_TAC o SPEC `u0:A`) THEN
      ANTS_TAC THENL [USE_THEN "u0D" ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> USE_THEN "u0w" (MP_TAC o EQ_MP th)) THEN
      DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `zb:A`
          (CONJUNCTS_THEN2 (LABEL_TAC "bD")
        (CONJUNCTS_THEN2 (LABEL_TAC "zbD") (CONJUNCTS_THEN2 (LABEL_TAC "ba")
          (CONJUNCTS_THEN2 (LABEL_TAC "hsbz") (LABEL_TAC "u0zb"))))))) THEN
