    DISCH_THEN(LABEL_TAC "sny")] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;`a:A`;`y:A`;
                `sn:A`] HSNAME_STAGE) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                  DISCH_THEN ACCEPT_TAC]);;

(* ===================================================================== *)
(* H4.8c : BVALF_HS_SEPARATION -- [[separation_ax x a s p]]^HS = TOP.      *)
(* Witness: the HS separation name (ESEPNAME_EXISTS_HS + HS_SEPNAME).      *)
(* ===================================================================== *)
let BVALF_HS_SEPARATION = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X v x a s p.
      hsbundle D E w1 om tw ii ci P leqp B inclB onebee X /\
      valuation D v /\ (!i. hsname D E B w1 X (v i)) /\
      ~(a IN FV p) /\ ~(s IN FV p) /\
      ~(a = x) /\ ~(s = x) /\ ~(a = s)
      ==> etop D E B inclB (bvalf_HS D E B inclB w1 X v
                            (separation_ax x a s p))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  TRY(SUBGOAL_THEN `!i:num. bname D (E:A->A->bool) B (((v):num->A) i)`
      ASSUME_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC HSNAME_BNAME THEN
    MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[valuation]; ALL_TAC]) THEN
  FIRST_ASSUM(fun th -> let cs = CONJUNCTS(REWRITE_RULE[hsbundle] th)
                        and cb = CONJUNCTS(MATCH_MP HSB_CBA th) in
    MAP_EVERY ASSUME_TAC [el 0 cs; el 1 cs; el 3 cs; el 17 cs; el 19 cs;
                          el 0 cb; el 1 cb]) THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B inclB` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  REWRITE_TAC[separation_ax] THEN
  (* peel !!a -> aa *)
  MP_TAC(ISPECL [`a:num`; `?? s (!! x ((x %% s) <-> (x %% a) && p))`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;`X:A`;`v:num->A`]
        BVALF_HS_ALL_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  X_GEN_TAC `aa:A` THEN STRIP_TAC THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (aa:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  
  SUBGOAL_THEN `valuation D ((a |-> (aa:A)) (v:num->A)) /\
                (!i. hsname D E B w1 X (((a |-> (aa:A)) (v:num->A)) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC HSNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  TRY(SUBGOAL_THEN `!i:num. bname D (E:A->A->bool) B
      ((((a |-> (aa:A)) (v:num->A)):num->A) i)` ASSUME_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC HSNAME_BNAME THEN
    MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[valuation]; ALL_TAC]) THEN
  ABBREV_TAC `v0 = (a |-> (aa:A)) (v:num->A)` THEN
  (* build the separation name sn at v0 *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;`X:A`;
                 `v0:num->A`;`p:form`;
    `x:num`;`aa:A`] ESEPNAME_EXISTS_HS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `sn:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `hsname D (E:A->A->bool) B w1 X sn` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;`ii:A`;
                         `ci:A`;`P:A`;`leqp:A`;`B:A`;`inclB:A`;`onebee:A`;
       `X:A`;`v0:num->A`;
      `p:form`;`x:num`;`aa:A`;`sn:A`] HS_SEPNAME) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (sn:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  (* witness sn for ??s *)
  MATCH_MP_TAC(ISPECL [`s:num`; `!! x ((x %% s) <-> (x %% a) && p)`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;`X:A`;`v0:num->A`;`sn:A`]
        BVALF_HS_EX_TOP) THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `valuation D ((s |-> (sn:A)) (v0:num->A)) /\
                (!i. hsname D E B w1 X (((s |-> (sn:A)) (v0:num->A)) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC HSNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  TRY(SUBGOAL_THEN `!i:num. bname D (E:A->A->bool) B
      ((((s |-> (sn:A)) (v0:num->A)):num->A) i)` ASSUME_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC HSNAME_BNAME THEN
    MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[valuation]; ALL_TAC]) THEN
  ABBREV_TAC `v1 = (s |-> (sn:A)) (v0:num->A)` THEN
  (* peel !!x -> tt *)
  MP_TAC(ISPECL [`x:num`; `(x %% s) <-> (x %% a) && p`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;`X:A`;`v1:num->A`]
        BVALF_HS_ALL_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  X_GEN_TAC `tt:A` THEN STRIP_TAC THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (tt:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  
  SUBGOAL_THEN `valuation D ((x |-> (tt:A)) (v1:num->A)) /\
                (!i. hsname D E B w1 X (((x |-> (tt:A)) (v1:num->A)) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC HSNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  TRY(SUBGOAL_THEN `!i:num. bname D (E:A->A->bool) B
      ((((x |-> (tt:A)) (v1:num->A)):num->A) i)` ASSUME_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC HSNAME_BNAME THEN
    MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[valuation]; ALL_TAC]) THEN
  ABBREV_TAC `vv = (x |-> (tt:A)) (v1:num->A)` THEN
  (* vv lookups *)
  SUBGOAL_THEN `(vv:num->A) x = tt /\ (vv:num->A) s = sn /\ (vv:num->A) a = aa`
  STRIP_ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["vv";"v1";"v0"] THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER]; ALL_TAC] THEN
  (* IFF_TOP -> value-equality *)
  MP_TAC(ISPECL [`(x %% s):form`; `((x %% a) && p):form`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;`X:A`;`vv:num->A`]
        BVALF_HS_IFF_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  (* goal: bvalf_HS vv (x%%s) = bvalf_HS vv ((x%%a)&&p) *)
  SUBGOAL_THEN `ebv_in D (E:A->A->bool) B inclB tt sn
                  (bvalf_HS D E B inclB w1 X (vv:num->A) (x %% s))`
                      (LABEL_TAC "eins") THENL
   [MP_TAC(ISPECL [`x:num`;`s:num`;`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;
                   `w1:A`;`X:A`;`vv:num->A`]
      BVALF_HS_MEM) THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `ebv_in D (E:A->A->bool) B inclB tt aa
                  (bvalf_HS D E B inclB w1 X (vv:num->A) (x %% a))`
                      (LABEL_TAC "eina") THENL
   [MP_TAC(ISPECL [`x:num`;`a:num`;`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;
                   `w1:A`;`X:A`;`vv:num->A`]
      BVALF_HS_MEM) THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
  (* p-value congruence: bvalf_HS vv p = bvalf_HS ((x|->tt)v0) p (s not in FV *)
  (* p)                                                                       *)
  SUBGOAL_THEN `bvalf_HS D (E:A->A->bool) B inclB w1 X (vv:num->A) (p:form) =
                bvalf_HS D E B inclB w1 X ((x |-> (tt:A)) (v0:num->A)) (p:form)`
                    (LABEL_TAC "pveq") THENL
   [MATCH_MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;
                         `w1:A`;`X:A`;`vv:num->A`;
      `(x |-> (tt:A)) (v0:num->A)`] BVALF_HS_FV_CONG) THEN
    ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC HSNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[];
      X_GEN_TAC `i:num` THEN DISCH_TAC THEN
      SUBGOAL_THEN `~(i:num = s)` ASSUME_TAC THENL
          [ASM_MESON_TAC[]; ALL_TAC] THEN
      EXPAND_TAC "vv" THEN EXPAND_TAC "v1" THEN
      ASM_CASES_TAC `i:num = x` THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER]]; ALL_TAC] THEN
  (* and-meet: raw form, then rewrite the middle by pveq *)
  SUBGOAL_THEN `emeet D (E:A->A->bool) B inclB
      (bvalf_HS D E B inclB w1 X (vv:num->A) (x %% a))
                  (bvalf_HS D E B inclB w1 X (vv:num->A) (p:form))
                  (bvalf_HS D E B inclB w1 X (vv:num->A) ((x %% a) && p))`
                      (LABEL_TAC "emt0") THENL
   [MATCH_MP_TAC(ISPECL [`(x %% a):form`;`p:form`;`D:A->bool`;
                         `E:A->A->bool`;`B:A`;
      `inclB:A`;`w1:A`;`X:A`;`vv:num->A`] BVALF_HS_AND_MEET) THEN
          ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `emeet D (E:A->A->bool) B inclB
      (bvalf_HS D E B inclB w1 X (vv:num->A) (x %% a))
                  (bvalf_HS D E B inclB w1 X ((x |-> (tt:A))
                      (v0:num->A)) (p:form))
                  (bvalf_HS D E B inclB w1 X (vv:num->A) ((x %% a) && p))`
                      (LABEL_TAC "emt") THENL
   [USE_THEN "pveq" (fun th -> ONCE_REWRITE_TAC[GSYM th]) THEN
    USE_THEN "emt0" ACCEPT_TAC; ALL_TAC] THEN
  (* value-in-D facts *)
  SUBGOAL_THEN `(bvalf_HS D (E:A->A->bool) B inclB w1 X (vv:num->A) (x %% s)) IN
      D` (LABEL_TAC "zinD") THENL
   [MP_TAC(ISPECL [`(x %% s):form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;
                   `w1:A`;`X:A`;`vv:num->A`]
      BVALF_HS_SPEC) THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(bvalf_HS D (E:A->A->bool) B inclB w1 X (vv:num->A) (x %% a)) IN
      D` (LABEL_TAC "ziaD") THENL
   [MP_TAC(ISPECL [`(x %% a):form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;
                   `w1:A`;`X:A`;`vv:num->A`]
      BVALF_HS_SPEC) THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
  (* assemble via EBV_IN_SEP_HS *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;`X:A`;
                 `v0:num->A`;`p:form`;`x:num`;
    `aa:A`;`tt:A`;`sn:A`;
    `bvalf_HS D (E:A->A->bool) B inclB w1 X (vv:num->A) (x %% s)`;
    `bvalf_HS D (E:A->A->bool) B inclB w1 X (vv:num->A) (x %% a)`;
    `bvalf_HS D (E:A->A->bool) B inclB w1 X (vv:num->A) ((x %% a) && p)`]
        EBV_IN_SEP_HS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN ACCEPT_TAC);;

(* ===================================================================== *)
(* H4.9a : UNION, the union name is HS.  HSSTAGE_DOM (domain elements of a *)
(* stage member lie in strictly earlier stages); EUUVAL_EQUIV (euuval is   *)
(* autB-equivariant when x is autN-fixed: EAUTB_LUB on the combination     *)
(* sets); UNION_SYM (the union name of a fixed x is fixed); HS_UNIONNAME.  *)
(* ===================================================================== *)
let HSSTAGE_DOM = prove
 (`!D (E:A->A->bool) B w1 X a y f u.
     model D E ZF_AX /\ B IN D /\ w1 IN D /\ X IN D /\
     a IN D /\ y IN D /\ eordinal D E a /\ hsstage D E B w1 X a y /\
     f IN D /\ E f y /\ eindom D E f u
     ==> u IN D /\ ?b z. b IN D /\ z IN D /\ E b a /\
         hsstage D E B w1 X b z /\ E u z`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
             (CONJUNCTS_THEN2 (LABEL_TAC "BD")
              (CONJUNCTS_THEN2 (LABEL_TAC "w1D")
               (CONJUNCTS_THEN2 (LABEL_TAC "XD")
                (CONJUNCTS_THEN2 (LABEL_TAC "aD")
                 (CONJUNCTS_THEN2 (LABEL_TAC "yD")
                  (CONJUNCTS_THEN2 (LABEL_TAC "aord")
                   (CONJUNCTS_THEN2 (LABEL_TAC "hsay")
                    (CONJUNCTS_THEN2 (LABEL_TAC "fD")
                     (CONJUNCTS_THEN2 (LABEL_TAC "fy")
                      (MP_TAC o REWRITE_RULE[eindom]))))))))))) THEN
  DISCH_THEN(X_CHOOSE_THEN `c:A` (CONJUNCTS_THEN2 (LABEL_TAC "cD")
      (MP_TAC o REWRITE_RULE[eapply]))) THEN
  DISCH_THEN(X_CHOOSE_THEN `zz:A` (CONJUNCTS_THEN2 (LABEL_TAC "op")
      (LABEL_TAC "zzf"))) THEN
  SUBGOAL_THEN `(zz:A) IN D` (LABEL_TAC "zzD") THENL
   [USE_THEN "op" (ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;`a:A`;`y:A`]
         HSSTAGE_CHAR) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `w:A` (CONJUNCTS_THEN2 (LABEL_TAC "wD")
      (CONJUNCTS_THEN2 (LABEL_TAC "wch") (LABEL_TAC "wfuns")))) THEN
  USE_THEN "wfuns" (MP_TAC o SPEC `f:A` o CONJUNCT2 o
                    REWRITE_RULE[ehsfuns]) THEN
  ANTS_TAC THENL [USE_THEN "fD" ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> USE_THEN "fy" (MP_TAC o EQ_MP th)) THEN
  REWRITE_TAC[ehsmem; ebnmem] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (CONJUNCTS_THEN2 (K ALL_TAC) (X_CHOOSE_THEN `cr:A`
    (CONJUNCTS_THEN2 (LABEL_TAC "crD") (CONJUNCTS_THEN2 (LABEL_TAC "crx")
      (LABEL_TAC "fcr"))))) (K ALL_TAC)) THEN
  SUBGOAL_THEN `(E:A->A->bool) zz cr` (LABEL_TAC "zzcr") THENL
   [USE_THEN "fcr" (MP_TAC o SPEC `zz:A` o REWRITE_RULE[esubset]) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`B:A`;`cr:A`;`zz:A`]
         ECROSS_MEMBER) THEN
  ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> USE_THEN "zzcr" (MP_TAC o EQ_MP th)) THEN
  DISCH_THEN(X_CHOOSE_THEN `u0:A` (X_CHOOSE_THEN `c0:A`
      (CONJUNCTS_THEN2 (LABEL_TAC "u0D")
    (CONJUNCTS_THEN2 (LABEL_TAC "c0D") (CONJUNCTS_THEN2 (LABEL_TAC "u0w")
      (CONJUNCTS_THEN2 (K ALL_TAC) (LABEL_TAC "op0"))))))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`u:A`;`c:A`;`zz:A`;`u0:A`;`c0:A`]
         EOPAIR_FST_DET) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN SUBST_ALL_TAC THEN
  CONJ_TAC THENL [USE_THEN "u0D" ACCEPT_TAC; ALL_TAC] THEN
  USE_THEN "wch" (MP_TAC o SPEC `u0:A`) THEN
  ANTS_TAC THENL [USE_THEN "u0D" ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> USE_THEN "u0w" (ACCEPT_TAC o EQ_MP th)));;

let EUUVAL_EQUIV = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X sg muci muP
  autB x s0 s0' q q'.
     hsbundle D E w1 om tw ii ci P leqp B inclB onebee X /\
     sg IN D /\ eperm D E w1 sg /\ pbundle D E ci P leqp B inclB sg
         muci muP autB /\
     x IN D /\ hsname D E B w1 X x /\ eautn D E B autB x x /\
     s0 IN D /\ eautn D E B autB s0 s0' /\
     euuval D E B inclB x s0 q /\ euuval D E B inclB x s0' q'
     ==> eapply D E autB q q'`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "hsb")
             (CONJUNCTS_THEN2 (LABEL_TAC "sgD")
              (CONJUNCTS_THEN2 (LABEL_TAC "sgperm")
               (CONJUNCTS_THEN2 (LABEL_TAC "pb")
                (CONJUNCTS_THEN2 (LABEL_TAC "xD")
                 (CONJUNCTS_THEN2 (LABEL_TAC "hsx")
                  (CONJUNCTS_THEN2 (LABEL_TAC "fx")
                   (CONJUNCTS_THEN2 (LABEL_TAC "s0D")
                    (CONJUNCTS_THEN2 (LABEL_TAC "as0")
                     (CONJUNCTS_THEN2 (LABEL_TAC "uq")
                      (LABEL_TAC "uq'"))))))))))) THEN
  USE_THEN "hsb" (MP_TAC o MATCH_MP HSB_CBA) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "cba")
             (CONJUNCTS_THEN2 (LABEL_TAC "inclD") (LABEL_TAC "leqpD"))) THEN
  USE_THEN "hsb" (MP_TAC o REWRITE_RULE[hsbundle]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
             (CONJUNCTS_THEN2 (LABEL_TAC "vl")
              (CONJUNCTS_THEN2 (LABEL_TAC "eom")
               (CONJUNCTS_THEN2 (LABEL_TAC "w1D")
                (CONJUNCTS_THEN2 (LABEL_TAC "w1card")
                 (CONJUNCTS_THEN2 (LABEL_TAC "omw1e")
                  (CONJUNCTS_THEN2 (LABEL_TAC "w1min")
                   (CONJUNCTS_THEN2 (LABEL_TAC "cr1")
                    (CONJUNCTS_THEN2 (LABEL_TAC "cr2")
                     (CONJUNCTS_THEN2 (LABEL_TAC "ftw")
                      (CONJUNCTS_THEN2 (LABEL_TAC "coh")
                       (CONJUNCTS_THEN2 (LABEL_TAC "leq")
                        (CONJUNCTS_THEN2 (LABEL_TAC "ros")
                         (CONJUNCTS_THEN2 (LABEL_TAC "inc")
                          (CONJUNCTS_THEN2 (LABEL_TAC "porder")
      (CONJUNCTS_THEN2 (LABEL_TAC "top")
       (CONJUNCTS_THEN2 (LABEL_TAC "oneD")
        (CONJUNCTS_THEN2 (LABEL_TAC "BD")
         (CONJUNCTS_THEN2 (LABEL_TAC "oneB")
          (CONJUNCTS_THEN2 (LABEL_TAC "XD")
           (CONJUNCTS_THEN2 (LABEL_TAC "ciX")
            (LABEL_TAC "PX")))))))))))))))))))))) THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B inclB /\ eporder D E B inclB`
   (CONJUNCTS_THEN2 (LABEL_TAC "balg") (LABEL_TAC "pord")) THENL
   [USE_THEN "cba" (fun th -> let b = MATCH_MP ECBA_IMP_BALG th in
      ACCEPT_TAC(CONJ b (MATCH_MP EBALG_IMP_PORDER b)));
    ALL_TAC] THEN
  USE_THEN "pb" (fun th -> let cs = CONJUNCTS(REWRITE_RULE[pbundle] th) in
    LABEL_TAC "autBD" (el 2 cs) THEN LABEL_TAC "bijB" (el 5 cs) THEN
    LABEL_TAC "presB" (el 10 cs)) THEN
  USE_THEN "bijB" (fun th -> let cs = CONJUNCTS(REWRITE_RULE[ebij] th) in
    LABEL_TAC "bijtot" (el 2 cs) THEN LABEL_TAC "bijsv" (el 3 cs)) THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B x` (LABEL_TAC "bnx") THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `(s0':A) IN D` (LABEL_TAC "s0'D") THENL
   [USE_THEN "as0" (ACCEPT_TAC o CONJUNCT2 o MATCH_MP AUTN_IMP); ALL_TAC] THEN
  USE_THEN "uq" (MP_TAC o REWRITE_RULE[euuval]) THEN
  DISCH_THEN(X_CHOOSE_THEN `S:A` (CONJUNCTS_THEN2
      (MP_TAC o REWRITE_RULE[euucombset]) (LABEL_TAC "Slub"))) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "SD") (LABEL_TAC "Sch")) THEN
  USE_THEN "uq'" (MP_TAC o REWRITE_RULE[euuval]) THEN
  DISCH_THEN(X_CHOOSE_THEN `S':A` (CONJUNCTS_THEN2
      (MP_TAC o REWRITE_RULE[euucombset]) (LABEL_TAC "S'lub"))) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "S'D") (LABEL_TAC "S'ch")) THEN
  SUBGOAL_THEN `(q:A) IN D /\ (E:A->A->bool) q B`
      (CONJUNCTS_THEN2 (LABEL_TAC "qD") (LABEL_TAC "qB")) THENL
   [USE_THEN "Slub" (ACCEPT_TAC o MATCH_MP ELUB_IN); ALL_TAC] THEN
  USE_THEN "bijtot" (MP_TAC o SPEC `q:A`) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `qi:A` (CONJUNCTS_THEN2 (LABEL_TAC "qiD")
      (CONJUNCTS_THEN2 (K ALL_TAC) (LABEL_TAC "aqi")))) THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) S B` (LABEL_TAC "SB") THENL
   [REWRITE_TAC[esubset] THEN X_GEN_TAC `c:A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "cD") (LABEL_TAC "cS")) THEN
    USE_THEN "Sch" (MP_TAC o SPEC `c:A`) THEN
    ANTS_TAC THENL [USE_THEN "cD" ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "cS" (MP_TAC o EQ_MP th)) THEN
    REWRITE_TAC[euucomb] THEN
    DISCH_THEN(X_CHOOSE_THEN `w:A` (X_CHOOSE_THEN `qw:A` (X_CHOOSE_THEN `ws:A`
      (CONJUNCTS_THEN2 (K ALL_TAC) (CONJUNCTS_THEN2 (K ALL_TAC)
          (CONJUNCTS_THEN2 (K ALL_TAC)
        (CONJUNCTS_THEN2 (K ALL_TAC) (CONJUNCTS_THEN2 (K ALL_TAC)
            (LABEL_TAC "mt"))))))))) THEN
    USE_THEN "mt" (ACCEPT_TAC o CONJUNCT2 o MATCH_MP EMEET_IN);
    ALL_TAC] THEN
  SUBGOAL_THEN `muPrel D (E:A->A->bool) autB S S'` (LABEL_TAC "mP") THENL
   [REWRITE_TAC[muPrel] THEN CONJ_TAC THENL
    [USE_THEN "S'D" ACCEPT_TAC; ALL_TAC] THEN
    X_GEN_TAC `yy:A` THEN DISCH_THEN(LABEL_TAC "yyD") THEN
    USE_THEN "S'ch" (MP_TAC o SPEC `yy:A`) THEN
    ANTS_TAC THENL [USE_THEN "yyD" ACCEPT_TAC; DISCH_THEN SUBST1_TAC] THEN
    REWRITE_TAC[euucomb] THEN EQ_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `w':A` (X_CHOOSE_THEN `qw':A`
         (X_CHOOSE_THEN `ws':A` (CONJUNCTS_THEN2 (LABEL_TAC "w'D")
         (CONJUNCTS_THEN2 (LABEL_TAC "qw'D")
          (CONJUNCTS_THEN2 (LABEL_TAC "ws'D")
           (CONJUNCTS_THEN2 (LABEL_TAC "axw'")
            (CONJUNCTS_THEN2 (LABEL_TAC "aw's0'") (LABEL_TAC "mt'"))))))))) THEN
      USE_THEN "axw'" (MP_TAC o REWRITE_RULE[eapply]) THEN
    DISCH_THEN(X_CHOOSE_THEN `z1:A` (CONJUNCTS_THEN2 (LABEL_TAC "op1")
        (LABEL_TAC "z1x"))) THEN
    SUBGOAL_THEN `(z1:A) IN D` (LABEL_TAC "z1D") THENL
     [USE_THEN "op1" (ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
