let UNION_SYM = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X sg muci
  muP autB x W un.
     hsbundle D E w1 om tw ii ci P leqp B inclB onebee X /\
     sg IN D /\ eperm D E w1 sg /\ pbundle D E ci P leqp B inclB sg
         muci muP autB /\
     x IN D /\ hsname D E B w1 X x /\ eautn D E B autB x x /\
     W IN D /\ (!t. t IN D ==> (E t W <=> ?w. w IN D /\ eindom D E x w /\
         eindom D E w t)) /\
     un IN D /\ bname D E B un /\
     (!z. z IN D ==> (E z un <=>
                ?s q. s IN D /\ q IN D /\ E s W /\ euuval D E B inclB x s q /\
                      eopair D (E:A->A->bool) s q z))
     ==> eautn D E B autB un un`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "hsb")
             (CONJUNCTS_THEN2 (LABEL_TAC "sgD")
              (CONJUNCTS_THEN2 (LABEL_TAC "sgperm")
               (CONJUNCTS_THEN2 (LABEL_TAC "pb")
                (CONJUNCTS_THEN2 (LABEL_TAC "xD")
                 (CONJUNCTS_THEN2 (LABEL_TAC "hsx")
                  (CONJUNCTS_THEN2 (LABEL_TAC "fx")
                   (CONJUNCTS_THEN2 (LABEL_TAC "WD")
                    (CONJUNCTS_THEN2 (LABEL_TAC "Wch")
                     (CONJUNCTS_THEN2 (LABEL_TAC "unD")
                      (CONJUNCTS_THEN2 (LABEL_TAC "bnun")
                       (LABEL_TAC "unch")))))))))))) THEN
  USE_THEN "hsb" (MP_TAC o MATCH_MP HSB_CBA) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "cba")
             (CONJUNCTS_THEN2 (LABEL_TAC "inclD") (LABEL_TAC "leqpD"))) THEN
  USE_THEN "hsb" (MP_TAC o REWRITE_RULE[hsbundle]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
             (CONJUNCTS_THEN2 (LABEL_TAC "vl")
              (CONJUNCTS_THEN2 (LABEL_TAC "eom")
               (CONJUNCTS_THEN2 (LABEL_TAC "w1D")
                (CONJUNCTS_THEN2 (LABEL_TAC "w1card")
                 (CONJUNCTS_THEN2 (LABEL_TAC "omw1e")
                  (CONJUNCTS_THEN2 (LABEL_TAC "w1min")
                   (CONJUNCTS_THEN2 (LABEL_TAC "cr1")
                    (CONJUNCTS_THEN2 (LABEL_TAC "cr2")
                     (CONJUNCTS_THEN2 (LABEL_TAC "ftw")
                      (CONJUNCTS_THEN2 (LABEL_TAC "coh")
                       (CONJUNCTS_THEN2 (LABEL_TAC "leq")
                        (CONJUNCTS_THEN2 (LABEL_TAC "ros")
                         (CONJUNCTS_THEN2 (LABEL_TAC "inc")
                          (CONJUNCTS_THEN2 (LABEL_TAC "porder")
      (CONJUNCTS_THEN2 (LABEL_TAC "top")
       (CONJUNCTS_THEN2 (LABEL_TAC "oneD")
        (CONJUNCTS_THEN2 (LABEL_TAC "BD")
         (CONJUNCTS_THEN2 (LABEL_TAC "oneB")
          (CONJUNCTS_THEN2 (LABEL_TAC "XD")
           (CONJUNCTS_THEN2 (LABEL_TAC "ciX")
            (LABEL_TAC "PX")))))))))))))))))))))) THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B inclB /\ eporder D E B inclB`
   (CONJUNCTS_THEN2 (LABEL_TAC "balg") (LABEL_TAC "pord")) THENL
   [USE_THEN "cba" (fun th -> let b = MATCH_MP ECBA_IMP_BALG th in
      ACCEPT_TAC(CONJ b (MATCH_MP EBALG_IMP_PORDER b)));
    ALL_TAC] THEN
  USE_THEN "pb" (fun th -> let cs = CONJUNCTS(REWRITE_RULE[pbundle] th) in
    LABEL_TAC "autBD" (el 2 cs) THEN LABEL_TAC "bijB" (el 5 cs) THEN
    LABEL_TAC "presB" (el 10 cs)) THEN
  USE_THEN "bijB" (fun th -> let cs = CONJUNCTS(REWRITE_RULE[ebij] th) in
    LABEL_TAC "bijtot" (el 2 cs) THEN LABEL_TAC "bijsv" (el 3 cs)) THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B x` (LABEL_TAC "bnx") THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  (* W is autN-invariant *)
  SUBGOAL_THEN `!s0. s0 IN D /\ (E:A->A->bool) s0 W ==> ?s1. s1 IN D /\
      E s1 W /\ eautn D E B autB s0 s1`
   (LABEL_TAC "Wfwd") THENL
   [X_GEN_TAC `s0:A` THEN DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "s0D")
       (LABEL_TAC "s0W")) THEN
    USE_THEN "Wch" (MP_TAC o SPEC `s0:A`) THEN
    ANTS_TAC THENL [USE_THEN "s0D" ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "s0W" (MP_TAC o EQ_MP th)) THEN
    DISCH_THEN(X_CHOOSE_THEN `w:A` (CONJUNCTS_THEN2 (LABEL_TAC "wD")
        (CONJUNCTS_THEN2
      (MP_TAC o REWRITE_RULE[eindom]) (MP_TAC o REWRITE_RULE[eindom])))) THEN
    DISCH_THEN(X_CHOOSE_THEN `ws:A` (CONJUNCTS_THEN2 (LABEL_TAC "wsD")
        (LABEL_TAC "aws0"))) THEN
    DISCH_THEN(X_CHOOSE_THEN `qw:A` (CONJUNCTS_THEN2 (LABEL_TAC "qwD")
        (LABEL_TAC "axw"))) THEN
    SUBGOAL_THEN `hsname D (E:A->A->bool) B w1 X w /\
        bname D E B w` (CONJUNCTS_THEN2 (LABEL_TAC "hsw")
                        (LABEL_TAC "bhsw")) THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;`x:A`;`w:A`]
             HSNAME_DOM) THEN
      ANTS_TAC THENL
       [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
        REWRITE_TAC[eindom] THEN EXISTS_TAC `qw:A` THEN CONJ_TAC THEN
            FIRST_ASSUM ACCEPT_TAC;
        DISCH_THEN(fun th -> CONJ_TAC THENL
          [ACCEPT_TAC(CONJUNCT2 th);
           MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC
               [`w1:A`;`X:A`] THEN
           REPEAT CONJ_TAC THEN FIRST [FIRST_ASSUM ACCEPT_TAC;
               ACCEPT_TAC(CONJUNCT1 th);
                                           ACCEPT_TAC(CONJUNCT2 th)]])];
      ALL_TAC] THEN
    SUBGOAL_THEN `hsname D (E:A->A->bool) B w1 X s0 /\
        bname D E B s0` (CONJUNCTS_THEN2 (LABEL_TAC "hss0")
                         (LABEL_TAC "bhss0")) THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;`w:A`;`s0:A`]
             HSNAME_DOM) THEN
      ANTS_TAC THENL
       [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
        REWRITE_TAC[eindom] THEN EXISTS_TAC `ws:A` THEN CONJ_TAC THEN
            FIRST_ASSUM ACCEPT_TAC;
        DISCH_THEN(fun th -> CONJ_TAC THENL
          [ACCEPT_TAC(CONJUNCT2 th);
           MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC
               [`w1:A`;`X:A`] THEN
           REPEAT CONJ_TAC THEN FIRST [FIRST_ASSUM ACCEPT_TAC;
               ACCEPT_TAC(CONJUNCT1 th);
                                           ACCEPT_TAC(CONJUNCT2 th)]])];
      ALL_TAC] THEN
