(* ######################################################################### *)
(* S4 / H4 (part 2) : HS |= ZF -- UNION and POWER SET.                       *)
(* Union: HS_UNIONNAME (the V^B union name of an HS name is HS: UNION_SYM + *)
(* supports + the name's own HS stage), union-value bounds (clones),         *)
(* BVALF_HS_UNION.                                                           *)
(* Power: subset-value clones (ESUBVAL_EQ_SUBSETVAL_HS, POW_RHS_SUBVAL_HS),  *)
(* EBV_IN_POW_HS, HS_POWFS (FS = all HS functions with domain dom xx, a set *)
(* inside one HS stage), POW_SYM (the power name over FS is autN-fixed),    *)
(* HS_POWNAME (HS at the successor stage), BVALF_HS_POWERSET.               *)
(* ######################################################################### *)
let HS_UNIONNAME = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X x W un.
     hsbundle D E w1 om tw ii ci P leqp B inclB onebee X /\
     x IN D /\ hsname D E B w1 X x /\
     W IN D /\ (!t. t IN D ==> (E t W <=> ?w. w IN D /\ eindom D E x w /\
         eindom D E w t)) /\
     un IN D /\ eisfun D E un /\
     (!z. z IN D ==> (E z un <=>
                ?s q. s IN D /\ q IN D /\ E s W /\ euuval D E B inclB x s q /\
                      eopair D (E:A->A->bool) s q z))
     ==> hsname D E B w1 X un`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "hsb")
             (CONJUNCTS_THEN2 (LABEL_TAC "xD")
              (CONJUNCTS_THEN2 (LABEL_TAC "hsx")
               (CONJUNCTS_THEN2 (LABEL_TAC "WD")
                (CONJUNCTS_THEN2 (LABEL_TAC "Wch")
                 (CONJUNCTS_THEN2 (LABEL_TAC "unD")
                  (CONJUNCTS_THEN2 (LABEL_TAC "isfun")
                   (LABEL_TAC "unch")))))))) THEN
  USE_THEN "hsb" (MP_TAC o MATCH_MP HSB_CBA) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "cba")
             (CONJUNCTS_THEN2 (LABEL_TAC "inclD") (LABEL_TAC "leqpD"))) THEN
  USE_THEN "hsb" (MP_TAC o REWRITE_RULE[hsbundle]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
             (CONJUNCTS_THEN2 (LABEL_TAC "vl")
              (CONJUNCTS_THEN2 (LABEL_TAC "eom")
               (CONJUNCTS_THEN2 (LABEL_TAC "w1D")
                (CONJUNCTS_THEN2 (LABEL_TAC "w1card")
                 (CONJUNCTS_THEN2 (LABEL_TAC "omw1e")
                  (CONJUNCTS_THEN2 (LABEL_TAC "w1min")
                   (CONJUNCTS_THEN2 (LABEL_TAC "cr1")
                    (CONJUNCTS_THEN2 (LABEL_TAC "cr2")
                     (CONJUNCTS_THEN2 (LABEL_TAC "ftw")
                      (CONJUNCTS_THEN2 (LABEL_TAC "coh")
                       (CONJUNCTS_THEN2 (LABEL_TAC "leq")
                        (CONJUNCTS_THEN2 (LABEL_TAC "ros")
                         (CONJUNCTS_THEN2 (LABEL_TAC "inc")
                          (CONJUNCTS_THEN2 (LABEL_TAC "porder")
      (CONJUNCTS_THEN2 (LABEL_TAC "top")
       (CONJUNCTS_THEN2 (LABEL_TAC "oneD")
        (CONJUNCTS_THEN2 (LABEL_TAC "BD")
         (CONJUNCTS_THEN2 (LABEL_TAC "oneB")
          (CONJUNCTS_THEN2 (LABEL_TAC "XD")
           (CONJUNCTS_THEN2 (LABEL_TAC "ciX")
            (LABEL_TAC "PX")))))))))))))))))))))) THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B inclB /\ eporder D E B inclB`
   (CONJUNCTS_THEN2 (LABEL_TAC "balg") (LABEL_TAC "pord")) THENL
   [USE_THEN "cba" (fun th -> let b = MATCH_MP ECBA_IMP_BALG th in
      ACCEPT_TAC(CONJ b (MATCH_MP EBALG_IMP_PORDER b)));
    ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B x` (LABEL_TAC "bnx") THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`x:A`;`W:A`;`un:A`]
         EUNIONNAME_BNAME) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                  DISCH_THEN(LABEL_TAC "bnun")] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;`x:A`]
         HSNAME_SYM) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                  DISCH_THEN(LABEL_TAC "symx")] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;`ii:A`;`ci:A`;
                `P:A`;`leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`x:A`]
      EHSSYM_ELIM_ALL) THEN
  ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ex:A` (CONJUNCTS_THEN2 (LABEL_TAC "exD")
      (CONJUNCTS_THEN2 (LABEL_TAC "exfin")
       (CONJUNCTS_THEN2 (LABEL_TAC "exsub") (LABEL_TAC "exfix"))))) THEN
  SUBGOAL_THEN `ehssym D (E:A->A->bool) B w1 X un` (LABEL_TAC "symun") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;`ii:A`;`ci:A`;
                  `P:A`;`leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`un:A`;`ex:A`]
       EHSSYM_INTRO) THEN
    ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    X_GEN_TAC `s:A` THEN DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "sD")
      (CONJUNCTS_THEN2 (LABEL_TAC "sperm") (LABEL_TAC "sfix"))) THEN
    MAP_EVERY X_GEN_TAC [`muci:A`;`muP:A`;`autB:A`] THEN
    DISCH_THEN(fun th ->
      SUBGOAL_THEN `pbundle D (E:A->A->bool) ci P leqp B inclB s muci muP autB`
          (LABEL_TAC "pb")
      THENL [REWRITE_TAC[pbundle] THEN ACCEPT_TAC th; ALL_TAC]) THEN
    USE_THEN "pb" (fun th -> let cs = CONJUNCTS(REWRITE_RULE[pbundle] th) in
      LABEL_TAC "mucD" (el 0 cs) THEN LABEL_TAC "muPD" (el 1 cs) THEN
      LABEL_TAC "autBD" (el 2 cs) THEN LABEL_TAC "mch" (el 6 cs) THEN
      LABEL_TAC "Pch" (el 7 cs) THEN LABEL_TAC "ach" (el 8 cs)) THEN
    USE_THEN "exfix" (MP_TAC o SPEC `s:A`) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPECL [`muci:A`;`muP:A`;`autB:A`]) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN(LABEL_TAC "fx")] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;`ii:A`;`ci:A`;
                  `P:A`;`leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`s:A`;
        `muci:A`;`muP:A`;`autB:A`;`x:A`;`W:A`;`un:A`] UNION_SYM) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `?a y. a IN D /\ y IN D /\ eordinal D (E:A->A->bool) a /\
                      hsstage D E B w1 X a y /\ E x y`
   (X_CHOOSE_THEN `a:A` (X_CHOOSE_THEN `y:A` (CONJUNCTS_THEN2 (LABEL_TAC "aD")
     (CONJUNCTS_THEN2 (LABEL_TAC "yD") (CONJUNCTS_THEN2 (LABEL_TAC "aord")
       (CONJUNCTS_THEN2 (LABEL_TAC "hsay") (LABEL_TAC "xy"))))))) THENL
   [USE_THEN "hsx" (ACCEPT_TAC o REWRITE_RULE[hsname]); ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;`un:A`;`a:A`;
                `y:A`] HSSTAGE_INTRO) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    X_GEN_TAC `z:A` THEN DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "zD")
        (LABEL_TAC "zun")) THEN
    USE_THEN "unch" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [USE_THEN "zD" ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "zun" (MP_TAC o EQ_MP th)) THEN
    DISCH_THEN(X_CHOOSE_THEN `s0:A` (X_CHOOSE_THEN `q:A`
        (CONJUNCTS_THEN2 (LABEL_TAC "s0D")
      (CONJUNCTS_THEN2 (LABEL_TAC "qD") (CONJUNCTS_THEN2 (LABEL_TAC "s0W")
        (CONJUNCTS_THEN2 (LABEL_TAC "euq") (LABEL_TAC "ops0"))))))) THEN
    USE_THEN "Wch" (MP_TAC o SPEC `s0:A`) THEN
    ANTS_TAC THENL [USE_THEN "s0D" ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "s0W" (MP_TAC o EQ_MP th)) THEN
    DISCH_THEN(X_CHOOSE_THEN `w:A` (CONJUNCTS_THEN2 (LABEL_TAC "wD")
        (CONJUNCTS_THEN2
      (LABEL_TAC "xw") (LABEL_TAC "ws0")))) THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;`a:A`;`y:A`;
                  `x:A`;`w:A`] HSSTAGE_DOM) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
               (X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `zb:A`
      (CONJUNCTS_THEN2 (LABEL_TAC "bD") (CONJUNCTS_THEN2 (LABEL_TAC "zbD")
        (CONJUNCTS_THEN2 (LABEL_TAC "ba")
         (CONJUNCTS_THEN2 (LABEL_TAC "hsbzb") (LABEL_TAC "wzb")))))))) THEN
    SUBGOAL_THEN `eordinal D (E:A->A->bool) b` (LABEL_TAC "bord") THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`a:A`;`b:A`]
             EORDINAL_MEMBER) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;`b:A`;`zb:A`;
                  `w:A`;`s0:A`] HSSTAGE_DOM) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
               (X_CHOOSE_THEN `b2:A` (X_CHOOSE_THEN `zb2:A`
      (CONJUNCTS_THEN2 (LABEL_TAC "b2D") (CONJUNCTS_THEN2 (LABEL_TAC "zb2D")
        (CONJUNCTS_THEN2 (LABEL_TAC "b2b")
         (CONJUNCTS_THEN2 (LABEL_TAC "hsb2zb2") (LABEL_TAC "s0zb2")))))))) THEN
    SUBGOAL_THEN `(E:A->A->bool) b2 a` (LABEL_TAC "b2a") THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`a:A`;`b2:A`;`b:A`]
             EORDINAL_TRANS_E) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`s0:A`;`q:A`] THEN REPEAT CONJ_TAC THEN
        TRY(FIRST_ASSUM ACCEPT_TAC) THENL
     [USE_THEN "euq" (ACCEPT_TAC o CONJUNCT2 o MATCH_MP EUUVAL_IN);
      MAP_EVERY EXISTS_TAC [`b2:A`;`zb2:A`] THEN REPEAT CONJ_TAC THEN
          FIRST_ASSUM ACCEPT_TAC];
    DISCH_THEN(LABEL_TAC "uny")] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;`a:A`;`y:A`;
                `un:A`] HSNAME_STAGE) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                  DISCH_THEN ACCEPT_TAC]);;

let EBV_IN_UNION_LE_HS = prove
 (`!D (E:A->A->bool) B leq w1 X x t un zun r.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
          w1 IN D /\ X IN D /\
      x IN D /\ hsname D E B w1 X x /\ t IN D /\ hsname D E B w1 X t /\
      un IN D /\
      (!s qs. s IN D /\ qs IN D /\ eapply D E un s qs
              ==> euuval D E B leq x s qs) /\
      zun IN D /\ ebv_in D E B leq t un zun /\
      r IN D /\ E r B /\
      (!w zwx ztw m.
          w IN D /\ hsname D E B w1 X w /\ zwx IN D /\ ztw IN D /\ m IN D /\
          ebv_in D E B leq w x zwx /\ ebv_in D E B leq t w ztw /\
          emeet D E B leq zwx ztw m
          ==> erel D E leq m r)
      ==> erel D E leq zun r`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (x:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (t:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (w:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`t:A`;`un:A`;
    `zun:A`;`r:A`] EBV_IN_LE_V) THEN
  ASM_REWRITE_TAC[] THEN
  MAP_EVERY X_GEN_TAC [`s:A`;`qs:A`;`es:A`;`c:A`] THEN STRIP_TAC THEN
  (* qs = un(s) is a euuval; get its B-membership *)
  SUBGOAL_THEN `euuval D (E:A->A->bool) B leq x s qs` ASSUME_TAC THENL
   [FIRST_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(qs:A) IN D /\ (E:A->A->bool) qs B` STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`x:A`;`s:A`;`qs:A`]
      EUUVAL_IN) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) es B` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`t:A`;`s:A`;`es:A`]
      EBV_EQ_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* residuation: build imp = es ==> r ; reduce c=qs MEET es <= r to qs <= *)
  (* imp                                                                   *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`es:A`;`r:A`]
    EBIMP_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `imp:A`) THEN
  SUBGOAL_THEN `(imp:A) IN D /\ (E:A->A->bool) imp B` STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                   `es:A`;`r:A`;`imp:A`]
      EBIMP_IN) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`qs:A`;`es:A`;
    `r:A`;`imp:A`;`c:A`] EBIMP_MEET_LE) THEN
  ASM_REWRITE_TAC[] THEN
  (* now goal:  erel leq qs imp ;  EUUVAL_LEAST reduces to per-combiner *)
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`x:A`;`s:A`;
    `qs:A`;`imp:A`] EUUVAL_LEAST) THEN
  ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `cc:A` THEN
  DISCH_THEN(X_CHOOSE_THEN `w:A` (X_CHOOSE_THEN `qw:A` (X_CHOOSE_THEN `ws:A`
    STRIP_ASSUME_TAC)) o REWRITE_RULE[euucomb]) THEN
  (* cc = x(w) MEET w(s) ;  its B-membership *)
  SUBGOAL_THEN `(cc:A) IN D /\ (E:A->A->bool) cc B` STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                   `qw:A`;`ws:A`;`cc:A`]
      EMEET_IN) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* dm = cc MEET es ;  reduce  cc <= imp  to  dm <= r  (EBIMP_LE_IMP) *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cc:A`;`es:A`]
    EBALG_MEET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `dm:A`) THEN
  SUBGOAL_THEN `(dm:A) IN D /\ (E:A->A->bool) dm B` STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                   `cc:A`;`es:A`;`dm:A`]
      EMEET_IN) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cc:A`;`es:A`;
    `r:A`;`imp:A`;`dm:A`] EBIMP_LE_IMP) THEN
  ASM_REWRITE_TAC[] THEN
  (* goal now:  erel leq dm r .  Establish hsname w, [[w in x]], [[t in w]]. *)
  SUBGOAL_THEN `hsname D (E:A->A->bool) B w1 X w` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;`x:A`;`w:A`]
           HSNAME_DOM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN REWRITE_TAC[eindom] THEN
    EXISTS_TAC `qw:A` THEN ASM_REWRITE_TAC[];
        DISCH_THEN(ACCEPT_TAC o CONJUNCT2)]; ALL_TAC] THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (w:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  SUBGOAL_THEN `(E:A->A->bool) qw B` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`x:A`;`w:A`;`qw:A`]
      BNAME_APPLY_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) ws B` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w:A`;`s:A`;`ws:A`]
      BNAME_APPLY_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;`x:A`]
    EBV_IN_VAL_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `zwx:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`t:A`;`w:A`]
    EBV_IN_VAL_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `ztw:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;`w:A`]
    EBV_EQ_VAL_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `eww:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `etop D (E:A->A->bool) B leq eww` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;`eww:A`]
      EBV_EQ_REFL) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `emeet D (E:A->A->bool) B leq qw eww qw` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;
                         `leq:A`;`eww:A`;`qw:A`]
      EMEET_TOP) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* term bound 1:  x(w) = qw <= [[w in x]] = zwx *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq qw zwx` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;`x:A`;
      `zwx:A`;`w:A`;`qw:A`;`eww:A`;`qw:A`] EBV_IN_GE_TERM_V) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* term bound 2:  w(s) MEET [[t=s]] = wse <= [[t in w]] = ztw *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ws:A`;`es:A`]
    EBALG_MEET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `wse:A`) THEN
  SUBGOAL_THEN `(wse:A) IN D /\ (E:A->A->bool) wse B` STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                   `ws:A`;`es:A`;`wse:A`]
      EMEET_IN) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq wse ztw` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`t:A`;`w:A`;
      `ztw:A`;`s:A`;`ws:A`;`es:A`;`wse:A`] EBV_IN_GE_TERM_V) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* dm <= cc <= qw <= zwx  and  dm <= ws, dm <= es => dm <= wse <= ztw *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq dm cc /\ erel D E leq dm es`
  STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                   `cc:A`;`es:A`;`dm:A`]
      EMEET_LE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq cc qw /\ erel D E leq cc ws`
  STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                   `qw:A`;`ws:A`;`cc:A`]
      EMEET_LE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq dm qw` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`dm:A`;`cc:A`;
      `qw:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq dm zwx` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`dm:A`;`qw:A`;
      `zwx:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq dm ws` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`dm:A`;`cc:A`;
      `ws:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq dm wse` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ws:A`;`es:A`;
      `wse:A`;`dm:A`] EMEET_GREATEST) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq dm ztw` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;
                         `leq:A`;`dm:A`;`wse:A`;
      `ztw:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* mfull = [[w in x]] MEET [[t in w]] ;  dm <= mfull <= r *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zwx:A`;`ztw:A`]
    EBALG_MEET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `mfull:A`) THEN
  SUBGOAL_THEN `(mfull:A) IN D /\ (E:A->A->bool) mfull B` STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zwx:A`;`ztw:A`;
      `mfull:A`] EMEET_IN) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq dm mfull` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                         `zwx:A`;`ztw:A`;
      `mfull:A`;`dm:A`] EMEET_GREATEST) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mfull r` ASSUME_TAC THENL
   [FIRST_ASSUM(fun th -> MP_TAC(SPECL
       [`w:A`;`zwx:A`;`ztw:A`;`mfull:A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                       `dm:A`;`mfull:A`;
    `r:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[]);;

let UNION_SUP_GE_HS = prove
 (`!D (E:A->A->bool) B leq w1 X vv xx un tt W zun.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
          w1 IN D /\ X IN D /\
      valuation D vv /\ (!i. hsname D E B w1 X (vv i)) /\
      vv 0 = xx /\ vv 2 = tt /\
      xx IN D /\ hsname D E B w1 X xx /\ tt IN D /\ hsname D E B w1 X tt /\
      un IN D /\ W IN D /\
      (!s. s IN D
           ==> (E s W <=> ?w. w IN D /\ eindom D E xx w /\ eindom D E w s)) /\
      (!s q. s IN D /\ E s W /\ euuval D E B leq xx s q
       ==> eapply D E un s q) /\
      zun IN D /\ ebv_in D E B leq tt un zun
      ==> erel D E leq (bvalf_HS D E B leq w1 X vv
                        (?? 3 ((3 %% 0) && (2 %% 3)))) zun`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (xx:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (tt:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `!i:num. bname D (E:A->A->bool) B (((vv):num->A) i)`
      ASSUME_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC HSNAME_BNAME THEN
    MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[valuation]; ALL_TAC]) THEN
  SUBGOAL_THEN `(E:A->A->bool) zun B` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                   `tt:A`;`un:A`;`zun:A`]
      EBV_IN_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`3`; `(3 %% 0) && (2 %% 3)`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;`X:A`;`vv:num->A`;`zun:A`]
        BVALF_HS_EX_LEAST) THEN
  ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `a:A` THEN STRIP_TAC THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (a:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  
  SUBGOAL_THEN `valuation D ((3 |-> (a:A)) (vv:num->A)) /\
                (!i. hsname D E B w1 X (((3 |-> (a:A)) (vv:num->A)) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC HSNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  TRY(SUBGOAL_THEN `!i:num. bname D (E:A->A->bool) B
      ((((3 |-> (a:A)) (vv:num->A)):num->A) i)` ASSUME_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC HSNAME_BNAME THEN
    MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[valuation]; ALL_TAC]) THEN
  SUBGOAL_THEN `((3 |-> (a:A)) (vv:num->A)) 0 = xx /\
                ((3 |-> (a:A)) (vv:num->A)) 2 = tt /\
                ((3 |-> (a:A)) (vv:num->A)) 3 = a`
  STRIP_ASSUME_TAC THENL
   [ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
  ABBREV_TAC `za = bvalf_HS D (E:A->A->bool) B leq w1 X
      ((3 |-> (a:A)) (vv:num->A)) (3 %% 0)` THEN
  ABBREV_TAC `zta = bvalf_HS D (E:A->A->bool) B leq w1 X
      ((3 |-> (a:A)) (vv:num->A)) (2 %% 3)` THEN
  ABBREV_TAC `mm = bvalf_HS D (E:A->A->bool) B leq w1 X
      ((3 |-> (a:A)) (vv:num->A)) ((3 %% 0) && (2 %% 3))` THEN
  SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq a xx za` ASSUME_TAC THENL
   [EXPAND_TAC "za" THEN
    MP_TAC(ISPECL [`3`;`0`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                   `leq:A`;`w1:A`;`X:A`;
      `(3 |-> (a:A)) (vv:num->A)`] BVALF_HS_MEM) THEN
          ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq tt a zta` ASSUME_TAC THENL
   [EXPAND_TAC "zta" THEN
    MP_TAC(ISPECL [`2`;`3`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                   `leq:A`;`w1:A`;`X:A`;
      `(3 |-> (a:A)) (vv:num->A)`] BVALF_HS_MEM) THEN
          ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `emeet D (E:A->A->bool) B leq za zta mm` ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["za";"zta";"mm"] THEN
    MP_TAC(ISPECL [`3 %% 0`;`2 %% 3`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                   `leq:A`;`w1:A`;`X:A`;
      `(3 |-> (a:A)) (vv:num->A)`] BVALF_HS_AND_MEET) THEN
          ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(za:A) IN D` ASSUME_TAC THENL
   [EXPAND_TAC "za" THEN
    MP_TAC(ISPECL [`3 %% 0`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                   `leq:A`;`w1:A`;`X:A`;
      `(3 |-> (a:A)) (vv:num->A)`] BVALF_HS_SPEC) THEN
          ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(zta:A) IN D` ASSUME_TAC THENL
   [EXPAND_TAC "zta" THEN
    MP_TAC(ISPECL [`2 %% 3`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                   `leq:A`;`w1:A`;`X:A`;
      `(3 |-> (a:A)) (vv:num->A)`] BVALF_HS_SPEC) THEN
          ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(mm:A) IN D` ASSUME_TAC THENL
   [EXPAND_TAC "mm" THEN
    MP_TAC(ISPECL [`(3 %% 0) && (2 %% 3)`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                   `leq:A`;`w1:A`;`X:A`;
      `(3 |-> (a:A)) (vv:num->A)`] BVALF_HS_SPEC) THEN
          ASM_SIMP_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`xx:A`;`tt:A`;
    `un:A`;`W:A`;`zun:A`;`a:A`;`za:A`;`zta:A`;`mm:A`] EBV_IN_UNION_GE) THEN
  ASM_REWRITE_TAC[]);;

let UNION_SUP_LE_HS = prove
 (`!D (E:A->A->bool) B leq w1 X vv xx un tt zun.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
          w1 IN D /\ X IN D /\
      valuation D vv /\ (!i. hsname D E B w1 X (vv i)) /\
      vv 0 = xx /\ vv 2 = tt /\
      xx IN D /\ hsname D E B w1 X xx /\ tt IN D /\ hsname D E B w1 X tt /\
      un IN D /\
      (!s qs. s IN D /\ qs IN D /\ eapply D E un s qs
              ==> euuval D E B leq xx s qs) /\
      zun IN D /\ ebv_in D E B leq tt un zun
      ==> erel D E leq zun (bvalf_HS D E B leq w1 X vv
                            (?? 3 ((3 %% 0) && (2 %% 3))))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (xx:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (tt:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `!i:num. bname D (E:A->A->bool) B (((vv):num->A) i)`
      ASSUME_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC HSNAME_BNAME THEN
    MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[valuation]; ALL_TAC]) THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(bvalf_HS D (E:A->A->bool) B leq w1 X vv
                 (?? 3 ((3 %% 0) && (2 %% 3)))) IN D`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL [`?? 3 ((3 %% 0) && (2 %% 3))`;`D:A->bool`;
                   `E:A->A->bool`;`B:A`;
      `leq:A`;`w1:A`;`X:A`;`vv:num->A`] BVALF_HS_SPEC) THEN
          ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) (bvalf_HS D E B leq w1 X vv
      (?? 3 ((3 %% 0) && (2 %% 3)))) B`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL [`?? 3 ((3 %% 0) && (2 %% 3))`;`D:A->bool`;
                   `E:A->A->bool`;`B:A`;
      `leq:A`;`w1:A`;`X:A`;`vv:num->A`] BVALF_HS_IN_B) THEN
          ASM_SIMP_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                       `X:A`;`xx:A`;`tt:A`;
    `un:A`;`zun:A`;
    `bvalf_HS (D:A->bool) (E:A->A->bool) (B:A) (leq:A) (w1:A) (X:A) (vv:num->A)
           (?? 3 ((3 %% 0) && (2 %% 3)))`]
    EBV_IN_UNION_LE_HS) THEN
  ASM_REWRITE_TAC[] THEN
  MAP_EVERY X_GEN_TAC [`w:A`;`zwx:A`;`ztw:A`;`m:A`] THEN STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((3 |-> (w:A)) (vv:num->A)) /\
                (!i. hsname D E B w1 X (((3 |-> (w:A)) (vv:num->A)) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC HSNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  TRY(SUBGOAL_THEN `!i:num. bname D (E:A->A->bool) B
      ((((3 |-> (w:A)) (vv:num->A)):num->A) i)` ASSUME_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC HSNAME_BNAME THEN
    MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[valuation]; ALL_TAC]) THEN
  SUBGOAL_THEN `((3 |-> (w:A)) (vv:num->A)) 0 = xx /\
                ((3 |-> (w:A)) (vv:num->A)) 2 = tt /\
                ((3 |-> (w:A)) (vv:num->A)) 3 = w`
  STRIP_ASSUME_TAC THENL
   [ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
  SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq w xx
                  (bvalf_HS D E B leq w1 X ((3 |-> (w:A))
                      (vv:num->A)) (3 %% 0))`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL [`3`;`0`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                   `leq:A`;`w1:A`;`X:A`;
      `(3 |-> (w:A)) (vv:num->A)`] BVALF_HS_MEM) THEN
          ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq tt w
                  (bvalf_HS D E B leq w1 X ((3 |-> (w:A))
                      (vv:num->A)) (2 %% 3))`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL [`2`;`3`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                   `leq:A`;`w1:A`;`X:A`;
      `(3 |-> (w:A)) (vv:num->A)`] BVALF_HS_MEM) THEN
          ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `emeet D (E:A->A->bool) B leq
                  (bvalf_HS D E B leq w1 X ((3 |-> (w:A)) (vv:num->A)) (3 %% 0))
                  (bvalf_HS D E B leq w1 X ((3 |-> (w:A)) (vv:num->A)) (2 %% 3))
                  (bvalf_HS D E B leq w1 X ((3 |-> (w:A)) (vv:num->A))
                   ((3 %% 0) && (2 %% 3)))`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL [`3 %% 0`;`2 %% 3`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                   `leq:A`;`w1:A`;`X:A`;
      `(3 |-> (w:A)) (vv:num->A)`] BVALF_HS_AND_MEET) THEN
          ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(bvalf_HS D (E:A->A->bool) B leq w1 X
                 ((3 |-> (w:A)) (vv:num->A)) (3 %% 0)) IN D`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL [`3 %% 0`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                   `leq:A`;`w1:A`;`X:A`;
      `(3 |-> (w:A)) (vv:num->A)`] BVALF_HS_SPEC) THEN
          ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(bvalf_HS D (E:A->A->bool) B leq w1 X
                 ((3 |-> (w:A)) (vv:num->A)) (2 %% 3)) IN D`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL [`2 %% 3`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                   `leq:A`;`w1:A`;`X:A`;
      `(3 |-> (w:A)) (vv:num->A)`] BVALF_HS_SPEC) THEN
          ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `zwx:A = bvalf_HS D E B leq w1 X
      ((3 |-> (w:A)) (vv:num->A)) (3 %% 0)`
  SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;`xx:A`;
      `zwx:A`;`bvalf_HS D E B leq w1 X ((3 |-> (w:A)) (vv:num->A)) (3 %% 0)`]
          EBV_IN_UNIQUE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `ztw:A = bvalf_HS D E B leq w1 X
      ((3 |-> (w:A)) (vv:num->A)) (2 %% 3)`
  SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`tt:A`;`w:A`;
      `ztw:A`;`bvalf_HS D E B leq w1 X ((3 |-> (w:A)) (vv:num->A)) (2 %% 3)`]
          EBV_IN_UNIQUE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `m:A = bvalf_HS D E B leq w1 X ((3 |-> (w:A)) (vv:num->A))
      ((3 %% 0) && (2 %% 3))`
  SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `bvalf_HS D E B leq w1 X ((3 |-> (w:A)) (vv:num->A)) (3 %% 0)`;
      `bvalf_HS D E B leq w1 X ((3 |-> (w:A)) (vv:num->A)) (2 %% 3)`;
      `m:A`;
      `bvalf_HS D E B leq w1 X ((3 |-> (w:A)) (vv:num->A))
          ((3 %% 0) && (2 %% 3))`]
      EMEET_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`3`; `(3 %% 0) && (2 %% 3)`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;`X:A`;`vv:num->A`;`w:A`]
        BVALF_HS_EX_UB) THEN
  ASM_REWRITE_TAC[]);;

(* ===================================================================== *)
(* H4.9b : BVALF_HS_UNION -- [[union_ax]]^HS = TOP.  Witness: the V^B      *)
(* union name of xx, which is HS (HS_UNIONNAME).                           *)
(* ===================================================================== *)
let BVALF_HS_UNION = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X v.
      hsbundle D E w1 om tw ii ci P leqp B inclB onebee X /\
      valuation D v /\ (!i. hsname D E B w1 X (v i))
      ==> etop D E B inclB (bvalf_HS D E B inclB w1 X v union_ax)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  TRY(SUBGOAL_THEN `!i:num. bname D (E:A->A->bool) B (((v):num->A) i)`
      ASSUME_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC HSNAME_BNAME THEN
    MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[valuation]; ALL_TAC]) THEN
  FIRST_ASSUM(fun th -> let cs = CONJUNCTS(REWRITE_RULE[hsbundle] th)
                        and cb = CONJUNCTS(MATCH_MP HSB_CBA th) in
    MAP_EVERY ASSUME_TAC [el 0 cs; el 1 cs; el 3 cs; el 17 cs; el 19 cs;
                          el 0 cb; el 1 cb]) THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B inclB` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  REWRITE_TAC[union_ax] THEN
  (* peel !!0 -> xx (the container / family) *)
  MP_TAC(ISPECL [`0`; `?? 1 (!! 2 ((2 %% 1) <-> ??- 3 0 (2 %% 3)))`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;`X:A`;`v:num->A`]
        BVALF_HS_ALL_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  X_GEN_TAC `xx:A` THEN STRIP_TAC THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (xx:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  
  SUBGOAL_THEN `valuation D ((0 |-> (xx:A)) (v:num->A)) /\
                (!i. hsname D E B w1 X (((0 |-> (xx:A)) (v:num->A)) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC HSNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  TRY(SUBGOAL_THEN `!i:num. bname D (E:A->A->bool) B
      ((((0 |-> (xx:A)) (v:num->A)):num->A) i)` ASSUME_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC HSNAME_BNAME THEN
    MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[valuation]; ALL_TAC]) THEN
  ABBREV_TAC `v0 = (0 |-> (xx:A)) (v:num->A)` THEN
  (* build the union-name domain W and the union name un *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`xx:A`] EUNIONDOM_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `W:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`xx:A`;`W:A`]
    EUNIONNAME_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `un:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `hsname D (E:A->A->bool) B w1 X un` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;`ii:A`;
                         `ci:A`;`P:A`;`leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;
       `xx:A`;`W:A`;`un:A`] HS_UNIONNAME) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (un:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  (* witness un for  ??1 *)
  MATCH_MP_TAC(ISPECL [`1`; `!! 2 ((2 %% 1) <-> ??- 3 0 (2 %% 3))`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;`X:A`;`v0:num->A`;`un:A`]
        BVALF_HS_EX_TOP) THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `valuation D ((1 |-> (un:A)) (v0:num->A)) /\
                (!i. hsname D E B w1 X (((1 |-> (un:A)) (v0:num->A)) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC HSNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  TRY(SUBGOAL_THEN `!i:num. bname D (E:A->A->bool) B
      ((((1 |-> (un:A)) (v0:num->A)):num->A) i)` ASSUME_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC HSNAME_BNAME THEN
    MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[valuation]; ALL_TAC]) THEN
  ABBREV_TAC `v1 = (1 |-> (un:A)) (v0:num->A)` THEN
  (* peel !!2 -> tt (the test element) *)
  MP_TAC(ISPECL [`2`; `(2 %% 1) <-> ??- 3 0 (2 %% 3)`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;`X:A`;`v1:num->A`]
        BVALF_HS_ALL_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  X_GEN_TAC `tt:A` THEN STRIP_TAC THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (tt:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  
  SUBGOAL_THEN `valuation D ((2 |-> (tt:A)) (v1:num->A)) /\
                (!i. hsname D E B w1 X (((2 |-> (tt:A)) (v1:num->A)) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC HSNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  TRY(SUBGOAL_THEN `!i:num. bname D (E:A->A->bool) B
      ((((2 |-> (tt:A)) (v1:num->A)):num->A) i)` ASSUME_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC HSNAME_BNAME THEN
    MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[valuation]; ALL_TAC]) THEN
  ABBREV_TAC `vv = (2 |-> (tt:A)) (v1:num->A)` THEN
  SUBGOAL_THEN `(vv:num->A) 0 = xx /\ (vv:num->A) 1 = un /\ (vv:num->A) 2 = tt`
  STRIP_ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["vv";"v1";"v0"] THEN
    SIMP_TAC[VALMOD_OTHER; VALMOD_BASIC; ARITH_EQ]; ALL_TAC] THEN
  (* IFF_TOP -> value-equality *)
  MP_TAC(ISPECL [`2 %% 1`; `??- 3 0 (2 %% 3)`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;`X:A`;`vv:num->A`]
        BVALF_HS_IFF_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[Existsmem_DEF] THEN
  (* goal: bvalf_HS vv (2%%1) = bvalf_HS vv (?? 3 ((3%%0)&&(2%%3))) *)
  ABBREV_TAC `zun = bvalf_HS D (E:A->A->bool) B inclB w1 X
      (vv:num->A) (2 %% 1)` THEN
  SUBGOAL_THEN `ebv_in D (E:A->A->bool) B inclB tt un zun` ASSUME_TAC THENL
   [EXPAND_TAC "zun" THEN
    MP_TAC(ISPECL [`2`;`1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;
                   `X:A`;`vv:num->A`]
      BVALF_HS_MEM) THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(zun:A) IN D` ASSUME_TAC THENL
   [EXPAND_TAC "zun" THEN
    MP_TAC(ISPECL [`2 %% 1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;
                   `X:A`;`vv:num->A`]
      BVALF_HS_SPEC) THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) zun B` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;
                   `tt:A`;`un:A`;`zun:A`]
      EBV_IN_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `(bvalf_HS D (E:A->A->bool) B inclB w1 X vv
      (?? 3 ((3 %% 0) && (2 %% 3)))) IN D`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL [`?? 3 ((3 %% 0) && (2 %% 3))`;`D:A->bool`;
                   `E:A->A->bool`;`B:A`;
      `inclB:A`;`w1:A`;`X:A`;`vv:num->A`] BVALF_HS_SPEC) THEN
          ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `(E:A->A->bool) (bvalf_HS D E B inclB w1 X vv
                     (?? 3 ((3 %% 0) && (2 %% 3)))) B`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL [`?? 3 ((3 %% 0) && (2 %% 3))`;`D:A->bool`;
                   `E:A->A->bool`;`B:A`;
      `inclB:A`;`w1:A`;`X:A`;`vv:num->A`] BVALF_HS_IN_B) THEN
          ASM_SIMP_TAC[]; ALL_TAC] THEN
  (* INV form for UNION_SUP_LE_HS *)
  SUBGOAL_THEN `!s qs. s IN D /\ qs IN D /\ eapply D (E:A->A->bool) un s qs
                       ==> euuval D E B inclB xx s qs`
  ASSUME_TAC THENL
   [REPEAT STRIP_TAC THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;
                   `xx:A`;`W:A`;`un:A`;
      `s:A`;`qs:A`] UNION_APPLY_INV) THEN
    ASM_REWRITE_TAC[] THEN STRIP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* antisymmetry: zun = SUP *)
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`zun:A`;
    `bvalf_HS (D:A->bool) (E:A->A->bool) (B:A) (inclB:A) (w1:A)
        (X:A) (vv:num->A)
           (?? 3 ((3 %% 0) && (2 %% 3)))`] EPORDER_ANTISYM) THEN
  ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;
                         `X:A`;`vv:num->A`;
      `xx:A`;`un:A`;`tt:A`;`zun:A`] UNION_SUP_LE_HS) THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;
                         `X:A`;`vv:num->A`;
      `xx:A`;`un:A`;`tt:A`;`W:A`;`zun:A`] UNION_SUP_GE_HS) THEN
          ASM_REWRITE_TAC[]]);;

(* ===================================================================== *)
(* H4.10a : POWER SET, subset values.  ESUBVAL_EQ_SUBSETVAL_HS (the glb   *)
(* over HS w of [[w in f]] => [[w in x]] is esubval x f) and              *)
(* POW_RHS_SUBVAL_HS ([[!!- 3 2 (3 %% 0)]]^HS = esubval) -- clones.       *)
(* ===================================================================== *)
let ESUBVAL_EQ_SUBSETVAL_HS = prove
 (`!D (E:A->A->bool) B leq w1 X x f z zsub.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
          w1 IN D /\ X IN D /\
      x IN D /\ hsname D E B w1 X x /\ f IN D /\ hsname D E B w1 X f /\
      esubval D E B leq x f z /\ z IN D /\
      zsub IN D /\ E zsub B /\
      (!w zwf zwx ii.
          w IN D /\ hsname D E B w1 X w /\ zwf IN D /\ zwx IN D /\ ii IN D /\
          ebv_in D E B leq w f zwf /\ ebv_in D E B leq w x zwx /\
          ebimp D E B leq zwf zwx ii
          ==> erel D E leq zsub ii) /\
      (!lb. lb IN D /\ E lb B /\
           (!w zwf zwx ii.
               w IN D /\ hsname D E B w1 X w /\ zwf IN D /\
                   zwx IN D /\ ii IN D /\
               ebv_in D E B leq w f zwf /\ ebv_in D E B leq w x zwx /\
               ebimp D E B leq zwf zwx ii
               ==> erel D E leq lb ii)
           ==> erel D E leq lb zsub)
      ==> z = zsub`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (x:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (f:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (w:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) z B` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUBVAL_IN]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`z:A`;`zsub:A`]
    EPORDER_ANTISYM) THEN
  ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [(* z <= zsub : zsub is greatest lower bound,
      z lower-bounds all W-combiners *)
    FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN
    MAP_EVERY X_GEN_TAC [`w:A`;`zwf:A`;`zwx:A`;`ii:A`] THEN STRIP_TAC THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (w:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (zwf:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (zwx:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (ii:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`x:A`;`f:A`;
      `z:A`;`w:A`;`zwf:A`;`zwx:A`;`ii:A`] ESUBVAL_ALLW_LB) THEN
    ASM_REWRITE_TAC[];
    (* zsub <= z : ESUBVAL_GREATEST + zsub <= each dom-f combiner *)
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`x:A`;`f:A`;
      `z:A`;`zsub:A`] ESUBVAL_GREATEST) THEN
    ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `c:A` THEN DISCH_TAC THEN
    POP_ASSUM(STRIP_ASSUME_TAC o REWRITE_RULE[esubcomb]) THEN
    SUBGOAL_THEN `eindom D (E:A->A->bool) f v` ASSUME_TAC THENL
     [REWRITE_TAC[eindom] THEN EXISTS_TAC `qv:A` THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `hsname D (E:A->A->bool) B w1 X v` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;`f:A`;`v:A`]
           HSNAME_DOM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN(ACCEPT_TAC o
        CONJUNCT2)]; ALL_TAC] THEN
    TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (v:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  SUBGOAL_THEN `(E:A->A->bool) qv B` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`f:A`;`v:A`;`qv:A`]
        BNAME_APPLY_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) z2 B` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:A`;`x:A`;
        `z2:A`] EBV_IN_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(c:A) IN D /\ (E:A->A->bool) c B` STRIP_ASSUME_TAC THENL
     [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EBIMP_IN); ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:A`;`f:A`]
      EBV_IN_VAL_EXISTS) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `zvf:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq qv zvf` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`f:A`;`v:A`;
        `qv:A`;`zvf:A`] EBV_MEMBER_LE_V) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zvf:A`;`z2:A`]
      EBIMP_EXISTS) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `ii:A`) THEN
    SUBGOAL_THEN `(ii:A) IN D /\ (E:A->A->bool) ii B` STRIP_ASSUME_TAC THENL
     [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EBIMP_IN); ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq zsub ii` ASSUME_TAC THENL
     [FIRST_X_ASSUM MATCH_MP_TAC THEN
      MAP_EVERY EXISTS_TAC [`v:A`;`zvf:A`;`z2:A`] THEN
          ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq ii c` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;
                           `leq:A`;`qv:A`;`zvf:A`;
        `z2:A`;`c:A`;`ii:A`] EBIMP_ANT) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                         `zsub:A`;`ii:A`;
      `c:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[]]);;

let POW_RHS_SUBVAL_HS = prove
 (`!D (E:A->A->bool) B leq w1 X vv xx tt zr.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
          w1 IN D /\ X IN D /\
      valuation D vv /\ (!i. hsname D E B w1 X (vv i)) /\
      vv 2 = tt /\ vv 0 = xx /\
      xx IN D /\ hsname D E B w1 X xx /\ tt IN D /\ hsname D E B w1 X tt /\
      esubval D E B leq xx tt zr /\ zr IN D
      ==> bvalf_HS D E B leq w1 X vv (!!- 3 2 (3 %% 0)) = zr`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (xx:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (tt:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `!i:num. bname D (E:A->A->bool) B (((vv):num->A) i)`
      ASSUME_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC HSNAME_BNAME THEN
    MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[valuation]; ALL_TAC]) THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  REWRITE_TAC[Forallmem_DEF] THEN
  SUBGOAL_THEN
   `bvalf_HS D (E:A->A->bool) B leq w1 X vv
       (!! 3 ((3 %% 2) --> (3 %% 0))) IN D /\
    (E:A->A->bool) (bvalf_HS D E B leq w1 X vv
                    (!! 3 ((3 %% 2) --> (3 %% 0)))) B`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL [`!! 3 ((3 %% 2) --> (3 %% 0))`;`D:A->bool`;`E:A->A->bool`;
        `B:A`;`leq:A`;`w1:A`;`X:A`;`vv:num->A`] BVALF_HS_SPEC) THEN
            ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`!! 3 ((3 %% 2) --> (3 %% 0))`;`D:A->bool`;`E:A->A->bool`;
        `B:A`;`leq:A`;`w1:A`;`X:A`;`vv:num->A`] BVALF_HS_IN_B) THEN
            ASM_SIMP_TAC[]];
    ALL_TAC] THEN
  (* per-hsname body-value characterization used by both GLB directions *)
  SUBGOAL_THEN
   `!c zwf zwx ii.
        c IN D /\ hsname D E B w1 X c /\ zwf IN D /\ zwx IN D /\ ii IN D /\
        ebv_in D E B leq c tt zwf /\ ebv_in D E B leq c xx zwx /\
        ebimp D E B leq zwf zwx ii
        ==> bvalf_HS D (E:A->A->bool) B leq w1 X ((3 |-> c) vv)
            ((3 %% 2) --> (3 %% 0)) = ii`
  (LABEL_TAC "body") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((3 |-> (c:A)) (vv:num->A)) /\
                  (!i. hsname D E B w1 X (((3 |-> (c:A)) (vv:num->A)) i))`
    STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC HSNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
    TRY(SUBGOAL_THEN `!i:num. bname D (E:A->A->bool) B
        ((((3 |-> (c:A)) (vv:num->A)):num->A) i)` ASSUME_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC HSNAME_BNAME THEN
    MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[valuation]; ALL_TAC]) THEN
  SUBGOAL_THEN `((3 |-> (c:A)) (vv:num->A)) 3 = c /\
                  ((3 |-> (c:A)) (vv:num->A)) 2 = tt /\
                  ((3 |-> (c:A)) (vv:num->A)) 0 = xx`
    STRIP_ASSUME_TAC THENL
     [ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) zwf B` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;
                           `leq:A`;`c:A`;`tt:A`;
        `zwf:A`] EBV_IN_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
      `bvalf_HS D (E:A->A->bool) B leq w1 X ((3 |-> (c:A)) (vv:num->A))
          (3 %% 2) IN D /\
       bvalf_HS D (E:A->A->bool) B leq w1 X
           ((3 |-> (c:A)) (vv:num->A)) (3 %% 0) IN D`
    STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [MP_TAC(ISPECL [`(3:num) %% 2`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                       `leq:A`;`w1:A`;`X:A`;
          `(3 |-> (c:A)) (vv:num->A)`] BVALF_HS_SPEC) THEN ASM_SIMP_TAC[];
        MP_TAC(ISPECL [`(3:num) %% 0`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                       `leq:A`;`w1:A`;`X:A`;
          `(3 |-> (c:A)) (vv:num->A)`] BVALF_HS_SPEC) THEN ASM_SIMP_TAC[]];
      ALL_TAC] THEN
    SUBGOAL_THEN
      `ebv_in D (E:A->A->bool) B leq c tt
          (bvalf_HS D E B leq w1 X ((3 |-> (c:A)) (vv:num->A)) (3 %% 2)) /\
       ebv_in D (E:A->A->bool) B leq c xx
          (bvalf_HS D E B leq w1 X ((3 |-> (c:A)) (vv:num->A)) (3 %% 0))`
    STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [MP_TAC(ISPECL [`3`;`2`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                       `leq:A`;`w1:A`;`X:A`;
          `(3 |-> (c:A)) (vv:num->A)`] BVALF_HS_MEM) THEN ASM_REWRITE_TAC[];
        MP_TAC(ISPECL [`3`;`0`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                       `leq:A`;`w1:A`;`X:A`;
          `(3 |-> (c:A)) (vv:num->A)`] BVALF_HS_MEM) THEN ASM_REWRITE_TAC[]];
      ALL_TAC] THEN
    SUBGOAL_THEN
      `bvalf_HS D (E:A->A->bool) B leq w1 X ((3 |-> (c:A)) (vv:num->A))
          (3 %% 2) = zwf /\
       bvalf_HS D (E:A->A->bool) B leq w1 X ((3 |-> (c:A)) (vv:num->A))
           (3 %% 0) = zwx`
    STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;
                             `leq:A`;`c:A`;`tt:A`;
          `bvalf_HS D (E:A->A->bool) B leq w1 X
              ((3 |-> (c:A)) (vv:num->A)) (3 %% 2)`;
          `zwf:A`] EBV_IN_UNIQUE) THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;
                             `leq:A`;`c:A`;`xx:A`;
          `bvalf_HS D (E:A->A->bool) B leq w1 X
              ((3 |-> (c:A)) (vv:num->A)) (3 %% 0)`;
          `zwx:A`] EBV_IN_UNIQUE) THEN ASM_REWRITE_TAC[]];
      ALL_TAC] THEN
    MP_TAC(ISPECL [`(3:num) %% 2`;`(3:num) %% 0`;`D:A->bool`;
                   `E:A->A->bool`;`B:A`;
      `leq:A`;`w1:A`;`X:A`;`(3 |-> (c:A)) (vv:num->A)`] BVALF_HS_IMP) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                         `zwf:A`;`zwx:A`;
      `bvalf_HS D (E:A->A->bool) B leq w1 X ((3 |-> (c:A)) (vv:num->A))
             ((3 %% 2) --> (3 %% 0))`;
      `ii:A`] EBIMP_UNIQUE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* reduce to ESUBVAL_EQ_SUBSETVAL_HS with candidate = the RHS bvalf_HS *)
  CONV_TAC SYM_CONV THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                       `X:A`;`xx:A`;`tt:A`;
    `zr:A`;
    `bvalf_HS D (E:A->A->bool) B leq w1 X vv (!! 3 ((3 %% 2) --> (3 %% 0)))`]
    ESUBVAL_EQ_SUBSETVAL_HS) THEN
  ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [(* lower-bound clause: RHS <= each combiner *)
    MAP_EVERY X_GEN_TAC [`w:A`;`zwf:A`;`zwx:A`;`ii:A`] THEN STRIP_TAC THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (w:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (zwf:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (zwx:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (ii:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  
    SUBGOAL_THEN
      `bvalf_HS D (E:A->A->bool) B leq w1 X ((3 |-> (w:A)) (vv:num->A))
             ((3 %% 2) --> (3 %% 0)) = ii`
    ASSUME_TAC THENL
     [USE_THEN "body" (fun th -> MATCH_MP_TAC(SPECL
         [`w:A`;`zwf:A`;`zwx:A`;`ii:A`] th)) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPECL [`3`;`(3 %% 2) --> (3 %% 0)`;`D:A->bool`;`E:A->A->bool`;`B:A`;
      `leq:A`;`w1:A`;`X:A`;`vv:num->A`;`w:A`] BVALF_HS_ALL_LB) THEN
    ASM_REWRITE_TAC[];
    (* greatest clause: any common lower bound <= RHS *)
    X_GEN_TAC `lb:A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
      (LABEL_TAC "lbh"))) THEN
    MATCH_MP_TAC(ISPECL [`3`;`(3 %% 2) --> (3 %% 0)`;`D:A->bool`;`E:A->A->bool`;
      `B:A`;`leq:A`;`w1:A`;`X:A`;`vv:num->A`;`lb:A`] BVALF_HS_ALL_GLB) THEN
    ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `c:A` THEN STRIP_TAC THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (c:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;`tt:A`]
      EBV_IN_VAL_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `zwf:A` STRIP_ASSUME_TAC) THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;`xx:A`]
      EBV_IN_VAL_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `zwx:A` STRIP_ASSUME_TAC) THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zwf:A`;`zwx:A`]
      EBIMP_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_TAC `ii:A`) THEN
    SUBGOAL_THEN `(ii:A) IN D /\ (E:A->A->bool) ii B` STRIP_ASSUME_TAC THENL
     [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EBIMP_IN); ALL_TAC] THEN
    SUBGOAL_THEN
      `bvalf_HS D (E:A->A->bool) B leq w1 X ((3 |-> (c:A)) (vv:num->A))
             ((3 %% 2) --> (3 %% 0)) = ii`
    ASSUME_TAC THENL
     [USE_THEN "body" (fun th -> MATCH_MP_TAC(SPECL
         [`c:A`;`zwf:A`;`zwx:A`;`ii:A`] th)) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "lbh" (fun th -> MATCH_MP_TAC(SPECL
        [`c:A`;`zwf:A`;`zwx:A`;`ii:A`] th)) THEN
    ASM_REWRITE_TAC[]]);;

(* ===================================================================== *)
(* H4.10b : POWER SET, membership in the power name.  POW_GE_EQ_HS (clone) *)
(* and EBV_IN_POW_GE_HS / EBV_IN_POW_HS (restated over hsbundle: the trace *)
(* name ft is the HS separation name of x by (0 %% 1), HS by HS_SEPNAME;   *)
(* FS need only contain the HS functions with domain dom x).               *)
(* ===================================================================== *)
let POW_GE_EQ_HS = prove
 (`!D (E:A->A->bool) B leq w1 X x t ft ztx ey.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
          w1 IN D /\ X IN D /\
      x IN D /\ hsname D E B w1 X x /\ t IN D /\ hsname D E B w1 X t /\
      ft IN D /\ hsname D E B w1 X ft /\ eisfun D E ft /\
      (!w. w IN D ==> (eindom D E ft w <=> eindom D E x w)) /\
      (!w q zwt m. w IN D /\ q IN D /\ zwt IN D /\ m IN D /\
                   eapply D E x w q /\ ebv_in D E B leq w t zwt /\
                   emeet D E B leq q zwt m ==> eapply D E ft w m) /\
      (!w zwx zwt r. w IN D /\ zwx IN D /\ zwt IN D /\ r IN D /\
                     hsname D E B w1 X w /\
                     ebv_in D E B leq w x zwx /\ ebv_in D E B leq w t zwt /\
                     emeet D E B leq zwx zwt r ==> ebv_in D E B leq w ft r) /\
      ztx IN D /\ esubval D E B leq x t ztx /\
      ey IN D /\ ebv_eq D E B leq t ft ey
      ==> erel D E leq ztx ey`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (x:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (t:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (ft:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (w:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) ztx B` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUBVAL_IN]; ALL_TAC] THEN
  (* common stage for t, ft *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`t:A`;`ft:A`]
         BNAME_DIRECTED) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `ao:A` (X_CHOOSE_THEN `stg:A` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `!zt. zt IN D /\ (E:A->A->bool) zt stg ==> bname D E B zt`
    ASSUME_TAC THENL
   [REPEAT STRIP_TAC THEN
     MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;
      `ao:A`;`stg:A`;`zt:A`] BNAME_STAGE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`stg:A`]
         EBVATT_EXISTS) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN EXISTS_TAC `t:A` THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `sIN:A` (X_CHOOSE_THEN `sEQ:A` ASSUME_TAC)) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`t:A`;`ft:A`] EOPAIR_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `pr:A`) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`stg:A`;
                 `sIN:A`;`sEQ:A`;
    `t:A`;`ft:A`;`pr:A`] EBVATT_VAL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
    (X_CHOOSE_THEN `zc:A` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `ebv_eq D (E:A->A->bool) B leq t ft zc` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ao:A`;
                   `stg:A`;`sIN:A`;
      `sEQ:A`;`t:A`;`ft:A`;`zc:A`] EBV_EQ_AT_STAGE) THEN
          ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `ey:A = zc` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`t:A`;`ft:A`;
      `ey:A`;`zc:A`] EBV_EQ_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ao:A`;
                 `stg:A`;`sIN:A`;
    `sEQ:A`;`t:A`;`ft:A`;`zc:A`;`ztx:A`] EBV_EQ_GLB_STAGE) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [ (* ---------------- (hu): x0 in dom t ---------------- *)
      MAP_EVERY X_GEN_TAC [`xu:A`;`qu:A`;`exv:A`;`cu:A`] THEN STRIP_TAC THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (xu:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (qu:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (exv:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (cu:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  
      SUBGOAL_THEN `eindom D (E:A->A->bool) t xu` ASSUME_TAC THENL
       [REWRITE_TAC[eindom] THEN EXISTS_TAC `qu:A` THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `hsname D (E:A->A->bool) B w1 X xu` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;`t:A`;`xu:A`]
           HSNAME_DOM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN(ACCEPT_TAC o
        CONJUNCT2)]; ALL_TAC] THEN
      TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (xu:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  SUBGOAL_THEN `(E:A->A->bool) qu B` ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;
                             `t:A`;`xu:A`;`qu:A`]
          BNAME_APPLY_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`xu:A`;`x:A`]
        EBV_IN_VAL_EXISTS) THEN ASM_REWRITE_TAC[] THEN
      DISCH_THEN(X_CHOOSE_THEN `zxx:A` STRIP_ASSUME_TAC) THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`xu:A`;`t:A`]
        EBV_IN_VAL_EXISTS) THEN ASM_REWRITE_TAC[] THEN
      DISCH_THEN(X_CHOOSE_THEN `zxt:A` STRIP_ASSUME_TAC) THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zxx:A`;`zxt:A`]
        EBALG_MEET) THEN ASM_REWRITE_TAC[] THEN
      DISCH_THEN(X_CHOOSE_TAC `r:A`) THEN
      SUBGOAL_THEN `(r:A) IN D /\ (E:A->A->bool) r B` STRIP_ASSUME_TAC THENL
       [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EMEET_IN); ALL_TAC] THEN
      SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq xu ft r` ASSUME_TAC THENL
       [UNDISCH_TAC `!w zwx zwt r. w IN D /\ zwx IN D /\ zwt IN D /\ r IN D /\
                     hsname D (E:A->A->bool) B w1 X w /\
                     ebv_in D E B leq w x zwx /\ ebv_in D E B leq w t zwt /\
                     emeet D E B leq zwx zwt r ==> ebv_in D E B leq w ft r` THEN
        DISCH_THEN(MP_TAC o SPECL [`xu:A`;`zxx:A`;`zxt:A`;`r:A`]) THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `exv:A = r` SUBST_ALL_TAC THENL
       [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;
                             `leq:A`;`xu:A`;`ft:A`;
          `exv:A`;`r:A`] EBV_IN_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ztx:A`;`qu:A`]
        EBALG_MEET) THEN ASM_REWRITE_TAC[] THEN
      DISCH_THEN(X_CHOOSE_TAC `m0:A`) THEN
      SUBGOAL_THEN `(m0:A) IN D /\ (E:A->A->bool) m0 B` STRIP_ASSUME_TAC THENL
       [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EMEET_IN); ALL_TAC] THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`qu:A`;`zxx:A`]
        EBIMP_EXISTS) THEN ASM_REWRITE_TAC[] THEN
      DISCH_THEN(X_CHOOSE_TAC `icomb:A`) THEN
      SUBGOAL_THEN `(icomb:A) IN D /\ (E:A->A->bool) icomb B`
          STRIP_ASSUME_TAC THENL
       [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EBIMP_IN); ALL_TAC] THEN
      SUBGOAL_THEN `esubcomb D (E:A->A->bool) B leq x t icomb` ASSUME_TAC THENL
       [REWRITE_TAC[esubcomb] THEN MAP_EVERY EXISTS_TAC
        [`xu:A`;`qu:A`;`zxx:A`] THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `erel D (E:A->A->bool) leq ztx icomb` ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;
                             `leq:A`;`x:A`;`t:A`;
          `ztx:A`;`icomb:A`] ESUBVAL_LB) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `erel D (E:A->A->bool) leq m0 zxx` ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;
                             `leq:A`;`ztx:A`;`qu:A`;
          `zxx:A`;`icomb:A`;`m0:A`] EBIMP_MEET_LE) THEN
              ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `erel D (E:A->A->bool) leq qu zxt` ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;
                             `leq:A`;`t:A`;`xu:A`;
          `qu:A`;`zxt:A`] EBV_MEMBER_LE_V) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `erel D (E:A->A->bool) leq m0 qu` ASSUME_TAC THENL
       [ASM_MESON_TAC[EMEET_LE]; ALL_TAC] THEN
      SUBGOAL_THEN `erel D (E:A->A->bool) leq m0 zxt` ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;
                             `leq:A`;`m0:A`;`qu:A`;
          `zxt:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `erel D (E:A->A->bool) leq m0 r` ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                             `zxx:A`;`zxt:A`;
          `r:A`;`m0:A`] EMEET_GREATEST) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;
                           `leq:A`;`ztx:A`;`qu:A`;
        `r:A`;`cu:A`;`m0:A`] EBIMP_LE_IMP) THEN ASM_REWRITE_TAC[];
      (* ---------------- (hv): y0 in dom ft = dom x ---------------- *)
      MAP_EVERY X_GEN_TAC [`yv:A`;`qyv:A`;`eyu:A`;`cv:A`] THEN STRIP_TAC THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (yv:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (qyv:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (eyu:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (cv:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  
      SUBGOAL_THEN `eindom D (E:A->A->bool) ft yv` ASSUME_TAC THENL
       [REWRITE_TAC[eindom] THEN EXISTS_TAC `qyv:A` THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `eindom D (E:A->A->bool) x yv` ASSUME_TAC THENL
       [UNDISCH_TAC `!w. w IN D ==> (eindom D (E:A->A->bool) ft w <=>
           eindom D E x w)` THEN
        DISCH_THEN(MP_TAC o SPEC `yv:A`) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `hsname D (E:A->A->bool) B w1 X yv` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;`x:A`;`yv:A`]
           HSNAME_DOM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN(ACCEPT_TAC o
        CONJUNCT2)]; ALL_TAC] THEN
      TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (yv:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  UNDISCH_TAC `eindom D (E:A->A->bool) x yv` THEN REWRITE_TAC[eindom] THEN
      DISCH_THEN(X_CHOOSE_THEN `qx0:A` STRIP_ASSUME_TAC) THEN
      SUBGOAL_THEN `(E:A->A->bool) qx0 B` ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;
                             `x:A`;`yv:A`;`qx0:A`]
          BNAME_APPLY_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`yv:A`;`t:A`]
        EBV_IN_VAL_EXISTS) THEN ASM_REWRITE_TAC[] THEN
      DISCH_THEN(X_CHOOSE_THEN `zyt:A` STRIP_ASSUME_TAC) THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`qx0:A`;`zyt:A`]
        EBALG_MEET) THEN ASM_REWRITE_TAC[] THEN
      DISCH_THEN(X_CHOOSE_TAC `mq:A`) THEN
      SUBGOAL_THEN `(mq:A) IN D /\ (E:A->A->bool) mq B` STRIP_ASSUME_TAC THENL
       [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EMEET_IN); ALL_TAC] THEN
      SUBGOAL_THEN `eapply D (E:A->A->bool) ft yv mq` ASSUME_TAC THENL
       [UNDISCH_TAC `!w q zwt m. w IN D /\ q IN D /\ zwt IN D /\ m IN D /\
                     eapply D (E:A->A->bool) x w q /\
                         ebv_in D E B leq w t zwt /\
                     emeet D E B leq q zwt m ==> eapply D E ft w m` THEN
        DISCH_THEN(MP_TAC o SPECL [`yv:A`;`qx0:A`;`zyt:A`;`mq:A`]) THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `qyv:A = mq` SUBST_ALL_TAC THENL
       [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`ft:A`;
                             `yv:A`;`qyv:A`;`mq:A`]
          EAPPLY_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `eyu:A = zyt` SUBST_ALL_TAC THENL
       [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;
                             `leq:A`;`yv:A`;`t:A`;
          `eyu:A`;`zyt:A`] EBV_IN_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `erel D (E:A->A->bool) leq mq zyt` ASSUME_TAC THENL
       [ASM_MESON_TAC[EMEET_LE]; ALL_TAC] THEN
      SUBGOAL_THEN `etop D (E:A->A->bool) B leq cv` ASSUME_TAC THENL
       [SUBGOAL_THEN `etop D (E:A->A->bool) B leq cv <=>
                      erel D (E:A->A->bool) leq mq zyt`
           (fun th -> ASM_REWRITE_TAC[th]) THEN
        MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;
                             `leq:A`;`mq:A`;`zyt:A`;
          `cv:A`] EBIMP_TOP) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;
                           `leq:A`;`cv:A`;`ztx:A`]
        ETOP_GE) THEN ASM_REWRITE_TAC[]];
    DISCH_THEN ACCEPT_TAC]);;

let EBV_IN_POW_GE_HS = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X x FS tt pn zin ztx.
      hsbundle D E w1 om tw ii ci P leqp B inclB onebee X /\
      x IN D /\ hsname D E B w1 X x /\ FS IN D /\
      tt IN D /\ hsname D E B w1 X tt /\ pn IN D /\ eisfun D E pn /\
      (!f. f IN D /\ E f FS ==> hsname D E B w1 X f) /\
      (!f q. f IN D /\ E f FS /\ esubval D E B inclB x f q
       ==> eapply D E pn f q) /\
      (!f. f IN D ==> (eindom D E pn f <=> E f FS)) /\
      (!f. f IN D /\ hsname D E B w1 X f /\ eisfun D E f /\
           (!w. w IN D ==> (eindom D E f w <=> eindom D E x w)) ==> E f FS) /\
      zin IN D /\ ztx IN D /\
      ebv_in D E B inclB tt pn zin /\ esubval D E B inclB x tt ztx
      ==> erel D E inclB ztx zin`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_ASSUM(fun th -> let cs = CONJUNCTS(REWRITE_RULE[hsbundle] th)
                        and cb = CONJUNCTS(MATCH_MP HSB_CBA th) in
    MAP_EVERY ASSUME_TAC [el 0 cs; el 1 cs; el 3 cs; el 17 cs; el 19 cs;
                          el 0 cb; el 1 cb]) THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (x:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (tt:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (f:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B inclB` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B inclB` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) ztx B` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUBVAL_IN]; ALL_TAC] THEN
  (* base valuation facts *)
  SUBGOAL_THEN `valuation D (\i:num. tt:A)` ASSUME_TAC THENL
   [REWRITE_TAC[valuation] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `!i:num. hsname D (E:A->A->bool) B w1 X ((\i:num. tt:A) i)`
      ASSUME_TAC THENL
   [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* BVEQ : bvalf_HS ((0|->w)(\i.tt)) (0%%1) = [[w in tt]] *)
  SUBGOAL_THEN
   `!w z. w IN D /\ z IN D /\ hsname D (E:A->A->bool) B w1 X w /\
          ebv_in D E B inclB w tt z
          ==> bvalf_HS D E B inclB w1 X ((0 |-> w) (\i:num. tt:A)) (0 %% 1) = z`
   (LABEL_TAC "bveq") THENL
   [REPEAT STRIP_TAC THEN
    TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (w:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  
    SUBGOAL_THEN `valuation D ((0 |-> w) (\i:num. tt:A)) /\
                  (!i. hsname D (E:A->A->bool) B w1 X
                   (((0 |-> w) (\i:num. tt:A)) i))`
    STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC HSNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
    TRY(SUBGOAL_THEN `!i:num. bname D (E:A->A->bool) B
        ((((0 |-> w) (\i:num. tt:A)):num->A) i)` ASSUME_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC HSNAME_BNAME THEN
    MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[valuation]; ALL_TAC]) THEN
  SUBGOAL_THEN
     `(bvalf_HS D (E:A->A->bool) B inclB w1 X ((0 |-> w) (\i:num. tt:A))
       (0 %% 1)) IN D`
      ASSUME_TAC THENL
     [MP_TAC(ISPECL [`0 %% 1`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                     `inclB:A`;`w1:A`;`X:A`;
        `(0 |-> w) (\i:num. tt:A)`] BVALF_HS_SPEC) THEN
      ASM_REWRITE_TAC[] THEN STRIP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPECL [`0`;`1`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                   `inclB:A`;`w1:A`;`X:A`;
      `(0 |-> w) (\i:num. tt:A)`] BVALF_HS_MEM) THEN
    ASM_REWRITE_TAC[] THEN
    SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ] THEN DISCH_TAC THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;
                         `inclB:A`;`w:A`;`tt:A`;
      `bvalf_HS D (E:A->A->bool) B inclB w1 X ((0 |-> w) (\i:num. tt:A))
          (0 %% 1)`;`z:A`]
      EBV_IN_UNIQUE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* build the trace name ft = separation of x by (0%%1) at (\i.tt), slot 0 *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;`X:A`;
                 `(\i:num. tt:A)`;
    `0 %% 1`;`0`;`x:A`] ESEPNAME_EXISTS_HS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ft:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `hsname D (E:A->A->bool) B w1 X ft` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;`ii:A`;
                         `ci:A`;`P:A`;`leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;
       `(\i:num. tt:A)`;
      `0 %% 1`;`0`;`x:A`;`ft:A`] HS_SEPNAME) THEN
          ASM_REWRITE_TAC[]; ALL_TAC] THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (ft:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  (* --- POW_GE_EQ_HS char-hyp: member-char --- *)
  SUBGOAL_THEN
   `!w zwx zwt r. w IN D /\ zwx IN D /\ zwt IN D /\ r IN D /\
                  hsname D (E:A->A->bool) B w1 X w /\
                  ebv_in D E B inclB w x zwx /\ ebv_in D E B inclB w tt zwt /\
                  emeet D E B inclB zwx zwt r ==> ebv_in D E B inclB w ft r`
   (LABEL_TAC "memchar") THENL
   [REPEAT STRIP_TAC THEN
    TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (w:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w:A`;`ft:A`]
      EBV_IN_VAL_EXISTS) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `zwf:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `emeet D (E:A->A->bool) B inclB zwx
                    (bvalf_HS D E B inclB w1 X ((0 |-> w)
                        (\i:num. tt:A)) (0 %% 1)) r`
      ASSUME_TAC THENL
     [SUBGOAL_THEN
        `bvalf_HS D (E:A->A->bool) B inclB w1 X ((0 |-> w) (\i:num. tt:A))
            (0 %% 1) = zwt`
        (fun th -> REWRITE_TAC[th]) THENL
       [USE_THEN "bveq" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(zwf:A) = r` SUBST_ALL_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;
                           `X:A`;`(\i:num. tt:A)`;
        `0 %% 1`;`0`;`x:A`;`w:A`;`ft:A`;`zwf:A`;`zwx:A`;`r:A`]
            EBV_IN_SEP_HS) THEN
      ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  (* --- POW_GE_EQ_HS char-hyp: apply-char --- *)
  SUBGOAL_THEN
   `!w q zwt m. w IN D /\ q IN D /\ zwt IN D /\ m IN D /\
                eapply D (E:A->A->bool) x w q /\ ebv_in D E B inclB w tt zwt /\
                emeet D E B inclB q zwt m ==> eapply D E ft w m`
   (LABEL_TAC "applychar") THENL
   [REPEAT STRIP_TAC THEN
    
    SUBGOAL_THEN `eindom D (E:A->A->bool) x w` ASSUME_TAC THENL
     [REWRITE_TAC[eindom] THEN EXISTS_TAC `q:A` THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `hsname D (E:A->A->bool) B w1 X w` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;`x:A`;`w:A`]
           HSNAME_DOM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN(ACCEPT_TAC o
        CONJUNCT2)]; ALL_TAC] THEN
    TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (w:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  SUBGOAL_THEN `emeet D (E:A->A->bool) B inclB q
                    (bvalf_HS D E B inclB w1 X ((0 |-> w)
                        (\i:num. tt:A)) (0 %% 1)) m`
      ASSUME_TAC THENL
     [SUBGOAL_THEN
        `bvalf_HS D (E:A->A->bool) B inclB w1 X ((0 |-> w) (\i:num. tt:A))
            (0 %% 1) = zwt`
        (fun th -> REWRITE_TAC[th]) THENL
       [USE_THEN "bveq" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    UNDISCH_TAC `!w q m. w IN D /\ q IN D /\ eindom D (E:A->A->bool) x w /\
                    eapply D E x w q /\
                    emeet D E B inclB q
                      (bvalf_HS D E B inclB w1 X ((0 |-> w)
                          (\i:num. tt:A)) (0 %% 1)) m
                    ==> eapply D E ft w m` THEN
    DISCH_THEN(MP_TAC o SPECL [`w:A`;`q:A`;`m:A`]) THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ey = [[tt = ft]] *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`tt:A`;`ft:A`]
    EBV_EQ_VAL_EXISTS) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `ey:A` STRIP_ASSUME_TAC) THEN
  (* direction (B): ztx <= ey *)
  SUBGOAL_THEN `erel D (E:A->A->bool) inclB ztx ey` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;
                         `X:A`;`x:A`;`tt:A`;
      `ft:A`;`ztx:A`;`ey:A`] POW_GE_EQ_HS) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* qf = [[ft SUBSET x]] *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`x:A`;`ft:A`]
    ESUBVAL_EXISTS) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_TAC `qf:A`) THEN
  SUBGOAL_THEN `(qf:A) IN D /\ (E:A->A->bool) qf B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUBVAL_IN]; ALL_TAC] THEN
  (* direction (A): ztx <= qf via SUBSET_GE_OF_SMALLER *)
  SUBGOAL_THEN `erel D (E:A->A->bool) inclB ztx qf` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;
                         `inclB:A`;`x:A`;`ft:A`;
      `ztx:A`;`qf:A`] SUBSET_GE_OF_SMALLER) THEN
    ASM_REWRITE_TAC[] THEN
    (* pointwise smaller: ft(w) <= x(w) *)
    MAP_EVERY X_GEN_TAC [`w:A`;`qw:A`] THEN STRIP_TAC THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (w:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (qw:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  
    SUBGOAL_THEN `eindom D (E:A->A->bool) ft w` ASSUME_TAC THENL
     [REWRITE_TAC[eindom] THEN EXISTS_TAC `qw:A` THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `eindom D (E:A->A->bool) x w` ASSUME_TAC THENL
     [UNDISCH_TAC `!w. w IN D
                       ==> (eindom D (E:A->A->bool) ft w <=>
                            eindom D E x w)` THEN
      DISCH_THEN(MP_TAC o SPEC `w:A`) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    UNDISCH_TAC `eindom D (E:A->A->bool) x w` THEN REWRITE_TAC[eindom] THEN
    DISCH_THEN(X_CHOOSE_THEN `qx0:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(E:A->A->bool) qx0 B` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`x:A`;`w:A`;`qx0:A`]
        BNAME_APPLY_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w:A`;`tt:A`]
      EBV_IN_VAL_EXISTS) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `zwt:A` STRIP_ASSUME_TAC) THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`qx0:A`;`zwt:A`]
      EBALG_MEET) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_TAC `mq:A`) THEN
    SUBGOAL_THEN `(mq:A) IN D /\ (E:A->A->bool) mq B` STRIP_ASSUME_TAC THENL
     [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EMEET_IN); ALL_TAC] THEN
    SUBGOAL_THEN `eapply D (E:A->A->bool) ft w mq` ASSUME_TAC THENL
     [USE_THEN "applychar" (fun th -> MATCH_MP_TAC th) THEN
      MAP_EVERY EXISTS_TAC [`qx0:A`;`zwt:A`] THEN
          ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `qw:A = mq` SUBST_ALL_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`ft:A`;
                           `w:A`;`qw:A`;`mq:A`]
        EAPPLY_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    EXISTS_TAC `qx0:A` THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[EMEET_LE]; ALL_TAC] THEN
  (* pn(ft) = qf *)
  SUBGOAL_THEN `(E:A->A->bool) ft FS` ASSUME_TAC THENL
   [UNDISCH_TAC `!f. f IN D /\ hsname D (E:A->A->bool) B w1 X f /\
    eisfun D E f /\
                     (!w. w IN D ==> (eindom D E f w <=> eindom D E x w))
                     ==> E f FS` THEN
    DISCH_THEN(MATCH_MP_TAC o SPEC `ft:A`) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `eapply D (E:A->A->bool) pn ft qf` ASSUME_TAC THENL
   [UNDISCH_TAC `!f q. f IN D /\ (E:A->A->bool) f FS /\
    esubval D E B inclB x f q
                       ==> eapply D E pn f q` THEN
    DISCH_THEN(MP_TAC o SPECL [`ft:A`;`qf:A`]) THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* c = qf MEET ey, then EBV_IN_GE_TERM_V gives c <= zin *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`qf:A`;`ey:A`]
    EBALG_MEET) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_TAC `c:A`) THEN
  SUBGOAL_THEN `(c:A) IN D /\ (E:A->A->bool) c B` STRIP_ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EMEET_IN); ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) inclB c zin` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;
                         `inclB:A`;`tt:A`;`pn:A`;
      `zin:A`;`ft:A`;`qf:A`;`ey:A`;`c:A`] EBV_IN_GE_TERM_V) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ztx <= c, then trans *)
  SUBGOAL_THEN `erel D (E:A->A->bool) inclB ztx c` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;
                         `inclB:A`;`qf:A`;`ey:A`;
      `c:A`;`ztx:A`] EMEET_GREATEST) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) zin B` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;
                         `inclB:A`;`tt:A`;`pn:A`;
      `zin:A`] EBV_IN_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`ztx:A`;`c:A`;
    `zin:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[]);;

let EBV_IN_POW_HS = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X x FS tt pn zin ztx.
      hsbundle D E w1 om tw ii ci P leqp B inclB onebee X /\
      x IN D /\ hsname D E B w1 X x /\ FS IN D /\
      tt IN D /\ hsname D E B w1 X tt /\ pn IN D /\ eisfun D E pn /\
      (!f. f IN D /\ E f FS ==> hsname D E B w1 X f) /\
      (!f q. f IN D /\ E f FS /\ esubval D E B inclB x f q
       ==> eapply D E pn f q) /\
      (!f. f IN D ==> (eindom D E pn f <=> E f FS)) /\
      (!f. f IN D /\ hsname D E B w1 X f /\ eisfun D E f /\
           (!w. w IN D ==> (eindom D E f w <=> eindom D E x w)) ==> E f FS) /\
      zin IN D /\ ztx IN D /\
      ebv_in D E B inclB tt pn zin /\ esubval D E B inclB x tt ztx
      ==> zin = ztx`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_ASSUM(fun th -> let cs = CONJUNCTS(REWRITE_RULE[hsbundle] th)
                        and cb = CONJUNCTS(MATCH_MP HSB_CBA th) in
    MAP_EVERY ASSUME_TAC [el 0 cs; el 1 cs; el 3 cs; el 17 cs; el 19 cs;
                          el 0 cb; el 1 cb]) THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (x:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (tt:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (f:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B inclB` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B inclB` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) ztx B` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUBVAL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) zin B` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;
                         `inclB:A`;`tt:A`;`pn:A`;
      `zin:A`] EBV_IN_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;
                       `zin:A`;`ztx:A`]
    EPORDER_ANTISYM) THEN
  ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [SUBGOAL_THEN `!f. f IN D /\ (E:A->A->bool) f FS
    ==> bname D E B f` ASSUME_TAC THENL
     [REPEAT STRIP_TAC THEN
     MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
      ASM_SIMP_TAC[]; ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;
                         `inclB:A`;`x:A`;`FS:A`;
      `tt:A`;`pn:A`;`zin:A`;`ztx:A`] EBV_IN_POW_LE) THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;`ii:A`;
                         `ci:A`;`P:A`;`leqp:A`;`B:A`;`inclB:A`;`onebee:A`;
        `X:A`;`x:A`;`FS:A`;
      `tt:A`;`pn:A`;`zin:A`;`ztx:A`] EBV_IN_POW_GE_HS) THEN
          ASM_REWRITE_TAC[]]);;

(* ===================================================================== *)
(* H4.10c : POWER SET, the HS function set.  HS_POWFS: the HS functions f  *)
(* with dom f = dom xx form a set FS (inside xx's own HS stage), carved   *)
(* out by separation; HSSTAGE_INTRO + HSSTAGE_DOM give the converse.       *)
(* ===================================================================== *)
let HS_POWFS = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X xx.
     hsbundle D E w1 om tw ii ci P leqp B inclB onebee X /\
     xx IN D /\ hsname D E B w1 X xx
     ==> ?FS a ya. FS IN D /\ a IN D /\ ya IN D /\ eordinal D E a /\
         hsstage D E B w1 X a ya /\
                   (!f. f IN D ==> (E f FS <=>
                          hsname D E B w1 X f /\ eisfun D E f /\
                          (!w. w IN D ==> (eindom D E f w <=>
                                           eindom D E xx w)))) /\
                   (!f. f IN D /\ E f FS ==> E f ya)`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "hsb")
             (CONJUNCTS_THEN2 (LABEL_TAC "xxD") (LABEL_TAC "hsxx"))) THEN
  USE_THEN "hsb" (MP_TAC o MATCH_MP HSB_CBA) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "cba")
             (CONJUNCTS_THEN2 (LABEL_TAC "inclD") (LABEL_TAC "leqpD"))) THEN
  USE_THEN "hsb" (MP_TAC o REWRITE_RULE[hsbundle]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
             (CONJUNCTS_THEN2 (LABEL_TAC "vl")
              (CONJUNCTS_THEN2 (LABEL_TAC "eom")
               (CONJUNCTS_THEN2 (LABEL_TAC "w1D")
                (CONJUNCTS_THEN2 (LABEL_TAC "w1card")
                 (CONJUNCTS_THEN2 (LABEL_TAC "omw1e")
                  (CONJUNCTS_THEN2 (LABEL_TAC "w1min")
                   (CONJUNCTS_THEN2 (LABEL_TAC "cr1")
                    (CONJUNCTS_THEN2 (LABEL_TAC "cr2")
                     (CONJUNCTS_THEN2 (LABEL_TAC "ftw")
                      (CONJUNCTS_THEN2 (LABEL_TAC "coh")
                       (CONJUNCTS_THEN2 (LABEL_TAC "leq")
                        (CONJUNCTS_THEN2 (LABEL_TAC "ros")
                         (CONJUNCTS_THEN2 (LABEL_TAC "inc")
                          (CONJUNCTS_THEN2 (LABEL_TAC "porder")
      (CONJUNCTS_THEN2 (LABEL_TAC "top")
       (CONJUNCTS_THEN2 (LABEL_TAC "oneD")
        (CONJUNCTS_THEN2 (LABEL_TAC "BD")
         (CONJUNCTS_THEN2 (LABEL_TAC "oneB")
          (CONJUNCTS_THEN2 (LABEL_TAC "XD")
           (CONJUNCTS_THEN2 (LABEL_TAC "ciX")
            (LABEL_TAC "PX")))))))))))))))))))))) THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B inclB /\ eporder D E B inclB`
   (CONJUNCTS_THEN2 (LABEL_TAC "balg") (LABEL_TAC "pord")) THENL
   [USE_THEN "cba" (fun th -> let b = MATCH_MP ECBA_IMP_BALG th in
      ACCEPT_TAC(CONJ b (MATCH_MP EBALG_IMP_PORDER b)));
    ALL_TAC] THEN
  SUBGOAL_THEN `?a y. a IN D /\ y IN D /\ eordinal D (E:A->A->bool) a /\
                      hsstage D E B w1 X a y /\ E xx y`
   (X_CHOOSE_THEN `a:A` (X_CHOOSE_THEN `ya:A` (CONJUNCTS_THEN2 (LABEL_TAC "aD")
     (CONJUNCTS_THEN2 (LABEL_TAC "yaD") (CONJUNCTS_THEN2 (LABEL_TAC "aord")
       (CONJUNCTS_THEN2 (LABEL_TAC "hsay") (LABEL_TAC "xxya"))))))) THENL
   [USE_THEN "hsxx" (ACCEPT_TAC o REWRITE_RULE[hsname]); ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;`a:A`;`ya:A`]
         HSSTAGE_CHAR) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `wa:A` (CONJUNCTS_THEN2 (LABEL_TAC "waD")
      (CONJUNCTS_THEN2 (LABEL_TAC "wach") (LABEL_TAC "wafuns")))) THEN
  USE_THEN "modl" (X_CHOOSE_TAC `v0:num->A` o MATCH_MP VALUATION_EXISTS o
                   MATCH_MP MODEL_NONEMPTY) THEN
  USE_THEN "modl" (MP_TAC o SPECL
    [`!! 21 ((?? 22 (apply_form 0 21 22)) <->
             (?? 22 (apply_form 14 21 22)))`; `0`;
     `(14 |-> (xx:A)) (v0:num->A)`; `ya:A`] o MATCH_MP ZF_SEPARATION) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL [MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THEN
                    FIRST_ASSUM ACCEPT_TAC;
                    USE_THEN "yaD" ACCEPT_TAC];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `FS:A` (CONJUNCTS_THEN2 (LABEL_TAC "FSD")
      (LABEL_TAC "FSch0"))) THEN
  (* the separation formula says dom f = dom xx *)
  SUBGOAL_THEN
   `!f:A. f IN D
          ==> (holds D (E:A->A->bool) ((0 |-> (f:A))
              ((14 |-> (xx:A)) (v0:num->A)))
                 (!! 21 ((?? 22 (apply_form 0 21 22)) <->
                         (?? 22 (apply_form 14 21 22)))) <=>
               (!w. w IN D ==> (eindom D E f w <=> eindom D E xx w)))`
   (LABEL_TAC "sem") THENL
   [X_GEN_TAC `f:A` THEN DISCH_THEN(LABEL_TAC "fD") THEN
    REWRITE_TAC[holds; HOLDS_IFF; HOLDS_EX; eindom] THEN
    MATCH_MP_TAC(MESON[] `(!w:A. w IN D ==> (Pw w <=> Qw w)) ==>
                          ((!w. w IN D ==> Pw w) <=>
                           (!w. w IN D ==> Qw w))`) THEN
    X_GEN_TAC `w:A` THEN DISCH_THEN(LABEL_TAC "wD") THEN
    MATCH_MP_TAC(TAUT `(a <=> a') /\ (b <=> b')
                 ==> ((a <=> b) <=> (a' <=> b'))`) THEN
    CONJ_TAC THEN
    (MATCH_MP_TAC(MESON[] `(!s:A. s IN D ==> (P s <=> Q s))
                          ==> ((?s. s IN D /\ P s) <=>
                               (?s. s IN D /\ Q s))`) THEN
    X_GEN_TAC `q:A` THEN DISCH_THEN(LABEL_TAC "qD") THEN
    SUBGOAL_THEN `valuation D ((22 |-> (q:A))
        ((21 |-> (w:A)) ((0 |-> (f:A)) ((14 |-> (xx:A)) (v0:num->A)))))`
        (LABEL_TAC "vq") THENL
     [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC) THEN
      FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    USE_THEN "vq" (fun vth -> SIMP_TAC[vth; HOLDS_APPLY_FORM]) THEN
    REWRITE_TAC[VALMOD; ARITH_EQ]);
    ALL_TAC] THEN
  SUBGOAL_THEN `!f:A. f IN D ==> ((E:A->A->bool) f FS <=> E f ya /\
      (!w. w IN D ==> (eindom D E f w <=> eindom D E xx w)))`
   (LABEL_TAC "FSch1") THENL
   [X_GEN_TAC `f:A` THEN DISCH_THEN(LABEL_TAC "fD") THEN
    USE_THEN "FSch0" (MP_TAC o SPEC `f:A`) THEN
    ANTS_TAC THENL [USE_THEN "fD" ACCEPT_TAC; DISCH_THEN SUBST1_TAC] THEN
    USE_THEN "sem" (MP_TAC o SPEC `f:A`) THEN
    ANTS_TAC THENL [USE_THEN "fD" ACCEPT_TAC; DISCH_THEN SUBST1_TAC] THEN
    REFL_TAC;
    ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`FS:A`;`a:A`;`ya:A`] THEN REPEAT CONJ_TAC THEN
      TRY(FIRST_ASSUM ACCEPT_TAC) THENL
   [X_GEN_TAC `f:A` THEN DISCH_THEN(LABEL_TAC "fD") THEN
    USE_THEN "FSch1" (MP_TAC o SPEC `f:A`) THEN
    ANTS_TAC THENL [USE_THEN "fD" ACCEPT_TAC; DISCH_THEN SUBST1_TAC] THEN
    EQ_TAC THENL
     [DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "fya") (LABEL_TAC "deq")) THEN
      REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THENL
       [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;`a:A`;
                      `ya:A`;`f:A`] HSNAME_STAGE) THEN
        ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                        DISCH_THEN ACCEPT_TAC];
        USE_THEN "wafuns" (MP_TAC o SPEC `f:A` o CONJUNCT2 o
                           REWRITE_RULE[ehsfuns]) THEN
        ANTS_TAC THENL [USE_THEN "fD" ACCEPT_TAC; ALL_TAC] THEN
        DISCH_THEN(fun th -> USE_THEN "fya" (MP_TAC o EQ_MP th)) THEN
        REWRITE_TAC[ehsmem; ebnmem] THEN DISCH_THEN(ACCEPT_TAC o
            CONJUNCT1 o CONJUNCT1)];
      DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "hsf")
                 (CONJUNCTS_THEN2 (LABEL_TAC "isff") (LABEL_TAC "deq"))) THEN
      CONJ_TAC THENL [ALL_TAC; USE_THEN "deq" ACCEPT_TAC] THEN
      SUBGOAL_THEN `bname D (E:A->A->bool) B f` (LABEL_TAC "bnf") THENL
       [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
        REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;`f:A`]
             HSNAME_SYM) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN(LABEL_TAC "symf")] THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;`f:A`;`a:A`;
                    `ya:A`] HSSTAGE_INTRO) THEN
      ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
      REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      X_GEN_TAC `z:A` THEN DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "zD")
          (LABEL_TAC "zf")) THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`f:A`;`z:A`]
             BNAME_MEM_PAIR) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `u0:A` (X_CHOOSE_THEN `c0:A`
          (CONJUNCTS_THEN2 (LABEL_TAC "u0D")
        (CONJUNCTS_THEN2 (LABEL_TAC "c0D")
         (CONJUNCTS_THEN2 (LABEL_TAC "c0B") (LABEL_TAC "op0")))))) THEN
      SUBGOAL_THEN `eindom D (E:A->A->bool) xx u0` (LABEL_TAC "xxu0") THENL
       [USE_THEN "deq" (MP_TAC o SPEC `u0:A`) THEN
        ANTS_TAC THENL [USE_THEN "u0D" ACCEPT_TAC;
                        DISCH_THEN(SUBST1_TAC o SYM)] THEN
        REWRITE_TAC[eindom; eapply] THEN EXISTS_TAC `c0:A` THEN
        CONJ_TAC THENL [USE_THEN "c0D" ACCEPT_TAC; ALL_TAC] THEN
        EXISTS_TAC `z:A` THEN CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
        ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;`a:A`;`ya:A`;
                    `xx:A`;`u0:A`] HSSTAGE_DOM) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
               (X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `zb:A`
      (CONJUNCTS_THEN2 (LABEL_TAC "bD") (CONJUNCTS_THEN2 (LABEL_TAC "zbD")
        (CONJUNCTS_THEN2 (LABEL_TAC "ba")
         (CONJUNCTS_THEN2 (LABEL_TAC "hsbzb") (LABEL_TAC "u0zb")))))))) THEN
      MAP_EVERY EXISTS_TAC [`u0:A`;`c0:A`] THEN REPEAT CONJ_TAC THEN
          TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      MAP_EVERY EXISTS_TAC [`b:A`;`zb:A`] THEN REPEAT CONJ_TAC THEN
          FIRST_ASSUM ACCEPT_TAC];
    X_GEN_TAC `f:A` THEN DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "fD")
        (LABEL_TAC "fFS")) THEN
    USE_THEN "FSch1" (MP_TAC o SPEC `f:A`) THEN
    ANTS_TAC THENL [USE_THEN "fD" ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "fFS" (MP_TAC o EQ_MP th)) THEN
    DISCH_THEN(ACCEPT_TAC o CONJUNCT1)]);;

(* ===================================================================== *)
(* H4.10d : POWER SET, the HS power name.  POW_SYM: the power name over FS *)
(* (all HS functions with domain dom xx) is autN-fixed when xx is (FS is   *)
(* autN-invariant; esubval equivariant via POW_RHS_SUBVAL_HS +            *)
(* BVALF_HS_EQUIV at the constant valuation \i. xx).  HS_POWNAME.          *)
(* ===================================================================== *)
let POW_SYM = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X sg muci
  muP autB xx FS pn.
     hsbundle D E w1 om tw ii ci P leqp B inclB onebee X /\
     sg IN D /\ eperm D E w1 sg /\ pbundle D E ci P leqp B inclB sg
         muci muP autB /\
     xx IN D /\ hsname D E B w1 X xx /\ eautn D E B autB xx xx /\
     FS IN D /\ (!f. f IN D ==> (E f FS <=> hsname D E B w1 X f /\
         eisfun D E f /\
                                 (!w. w IN D ==> (eindom D E f w <=>
                                     eindom D E xx w)))) /\
     pn IN D /\ bname D E B pn /\ (!z. z IN D ==> (E z pn <=>
                ?s q. s IN D /\ q IN D /\ E s FS /\
                    esubval D E B inclB xx s q /\
                      eopair D (E:A->A->bool) s q z))
     ==> eautn D E B autB pn pn`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "hsb")
             (CONJUNCTS_THEN2 (LABEL_TAC "sgD")
              (CONJUNCTS_THEN2 (LABEL_TAC "sgperm")
               (CONJUNCTS_THEN2 (LABEL_TAC "pb")
                (CONJUNCTS_THEN2 (LABEL_TAC "xxD")
                 (CONJUNCTS_THEN2 (LABEL_TAC "hsxx")
                  (CONJUNCTS_THEN2 (LABEL_TAC "fxx")
                   (CONJUNCTS_THEN2 (LABEL_TAC "FSD")
                    (CONJUNCTS_THEN2 (LABEL_TAC "FSch")
                     (CONJUNCTS_THEN2 (LABEL_TAC "pnD")
                      (CONJUNCTS_THEN2 (LABEL_TAC "bnpn")
                       (LABEL_TAC "pnch")))))))))))) THEN
  USE_THEN "hsb" (MP_TAC o MATCH_MP HSB_CBA) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "cba")
             (CONJUNCTS_THEN2 (LABEL_TAC "inclD") (LABEL_TAC "leqpD"))) THEN
  USE_THEN "hsb" (MP_TAC o REWRITE_RULE[hsbundle]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
             (CONJUNCTS_THEN2 (LABEL_TAC "vl")
              (CONJUNCTS_THEN2 (LABEL_TAC "eom")
               (CONJUNCTS_THEN2 (LABEL_TAC "w1D")
                (CONJUNCTS_THEN2 (LABEL_TAC "w1card")
                 (CONJUNCTS_THEN2 (LABEL_TAC "omw1e")
                  (CONJUNCTS_THEN2 (LABEL_TAC "w1min")
                   (CONJUNCTS_THEN2 (LABEL_TAC "cr1")
                    (CONJUNCTS_THEN2 (LABEL_TAC "cr2")
                     (CONJUNCTS_THEN2 (LABEL_TAC "ftw")
                      (CONJUNCTS_THEN2 (LABEL_TAC "coh")
                       (CONJUNCTS_THEN2 (LABEL_TAC "leq")
                        (CONJUNCTS_THEN2 (LABEL_TAC "ros")
                         (CONJUNCTS_THEN2 (LABEL_TAC "inc")
                          (CONJUNCTS_THEN2 (LABEL_TAC "porder")
      (CONJUNCTS_THEN2 (LABEL_TAC "top")
       (CONJUNCTS_THEN2 (LABEL_TAC "oneD")
        (CONJUNCTS_THEN2 (LABEL_TAC "BD")
         (CONJUNCTS_THEN2 (LABEL_TAC "oneB")
          (CONJUNCTS_THEN2 (LABEL_TAC "XD")
           (CONJUNCTS_THEN2 (LABEL_TAC "ciX")
            (LABEL_TAC "PX")))))))))))))))))))))) THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B inclB /\ eporder D E B inclB`
   (CONJUNCTS_THEN2 (LABEL_TAC "balg") (LABEL_TAC "pord")) THENL
   [USE_THEN "cba" (fun th -> let b = MATCH_MP ECBA_IMP_BALG th in
      ACCEPT_TAC(CONJ b (MATCH_MP EBALG_IMP_PORDER b)));
    ALL_TAC] THEN
  USE_THEN "pb" (fun th -> let cs = CONJUNCTS(REWRITE_RULE[pbundle] th) in
    LABEL_TAC "autBD" (el 2 cs) THEN LABEL_TAC "bijB" (el 5 cs) THEN
    LABEL_TAC "presB" (el 10 cs)) THEN
  USE_THEN "bijB" (fun th -> let cs = CONJUNCTS(REWRITE_RULE[ebij] th) in
    LABEL_TAC "bijtot" (el 2 cs) THEN LABEL_TAC "bijsv" (el 3 cs)) THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B xx` (LABEL_TAC "bnxx") THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
   `!f f'. f IN D /\ hsname D (E:A->A->bool) B w1 X f /\
       (!w. w IN D ==> (eindom D E f w <=> eindom D E xx w)) /\
           eautn D E B autB f f' ==> (!w. w IN D
               ==> (eindom D E f' w <=> eindom D E xx w))`
   (LABEL_TAC "dommap") THENL
   [MAP_EVERY X_GEN_TAC [`f:A`;`f':A`] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "fD")
               (CONJUNCTS_THEN2 (LABEL_TAC "hsf")
                (CONJUNCTS_THEN2 (LABEL_TAC "deqf") (LABEL_TAC "aff'")))) THEN
    SUBGOAL_THEN `(f':A) IN D` (LABEL_TAC "f'D") THENL
     [USE_THEN "aff'" (ACCEPT_TAC o CONJUNCT2 o MATCH_MP
                       AUTN_IMP); ALL_TAC] THEN
    SUBGOAL_THEN `bname D (E:A->A->bool) B f` (LABEL_TAC "bnf") THENL
     [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
      REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    X_GEN_TAC `w:A` THEN DISCH_THEN(LABEL_TAC "wD") THEN EQ_TAC THENL
     [REWRITE_TAC[eindom] THEN DISCH_THEN(X_CHOOSE_THEN `c':A`
         (CONJUNCTS_THEN2 (LABEL_TAC "c'D") (LABEL_TAC "af'wc'"))) THEN
      USE_THEN "af'wc'" (MP_TAC o REWRITE_RULE[eapply]) THEN
    DISCH_THEN(X_CHOOSE_THEN `z1:A` (CONJUNCTS_THEN2 (LABEL_TAC "op1")
        (LABEL_TAC "z1f'"))) THEN
    SUBGOAL_THEN `(z1:A) IN D` (LABEL_TAC "z1D") THENL
     [USE_THEN "op1" (ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`f:A`;`f':A`;
                    `z1:A`] AUTN_MEM) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "z1f'" (MP_TAC o EQ_MP th)) THEN
    DISCH_THEN(X_CHOOSE_THEN `m:A` (X_CHOOSE_THEN `t:A`
        (X_CHOOSE_THEN `c:A` (X_CHOOSE_THEN `t2:A`
        (X_CHOOSE_THEN `c2:A` (CONJUNCTS_THEN2 (LABEL_TAC "mD")
        (CONJUNCTS_THEN2 (LABEL_TAC "tD")
         (CONJUNCTS_THEN2 (LABEL_TAC "cD")
          (CONJUNCTS_THEN2 (LABEL_TAC "t2D")
           (CONJUNCTS_THEN2 (LABEL_TAC "c2D")
            (CONJUNCTS_THEN2 (LABEL_TAC "mf")
             (CONJUNCTS_THEN2 (LABEL_TAC "opm")
              (CONJUNCTS_THEN2 (LABEL_TAC "att2")
               (CONJUNCTS_THEN2 (LABEL_TAC "acc2")
                (LABEL_TAC "op2"))))))))))))))) THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`t2:A`;`c2:A`;`w:A`;`c':A`;
