                        DISCH_THEN(SUBST1_TAC o SYM)] THEN
        REWRITE_TAC[eindom; eapply] THEN EXISTS_TAC `c:A` THEN
        CONJ_TAC THENL [USE_THEN "cD" ACCEPT_TAC; ALL_TAC] THEN
        EXISTS_TAC `m:A` THEN CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
        ALL_TAC] THEN
      REWRITE_TAC[eindom] THEN DISCH_THEN(X_CHOOSE_THEN `q:A`
          (CONJUNCTS_THEN2 (LABEL_TAC "qD") (LABEL_TAC "axtq"))) THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`xx:A`;`t:A`;`q:A`]
             BNAME_APPLY_IN_B) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN(LABEL_TAC "qB")] THEN
