                (LABEL_TAC "op2"))))))))))))))) THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`t2:A`;`c2:A`;`w:A`;`q':A`;
                    `z1:A`] EOPAIR_INJ) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
