        ALL_TAC] THEN
      REWRITE_TAC[eindom] THEN DISCH_THEN(X_CHOOSE_THEN `cf:A`
          (CONJUNCTS_THEN2 (LABEL_TAC "cfD") (LABEL_TAC "aftcf"))) THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`f:A`;`t:A`;`cf:A`]
             BNAME_APPLY_IN_B) THEN
