    DISCH_THEN(fun th -> USE_THEN "zpn" (MP_TAC o EQ_MP th)) THEN
    DISCH_THEN(X_CHOOSE_THEN `s1:A` (X_CHOOSE_THEN `q1:A`
        (CONJUNCTS_THEN2 (LABEL_TAC "s1D")
      (CONJUNCTS_THEN2 (LABEL_TAC "q1D") (CONJUNCTS_THEN2 (LABEL_TAC "s1FS")
        (CONJUNCTS_THEN2 (LABEL_TAC "svq1") (LABEL_TAC "ops1"))))))) THEN
    USE_THEN "FSbwd" (MP_TAC o SPEC `s1:A`) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `s0:A` (CONJUNCTS_THEN2 (LABEL_TAC "s0D")
        (CONJUNCTS_THEN2
      (LABEL_TAC "s0FS") (LABEL_TAC "as0s1")))) THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`xx:A`;`s0:A`]
           ESUBVAL_EXISTS) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `q0:A` (LABEL_TAC "svq0")) THEN
    USE_THEN "svq0" (fun th -> LABEL_TAC "q0D"
                     (CONJUNCT1(MATCH_MP ESUBVAL_IN th))) THEN
    USE_THEN "veq" (MP_TAC o SPECL [`s0:A`;`s1:A`;`q0:A`;`q1:A`]) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN(LABEL_TAC "aq0q1")] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`s0:A`;`q0:A`] EOPAIR_EXISTS) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `m0:A` (LABEL_TAC "opm0")) THEN
    SUBGOAL_THEN `(m0:A) IN D` (LABEL_TAC "m0D") THENL
     [USE_THEN "opm0" (ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) m0 pn` (LABEL_TAC "m0pn") THENL
     [USE_THEN "pnch" (MP_TAC o SPEC `m0:A`) THEN
      ANTS_TAC THENL [USE_THEN "m0D" ACCEPT_TAC; DISCH_THEN SUBST1_TAC] THEN
      MAP_EVERY EXISTS_TAC [`s0:A`;`q0:A`] THEN REPEAT CONJ_TAC THEN
          FIRST_ASSUM ACCEPT_TAC;
      ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`m0:A`;`s0:A`;`q0:A`;`s1:A`;`q1:A`] THEN
    REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC]);;

let HS_POWNAME = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X xx FS a ya pn.
     hsbundle D E w1 om tw ii ci P leqp B inclB onebee X /\
     xx IN D /\ hsname D E B w1 X xx /\
     FS IN D /\ (!f. f IN D ==> (E f FS <=> hsname D E B w1 X f /\
         eisfun D E f /\
                                 (!w. w IN D ==> (eindom D E f w <=>
                                     eindom D E xx w)))) /\
     a IN D /\ ya IN D /\ eordinal D E a /\ hsstage D E B w1 X a ya /\
     (!f. f IN D /\ E f FS ==> E f ya) /\
     pn IN D /\ eisfun D E pn /\ (!z. z IN D ==> (E z pn <=>
                ?s q. s IN D /\ q IN D /\ E s FS /\
                    esubval D E B inclB xx s q /\
                      eopair D (E:A->A->bool) s q z))
     ==> hsname D E B w1 X pn`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "hsb")
             (CONJUNCTS_THEN2 (LABEL_TAC "xxD")
              (CONJUNCTS_THEN2 (LABEL_TAC "hsxx")
               (CONJUNCTS_THEN2 (LABEL_TAC "FSD")
                (CONJUNCTS_THEN2 (LABEL_TAC "FSch")
                 (CONJUNCTS_THEN2 (LABEL_TAC "aD")
                  (CONJUNCTS_THEN2 (LABEL_TAC "yaD")
                   (CONJUNCTS_THEN2 (LABEL_TAC "aord")
                    (CONJUNCTS_THEN2 (LABEL_TAC "hsaya")
                     (CONJUNCTS_THEN2 (LABEL_TAC "FSya")
                      (CONJUNCTS_THEN2 (LABEL_TAC "pnD")
                       (CONJUNCTS_THEN2 (LABEL_TAC "isfun")
                        (LABEL_TAC "pnch"))))))))))))) THEN
  USE_THEN "hsb" (MP_TAC o MATCH_MP HSB_CBA) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "cba")
             (CONJUNCTS_THEN2 (LABEL_TAC "inclD") (LABEL_TAC "leqpD"))) THEN
  USE_THEN "hsb" (MP_TAC o REWRITE_RULE[hsbundle]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
             (CONJUNCTS_THEN2 (LABEL_TAC "vl")
              (CONJUNCTS_THEN2 (LABEL_TAC "eom")
               (CONJUNCTS_THEN2 (LABEL_TAC "w1D")
                (CONJUNCTS_THEN2 (LABEL_TAC "w1card")
                 (CONJUNCTS_THEN2 (LABEL_TAC "omw1e")
                  (CONJUNCTS_THEN2 (LABEL_TAC "w1min")
                   (CONJUNCTS_THEN2 (LABEL_TAC "cr1")
                    (CONJUNCTS_THEN2 (LABEL_TAC "cr2")
                     (CONJUNCTS_THEN2 (LABEL_TAC "ftw")
                      (CONJUNCTS_THEN2 (LABEL_TAC "coh")
                       (CONJUNCTS_THEN2 (LABEL_TAC "leq")
                        (CONJUNCTS_THEN2 (LABEL_TAC "ros")
                         (CONJUNCTS_THEN2 (LABEL_TAC "inc")
                          (CONJUNCTS_THEN2 (LABEL_TAC "porder")
      (CONJUNCTS_THEN2 (LABEL_TAC "top")
       (CONJUNCTS_THEN2 (LABEL_TAC "oneD")
        (CONJUNCTS_THEN2 (LABEL_TAC "BD")
         (CONJUNCTS_THEN2 (LABEL_TAC "oneB")
          (CONJUNCTS_THEN2 (LABEL_TAC "XD")
           (CONJUNCTS_THEN2 (LABEL_TAC "ciX")
            (LABEL_TAC "PX")))))))))))))))))))))) THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B inclB /\ eporder D E B inclB`
   (CONJUNCTS_THEN2 (LABEL_TAC "balg") (LABEL_TAC "pord")) THENL
   [USE_THEN "cba" (fun th -> let b = MATCH_MP ECBA_IMP_BALG th in
      ACCEPT_TAC(CONJ b (MATCH_MP EBALG_IMP_PORDER b)));
    ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B xx` (LABEL_TAC "bnxx") THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `!z. z IN D /\ (E:A->A->bool) z FS
      ==> bname D E B z` (LABEL_TAC "FSbn") THENL
   [X_GEN_TAC `f:A` THEN DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "fD")
       (LABEL_TAC "fFS")) THEN
    USE_THEN "FSch" (MP_TAC o SPEC `f:A`) THEN
    ANTS_TAC THENL [USE_THEN "fD" ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "fFS" (MP_TAC o EQ_MP th)) THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "hsf")
               (CONJUNCTS_THEN2 (LABEL_TAC "isff") (LABEL_TAC "deqf"))) THEN
    MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`FS:A`] BNAME_BOUND) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `fa:A` (X_CHOOSE_THEN `fy:A`
      (CONJUNCTS_THEN2 (LABEL_TAC "faD")
       (CONJUNCTS_THEN2 (LABEL_TAC "fyD")
        (CONJUNCTS_THEN2 (LABEL_TAC "faord")
         (CONJUNCTS_THEN2 (LABEL_TAC "bnfafy") (LABEL_TAC "FSfy"))))))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`xx:A`;`FS:A`;`fa:A`;
                `fy:A`;`pn:A`] EPOWERNAME_BNAME) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                  DISCH_THEN(LABEL_TAC "bnpn")] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;`xx:A`]
         HSNAME_SYM) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                  DISCH_THEN(LABEL_TAC "symx")] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;`ii:A`;`ci:A`;
                `P:A`;`leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`xx:A`]
      EHSSYM_ELIM_ALL) THEN
  ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ex:A` (CONJUNCTS_THEN2 (LABEL_TAC "exD")
      (CONJUNCTS_THEN2 (LABEL_TAC "exfin")
       (CONJUNCTS_THEN2 (LABEL_TAC "exsub") (LABEL_TAC "exfix"))))) THEN
  SUBGOAL_THEN `ehssym D (E:A->A->bool) B w1 X pn` (LABEL_TAC "sympn") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;`ii:A`;`ci:A`;
                  `P:A`;`leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`pn:A`;`ex:A`]
       EHSSYM_INTRO) THEN
    ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    X_GEN_TAC `sg:A` THEN DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "sgD")
      (CONJUNCTS_THEN2 (LABEL_TAC "sgperm") (LABEL_TAC "sgfix"))) THEN
    MAP_EVERY X_GEN_TAC [`muci:A`;`muP:A`;`autB:A`] THEN
    DISCH_THEN(fun th ->
      SUBGOAL_THEN `pbundle D (E:A->A->bool) ci P leqp B inclB sg muci muP autB`
          (LABEL_TAC "pb")
      THENL [REWRITE_TAC[pbundle] THEN ACCEPT_TAC th; ALL_TAC]) THEN
    USE_THEN "pb" (fun th -> let cs = CONJUNCTS(REWRITE_RULE[pbundle] th) in
      LABEL_TAC "mucD" (el 0 cs) THEN LABEL_TAC "muPD" (el 1 cs) THEN
      LABEL_TAC "autBD" (el 2 cs) THEN LABEL_TAC "mch" (el 6 cs) THEN
      LABEL_TAC "Pch" (el 7 cs) THEN LABEL_TAC "ach" (el 8 cs)) THEN
    USE_THEN "exfix" (MP_TAC o SPEC `sg:A`) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPECL [`muci:A`;`muP:A`;`autB:A`]) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN(LABEL_TAC "fxx")] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;`ii:A`;`ci:A`;
                  `P:A`;`leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`sg:A`;
        `muci:A`;`muP:A`;`autB:A`;`xx:A`;`FS:A`;`pn:A`] POW_SYM) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`a:A`] ESUC_EXISTS) THEN
  ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `a2:A` (LABEL_TAC "asuc")) THEN
  SUBGOAL_THEN `(a2:A) IN D` (LABEL_TAC "a2D") THENL
   [USE_THEN "asuc" (ACCEPT_TAC o MATCH_MP ESUC_IN); ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) a2` (LABEL_TAC "a2ord") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`a:A`;`a2:A`] EORDINAL_ESUC) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) a a2` (LABEL_TAC "aa2") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`a:A`;`a2:A`] ESUC_MEMBER) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;`a2:A`]
         HSSTAGE_EXISTS) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `y2:A` (CONJUNCTS_THEN2 (LABEL_TAC "y2D")
      (LABEL_TAC "hsa2y2"))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;`pn:A`;`a2:A`;
                `y2:A`] HSSTAGE_INTRO) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    X_GEN_TAC `z:A` THEN DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "zD")
        (LABEL_TAC "zpn")) THEN
    USE_THEN "pnch" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [USE_THEN "zD" ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "zpn" (MP_TAC o EQ_MP th)) THEN
    DISCH_THEN(X_CHOOSE_THEN `s0:A` (X_CHOOSE_THEN `q:A`
        (CONJUNCTS_THEN2 (LABEL_TAC "s0D")
      (CONJUNCTS_THEN2 (LABEL_TAC "qD") (CONJUNCTS_THEN2 (LABEL_TAC "s0FS")
        (CONJUNCTS_THEN2 (LABEL_TAC "svq") (LABEL_TAC "ops0"))))))) THEN
    SUBGOAL_THEN `(E:A->A->bool) q B` (LABEL_TAC "qB") THENL
     [USE_THEN "svq" (ACCEPT_TAC o CONJUNCT2 o MATCH_MP
                      ESUBVAL_IN); ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) s0 ya` (LABEL_TAC "s0ya") THENL
     [USE_THEN "FSya" MATCH_MP_TAC THEN CONJ_TAC THEN
      FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`s0:A`;`q:A`] THEN REPEAT CONJ_TAC THEN
        TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    MAP_EVERY EXISTS_TAC [`a:A`;`ya:A`] THEN REPEAT CONJ_TAC THEN
        FIRST_ASSUM ACCEPT_TAC;
    DISCH_THEN(LABEL_TAC "pny2")] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;`a2:A`;`y2:A`;
                `pn:A`] HSNAME_STAGE) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                  DISCH_THEN ACCEPT_TAC]);;

(* ===================================================================== *)
(* H4.10e : BVALF_HS_POWERSET -- [[powerset_ax]]^HS = TOP.  FS = the HS    *)
(* functions with domain dom xx (HS_POWFS, a set inside one HS stage);     *)
(* pn = the V^B power name over FS (EPOWERNAME_EXISTS), HS by HS_POWNAME;  *)
(* LHS [[tt IN pn]] = esubval xx tt (EBV_IN_POW_HS), RHS likewise          *)
(* (POW_RHS_SUBVAL_HS).                                                     *)
(* ===================================================================== *)
let BVALF_HS_POWERSET = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X v.
      hsbundle D E w1 om tw ii ci P leqp B inclB onebee X /\
      valuation D v /\ (!i. hsname D E B w1 X (v i))
      ==> etop D E B inclB (bvalf_HS D E B inclB w1 X v powerset_ax)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  TRY(SUBGOAL_THEN `!i:num. bname D (E:A->A->bool) B ((v:num->A) i)`
      ASSUME_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC HSNAME_BNAME THEN
    MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[valuation]; ALL_TAC]) THEN
  FIRST_ASSUM(fun th -> let cs = CONJUNCTS(REWRITE_RULE[hsbundle] th)
                        and cb = CONJUNCTS(MATCH_MP HSB_CBA th) in
    MAP_EVERY ASSUME_TAC [el 0 cs; el 1 cs; el 3 cs; el 17 cs; el 19 cs;
                          el 0 cb; el 1 cb]) THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B inclB` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  REWRITE_TAC[powerset_ax] THEN
  (* peel !!0 -> xx *)
  MP_TAC(ISPECL [`0`; `?? 1 (!! 2 ((2 %% 1) <-> !!- 3 2 (3 %% 0)))`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;`X:A`;`v:num->A`]
        BVALF_HS_ALL_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  X_GEN_TAC `xx:A` THEN STRIP_TAC THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (xx:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  SUBGOAL_THEN `valuation D ((0 |-> (xx:A)) (v:num->A)) /\
                (!i. hsname D E B w1 X (((0 |-> (xx:A)) (v:num->A)) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC HSNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  TRY(SUBGOAL_THEN `!i:num. bname D (E:A->A->bool) B
      ((((0 |-> (xx:A)) (v:num->A)):num->A) i)` ASSUME_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC HSNAME_BNAME THEN
    MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[valuation]; ALL_TAC]) THEN
  ABBREV_TAC `v0 = (0 |-> (xx:A)) (v:num->A)` THEN
  (* FS: the HS functions with domain dom xx, inside the HS stage ya *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;`ii:A`;`ci:A`;
                 `P:A`;`leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;
      `xx:A`] HS_POWFS) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `FS:A` (X_CHOOSE_THEN `a:A` (X_CHOOSE_THEN `ya:A`
    (CONJUNCTS_THEN2 (LABEL_TAC "FSD") (CONJUNCTS_THEN2 (LABEL_TAC "aD")
      (CONJUNCTS_THEN2 (LABEL_TAC "yaD") (CONJUNCTS_THEN2 (LABEL_TAC "aord")
        (CONJUNCTS_THEN2 (LABEL_TAC "hsaya") (CONJUNCTS_THEN2 (LABEL_TAC "FSch")
          (LABEL_TAC "FSya")))))))))) THEN
  SUBGOAL_THEN `!f. f IN D /\ (E:A->A->bool) f FS
      ==> hsname D E B w1 X f` (LABEL_TAC "FShs") THENL
   [X_GEN_TAC `f:A` THEN DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "fD")
       (LABEL_TAC "fFS")) THEN
    USE_THEN "FSch" (MP_TAC o SPEC `f:A`) THEN
    ANTS_TAC THENL [USE_THEN "fD" ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "fFS" (MP_TAC o EQ_MP th)) THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "hsf")
               (CONJUNCTS_THEN2 (LABEL_TAC "isff") (LABEL_TAC "deqf"))) THEN
    USE_THEN "hsf" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `!f. f IN D /\ hsname D (E:A->A->bool) B w1 X f /\
      eisfun D E f /\
                    (!w. w IN D ==> (eindom D E f w <=>
                                     eindom D E xx w)) ==> E f FS`
   (LABEL_TAC "FSin") THENL
   [X_GEN_TAC `f:A` THEN DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "fD")
       (LABEL_TAC "fprops")) THEN
    USE_THEN "FSch" (MP_TAC o SPEC `f:A`) THEN
    ANTS_TAC THENL [USE_THEN "fD" ACCEPT_TAC; DISCH_THEN SUBST1_TAC] THEN
    USE_THEN "fprops" ACCEPT_TAC;
    ALL_TAC] THEN
  (* the power name over FS *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`xx:A`;`FS:A`]
         EPOWERNAME_EXISTS) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `pn:A` (CONJUNCTS_THEN2 (LABEL_TAC "pnD")
      (CONJUNCTS_THEN2 (LABEL_TAC "isfun")
    (CONJUNCTS_THEN2 (LABEL_TAC "edom")
     (CONJUNCTS_THEN2 (LABEL_TAC "pnapp") (LABEL_TAC "pnch")))))) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;`ii:A`;`ci:A`;
                 `P:A`;`leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`xx:A`;`FS:A`;
      `a:A`;`ya:A`;`pn:A`] HS_POWNAME) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                  DISCH_THEN(LABEL_TAC "hspn")] THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (pn:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  SUBGOAL_THEN `!f:A. f IN D ==> (eindom D (E:A->A->bool) pn f <=> E f FS)`
      (LABEL_TAC "cl3") THENL
   [USE_THEN "edom" (MP_TAC o REWRITE_RULE[edomain]) THEN
    MESON_TAC[]; ALL_TAC] THEN
  (* witness pn for ??1 *)
  MATCH_MP_TAC(ISPECL [`1`; `!! 2 ((2 %% 1) <-> !!- 3 2 (3 %% 0))`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;`X:A`;`v0:num->A`;`pn:A`]
        BVALF_HS_EX_TOP) THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `valuation D ((1 |-> (pn:A)) (v0:num->A)) /\
                (!i. hsname D E B w1 X (((1 |-> (pn:A)) (v0:num->A)) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC HSNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  TRY(SUBGOAL_THEN `!i:num. bname D (E:A->A->bool) B
      ((((1 |-> (pn:A)) (v0:num->A)):num->A) i)` ASSUME_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC HSNAME_BNAME THEN
    MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[valuation]; ALL_TAC]) THEN
  ABBREV_TAC `v1 = (1 |-> (pn:A)) (v0:num->A)` THEN
  (* peel !!2 -> tt *)
  MP_TAC(ISPECL [`2`; `(2 %% 1) <-> !!- 3 2 (3 %% 0)`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;`X:A`;`v1:num->A`]
        BVALF_HS_ALL_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  X_GEN_TAC `tt:A` THEN STRIP_TAC THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (tt:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  SUBGOAL_THEN `valuation D ((2 |-> (tt:A)) (v1:num->A)) /\
                (!i. hsname D E B w1 X (((2 |-> (tt:A)) (v1:num->A)) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC HSNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  TRY(SUBGOAL_THEN `!i:num. bname D (E:A->A->bool) B
      ((((2 |-> (tt:A)) (v1:num->A)):num->A) i)` ASSUME_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC HSNAME_BNAME THEN
    MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[valuation]; ALL_TAC]) THEN
  ABBREV_TAC `vv = (2 |-> (tt:A)) (v1:num->A)` THEN
  SUBGOAL_THEN `(vv:num->A) 0 = xx /\ (vv:num->A) 1 = pn /\ (vv:num->A) 2 = tt`
  STRIP_ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["vv";"v1";"v0"] THEN
    SIMP_TAC[VALMOD_OTHER; VALMOD_BASIC; ARITH_EQ]; ALL_TAC] THEN
  (* IFF_TOP -> value equality *)
  MP_TAC(ISPECL [`2 %% 1`; `!!- 3 2 (3 %% 0)`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;`X:A`;`vv:num->A`]
        BVALF_HS_IFF_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  (* ztx = esubval xx tt *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`xx:A`;`tt:A`]
         ESUBVAL_EXISTS) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ztx:A` (LABEL_TAC "svx")) THEN
  SUBGOAL_THEN `(ztx:A) IN D /\ (E:A->A->bool) ztx B`
      (CONJUNCTS_THEN2 (LABEL_TAC "ztxD") (LABEL_TAC "ztxB")) THENL
   [USE_THEN "svx" (ACCEPT_TAC o MATCH_MP ESUBVAL_IN); ALL_TAC] THEN
  (* RHS = ztx *)
  SUBGOAL_THEN `bvalf_HS D (E:A->A->bool) B inclB w1 X vv (!!- 3 2 (3 %% 0)) =
      ztx` SUBST1_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;
                   `X:A`;`vv:num->A`;
      `xx:A`;`tt:A`;`ztx:A`] POW_RHS_SUBVAL_HS) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  (* LHS: zin = [[tt IN pn]] *)
  ABBREV_TAC `zin = bvalf_HS D (E:A->A->bool) B inclB w1 X
      (vv:num->A) (2 %% 1)` THEN
  SUBGOAL_THEN `ebv_in D (E:A->A->bool) B inclB tt pn zin`
      (LABEL_TAC "inz") THENL
   [EXPAND_TAC "zin" THEN
    MP_TAC(ISPECL [`2`;`1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;
                   `X:A`;`vv:num->A`]
      BVALF_HS_MEM) THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(zin:A) IN D` (LABEL_TAC "zinD") THENL
   [EXPAND_TAC "zin" THEN
    MP_TAC(ISPECL [`2 %% 1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;
                   `X:A`;`vv:num->A`]
      BVALF_HS_SPEC) THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;`ii:A`;`ci:A`;
                 `P:A`;`leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`xx:A`;`FS:A`;
      `tt:A`;`pn:A`;`zin:A`;`ztx:A`] EBV_IN_POW_HS) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                  DISCH_THEN ACCEPT_TAC]);;

(* ######################################################################### *)
(* S4 / H4 (part 3) : HS |= ZF -- REPLACEMENT, and the ZF ASSEMBLY.          *)
(* Replacement: HS clones of the V^B collection machinery                    *)
(* (EBVALF_EXMEM/ALLMEM, FUNC_EQ_FULL, EBV_PERWITNESS_FULL, EBV_MEMRED,      *)
(* BVAL_HS_REPLIMG_EXISTS, PERU_SUP, EBV_REPL_CORE); the uniform bound is    *)
(* NEW: HSVAL_ATTAIN_U (one set of HS names attaining every value of p(u,.) *)
(* for every u in dom aa, via COLL_L over attained pairs) cut to the HS      *)
(* members of a bname stage (autN-invariant: HSCUT_INV), whose full name is  *)
(* HS (FULLNAME_SYM, HS_FULLNAME); REPL_STABILIZE_HS; BVALF_HS_REPLACEMENT.  *)
(* Assembly: BVALF_HS_ZF_TOP, HS_QUOT_MODEL_ZF (the HS quotient by ANY      *)
(* ultrafilter is a model of ZF).                                           *)
(* ######################################################################### *)

let EBVALF_EXMEM_LE_HS = prove
 (`!D (E:A->A->bool) B leq w1 X v x a p w0.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
          w1 IN D /\ X IN D /\
      valuation D v /\ (!i. hsname D E B w1 X (v i)) /\
      ~(a = x) /\ w0 IN D /\ E w0 B /\
      (!ss m. ss IN D /\ hsname D E B w1 X ss /\
              emeet D E B leq (bvalf_HS D E B leq w1 X ((x |-> ss) v) (x %% a))
                              (bvalf_HS D E B leq w1 X ((x |-> ss) v) p) m
              ==> erel D E leq m w0)
      ==> erel D E leq (bvalf_HS D E B leq w1 X v (??- x a p)) w0`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (ss:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `!i:num. bname D (E:A->A->bool) B (((v):num->A) i)`
      ASSUME_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC HSNAME_BNAME THEN
    MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[valuation]; ALL_TAC]) THEN
  REWRITE_TAC[Existsmem_DEF] THEN
  MATCH_MP_TAC(ISPECL [`x:num`; `x %% a && p`; `D:A->bool`;`E:A->A->bool`;
                       `B:A`;`leq:A`;`w1:A`;`X:A`;`v:num->A`;`w0:A`]
                           BVALF_HS_EX_LEAST) THEN
  ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `ss:A` THEN STRIP_TAC THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (ss:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  
  SUBGOAL_THEN `valuation D ((x |-> ss)(v:num->A)) /\
                (!i. hsname D E B w1 X (((x |-> ss)(v:num->A)) i))`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD; HSNAMEVAL_VALMOD]; ALL_TAC] THEN
  TRY(SUBGOAL_THEN `!i:num. bname D (E:A->A->bool) B
      ((((x |-> ss)(v:num->A)):num->A) i)` ASSUME_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC HSNAME_BNAME THEN
    MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[valuation]; ALL_TAC]) THEN
  MP_TAC(ISPECL [`x %% a`; `p:form`; `D:A->bool`;`E:A->A->bool`;`B:A`;
                 `leq:A`;`w1:A`;`X:A`;
                 `(x |-> ss)(v:num->A)`] BVALF_HS_AND_MEET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  FIRST_X_ASSUM(MP_TAC o SPECL
    [`ss:A`; `bvalf_HS D (E:A->A->bool) B leq w1 X ((x |-> ss) v)
     (x %% a && p)`]) THEN
  ASM_REWRITE_TAC[]);;

let EBVALF_ALLMEM_LE_HS = prove
 (`!D (E:A->A->bool) B leq w1 X v x a p ss.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
          w1 IN D /\ X IN D /\
      valuation D v /\ (!i. hsname D E B w1 X (v i)) /\
      ss IN D /\ hsname D E B w1 X ss
      ==> erel D E leq (bvalf_HS D E B leq w1 X v (!!- x a p))
                       (bvalf_HS D E B leq w1 X ((x |-> ss) v) (x %% a --> p))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (ss:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `!i:num. bname D (E:A->A->bool) B (((v):num->A) i)`
      ASSUME_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC HSNAME_BNAME THEN
    MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[valuation]; ALL_TAC]) THEN
  REWRITE_TAC[Forallmem_DEF] THEN
  MATCH_MP_TAC(ISPECL [`x:num`; `x %% a --> p`; `D:A->bool`;`E:A->A->bool`;
                       `B:A`;`leq:A`;`w1:A`;`X:A`;`v:num->A`;`ss:A`]
                           BVALF_HS_ALL_LB) THEN
  ASM_REWRITE_TAC[]);;

let FUNC_EQ_FULL_HS = prove
 (`!D (E:A->A->bool) B leq w1 X v0 p y z tt s d ets.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
          w1 IN D /\ X IN D /\
      valuation D v0 /\ (!i. hsname D E B w1 X (v0 i)) /\
      hsname D E B w1 X tt /\ hsname D E B w1 X s /\ tt IN D /\ s IN D /\
      ~(z IN FV p) /\ ~(y = z) /\
      d IN D /\ E d B /\ ets IN D /\
      ebv_eq D E B leq tt s ets /\
      erel D E leq d (bvalf_HS D E B leq w1 X v0
                      (?? z (!! y (p --> Eq y z)))) /\
      erel D E leq d (bvalf_HS D E B leq w1 X ((y |-> tt) v0) p) /\
      erel D E leq d (bvalf_HS D E B leq w1 X ((y |-> s) v0) p)
      ==> erel D E leq d ets`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (tt:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (s:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `!i:num. bname D (E:A->A->bool) B (((v0):num->A) i)`
      ASSUME_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC HSNAME_BNAME THEN
    MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[valuation]; ALL_TAC]) THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_PORDER]; ALL_TAC] THEN
  (* valuation + hsname for the two image valuations *)
  SUBGOAL_THEN
   `valuation D ((y |-> tt) (v0:num->A)) /\
    (!i. hsname D E B w1 X (((y |-> tt) (v0:num->A)) i)) /\
    valuation D ((y |-> s) (v0:num->A)) /\
    (!i. hsname D E B w1 X (((y |-> s) (v0:num->A)) i))`
  STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC HSNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC HSNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  (* pt, ps in D and in B *)
  SUBGOAL_THEN
   `(bvalf_HS D (E:A->A->bool) B leq w1 X ((y |-> tt) v0) p) IN D /\
    (E:A->A->bool) (bvalf_HS D E B leq w1 X ((y |-> tt) v0) p) B /\
    (bvalf_HS D (E:A->A->bool) B leq w1 X ((y |-> s) v0) p) IN D /\
    (E:A->A->bool) (bvalf_HS D E B leq w1 X ((y |-> s) v0) p) B`
  STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THENL
     [MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                     `leq:A`;`w1:A`;`X:A`;
        `(y |-> (tt:A)) (v0:num->A)`] BVALF_HS_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                     `leq:A`;`w1:A`;`X:A`;
        `(y |-> (tt:A)) (v0:num->A)`] BVALF_HS_IN_B) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                     `leq:A`;`w1:A`;`X:A`;
        `(y |-> (s:A)) (v0:num->A)`] BVALF_HS_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                     `leq:A`;`w1:A`;`X:A`;
        `(y |-> (s:A)) (v0:num->A)`] BVALF_HS_IN_B) THEN ASM_SIMP_TAC[]];
    ALL_TAC] THEN
  (* E ets B *)
  SUBGOAL_THEN `(E:A->A->bool) ets B` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                         `tt:A`;`s:A`;`ets:A`]
      EBV_EQ_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* w = meet(pt,ps) *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
    `bvalf_HS D (E:A->A->bool) B leq w1 X ((y |-> tt) v0) p`;
    `bvalf_HS D (E:A->A->bool) B leq w1 X ((y |-> s) v0) p`] EBALG_MEET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_THEN `w:A`
      (LABEL_TAC "wmeet")) THEN
  SUBGOAL_THEN `(w:A) IN D /\ (E:A->A->bool) w B` STRIP_ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EMEET_IN); ALL_TAC] THEN
  SUBGOAL_THEN
   `erel D (E:A->A->bool) leq w (bvalf_HS D E B leq w1 X ((y |-> tt) v0) p) /\
    erel D (E:A->A->bool) leq w (bvalf_HS D E B leq w1 X ((y |-> s) v0) p)`
  STRIP_ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `bvalf_HS D (E:A->A->bool) B leq w1 X ((y |-> tt) v0) p`;
      `bvalf_HS D (E:A->A->bool) B leq w1 X ((y |-> s) v0) p`;
          `w:A`] EMEET_LE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* wimp = (w ==> ets) *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;`ets:A`]
         EBIMP_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_THEN `wimp:A`
      (LABEL_TAC "wimp")) THEN
  SUBGOAL_THEN `(wimp:A) IN D /\ (E:A->A->bool) wimp B` STRIP_ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EBIMP_IN); ALL_TAC] THEN
  (* ===== PERZ: for every hsname zz, fv(zz) <= wimp ===== *)
  SUBGOAL_THEN
   `!zz. zz IN D /\ hsname D E B w1 X zz
         ==> erel D (E:A->A->bool) leq
                (bvalf_HS D E B leq w1 X ((z |-> zz) v0)
                 (!! y (p --> Eq y z))) wimp`
  (LABEL_TAC "perz") THENL
   [X_GEN_TAC `zz:A` THEN STRIP_TAC THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (zz:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  
    (* valuation/hsname for (z|->zz)v0, (y|->tt)(z|->zz)v0, (y|->s)(z|->zz)v0 *)
    SUBGOAL_THEN
     `valuation D ((z |-> zz) (v0:num->A)) /\
      (!i. hsname D E B w1 X (((z |-> zz) (v0:num->A)) i))`
    STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC HSNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
    SUBGOAL_THEN
     `valuation D ((y |-> tt) ((z |-> zz) (v0:num->A))) /\
      (!i. hsname D E B w1 X (((y |-> tt) ((z |-> zz) (v0:num->A))) i)) /\
      valuation D ((y |-> s) ((z |-> zz) (v0:num->A))) /\
      (!i. hsname D E B w1 X (((y |-> s) ((z |-> zz) (v0:num->A))) i))`
    STRIP_ASSUME_TAC THENL
     [REPEAT CONJ_TAC THENL
       [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC HSNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC HSNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
    (* value slots of the two output valuations at y and z *)
    SUBGOAL_THEN
     `((y |-> tt) ((z |-> zz) (v0:num->A))) y = tt /\
      ((y |-> tt) ((z |-> zz) (v0:num->A))) z = zz /\
      ((y |-> s) ((z |-> zz) (v0:num->A))) y = s /\
      ((y |-> s) ((z |-> zz) (v0:num->A))) z = zz`
    STRIP_ASSUME_TAC THENL
     [REPEAT CONJ_TAC THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER]; ALL_TAC] THEN
    (* congruence: bvalf_HS ((y|->tt)(z|->zz)v0) p = bvalf_HS ((y|->tt)v0) p *)
    SUBGOAL_THEN
     `bvalf_HS D (E:A->A->bool) B leq w1 X ((y |-> tt) ((z |-> zz) v0)) p =
      bvalf_HS D E B leq w1 X ((y |-> tt) v0) p`
    (LABEL_TAC "cgt") THENL
     [MATCH_MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                           `leq:A`;`w1:A`;`X:A`;
        `(y |-> (tt:A)) ((z |-> zz) (v0:num->A))`;`(y |-> (tt:A)) (v0:num->A)`]
            BVALF_HS_FV_CONG) THEN
      ASM_REWRITE_TAC[] THEN
      X_GEN_TAC `i:num` THEN DISCH_TAC THEN
      SUBGOAL_THEN `~(i:num = z)` ASSUME_TAC THENL
          [ASM_MESON_TAC[]; ALL_TAC] THEN
      REWRITE_TAC[VALMOD] THEN ASM_CASES_TAC `i:num = y` THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `bvalf_HS D (E:A->A->bool) B leq w1 X ((y |-> s) ((z |-> zz) v0)) p =
      bvalf_HS D E B leq w1 X ((y |-> s) v0) p`
    (LABEL_TAC "cgs") THENL
     [MATCH_MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                           `leq:A`;`w1:A`;`X:A`;
        `(y |-> (s:A)) ((z |-> zz) (v0:num->A))`;`(y |-> (s:A)) (v0:num->A)`]
            BVALF_HS_FV_CONG) THEN
      ASM_REWRITE_TAC[] THEN
      X_GEN_TAC `i:num` THEN DISCH_TAC THEN
      SUBGOAL_THEN `~(i:num = z)` ASSUME_TAC THENL
          [ASM_MESON_TAC[]; ALL_TAC] THEN
      REWRITE_TAC[VALMOD] THEN ASM_CASES_TAC `i:num = y` THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    (* fv(zz), i1, etz and the two clauses fv<=i1, ebv_eq tt zz etz, ebimp pt *)
    (* etz i1                                                                 *)
    SUBGOAL_THEN
     `erel D (E:A->A->bool) leq
        (bvalf_HS D E B leq w1 X ((z |-> zz) v0) (!! y (p --> Eq y z)))
        (bvalf_HS D E B leq w1 X ((y |-> tt) ((z |-> zz) v0)) (p --> Eq y z))`
    (LABEL_TAC "lb1") THENL
     [MP_TAC(ISPECL [`y:num`;`(p --> Eq y z):form`;`D:A->bool`;
                     `E:A->A->bool`;`B:A`;
        `leq:A`;`w1:A`;`X:A`;`(z |-> zz) (v0:num->A)`;`tt:A`]
            BVALF_HS_ALL_LB) THEN
      ASM_SIMP_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
     `erel D (E:A->A->bool) leq
        (bvalf_HS D E B leq w1 X ((z |-> zz) v0) (!! y (p --> Eq y z)))
        (bvalf_HS D E B leq w1 X ((y |-> s) ((z |-> zz) v0)) (p --> Eq y z))`
    (LABEL_TAC "lb2") THENL
     [MP_TAC(ISPECL [`y:num`;`(p --> Eq y z):form`;`D:A->bool`;
                     `E:A->A->bool`;`B:A`;
        `leq:A`;`w1:A`;`X:A`;`(z |-> zz) (v0:num->A)`;`s:A`]
            BVALF_HS_ALL_LB) THEN
      ASM_SIMP_TAC[]; ALL_TAC] THEN
    (* ebv_eq tt zz etz where etz = bvalf_HS ((y|->tt)(z|->zz)v0) (Eq y z) *)
    SUBGOAL_THEN
     `ebv_eq D (E:A->A->bool) B leq tt zz
        (bvalf_HS D E B leq w1 X ((y |-> tt) ((z |-> zz) v0)) (Eq y z))`
    (LABEL_TAC "eqt") THENL
     [MP_TAC(ISPECL [`y:num`;`z:num`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                     `leq:A`;`w1:A`;`X:A`;
        `(y |-> (tt:A)) ((z |-> zz) (v0:num->A))`] BVALF_HS_EQ2) THEN
      ASM_REWRITE_TAC[] THEN
      SUBGOAL_THEN
       `((y |-> tt) ((z |-> zz) (v0:num->A))) y = tt /\
        ((y |-> tt) ((z |-> zz) (v0:num->A))) z = zz`
       (fun th -> REWRITE_TAC[th]) THENL
       [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC; ALL_TAC] THEN
    SUBGOAL_THEN
     `ebv_eq D (E:A->A->bool) B leq s zz
        (bvalf_HS D E B leq w1 X ((y |-> s) ((z |-> zz) v0)) (Eq y z))`
    (LABEL_TAC "eqs") THENL
     [MP_TAC(ISPECL [`y:num`;`z:num`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                     `leq:A`;`w1:A`;`X:A`;
        `(y |-> (s:A)) ((z |-> zz) (v0:num->A))`] BVALF_HS_EQ2) THEN
      ASM_REWRITE_TAC[] THEN
      SUBGOAL_THEN
       `((y |-> s) ((z |-> zz) (v0:num->A))) y = s /\
        ((y |-> s) ((z |-> zz) (v0:num->A))) z = zz`
       (fun th -> REWRITE_TAC[th]) THENL
       [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC; ALL_TAC] THEN
    (* ebimp pt etz i1 and ebimp ps esz i2 *)
    SUBGOAL_THEN
     `ebimp D (E:A->A->bool) B leq
        (bvalf_HS D E B leq w1 X ((y |-> tt) v0) p)
        (bvalf_HS D E B leq w1 X ((y |-> tt) ((z |-> zz) v0)) (Eq y z))
        (bvalf_HS D E B leq w1 X ((y |-> tt) ((z |-> zz) v0)) (p --> Eq y z))`
    (LABEL_TAC "imp1") THENL
     [MP_TAC(ISPECL [`p:form`;`(Eq y z):form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                     `leq:A`;`w1:A`;`X:A`;
        `(y |-> (tt:A)) ((z |-> zz) (v0:num->A))`] BVALF_HS_IMP) THEN
      ASM_REWRITE_TAC[] THEN
      DISCH_THEN(MP_TAC o ONCE_REWRITE_RULE[GSYM(ASSUME
        `bvalf_HS D (E:A->A->bool) B leq w1 X ((y |-> tt) ((z |-> zz) v0)) p =
         bvalf_HS D E B leq w1 X ((y |-> tt) v0) p`)]) THEN
      REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
     `ebimp D (E:A->A->bool) B leq
        (bvalf_HS D E B leq w1 X ((y |-> s) v0) p)
        (bvalf_HS D E B leq w1 X ((y |-> s) ((z |-> zz) v0)) (Eq y z))
        (bvalf_HS D E B leq w1 X ((y |-> s) ((z |-> zz) v0)) (p --> Eq y z))`
    (LABEL_TAC "imp2") THENL
     [MP_TAC(ISPECL [`p:form`;`(Eq y z):form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                     `leq:A`;`w1:A`;`X:A`;
        `(y |-> (s:A)) ((z |-> zz) (v0:num->A))`] BVALF_HS_IMP) THEN
      ASM_REWRITE_TAC[] THEN
      DISCH_THEN(MP_TAC o ONCE_REWRITE_RULE[GSYM(ASSUME
        `bvalf_HS D (E:A->A->bool) B leq w1 X ((y |-> s) ((z |-> zz) v0)) p =
         bvalf_HS D E B leq w1 X ((y |-> s) v0) p`)]) THEN
      REWRITE_TAC[]; ALL_TAC] THEN
    (* IN D facts for fv(zz), etz, esz, i1, i2 *)
    SUBGOAL_THEN
     `(bvalf_HS D (E:A->A->bool) B leq w1 X ((z |-> zz) v0)
       (!! y (p --> Eq y z))) IN D /\
      (bvalf_HS D (E:A->A->bool) B leq w1 X ((y |-> tt) ((z |-> zz) v0))
       (Eq y z)) IN D /\
      (bvalf_HS D (E:A->A->bool) B leq w1 X ((y |-> s) ((z |-> zz) v0))
       (Eq y z)) IN D /\
      (bvalf_HS D (E:A->A->bool) B leq w1 X ((y |-> tt) ((z |-> zz) v0))
       (p --> Eq y z)) IN D /\
      (bvalf_HS D (E:A->A->bool) B leq w1 X ((y |-> s) ((z |-> zz) v0))
       (p --> Eq y z)) IN D`
    STRIP_ASSUME_TAC THENL
     [REPEAT CONJ_TAC THENL
       [MP_TAC(ISPECL [`(!! y (p --> Eq y z)):form`;`D:A->bool`;`E:A->A->bool`;
                       `B:A`;`leq:A`;`w1:A`;`X:A`;
          `(z |-> zz) (v0:num->A)`] BVALF_HS_SPEC) THEN ASM_SIMP_TAC[];
        MP_TAC(ISPECL [`(Eq y z):form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                       `leq:A`;`w1:A`;`X:A`;
          `(y |-> (tt:A)) ((z |-> zz) (v0:num->A))`] BVALF_HS_SPEC) THEN
              ASM_SIMP_TAC[];
        MP_TAC(ISPECL [`(Eq y z):form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                       `leq:A`;`w1:A`;`X:A`;
          `(y |-> (s:A)) ((z |-> zz) (v0:num->A))`] BVALF_HS_SPEC) THEN
              ASM_SIMP_TAC[];
        MP_TAC(ISPECL [`(p --> Eq y z):form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                       `leq:A`;`w1:A`;`X:A`;
          `(y |-> (tt:A)) ((z |-> zz) (v0:num->A))`] BVALF_HS_SPEC) THEN
              ASM_SIMP_TAC[];
        MP_TAC(ISPECL [`(p --> Eq y z):form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                       `leq:A`;`w1:A`;`X:A`;
          `(y |-> (s:A)) ((z |-> zz) (v0:num->A))`] BVALF_HS_SPEC) THEN
              ASM_SIMP_TAC[]];
      ALL_TAC] THEN
    (* m = meet(fv(zz), w) *)
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `bvalf_HS D (E:A->A->bool) B leq w1 X ((z |-> zz) v0)
          (!! y (p --> Eq y z))`;`w:A`]
      EBALG_MEET) THEN
    ASM_REWRITE_TAC[] THEN
    ANTS_TAC THENL
     [MP_TAC(ISPECL [`(!! y (p --> Eq y z)):form`;`D:A->bool`;`E:A->A->bool`;
                     `B:A`;`leq:A`;`w1:A`;`X:A`;
        `(z |-> zz) (v0:num->A)`] BVALF_HS_IN_B) THEN
            ASM_SIMP_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `m:A` (LABEL_TAC "mmeet")) THEN
    SUBGOAL_THEN `(m:A) IN D /\ (E:A->A->bool) m B` STRIP_ASSUME_TAC THENL
     [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EMEET_IN); ALL_TAC] THEN
    SUBGOAL_THEN
     `erel D (E:A->A->bool) leq m
        (bvalf_HS D E B leq w1 X ((z |-> zz) v0) (!! y (p --> Eq y z))) /\
      erel D (E:A->A->bool) leq m w`
    STRIP_ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `bvalf_HS D (E:A->A->bool) B leq w1 X ((z |-> zz) v0)
            (!! y (p --> Eq y z))`;`w:A`;`m:A`]
        EMEET_LE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* m <= pt, m <= ps via w <= pt, w <= ps *)
    SUBGOAL_THEN `erel D (E:A->A->bool) leq m
        (bvalf_HS D E B leq w1 X ((y |-> tt) v0) p)`
    ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;`w:A`;
        `bvalf_HS D (E:A->A->bool) B leq w1 X ((y |-> tt) v0) p`]
            EPORDER_TRANS) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq m
        (bvalf_HS D E B leq w1 X ((y |-> s) v0) p)`
    ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;`w:A`;
        `bvalf_HS D (E:A->A->bool) B leq w1 X ((y |-> s) v0) p`]
            EPORDER_TRANS) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* EBV_FUNC_EQ: m <= ets *)
    SUBGOAL_THEN `erel D (E:A->A->bool) leq m ets` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
        [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;
         `bvalf_HS D (E:A->A->bool) B leq w1 X ((z |-> zz) v0)
             (!! y (p --> Eq y z))`;
         `bvalf_HS D (E:A->A->bool) B leq w1 X ((y |-> tt) v0) p`;
         `bvalf_HS D (E:A->A->bool) B leq w1 X ((y |-> s) v0) p`;
         `zz:A`;`tt:A`;`s:A`;
         `bvalf_HS D (E:A->A->bool) B leq w1 X
             ((y |-> tt) ((z |-> zz) v0)) (Eq y z)`;
         `bvalf_HS D (E:A->A->bool) B leq w1 X
             ((y |-> s) ((z |-> zz) v0)) (Eq y z)`;
         `ets:A`;
         `bvalf_HS D (E:A->A->bool) B leq w1 X ((y |-> tt) ((z |-> zz) v0))
             (p --> Eq y z)`;
         `bvalf_HS D (E:A->A->bool) B leq w1 X ((y |-> s) ((z |-> zz) v0))
             (p --> Eq y z)`]
        EBV_FUNC_EQ) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* E fv(zz) B  -- needed by EBIMP_LE_IMP's E a B (persist it now) *)
    SUBGOAL_THEN
     `(E:A->A->bool) (bvalf_HS D E B leq w1 X ((z |-> zz) v0)
                      (!! y (p --> Eq y z))) B`
    ASSUME_TAC THENL
     [MP_TAC(ISPECL [`(!! y (p --> Eq y z)):form`;`D:A->bool`;`E:A->A->bool`;
                     `B:A`;`leq:A`;`w1:A`;`X:A`;
        `(z |-> zz) (v0:num->A)`] BVALF_HS_IN_B) THEN
            ASM_SIMP_TAC[]; ALL_TAC] THEN
    (* EBIMP_LE_IMP: fv(zz) <= wimp *)
    MATCH_MP_TAC(ISPECL
      [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
       `bvalf_HS D (E:A->A->bool) B leq w1 X ((z |-> zz) v0)
           (!! y (p --> Eq y z))`;
       `w:A`;`ets:A`;`wimp:A`;`m:A`] EBIMP_LE_IMP) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* ===== assemble via BVALF_HS_EX_LEAST ===== *)
  SUBGOAL_THEN
   `erel D (E:A->A->bool) leq
      (bvalf_HS D E B leq w1 X v0 (?? z (!! y (p --> Eq y z)))) wimp`
  (LABEL_TAC "prem_le") THENL
   [MATCH_MP_TAC(ISPECL [`z:num`;`(!! y (p --> Eq y z)):form`;
                         `D:A->bool`;`E:A->A->bool`;
      `B:A`;`leq:A`;`w1:A`;`X:A`;`v0:num->A`;`wimp:A`] BVALF_HS_EX_LEAST) THEN
    ASM_REWRITE_TAC[] THEN USE_THEN "perz" ACCEPT_TAC; ALL_TAC] THEN
  (* d <= prem <= wimp *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq d wimp` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`d:A`;
      `bvalf_HS D (E:A->A->bool) B leq w1 X v0
          (?? z (!! y (p --> Eq y z)))`;`wimp:A`]
      EPORDER_TRANS) THEN
    ASM_REWRITE_TAC[] THEN
    MP_TAC(ISPECL [`(?? z (!! y (p --> Eq y z))):form`;`D:A->bool`;
                   `E:A->A->bool`;`B:A`;
      `leq:A`;`w1:A`;`X:A`;`v0:num->A`] BVALF_HS_IN_B) THEN
    ASM_SIMP_TAC[] THEN DISCH_TAC THEN
    MP_TAC(ISPECL [`(?? z (!! y (p --> Eq y z))):form`;`D:A->bool`;
                   `E:A->A->bool`;`B:A`;
      `leq:A`;`w1:A`;`X:A`;`v0:num->A`] BVALF_HS_SPEC) THEN
          ASM_SIMP_TAC[]; ALL_TAC] THEN
  (* d <= w *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq d w` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `bvalf_HS D (E:A->A->bool) B leq w1 X ((y |-> tt) v0) p`;
      `bvalf_HS D (E:A->A->bool) B leq w1 X ((y |-> s) v0) p`;`w:A`;`d:A`]
          EMEET_GREATEST) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* md = meet(d,w) *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`d:A`;`w:A`]
         EBALG_MEET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_THEN `md:A`
      (LABEL_TAC "mdmeet")) THEN
  SUBGOAL_THEN `(md:A) IN D /\ (E:A->A->bool) md B` STRIP_ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EMEET_IN); ALL_TAC] THEN
  (* EBIMP_MEET_LE: md <= ets *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq md ets` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                         `d:A`;`w:A`;`ets:A`;
      `wimp:A`;`md:A`] EBIMP_MEET_LE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* d <= md *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq d md` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`d:A`;
                         `w:A`;`md:A`;`d:A`]
      EMEET_GREATEST) THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`d:A`]
                 EPORDER_REFL) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* d <= md <= ets *)
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                       `d:A`;`md:A`;`ets:A`]
    EPORDER_TRANS) THEN
  ASM_REWRITE_TAC[]);;

let EBV_PERWITNESS_FULL_HS = prove
 (`!D (E:A->A->bool) B leq w1 X v x y z a p ss tt dd cn onebee SS g K m.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
          w1 IN D /\ X IN D /\
      valuation D v /\ (!i. hsname D E B w1 X (v i)) /\
      hsname D E B w1 X ss /\ ss IN D /\ hsname D E B w1 X tt /\ tt IN D /\
      ~(z IN FV p) /\ ~(y = z) /\ ~(x = y) /\ ~(x = a) /\
      dd IN D /\ (!s. s IN D /\ E s dd ==> hsname D E B w1 X s) /\
      onebee IN D /\ E onebee B /\ etop D E B leq onebee /\
      cn IN D /\ (!s. s IN D /\ E s dd ==> eapply D E cn s onebee) /\
      K IN D /\ E K B /\ ebv_in D E B leq tt cn K /\
      SS IN D /\ esubset D E SS B /\ elub D E B leq SS g /\ g IN D /\
      (!w. w IN D
           ==> (E w SS <=>
                ?s. s IN D /\ E s dd /\
                    bval_HS D E B leq w1 X ((y |-> s) ((x |-> ss) v)) p w)) /\
      m IN D /\ E m B /\
      erel D E leq m (bvalf_HS D E B leq w1 X v
                      (!!- x a (?? z (!! y (p --> Eq y z))))) /\
      erel D E leq m (bvalf_HS D E B leq w1 X ((x |-> ss) v) (x %% a)) /\
      erel D E leq m (bvalf_HS D E B leq w1 X ((y |-> tt) ((x |-> ss) v)) p) /\
      erel D E leq (bvalf_HS D E B leq w1 X ((y |-> tt) ((x |-> ss) v)) p) g
      ==> erel D E leq m K`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (ss:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (tt:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (s:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `!i:num. bname D (E:A->A->bool) B (((v):num->A) i)`
      ASSUME_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC HSNAME_BNAME THEN
    MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[valuation]; ALL_TAC]) THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_PORDER]; ALL_TAC] THEN
  (* v0 = (x|->ss)v valuation + hsname slots *)
  SUBGOAL_THEN
   `valuation D ((x |-> ss) (v:num->A)) /\
    (!i. hsname D E B w1 X (((x |-> ss) (v:num->A)) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC HSNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  (* (y|->tt)v0 valuation + hsname slots *)
  SUBGOAL_THEN
   `valuation D ((y |-> tt) ((x |-> ss) (v:num->A))) /\
    (!i. hsname D E B w1 X (((y |-> tt) ((x |-> ss) (v:num->A))) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC HSNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  (* IN D / E B facts for prem, ain, premss, i0, ptt *)
  SUBGOAL_THEN
   `(bvalf_HS D (E:A->A->bool) B leq w1 X v
     (!!- x a (?? z (!! y (p --> Eq y z))))) IN D /\
    (E:A->A->bool) (bvalf_HS D E B leq w1 X v
                    (!!- x a (?? z (!! y (p --> Eq y z))))) B /\
    (bvalf_HS D (E:A->A->bool) B leq w1 X ((x |-> ss) v) (x %% a)) IN D /\
    (E:A->A->bool) (bvalf_HS D E B leq w1 X ((x |-> ss) v) (x %% a)) B /\
    (bvalf_HS D (E:A->A->bool) B leq w1 X ((x |-> ss) v)
     (?? z (!! y (p --> Eq y z)))) IN D /\
    (E:A->A->bool) (bvalf_HS D E B leq w1 X ((x |-> ss) v)
                    (?? z (!! y (p --> Eq y z)))) B /\
    (bvalf_HS D (E:A->A->bool) B leq w1 X ((x |-> ss) v)
        (x %% a --> (?? z (!! y (p --> Eq y z))))) IN D /\
    (E:A->A->bool) (bvalf_HS D E B leq w1 X ((x |-> ss) v)
        (x %% a --> (?? z (!! y (p --> Eq y z))))) B /\
    (bvalf_HS D (E:A->A->bool) B leq w1 X ((y |-> tt) ((x |-> ss) v)) p) IN D /\
    (E:A->A->bool) (bvalf_HS D E B leq w1 X ((y |-> tt) ((x |-> ss) v)) p) B`
  STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THENL
     [MP_TAC(ISPECL [`(!!- x a (?? z (!! y (p --> Eq y z)))):form`;`D:A->bool`;
                     `E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;`X:A`;`v:num->A`]
         BVALF_HS_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`(!!- x a (?? z (!! y (p --> Eq y z)))):form`;`D:A->bool`;
                     `E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;`X:A`;`v:num->A`]
          BVALF_HS_IN_B) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`(x %% a):form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                     `w1:A`;`X:A`;`(x |-> (ss:A)) (v:num->A)`] BVALF_HS_SPEC)
          THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`(x %% a):form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                     `w1:A`;`X:A`;`(x |-> (ss:A)) (v:num->A)`] BVALF_HS_IN_B)
          THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`(?? z (!! y (p --> Eq y z))):form`;`D:A->bool`;
                     `E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;`X:A`;
          `(x |-> (ss:A)) (v:num->A)`] BVALF_HS_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`(?? z (!! y (p --> Eq y z))):form`;`D:A->bool`;
                     `E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;`X:A`;
          `(x |-> (ss:A)) (v:num->A)`] BVALF_HS_IN_B) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`(x %% a --> (?? z (!! y (p --> Eq y z)))):form`;
                     `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;`X:A`;
          `(x |-> (ss:A)) (v:num->A)`] BVALF_HS_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`(x %% a --> (?? z (!! y (p --> Eq y z)))):form`;
                     `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;`X:A`;
          `(x |-> (ss:A)) (v:num->A)`] BVALF_HS_IN_B) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                     `X:A`;`(y |-> (tt:A)) ((x |-> (ss:A)) (v:num->A))`]
          BVALF_HS_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                     `X:A`;`(y |-> (tt:A)) ((x |-> (ss:A)) (v:num->A))`]
          BVALF_HS_IN_B) THEN ASM_SIMP_TAC[]];
    ALL_TAC] THEN
  (* ebimp ain premss i0 via BVALF_HS_IMP *)
  SUBGOAL_THEN
   `ebimp D (E:A->A->bool) B leq
      (bvalf_HS D E B leq w1 X ((x |-> ss) v) (x %% a))
      (bvalf_HS D E B leq w1 X ((x |-> ss) v) (?? z (!! y (p --> Eq y z))))
      (bvalf_HS D E B leq w1 X ((x |-> ss) v)
       (x %% a --> (?? z (!! y (p --> Eq y z)))))`
  (LABEL_TAC "imp0") THENL
   [MP_TAC(ISPECL [`(x %% a):form`;`(?? z (!! y (p --> Eq y z))):form`;
                   `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;`X:A`;
       `(x |-> (ss:A)) (v:num->A)`] BVALF_HS_IMP) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* prem <= i0 via EBVALF_ALLMEM_LE_HS *)
  SUBGOAL_THEN
   `erel D (E:A->A->bool) leq
      (bvalf_HS D E B leq w1 X v (!!- x a (?? z (!! y (p --> Eq y z)))))
      (bvalf_HS D E B leq w1 X ((x |-> ss) v)
       (x %% a --> (?? z (!! y (p --> Eq y z)))))`
  (LABEL_TAC "premi0") THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;`X:A`;
                   `v:num->A`;`x:num`;`a:num`;
      `(?? z (!! y (p --> Eq y z))):form`;`ss:A`] EBVALF_ALLMEM_LE_HS) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* m <= i0 (TRANS m,prem,i0) *)
  SUBGOAL_THEN
   `erel D (E:A->A->bool) leq m
      (bvalf_HS D E B leq w1 X ((x |-> ss) v)
       (x %% a --> (?? z (!! y (p --> Eq y z)))))`
  (LABEL_TAC "mi0") THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;
      `bvalf_HS D (E:A->A->bool) B leq w1 X v
          (!!- x a (?? z (!! y (p --> Eq y z))))`;
      `bvalf_HS D (E:A->A->bool) B leq w1 X ((x |-> ss) v)
          (x %% a --> (?? z (!! y (p --> Eq y z))))`]
      EPORDER_TRANS) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* m <= premss via EBV_MP_LE *)
  SUBGOAL_THEN
   `erel D (E:A->A->bool) leq m
      (bvalf_HS D E B leq w1 X ((x |-> ss) v) (?? z (!! y (p --> Eq y z))))`
  (LABEL_TAC "mpremss") THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;
      `bvalf_HS D (E:A->A->bool) B leq w1 X ((x |-> ss) v) (x %% a)`;
      `bvalf_HS D (E:A->A->bool) B leq w1 X ((x |-> ss) v)
          (?? z (!! y (p --> Eq y z)))`;
      `bvalf_HS D (E:A->A->bool) B leq w1 X ((x |-> ss) v)
          (x %% a --> (?? z (!! y (p --> Eq y z))))`]
      EBV_MP_LE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* i0' = ebimp m K *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;`K:A`]
         EBIMP_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_THEN `imK:A`
      (LABEL_TAC "imK")) THEN
  SUBGOAL_THEN `(imK:A) IN D /\ (E:A->A->bool) imK B` STRIP_ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EBIMP_IN); ALL_TAC] THEN
  (* ===== per-pS discharge ===== *)
  SUBGOAL_THEN
   `!pS mm. pS IN D /\ E pS SS /\ emeet D (E:A->A->bool) B leq m pS mm
            ==> erel D E leq mm K`
  (LABEL_TAC "perpS") THENL
   [MAP_EVERY X_GEN_TAC [`pS:A`;`mm:A`] THEN STRIP_TAC THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (pS:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (mm:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  
    (* s in dd with pS = bvalf_HS ((y|->s)v0) p *)
    SUBGOAL_THEN
     `?s:A. s IN D /\ E s dd /\
            bval_HS D (E:A->A->bool) B leq w1 X
                ((y |-> s) ((x |-> (ss:A)) (v:num->A))) p (pS:A)`
    STRIP_ASSUME_TAC THENL
     [SUBGOAL_THEN
       `(E:A->A->bool) pS SS <=>
        (?s:A. s IN D /\ E s dd /\
               bval_HS D (E:A->A->bool) B leq w1 X
                   ((y |-> s) ((x |-> (ss:A)) (v:num->A))) p (pS:A))`
       ASSUME_TAC THENL
       [FIRST_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      ASM_MESON_TAC[];
      ALL_TAC] THEN
    (* hsname s *)
    SUBGOAL_THEN `hsname D (E:A->A->bool) B w1 X s` ASSUME_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (s:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  (* (y|->s)v0 valuation + hsname *)
    SUBGOAL_THEN
     `valuation D ((y |-> s) ((x |-> ss) (v:num->A))) /\
      (!i. hsname D E B w1 X (((y |-> s) ((x |-> ss) (v:num->A))) i))`
    STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC HSNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
    (* pS = bvalf_HS ((y|->s)v0) p *)
    SUBGOAL_THEN `pS = bvalf_HS D (E:A->A->bool) B leq w1 X
        ((y |-> s) ((x |-> ss) v)) p`
    (LABEL_TAC "pSval") THENL
     [MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                     `leq:A`;`w1:A`;`X:A`;
        `(y |-> (s:A)) ((x |-> (ss:A)) (v:num->A))`] BVALF_HS_SPEC) THEN
      ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
      MATCH_MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                           `leq:A`;`w1:A`;`X:A`;
        `(y |-> (s:A)) ((x |-> (ss:A)) (v:num->A))`;`pS:A`;
        `bvalf_HS D (E:A->A->bool) B leq w1 X ((y |-> s) ((x |-> ss) v)) p`]
            BVAL_HS_UNIQUE) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* ets = [[tt=s]] *)
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`tt:A`;`s:A`]
           EBV_EQ_VAL_EXISTS) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `ets:A` STRIP_ASSUME_TAC) THEN
    (* mm facts *)
    SUBGOAL_THEN `(mm:A) IN D /\ (E:A->A->bool) mm B` STRIP_ASSUME_TAC THENL
     [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EMEET_IN); ALL_TAC] THEN
    SUBGOAL_THEN
     `erel D (E:A->A->bool) leq mm m /\ erel D (E:A->A->bool) leq mm pS`
    STRIP_ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                           `m:A`;`pS:A`;`mm:A`]
        EMEET_LE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* mm <= premss *)
    SUBGOAL_THEN
     `erel D (E:A->A->bool) leq mm
        (bvalf_HS D E B leq w1 X ((x |-> ss) v) (?? z (!! y (p --> Eq y z))))`
    ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;
                           `leq:A`;`mm:A`;`m:A`;
        `bvalf_HS D (E:A->A->bool) B leq w1 X ((x |-> ss) v)
            (?? z (!! y (p --> Eq y z)))`]
        EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* mm <= ptt *)
    SUBGOAL_THEN
     `erel D (E:A->A->bool) leq mm
        (bvalf_HS D E B leq w1 X ((y |-> tt) ((x |-> ss) v)) p)`
    ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;
                           `leq:A`;`mm:A`;`m:A`;
        `bvalf_HS D (E:A->A->bool) B leq w1 X ((y |-> tt) ((x |-> ss) v)) p`]
        EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* mm <= pS = bvalf_HS ((y|->s)v0) p *)
    SUBGOAL_THEN
     `erel D (E:A->A->bool) leq mm
        (bvalf_HS D E B leq w1 X ((y |-> s) ((x |-> ss) v)) p)`
    ASSUME_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    (* FUNC_EQ_FULL_HS: mm <= ets = [[tt=s]] *)
    SUBGOAL_THEN `erel D (E:A->A->bool) leq mm ets` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;
                           `leq:A`;`w1:A`;`X:A`;
        `(x |-> (ss:A)) (v:num->A)`;`p:form`;`y:num`;`z:num`;`tt:A`;
            `s:A`;`mm:A`;`ets:A`]
        FUNC_EQ_FULL_HS) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* eapply cn s onebee (from the EFULLNAME dd-clause) *)
    SUBGOAL_THEN `eapply D (E:A->A->bool) cn s onebee` ASSUME_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    (* EFULLNAME_IN_GE_ELT: ets <= K *)
    SUBGOAL_THEN `erel D (E:A->A->bool) leq ets K` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                           `onebee:A`;`cn:A`;
        `s:A`;`tt:A`;`K:A`;`ets:A`] EFULLNAME_IN_GE_ELT) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* mm <= ets <= K *)
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                         `mm:A`;`ets:A`;`K:A`]
      EPORDER_TRANS) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* ===== EBV_PERWITNESS_LE ===== *)
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                       `m:A`;`K:A`;`g:A`;
    `bvalf_HS D (E:A->A->bool) B leq w1 X ((y |-> tt) ((x |-> ss) v))
        p`;`SS:A`;`imK:A`]
    EBV_PERWITNESS_LE) THEN
  ASM_REWRITE_TAC[]);;

let EBV_MEMRED_HS = prove
 (`!D (E:A->A->bool) B leq w1 X v x a p prem K.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
          w1 IN D /\ X IN D /\
      valuation D v /\ (!i. hsname D E B w1 X (v i)) /\
      ~(a = x) /\
      prem IN D /\ E prem B /\ K IN D /\ E K B /\
      (!yy qy m0.
          yy IN D /\ eapply D E (v a) yy qy /\ m0 IN D /\ E m0 B /\
          erel D E leq m0 prem /\
          erel D E leq m0 (bvalf_HS D E B leq w1 X ((x |-> yy) v) (x %% a)) /\
          erel D E leq m0 (bvalf_HS D E B leq w1 X ((x |-> yy) v) p)
          ==> erel D E leq m0 K)
      ==> (!ss m0.
              ss IN D /\ hsname D E B w1 X ss /\ m0 IN D /\ E m0 B /\
              erel D E leq m0 prem /\
              erel D E leq m0 (bvalf_HS D E B leq w1 X
                               ((x |-> ss) v) (x %% a)) /\
              erel D E leq m0 (bvalf_HS D E B leq w1 X ((x |-> ss) v) p)
              ==> erel D E leq m0 K)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (ss:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `!i:num. bname D (E:A->A->bool) B (((v):num->A) i)`
      ASSUME_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC HSNAME_BNAME THEN
    MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[valuation]; ALL_TAC]) THEN
  MAP_EVERY X_GEN_TAC [`ss:A`;`m0:A`] THEN STRIP_TAC THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (ss:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (m0:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `~(x:num = a)` ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
  (* hsname (v a) and (v a) IN D *)
  SUBGOAL_THEN
   `hsname D (E:A->A->bool) B w1 X ((v:num->A) a) /\ ((v:num->A) a) IN D`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL [ASM_MESON_TAC[]; ASM_MESON_TAC[valuation]]; ALL_TAC] THEN
  (* valuation (x|->ss)v + all-hsname *)
  SUBGOAL_THEN
   `valuation D ((x |-> ss) (v:num->A)) /\
    (!i. hsname D E B w1 X (((x |-> ss) (v:num->A)) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC HSNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  (* MEMSS, PVALSS IN D / E B *)
  SUBGOAL_THEN
   `(bvalf_HS D (E:A->A->bool) B leq w1 X ((x |-> ss) v) (x %% a)) IN D /\
    (E:A->A->bool) (bvalf_HS D E B leq w1 X ((x |-> ss) v) (x %% a)) B /\
    (bvalf_HS D (E:A->A->bool) B leq w1 X ((x |-> ss) v) p) IN D /\
    (E:A->A->bool) (bvalf_HS D E B leq w1 X ((x |-> ss) v) p) B`
  STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THENL
     [MP_TAC(ISPECL [`(x %% a):form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                     `w1:A`;`X:A`;`(x |-> (ss:A)) (v:num->A)`] BVALF_HS_SPEC)
         THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`(x %% a):form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                     `w1:A`;`X:A`;`(x |-> (ss:A)) (v:num->A)`] BVALF_HS_IN_B)
          THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                     `X:A`;`(x |-> (ss:A)) (v:num->A)`] BVALF_HS_SPEC) THEN
          ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                     `X:A`;`(x |-> (ss:A)) (v:num->A)`] BVALF_HS_IN_B) THEN
          ASM_SIMP_TAC[]];
    ALL_TAC] THEN
  (* ebv_in ss (v a) MEMSS *)
  SUBGOAL_THEN
   `ebv_in D (E:A->A->bool) B leq ss ((v:num->A) a)
      (bvalf_HS D E B leq w1 X ((x |-> ss) v) (x %% a))`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL [`x:num`;`a:num`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                   `leq:A`;`w1:A`;`X:A`;
      `(x |-> (ss:A)) (v:num->A)`] BVALF_HS_MEM) THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER]; ALL_TAC] THEN
  (* ww1 = ebimp m0 K *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m0:A`;`K:A`]
         EBIMP_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_THEN `ww1:A`
      (LABEL_TAC "ww1")) THEN
  SUBGOAL_THEN `(ww1:A) IN D /\ (E:A->A->bool) ww1 B` STRIP_ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EBIMP_IN); ALL_TAC] THEN
  (* rank rv of (v a) *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`(v:num->A) a`]
         EBNRANK_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `rv:A` (LABEL_TAC "rvrank")) THEN
  (* ===== MAIN: [[ss in aa]] <= ww1 via EBV_IN_LE_V ===== *)
  SUBGOAL_THEN
   `erel D (E:A->A->bool) leq (bvalf_HS D E B leq w1 X
       ((x |-> ss) v) (x %% a)) ww1`
  ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                         `ss:A`;`(v:num->A) a`;
      `bvalf_HS D (E:A->A->bool) B leq w1 X ((x |-> ss) v) (x %% a)`;`ww1:A`]
          EBV_IN_LE_V) THEN
    ASM_REWRITE_TAC[] THEN
    MAP_EVERY X_GEN_TAC [`yv:A`;`qy:A`;`ey:A`;`cc:A`] THEN STRIP_TAC THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (yv:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (qy:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (ey:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (cc:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  
    (* cc facts *)
    SUBGOAL_THEN `(E:A->A->bool) cc B` ASSUME_TAC THENL
     [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
    (* E ey B (the ebv_eq value [[ss=yv]]) - needed by EPORDER_TRANS target
       and EBALG_MEET(ey,PVALSS); ey has no E-fact from
          EBV_IN_LE_V's universal *)
    SUBGOAL_THEN `(E:A->A->bool) ey B` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                           `ss:A`;`yv:A`;`ey:A`]
        EBV_EQ_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
     `erel D (E:A->A->bool) leq cc qy /\ erel D (E:A->A->bool) leq cc ey`
    STRIP_ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                           `qy:A`;`ey:A`;`cc:A`]
        EMEET_LE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* E qy B *)
    SUBGOAL_THEN `(E:A->A->bool) qy B` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;
                           `(v:num->A) a`;`yv:A`;`qy:A`]
        BNAME_APPLY_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* hsname yv *)
    SUBGOAL_THEN `hsname D (E:A->A->bool) B w1 X yv` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;
                    `(v:num->A) a`;`yv:A`] HSNAME_DOM) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN REWRITE_TAC[eindom] THEN EXISTS_TAC `qy:A` THEN
        ASM_REWRITE_TAC[];
        DISCH_THEN(ACCEPT_TAC o CONJUNCT2)]; ALL_TAC] THEN
    TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (yv:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  (* valuation (x|->yv)v + all-hsname *)
    SUBGOAL_THEN
     `valuation D ((x |-> yv) (v:num->A)) /\
      (!i. hsname D E B w1 X (((x |-> yv) (v:num->A)) i))`
    STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC HSNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
    (* MEMV(yv), PVAL(yv) IN D / E B *)
    SUBGOAL_THEN
     `(bvalf_HS D (E:A->A->bool) B leq w1 X ((x |-> yv) v) (x %% a)) IN D /\
      (E:A->A->bool) (bvalf_HS D E B leq w1 X ((x |-> yv) v) (x %% a)) B /\
      (bvalf_HS D (E:A->A->bool) B leq w1 X ((x |-> yv) v) p) IN D /\
      (E:A->A->bool) (bvalf_HS D E B leq w1 X ((x |-> yv) v) p) B`
    STRIP_ASSUME_TAC THENL
     [REPEAT CONJ_TAC THENL
       [MP_TAC(ISPECL [`(x %% a):form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                       `w1:A`;`X:A`;`(x |-> (yv:A)) (v:num->A)`] BVALF_HS_SPEC)
           THEN ASM_SIMP_TAC[];
        MP_TAC(ISPECL [`(x %% a):form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                       `w1:A`;`X:A`;`(x |-> (yv:A)) (v:num->A)`] BVALF_HS_IN_B)
            THEN ASM_SIMP_TAC[];
        MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                       `X:A`;`(x |-> (yv:A)) (v:num->A)`] BVALF_HS_SPEC) THEN
            ASM_SIMP_TAC[];
        MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                       `X:A`;`(x |-> (yv:A)) (v:num->A)`] BVALF_HS_IN_B) THEN
            ASM_SIMP_TAC[]];
      ALL_TAC] THEN
    (* ebv_in yv (v a) MEMV(yv) *)
    SUBGOAL_THEN
     `ebv_in D (E:A->A->bool) B leq yv ((v:num->A) a)
        (bvalf_HS D E B leq w1 X ((x |-> yv) v) (x %% a))`
    ASSUME_TAC THENL
     [MP_TAC(ISPECL [`x:num`;`a:num`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                     `leq:A`;`w1:A`;`X:A`;
        `(x |-> (yv:A)) (v:num->A)`] BVALF_HS_MEM) THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER]; ALL_TAC] THEN
    (* eyy = [[yv=yv]] *)
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`yv:A`;`yv:A`]
           EBV_EQ_VAL_EXISTS) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `eyy:A` STRIP_ASSUME_TAC) THEN
    (* etop eyy *)
    SUBGOAL_THEN `etop D (E:A->A->bool) B leq eyy` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;
                           `leq:A`;`yv:A`;`eyy:A`]
        EBV_EQ_REFL) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* emeet qy eyy qy *)
    SUBGOAL_THEN `emeet D (E:A->A->bool) B leq qy eyy qy` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;
                           `leq:A`;`eyy:A`;`qy:A`]
        EMEET_TOP) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* qy <= MEMV(yv) *)
    SUBGOAL_THEN
     `erel D (E:A->A->bool) leq qy (bvalf_HS D E B leq w1 X
         ((x |-> yv) v) (x %% a))`
    ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                           `yv:A`;`(v:num->A) a`;
        `bvalf_HS D (E:A->A->bool) B leq w1 X ((x |-> yv) v) (x %% a)`;`yv:A`;
            `qy:A`;`eyy:A`;`qy:A`]
        EBV_IN_GE_TERM_V) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* m0y = meet(cc, m0) *)
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cc:A`;`m0:A`]
           EBALG_MEET) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_THEN `m0y:A`
        (LABEL_TAC "m0ymeet")) THEN
    SUBGOAL_THEN `(m0y:A) IN D /\ (E:A->A->bool) m0y B` STRIP_ASSUME_TAC THENL
     [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EMEET_IN); ALL_TAC] THEN
    SUBGOAL_THEN
     `erel D (E:A->A->bool) leq m0y cc /\ erel D (E:A->A->bool) leq m0y m0`
    STRIP_ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                           `cc:A`;`m0:A`;`m0y:A`]
        EMEET_LE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* m0y <= qy, m0y <= ey (via cc) *)
    SUBGOAL_THEN `erel D (E:A->A->bool) leq m0y qy` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                           `m0y:A`;`cc:A`;`qy:A`]
        EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq m0y ey` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                           `m0y:A`;`cc:A`;`ey:A`]
        EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* m0y <= prem (via m0) *)
    SUBGOAL_THEN `erel D (E:A->A->bool) leq m0y prem` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m0y:A`;
                           `m0:A`;`prem:A`]
        EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* m0y <= MEMV(yv) (via qy) *)
    SUBGOAL_THEN
     `erel D (E:A->A->bool) leq m0y (bvalf_HS D E B leq w1 X
         ((x |-> yv) v) (x %% a))`
    ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;
                           `leq:A`;`m0y:A`;`qy:A`;
        `bvalf_HS D (E:A->A->bool) B leq w1 X ((x |-> yv) v) (x %% a)`]
            EPORDER_TRANS) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* m0y <= PVALSS (via m0) *)
    SUBGOAL_THEN
     `erel D (E:A->A->bool) leq m0y (bvalf_HS D E B leq w1 X ((x |-> ss) v) p)`
    ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;
                           `leq:A`;`m0y:A`;`m0:A`;
        `bvalf_HS D (E:A->A->bool) B leq w1 X ((x |-> ss) v) p`]
            EPORDER_TRANS) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* mc = meet(ey, PVALSS) *)
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ey:A`;
      `bvalf_HS D (E:A->A->bool) B leq w1 X ((x |-> ss) v) p`] EBALG_MEET) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_THEN `mc:A`
        (LABEL_TAC "mcmeet")) THEN
    SUBGOAL_THEN `(mc:A) IN D /\ (E:A->A->bool) mc B` STRIP_ASSUME_TAC THENL
     [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EMEET_IN); ALL_TAC] THEN
    (* mc <= PVAL(yv) via BVAL_SUBST_CONG_HS (x-slot: ss -> yv) *)
    SUBGOAL_THEN
     `erel D (E:A->A->bool) leq mc (bvalf_HS D E B leq w1 X ((x |-> yv) v) p)`
    ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                           `w1:A`;`X:A`;`v:num->A`;
        `x:num`;`ss:A`;`yv:A`;`ey:A`;`mc:A`] BVAL_SUBST_CONG_HS) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* m0y <= mc via EMEET_GREATEST (m0y<=ey, m0y<=PVALSS) *)
    SUBGOAL_THEN `erel D (E:A->A->bool) leq m0y mc` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ey:A`;
        `bvalf_HS D (E:A->A->bool) B leq w1 X ((x |-> ss) v) p`;`mc:A`;`m0y:A`]
            EMEET_GREATEST) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* m0y <= PVAL(yv) (via mc) *)
    SUBGOAL_THEN
     `erel D (E:A->A->bool) leq m0y (bvalf_HS D E B leq w1 X ((x |-> yv) v) p)`
    ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;
                           `leq:A`;`m0y:A`;`mc:A`;
        `bvalf_HS D (E:A->A->bool) B leq w1 X ((x |-> yv) v) p`]
            EPORDER_TRANS) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* dom-member hypothesis at yv, qy, m0y: m0y <= K *)
    SUBGOAL_THEN `erel D (E:A->A->bool) leq m0y K` ASSUME_TAC THENL
     [FIRST_ASSUM(MATCH_MP_TAC o SPECL [`yv:A`;`qy:A`;`m0y:A`]) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* cc <= ww1 via EBIMP_LE_IMP *)
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                         `cc:A`;`m0:A`;`K:A`;
      `ww1:A`;`m0y:A`] EBIMP_LE_IMP) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* ===== final: m0 <= [[ss in aa]] <= ww1, then m0 <= K ===== *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m0 ww1` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m0:A`;
      `bvalf_HS D (E:A->A->bool) B leq w1 X ((x |-> ss) v) (x %% a)`;`ww1:A`]
          EPORDER_TRANS) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* mm2 = meet(m0,m0) *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m0:A`;`m0:A`]
         EBALG_MEET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_THEN `mm2:A`
      (LABEL_TAC "mm2meet")) THEN
  SUBGOAL_THEN `(mm2:A) IN D /\ (E:A->A->bool) mm2 B` STRIP_ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EMEET_IN); ALL_TAC] THEN
  (* mm2 <= K via EBIMP_MEET_LE *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mm2 K` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                         `m0:A`;`m0:A`;`K:A`;
      `ww1:A`;`mm2:A`] EBIMP_MEET_LE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* m0 <= mm2 *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m0 mm2` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m0:A`;
                         `m0:A`;`mm2:A`;`m0:A`]
      EMEET_GREATEST) THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m0:A`]
                 EPORDER_REFL) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* m0 <= mm2 <= K *)
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                       `m0:A`;`mm2:A`;`K:A`]
    EPORDER_TRANS) THEN
  ASM_REWRITE_TAC[]);;

let BVAL_HS_REPLIMG_EXISTS = prove
 (`!p iy D (E:A->A->bool) B leq w1 X vbase dd.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
          w1 IN D /\ X IN D /\
      valuation D vbase /\ (!i. hsname D E B w1 X (vbase i)) /\
      dd IN D /\ (!s. s IN D /\ E s dd ==> hsname D E B w1 X s)
      ==> ?S. S IN D /\ esubset D E S B /\
              (!z. z IN D
                   ==> (E z S <=>
                        ?s. s IN D /\ E s dd /\
                            bval_HS D E B leq w1 X ((iy |-> s) vbase) p z))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (s:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `!i:num. bname D (E:A->A->bool) B (((vbase):num->A) i)`
      ASSUME_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC HSNAME_BNAME THEN
    MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[valuation]; ALL_TAC]) THEN
  SUBGOAL_THEN `!x. (vbase:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[ecba]); ALL_TAC] THEN
  SUBGOAL_THEN
    `?izz. ~(izz IN ({2, 3, 8, 9, 30, 31, 32 + iy} UNION IMAGE
                     (\k. 32 + k) (FV p)))`
    (X_CHOOSE_TAC `izz:num`) THENL
   [MATCH_MP_TAC num_FINITE_AVOID THEN
    SIMP_TAC[FINITE_UNION; FINITE_INSERT; FINITE_EMPTY;
             FINITE_IMAGE; FV_FINITE];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(izz = 2) /\ ~(2 = izz) /\ ~(izz = 3) /\ ~(3 = izz) /\
    ~(izz = 8) /\ ~(8 = izz) /\ ~(izz = 9) /\ ~(9 = izz) /\
    ~(izz = 30) /\ ~(izz = 31) /\ ~(izz = 32 + iy) /\ ~(32 + iy = izz) /\
    (!i. i IN FV p ==> ~(izz = 32 + i) /\ ~(32 + i = izz))`
   STRIP_ASSUME_TAC THENL
   [UNDISCH_TAC
     `~(izz IN ({2, 3, 8, 9, 30, 31, 32 + iy} UNION IMAGE
                (\k. 32 + k) (FV p)))` THEN
    REWRITE_TAC[IN_UNION; IN_INSERT; NOT_IN_EMPTY; IN_IMAGE] THEN MESON_TAC[];
    ALL_TAC] THEN
  X_CHOOSE_TAC `fp:form` (ISPECL [`p:form`; `izz:num`; `3`]
                          BVAL_HS_DEFINABLE) THEN
  ABBREV_TAC `w0 = (9 |-> (X:A)) ((8 |-> (w1:A))
      ((2 |-> B) ((3 |-> leq) (\k. (vbase:num->A) (k - 32)))))` THEN
  SUBGOAL_THEN
   `valuation D (w0:num->A) /\ w0 2 = B /\ w0 3 = leq /\
       w0 8 = w1 /\ w0 9 = X /\
    (!i. w0 (32 + i) = (vbase:num->A) i)`
   STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "w0" THEN REPEAT CONJ_TAC THENL
     [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]) THEN
      REWRITE_TAC[valuation] THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[VALMOD; ARITH_EQ]; REWRITE_TAC[VALMOD; ARITH_EQ];
      REWRITE_TAC[VALMOD; ARITH_EQ]; REWRITE_TAC[VALMOD; ARITH_EQ];
      GEN_TAC THEN
      SIMP_TAC[VALMOD_OTHER; ARITH_RULE `~(32 + i = 2) /\ ~(32 + i = 3) /\
                                         ~(32 + i = 8) /\ ~(32 + i = 9)`] THEN
      AP_TERM_TAC THEN ARITH_TAC];
    ALL_TAC] THEN
  (* BRIDGE *)
  SUBGOAL_THEN
   `!s w. s IN D /\ w IN D
      ==> (holds D E ((izz |-> w) (((32 + iy) |-> s) (w0:num->A))) fp <=>
           bval_HS D E B leq w1 X ((iy |-> s) vbase) p w)`
   (LABEL_TAC "bridge") THENL
   [MAP_EVERY X_GEN_TAC [`s:A`; `w:A`] THEN STRIP_TAC THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (s:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (w:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  
    SUBGOAL_THEN `valuation D ((izz |-> w) (((32 + iy) |-> s) (w0:num->A)))`
      ASSUME_TAC THENL [ASM_SIMP_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    FIRST_X_ASSUM(fun th -> MP_TAC(SPECL
      [`D:A->bool`; `E:A->A->bool`;
       `(izz |-> w) (((32 + iy) |-> s) (w0:num->A))`] th) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN ARITH_TAC; ALL_TAC]) THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER;
      ARITH_RULE `~(2 = 32 + iy) /\ ~(3 = 32 + iy) /\ ~(8 = 32 + iy) /\
          ~(9 = 32 + iy)`] THEN
    MATCH_MP_TAC BVAL_HS_FV THEN X_GEN_TAC `i:num` THEN DISCH_TAC THEN
    ASM_CASES_TAC `i:num = iy` THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER;
      ARITH_RULE `~(i = iy) ==> ~(32 + i = 32 + iy)`]; ALL_TAC] THEN
  (* apply ZF_REPLACEMENT *)
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`] ZF_REPLACEMENT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`fp:form`; `32 + iy`; `izz:num`; `w0:num->A`; `dd:A`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `u:A` THEN STRIP_TAC THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (u:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  
    SUBGOAL_THEN `hsname D (E:A->A->bool) B w1 X u` ASSUME_TAC THENL
     [UNDISCH_TAC `!s. s IN D /\ E s dd
      ==> hsname D (E:A->A->bool) B w1 X s` THEN
      DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (u:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  SUBGOAL_THEN `valuation D ((iy |-> u) (vbase:num->A))` ASSUME_TAC THENL
     [ASM_SIMP_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    SUBGOAL_THEN `!i. hsname D (E:A->A->bool) B w1 X
        (((iy |-> u) (vbase:num->A)) i)`
      ASSUME_TAC THENL
     [X_GEN_TAC `i:num` THEN ASM_CASES_TAC `i:num = iy` THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER]; ALL_TAC] THEN
    MP_TAC(ISPECL [`p:form`; `D:A->bool`; `E:A->A->bool`; `B:A`;
                   `leq:A`;`w1:A`;`X:A`;
      `(iy |-> u) (vbase:num->A)`] BVAL_HS_TOTAL) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `w':A` THEN STRIP_TAC THEN
    MATCH_MP_TAC(ISPECL [`p:form`; `D:A->bool`; `E:A->A->bool`; `B:A`;
                         `leq:A`;`w1:A`;`X:A`;
      `(iy |-> u) (vbase:num->A)`; `w':A`; `w:A`] BVAL_HS_UNIQUE) THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "bridge" (MP_TAC o SPECL [`u:A`; `w':A`]) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[];
      DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `S:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN
   `!z. z IN D
      ==> (E z S <=> ?s. s IN D /\ E s dd /\
                         bval_HS D (E:A->A->bool) B leq w1 X
                             ((iy |-> (s:A)) vbase) p z)`
   ASSUME_TAC THENL
   [X_GEN_TAC `z:A` THEN DISCH_TAC THEN
    FIRST_X_ASSUM(fun th -> MP_TAC(SPEC `z:A` th)) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MATCH_MP_TAC EXISTS_AND_CONG THEN X_GEN_TAC `s:A` THEN STRIP_TAC THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (s:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  
    USE_THEN "bridge" (MP_TAC o SPECL [`s:A`; `z:A`]) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[];
      DISCH_THEN(fun th -> REWRITE_TAC[th])];
    ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) S B` ASSUME_TAC THENL
   [REWRITE_TAC[esubset] THEN X_GEN_TAC `z:A` THEN STRIP_TAC THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (z:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  
    FIRST_X_ASSUM(fun th -> MP_TAC(SPEC `z:A` th)) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `s:A` STRIP_ASSUME_TAC) THEN
    MATCH_MP_TAC(ISPECL [`p:form`; `D:A->bool`; `E:A->A->bool`; `B:A`;
                         `leq:A`;`w1:A`;`X:A`;
      `(iy |-> (s:A)) (vbase:num->A)`; `z:A`] BVAL_HS_IN_B) THEN
    ASM_REWRITE_TAC[] THEN MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  EXISTS_TAC `S:A` THEN ASM_REWRITE_TAC[]);;

let PERU_SUP_HS = prove
 (`!D (E:A->A->bool) B leq w1 X v0 p x y u dd.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
          w1 IN D /\ X IN D /\
      valuation D v0 /\ (!i. hsname D E B w1 X (v0 i)) /\
      ~(x = y) /\
      u IN D /\ hsname D E B w1 X u /\
      dd IN D /\ (!s. s IN D /\ E s dd ==> hsname D E B w1 X s) /\
      (!tt. tt IN D /\ hsname D E B w1 X tt
            ==> ?s. s IN D /\ E s dd /\
                    bvalf_HS D E B leq w1 X ((y |-> s) ((x |-> u) v0)) p =
                    bvalf_HS D E B leq w1 X ((y |-> tt) ((x |-> u) v0)) p)
      ==> ?SS g. SS IN D /\ esubset D E SS B /\ elub D E B leq SS g /\ g IN D /\
                 (!w. w IN D
                      ==> (E w SS <=>
                           ?s. s IN D /\ E s dd /\
                               bval_HS D E B leq w1 X ((y |-> s)
                                   ((x |-> u) v0)) p w)) /\
                 (!tt. tt IN D /\ hsname D E B w1 X tt
                       ==> erel D E leq
                             (bvalf_HS D E B leq w1 X
                              ((y |-> tt) ((x |-> u) v0)) p) g)`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
             (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
     (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
       (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
        (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "ach")))))))))))))) THEN
  (* valuation (x|->u)v0 + all-hsname slots *)
  SUBGOAL_THEN
   `valuation D ((x |-> u) (v0:num->A)) /\
    (!i. hsname D E B w1 X (((x |-> u) (v0:num->A)) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC HSNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  (* SS = S_dd via BVAL_HS_REPLIMG_EXISTS *)
  MP_TAC(ISPECL
    [`p:form`; `y:num`; `D:A->bool`; `E:A->A->bool`; `B:A`;
     `leq:A`;`w1:A`;`X:A`;
     `(x |-> u) (v0:num->A)`; `dd:A`] BVAL_HS_REPLIMG_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `SS:A`
    (CONJUNCTS_THEN2 (LABEL_TAC "ssin")
     (CONJUNCTS_THEN2 (LABEL_TAC "sssub") (LABEL_TAC "ssmem")))) THEN
  (* g = elub SS *)
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`;
                 `SS:A`] ECBA_SUP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `g:A` (LABEL_TAC "glub")) THEN
  SUBGOAL_THEN `(g:A) IN D` (LABEL_TAC "gin") THENL
   [ASM_MESON_TAC[ELUB_IN]; ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`SS:A`; `g:A`] THEN
  ASM_REWRITE_TAC[] THEN
  (* remaining goal: !tt hsname. [[p(u,tt)]] <= g *)
  X_GEN_TAC `tt:A` THEN STRIP_TAC THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (tt:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (u:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (s:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (tt:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  TRY(SUBGOAL_THEN `!i:num. bname D (E:A->A->bool) B (((v0):num->A) i)`
      ASSUME_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC HSNAME_BNAME THEN
    MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[valuation]; ALL_TAC]) THEN
  USE_THEN "ach" (MP_TAC o SPEC `tt:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `s:A`
    (CONJUNCTS_THEN2 (LABEL_TAC "sin")
     (CONJUNCTS_THEN2 (LABEL_TAC "sdd") (LABEL_TAC "aeq")))) THEN
  SUBGOAL_THEN `hsname D (E:A->A->bool) B w1 X s` ASSUME_TAC THENL
   [FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (s:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  SUBGOAL_THEN
   `valuation D ((y |-> s) ((x |-> u) (v0:num->A))) /\
    (!i. hsname D E B w1 X (((y |-> s) ((x |-> u) (v0:num->A))) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC HSNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  (* bvalf_HS((y|->s)(x|->u)v0) p IN D + a bval_HS-witness of itself *)
  MP_TAC(ISPECL [`p:form`; `D:A->bool`; `E:A->A->bool`; `B:A`;
                 `leq:A`;`w1:A`;`X:A`;
    `(y |-> s) ((x |-> u) (v0:num->A))`] BVALF_HS_SPEC) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  (* E [[p(u,s)]] SS via the SS characterization, witness s *)
  SUBGOAL_THEN
   `(E:A->A->bool) (bvalf_HS D E B leq w1 X ((y |-> s) ((x |-> u) v0)) p) SS`
  ASSUME_TAC THENL
   [USE_THEN "ssmem"
      (MP_TAC o SPEC `bvalf_HS D (E:A->A->bool) B leq w1 X
       ((y |-> s) ((x |-> u) v0)) p`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EXISTS_TAC `s:A` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* goal: erel leq [[p(u,tt)]] g ; rewrite [[p(u,tt)]] = [[p(u,s)]] (GSYM *)
  (* aeq)                                                                  *)
  USE_THEN "aeq" (SUBST1_TAC o SYM) THEN
  (* ELUB_UB: [[p(u,s)]] <= g *)
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `SS:A`; `g:A`;
    `bvalf_HS D (E:A->A->bool) B leq w1 X ((y |-> s) ((x |-> u) v0))
        p`] ELUB_UB) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]);;

let prem_tm_HS = `bvalf_HS (D:A->bool) (E:A->A->bool) (B:A) (leq:A) (w1:A)
    (X:A) (v:num->A)
                 (!!- x a (?? z (!! y (p --> Eq y z))))`;;

let r_tm_HS = `bvalf_HS (D:A->bool) (E:A->A->bool) (B:A) (leq:A) (w1:A) (X:A)
    (vm:num->A) (??- x a p)`;;

let EBV_REPL_CORE_HS = prove
 (`!D (E:A->A->bool) B leq w1 X v x y z a p tt dm ddstar onebee cn K mm.
    model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
        w1 IN D /\ X IN D /\
    valuation D v /\ (!i. hsname D E B w1 X (v i)) /\
    ~(x = a) /\ ~(x = y) /\ ~(y = z) /\ ~(a = y) /\ ~(z IN FV p) /\
    tt IN D /\ hsname D E B w1 X tt /\
    dm IN D /\ (!u. u IN D ==> (E u dm <=> eindom D E (v a) u)) /\
    ddstar IN D /\ (!s. s IN D /\ E s ddstar ==> hsname D E B w1 X s) /\
    (!u. u IN D /\ E u dm
         ==> !t2. t2 IN D /\ hsname D E B w1 X t2
                  ==> ?s. s IN D /\ E s ddstar /\
                          bvalf_HS D E B leq w1 X ((y |-> s) ((x |-> u) v)) p =
                          bvalf_HS D E B leq w1 X ((y |-> t2)
                              ((x |-> u) v)) p) /\
    onebee IN D /\ E onebee B /\ etop D E B leq onebee /\
    cn IN D /\ eisfun D E cn /\
    (!s. s IN D /\ E s ddstar ==> eapply D E cn s onebee) /\
    K IN D /\ E K B /\ ebv_in D E B leq tt cn K /\
    emeet D E B leq
      (bvalf_HS D E B leq w1 X v (!!- x a (?? z (!! y (p --> Eq y z)))))
      (bvalf_HS D E B leq w1 X ((y |-> tt) v) (??- x a p)) mm
    ==> erel D E leq mm K`,
  (* ===== setup ===== *)
  REPEAT GEN_TAC THEN
  ABBREV_TAC `vm = (y |-> tt) (v:num->A)` THEN
  ABBREV_TAC `aa = (v:num->A) a` THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
             (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 (LABEL_TAC "dmch")
      (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 (LABEL_TAC "ddbn")
      (CONJUNCTS_THEN2 (LABEL_TAC "ach")
       (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 (LABEL_TAC "cnap")
      (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 (LABEL_TAC "ebvin")
       (LABEL_TAC "meet")))))))))))))))))))))))))))))) THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
