            ~(8 = 32 + i) /\ ~(32 + i = 8) /\ ~(9 = 32 + i) /\ ~(32 + i = 9)`;
            ASSUME `~(x:num = n)`; ASSUME `~(n:num = x)`] THEN
            ASM_REWRITE_TAC[]];
    DISCH_THEN(fun th -> USE_THEN "hq" (MP_TAC o EQ_MP th))] THEN
  REWRITE_TAC[VALMOD; ARITH_EQ; EQ_ADD_LCANCEL; ARITH_RULE `~(0 = 32 + x) /\
              ~(32 + x = 0) /\ ~(1 = 32 + x) /\ ~(32 + x = 1) /\
      ~(2 = 32 + x) /\ ~(32 + x = 2) /\ ~(3 = 32 + x) /\ ~(32 + x = 3) /\
      ~(5 = 32 + x) /\ ~(32 + x = 5) /\ ~(6 = 32 + x) /\ ~(32 + x = 6) /\
      ~(7 = 32 + x) /\ ~(32 + x = 7) /\ ~(8 = 32 + x) /\ ~(32 + x = 8) /\
      ~(9 = 32 + x) /\ ~(32 + x = 9) /\ ~(0 = 32 + n) /\ ~(32 + n = 0) /\
      ~(1 = 32 + n) /\ ~(32 + n = 1) /\ ~(2 = 32 + n) /\ ~(32 + n = 2) /\
      ~(3 = 32 + n) /\ ~(32 + n = 3) /\ ~(5 = 32 + n) /\ ~(32 + n = 5) /\
      ~(6 = 32 + n) /\ ~(32 + n = 6) /\ ~(7 = 32 + n) /\ ~(32 + n = 7) /\
      ~(8 = 32 + n) /\ ~(32 + n = 8) /\ ~(9 = 32 + n) /\ ~(32 + n = 9) /\
      ~(0 = 32 + i) /\ ~(32 + i = 0) /\ ~(1 = 32 + i) /\ ~(32 + i = 1) /\
      ~(2 = 32 + i) /\ ~(32 + i = 2) /\ ~(3 = 32 + i) /\ ~(32 + i = 3) /\
      ~(5 = 32 + i) /\ ~(32 + i = 5) /\ ~(6 = 32 + i) /\ ~(32 + i = 6) /\
      ~(7 = 32 + i) /\ ~(32 + i = 7) /\ ~(8 = 32 + i) /\ ~(32 + i = 8) /\
      ~(9 = 32 + i) /\ ~(32 + i = 9)`; ASSUME `~(x:num = n)`;
      ASSUME `~(n:num = x)`] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "op1")
             (CONJUNCTS_THEN2 (LABEL_TAC "hsq") (LABEL_TAC "bvq"))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`u:A`;
                `bvalf_HS D (E:A->A->bool) B leq w1 X
      ((n |-> (a:A)) ((x |-> (u:A)) (v:num->A))) p`;`u1:A`;`val1:A`;`z:A`]
      EOPAIR_INJ) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (SUBST_ALL_TAC o SYM) (SUBST_ALL_TAC o SYM)) THEN
  EXISTS_TAC `q:A` THEN CONJ_TAC THENL [USE_THEN "qD" ACCEPT_TAC; ALL_TAC] THEN
  CONJ_TAC THENL
   [USE_THEN "Ich" (MP_TAC o SPEC `q:A`) THEN
    ANTS_TAC THENL [USE_THEN "qD" ACCEPT_TAC; DISCH_THEN SUBST1_TAC] THEN
    CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  CONV_TAC SYM_CONV THEN
  MATCH_MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                       `leq:A`;`w1:A`;`X:A`;
                       `(n |-> (q:A)) ((x |-> (u:A)) (v:num->A))`;
                       `bvalf_HS D (E:A->A->bool) B leq w1 X
                           ((n |-> (a:A)) ((x |-> (u:A)) (v:num->A))) p`]
                BVALF_HS_EQ) THEN
  REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THENL
   [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC) THEN
    FIRST_ASSUM ACCEPT_TAC;
    REPEAT(MATCH_MP_TAC HSNAMEVAL_VALMOD THEN CONJ_TAC) THEN
        FIRST_ASSUM ACCEPT_TAC]);;

(* ===================================================================== *)
(* H4.11b : the HS full name.  HSCUT_INV: Z = W_lam /\ HS (a bname stage   *)
(* cut down to its HS members) is mapped onto itself by every autN         *)
(* (AUTN_STAGE_PRESERVE/SURJ + AUTN_HS/AUTN_HS_ONTO + AUTN_INJ).            *)
(* FULLNAME_SYM: the full name {<s,top> : s IN Z} over such an invariant Z  *)
(* is autN-fixed (autB fixes top).  HS_FULLNAME: it is an HS name (empty    *)
(* support; one stage above an HS stage bounding Z).                        *)
(* ===================================================================== *)
let HSCUT_INV = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X sg muci
  muP autB lam W Z.
     hsbundle D E w1 om tw ii ci P leqp B inclB onebee X /\
     sg IN D /\ eperm D E w1 sg /\ pbundle D E ci P leqp B inclB sg
         muci muP autB /\
     lam IN D /\ W IN D /\ eordinal D E lam /\ ebnstage D E B lam W /\
     Z IN D /\ (!s. s IN D ==> (E s Z <=> E s W /\ hsname D E B w1 X s))
     ==> (!s s'. s IN D /\ E s Z /\ eautn D E B autB s s' ==> E s' Z) /\
         (!s'. s' IN D /\ E s' Z ==> ?s. s IN D /\ E s Z /\
          eautn D E B autB s s')`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "hsb")
             (CONJUNCTS_THEN2 (LABEL_TAC "sgD")
              (CONJUNCTS_THEN2 (LABEL_TAC "sgperm")
               (CONJUNCTS_THEN2 (LABEL_TAC "pb")
                (CONJUNCTS_THEN2 (LABEL_TAC "lamD")
                 (CONJUNCTS_THEN2 (LABEL_TAC "WD")
                  (CONJUNCTS_THEN2 (LABEL_TAC "lamord")
                   (CONJUNCTS_THEN2 (LABEL_TAC "stW")
                    (CONJUNCTS_THEN2 (LABEL_TAC "ZD")
                     (LABEL_TAC "Zch")))))))))) THEN
  USE_THEN "hsb" (MP_TAC o MATCH_MP HSB_CBA) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "cba")
             (CONJUNCTS_THEN2 (LABEL_TAC "inclD") (LABEL_TAC "leqpD"))) THEN
  USE_THEN "hsb" (MP_TAC o REWRITE_RULE[hsbundle]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
             (CONJUNCTS_THEN2 (LABEL_TAC "vl")
              (CONJUNCTS_THEN2 (LABEL_TAC "eom")
               (CONJUNCTS_THEN2 (LABEL_TAC "w1D")
                (CONJUNCTS_THEN2 (LABEL_TAC "w1card")
                 (CONJUNCTS_THEN2 (LABEL_TAC "omw1e")
                  (CONJUNCTS_THEN2 (LABEL_TAC "w1min")
                   (CONJUNCTS_THEN2 (LABEL_TAC "cr1")
                    (CONJUNCTS_THEN2 (LABEL_TAC "cr2")
                     (CONJUNCTS_THEN2 (LABEL_TAC "ftw")
                      (CONJUNCTS_THEN2 (LABEL_TAC "coh")
                       (CONJUNCTS_THEN2 (LABEL_TAC "leq")
                        (CONJUNCTS_THEN2 (LABEL_TAC "ros")
                         (CONJUNCTS_THEN2 (LABEL_TAC "inc")
                          (CONJUNCTS_THEN2 (LABEL_TAC "porder")
      (CONJUNCTS_THEN2 (LABEL_TAC "top")
       (CONJUNCTS_THEN2 (LABEL_TAC "oneD")
        (CONJUNCTS_THEN2 (LABEL_TAC "BD")
         (CONJUNCTS_THEN2 (LABEL_TAC "oneB")
          (CONJUNCTS_THEN2 (LABEL_TAC "XD")
           (CONJUNCTS_THEN2 (LABEL_TAC "ciX")
            (LABEL_TAC "PX")))))))))))))))))))))) THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B inclB /\ eporder D E B inclB`
   (CONJUNCTS_THEN2 (LABEL_TAC "balg") (LABEL_TAC "pord")) THENL
   [USE_THEN "cba" (fun th -> let b = MATCH_MP ECBA_IMP_BALG th in
      ACCEPT_TAC(CONJ b (MATCH_MP EBALG_IMP_PORDER b)));
    ALL_TAC] THEN
  USE_THEN "pb" (fun th -> let cs = CONJUNCTS(REWRITE_RULE[pbundle] th) in
    LABEL_TAC "autBD" (el 2 cs) THEN LABEL_TAC "bijB" (el 5 cs) THEN
    LABEL_TAC "presB" (el 10 cs)) THEN
  USE_THEN "bijB" (fun th -> let cs = CONJUNCTS(REWRITE_RULE[ebij] th) in
    LABEL_TAC "bijtot" (el 2 cs) THEN LABEL_TAC "bijsv" (el 3 cs)) THEN
  CONJ_TAC THENL
   [MAP_EVERY X_GEN_TAC [`s:A`;`s':A`] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "sD")
               (CONJUNCTS_THEN2 (LABEL_TAC "sZ") (LABEL_TAC "ass'"))) THEN
    USE_THEN "Zch" (MP_TAC o SPEC `s:A`) THEN
    ANTS_TAC THENL [USE_THEN "sD" ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "sZ" (MP_TAC o EQ_MP th)) THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "sW") (LABEL_TAC "hss")) THEN
    SUBGOAL_THEN `(s':A) IN D` (LABEL_TAC "s'D") THENL
     [USE_THEN "ass'" (ACCEPT_TAC o CONJUNCT2 o MATCH_MP
                       AUTN_IMP); ALL_TAC] THEN
    USE_THEN "Zch" (MP_TAC o SPEC `s':A`) THEN
    ANTS_TAC THENL [USE_THEN "s'D" ACCEPT_TAC; DISCH_THEN SUBST1_TAC] THEN
    CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`lam:A`;`W:A`;
                    `s:A`;`s':A`] AUTN_STAGE_PRESERVE) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN ACCEPT_TAC];
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;`ii:A`;
                    `ci:A`;`P:A`;`leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;
          `sg:A`;`muci:A`;`muP:A`;`autB:A`;`s:A`;`s':A`] AUTN_HS) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN ACCEPT_TAC]];
    X_GEN_TAC `s':A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "s'D") (LABEL_TAC "s'Z")) THEN
    USE_THEN "Zch" (MP_TAC o SPEC `s':A`) THEN
    ANTS_TAC THENL [USE_THEN "s'D" ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "s'Z" (MP_TAC o EQ_MP th)) THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "s'W") (LABEL_TAC "hss'")) THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`lam:A`;`W:A`;
                  `s':A`] AUTN_STAGE_SURJ) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `s:A` (CONJUNCTS_THEN2 (LABEL_TAC "sD")
        (CONJUNCTS_THEN2 (LABEL_TAC "sW") (LABEL_TAC "ass'")))) THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;`ii:A`;`ci:A`;
                  `P:A`;`leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`sg:A`;
        `muci:A`;`muP:A`;`autB:A`;`s':A`] AUTN_HS_ONTO) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `nm:A` (CONJUNCTS_THEN2 (LABEL_TAC "nmD")
        (CONJUNCTS_THEN2 (LABEL_TAC "hsnm") (LABEL_TAC "anm")))) THEN
    SUBGOAL_THEN `s:A = nm` SUBST_ALL_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`s:A`;`nm:A`;
                    `s':A`] AUTN_INJ) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    EXISTS_TAC `nm:A` THEN REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    USE_THEN "Zch" (MP_TAC o SPEC `nm:A`) THEN
    ANTS_TAC THENL [USE_THEN "nmD" ACCEPT_TAC; DISCH_THEN SUBST1_TAC] THEN
    CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC]);;

let FULLNAME_SYM = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X sg
  muci muP autB Z cn.
     hsbundle D E w1 om tw ii ci P leqp B inclB onebee X /\
     sg IN D /\ eperm D E w1 sg /\ pbundle D E ci P leqp B inclB sg
         muci muP autB /\
     Z IN D /\ (!s. s IN D /\ E s Z ==> hsname D E B w1 X s) /\
     (!s s'. s IN D /\ E s Z /\ eautn D E B autB s s' ==> E s' Z) /\
         (!s'. s' IN D /\ E s' Z ==> ?s. s IN D /\ E s Z /\
          eautn D E B autB s s') /\
     cn IN D /\ bname D E B cn /\ (!z. z IN D
         ==> (E z cn <=> ?s. s IN D /\ E s Z /\
              eopair D (E:A->A->bool) s onebee z))
     ==> eautn D E B autB cn cn`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "hsb")
             (CONJUNCTS_THEN2 (LABEL_TAC "sgD")
              (CONJUNCTS_THEN2 (LABEL_TAC "sgperm")
               (CONJUNCTS_THEN2 (LABEL_TAC "pb")
                (CONJUNCTS_THEN2 (LABEL_TAC "ZD")
                 (CONJUNCTS_THEN2 (LABEL_TAC "Zhs")
                  (CONJUNCTS_THEN2 (LABEL_TAC "invf")
                   (CONJUNCTS_THEN2 (LABEL_TAC "invb")
                    (CONJUNCTS_THEN2 (LABEL_TAC "cnD")
                     (CONJUNCTS_THEN2 (LABEL_TAC "bncn")
                      (LABEL_TAC "cnch"))))))))))) THEN
  USE_THEN "hsb" (MP_TAC o MATCH_MP HSB_CBA) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "cba")
             (CONJUNCTS_THEN2 (LABEL_TAC "inclD") (LABEL_TAC "leqpD"))) THEN
  USE_THEN "hsb" (MP_TAC o REWRITE_RULE[hsbundle]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
             (CONJUNCTS_THEN2 (LABEL_TAC "vl")
              (CONJUNCTS_THEN2 (LABEL_TAC "eom")
               (CONJUNCTS_THEN2 (LABEL_TAC "w1D")
                (CONJUNCTS_THEN2 (LABEL_TAC "w1card")
                 (CONJUNCTS_THEN2 (LABEL_TAC "omw1e")
                  (CONJUNCTS_THEN2 (LABEL_TAC "w1min")
                   (CONJUNCTS_THEN2 (LABEL_TAC "cr1")
                    (CONJUNCTS_THEN2 (LABEL_TAC "cr2")
                     (CONJUNCTS_THEN2 (LABEL_TAC "ftw")
                      (CONJUNCTS_THEN2 (LABEL_TAC "coh")
                       (CONJUNCTS_THEN2 (LABEL_TAC "leq")
                        (CONJUNCTS_THEN2 (LABEL_TAC "ros")
                         (CONJUNCTS_THEN2 (LABEL_TAC "inc")
                          (CONJUNCTS_THEN2 (LABEL_TAC "porder")
      (CONJUNCTS_THEN2 (LABEL_TAC "top")
       (CONJUNCTS_THEN2 (LABEL_TAC "oneD")
        (CONJUNCTS_THEN2 (LABEL_TAC "BD")
         (CONJUNCTS_THEN2 (LABEL_TAC "oneB")
          (CONJUNCTS_THEN2 (LABEL_TAC "XD")
           (CONJUNCTS_THEN2 (LABEL_TAC "ciX")
            (LABEL_TAC "PX")))))))))))))))))))))) THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B inclB /\ eporder D E B inclB`
   (CONJUNCTS_THEN2 (LABEL_TAC "balg") (LABEL_TAC "pord")) THENL
   [USE_THEN "cba" (fun th -> let b = MATCH_MP ECBA_IMP_BALG th in
      ACCEPT_TAC(CONJ b (MATCH_MP EBALG_IMP_PORDER b)));
    ALL_TAC] THEN
  USE_THEN "pb" (fun th -> let cs = CONJUNCTS(REWRITE_RULE[pbundle] th) in
    LABEL_TAC "autBD" (el 2 cs) THEN LABEL_TAC "bijB" (el 5 cs) THEN
    LABEL_TAC "presB" (el 10 cs)) THEN
  USE_THEN "bijB" (fun th -> let cs = CONJUNCTS(REWRITE_RULE[ebij] th) in
    LABEL_TAC "bijtot" (el 2 cs) THEN LABEL_TAC "bijsv" (el 3 cs)) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`autB:A`;`onebee:A`]
         EAUTB_FIXES_TOP) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                  DISCH_THEN(LABEL_TAC "fixtop")] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`cn:A`]
         AUTN_TOTAL) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `cn':A` (CONJUNCTS_THEN2 (LABEL_TAC "cn'D")
        (LABEL_TAC "acn"))) THEN
  SUBGOAL_THEN `cn':A = cn` (fun th -> USE_THEN "acn"
      (ACCEPT_TAC o REWRITE_RULE[th])) THEN
  USE_THEN "modl" (MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
  REPEAT CONJ_TAC THENL [USE_THEN "cn'D" ACCEPT_TAC;
                         USE_THEN "cnD" ACCEPT_TAC; ALL_TAC] THEN
  X_GEN_TAC `z:A` THEN DISCH_THEN(LABEL_TAC "zD") THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`cn:A`;`cn':A`;
                `z:A`] AUTN_MEM) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                  DISCH_THEN SUBST1_TAC] THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `m:A` (X_CHOOSE_THEN `t:A`
       (X_CHOOSE_THEN `c:A` (X_CHOOSE_THEN `t':A`
       (X_CHOOSE_THEN `c':A` (CONJUNCTS_THEN2 (LABEL_TAC "mD")
       (CONJUNCTS_THEN2 (LABEL_TAC "tD")
        (CONJUNCTS_THEN2 (LABEL_TAC "cD")
         (CONJUNCTS_THEN2 (LABEL_TAC "t'D")
          (CONJUNCTS_THEN2 (LABEL_TAC "c'D")
           (CONJUNCTS_THEN2 (LABEL_TAC "mcn")
            (CONJUNCTS_THEN2 (LABEL_TAC "opm")
             (CONJUNCTS_THEN2 (LABEL_TAC "att'")
              (CONJUNCTS_THEN2 (LABEL_TAC "acc'")
               (LABEL_TAC "op'"))))))))))))))) THEN
    USE_THEN "cnch" (MP_TAC o SPEC `m:A`) THEN
    ANTS_TAC THENL [USE_THEN "mD" ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "mcn" (MP_TAC o EQ_MP th)) THEN
    DISCH_THEN(X_CHOOSE_THEN `s:A` (CONJUNCTS_THEN2 (LABEL_TAC "sD")
      (CONJUNCTS_THEN2 (LABEL_TAC "sZ") (LABEL_TAC "ops")))) THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`t:A`;`c:A`;`s:A`;`onebee:A`;`m:A`]
           EOPAIR_INJ) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(CONJUNCTS_THEN2 SUBST_ALL_TAC SUBST_ALL_TAC) THEN
    SUBGOAL_THEN `c':A = onebee` SUBST_ALL_TAC THENL
     [USE_THEN "bijsv" (MP_TAC o SPECL [`onebee:A`;`c':A`;`onebee:A`]) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    USE_THEN "cnch" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [USE_THEN "zD" ACCEPT_TAC; DISCH_THEN SUBST1_TAC] THEN
    EXISTS_TAC `t':A` THEN REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    USE_THEN "invf" MATCH_MP_TAC THEN EXISTS_TAC `s:A` THEN
    REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    DISCH_THEN(LABEL_TAC "zcn") THEN
    USE_THEN "cnch" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [USE_THEN "zD" ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "zcn" (MP_TAC o EQ_MP th)) THEN
    DISCH_THEN(X_CHOOSE_THEN `s':A` (CONJUNCTS_THEN2 (LABEL_TAC "s'D")
      (CONJUNCTS_THEN2 (LABEL_TAC "s'Z") (LABEL_TAC "ops'")))) THEN
    USE_THEN "invb" (MP_TAC o SPEC `s':A`) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `s:A` (CONJUNCTS_THEN2 (LABEL_TAC "sD")
      (CONJUNCTS_THEN2 (LABEL_TAC "sZ") (LABEL_TAC "ass'")))) THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`s:A`;`onebee:A`]
           EOPAIR_EXISTS) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `m0:A` (LABEL_TAC "opm0")) THEN
    SUBGOAL_THEN `(m0:A) IN D` (LABEL_TAC "m0D") THENL
     [USE_THEN "opm0" (ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) m0 cn` (LABEL_TAC "m0cn") THENL
     [USE_THEN "cnch" (MP_TAC o SPEC `m0:A`) THEN
      ANTS_TAC THENL [USE_THEN "m0D" ACCEPT_TAC; DISCH_THEN SUBST1_TAC] THEN
      EXISTS_TAC `s:A` THEN REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
      ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`m0:A`;`s:A`;`onebee:A`;`s':A`;`onebee:A`] THEN
    REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC]);;

let HS_FULLNAME = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X Z cn.
     hsbundle D E w1 om tw ii ci P leqp B inclB onebee X /\
     Z IN D /\ (!s. s IN D /\ E s Z ==> hsname D E B w1 X s) /\
     (!sg muci muP autB. sg IN D /\ eperm D E w1 sg /\
                         pbundle D E ci P leqp B inclB sg muci muP autB
                         ==> (!s s'. s IN D /\ E s Z /\ eautn D E B autB s s'
                              ==> E s' Z) /\ (!s'. s' IN D /\ E s' Z
                                              ==> ?s. s IN D /\ E s Z /\
                             eautn D E B autB s s')) /\
     cn IN D /\ eisfun D E cn /\ (!z. z IN D
         ==> (E z cn <=> ?s. s IN D /\ E s Z /\
              eopair D (E:A->A->bool) s onebee z))
     ==> hsname D E B w1 X cn`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "hsb")
             (CONJUNCTS_THEN2 (LABEL_TAC "ZD")
              (CONJUNCTS_THEN2 (LABEL_TAC "Zhs")
               (CONJUNCTS_THEN2 (LABEL_TAC "inv")
                (CONJUNCTS_THEN2 (LABEL_TAC "cnD")
                 (CONJUNCTS_THEN2 (LABEL_TAC "isfun")
                  (LABEL_TAC "cnch"))))))) THEN
  USE_THEN "hsb" (MP_TAC o MATCH_MP HSB_CBA) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "cba")
             (CONJUNCTS_THEN2 (LABEL_TAC "inclD") (LABEL_TAC "leqpD"))) THEN
  USE_THEN "hsb" (MP_TAC o REWRITE_RULE[hsbundle]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
             (CONJUNCTS_THEN2 (LABEL_TAC "vl")
              (CONJUNCTS_THEN2 (LABEL_TAC "eom")
               (CONJUNCTS_THEN2 (LABEL_TAC "w1D")
                (CONJUNCTS_THEN2 (LABEL_TAC "w1card")
                 (CONJUNCTS_THEN2 (LABEL_TAC "omw1e")
                  (CONJUNCTS_THEN2 (LABEL_TAC "w1min")
                   (CONJUNCTS_THEN2 (LABEL_TAC "cr1")
                    (CONJUNCTS_THEN2 (LABEL_TAC "cr2")
                     (CONJUNCTS_THEN2 (LABEL_TAC "ftw")
                      (CONJUNCTS_THEN2 (LABEL_TAC "coh")
                       (CONJUNCTS_THEN2 (LABEL_TAC "leq")
                        (CONJUNCTS_THEN2 (LABEL_TAC "ros")
                         (CONJUNCTS_THEN2 (LABEL_TAC "inc")
                          (CONJUNCTS_THEN2 (LABEL_TAC "porder")
      (CONJUNCTS_THEN2 (LABEL_TAC "top")
       (CONJUNCTS_THEN2 (LABEL_TAC "oneD")
        (CONJUNCTS_THEN2 (LABEL_TAC "BD")
