  SUBGOAL_THEN `!z. z IN D /\ (E:A->A->bool) z Z
      ==> bname D E B z` (LABEL_TAC "Zbn") THENL
   [X_GEN_TAC `z:A` THEN DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "zD")
