      (CONJUNCTS_THEN2 (LABEL_TAC "sgperm") (K ALL_TAC))) THEN
    MAP_EVERY X_GEN_TAC [`muci:A`;`muP:A`;`autB:A`] THEN
    DISCH_THEN(fun th ->
      SUBGOAL_THEN `pbundle D (E:A->A->bool) ci P leqp B inclB sg muci muP autB`
          (LABEL_TAC "pb")
      THENL [REWRITE_TAC[pbundle] THEN ACCEPT_TAC th; ALL_TAC]) THEN
    USE_THEN "inv" (MP_TAC o SPECL [`sg:A`;`muci:A`;`muP:A`;`autB:A`]) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "invf") (LABEL_TAC "invb")) THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;`ii:A`;`ci:A`;
                  `P:A`;`leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`sg:A`;
        `muci:A`;`muP:A`;`autB:A`;`Z:A`;`cn:A`] FULLNAME_SYM) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;`Z:A`]
         HSNAME_BOUND) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `c0:A` (X_CHOOSE_THEN `yc0:A`
      (CONJUNCTS_THEN2 (LABEL_TAC "c0D")
       (CONJUNCTS_THEN2 (LABEL_TAC "yc0D")
        (CONJUNCTS_THEN2 (LABEL_TAC "c0ord")
         (CONJUNCTS_THEN2 (LABEL_TAC "hsc0") (LABEL_TAC "Zyc0"))))))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`c0:A`] ESUC_EXISTS) THEN
  ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `a2:A` (LABEL_TAC "asuc")) THEN
  SUBGOAL_THEN `(a2:A) IN D` (LABEL_TAC "a2D") THENL
   [USE_THEN "asuc" (ACCEPT_TAC o MATCH_MP ESUC_IN); ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) a2` (LABEL_TAC "a2ord") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`c0:A`;`a2:A`] EORDINAL_ESUC) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) c0 a2` (LABEL_TAC "c0a2") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`c0:A`;`a2:A`] ESUC_MEMBER) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;`a2:A`]
         HSSTAGE_EXISTS) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
