(* ===================================================================== *)
(* H4.11c : REPL_STABILIZE_HS -- the uniform bounding set for HS           *)
(* replacement: ddstar = W_lam /\ HS, where W_lam is a bname stage holding  *)
(* the uniform attaining set of HSVAL_ATTAIN_U.  ddstar is autN-invariant   *)
(* (HSCUT_INV), so its full name is HS (HS_FULLNAME).                        *)
(* ===================================================================== *)
let REPL_STABILIZE_HS = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X v x y p dm.
     hsbundle D E w1 om tw ii ci P leqp B inclB onebee X /\
     valuation D v /\ (!i. hsname D E B w1 X (v i)) /\ ~(x = y) /\
     dm IN D /\ (!u. u IN D /\ E u dm ==> hsname D E B w1 X u)
     ==> ?ddstar. ddstar IN D /\ (!s. s IN D /\ E s ddstar
         ==> hsname D E B w1 X s) /\
                  (!sg muci muP autB. sg IN D /\ eperm D E w1 sg /\
                         pbundle D E ci P leqp B inclB sg muci muP autB
                         ==> (!s s'. s IN D /\ E s ddstar /\
                              eautn D E B autB s s' ==> E s' ddstar) /\
                             (!s'. s' IN D /\ E s' ddstar ==> ?s. s IN D /\
                              E s ddstar /\ eautn D E B autB s s')) /\
                  (!u. u IN D /\ E u dm
                       ==> !tt. tt IN D /\ hsname D E B w1 X tt
                                ==> ?s. s IN D /\ E s ddstar /\
                                        bvalf_HS D E B inclB w1 X
                                            ((y |-> s) ((x |-> u) v)) p =
                                        bvalf_HS D E B inclB w1 X
                                            ((y |-> tt) ((x |-> u) v)) p)`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "hsb")
             (CONJUNCTS_THEN2 (LABEL_TAC "vv")
              (CONJUNCTS_THEN2 (LABEL_TAC "hsv")
               (CONJUNCTS_THEN2 (LABEL_TAC "xy")
                (CONJUNCTS_THEN2 (LABEL_TAC "dmD") (LABEL_TAC "dmhs")))))) THEN
  USE_THEN "hsb" (MP_TAC o MATCH_MP HSB_CBA) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "cba")
             (CONJUNCTS_THEN2 (LABEL_TAC "inclD") (LABEL_TAC "leqpD"))) THEN
  USE_THEN "hsb" (MP_TAC o REWRITE_RULE[hsbundle]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
             (CONJUNCTS_THEN2 (LABEL_TAC "vl")
              (CONJUNCTS_THEN2 (LABEL_TAC "eom")
               (CONJUNCTS_THEN2 (LABEL_TAC "w1D")
                (CONJUNCTS_THEN2 (LABEL_TAC "w1card")
                 (CONJUNCTS_THEN2 (LABEL_TAC "omw1e")
                  (CONJUNCTS_THEN2 (LABEL_TAC "w1min")
                   (CONJUNCTS_THEN2 (LABEL_TAC "cr1")
                    (CONJUNCTS_THEN2 (LABEL_TAC "cr2")
                     (CONJUNCTS_THEN2 (LABEL_TAC "ftw")
                      (CONJUNCTS_THEN2 (LABEL_TAC "coh")
                       (CONJUNCTS_THEN2 (LABEL_TAC "leq")
                        (CONJUNCTS_THEN2 (LABEL_TAC "ros")
                         (CONJUNCTS_THEN2 (LABEL_TAC "inc")
                          (CONJUNCTS_THEN2 (LABEL_TAC "porder")
      (CONJUNCTS_THEN2 (LABEL_TAC "top")
       (CONJUNCTS_THEN2 (LABEL_TAC "oneD")
        (CONJUNCTS_THEN2 (LABEL_TAC "BD")
         (CONJUNCTS_THEN2 (LABEL_TAC "oneB")
          (CONJUNCTS_THEN2 (LABEL_TAC "XD")
           (CONJUNCTS_THEN2 (LABEL_TAC "ciX")
            (LABEL_TAC "PX")))))))))))))))))))))) THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B inclB /\ eporder D E B inclB`
   (CONJUNCTS_THEN2 (LABEL_TAC "balg") (LABEL_TAC "pord")) THENL
   [USE_THEN "cba" (fun th -> let b = MATCH_MP ECBA_IMP_BALG th in
      ACCEPT_TAC(CONJ b (MATCH_MP EBALG_IMP_PORDER b)));
    ALL_TAC] THEN
  MP_TAC(SPECL [`x:num`;`y:num`;`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                `inclB:A`;`w1:A`;`X:A`;
                `v:num->A`;`dm:A`] HSVAL_ATTAIN_U) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `Is:A` (CONJUNCTS_THEN2 (LABEL_TAC "ID")
    (CONJUNCTS_THEN2 (LABEL_TAC "Ihs") (LABEL_TAC "Iach")))) THEN
  SUBGOAL_THEN `!z. z IN D /\ (E:A->A->bool) z Is
      ==> bname D E B z` (LABEL_TAC "Ibn") THENL
   [X_GEN_TAC `z:A` THEN DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "zD")
       (LABEL_TAC "zI")) THEN
    MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    USE_THEN "Ihs" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; DISCH_TAC] THEN
    REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`Is:A`] BNAME_BOUND) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `lam:A` (X_CHOOSE_THEN `W:A`
      (CONJUNCTS_THEN2 (LABEL_TAC "lamD")
       (CONJUNCTS_THEN2 (LABEL_TAC "WD")
        (CONJUNCTS_THEN2 (LABEL_TAC "lamord")
         (CONJUNCTS_THEN2 (LABEL_TAC "stW") (LABEL_TAC "IW"))))))) THEN
  (* Z = HS members of W *)
  ABBREV_TAC `w0 = (9 |-> (X:A)) ((8 |-> (w1:A))
      ((2 |-> (B:A)) (v:num->A)))` THEN
  SUBGOAL_THEN `valuation D (w0:num->A) /\ w0 2 = B /\ w0 8 = w1 /\ w0 9 = X`
   (CONJUNCTS_THEN2 (LABEL_TAC "vw0") (CONJUNCTS_THEN2 (LABEL_TAC "w02")
     (CONJUNCTS_THEN2 (LABEL_TAC "w08") (LABEL_TAC "w09")))) THENL
   [EXPAND_TAC "w0" THEN REPEAT CONJ_TAC THENL
     [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC) THEN
      FIRST_ASSUM ACCEPT_TAC;
      REWRITE_TAC[VALMOD; ARITH_EQ]; REWRITE_TAC[VALMOD; ARITH_EQ];
          REWRITE_TAC[VALMOD; ARITH_EQ]];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`] ZF_SEPARATION) THEN
  ANTS_TAC THENL [USE_THEN "modl" ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL [`hsname_form 1`; `1`; `w0:num->A`; `W:A`]) THEN
  ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `Z:A` (CONJUNCTS_THEN2 (LABEL_TAC "ZD")
      (LABEL_TAC "Zch0"))) THEN
  SUBGOAL_THEN
   `!s:A. s IN D ==> ((E:A->A->bool) s Z <=> E s W /\ hsname D E B w1 X s)`
   (LABEL_TAC "Zch") THENL
   [X_GEN_TAC `s:A` THEN DISCH_THEN(LABEL_TAC "sD") THEN
    USE_THEN "Zch0" (MP_TAC o SPEC `s:A`) THEN
    ANTS_TAC THENL [USE_THEN "sD" ACCEPT_TAC; DISCH_THEN SUBST1_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`(1 |-> (s:A)) (w0:num->A)`;`1`]
           HOLDS_HSNAME_FORM) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN TRY ARITH_TAC THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
      DISCH_THEN SUBST1_TAC] THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE `~(2 = 1) /\
                 ~(8 = 1) /\ ~(9 = 1)`];
    ALL_TAC] THEN
  EXISTS_TAC `Z:A` THEN REPEAT CONJ_TAC THENL
   [USE_THEN "ZD" ACCEPT_TAC;
    X_GEN_TAC `s:A` THEN DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "sD")
        (LABEL_TAC "sZ")) THEN
    USE_THEN "Zch" (MP_TAC o SPEC `s:A`) THEN
    ANTS_TAC THENL [USE_THEN "sD" ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "sZ" (MP_TAC o EQ_MP th)) THEN
    DISCH_THEN(ACCEPT_TAC o CONJUNCT2);
    MAP_EVERY X_GEN_TAC [`sg:A`;`muci:A`;`muP:A`;`autB:A`] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "sgD")
               (CONJUNCTS_THEN2 (LABEL_TAC "sgperm") (LABEL_TAC "pb"))) THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;`ii:A`;`ci:A`;
                  `P:A`;`leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`sg:A`;
        `muci:A`;`muP:A`;`autB:A`;`lam:A`;`W:A`;`Z:A`] HSCUT_INV) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    X_GEN_TAC `u:A` THEN DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "uD")
        (LABEL_TAC "udm")) THEN
    X_GEN_TAC `tt:A` THEN DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "ttD")
        (LABEL_TAC "hstt")) THEN
    USE_THEN "Iach" (MP_TAC o SPECL [`u:A`;`tt:A`]) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `q:A` (CONJUNCTS_THEN2 (LABEL_TAC "qD")
      (CONJUNCTS_THEN2 (LABEL_TAC "qI") (LABEL_TAC "qeq")))) THEN
    EXISTS_TAC `q:A` THEN REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    USE_THEN "Zch" (MP_TAC o SPEC `q:A`) THEN
    ANTS_TAC THENL [USE_THEN "qD" ACCEPT_TAC; DISCH_THEN SUBST1_TAC] THEN
    CONJ_TAC THENL
     [USE_THEN "IW" MATCH_MP_TAC THEN CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
      USE_THEN "Ihs" MATCH_MP_TAC THEN CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC]]);;

(* term abbreviations for BVALF_HS_REPLACEMENT (HS versions of the V^B ones) *)
let funcf_tm_RH = `!!- x a (?? z (!! y (p --> Eq y z)))`;;
let exb_tm_RH   = `?? b (!! y ((y %% b) <-> ??- x a p))`;;
let collb_tm_RH = `!! y ((y %% b) <-> ??- x a p)`;;

let prem_tm_RH =
  `bvalf_HS (D:A->bool) (E:A->A->bool) (B:A) (inclB:A) (w1:A) (X:A) (v0:num->A)
     (!!- x a (?? z (!! y (p --> Eq y z))))`;;
let rr_tm_RH =
  `bvalf_HS (D:A->bool) (E:A->A->bool) (B:A) (inclB:A) (w1:A) (X:A)
      ((y |-> tt) (v0:num->A))
     (??- x a p)`;;
let pval_tm_RH =
  `bvalf_HS (D:A->bool) (E:A->A->bool) (B:A) (inclB:A) (w1:A) (X:A)
      (vv2:num->A) (y %% b)`;;
let qval_tm_RH =
  `bvalf_HS (D:A->bool) (E:A->A->bool) (B:A) (inclB:A) (w1:A) (X:A)
      (vv2:num->A) (??- x a p)`;;
let i1_tm_RH =
  `bvalf_HS (D:A->bool) (E:A->A->bool) (B:A) (inclB:A) (w1:A) (X:A) (vv2:num->A)
     ((y %% b) --> ??- x a p)`;;
let i2_tm_RH =
  `bvalf_HS (D:A->bool) (E:A->A->bool) (B:A) (inclB:A) (w1:A) (X:A) (vv2:num->A)
     ((??- x a p) --> (y %% b))`;;
let and_tm_RH =
  `bvalf_HS (D:A->bool) (E:A->A->bool) (B:A) (inclB:A) (w1:A) (X:A) (vv2:num->A)
     (((y %% b) --> ??- x a p) && ((??- x a p) --> (y %% b)))`;;
let collv1_tm_RH =
  `bvalf_HS (D:A->bool) (E:A->A->bool) (B:A) (inclB:A) (w1:A) (X:A) (v1:num->A)
     (!! y ((y %% b) <-> ??- x a p))`;;
let exbv0_tm_RH =
  `bvalf_HS (D:A->bool) (E:A->A->bool) (B:A) (inclB:A) (w1:A) (X:A) (v0:num->A)
     (?? b (!! y ((y %% b) <-> ??- x a p)))`;;
(* ===================================================================== *)
(* H4.11d : BVALF_HS_REPLACEMENT -- [[replacement_ax x y z a b p]]^HS = TOP *)
(* Witness bb = the HS separation name SEP(cn, ??- x a p), cn = the HS full *)
(* name over the uniform autN-invariant bound ddstar (REPL_STABILIZE_HS +    *)
(* HS_FULLNAME); per-tt endgame EBV_REPL_CORE_HS.                           *)
(* ===================================================================== *)
let BVALF_HS_REPLACEMENT = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X v x y z a b p.
      hsbundle D E w1 om tw ii ci P leqp B inclB onebee X /\
      valuation D v /\ (!i. hsname D E B w1 X (v i)) /\
      ~(z IN FV p) /\ ~(a IN FV p) /\ ~(b IN FV p) /\
      ~(x = y) /\ ~(x = z) /\ ~(x = a) /\ ~(x = b) /\
      ~(y = z) /\ ~(y = a) /\ ~(y = b) /\
      ~(z = a) /\ ~(z = b) /\ ~(a = b)
      ==> etop D E B inclB (bvalf_HS D E B inclB w1 X v
                            (replacement_ax x y z a b p))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_ASSUM(fun th -> let cs = CONJUNCTS(REWRITE_RULE[hsbundle] th)
                        and cb = CONJUNCTS(MATCH_MP HSB_CBA th) in
    MAP_EVERY ASSUME_TAC [el 0 cs; el 1 cs; el 3 cs; el 17 cs; el 19 cs;
                          el 0 cb; el 1 cb]) THEN
  TRY(SUBGOAL_THEN `!i:num. bname D (E:A->A->bool) B (((v):num->A) i)`
      ASSUME_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC HSNAME_BNAME THEN
    MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[valuation]; ALL_TAC]) THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B inclB` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B inclB` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `~(a:num = y) /\ ~(b:num = y)` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[replacement_ax] THEN
  (* ---- peel !!a -> aa ---- *)
  MP_TAC(ISPECL [`a:num`;
    `(!!- x a (?? z (!! y (p --> Eq y z)))) -->
     ?? b (!! y ((y %% b) <-> ??- x a p))`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;`X:A`;`v:num->A`]
        BVALF_HS_ALL_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  X_GEN_TAC `aa:A` THEN STRIP_TAC THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (aa:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  
  SUBGOAL_THEN `valuation D ((a |-> (aa:A)) (v:num->A)) /\
                (!i. hsname D E B w1 X (((a |-> (aa:A)) (v:num->A)) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC HSNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  TRY(SUBGOAL_THEN `!i:num. bname D (E:A->A->bool) B
      ((((a |-> (aa:A)) (v:num->A)):num->A) i)` ASSUME_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC HSNAME_BNAME THEN
    MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[valuation]; ALL_TAC]) THEN
  ABBREV_TAC `v0 = (a |-> (aa:A)) (v:num->A)` THEN
  SUBGOAL_THEN `(v0:num->A) a = aa` (LABEL_TAC "v0a") THENL
   [EXPAND_TAC "v0" THEN REWRITE_TAC[VALMOD_BASIC]; ALL_TAC] THEN
  (* ---- IMP_TOP : goal becomes  PREM <= [[?? b collb]]_v0 ---- *)
  MP_TAC(ISPECL [funcf_tm_RH; exb_tm_RH;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;`X:A`;`v0:num->A`]
        BVALF_HS_IMP_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  (* ---- PREM in D, E PREM B ---- *)
  SUBGOAL_THEN (mk_conj(mk_comb(mk_comb(`(IN):A->(A->bool)->bool`,
      prem_tm_RH),`D:A->bool`),
                        list_mk_comb(`E:A->A->bool`,[prem_tm_RH;`B:A`])))
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL [funcf_tm_RH;`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;
                     `w1:A`;`X:A`;`v0:num->A`]
        BVALF_HS_SPEC) THEN ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
            ASM_REWRITE_TAC[];
      MATCH_MP_TAC BVALF_HS_IN_B THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  (* ---- dm = domain of aa ---- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`aa:A`] EDOMAIN_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `dm:A` (STRIP_ASSUME_TAC o
      REWRITE_RULE[edomain])) THEN
  SUBGOAL_THEN
    `dm IN D /\ (!u. u IN D ==> (E u dm <=>
        eindom D (E:A->A->bool) ((v0:num->A) a) u))`
    (LABEL_TAC "dmch") THENL
   [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `!u:A. u IN D /\ E u dm ==> hsname D (E:A->A->bool) B w1 X u`
    (LABEL_TAC "dmbn") THENL
   [X_GEN_TAC `u:A` THEN STRIP_TAC THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (u:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;`aa:A`;`u:A`]
           HSNAME_DOM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
                    DISCH_THEN(ACCEPT_TAC o CONJUNCT2)]; ALL_TAC] THEN
  (* ---- REPL_STABILIZE : uniform stage ddstar = W_lam ---- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;`ii:A`;`ci:A`;
                 `P:A`;`leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`v0:num->A`;
      `x:num`;`y:num`;`p:form`;`dm:A`] REPL_STABILIZE_HS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ddstar:A`
    (CONJUNCTS_THEN2 (LABEL_TAC "ddin")
     (CONJUNCTS_THEN2 (LABEL_TAC "ddbn")
      (CONJUNCTS_THEN2 (LABEL_TAC "ddinv") (LABEL_TAC "achv0"))))) THEN
  (* ---- onebee = top of B ---- *)
  SUBGOAL_THEN `etop D (E:A->A->bool) B inclB onebee /\ onebee IN D /\
      (E:A->A->bool) onebee B`
   (CONJUNCTS_THEN2 (LABEL_TAC "onetop") STRIP_ASSUME_TAC) THENL
   [FIRST_ASSUM(fun th -> let cs = CONJUNCTS(REWRITE_RULE[hsbundle] th) in
      ACCEPT_TAC(CONJ (el 15 cs) (CONJ (el 16 cs) (el 18 cs)))); ALL_TAC] THEN
  (* ---- cn = EFULLNAME(onebee, ddstar) ---- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`ddstar:A`]
    EFULLNAME_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `cn:A`
    (CONJUNCTS_THEN2 (LABEL_TAC "cnin")
     (CONJUNCTS_THEN2 (LABEL_TAC "cnfun")
      (CONJUNCTS_THEN2 (LABEL_TAC "cndom")
       (CONJUNCTS_THEN2 (LABEL_TAC "cnap") (LABEL_TAC "cnmem")))))) THEN
  SUBGOAL_THEN `hsname D (E:A->A->bool) B w1 X cn` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;`ii:A`;
                   `ci:A`;`P:A`;`leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;
       `ddstar:A`;`cn:A`] HS_FULLNAME) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (cn:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  (* ---- bb = ESEPNAME(cn, ??- x a p) with sep-var y ---- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;
                 `X:A`;`v0:num->A`;
    `??- x a p`;`y:num`;`cn:A`] ESEPNAME_EXISTS_HS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `bb:A`
    (CONJUNCTS_THEN2 (LABEL_TAC "bbin")
     (CONJUNCTS_THEN2 (LABEL_TAC "bbfun")
      (CONJUNCTS_THEN2 (LABEL_TAC "bbdom")
       (CONJUNCTS_THEN2 (LABEL_TAC "bbap") (LABEL_TAC "bbmem")))))) THEN
  SUBGOAL_THEN `hsname D (E:A->A->bool) B w1 X bb` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;`ii:A`;
                         `ci:A`;`P:A`;`leqp:A`;`B:A`;`inclB:A`;`onebee:A`;
       `X:A`;`v0:num->A`;
      `??- x a p`;`y:num`;`cn:A`;`bb:A`] HS_SEPNAME) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (bb:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  (* ---- v1 = (b|->bb)v0 ---- *)
  SUBGOAL_THEN `valuation D ((b |-> (bb:A)) (v0:num->A)) /\
                (!i. hsname D E B w1 X (((b |-> (bb:A)) (v0:num->A)) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC HSNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  TRY(SUBGOAL_THEN `!i:num. bname D (E:A->A->bool) B
      ((((b |-> (bb:A)) (v0:num->A)):num->A) i)` ASSUME_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC HSNAME_BNAME THEN
    MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[valuation]; ALL_TAC]) THEN
  ABBREV_TAC `v1 = (b |-> (bb:A)) (v0:num->A)` THEN
  (* ---- exub : [[collb]]_v1 <= [[?? b collb]]_v0 ---- *)
  SUBGOAL_THEN (list_mk_comb(`erel (D:A->bool) (E:A->A->bool) (inclB:A)`,
                             [collv1_tm_RH; exbv0_tm_RH]))
    (LABEL_TAC "exub") THENL
   [SUBGOAL_THEN `(v1:num->A) = (b |-> (bb:A)) (v0:num->A)` SUBST1_TAC THENL
     [CONV_TAC SYM_CONV THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL [`b:num`;collb_tm_RH;`D:A->bool`;`E:A->A->bool`;`B:A`;
      `inclB:A`;`w1:A`;`X:A`;`v0:num->A`;`bb:A`] BVALF_HS_EX_UB) THEN
          ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ---- premle : PREM <= [[collb]]_v1  (the endgame) ---- *)
  SUBGOAL_THEN (list_mk_comb(`erel (D:A->bool) (E:A->A->bool) (inclB:A)`,
                             [prem_tm_RH; collv1_tm_RH]))
    (LABEL_TAC "premle") THENL
   [MATCH_MP_TAC(ISPECL [`y:num`;`(y %% b) <-> ??- x a p`;`D:A->bool`;
      `E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;`X:A`;`v1:num->A`;prem_tm_RH]
          BVALF_HS_ALL_GLB) THEN
    ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `tt:A` THEN STRIP_TAC THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (tt:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  
    SUBGOAL_THEN `valuation D ((y |-> (tt:A)) (v1:num->A)) /\
                  (!i. hsname D E B w1 X (((y |-> (tt:A)) (v1:num->A)) i))`
    STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC HSNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
    TRY(SUBGOAL_THEN `!i:num. bname D (E:A->A->bool) B
        ((((y |-> (tt:A)) (v1:num->A)):num->A) i)` ASSUME_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC HSNAME_BNAME THEN
    MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[valuation]; ALL_TAC]) THEN
  ABBREV_TAC `vv2 = (y |-> (tt:A)) (v1:num->A)` THEN
    (* vv2 lookups *)
    SUBGOAL_THEN `(vv2:num->A) y = tt /\ (vv2:num->A) b = bb`
      STRIP_ASSUME_TAC THENL
     [MAP_EVERY EXPAND_TAC ["vv2";"v1"] THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER]; ALL_TAC] THEN
    (* helper valuation (y|->tt)v0 *)
    SUBGOAL_THEN `valuation D ((y |-> (tt:A)) (v0:num->A)) /\
                  (!i. hsname D E B w1 X (((y |-> (tt:A)) (v0:num->A)) i))`
    STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC HSNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
    TRY(SUBGOAL_THEN `!i:num. bname D (E:A->A->bool) B
        ((((y |-> (tt:A)) (v0:num->A)):num->A) i)` ASSUME_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC HSNAME_BNAME THEN
    MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[valuation]; ALL_TAC]) THEN
  REWRITE_TAC[Iff_DEF] THEN
    (* K = [[tt IN cn]] *)
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`tt:A`;`cn:A`]
      EBV_IN_VAL_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `K:A`
      (CONJUNCTS_THEN2 (LABEL_TAC "kkin")
       (CONJUNCTS_THEN2 (LABEL_TAC "kkB") (LABEL_TAC "kkev")))) THEN
    (* rr in D, E rr B *)
    SUBGOAL_THEN (mk_conj(mk_comb(mk_comb(`(IN):A->(A->bool)->bool`,
        rr_tm_RH),`D:A->bool`),
                          list_mk_comb(`E:A->A->bool`,[rr_tm_RH;`B:A`])))
      STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [MP_TAC(ISPECL [`??- x a p`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                       `inclB:A`;`w1:A`;`X:A`;
          `(y |-> (tt:A)) (v0:num->A)`] BVALF_HS_SPEC) THEN
        ASM_REWRITE_TAC[] THEN STRIP_TAC THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC BVALF_HS_IN_B THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
    (* qeq : [[??- x a p]]_vv2 = rr  (b not in FV) *)
    SUBGOAL_THEN (mk_eq(qval_tm_RH,rr_tm_RH)) (LABEL_TAC "qeq") THENL
     [MATCH_MP_TAC(ISPECL [`??- x a p`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                           `inclB:A`;`w1:A`;`X:A`;
        `vv2:num->A`;`(y |-> (tt:A)) (v0:num->A)`] BVALF_HS_FV_CONG) THEN
      ASM_REWRITE_TAC[] THEN
      X_GEN_TAC `i:num` THEN
      REWRITE_TAC[FV_CLAUSES; IN_DELETE; IN_INSERT] THEN DISCH_TAC THEN
      SUBGOAL_THEN `~(i:num = b)` ASSUME_TAC THENL
       [ASM_MESON_TAC[]; ALL_TAC] THEN
      MAP_EVERY EXPAND_TAC ["vv2";"v1"] THEN
      ASM_CASES_TAC `i:num = y` THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER]; ALL_TAC] THEN
    (* pval = [[y IN b]]_vv2, ebv_in tt bb pval *)
    SUBGOAL_THEN (list_mk_comb(`ebv_in (D:A->bool) (E:A->A->bool)
        (B:A) (inclB:A)`,
                               [`tt:A`;`bb:A`;pval_tm_RH]))
      (LABEL_TAC "pmem") THENL
     [MP_TAC(ISPECL [`y:num`;`b:num`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                     `inclB:A`;`w1:A`;`X:A`;
        `vv2:num->A`] BVALF_HS_MEM) THEN ASM_REWRITE_TAC[] THEN
      ASM_SIMP_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN (mk_conj(mk_comb(mk_comb(`(IN):A->(A->bool)->bool`,
        pval_tm_RH),`D:A->bool`),
                          list_mk_comb(`E:A->A->bool`,[pval_tm_RH;`B:A`])))
      STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [MP_TAC(ISPECL [`(y %% b):form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                       `inclB:A`;`w1:A`;`X:A`;
          `vv2:num->A`] BVALF_HS_SPEC) THEN ASM_REWRITE_TAC[] THEN
              STRIP_TAC THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC BVALF_HS_IN_B THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
    (* rhs = meet(K,rr) *)
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`K:A`;rr_tm_RH]
      EBALG_MEET) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `rhs:A` (LABEL_TAC "rhsmeet")) THEN
    (* pvaleq : pval = rhs  (EBV_IN_SEP_HS) *)
    SUBGOAL_THEN (mk_eq(pval_tm_RH,`rhs:A`)) (LABEL_TAC "pvaleq") THENL
     [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;
                     `X:A`;`v0:num->A`;
        `??- x a p`;`y:num`;`cn:A`;`tt:A`;`bb:A`;pval_tm_RH;`K:A`;`rhs:A`]
        EBV_IN_SEP_HS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
    (* emKrr : emeet K rr pval *)
    SUBGOAL_THEN (list_mk_comb(`emeet (D:A->bool) (E:A->A->bool)
        (B:A) (inclB:A)`,
                               [`K:A`;rr_tm_RH;pval_tm_RH]))
      (LABEL_TAC "emKrr") THENL
     [USE_THEN "pvaleq" (fun th -> ONCE_REWRITE_TAC[th]) THEN
      USE_THEN "rhsmeet" ACCEPT_TAC; ALL_TAC] THEN
    (* mm = meet(PREM,rr) *)
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;
                   prem_tm_RH;rr_tm_RH]
      EBALG_MEET) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `mm:A` (LABEL_TAC "mmmeet")) THEN
    SUBGOAL_THEN `(mm:A) IN D /\ (E:A->A->bool) mm B` STRIP_ASSUME_TAC THENL
     [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EMEET_IN); ALL_TAC] THEN
    (* core : mm <= K  (EBV_REPL_CORE_HS) *)
    SUBGOAL_THEN `erel (D:A->bool) (E:A->A->bool) inclB mm (K:A)`
        (LABEL_TAC "core") THENL
     [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;
                     `X:A`;`v0:num->A`;
        `x:num`;`y:num`;`z:num`;`a:num`;`p:form`;`tt:A`;`dm:A`;`ddstar:A`;
        `onebee:A`;`cn:A`;`K:A`;`mm:A`] EBV_REPL_CORE_HS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
                      DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    (* mm <= rr *)
    SUBGOAL_THEN (list_mk_comb(`erel (D:A->bool) (E:A->A->bool) (inclB:A)`,
        [`mm:A`;rr_tm_RH]))
      (LABEL_TAC "mmrr") THENL
     [ASM_MESON_TAC[EMEET_LE]; ALL_TAC] THEN
    (* mm <= pval  (EMEET_GREATEST on emKrr) *)
    SUBGOAL_THEN (list_mk_comb(`erel (D:A->bool) (E:A->A->bool) (inclB:A)`,
        [`mm:A`;pval_tm_RH]))
      (LABEL_TAC "mmpval") THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;
                           `inclB:A`;`K:A`;rr_tm_RH;
        pval_tm_RH;`mm:A`] EMEET_GREATEST) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* i1 : ebimp pval qval i1  (BVALF_HS_IMP), then qeq -> ebimp pval rr i1 *)
    SUBGOAL_THEN (list_mk_comb(`ebimp (D:A->bool) (E:A->A->bool)
        (B:A) (inclB:A)`,
                               [pval_tm_RH;rr_tm_RH;i1_tm_RH]))
                                   (LABEL_TAC "imp1") THENL
     [MP_TAC(ISPECL [`(y %% b):form`;`??- x a p`;`D:A->bool`;
                     `E:A->A->bool`;`B:A`;
        `inclB:A`;`w1:A`;`X:A`;`vv2:num->A`] BVALF_HS_IMP) THEN
            ASM_REWRITE_TAC[] THEN
      USE_THEN "qeq" (fun th -> REWRITE_TAC[th]); ALL_TAC] THEN
    (* m1 = meet(PREM,pval) *)
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;
                   prem_tm_RH;pval_tm_RH]
      EBALG_MEET) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `m1:A` (LABEL_TAC "m1meet")) THEN
    SUBGOAL_THEN `(m1:A) IN D /\ (E:A->A->bool) m1 B` STRIP_ASSUME_TAC THENL
     [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EMEET_IN); ALL_TAC] THEN
    (* pval <= rr *)
    SUBGOAL_THEN (list_mk_comb(`erel (D:A->bool) (E:A->A->bool) (inclB:A)`,
        [pval_tm_RH;rr_tm_RH]))
      (LABEL_TAC "pvalrr") THENL
     [ASM_MESON_TAC[EMEET_LE]; ALL_TAC] THEN
    (* m1 <= rr *)
    SUBGOAL_THEN (list_mk_comb(`erel (D:A->bool) (E:A->A->bool) (inclB:A)`,
        [`m1:A`;rr_tm_RH]))
      (LABEL_TAC "m1rr") THENL
     [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`m1:A`;
                     pval_tm_RH;rr_tm_RH]
        EPORDER_TRANS) THEN ASM_REWRITE_TAC[] THEN
      DISCH_THEN MATCH_MP_TAC THEN ASM_MESON_TAC[EMEET_LE]; ALL_TAC] THEN
    (* prem <= i1  (EBIMP_LE_IMP) *)
    SUBGOAL_THEN (list_mk_comb(`erel (D:A->bool) (E:A->A->bool) (inclB:A)`,
        [prem_tm_RH;i1_tm_RH]))
      (LABEL_TAC "prem_i1") THENL
     [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;prem_tm_RH;
                     pval_tm_RH;rr_tm_RH;
        i1_tm_RH;`m1:A`] EBIMP_LE_IMP) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* i2 : ebimp qval pval i2, then qeq -> ebimp rr pval i2 *)
    SUBGOAL_THEN (list_mk_comb(`ebimp (D:A->bool) (E:A->A->bool)
        (B:A) (inclB:A)`,
                               [rr_tm_RH;pval_tm_RH;i2_tm_RH]))
                                   (LABEL_TAC "imp2") THENL
     [MP_TAC(ISPECL [`??- x a p`;`(y %% b):form`;`D:A->bool`;
                     `E:A->A->bool`;`B:A`;
        `inclB:A`;`w1:A`;`X:A`;`vv2:num->A`] BVALF_HS_IMP) THEN
            ASM_REWRITE_TAC[] THEN
      USE_THEN "qeq" (fun th -> REWRITE_TAC[th]); ALL_TAC] THEN
    (* prem <= i2  (EBIMP_LE_IMP, m=mm) *)
    SUBGOAL_THEN (list_mk_comb(`erel (D:A->bool) (E:A->A->bool) (inclB:A)`,
        [prem_tm_RH;i2_tm_RH]))
      (LABEL_TAC "prem_i2") THENL
     [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;prem_tm_RH;
                     rr_tm_RH;pval_tm_RH;
        i2_tm_RH;`mm:A`] EBIMP_LE_IMP) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* andmeet : emeet i1 i2 andval *)
    SUBGOAL_THEN (list_mk_comb(`emeet (D:A->bool) (E:A->A->bool)
        (B:A) (inclB:A)`,
                               [i1_tm_RH;i2_tm_RH;and_tm_RH]))
                                   (LABEL_TAC "andmeet") THENL
     [MP_TAC(ISPECL [`(y %% b) --> ??- x a p`;`(??- x a p) --> (y %% b)`;
        `D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;`X:A`;`vv2:num->A`]
            BVALF_HS_AND_MEET) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* finish : PREM <= andval *)
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;
                         i1_tm_RH;i2_tm_RH;
      and_tm_RH;prem_tm_RH] EMEET_GREATEST) THEN
          ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ---- collv1, exbv0 values in D (transitivity membership side conds) ---- *)
  SUBGOAL_THEN (mk_comb(mk_comb(`(IN):A->(A->bool)->bool`,
      collv1_tm_RH),`D:A->bool`))
    ASSUME_TAC THENL
   [MP_TAC(ISPECL [collb_tm_RH;`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;
                   `w1:A`;`X:A`;`v1:num->A`]
      BVALF_HS_SPEC) THEN ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
          ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN (mk_comb(mk_comb(`(IN):A->(A->bool)->bool`,
      exbv0_tm_RH),`D:A->bool`))
    ASSUME_TAC THENL
   [MP_TAC(ISPECL [exb_tm_RH;`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;
                   `X:A`;`v0:num->A`]
      BVALF_HS_SPEC) THEN ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
          ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ---- combine premle + exub via transitivity ---- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;prem_tm_RH;
                 collv1_tm_RH;exbv0_tm_RH]
    EPORDER_TRANS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
  ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THEN
  MATCH_MP_TAC BVALF_HS_IN_B THEN ASM_REWRITE_TAC[]);;

(* ===================================================================== *)
(* H4.12 : ASSEMBLY.  Every axiom of ZF_AX has HS-value TOP at every HS    *)
(* valuation (BVALF_HS_ZF_TOP), hence (QSAT_AX_HS + QDOM_HS_NONEMPTY) the  *)
(* HS quotient by ANY ultrafilter U is a model of ZF (HS_QUOT_MODEL_ZF).    *)
(* ===================================================================== *)
let BVALF_HS_INF_TOP = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X.
      hsbundle D E w1 om tw ii ci P leqp B inclB onebee X
      ==> !c. valuation D c /\ (!i. hsname D E B w1 X (c i))
              ==> etop D E B inclB (bvalf_HS D E B inclB w1 X c infinity_ax)`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "hsb") THEN
  USE_THEN "hsb" (fun th -> let cs = CONJUNCTS(REWRITE_RULE[hsbundle] th)
                            and cb = CONJUNCTS(MATCH_MP HSB_CBA th)
                            and cf = CONJUNCTS(MATCH_MP HSB_FACTS th) in
    MAP_EVERY ASSUME_TAC [el 0 cs; el 1 cs; el 2 cs; el 3 cs; el 15 cs;
                          el 16 cs; el 17 cs;
                          el 18 cs; el 19 cs; el 0 cb; el 1 cb; el 0 cf]) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`om:A`]
         ECHECK_EXHAUSTION) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `vom:A`) THEN
  X_GEN_TAC `c:num->A` THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;`X:A`;
                 `onebee:A`;`om:A`;
                 `vom:A`;`c:num->A`;`tw:A`;`ii:A`;`ci:A`;`P:A`;`leqp:A`]
                     BVALF_HS_INFINITY) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                  DISCH_THEN ACCEPT_TAC]);;

let BVALF_HS_ZF_TOP = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X p.
      hsbundle D E w1 om tw ii ci P leqp B inclB onebee X /\ p IN ZF_AX
      ==> !c. valuation D c /\ (!i. hsname D E B w1 X (c i))
              ==> etop D E B inclB (bvalf_HS D E B inclB w1 X c p)`,
  REPEAT GEN_TAC THEN DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "hsb") MP_TAC) THEN
  USE_THEN "hsb" (fun th -> let cs = CONJUNCTS(REWRITE_RULE[hsbundle] th)
                            and cb = CONJUNCTS(MATCH_MP HSB_CBA th) in
    MAP_EVERY ASSUME_TAC [el 0 cs; el 3 cs; el 17 cs; el 19 cs;
                          el 0 cb; el 1 cb]) THEN
  REWRITE_TAC[ZF_AX; IN_INSERT; IN_UNION; NOT_IN_EMPTY; IN_ELIM_THM] THEN
  STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `c:num->A` THEN STRIP_TAC THENL
   [MATCH_MP_TAC BVALF_HS_EXTENSIONALITY THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC BVALF_HS_FOUNDATION THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;
                         `ii:A`;`ci:A`;`P:A`;
                         `leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`c:num->A`]
                             BVALF_HS_PAIRING) THEN
    ASM_REWRITE_TAC[];
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;
                         `ii:A`;`ci:A`;`P:A`;
                         `leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`c:num->A`]
                             BVALF_HS_UNION) THEN
    ASM_REWRITE_TAC[];
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;
                         `ii:A`;`ci:A`;`P:A`;
                         `leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`c:num->A`]
                             BVALF_HS_POWERSET) THEN
    ASM_REWRITE_TAC[];
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;
                   `ii:A`;`ci:A`;`P:A`;
                   `leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`]
                       BVALF_HS_INF_TOP) THEN
    ANTS_TAC THENL [USE_THEN "hsb" ACCEPT_TAC; DISCH_THEN MATCH_MP_TAC] THEN
    ASM_REWRITE_TAC[];
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;
                         `ii:A`;`ci:A`;`P:A`;
                         `leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`c:num->A`;
                         `x:num`;`a:num`;`s:num`;`p':form`]
                             BVALF_HS_SEPARATION) THEN
    ASM_REWRITE_TAC[];
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;
                         `ii:A`;`ci:A`;`P:A`;
                         `leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`c:num->A`;
                         `x:num`;`y:num`;`z:num`;`a:num`;`b:num`;`p':form`]
                             BVALF_HS_REPLACEMENT) THEN
    ASM_REWRITE_TAC[]]);;

let HS_QUOT_MODEL_ZF = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X U.
      hsbundle D E w1 om tw ii ci P leqp B inclB onebee X /\
      eultra D E B inclB U
      ==> model (qdom_HS D E B inclB w1 X U) (qmem D E B inclB U) ZF_AX`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  REWRITE_TAC[model; satisfies] THEN CONJ_TAC THENL
   [MATCH_MP_TAC QDOM_HS_NONEMPTY THEN
    MAP_EVERY EXISTS_TAC [`om:A`;`tw:A`;`ii:A`;`ci:A`;`P:A`;`leqp:A`;
                          `onebee:A`] THEN
    ASM_REWRITE_TAC[];
    MAP_EVERY X_GEN_TAC [`v:num->A`; `p:form`] THEN STRIP_TAC THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;
                   `ii:A`;`ci:A`;`P:A`;
                   `leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`U:A`;`p:form`]
                       QSAT_AX_HS) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;
                           `ii:A`;`ci:A`;`P:A`;
                           `leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`p:form`]
                               BVALF_HS_ZF_TOP) THEN
      CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
      DISCH_THEN MATCH_MP_TAC THEN FIRST_ASSUM ACCEPT_TAC]]);;

(* ######################################################################### *)
(* S6 (part 1) : THE ~AC CORE -- infrastructure.                            *)
(* Internal half (pure ZF in any model): HOLDS_CHOICE_AX_ELIM,              *)
(* CHOICE_REL_INTERNAL (choice_ax gives every family of nonempty sets a     *)
(* choice relation).  Tools: W1_UNCOUNTABLE, TRANSPOSITION_EXISTS.  The     *)
(* real bundle (ereal/eembf/nbundle) and the names: RS_e and its full name  *)
(* Shat_e (support e; NB_SHAT), and the family S = full name over the HS    *)
(* names of one stage with a top-valued member (empty support; NB_FAMILY).  *)
(* Design: NOTAC_S6_DESIGN.txt.                                             *)
(* ######################################################################### *)
(* ===================================================================== *)
(* S6-A : the INTERNAL half of the ~AC argument (pure ZF in any model).   *)
(* HOLDS_CHOICE_AX_ELIM: the converse of HOLDS_CHOICE_AX_INTRO.            *)
(* ===================================================================== *)
let HOLDS_CHOICE_AX_ELIM = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v /\ holds D E v choice_ax
        ==> !x. x IN D /\
             (!y. y IN D /\ E y x ==> ?z. z IN D /\ E z y) /\
             (!y y'. y IN D /\ y' IN D /\ E y x /\ E y' x /\
                     ~(y = y')
                     ==> ~(?z. z IN D /\ E z y /\ E z y'))
             ==> ?c. c IN D /\
                     !y. y IN D /\ E y x
                         ==> ?z. z IN D /\ E z y /\ E z c /\
                                 !z'. z' IN D /\ E z' y /\
                                      E z' c
                                      ==> z' = z`,
  REPEAT GEN_TAC THEN DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC MP_TAC)) THEN
  REWRITE_TAC[choice_ax; HOLDS_EX; HOLDS_AND; HOLDS_NOT; holds] THEN
  REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
  REWRITE_TAC[] THEN
  DISCH_THEN(LABEL_TAC "ch") THEN
  X_GEN_TAC `x:A` THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "xD")
             (CONJUNCTS_THEN2 (LABEL_TAC "ne") (LABEL_TAC "dj"))) THEN
  USE_THEN "ch" (MP_TAC o SPEC `x:A`) THEN
  ANTS_TAC THENL [USE_THEN "xD" ACCEPT_TAC; ALL_TAC] THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [X_GEN_TAC `y:A` THEN DISCH_TAC THEN DISCH_TAC THEN
      USE_THEN "ne" MATCH_MP_TAC THEN CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
      X_GEN_TAC `y:A` THEN DISCH_TAC THEN X_GEN_TAC `y':A` THEN
          DISCH_TAC THEN STRIP_TAC THEN
      USE_THEN "dj" MATCH_MP_TAC THEN REPEAT CONJ_TAC THEN
          FIRST_ASSUM ACCEPT_TAC];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `c:A` (CONJUNCTS_THEN2 (LABEL_TAC "cD")
      (LABEL_TAC "cp"))) THEN
  EXISTS_TAC `c:A` THEN CONJ_TAC THENL [USE_THEN "cD" ACCEPT_TAC; ALL_TAC] THEN
  X_GEN_TAC `y:A` THEN DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "yD")
      (LABEL_TAC "yx")) THEN
  USE_THEN "cp" (MP_TAC o SPEC `y:A`) THEN
  ANTS_TAC THENL [USE_THEN "yD" ACCEPT_TAC; ALL_TAC] THEN
  ANTS_TAC THENL [USE_THEN "yx" ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `z:A` (CONJUNCTS_THEN2 (LABEL_TAC "zD")
      (CONJUNCTS_THEN2 (LABEL_TAC "zy") (CONJUNCTS_THEN2 (LABEL_TAC "zc")
      (LABEL_TAC "uq"))))) THEN
  EXISTS_TAC `z:A` THEN REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
  X_GEN_TAC `z':A` THEN STRIP_TAC THEN
  USE_THEN "uq" (MP_TAC o SPEC `z':A`) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                  DISCH_THEN ACCEPT_TAC]);;

(* CHOICE_REL_INTERNAL: in any model of ZF + choice_ax, a family s of       *)
(* nonempty sets has a "choice relation" y: for each x IN s exactly one z IN *)
(* x has <x,z> IN y.  Via F' = { {x} x x : x IN s } (ZF_REPLACEMENT along    *)
(* !!9 ((9%%2) <-> ??10 ((10%%1) && opair_form 1 10 9))), which is a family *)
(* of nonempty pairwise disjoint sets (EOPAIR_INJ); its transversal is y.    *)
let CHOICE_REL_INTERNAL = prove
 (`!D (E:A->A->bool) s.
     model D E ZF_AX /\ (!v. valuation D v ==> holds D E v choice_ax) /\
     s IN D /\ (!x. x IN D /\ E x s ==> ?z. z IN D /\ E z x)
     ==> ?y. y IN D /\
             !x. x IN D /\ E x s
                 ==> ?z. z IN D /\ E z x /\
                         (?p. p IN D /\ eopair D E x z p /\ E p y) /\
                         !z'. z' IN D /\ E z' x /\
                              (?p'. p' IN D /\ eopair D E x z' p' /\ E p' y)
                              ==> z' = z`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
             (CONJUNCTS_THEN2 (LABEL_TAC "ac")
    (CONJUNCTS_THEN2 (LABEL_TAC "sD") (LABEL_TAC "ne")))) THEN
  USE_THEN "modl" (MP_TAC o MATCH_MP MODEL_NONEMPTY) THEN
  DISCH_THEN(X_CHOOSE_THEN `v0:num->A` (LABEL_TAC "vv") o MATCH_MP
             VALUATION_EXISTS) THEN
  (* the sets X_x = {x} x x *)
  SUBGOAL_THEN
   `!x:A. x IN D ==> ?X. X IN D /\
          !p. p IN D ==> ((E:A->A->bool) p X <=> ?z. z IN D /\ E z x /\
                          eopair D E x z p)`
   (LABEL_TAC "Xex") THENL
   [X_GEN_TAC `x:A` THEN DISCH_THEN(LABEL_TAC "xD") THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`x:A`;`x:A`] EPAIR_EXISTS) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `sx:A` (LABEL_TAC "sx")) THEN
    SUBGOAL_THEN `(sx:A) IN D` (LABEL_TAC "sxD") THENL
     [USE_THEN "sx" (ACCEPT_TAC o MATCH_MP EPAIR_IN); ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`sx:A`;`x:A`] ECROSS_EXISTS) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `X:A` (LABEL_TAC "cr")) THEN
    EXISTS_TAC `X:A` THEN CONJ_TAC THENL
     [USE_THEN "cr" (ACCEPT_TAC o CONJUNCT1 o
                     REWRITE_RULE[ecross]); ALL_TAC] THEN
    X_GEN_TAC `p:A` THEN DISCH_THEN(LABEL_TAC "pD") THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`sx:A`;`x:A`;`X:A`;`p:A`]
           ECROSS_MEMBER) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN SUBST1_TAC] THEN
    EQ_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `u:A` (X_CHOOSE_THEN `w:A`
         (CONJUNCTS_THEN2 (LABEL_TAC "uD")
        (CONJUNCTS_THEN2 (LABEL_TAC "wD") (CONJUNCTS_THEN2 (LABEL_TAC "usx")
          (CONJUNCTS_THEN2 (LABEL_TAC "wx") (LABEL_TAC "op"))))))) THEN
      SUBGOAL_THEN `u:A = x` SUBST_ALL_TAC THENL
       [USE_THEN "sx" (MP_TAC o SPEC `u:A` o CONJUNCT2 o
                       REWRITE_RULE[epair]) THEN
        ANTS_TAC THENL [USE_THEN "uD" ACCEPT_TAC;
                        DISCH_THEN(fun th -> USE_THEN "usx"
            (MP_TAC o EQ_MP th))] THEN
        DISCH_THEN ACCEPT_TAC;
        ALL_TAC] THEN
      EXISTS_TAC `w:A` THEN REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
      DISCH_THEN(X_CHOOSE_THEN `z:A` (CONJUNCTS_THEN2 (LABEL_TAC "zD")
        (CONJUNCTS_THEN2 (LABEL_TAC "zx") (LABEL_TAC "op")))) THEN
      MAP_EVERY EXISTS_TAC [`x:A`;`z:A`] THEN REPEAT CONJ_TAC THEN
          TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      USE_THEN "sx" (MP_TAC o SPEC `x:A` o CONJUNCT2 o REWRITE_RULE[epair]) THEN
      ANTS_TAC THENL [USE_THEN "xD" ACCEPT_TAC; DISCH_THEN SUBST1_TAC] THEN
      REWRITE_TAC[]];
    ALL_TAC] THEN
  (* semantics of the replacement formula *)
  SUBGOAL_THEN
   `!u w:A. u IN D /\ w IN D
            ==> (holds D (E:A->A->bool) ((2 |-> w) ((1 |-> u) (v0:num->A)))
                   (!! 9 ((9 %% 2) <-> ?? 10 ((10 %% 1) &&
                       opair_form 1 10 9))) <=>
                 !p. p IN D ==> (E p w <=> ?z. z IN D /\ E z u /\
                                 eopair D E u z p))`
   (LABEL_TAC "phisem") THENL
   [MAP_EVERY X_GEN_TAC [`u:A`;`w:A`] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "uD") (LABEL_TAC "wD")) THEN
    REWRITE_TAC[holds; HOLDS_IFF; HOLDS_EX; HOLDS_AND] THEN
    MATCH_MP_TAC(MESON[] `(!p:A. p IN D ==> (Pw p <=> Qw p)) ==>
                          ((!p. p IN D ==> Pw p) <=>
                           (!p. p IN D ==> Qw p))`) THEN
    X_GEN_TAC `p:A` THEN DISCH_THEN(LABEL_TAC "pD") THEN
    MATCH_MP_TAC(TAUT `(a <=> a') /\ (b <=> b')
                 ==> ((a <=> b) <=> (a' <=> b'))`) THEN
    CONJ_TAC THENL
     [REWRITE_TAC[VALMOD; ARITH_EQ];
      MATCH_MP_TAC(MESON[] `(!s:A. s IN D ==> (P s <=> Q s))
                            ==> ((?s. s IN D /\ P s) <=>
                                 (?s. s IN D /\ Q s))`) THEN
      X_GEN_TAC `z:A` THEN DISCH_THEN(LABEL_TAC "zD") THEN
      SUBGOAL_THEN `valuation D ((10 |-> (z:A))
          ((9 |-> (p:A)) ((2 |-> (w:A)) ((1 |-> (u:A)) (v0:num->A)))))`
       (LABEL_TAC "vz") THENL
       [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC) THEN
        FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      USE_THEN "vz" (fun vth -> SIMP_TAC[vth; HOLDS_OPAIR_FORM]) THEN
      REWRITE_TAC[VALMOD; ARITH_EQ]];
    ALL_TAC] THEN
  (* F' by replacement *)
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`] ZF_REPLACEMENT) THEN
  ANTS_TAC THENL [USE_THEN "modl" ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`!! 9 ((9 %% 2) <-> ?? 10 ((10 %% 1) && opair_form 1 10 9))`; `1`; `2`;
     `v0:num->A`; `s:A`]) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN TRY ARITH_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    X_GEN_TAC `u:A` THEN DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "uD")
        (LABEL_TAC "us")) THEN
    USE_THEN "Xex" (MP_TAC o SPEC `u:A`) THEN
    ANTS_TAC THENL [USE_THEN "uD" ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `X0:A` (CONJUNCTS_THEN2 (LABEL_TAC "X0D")
        (LABEL_TAC "X0ch"))) THEN
    EXISTS_TAC `X0:A` THEN CONJ_TAC THENL
        [USE_THEN "X0D" ACCEPT_TAC; ALL_TAC] THEN
    X_GEN_TAC `w':A` THEN DISCH_THEN(CONJUNCTS_THEN2
        (LABEL_TAC "w'D") MP_TAC) THEN
    USE_THEN "phisem" (MP_TAC o SPECL [`u:A`;`w':A`]) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN SUBST1_TAC] THEN
    DISCH_THEN(LABEL_TAC "w'ch") THEN
    USE_THEN "modl" (MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
    REPEAT CONJ_TAC THENL [USE_THEN "w'D" ACCEPT_TAC;
                           USE_THEN "X0D" ACCEPT_TAC; ALL_TAC] THEN
    X_GEN_TAC `p:A` THEN DISCH_THEN(LABEL_TAC "pD") THEN
    USE_THEN "w'ch" (MP_TAC o SPEC `p:A`) THEN
    ANTS_TAC THENL [USE_THEN "pD" ACCEPT_TAC; DISCH_THEN SUBST1_TAC] THEN
    USE_THEN "X0ch" (MP_TAC o SPEC `p:A`) THEN
    ANTS_TAC THENL [USE_THEN "pD" ACCEPT_TAC; DISCH_THEN SUBST1_TAC] THEN
    REFL_TAC;
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `FF:A` (CONJUNCTS_THEN2 (LABEL_TAC "FFD")
      (LABEL_TAC "FFch0"))) THEN
  SUBGOAL_THEN
   `!X:A. X IN D ==> ((E:A->A->bool) X FF <=>
            ?u. u IN D /\ E u s /\ !p. p IN D
                ==> (E p X <=> ?z. z IN D /\ E z u /\ eopair D E u z p))`
   (LABEL_TAC "FFch") THENL
   [X_GEN_TAC `X:A` THEN DISCH_THEN(LABEL_TAC "XD") THEN
    USE_THEN "FFch0" (MP_TAC o SPEC `X:A`) THEN
    ANTS_TAC THENL [USE_THEN "XD" ACCEPT_TAC; DISCH_THEN SUBST1_TAC] THEN
    MATCH_MP_TAC(MESON[] `(!u:A. u IN D ==> (P u <=> Q u))
                          ==> ((?u. u IN D /\ R u /\ P u) <=>
                               (?u. u IN D /\ R u /\ Q u))`) THEN
    X_GEN_TAC `u:A` THEN DISCH_THEN(LABEL_TAC "uD") THEN
    USE_THEN "phisem" (MP_TAC o SPECL [`u:A`;`X:A`]) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  (* choice_ax applied to FF *)
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`v0:num->A`]
         HOLDS_CHOICE_AX_ELIM) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    USE_THEN "ac" MATCH_MP_TAC THEN USE_THEN "vv" ACCEPT_TAC;
    ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `FF:A`) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [USE_THEN "FFD" ACCEPT_TAC;
      X_GEN_TAC `X:A` THEN DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "XD")
          (LABEL_TAC "XF")) THEN
      USE_THEN "FFch" (MP_TAC o SPEC `X:A`) THEN
      ANTS_TAC THENL [USE_THEN "XD" ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> USE_THEN "XF" (MP_TAC o EQ_MP th)) THEN
      DISCH_THEN(X_CHOOSE_THEN `u:A` (CONJUNCTS_THEN2 (LABEL_TAC "uD")
        (CONJUNCTS_THEN2 (LABEL_TAC "us") (LABEL_TAC "Xch")))) THEN
      USE_THEN "ne" (MP_TAC o SPEC `u:A`) THEN
      ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `z:A` (CONJUNCTS_THEN2 (LABEL_TAC "zD")
          (LABEL_TAC "zu"))) THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`u:A`;`z:A`] EOPAIR_EXISTS) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `p:A` (LABEL_TAC "op")) THEN
      SUBGOAL_THEN `(p:A) IN D` (LABEL_TAC "pD") THENL
       [USE_THEN "op" (ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
      EXISTS_TAC `p:A` THEN CONJ_TAC THENL
          [USE_THEN "pD" ACCEPT_TAC; ALL_TAC] THEN
      USE_THEN "Xch" (MP_TAC o SPEC `p:A`) THEN
      ANTS_TAC THENL [USE_THEN "pD" ACCEPT_TAC; DISCH_THEN SUBST1_TAC] THEN
      EXISTS_TAC `z:A` THEN REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
      MAP_EVERY X_GEN_TAC [`X:A`;`X':A`] THEN
      DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "XD")
                 (CONJUNCTS_THEN2 (LABEL_TAC "X'D")
        (CONJUNCTS_THEN2 (LABEL_TAC "XF")
         (CONJUNCTS_THEN2 (LABEL_TAC "X'F") (LABEL_TAC "XX'"))))) THEN
      DISCH_THEN(X_CHOOSE_THEN `q:A` (CONJUNCTS_THEN2 (LABEL_TAC "qD")
        (CONJUNCTS_THEN2 (LABEL_TAC "qX") (LABEL_TAC "qX'")))) THEN
      USE_THEN "FFch" (MP_TAC o SPEC `X:A`) THEN
      ANTS_TAC THENL [USE_THEN "XD" ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> USE_THEN "XF" (MP_TAC o EQ_MP th)) THEN
      DISCH_THEN(X_CHOOSE_THEN `u:A` (CONJUNCTS_THEN2 (LABEL_TAC "uD")
        (CONJUNCTS_THEN2 (LABEL_TAC "us") (LABEL_TAC "Xch")))) THEN
      USE_THEN "FFch" (MP_TAC o SPEC `X':A`) THEN
      ANTS_TAC THENL [USE_THEN "X'D" ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> USE_THEN "X'F" (MP_TAC o EQ_MP th)) THEN
      DISCH_THEN(X_CHOOSE_THEN `u':A` (CONJUNCTS_THEN2 (LABEL_TAC "u'D")
        (CONJUNCTS_THEN2 (LABEL_TAC "u's") (LABEL_TAC "X'ch")))) THEN
      USE_THEN "Xch" (MP_TAC o SPEC `q:A`) THEN
      ANTS_TAC THENL [USE_THEN "qD" ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> USE_THEN "qX" (MP_TAC o EQ_MP th)) THEN
      DISCH_THEN(X_CHOOSE_THEN `z:A` (CONJUNCTS_THEN2 (LABEL_TAC "zD")
        (CONJUNCTS_THEN2 (LABEL_TAC "zu") (LABEL_TAC "opq")))) THEN
      USE_THEN "X'ch" (MP_TAC o SPEC `q:A`) THEN
      ANTS_TAC THENL [USE_THEN "qD" ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> USE_THEN "qX'" (MP_TAC o EQ_MP th)) THEN
      DISCH_THEN(X_CHOOSE_THEN `z':A` (CONJUNCTS_THEN2 (LABEL_TAC "z'D")
        (CONJUNCTS_THEN2 (LABEL_TAC "z'u'") (LABEL_TAC "opq'")))) THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`u:A`;`z:A`;`u':A`;`z':A`;`q:A`]
             EOPAIR_INJ) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(CONJUNCTS_THEN2 (SUBST_ALL_TAC o SYM) (K ALL_TAC)) THEN
      USE_THEN "XX'" MP_TAC THEN REWRITE_TAC[] THEN
      USE_THEN "modl" (MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
      REPEAT CONJ_TAC THENL [USE_THEN "XD" ACCEPT_TAC;
                             USE_THEN "X'D" ACCEPT_TAC; ALL_TAC] THEN
      X_GEN_TAC `r:A` THEN DISCH_THEN(LABEL_TAC "rD") THEN
      USE_THEN "Xch" (MP_TAC o SPEC `r:A`) THEN
      ANTS_TAC THENL [USE_THEN "rD" ACCEPT_TAC; DISCH_THEN SUBST1_TAC] THEN
      USE_THEN "X'ch" (MP_TAC o SPEC `r:A`) THEN
      ANTS_TAC THENL [USE_THEN "rD" ACCEPT_TAC; DISCH_THEN SUBST1_TAC] THEN
      REFL_TAC];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `c:A` (CONJUNCTS_THEN2 (LABEL_TAC "cD")
      (LABEL_TAC "cp"))) THEN
  EXISTS_TAC `c:A` THEN CONJ_TAC THENL [USE_THEN "cD" ACCEPT_TAC; ALL_TAC] THEN
  X_GEN_TAC `x:A` THEN DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "xD")
      (LABEL_TAC "xs")) THEN
  USE_THEN "Xex" (MP_TAC o SPEC `x:A`) THEN
  ANTS_TAC THENL [USE_THEN "xD" ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `X:A` (CONJUNCTS_THEN2 (LABEL_TAC "XD")
      (LABEL_TAC "Xch"))) THEN
  SUBGOAL_THEN `(E:A->A->bool) X FF` (LABEL_TAC "XF") THENL
   [USE_THEN "FFch" (MP_TAC o SPEC `X:A`) THEN
    ANTS_TAC THENL [USE_THEN "XD" ACCEPT_TAC; DISCH_THEN SUBST1_TAC] THEN
    EXISTS_TAC `x:A` THEN REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  USE_THEN "cp" (MP_TAC o SPEC `X:A`) THEN
  ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `q:A` (CONJUNCTS_THEN2 (LABEL_TAC "qD")
    (CONJUNCTS_THEN2 (LABEL_TAC "qX") (CONJUNCTS_THEN2 (LABEL_TAC "qc")
        (LABEL_TAC "quq"))))) THEN
  USE_THEN "Xch" (MP_TAC o SPEC `q:A`) THEN
  ANTS_TAC THENL [USE_THEN "qD" ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> USE_THEN "qX" (MP_TAC o EQ_MP th)) THEN
  DISCH_THEN(X_CHOOSE_THEN `z:A` (CONJUNCTS_THEN2 (LABEL_TAC "zD")
    (CONJUNCTS_THEN2 (LABEL_TAC "zx") (LABEL_TAC "opq")))) THEN
  EXISTS_TAC `z:A` THEN REPEAT CONJ_TAC THENL
   [USE_THEN "zD" ACCEPT_TAC;
    USE_THEN "zx" ACCEPT_TAC;
    EXISTS_TAC `q:A` THEN REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    X_GEN_TAC `z':A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "z'D")
               (CONJUNCTS_THEN2 (LABEL_TAC "z'x")
      (X_CHOOSE_THEN `p':A` (CONJUNCTS_THEN2 (LABEL_TAC "p'D")
        (CONJUNCTS_THEN2 (LABEL_TAC "opp'") (LABEL_TAC "p'c")))))) THEN
    SUBGOAL_THEN `(E:A->A->bool) p' X` (LABEL_TAC "p'X") THENL
     [USE_THEN "Xch" (MP_TAC o SPEC `p':A`) THEN
      ANTS_TAC THENL [USE_THEN "p'D" ACCEPT_TAC; DISCH_THEN SUBST1_TAC] THEN
      EXISTS_TAC `z':A` THEN REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `p':A = q` SUBST_ALL_TAC THENL
     [USE_THEN "quq" MATCH_MP_TAC THEN REPEAT CONJ_TAC THEN
      FIRST_ASSUM ACCEPT_TAC;
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`x:A`;`z':A`;`x:A`;`z:A`;`q:A`]
           EOPAIR_INJ) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN(ACCEPT_TAC o CONJUNCT2)]]);;

(* ===================================================================== *)
(* S6-B : W1_UNCOUNTABLE (no countable set covers w1) and the            *)
(* transposition (a a') of w1 as an internal permutation.                 *)
(* ===================================================================== *)
let W1_UNCOUNTABLE = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X c.
     hsbundle D E w1 om tw ii ci P leqp B inclB onebee X /\
     c IN D /\ (?n. n IN D /\ E n w1 /\ ?f. ebij D E f n c)
     ==> ?x. x IN D /\ E x w1 /\ ~(E x c)`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "hsb")
             (CONJUNCTS_THEN2 (LABEL_TAC "cD") (LABEL_TAC "cnt"))) THEN
  USE_THEN "hsb" (fun th -> let cs = CONJUNCTS(REWRITE_RULE[hsbundle] th)
                            and cf = CONJUNCTS(MATCH_MP HSB_FACTS th) in
    LABEL_TAC "modl" (el 0 cs) THEN LABEL_TAC "eom" (el 2 cs) THEN
        LABEL_TAC "w1D" (el 3 cs) THEN
    LABEL_TAC "w1card" (el 4 cs) THEN LABEL_TAC "omw1" (el 5 cs) THEN
        LABEL_TAC "omD" (el 0 cf)) THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) om` (LABEL_TAC "omord") THENL
   [MATCH_MP_TAC EOMEGA_ORDINAL THEN CONJ_TAC THEN
    FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `~(!x:A. x IN D /\ (E:A->A->bool) x w1 ==> E x c)` MP_TAC THENL
   [DISCH_THEN(LABEL_TAC "cov") THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;`ii:A`;
                  `ci:A`;`P:A`;`leqp:A`;
                  `B:A`;`inclB:A`;`onebee:A`;`X:A`;`c:A`] CSUPPORT_TO_OM) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `k:A` (LABEL_TAC "kinj")) THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`k:A`;`c:A`;`om:A`;`w1:A`;`om:A`]
           EINJ_RESTRICT_DOM) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      FIRST [USE_THEN "kinj" (ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[einj]);
             MAP_EVERY X_GEN_TAC [`t:A`;`u:A`] THEN STRIP_TAC THEN
             USE_THEN "kinj" (MP_TAC o SPECL [`t:A`;`u:A`] o CONJUNCT1 o
                              CONJUNCT2 o REWRITE_RULE[einj]) THEN
             ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                             DISCH_THEN(ACCEPT_TAC o CONJUNCT2)]];
      ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `e:A` (LABEL_TAC "einj")) THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`om:A`;`w1:A`]
           ECARD_NO_INJ_DOWN) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    REWRITE_TAC[] THEN EXISTS_TAC `e:A` THEN USE_THEN "einj" ACCEPT_TAC;
    MESON_TAC[]]);;

let TRANSPOSITION_EXISTS = prove
 (`!D (E:A->A->bool) w a a'.
     model D E ZF_AX /\ w IN D /\ a IN D /\ a' IN D /\ E a w /\ E a' w
     ==> ?s. eperm D E w s /\
             (!x y. x IN D /\ y IN D
                    ==> (eapply D E s x y <=>
                         E x w /\ ((x = a /\ y = a') \/ (x = a' /\ y = a) \/
                                   (~(x = a) /\ ~(x = a') /\ y = x))))`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
             (CONJUNCTS_THEN2 (LABEL_TAC "wD")
    (CONJUNCTS_THEN2 (LABEL_TAC "aD") (CONJUNCTS_THEN2 (LABEL_TAC "a'D")
      (CONJUNCTS_THEN2 (LABEL_TAC "aw") (LABEL_TAC "a'w")))))) THEN
  USE_THEN "modl" (MP_TAC o MATCH_MP MODEL_NONEMPTY) THEN
  DISCH_THEN(X_CHOOSE_THEN `v0:num->A` (LABEL_TAC "v0") o MATCH_MP
             VALUATION_EXISTS) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`w:A`] ECROSS_EXISTS) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ww:A` (LABEL_TAC "ww")) THEN
  SUBGOAL_THEN `(ww:A) IN D` (LABEL_TAC "wwD") THENL
   [USE_THEN "ww" (ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[ecross]); ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((4 |-> (a':A)) ((3 |-> (a:A)) (v0:num->A)))`
      (LABEL_TAC "vv") THENL
   [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC) THEN
    FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
   `!p:A. p IN D
          ==> (holds D (E:A->A->bool) ((0 |-> p)
              ((4 |-> (a':A)) ((3 |-> (a:A)) (v0:num->A))))
                 (?? 1 (?? 2 (opair_form 1 2 0 &&
                    (((Eq 1 3) && (Eq 2 4)) ||
                     (((Eq 1 4) && (Eq 2 3)) ||
                      ((Not (Eq 1 3)) && ((Not (Eq 1 4)) && (Eq 2 1)))))))) <=>
               ?x. x IN D /\ ?y. y IN D /\ eopair D E x y p /\
