(* ===================================================================== *)
(* S6-C2a : stage bookkeeping + the real-name sets.  FULLNAME_IN_STAGE: the *)
(* full name over dd SUBSET W_fa lies in W_(fa+1) (EFULLNAME_BNAME with the *)
(* stage explicit).  NB_RS: RS_e = { r_a : a IN w1, a NOT IN e } as a set.   *)
(* ===================================================================== *)
let FULLNAME_IN_STAGE = prove
 (`!D (E:A->A->bool) B leq onebee dd fa fy sa ysa cn.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      onebee IN D /\ E onebee B /\ dd IN D /\
      fa IN D /\ fy IN D /\ eordinal D E fa /\ ebnstage D E B fa fy /\
      (!f. f IN D /\ E f dd ==> E f fy) /\
      esuc D E fa sa /\ ysa IN D /\ ebnstage D E B sa ysa /\
      cn IN D /\ eisfun D E cn /\
      (!z. z IN D
           ==> (E z cn <=>
                ?s. s IN D /\ E s dd /\
                    eopair D (E:A->A->bool) s onebee z))
      ==> E cn ysa`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(sa:A) IN D /\ eordinal D (E:A->A->bool) sa /\
      (E:A->A->bool) fa sa`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_IN; EORDINAL_ESUC; ESUC_MEMBER]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`sa:A`;`ysa:A`]
         EBNSTAGE_CHAR) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `w1:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 (LABEL_TAC "w1ch") ASSUME_TAC))) THEN
  SUBGOAL_THEN `!u:A. u IN D /\ (E:A->A->bool) u fy
      ==> E u w1` (LABEL_TAC "Ysub") THENL
   [X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    USE_THEN "w1ch" (MP_TAC o SPEC `u:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MAP_EVERY EXISTS_TAC [`fa:A`;`fy:A`] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`B:A`] ECROSS_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `cr:A` (LABEL_TAC "cr")) THEN
  SUBGOAL_THEN `(cr:A) IN D` ASSUME_TAC THENL
   [USE_THEN "cr" (MP_TAC o REWRITE_RULE[ecross]) THEN SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) cn cr` ASSUME_TAC THENL
   [REWRITE_TAC[esubset] THEN X_GEN_TAC `z:A` THEN STRIP_TAC THEN
    USE_THEN "cr" (MP_TAC o SPEC `z:A` o CONJUNCT2 o REWRITE_RULE[ecross]) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    SUBGOAL_THEN
     `?s. s IN D /\ E s dd /\ eopair D (E:A->A->bool) s onebee z`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) s fy` ASSUME_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) s w1` ASSUME_TAC THENL
     [USE_THEN "Ysub" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`s:A`;`onebee:A`] THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `ebnmem D (E:A->A->bool) B w1 cn` ASSUME_TAC THENL
   [REWRITE_TAC[ebnmem] THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `cr:A` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) cn ysa` ASSUME_TAC THENL
   [UNDISCH_TAC `ebnfuns D (E:A->A->bool) B w1 ysa` THEN
    REWRITE_TAC[ebnfuns] THEN
    DISCH_THEN(MP_TAC o SPEC `cn:A` o CONJUNCT2) THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
  FIRST_ASSUM ACCEPT_TAC);;

