   (CONJUNCTS_THEN2 (LABEL_TAC "balg") (LABEL_TAC "pord")) THENL
   [USE_THEN "cba" (fun th -> let b = MATCH_MP ECBA_IMP_BALG th in
      ACCEPT_TAC(CONJ b (MATCH_MP EBALG_IMP_PORDER b)));
    ALL_TAC] THEN
  USE_THEN "rfapp" (MP_TAC o SPECL [`a:A`;`r:A`]) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (LABEL_TAC "er")) THEN
  USE_THEN "rfapp" (MP_TAC o SPECL [`a:A`;`r':A`]) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (LABEL_TAC "er'")) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`om:A`;`onebee:A`;`embf:A`;`onetw:A`;
                `a:A`;`r:A`;`r':A`] NB_REAL_UNIQUE) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                  DISCH_THEN ACCEPT_TAC]);;

let NB_RS = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X embf
  onetw ztw realfn e.
     nbundle D E w1 om tw ii ci P leqp B inclB onebee X embf onetw ztw
         realfn /\ e IN D
     ==> ?RS. RS IN D /\
              !w. w IN D ==> (E w RS <=> ?u. u IN D /\ E u w1 /\ ~(E u e) /\
                              eapply D E realfn u w)`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "nb") (LABEL_TAC "eD")) THEN
  USE_THEN "nb" (fun th -> let cs = CONJUNCTS(REWRITE_RULE[nbundle] th) in
    LABEL_TAC "hsb" (el 0 cs) THEN LABEL_TAC "emb" (el 1 cs) THEN
    LABEL_TAC "otD" (el 2 cs) THEN LABEL_TAC "ottw" (el 3 cs) THEN
    LABEL_TAC "ztD" (el 4 cs) THEN LABEL_TAC "zttw" (el 5 cs) THEN
        LABEL_TAC "otzt" (el 6 cs) THEN
    LABEL_TAC "rfD" (el 7 cs) THEN LABEL_TAC "rftot" (el 8 cs) THEN
        LABEL_TAC "rfapp" (el 9 cs)) THEN
  USE_THEN "emb" (fun th -> let cs = CONJUNCTS(REWRITE_RULE[eembf] th) in
    LABEL_TAC "embfD" (el 0 cs) THEN LABEL_TAC "efun" (el 1 cs) THEN
        LABEL_TAC "gc" (el 2 cs) THEN
    LABEL_TAC "etot" (el 3 cs) THEN LABEL_TAC "evalB" (el 4 cs)) THEN
  USE_THEN "hsb" (MP_TAC o MATCH_MP HSB_CBA) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "cba")
             (CONJUNCTS_THEN2 (LABEL_TAC "inclD") (LABEL_TAC "leqpD"))) THEN
  USE_THEN "hsb" (MP_TAC o REWRITE_RULE[hsbundle]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
             (CONJUNCTS_THEN2 (LABEL_TAC "vl")
              (CONJUNCTS_THEN2 (LABEL_TAC "eom")
               (CONJUNCTS_THEN2 (LABEL_TAC "w1D")
                (CONJUNCTS_THEN2 (LABEL_TAC "w1card")
                 (CONJUNCTS_THEN2 (LABEL_TAC "omw1e")
                  (CONJUNCTS_THEN2 (LABEL_TAC "w1min")
                   (CONJUNCTS_THEN2 (LABEL_TAC "cr1")
                    (CONJUNCTS_THEN2 (LABEL_TAC "cr2")
                     (CONJUNCTS_THEN2 (LABEL_TAC "ftw")
                      (CONJUNCTS_THEN2 (LABEL_TAC "coh")
                       (CONJUNCTS_THEN2 (LABEL_TAC "leq")
                        (CONJUNCTS_THEN2 (LABEL_TAC "ros")
                         (CONJUNCTS_THEN2 (LABEL_TAC "inc")
                          (CONJUNCTS_THEN2 (LABEL_TAC "porder")
      (CONJUNCTS_THEN2 (LABEL_TAC "top")
       (CONJUNCTS_THEN2 (LABEL_TAC "oneD")
        (CONJUNCTS_THEN2 (LABEL_TAC "BD")
         (CONJUNCTS_THEN2 (LABEL_TAC "oneB")
          (CONJUNCTS_THEN2 (LABEL_TAC "XD")
           (CONJUNCTS_THEN2 (LABEL_TAC "ciX")
            (LABEL_TAC "PX")))))))))))))))))))))) THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B inclB /\ eporder D E B inclB`
   (CONJUNCTS_THEN2 (LABEL_TAC "balg") (LABEL_TAC "pord")) THENL
   [USE_THEN "cba" (fun th -> let b = MATCH_MP ECBA_IMP_BALG th in
      ACCEPT_TAC(CONJ b (MATCH_MP EBALG_IMP_PORDER b)));
    ALL_TAC] THEN
  USE_THEN "modl" (MP_TAC o MATCH_MP MODEL_NONEMPTY) THEN
  DISCH_THEN(X_CHOOSE_THEN `v0:num->A` (LABEL_TAC "v0") o MATCH_MP
             VALUATION_EXISTS) THEN
  SUBGOAL_THEN `valuation D ((6 |-> (e:A)) ((5 |-> (realfn:A)) (v0:num->A)))`
      (LABEL_TAC "vv") THENL
   [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC) THEN
    FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
   `!u w:A. u IN D /\ w IN D
            ==> (holds D (E:A->A->bool) ((2 |-> w)
                ((1 |-> u) ((6 |-> (e:A)) ((5 |-> (realfn:A)) (v0:num->A)))))
                   (Not (1 %% 6) && apply_form 5 1 2) <=>
                 ~(E u e) /\ eapply D E realfn u w)`
   (LABEL_TAC "sem") THENL
   [MAP_EVERY X_GEN_TAC [`u:A`;`w:A`] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "uD") (LABEL_TAC "wD")) THEN
    SUBGOAL_THEN `valuation D ((2 |-> (w:A))
        ((1 |-> (u:A)) ((6 |-> (e:A)) ((5 |-> (realfn:A)) (v0:num->A)))))`
     (LABEL_TAC "vuw") THENL
     [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC) THEN
      FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    USE_THEN "vuw" (fun vth -> SIMP_TAC[vth; HOLDS_AND; HOLDS_NOT;
        HOLDS_APPLY_FORM]) THEN
    REWRITE_TAC[holds; VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`] ZF_REPLACEMENT) THEN
  ANTS_TAC THENL [USE_THEN "modl" ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL [`Not (1 %% 6) && apply_form 5 1 2`; `1`; `2`;
    `(6 |-> (e:A)) ((5 |-> (realfn:A)) (v0:num->A))`; `w1:A`]) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN TRY ARITH_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    X_GEN_TAC `u:A` THEN DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "uD")
        (LABEL_TAC "uw1")) THEN
    USE_THEN "rftot" (MP_TAC o SPEC `u:A`) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `r:A` (CONJUNCTS_THEN2 (LABEL_TAC "ur")
        (LABEL_TAC "er"))) THEN
    SUBGOAL_THEN `(r:A) IN D` (LABEL_TAC "rD") THENL
     [USE_THEN "er" (ACCEPT_TAC o CONJUNCT1 o
                     REWRITE_RULE[ereal]); ALL_TAC] THEN
    EXISTS_TAC `r:A` THEN CONJ_TAC THENL
        [USE_THEN "rD" ACCEPT_TAC; ALL_TAC] THEN
    X_GEN_TAC `w':A` THEN DISCH_THEN(CONJUNCTS_THEN2
        (LABEL_TAC "w'D") MP_TAC) THEN
    USE_THEN "sem" (MP_TAC o SPECL [`u:A`;`w':A`]) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN SUBST1_TAC] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (LABEL_TAC "uw'")) THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;`ii:A`;`ci:A`;
                  `P:A`;`leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`embf:A`;
        `onetw:A`;`ztw:A`;`realfn:A`;`u:A`;`w':A`;`r:A`] NB_RFUNC) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `RS:A` (CONJUNCTS_THEN2 (LABEL_TAC "RSD")
      (LABEL_TAC "RSch0"))) THEN
  EXISTS_TAC `RS:A` THEN CONJ_TAC THENL
      [USE_THEN "RSD" ACCEPT_TAC; ALL_TAC] THEN
  X_GEN_TAC `w:A` THEN DISCH_THEN(LABEL_TAC "wD") THEN
  USE_THEN "RSch0" (MP_TAC o SPEC `w:A`) THEN
  ANTS_TAC THENL [USE_THEN "wD" ACCEPT_TAC; DISCH_THEN SUBST1_TAC] THEN
  MATCH_MP_TAC(MESON[] `(!u:A. u IN D ==> (P u <=> Q u))
                        ==> ((?u. u IN D /\ R u /\ P u) <=>
                             (?u. u IN D /\ R u /\ Q u))`) THEN
  X_GEN_TAC `u:A` THEN DISCH_THEN(LABEL_TAC "uD") THEN
  USE_THEN "sem" (MP_TAC o SPECL [`u:A`;`w:A`]) THEN
  ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                  DISCH_THEN ACCEPT_TAC]);;

(* ===================================================================== *)
(* S6-C2b : HS_FULLNAME_E (the full name over Z is HS with support ee if Z *)
(* is invariant under every autN whose permutation fixes ee); RS_INV (the   *)
(* real-name set RS_e is invariant under permutations fixing e).            *)
(* ===================================================================== *)
let HS_FULLNAME_E = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X ee Z cn.
     hsbundle D E w1 om tw ii ci P leqp B inclB onebee X /\
     ee IN D /\ (?n. n IN D /\ E n w1 /\ ?f. ebij D E f n ee) /\
         esubset D E ee w1 /\
     Z IN D /\ (!s. s IN D /\ E s Z ==> hsname D E B w1 X s) /\
     (!sg muci muP autB. sg IN D /\ eperm D E w1 sg /\ efixes D E sg ee /\
                         pbundle D E ci P leqp B inclB sg muci muP autB
                         ==> (!s s'. s IN D /\ E s Z /\ eautn D E B autB s s'
                              ==> E s' Z) /\ (!s'. s' IN D /\ E s' Z
                                              ==> ?s. s IN D /\ E s Z /\
                             eautn D E B autB s s')) /\
     cn IN D /\ eisfun D E cn /\ (!z. z IN D
         ==> (E z cn <=> ?s. s IN D /\ E s Z /\
              eopair D (E:A->A->bool) s onebee z))
     ==> hsname D E B w1 X cn`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "hsb")
             (CONJUNCTS_THEN2 (LABEL_TAC "exD")
              (CONJUNCTS_THEN2 (LABEL_TAC "exfin")
               (CONJUNCTS_THEN2 (LABEL_TAC "exsub")
                (CONJUNCTS_THEN2 (LABEL_TAC "ZD")
                 (CONJUNCTS_THEN2 (LABEL_TAC "Zhs")
                  (CONJUNCTS_THEN2 (LABEL_TAC "inv")
                   (CONJUNCTS_THEN2 (LABEL_TAC "cnD")
                    (CONJUNCTS_THEN2 (LABEL_TAC "isfun")
                     (LABEL_TAC "cnch")))))))))) THEN
  USE_THEN "hsb" (MP_TAC o MATCH_MP HSB_CBA) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "cba")
             (CONJUNCTS_THEN2 (LABEL_TAC "inclD") (LABEL_TAC "leqpD"))) THEN
  USE_THEN "hsb" (MP_TAC o REWRITE_RULE[hsbundle]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
             (CONJUNCTS_THEN2 (LABEL_TAC "vl")
              (CONJUNCTS_THEN2 (LABEL_TAC "eom")
               (CONJUNCTS_THEN2 (LABEL_TAC "w1D")
                (CONJUNCTS_THEN2 (LABEL_TAC "w1card")
                 (CONJUNCTS_THEN2 (LABEL_TAC "omw1e")
                  (CONJUNCTS_THEN2 (LABEL_TAC "w1min")
                   (CONJUNCTS_THEN2 (LABEL_TAC "cr1")
                    (CONJUNCTS_THEN2 (LABEL_TAC "cr2")
                     (CONJUNCTS_THEN2 (LABEL_TAC "ftw")
                      (CONJUNCTS_THEN2 (LABEL_TAC "coh")
                       (CONJUNCTS_THEN2 (LABEL_TAC "leq")
                        (CONJUNCTS_THEN2 (LABEL_TAC "ros")
                         (CONJUNCTS_THEN2 (LABEL_TAC "inc")
                          (CONJUNCTS_THEN2 (LABEL_TAC "porder")
      (CONJUNCTS_THEN2 (LABEL_TAC "top")
       (CONJUNCTS_THEN2 (LABEL_TAC "oneD")
        (CONJUNCTS_THEN2 (LABEL_TAC "BD")
         (CONJUNCTS_THEN2 (LABEL_TAC "oneB")
          (CONJUNCTS_THEN2 (LABEL_TAC "XD")
           (CONJUNCTS_THEN2 (LABEL_TAC "ciX")
            (LABEL_TAC "PX")))))))))))))))))))))) THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B inclB /\ eporder D E B inclB`
   (CONJUNCTS_THEN2 (LABEL_TAC "balg") (LABEL_TAC "pord")) THENL
   [USE_THEN "cba" (fun th -> let b = MATCH_MP ECBA_IMP_BALG th in
      ACCEPT_TAC(CONJ b (MATCH_MP EBALG_IMP_PORDER b)));
    ALL_TAC] THEN
  SUBGOAL_THEN `!z. z IN D /\ (E:A->A->bool) z Z
      ==> bname D E B z` (LABEL_TAC "Zbn") THENL
   [X_GEN_TAC `z:A` THEN DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "zD")
       (LABEL_TAC "zZ")) THEN
    MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    USE_THEN "Zhs" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; DISCH_TAC] THEN
    REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`Z:A`] BNAME_BOUND) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `fa:A` (X_CHOOSE_THEN `fy:A`
      (CONJUNCTS_THEN2 (LABEL_TAC "faD")
       (CONJUNCTS_THEN2 (LABEL_TAC "fyD")
        (CONJUNCTS_THEN2 (LABEL_TAC "faord")
         (CONJUNCTS_THEN2 (LABEL_TAC "bnfafy") (LABEL_TAC "Zfy"))))))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`onebee:A`;`Z:A`;
                `fa:A`;`fy:A`;`cn:A`] EFULLNAME_BNAME) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                  DISCH_THEN(LABEL_TAC "bncn")] THEN
  SUBGOAL_THEN `ehssym D (E:A->A->bool) B w1 X cn` (LABEL_TAC "symcn") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;`ii:A`;`ci:A`;
                  `P:A`;`leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`cn:A`;`ee:A`]
       EHSSYM_INTRO) THEN
    ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    X_GEN_TAC `sg:A` THEN DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "sgD")
      (CONJUNCTS_THEN2 (LABEL_TAC "sgperm") (LABEL_TAC "sgfix"))) THEN
    MAP_EVERY X_GEN_TAC [`muci:A`;`muP:A`;`autB:A`] THEN
    DISCH_THEN(fun th ->
      SUBGOAL_THEN `pbundle D (E:A->A->bool) ci P leqp B inclB sg muci muP autB`
          (LABEL_TAC "pb")
      THENL [REWRITE_TAC[pbundle] THEN ACCEPT_TAC th; ALL_TAC]) THEN
    USE_THEN "inv" (MP_TAC o SPECL [`sg:A`;`muci:A`;`muP:A`;`autB:A`]) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "invf") (LABEL_TAC "invb")) THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;`ii:A`;`ci:A`;
                  `P:A`;`leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`sg:A`;
        `muci:A`;`muP:A`;`autB:A`;`Z:A`;`cn:A`] FULLNAME_SYM) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;`Z:A`]
         HSNAME_BOUND) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `c0:A` (X_CHOOSE_THEN `yc0:A`
      (CONJUNCTS_THEN2 (LABEL_TAC "c0D")
       (CONJUNCTS_THEN2 (LABEL_TAC "yc0D")
        (CONJUNCTS_THEN2 (LABEL_TAC "c0ord")
         (CONJUNCTS_THEN2 (LABEL_TAC "hsc0") (LABEL_TAC "Zyc0"))))))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`c0:A`] ESUC_EXISTS) THEN
  ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `a2:A` (LABEL_TAC "asuc")) THEN
  SUBGOAL_THEN `(a2:A) IN D` (LABEL_TAC "a2D") THENL
   [USE_THEN "asuc" (ACCEPT_TAC o MATCH_MP ESUC_IN); ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) a2` (LABEL_TAC "a2ord") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`c0:A`;`a2:A`] EORDINAL_ESUC) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) c0 a2` (LABEL_TAC "c0a2") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`c0:A`;`a2:A`] ESUC_MEMBER) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;`a2:A`]
         HSSTAGE_EXISTS) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `y2:A` (CONJUNCTS_THEN2 (LABEL_TAC "y2D")
      (LABEL_TAC "hsa2y2"))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;`cn:A`;`a2:A`;
                `y2:A`] HSSTAGE_INTRO) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    X_GEN_TAC `z:A` THEN DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "zD")
        (LABEL_TAC "zcn")) THEN
    USE_THEN "cnch" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [USE_THEN "zD" ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "zcn" (MP_TAC o EQ_MP th)) THEN
    DISCH_THEN(X_CHOOSE_THEN `s0:A` (CONJUNCTS_THEN2 (LABEL_TAC "s0D")
      (CONJUNCTS_THEN2 (LABEL_TAC "s0Z") (LABEL_TAC "ops0")))) THEN
    SUBGOAL_THEN `(E:A->A->bool) s0 yc0` (LABEL_TAC "s0yc0") THENL
     [USE_THEN "Zyc0" MATCH_MP_TAC THEN CONJ_TAC THEN
      FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`s0:A`;`onebee:A`] THEN REPEAT CONJ_TAC THEN
        TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    MAP_EVERY EXISTS_TAC [`c0:A`;`yc0:A`] THEN REPEAT CONJ_TAC THEN
        FIRST_ASSUM ACCEPT_TAC;
    DISCH_THEN(LABEL_TAC "cny2")] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;`a2:A`;`y2:A`;
                `cn:A`] HSNAME_STAGE) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                  DISCH_THEN ACCEPT_TAC]);;

let RS_INV = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X embf onetw ztw
  realfn e RS sg muci muP autB.
     nbundle D E w1 om tw ii ci P leqp B inclB onebee X embf onetw ztw realfn /\
         e IN D /\ RS IN D /\
     (!w. w IN D ==> (E w RS <=> ?u. u IN D /\ E u w1 /\ ~(E u e) /\
                      eapply D E realfn u w)) /\
     sg IN D /\ eperm D E w1 sg /\ efixes D E sg e /\
     pbundle D E ci P leqp B inclB sg muci muP autB
     ==> (!s s'. s IN D /\ E s RS /\ eautn D E B autB s s' ==> E s' RS) /\
         (!s'. s' IN D /\ E s' RS ==> ?s. s IN D /\ E s RS /\
          eautn D E B autB s s')`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "nb")
