   [MAP_EVERY X_GEN_TAC [`s:A`;`s':A`] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "sD")
               (CONJUNCTS_THEN2 (LABEL_TAC "sRS") (LABEL_TAC "ass'"))) THEN
    USE_THEN "RSch" (MP_TAC o SPEC `s:A`) THEN
