    DISCH_THEN(X_CHOOSE_THEN `s2:A` (CONJUNCTS_THEN2 (LABEL_TAC "u's2")
        (LABEL_TAC "ers2"))) THEN
    SUBGOAL_THEN `(s2:A) IN D` (LABEL_TAC "s2D") THENL
     [USE_THEN "ers2" (ACCEPT_TAC o CONJUNCT1 o
                       REWRITE_RULE[ereal]); ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;`ii:A`;`ci:A`;
                  `P:A`;`leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`embf:A`;
        `onetw:A`;`ztw:A`;`realfn:A`;`sg:A`;`muci:A`;`muP:A`;`autB:A`;`u:A`;
        `u':A`;`s:A`;`s2:A`] NB_REAL_AUT) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN(LABEL_TAC "ass2")] THEN
    SUBGOAL_THEN `s':A = s2` SUBST_ALL_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`autB:A`;`s:A`;`s':A`;
                    `s2:A`] AUTN_SV) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    USE_THEN "RSch" (MP_TAC o SPEC `s2:A`) THEN
    ANTS_TAC THENL [USE_THEN "s2D" ACCEPT_TAC; DISCH_THEN SUBST1_TAC] THEN
    EXISTS_TAC `u':A` THEN REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    X_GEN_TAC `s':A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "s'D") (LABEL_TAC "s'RS")) THEN
    USE_THEN "RSch" (MP_TAC o SPEC `s':A`) THEN
    ANTS_TAC THENL [USE_THEN "s'D" ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "s'RS" (MP_TAC o EQ_MP th)) THEN
    DISCH_THEN(X_CHOOSE_THEN `u':A` (CONJUNCTS_THEN2 (LABEL_TAC "u'D")
        (CONJUNCTS_THEN2 (LABEL_TAC "u'w1")
      (CONJUNCTS_THEN2 (LABEL_TAC "u'e") (LABEL_TAC "u's'"))))) THEN
    USE_THEN "sgsur" (MP_TAC o SPEC `u':A`) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `u:A` (CONJUNCTS_THEN2 (LABEL_TAC "uD")
        (CONJUNCTS_THEN2 (LABEL_TAC "uw1") (LABEL_TAC "sguu'")))) THEN
    SUBGOAL_THEN `~((E:A->A->bool) u e)` (LABEL_TAC "ue") THENL
     [DISCH_THEN(LABEL_TAC "uine") THEN
      USE_THEN "sgfix" (MP_TAC o SPEC `u:A` o REWRITE_RULE[efixes]) THEN
      ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN(LABEL_TAC "sguu")] THEN
      SUBGOAL_THEN `u':A = u` SUBST_ALL_TAC THENL
       [USE_THEN "sgsv" (MP_TAC o SPECL [`u:A`;`u':A`;`u:A`]) THEN
        ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                        DISCH_THEN ACCEPT_TAC];
        ALL_TAC] THEN
      USE_THEN "u'e" (fun th -> USE_THEN "uine"
                      (ACCEPT_TAC o EQ_MP (EQF_INTRO th)));
      ALL_TAC] THEN
    USE_THEN "rfapp" (MP_TAC o SPECL [`u':A`;`s':A`]) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (LABEL_TAC "ers'")) THEN
    USE_THEN "rftot" (MP_TAC o SPEC `u:A`) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `s:A` (CONJUNCTS_THEN2 (LABEL_TAC "us")
        (LABEL_TAC "ers"))) THEN
    SUBGOAL_THEN `(s:A) IN D` (LABEL_TAC "sD") THENL
     [USE_THEN "ers" (ACCEPT_TAC o CONJUNCT1 o
                      REWRITE_RULE[ereal]); ALL_TAC] THEN
    EXISTS_TAC `s:A` THEN REPEAT CONJ_TAC THENL
     [USE_THEN "sD" ACCEPT_TAC;
      USE_THEN "RSch" (MP_TAC o SPEC `s:A`) THEN
      ANTS_TAC THENL [USE_THEN "sD" ACCEPT_TAC; DISCH_THEN SUBST1_TAC] THEN
      EXISTS_TAC `u:A` THEN REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;`ii:A`;
                    `ci:A`;`P:A`;`leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;
          `embf:A`;`onetw:A`;`ztw:A`;`realfn:A`;`sg:A`;`muci:A`;`muP:A`;
          `autB:A`;`u:A`;`u':A`;`s:A`;`s':A`] NB_REAL_AUT) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN ACCEPT_TAC]]]);;

(* ===================================================================== *)
(* S6-C3 : the family name S.  NB_REALSTAGE: one bname stage holds every   *)
(* real name.  ZSET: ZZ = { z IN W : z HS with a member <t,top> }.          *)
(* ZTOP_INV: ZZ (W a bname stage) is mapped onto itself by every autN.      *)
(* ===================================================================== *)
let NB_REALSTAGE = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X embf
  onetw ztw realfn.
     nbundle D E w1 om tw ii ci P leqp B inclB onebee X embf onetw ztw realfn
     ==> ?fa fy. fa IN D /\ fy IN D /\ eordinal D E fa /\
         ebnstage D E B fa fy /\
                 (!a r. a IN D /\ r IN D /\ eapply D E realfn a r ==> E r fy)`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "nb") THEN
  USE_THEN "nb" (fun th -> let cs = CONJUNCTS(REWRITE_RULE[nbundle] th) in
    LABEL_TAC "hsb" (el 0 cs) THEN LABEL_TAC "emb" (el 1 cs) THEN
    LABEL_TAC "otD" (el 2 cs) THEN LABEL_TAC "ottw" (el 3 cs) THEN
    LABEL_TAC "ztD" (el 4 cs) THEN LABEL_TAC "zttw" (el 5 cs) THEN
        LABEL_TAC "otzt" (el 6 cs) THEN
    LABEL_TAC "rfD" (el 7 cs) THEN LABEL_TAC "rftot" (el 8 cs) THEN
        LABEL_TAC "rfapp" (el 9 cs)) THEN
  USE_THEN "emb" (fun th -> let cs = CONJUNCTS(REWRITE_RULE[eembf] th) in
    LABEL_TAC "embfD" (el 0 cs) THEN LABEL_TAC "efun" (el 1 cs) THEN
        LABEL_TAC "gc" (el 2 cs) THEN
    LABEL_TAC "etot" (el 3 cs) THEN LABEL_TAC "evalB" (el 4 cs)) THEN
  USE_THEN "hsb" (MP_TAC o MATCH_MP HSB_CBA) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "cba")
             (CONJUNCTS_THEN2 (LABEL_TAC "inclD") (LABEL_TAC "leqpD"))) THEN
  USE_THEN "hsb" (MP_TAC o REWRITE_RULE[hsbundle]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
             (CONJUNCTS_THEN2 (LABEL_TAC "vl")
              (CONJUNCTS_THEN2 (LABEL_TAC "eom")
               (CONJUNCTS_THEN2 (LABEL_TAC "w1D")
                (CONJUNCTS_THEN2 (LABEL_TAC "w1card")
                 (CONJUNCTS_THEN2 (LABEL_TAC "omw1e")
                  (CONJUNCTS_THEN2 (LABEL_TAC "w1min")
                   (CONJUNCTS_THEN2 (LABEL_TAC "cr1")
                    (CONJUNCTS_THEN2 (LABEL_TAC "cr2")
                     (CONJUNCTS_THEN2 (LABEL_TAC "ftw")
                      (CONJUNCTS_THEN2 (LABEL_TAC "coh")
                       (CONJUNCTS_THEN2 (LABEL_TAC "leq")
                        (CONJUNCTS_THEN2 (LABEL_TAC "ros")
                         (CONJUNCTS_THEN2 (LABEL_TAC "inc")
                          (CONJUNCTS_THEN2 (LABEL_TAC "porder")
      (CONJUNCTS_THEN2 (LABEL_TAC "top")
       (CONJUNCTS_THEN2 (LABEL_TAC "oneD")
        (CONJUNCTS_THEN2 (LABEL_TAC "BD")
         (CONJUNCTS_THEN2 (LABEL_TAC "oneB")
          (CONJUNCTS_THEN2 (LABEL_TAC "XD")
           (CONJUNCTS_THEN2 (LABEL_TAC "ciX")
            (LABEL_TAC "PX")))))))))))))))))))))) THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B inclB /\ eporder D E B inclB`
   (CONJUNCTS_THEN2 (LABEL_TAC "balg") (LABEL_TAC "pord")) THENL
   [USE_THEN "cba" (fun th -> let b = MATCH_MP ECBA_IMP_BALG th in
      ACCEPT_TAC(CONJ b (MATCH_MP EBALG_IMP_PORDER b)));
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;`ii:A`;`ci:A`;
                `P:A`;`leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`]
      CSUPPORT_EMPTY) THEN
  ANTS_TAC THENL [USE_THEN "hsb" ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `e0:A` (CONJUNCTS_THEN2 (LABEL_TAC "e0D")
      (CONJUNCTS_THEN2 (LABEL_TAC "e0emp") (K ALL_TAC)))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;`ii:A`;`ci:A`;
                `P:A`;`leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`embf:A`;
      `onetw:A`;`ztw:A`;`realfn:A`;`e0:A`] NB_RS) THEN
  ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `RAN:A` (CONJUNCTS_THEN2 (LABEL_TAC "RAND")
      (LABEL_TAC "RANch"))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`RAN:A`] BNAME_BOUND) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    X_GEN_TAC `z:A` THEN DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "zD")
        (LABEL_TAC "zR")) THEN
    USE_THEN "RANch" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [USE_THEN "zD" ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "zR" (MP_TAC o EQ_MP th)) THEN
    DISCH_THEN(X_CHOOSE_THEN `u:A` (CONJUNCTS_THEN2 (LABEL_TAC "uD")
        (CONJUNCTS_THEN2 (LABEL_TAC "uw1")
      (CONJUNCTS_THEN2 (K ALL_TAC) (LABEL_TAC "uz"))))) THEN
    USE_THEN "rfapp" (MP_TAC o SPECL [`u:A`;`z:A`]) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (LABEL_TAC "er")) THEN
    MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;`ii:A`;`ci:A`;
                  `P:A`;`leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`embf:A`;
        `onetw:A`;`ztw:A`;`realfn:A`;`u:A`;`z:A`] NB_REAL_HS) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; DISCH_TAC] THEN
    REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `fa:A` (X_CHOOSE_THEN `fy:A`
      (CONJUNCTS_THEN2 (LABEL_TAC "faD")
       (CONJUNCTS_THEN2 (LABEL_TAC "fyD")
        (CONJUNCTS_THEN2 (LABEL_TAC "faord")
         (CONJUNCTS_THEN2 (LABEL_TAC "bnst") (LABEL_TAC "RANfy"))))))) THEN
  MAP_EVERY EXISTS_TAC [`fa:A`;`fy:A`] THEN REPEAT CONJ_TAC THEN
      TRY(FIRST_ASSUM ACCEPT_TAC) THEN
  MAP_EVERY X_GEN_TAC [`a:A`;`r:A`] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "aD")
             (CONJUNCTS_THEN2 (LABEL_TAC "rD") (LABEL_TAC "ar"))) THEN
  USE_THEN "RANfy" MATCH_MP_TAC THEN CONJ_TAC THENL
      [USE_THEN "rD" ACCEPT_TAC; ALL_TAC] THEN
  USE_THEN "RANch" (MP_TAC o SPEC `r:A`) THEN
  ANTS_TAC THENL [USE_THEN "rD" ACCEPT_TAC; DISCH_THEN SUBST1_TAC] THEN
  EXISTS_TAC `a:A` THEN REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THENL
   [USE_THEN "rfapp" (MP_TAC o SPECL [`a:A`;`r:A`]) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN(ACCEPT_TAC o CONJUNCT1)];
    USE_THEN "e0emp" (MATCH_MP_TAC) THEN USE_THEN "aD" ACCEPT_TAC]);;

let ZSET = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X W.
     hsbundle D E w1 om tw ii ci P leqp B inclB onebee X /\ W IN D
     ==> ?Z. Z IN D /\ (!z. z IN D ==> (E z Z <=> E z W /\
         hsname D E B w1 X z /\
                ?t. t IN D /\ ?p. p IN D /\ E p z /\
                    eopair D (E:A->A->bool) t onebee p))`,
  REPEAT GEN_TAC THEN DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "hsb")
      (LABEL_TAC "WD")) THEN
  USE_THEN "hsb" (MP_TAC o MATCH_MP HSB_CBA) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "cba")
             (CONJUNCTS_THEN2 (LABEL_TAC "inclD") (LABEL_TAC "leqpD"))) THEN
  USE_THEN "hsb" (MP_TAC o REWRITE_RULE[hsbundle]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
             (CONJUNCTS_THEN2 (LABEL_TAC "vl")
              (CONJUNCTS_THEN2 (LABEL_TAC "eom")
               (CONJUNCTS_THEN2 (LABEL_TAC "w1D")
                (CONJUNCTS_THEN2 (LABEL_TAC "w1card")
                 (CONJUNCTS_THEN2 (LABEL_TAC "omw1e")
                  (CONJUNCTS_THEN2 (LABEL_TAC "w1min")
                   (CONJUNCTS_THEN2 (LABEL_TAC "cr1")
                    (CONJUNCTS_THEN2 (LABEL_TAC "cr2")
                     (CONJUNCTS_THEN2 (LABEL_TAC "ftw")
                      (CONJUNCTS_THEN2 (LABEL_TAC "coh")
                       (CONJUNCTS_THEN2 (LABEL_TAC "leq")
                        (CONJUNCTS_THEN2 (LABEL_TAC "ros")
                         (CONJUNCTS_THEN2 (LABEL_TAC "inc")
                          (CONJUNCTS_THEN2 (LABEL_TAC "porder")
      (CONJUNCTS_THEN2 (LABEL_TAC "top")
       (CONJUNCTS_THEN2 (LABEL_TAC "oneD")
        (CONJUNCTS_THEN2 (LABEL_TAC "BD")
         (CONJUNCTS_THEN2 (LABEL_TAC "oneB")
          (CONJUNCTS_THEN2 (LABEL_TAC "XD")
           (CONJUNCTS_THEN2 (LABEL_TAC "ciX")
