(* ===================================================================== *)
(* S6-C4 : the two names of the ~AC core.  NB_SHAT: Shat_e, the full name  *)
(* over RS_e = { r_a : a IN w1 \ e } (e countable): HS, fixed by autN for  *)
(* permutations fixing e, in the stage ysa, with a member <r_a,top>.        *)
(* NB_FAMILY: S, the full name over ZZ (HS members of ysa with a top        *)
(* member): HS and fixed by every autN.                                     *)
(* ===================================================================== *)
let NB_SHAT = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X embf onetw ztw
  realfn fa fy sa ysa e.
     nbundle D E w1 om tw ii ci P leqp B inclB onebee X embf onetw ztw realfn /\
     fa IN D /\ fy IN D /\ eordinal D E fa /\ ebnstage D E B fa fy /\
     (!a r. a IN D /\ r IN D /\ eapply D E realfn a r ==> E r fy) /\
     esuc D E fa sa /\ ysa IN D /\ ebnstage D E B sa ysa /\
     e IN D /\ (?n. n IN D /\ E n w1 /\ ?f. ebij D E f n e) /\ esubset D E e w1
     ==> ?RS Sh. RS IN D /\ (!w. w IN D
                             ==> (E w RS <=> ?u. u IN D /\ E u w1 /\ ~(E u e) /\
         eapply D E realfn u w)) /\
                 Sh IN D /\ eisfun D E Sh /\ (!s. s IN D /\ E s RS
                     ==> eapply D E Sh s onebee) /\
               (!z. z IN D ==> (E z Sh <=> ?s. s IN D /\ E s RS /\
                                eopair D (E:A->A->bool) s onebee z)) /\
                 hsname D E B w1 X Sh /\ E Sh ysa /\
                 (?t. t IN D /\ ?p. p IN D /\ E p Sh /\
                  eopair D E t onebee p) /\
                 (!sg muci muP autB. sg IN D /\ eperm D E w1 sg /\
                  efixes D E sg e /\
                     pbundle D E ci P leqp B inclB sg muci muP autB
                         ==> eautn D E B autB Sh Sh)`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "nb")
             (CONJUNCTS_THEN2 (LABEL_TAC "faD")
              (CONJUNCTS_THEN2 (LABEL_TAC "fyD")
               (CONJUNCTS_THEN2 (LABEL_TAC "faord")
                (CONJUNCTS_THEN2 (LABEL_TAC "stf")
                 (CONJUNCTS_THEN2 (LABEL_TAC "Rfy")
                  (CONJUNCTS_THEN2 (LABEL_TAC "suc")
                   (CONJUNCTS_THEN2 (LABEL_TAC "ysaD")
                    (CONJUNCTS_THEN2 (LABEL_TAC "sts")
                     (CONJUNCTS_THEN2 (LABEL_TAC "eD")
                      (CONJUNCTS_THEN2 (LABEL_TAC "efin")
                       (LABEL_TAC "esub")))))))))))) THEN
  USE_THEN "nb" (fun th -> let cs = CONJUNCTS(REWRITE_RULE[nbundle] th) in
    LABEL_TAC "hsb" (el 0 cs) THEN LABEL_TAC "emb" (el 1 cs) THEN
    LABEL_TAC "otD" (el 2 cs) THEN LABEL_TAC "ottw" (el 3 cs) THEN
    LABEL_TAC "ztD" (el 4 cs) THEN LABEL_TAC "zttw" (el 5 cs) THEN
        LABEL_TAC "otzt" (el 6 cs) THEN
    LABEL_TAC "rfD" (el 7 cs) THEN LABEL_TAC "rftot" (el 8 cs) THEN
        LABEL_TAC "rfapp" (el 9 cs)) THEN
