   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`fa:A`;`fy:A`;`sa:A`;`ysa:A`;`Z:A`;`S:A`] THEN
  REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
  MAP_EVERY X_GEN_TAC [`sg:A`;`muci:A`;`muP:A`;`autB:A`] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "sgD")
             (CONJUNCTS_THEN2 (LABEL_TAC "sgperm") (LABEL_TAC "pb"))) THEN
  USE_THEN "inv" (MP_TAC o SPECL [`sg:A`;`muci:A`;`muP:A`;`autB:A`]) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "invf") (LABEL_TAC "invb")) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;`ii:A`;`ci:A`;
                `P:A`;`leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`sg:A`;`muci:A`;
      `muP:A`;`autB:A`;`Z:A`;`S:A`] FULLNAME_SYM) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                  DISCH_THEN ACCEPT_TAC]);;

(* ===================================================================== *)
(* S6-D : (NE) every member of the family S is nonempty, with value TOP.   *)
(* For x HS: [[x IN S]] <= sup_{y IN ZZ} [[x = y]] (EBV_IN_LE_V), and for  *)
(* y IN ZZ with member <t,top>: [[t IN y]] = TOP, so [[x = y]] <=          *)
(* [[t IN x]] <= [[?? 2 (2 %% 1)]] (EBV_IN_CONG_R, BVALF_HS_EX_UB).         *)
(* ===================================================================== *)
let FULLFAM_NE = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X Z S v.
     hsbundle D E w1 om tw ii ci P leqp B inclB onebee X /\
     Z IN D /\
     (!s. s IN D /\ E s Z ==> hsname D E B w1 X s /\
          ?t. t IN D /\ ?p. p IN D /\ E p s /\ eopair D E t onebee p) /\
     S IN D /\ (!z. z IN D ==> (E z S <=> ?s. s IN D /\ E s Z /\
         eopair D (E:A->A->bool) s onebee z)) /\
     hsname D E B w1 X S /\
     valuation D v /\ (!i. hsname D E B w1 X (v i)) /\ v 0 = S
     ==> etop D E B inclB (bvalf_HS D E B inclB w1 X v
                           (!! 1 ((1 %% 0) --> ?? 2 (2 %% 1))))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_ASSUM(fun th -> let cs = CONJUNCTS(REWRITE_RULE[hsbundle] th)
                        and cb = CONJUNCTS(MATCH_MP HSB_CBA th) in
    MAP_EVERY ASSUME_TAC [el 0 cs; el 1 cs; el 3 cs; el 15 cs; el 16 cs;
                          el 17 cs; el 18 cs; el 19 cs; el 0 cb; el 1 cb]) THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B inclB /\
      eporder D E B inclB` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  MP_TAC(ISPECL [`1`; `(1 %% 0) --> ?? 2 (2 %% 1)`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;`X:A`;`v:num->A`]
        BVALF_HS_ALL_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN SUBST1_TAC] THEN
  X_GEN_TAC `x:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((1 |-> (x:A)) (v:num->A)) /\
                (!i. hsname D (E:A->A->bool) B w1 X
                 (((1 |-> (x:A)) (v:num->A)) i))`
   (CONJUNCTS_THEN2 (LABEL_TAC "v1") (LABEL_TAC "hv1")) THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC HSNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  MP_TAC(ISPECL [`1 %% 0`; `?? 2 (2 %% 1)`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;`X:A`;
        `(1 |-> (x:A)) (v:num->A)`] BVALF_HS_IMP_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN SUBST1_TAC] THEN
  ABBREV_TAC `G = bvalf_HS D (E:A->A->bool) B inclB w1 X
      ((1 |-> (x:A)) (v:num->A)) (?? 2 (2 %% 1))` THEN
  SUBGOAL_THEN `(G:A) IN D /\ (E:A->A->bool) G B`
      (CONJUNCTS_THEN2 (LABEL_TAC "GD") (LABEL_TAC "GB")) THENL
   [EXPAND_TAC "G" THEN CONJ_TAC THENL
     [MP_TAC(ISPECL [`?? 2 (2 %% 1)`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                     `inclB:A`;`w1:A`;`X:A`;
        `(1 |-> (x:A)) (v:num->A)`] BVALF_HS_SPEC) THEN ASM_SIMP_TAC[];
      MATCH_MP_TAC BVALF_HS_IN_B THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  ABBREV_TAC `mv = bvalf_HS D (E:A->A->bool) B inclB w1 X
      ((1 |-> (x:A)) (v:num->A)) (1 %% 0)` THEN
  SUBGOAL_THEN `ebv_in D (E:A->A->bool) B inclB x S mv` (LABEL_TAC "mvin") THENL
   [EXPAND_TAC "mv" THEN
    MP_TAC(ISPECL [`1`;`0`;`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;
                   `X:A`;`(1 |-> (x:A)) (v:num->A)`]
      BVALF_HS_MEM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER;
                 ARITH_RULE `~(0 = 1)`]; ALL_TAC] THEN
  SUBGOAL_THEN `(mv:A) IN D` (LABEL_TAC "mvD") THENL
   [EXPAND_TAC "mv" THEN
    MP_TAC(ISPECL [`1 %% 0`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                   `inclB:A`;`w1:A`;`X:A`;
      `(1 |-> (x:A)) (v:num->A)`] BVALF_HS_SPEC) THEN
          ASM_SIMP_TAC[]; ALL_TAC] THEN
  TRY(SUBGOAL_THEN `bname D (E:A->A->bool) B (x:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
    ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`x:A`;`S:A`;`mv:A`;
                `G:A`] EBV_IN_LE_V) THEN
  ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
  REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
  MAP_EVERY X_GEN_TAC [`y:A`;`qy:A`;`ey:A`;`c:A`] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "yD") (CONJUNCTS_THEN2 (LABEL_TAC "qyD")
    (CONJUNCTS_THEN2 (LABEL_TAC "eyD") (CONJUNCTS_THEN2 (LABEL_TAC "cD")
      (CONJUNCTS_THEN2 (LABEL_TAC "Syqy")
       (CONJUNCTS_THEN2 (LABEL_TAC "eyeq") (LABEL_TAC "cmeet"))))))) THEN
  (* (y,qy) in S: y IN Z, qy = onebee *)
  USE_THEN "Syqy" (MP_TAC o REWRITE_RULE[eapply]) THEN
  DISCH_THEN(X_CHOOSE_THEN `zq:A` (CONJUNCTS_THEN2 (LABEL_TAC "opq")
      (LABEL_TAC "zqS"))) THEN
  SUBGOAL_THEN `(zq:A) IN D` (LABEL_TAC "zqD") THENL
   [USE_THEN "opq" (ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
  FIRST_X_ASSUM(fun th -> MP_TAC(SPEC `zq:A` th) THEN
    ANTS_TAC THENL [USE_THEN "zqD" ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th' -> USE_THEN "zqS" (MP_TAC o EQ_MP th'))) THEN
  DISCH_THEN(X_CHOOSE_THEN `s0:A` (CONJUNCTS_THEN2 (LABEL_TAC "s0D")
    (CONJUNCTS_THEN2 (LABEL_TAC "s0Z") (LABEL_TAC "ops0")))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`y:A`;`qy:A`;`s0:A`;`onebee:A`;
                `zq:A`] EOPAIR_INJ) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (SUBST_ALL_TAC o SYM) SUBST_ALL_TAC) THEN
  FIRST_ASSUM(fun th -> MP_TAC(SPEC `y:A` th) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "hsy")
             (X_CHOOSE_THEN `t:A` (CONJUNCTS_THEN2 (LABEL_TAC "tD")
    (X_CHOOSE_THEN `p:A` (CONJUNCTS_THEN2 (LABEL_TAC "pD")
                          (CONJUNCTS_THEN2 (LABEL_TAC "py")
                           (LABEL_TAC "opp"))))))) THEN
  SUBGOAL_THEN `hsname D (E:A->A->bool) B w1 X t /\
      bname D E B t /\ bname D E B y`
   (CONJUNCTS_THEN2 (LABEL_TAC "hst") (CONJUNCTS_THEN2 (LABEL_TAC "bnt")
       (LABEL_TAC "bny"))) THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`X:A`;`y:A`;`t:A`]
           HSNAME_DOM) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      REWRITE_TAC[eindom; eapply] THEN EXISTS_TAC `onebee:A` THEN
      CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      EXISTS_TAC `p:A` THEN CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
      DISCH_THEN(fun th -> REPEAT CONJ_TAC THENL
        [ACCEPT_TAC(CONJUNCT2 th);
         MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
         REPEAT CONJ_TAC THEN FIRST [FIRST_ASSUM ACCEPT_TAC;
             ACCEPT_TAC(CONJUNCT1 th);
                                         ACCEPT_TAC(CONJUNCT2 th)];
         MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
         REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC])];
    ALL_TAC] THEN
  (* ty = [[t IN y]] = top *)
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`t:A`;`y:A`]
         EBV_IN_VAL_EXISTS) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ty:A` (CONJUNCTS_THEN2 (LABEL_TAC "tyD")
      (CONJUNCTS_THEN2 (LABEL_TAC "tyB") (LABEL_TAC "tyin")))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`t:A`;`t:A`]
         EBV_EQ_VAL_EXISTS) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ett:A` (CONJUNCTS_THEN2 (LABEL_TAC "ettD")
      (CONJUNCTS_THEN2 (LABEL_TAC "ettB") (LABEL_TAC "etteq")))) THEN
  SUBGOAL_THEN `etop D (E:A->A->bool) B inclB ett` (LABEL_TAC "etttop") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`t:A`;`ett:A`]
           EBV_EQ_REFL) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) inclB onebee ty` (LABEL_TAC "onety") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`t:A`;`y:A`;`ty:A`;
                  `t:A`;`onebee:A`;`ett:A`;`onebee:A`] EBV_IN_GE_TERM_V) THEN
    ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THENL
     [REWRITE_TAC[eapply] THEN EXISTS_TAC `p:A` THEN CONJ_TAC THEN
      FIRST_ASSUM ACCEPT_TAC;
      MATCH_MP_TAC EMEET_TOP THEN REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `ty:A = onebee` SUBST_ALL_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`ty:A`;`onebee:A`]
           EPORDER_ANTISYM) THEN
    ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    MATCH_MP_TAC ETOP_GE THEN EXISTS_TAC `B:A` THEN REPEAT CONJ_TAC THEN
        FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  (* [[x = y]] <= [[t IN x]] *)
  ABBREV_TAC `tx = bvalf_HS D (E:A->A->bool) B inclB w1 X
      ((2 |-> (t:A)) ((1 |-> (x:A)) (v:num->A))) (2 %% 1)` THEN
  SUBGOAL_THEN `valuation D ((2 |-> (t:A)) ((1 |-> (x:A)) (v:num->A))) /\
                (!i. hsname D (E:A->A->bool) B w1 X
                 (((2 |-> (t:A)) ((1 |-> (x:A)) (v:num->A))) i))`
   (CONJUNCTS_THEN2 (LABEL_TAC "v2") (LABEL_TAC "hv2")) THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
      MATCH_MP_TAC HSNAMEVAL_VALMOD THEN CONJ_TAC THEN
          FIRST_ASSUM ACCEPT_TAC]; ALL_TAC] THEN
  SUBGOAL_THEN `ebv_in D (E:A->A->bool) B inclB t x tx` (LABEL_TAC "txin") THENL
   [EXPAND_TAC "tx" THEN
    MP_TAC(ISPECL [`2`;`1`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                   `inclB:A`;`w1:A`;`X:A`;
      `(2 |-> (t:A)) ((1 |-> (x:A)) (v:num->A))`] BVALF_HS_MEM) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    REWRITE_TAC[VALMOD; ARITH_EQ]; ALL_TAC] THEN
  SUBGOAL_THEN `(tx:A) IN D /\ (E:A->A->bool) tx B`
      (CONJUNCTS_THEN2 (LABEL_TAC "txD") (LABEL_TAC "txB")) THENL
   [EXPAND_TAC "tx" THEN CONJ_TAC THENL
     [MP_TAC(ISPECL [`2 %% 1`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                     `inclB:A`;`w1:A`;`X:A`;
        `(2 |-> (t:A)) ((1 |-> (x:A)) (v:num->A))`] BVALF_HS_SPEC) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; SIMP_TAC[]];
      MATCH_MP_TAC BVALF_HS_IN_B THEN REPEAT CONJ_TAC THEN
          FIRST_ASSUM ACCEPT_TAC]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) ey B` (LABEL_TAC "eyB") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`x:A`;`y:A`;`ey:A`]
           EBV_EQ_IN_B) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) inclB ey tx` (LABEL_TAC "eytx") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`y:A`;`x:A`;`t:A`;
                  `ey:A`;`onebee:A`;`tx:A`;`ey:A`] EBV_IN_CONG_R) THEN
    ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`x:A`;`y:A`;
                    `ey:A`] EBV_EQ_SYM) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN ACCEPT_TAC];
      MATCH_MP_TAC EMEET_TOP THEN REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) inclB tx G` (LABEL_TAC "txG") THENL
   [EXPAND_TAC "tx" THEN EXPAND_TAC "G" THEN
    MP_TAC(ISPECL [`2`;`2 %% 1`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                   `inclB:A`;`w1:A`;`X:A`;
      `(1 |-> (x:A)) (v:num->A)`;`t:A`] BVALF_HS_EX_UB) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) inclB c ey` (LABEL_TAC "cey") THENL
   [USE_THEN "cmeet" (ACCEPT_TAC o CONJUNCT2 o MATCH_MP EMEET_LE); ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) c B` (LABEL_TAC "cB") THENL
   [USE_THEN "cmeet" (ACCEPT_TAC o CONJUNCT2 o MATCH_MP EMEET_IN); ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`c:A`;`ey:A`;`G:A`]
         EPORDER_TRANS) THEN
  ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
  REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`ey:A`;`tx:A`;`G:A`]
         EPORDER_TRANS) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                  DISCH_THEN ACCEPT_TAC]);;

(* ===================================================================== *)
(* S6-E1 : NCR_UNIQ -- the uniqueness clause of CFF makes the two           *)
(* membership values c_r = [[<1,2> IN 4]] at 2 := r and c_r' incompatible  *)
(* below G = [[?? 2 BODY]] when [[r = r']] = BOT.                          *)
(* ===================================================================== *)
let NCR_UNIQ = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X u r r' m.
     hsbundle D E w1 om tw ii ci P leqp B inclB onebee X /\
     valuation D u /\ (!i. hsname D E B w1 X (u i)) /\
     r IN D /\ hsname D E B w1 X r /\ r' IN D /\ hsname D E B w1 X r' /\
     etop D E B inclB (bvalf_HS D (E:A->A->bool) B inclB w1 X
                       ((2 |-> (r:A)) (u:num->A)) (2 %% 1)) /\
     etop D E B inclB (bvalf_HS D (E:A->A->bool) B inclB w1 X
                       ((2 |-> (r':A)) (u:num->A)) (2 %% 1)) /\
     (!e. e IN D /\ ebv_eq D E B inclB r r' e ==> ebot D E B inclB e) /\
     m IN D /\ E m B /\
     erel D E inclB m (bvalf_HS D (E:A->A->bool) B inclB w1 X (u:num->A)
                       (?? 2 (((2 %% 1) && ?? 5 (opair_form 1 2 5 && (5 %% 4)))
         && ?? 3 ((Eq 3 2) && !! 2 (((2 %% 1) &&
         ?? 5 (opair_form 1 2 5 && (5 %% 4))) --> Eq 2 3))))) /\
     erel D E inclB m (bvalf_HS D (E:A->A->bool) B inclB w1 X
                       ((2 |-> (r:A)) (u:num->A))
         (?? 5 (opair_form 1 2 5 && (5 %% 4)))) /\
     erel D E inclB m (bvalf_HS D (E:A->A->bool) B inclB w1 X
                       ((2 |-> (r':A)) (u:num->A))
         (?? 5 (opair_form 1 2 5 && (5 %% 4))))
     ==> ebot D E B inclB m`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "hsb")
             (CONJUNCTS_THEN2 (LABEL_TAC "vu")
              (CONJUNCTS_THEN2 (LABEL_TAC "hu")
               (CONJUNCTS_THEN2 (LABEL_TAC "rD")
                (CONJUNCTS_THEN2 (LABEL_TAC "hsr")
                 (CONJUNCTS_THEN2 (LABEL_TAC "r'D")
                  (CONJUNCTS_THEN2 (LABEL_TAC "hsr'")
                   (CONJUNCTS_THEN2 (LABEL_TAC "topr")
                    (CONJUNCTS_THEN2 (LABEL_TAC "topr'")
                     (CONJUNCTS_THEN2 (LABEL_TAC "rr'bot")
                      (CONJUNCTS_THEN2 (LABEL_TAC "mD")
                       (CONJUNCTS_THEN2 (LABEL_TAC "mB")
                        (CONJUNCTS_THEN2 (LABEL_TAC "mG")
                         (CONJUNCTS_THEN2 (LABEL_TAC "mcr")
                          (LABEL_TAC "mcr'"))))))))))))))) THEN
  FIRST_ASSUM(fun th -> let cs = CONJUNCTS(REWRITE_RULE[hsbundle] th)
                        and cb = CONJUNCTS(MATCH_MP HSB_CBA th) in
    MAP_EVERY ASSUME_TAC [el 0 cs; el 1 cs; el 3 cs; el 15 cs; el 16 cs;
                          el 17 cs; el 18 cs; el 19 cs; el 0 cb; el 1 cb]) THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B inclB /\
      eporder D E B inclB` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
