        ?? 5 (opair_form 1 2 5 && (5 %% 4))) --> Eq 2 3)))`;
        `bvalf_HS D (E:A->A->bool) B inclB w1 X ((2 |-> (z:A)) (u:num->A))
        (?? 3 ((Eq 3 2) && !! 2 (((2 %% 1) &&
        ?? 5 (opair_form 1 2 5 && (5 %% 4))) --> Eq 2 3)))`;`nk:A`]
        EPORDER_TRANS) THEN
    REPEAT CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC; FIRST_ASSUM ACCEPT_TAC; FIRST_ASSUM ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC; FIRST_ASSUM ACCEPT_TAC; FIRST_ASSUM ACCEPT_TAC;
      USE_THEN "BdHz" ACCEPT_TAC; USE_THEN "Hznk" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) inclB
      (bvalf_HS D (E:A->A->bool) B inclB w1 X (u:num->A)
       (?? 2 (((2 %% 1) && ?? 5 (opair_form 1 2 5 && (5 %% 4))) &&
              ?? 3 ((Eq 3 2) && !! 2 (((2 %% 1) &&
      ?? 5 (opair_form 1 2 5 && (5 %% 4))) --> Eq 2 3))))) nk`
      (LABEL_TAC "Gnk") THENL
   [MP_TAC(ISPECL [`2`;`((2 %% 1) && ?? 5 (opair_form 1 2 5 && (5 %% 4))) &&
                   ?? 3 ((Eq 3 2) && !! 2 (((2 %% 1) &&
       ?? 5 (opair_form 1 2 5 && (5 %% 4))) --> Eq 2 3))`;`D:A->bool`;
       `E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;`X:A`;`u:num->A`;`nk:A`]
       BVALF_HS_EX_LEAST) THEN
    ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    X_GEN_TAC `z:A` THEN DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "zD")
        (LABEL_TAC "hsz")) THEN
    USE_THEN "clB" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`k:A`;`nk:A`;`m:A`]
         BELOW_COMPL_BOT) THEN
  ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
  REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THENL
   [MATCH_MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;
                        `bvalf_HS D (E:A->A->bool) B inclB w1 X
       ((2 |-> (r:A)) (u:num->A)) (?? 5 (opair_form 1 2 5 && (5 %% 4)))`;
       `bvalf_HS D (E:A->A->bool) B inclB w1 X ((2 |-> (r':A)) (u:num->A))
       (?? 5 (opair_form 1 2 5 && (5 %% 4)))`;`k:A`;`m:A`] EMEET_GREATEST) THEN
    REPEAT CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; FIRST_ASSUM ACCEPT_TAC;
                           FIRST_ASSUM ACCEPT_TAC; USE_THEN "mcr" ACCEPT_TAC;
        USE_THEN "mcr'" ACCEPT_TAC];
    MATCH_MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`m:A`;
                        `bvalf_HS D (E:A->A->bool) B inclB w1 X (u:num->A)
        (?? 2 (((2 %% 1) && ?? 5 (opair_form 1 2 5 && (5 %% 4))) &&
               ?? 3 ((Eq 3 2) && !! 2 (((2 %% 1) &&
        ?? 5 (opair_form 1 2 5 && (5 %% 4))) --> Eq 2 3))))`;`nk:A`]
        EPORDER_TRANS) THEN
    REPEAT CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC; FIRST_ASSUM ACCEPT_TAC; FIRST_ASSUM ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC; FIRST_ASSUM ACCEPT_TAC; FIRST_ASSUM ACCEPT_TAC;
      USE_THEN "mG" ACCEPT_TAC; USE_THEN "Gnk" ACCEPT_TAC]]);;

(* ===================================================================== *)
(* S6-E2 : NCR_SOME -- if b <= G and b meets no c_r (r IN dom Sh), b = BOT. *)
(* For HS z: [[P]]_z = [[z IN Sh]] /\ [[CY]]_z, [[z IN Sh]] <= sup_y        *)
(* [[z = y]] (EBV_IN_LE_V), [[z = y]] /\ [[CY]]_z <= c_y (Leibniz), and     *)
(* c_y /\ b = BOT; residuate to [[P]]_z <= ~b, so G <= ~b.                  *)
(* ===================================================================== *)
let NCR_SOME = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X u RS b.
     hsbundle D E w1 om tw ii ci P leqp B inclB onebee X /\
     valuation D u /\ (!i. hsname D E B w1 X (u i)) /\
     RS IN D /\ (!s. s IN D /\ E s RS ==> hsname D E B w1 X s) /\
     (!z. z IN D ==> (E z (u 1) <=> ?s. s IN D /\ E s RS /\
                      eopair D (E:A->A->bool) s onebee z)) /\
     b IN D /\ E b B /\
     erel D E inclB b (bvalf_HS D (E:A->A->bool) B inclB w1 X (u:num->A)
                       (?? 2 (((2 %% 1) && ?? 5 (opair_form 1 2 5 && (5 %% 4)))
         && ?? 3 ((Eq 3 2) && !! 2 (((2 %% 1) &&
         ?? 5 (opair_form 1 2 5 && (5 %% 4))) --> Eq 2 3))))) /\
     (!r m. r IN D /\ E r RS /\ m IN D /\ E m B /\ erel D E inclB m b /\
            erel D E inclB m (bvalf_HS D (E:A->A->bool) B inclB w1 X
                              ((2 |-> (r:A)) (u:num->A))
                (?? 5 (opair_form 1 2 5 && (5 %% 4)))) ==> ebot D E B inclB m)
     ==> ebot D E B inclB b`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "hsb")
             (CONJUNCTS_THEN2 (LABEL_TAC "vu")
              (CONJUNCTS_THEN2 (LABEL_TAC "hu")
               (CONJUNCTS_THEN2 (LABEL_TAC "RSD")
                (CONJUNCTS_THEN2 (LABEL_TAC "RShs")
                 (CONJUNCTS_THEN2 (LABEL_TAC "Shch")
                  (CONJUNCTS_THEN2 (LABEL_TAC "bD")
                   (CONJUNCTS_THEN2 (LABEL_TAC "bB")
                    (CONJUNCTS_THEN2 (LABEL_TAC "bG")
                     (LABEL_TAC "disj")))))))))) THEN
  FIRST_ASSUM(fun th -> let cs = CONJUNCTS(REWRITE_RULE[hsbundle] th)
                        and cb = CONJUNCTS(MATCH_MP HSB_CBA th) in
    MAP_EVERY ASSUME_TAC [el 0 cs; el 1 cs; el 3 cs; el 15 cs; el 16 cs;
                          el 17 cs; el 18 cs; el 19 cs; el 0 cb; el 1 cb]) THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B inclB /\
      eporder D E B inclB` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`] EBALG_BOT) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `bot:A` (LABEL_TAC "bot")) THEN
  SUBGOAL_THEN `(bot:A) IN D /\ (E:A->A->bool) bot B`
      (CONJUNCTS_THEN2 (LABEL_TAC "botD") (LABEL_TAC "botB")) THENL
   [USE_THEN "bot" (ACCEPT_TAC o MATCH_MP EBOT_IN); ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`b:A`]
         EBALG_COMPL) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `nb:A` (LABEL_TAC "nb")) THEN
  SUBGOAL_THEN `(nb:A) IN D /\ (E:A->A->bool) nb B`
      (CONJUNCTS_THEN2 (LABEL_TAC "nbD") (LABEL_TAC "nbB")) THENL
   [USE_THEN "nb" (ACCEPT_TAC o MATCH_MP ECOMPL_IN); ALL_TAC] THEN
  SUBGOAL_THEN `(u:num->A) 1 IN D` (LABEL_TAC "ShD") THENL
   [USE_THEN "vu" (ACCEPT_TAC o SPEC `1` o
                   REWRITE_RULE[valuation]); ALL_TAC] THEN
  (* each c_y is disjoint from b, hence below ~b; then the Leibniz bound *)
  SUBGOAL_THEN
   `!z. z IN D /\ hsname D (E:A->A->bool) B w1 X z
        ==> erel D E inclB (bvalf_HS D (E:A->A->bool) B inclB w1 X
                            ((2 |-> (z:A)) (u:num->A))
            (((2 %% 1) && ?? 5 (opair_form 1 2 5 && (5 %% 4))) &&
             ?? 3 ((Eq 3 2) && !! 2 (((2 %% 1) &&
            ?? 5 (opair_form 1 2 5 && (5 %% 4))) --> Eq 2 3)))) nb`
   (LABEL_TAC "clB") THENL
   [X_GEN_TAC `z:A` THEN DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "zD")
       (LABEL_TAC "hsz")) THEN
    SUBGOAL_THEN `valuation D ((2 |-> (z:A)) (u:num->A)) /\
        (!i. hsname D (E:A->A->bool) B w1 X (((2 |-> (z:A)) (u:num->A)) i))`
     (CONJUNCTS_THEN2 (LABEL_TAC "vz") (LABEL_TAC "hz")) THENL
     [CONJ_TAC THENL
       [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC) THEN
        FIRST_ASSUM ACCEPT_TAC;
        REPEAT(MATCH_MP_TAC HSNAMEVAL_VALMOD THEN CONJ_TAC) THEN
            FIRST_ASSUM ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `(bvalf_HS D (E:A->A->bool) B inclB w1 X
                   ((2 |-> (z:A)) (u:num->A)) (((2 %% 1) &&
        ?? 5 (opair_form 1 2 5 && (5 %% 4))) &&
        ?? 3 ((Eq 3 2) && !! 2 (((2 %% 1) &&
        ?? 5 (opair_form 1 2 5 && (5 %% 4))) --> Eq 2 3)))) IN D /\
        (E:A->A->bool) (bvalf_HS D (E:A->A->bool) B inclB w1 X
                        ((2 |-> (z:A)) (u:num->A))
        (((2 %% 1) && ?? 5 (opair_form 1 2 5 && (5 %% 4))) &&
         ?? 3 ((Eq 3 2) && !! 2 (((2 %% 1) &&
        ?? 5 (opair_form 1 2 5 && (5 %% 4))) --> Eq 2 3)))) B`
        (CONJUNCTS_THEN2 (LABEL_TAC "BdD") (LABEL_TAC "BdB")) THENL
     [CONJ_TAC THENL
       [MP_TAC(ISPECL [`((2 %% 1) && ?? 5 (opair_form 1 2 5 && (5 %% 4))) &&
                       ?? 3 ((Eq 3 2) && !! 2 (((2 %% 1) &&
           ?? 5 (opair_form 1 2 5 && (5 %% 4))) --> Eq 2 3))`;`D:A->bool`;
           `E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;`X:A`;
           `(2 |-> (z:A)) (u:num->A)`] BVALF_HS_SPEC) THEN
        ANTS_TAC THENL [REPEAT CONJ_TAC THEN
                        FIRST_ASSUM ACCEPT_TAC; SIMP_TAC[]];
        MATCH_MP_TAC BVALF_HS_IN_B THEN REPEAT CONJ_TAC THEN
            FIRST_ASSUM ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `(bvalf_HS D (E:A->A->bool) B inclB w1 X
                   ((2 |-> (z:A)) (u:num->A)) ((2 %% 1) &&
        ?? 5 (opair_form 1 2 5 && (5 %% 4)))) IN D /\
        (E:A->A->bool) (bvalf_HS D (E:A->A->bool) B inclB w1 X
                        ((2 |-> (z:A)) (u:num->A))
        ((2 %% 1) && ?? 5 (opair_form 1 2 5 && (5 %% 4)))) B`
        (CONJUNCTS_THEN2 (LABEL_TAC "PzD") (LABEL_TAC "PzB")) THENL
     [CONJ_TAC THENL
       [MP_TAC(ISPECL [`(2 %% 1) && ?? 5 (opair_form 1 2 5 && (5 %% 4))`;
                       `D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;`X:A`;
           `(2 |-> (z:A)) (u:num->A)`] BVALF_HS_SPEC) THEN
        ANTS_TAC THENL [REPEAT CONJ_TAC THEN
                        FIRST_ASSUM ACCEPT_TAC; SIMP_TAC[]];
        MATCH_MP_TAC BVALF_HS_IN_B THEN REPEAT CONJ_TAC THEN
            FIRST_ASSUM ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `(bvalf_HS D (E:A->A->bool) B inclB w1 X
                   ((2 |-> (z:A)) (u:num->A)) (2 %% 1)) IN D /\
        (E:A->A->bool) (bvalf_HS D (E:A->A->bool) B inclB w1 X
                        ((2 |-> (z:A)) (u:num->A)) (2 %% 1)) B`
        (CONJUNCTS_THEN2 (LABEL_TAC "MzD") (LABEL_TAC "MzB")) THENL
     [CONJ_TAC THENL
       [MP_TAC(ISPECL [`2 %% 1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;
                       `w1:A`;`X:A`;`(2 |-> (z:A)) (u:num->A)`]
           BVALF_HS_SPEC) THEN
        ANTS_TAC THENL [REPEAT CONJ_TAC THEN
                        FIRST_ASSUM ACCEPT_TAC; SIMP_TAC[]];
        MATCH_MP_TAC BVALF_HS_IN_B THEN REPEAT CONJ_TAC THEN
            FIRST_ASSUM ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `(bvalf_HS D (E:A->A->bool) B inclB w1 X
                   ((2 |-> (z:A)) (u:num->A)) (?? 5
        (opair_form 1 2 5 && (5 %% 4)))) IN D /\
        (E:A->A->bool) (bvalf_HS D (E:A->A->bool) B inclB w1 X
                        ((2 |-> (z:A)) (u:num->A))
        (?? 5 (opair_form 1 2 5 && (5 %% 4)))) B`
        (CONJUNCTS_THEN2 (LABEL_TAC "CzD") (LABEL_TAC "CzB")) THENL
     [CONJ_TAC THENL
       [MP_TAC(ISPECL [`?? 5 (opair_form 1 2 5 && (5 %% 4))`;`D:A->bool`;
                       `E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;`X:A`;
           `(2 |-> (z:A)) (u:num->A)`] BVALF_HS_SPEC) THEN
        ANTS_TAC THENL [REPEAT CONJ_TAC THEN
                        FIRST_ASSUM ACCEPT_TAC; SIMP_TAC[]];
        MATCH_MP_TAC BVALF_HS_IN_B THEN REPEAT CONJ_TAC THEN
            FIRST_ASSUM ACCEPT_TAC];
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;
                  `bvalf_HS D (E:A->A->bool) B inclB w1 X
        ((2 |-> (z:A)) (u:num->A)) (?? 5 (opair_form 1 2 5 && (5 %% 4)))`;
        `nb:A`] EBIMP_EXISTS) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `R:A` (LABEL_TAC "Rimp")) THEN
    SUBGOAL_THEN `(R:A) IN D /\ (E:A->A->bool) R B`
        (CONJUNCTS_THEN2 (LABEL_TAC "RD") (LABEL_TAC "RB")) THENL
     [USE_THEN "Rimp" (ACCEPT_TAC o MATCH_MP EBIMP_IN); ALL_TAC] THEN
    SUBGOAL_THEN `ebv_in D (E:A->A->bool) B inclB z ((u:num->A) 1)
        (bvalf_HS D (E:A->A->bool) B inclB w1 X ((2 |-> (z:A)) (u:num->A))
         (2 %% 1))` (LABEL_TAC "Mzin") THENL
     [MP_TAC(ISPECL [`2`;`1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;
                     `X:A`;`(2 |-> (z:A)) (u:num->A)`] BVALF_HS_MEM) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      REWRITE_TAC[VALMOD; ARITH_EQ];
      ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) inclB
        (bvalf_HS D (E:A->A->bool) B inclB w1 X ((2 |-> (z:A)) (u:num->A))
         (2 %% 1)) R` (LABEL_TAC "MzR") THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`z:A`;
                    `(u:num->A) 1`;`bvalf_HS D (E:A->A->bool) B inclB w1 X
         ((2 |-> (z:A)) (u:num->A)) (2 %% 1)`;`R:A`] EBV_IN_LE_V) THEN
      ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
      REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      MAP_EVERY X_GEN_TAC [`y:A`;`qy:A`;`ey:A`;`c:A`] THEN
      DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "yD")
                 (CONJUNCTS_THEN2 (LABEL_TAC "qyD")
        (CONJUNCTS_THEN2 (LABEL_TAC "eyD") (CONJUNCTS_THEN2 (LABEL_TAC "cD")
          (CONJUNCTS_THEN2 (LABEL_TAC "Syqy")
           (CONJUNCTS_THEN2 (LABEL_TAC "eyeq") (LABEL_TAC "cmeet"))))))) THEN
      USE_THEN "Syqy" (MP_TAC o REWRITE_RULE[eapply]) THEN
      DISCH_THEN(X_CHOOSE_THEN `zq:A` (CONJUNCTS_THEN2 (LABEL_TAC "opq")
          (LABEL_TAC "zqS"))) THEN
      SUBGOAL_THEN `(zq:A) IN D` (LABEL_TAC "zqD") THENL
       [USE_THEN "opq" (ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
      USE_THEN "Shch" (MP_TAC o SPEC `zq:A`) THEN
      ANTS_TAC THENL [USE_THEN "zqD" ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> USE_THEN "zqS" (MP_TAC o EQ_MP th)) THEN
      DISCH_THEN(X_CHOOSE_THEN `s0:A` (CONJUNCTS_THEN2 (LABEL_TAC "s0D")
        (CONJUNCTS_THEN2 (LABEL_TAC "s0RS") (LABEL_TAC "ops0")))) THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`y:A`;`qy:A`;`s0:A`;`onebee:A`;
                    `zq:A`] EOPAIR_INJ) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(CONJUNCTS_THEN2 (SUBST_ALL_TAC o SYM) SUBST_ALL_TAC) THEN
      SUBGOAL_THEN `hsname D (E:A->A->bool) B w1 X y` (LABEL_TAC "hsy") THENL
       [USE_THEN "RShs" MATCH_MP_TAC THEN CONJ_TAC THEN
        FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      SUBGOAL_THEN `valuation D ((2 |-> (y:A)) (u:num->A)) /\
          (!i. hsname D (E:A->A->bool) B w1 X (((2 |-> (y:A)) (u:num->A)) i))`
     (CONJUNCTS_THEN2 (LABEL_TAC "vy") (LABEL_TAC "hy")) THENL
     [CONJ_TAC THENL
       [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC) THEN
        FIRST_ASSUM ACCEPT_TAC;
        REPEAT(MATCH_MP_TAC HSNAMEVAL_VALMOD THEN CONJ_TAC) THEN
            FIRST_ASSUM ACCEPT_TAC];
      ALL_TAC] THEN
      SUBGOAL_THEN `(bvalf_HS D (E:A->A->bool) B inclB w1 X
                     ((2 |-> (y:A)) (u:num->A)) (?? 5
          (opair_form 1 2 5 && (5 %% 4)))) IN D /\
          (E:A->A->bool) (bvalf_HS D (E:A->A->bool) B inclB w1 X
                          ((2 |-> (y:A)) (u:num->A))
          (?? 5 (opair_form 1 2 5 && (5 %% 4)))) B`
          (CONJUNCTS_THEN2 (LABEL_TAC "CyD") (LABEL_TAC "CyB")) THENL
     [CONJ_TAC THENL
       [MP_TAC(ISPECL [`?? 5 (opair_form 1 2 5 && (5 %% 4))`;`D:A->bool`;
                       `E:A->A->bool`;`B:A`;`inclB:A`;`w1:A`;`X:A`;
           `(2 |-> (y:A)) (u:num->A)`] BVALF_HS_SPEC) THEN
        ANTS_TAC THENL [REPEAT CONJ_TAC THEN
                        FIRST_ASSUM ACCEPT_TAC; SIMP_TAC[]];
        MATCH_MP_TAC BVALF_HS_IN_B THEN REPEAT CONJ_TAC THEN
            FIRST_ASSUM ACCEPT_TAC];
      ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) ey B` (LABEL_TAC "eyB") THENL
       [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`z:A`;`y:A`;
                      `ey:A`] EBV_EQ_IN_B) THEN
        ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                        DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) c B` (LABEL_TAC "cB") THENL
       [USE_THEN "cmeet" (ACCEPT_TAC o CONJUNCT2 o MATCH_MP
                          EMEET_IN); ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`ey:A`;
                    `bvalf_HS D (E:A->A->bool) B inclB w1 X
          ((2 |-> (z:A)) (u:num->A)) (?? 5 (opair_form 1 2 5 && (5 %% 4)))`]
          EBALG_MEET) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
