(* ===================================================================== *)
(* S6-E3 : the condition level.  BOT_NOMEM: the bottom of RO(P) has no    *)
(* conditions.  FRESH_INDEX: a condition mentions only finitely many       *)
(* w1-indices, so an index outside any countable set exists.  COND_SWAP:   *)
(* for the transposition (a a') with a' not mentioned by pi, pi and its    *)
(* image muP(pi) are compatible; pi IN x gives a common extension in x     *)
(* and in autB(x).                                                          *)
(* ===================================================================== *)
let BOT_NOMEM = prove
 (`!D (E:A->A->bool) P leqp B inclB z r.
     model D E ZF_AX /\ eleqp D E P leqp /\ eroset D E P leqp B /\
         eincl D E B inclB /\
     ebot D E B inclB z /\ r IN D
     ==> ~(E r z)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN DISCH_TAC THEN
  FIRST_ASSUM(X_CHOOSE_TAC `z0:A` o MATCH_MP EEMPTY_EXISTS) THEN
  SUBGOAL_THEN `(z0:A) IN D` ASSUME_TAC THENL
      [ASM_MESON_TAC[eempty]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) z0 B` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`B:A`;`z0:A`]
           EROSET_BOT) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(z:A) IN D /\ (E:A->A->bool) z B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBOT_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) inclB z z0` ASSUME_TAC THENL
   [ASM_MESON_TAC[ebot]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`z:A`;`z0:A`]
         EINCL_EREL) THEN
  ASM_REWRITE_TAC[esubset] THEN
  DISCH_THEN(MP_TAC o SPEC `r:A`) THEN ASM_REWRITE_TAC[] THEN
  ASM_MESON_TAC[eempty]);;

let FRESH_INDEX = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X pi e a.
     hsbundle D E w1 om tw ii ci P leqp B inclB onebee X /\
     pi IN D /\ E pi P /\
     e IN D /\ (?n. n IN D /\ E n w1 /\ ?f. ebij D E f n e) /\
         esubset D E e w1 /\
     a IN D /\ E a w1
     ==> ?a'. a' IN D /\ E a' w1 /\ ~(E a' e) /\ ~(a' = a) /\
         (!q a3 a4 a5 a6. q IN D /\ a3 IN D /\ a4 IN D /\ a5 IN D /\ a6 IN D /\
             E q pi /\ eopair D E a3 a4 q /\ eopair D E a5 a6 a3
                 ==> ~(a5 = a'))`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "hsb")
             (CONJUNCTS_THEN2 (LABEL_TAC "piD")
              (CONJUNCTS_THEN2 (LABEL_TAC "piP")
               (CONJUNCTS_THEN2 (LABEL_TAC "eD")
                (CONJUNCTS_THEN2 (LABEL_TAC "efin")
                 (CONJUNCTS_THEN2 (LABEL_TAC "esub")
                  (CONJUNCTS_THEN2 (LABEL_TAC "aD")
                   (LABEL_TAC "aw1")))))))) THEN
  USE_THEN "hsb" (MP_TAC o MATCH_MP HSB_CBA) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "cba")
             (CONJUNCTS_THEN2 (LABEL_TAC "inclD") (LABEL_TAC "leqpD"))) THEN
  USE_THEN "hsb" (MP_TAC o REWRITE_RULE[hsbundle]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
             (CONJUNCTS_THEN2 (LABEL_TAC "vl")
              (CONJUNCTS_THEN2 (LABEL_TAC "eom")
               (CONJUNCTS_THEN2 (LABEL_TAC "w1D")
                (CONJUNCTS_THEN2 (LABEL_TAC "w1card")
                 (CONJUNCTS_THEN2 (LABEL_TAC "omw1e")
                  (CONJUNCTS_THEN2 (LABEL_TAC "w1min")
                   (CONJUNCTS_THEN2 (LABEL_TAC "cr1")
                    (CONJUNCTS_THEN2 (LABEL_TAC "cr2")
                     (CONJUNCTS_THEN2 (LABEL_TAC "ftw")
                      (CONJUNCTS_THEN2 (LABEL_TAC "coh")
                       (CONJUNCTS_THEN2 (LABEL_TAC "leq")
                        (CONJUNCTS_THEN2 (LABEL_TAC "ros")
                         (CONJUNCTS_THEN2 (LABEL_TAC "inc")
                          (CONJUNCTS_THEN2 (LABEL_TAC "porder")
      (CONJUNCTS_THEN2 (LABEL_TAC "top")
       (CONJUNCTS_THEN2 (LABEL_TAC "oneD")
        (CONJUNCTS_THEN2 (LABEL_TAC "BD")
         (CONJUNCTS_THEN2 (LABEL_TAC "oneB")
          (CONJUNCTS_THEN2 (LABEL_TAC "XD")
           (CONJUNCTS_THEN2 (LABEL_TAC "ciX")
            (LABEL_TAC "PX")))))))))))))))))))))) THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B inclB /\ eporder D E B inclB`
   (CONJUNCTS_THEN2 (LABEL_TAC "balg") (LABEL_TAC "pord")) THENL
   [USE_THEN "cba" (fun th -> let b = MATCH_MP ECBA_IMP_BALG th in
      ACCEPT_TAC(CONJ b (MATCH_MP EBALG_IMP_PORDER b)));
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`pi:A`] EDOMAIN_EXISTS) THEN
  ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `dp:A` (LABEL_TAC "dp")) THEN
  SUBGOAL_THEN `(dp:A) IN D` (LABEL_TAC "dpD") THENL
   [USE_THEN "dp" (ACCEPT_TAC o CONJUNCT1 o
                   REWRITE_RULE[edomain]); ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`ii:A`;`tw:A`;`ci:A`;`om:A`;`P:A`;
                `pi:A`;`dp:A`] COHEN_DOM_FIN_SUB) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "dpfin") (LABEL_TAC "dpii")) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`dp:A`] EDOMAIN_EXISTS) THEN
  ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ddp:A` (LABEL_TAC "ddp")) THEN
  SUBGOAL_THEN `(ddp:A) IN D` (LABEL_TAC "ddpD") THENL
