  SUBGOAL_THEN `!z. z IN D /\ (E:A->A->bool) z dp ==> ?u w. u IN D /\ w IN D /\
      eopair D E u w z /\ E u w1`
   (LABEL_TAC "dppairs") THENL
   [X_GEN_TAC `z:A` THEN DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "zD")
       (LABEL_TAC "zdp")) THEN
    SUBGOAL_THEN `(E:A->A->bool) z ii` (LABEL_TAC "zii") THENL
     [USE_THEN "dpii" (MATCH_MP_TAC o REWRITE_RULE[esubset]) THEN CONJ_TAC THEN
