    X_GEN_TAC `z:A` THEN DISCH_TAC THEN
    USE_THEN "dppairs" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `u:A` (X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC)) THEN
    MAP_EVERY EXISTS_TAC [`u:A`;`w:A`] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) ddp w1` (LABEL_TAC "ddpw1") THENL
   [REWRITE_TAC[esubset] THEN X_GEN_TAC `u:A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "uD") (LABEL_TAC "uddp")) THEN
    USE_THEN "ddp" (MP_TAC o SPEC `u:A` o CONJUNCT2 o
                    REWRITE_RULE[edomain]) THEN
    ANTS_TAC THENL [USE_THEN "uD" ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "uddp" (MP_TAC o EQ_MP th)) THEN
