(* ===================================================================== *)
(* S6-E3c : COND_SWAP -- a condition pi in x, with the swapped index a'    *)
(* fresh for pi, has a common extension rho with its autB-image in x'.     *)
(* ===================================================================== *)
let COND_SWAP = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X a a' sg muci
  muP autB pi x x'.
     hsbundle D E w1 om tw ii ci P leqp B inclB onebee X /\
     a IN D /\ E a w1 /\ a' IN D /\ E a' w1 /\
     sg IN D /\ (!x y. x IN D /\ y IN D ==> (eapply D E sg x y <=> E x w1 /\
             ((x = a /\ y = a') \/ (x = a' /\ y = a) \/
              (~(x = a) /\ ~(x = a') /\ y = x)))) /\
     pbundle D E ci P leqp B inclB sg muci muP autB /\
     pi IN D /\ E pi P /\ (!q a3 a4 a5 a6. q IN D /\ a3 IN D /\ a4 IN D /\
                           a5 IN D /\ a6 IN D /\
             E q pi /\ eopair D E a3 a4 q /\ eopair D E a5 a6 a3
                 ==> ~(a5 = a')) /\
     x IN D /\ E x B /\ x' IN D /\ eapply D E autB x x' /\ E pi x
     ==> ?rho. rho IN D /\ E rho P /\ E rho x /\ E rho x'`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "hsb")
             (CONJUNCTS_THEN2 (LABEL_TAC "aD")
              (CONJUNCTS_THEN2 (LABEL_TAC "aw1")
               (CONJUNCTS_THEN2 (LABEL_TAC "a'D")
                (CONJUNCTS_THEN2 (LABEL_TAC "a'w1")
                 (CONJUNCTS_THEN2 (LABEL_TAC "sgD")
                  (CONJUNCTS_THEN2 (LABEL_TAC "TCH")
                   (CONJUNCTS_THEN2 (LABEL_TAC "pb")
                    (CONJUNCTS_THEN2 (LABEL_TAC "piD")
                     (CONJUNCTS_THEN2 (LABEL_TAC "piP")
                      (CONJUNCTS_THEN2 (LABEL_TAC "FRESH")
                       (CONJUNCTS_THEN2 (LABEL_TAC "xD")
                        (CONJUNCTS_THEN2 (LABEL_TAC "xB")
                         (CONJUNCTS_THEN2 (LABEL_TAC "x'D")
                          (CONJUNCTS_THEN2 (LABEL_TAC "axx'")
      (LABEL_TAC "pix")))))))))))))))) THEN
  USE_THEN "hsb" (MP_TAC o MATCH_MP HSB_CBA) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "cba")
             (CONJUNCTS_THEN2 (LABEL_TAC "inclD") (LABEL_TAC "leqpD"))) THEN
  USE_THEN "hsb" (MP_TAC o REWRITE_RULE[hsbundle]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
             (CONJUNCTS_THEN2 (LABEL_TAC "vl")
              (CONJUNCTS_THEN2 (LABEL_TAC "eom")
               (CONJUNCTS_THEN2 (LABEL_TAC "w1D")
                (CONJUNCTS_THEN2 (LABEL_TAC "w1card")
                 (CONJUNCTS_THEN2 (LABEL_TAC "omw1e")
                  (CONJUNCTS_THEN2 (LABEL_TAC "w1min")
                   (CONJUNCTS_THEN2 (LABEL_TAC "cr1")
                    (CONJUNCTS_THEN2 (LABEL_TAC "cr2")
                     (CONJUNCTS_THEN2 (LABEL_TAC "ftw")
                      (CONJUNCTS_THEN2 (LABEL_TAC "coh")
                       (CONJUNCTS_THEN2 (LABEL_TAC "leq")
                        (CONJUNCTS_THEN2 (LABEL_TAC "ros")
                         (CONJUNCTS_THEN2 (LABEL_TAC "inc")
                          (CONJUNCTS_THEN2 (LABEL_TAC "porder")
      (CONJUNCTS_THEN2 (LABEL_TAC "top")
       (CONJUNCTS_THEN2 (LABEL_TAC "oneD")
        (CONJUNCTS_THEN2 (LABEL_TAC "BD")
         (CONJUNCTS_THEN2 (LABEL_TAC "oneB")
          (CONJUNCTS_THEN2 (LABEL_TAC "XD")
           (CONJUNCTS_THEN2 (LABEL_TAC "ciX")
            (LABEL_TAC "PX")))))))))))))))))))))) THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B inclB /\ eporder D E B inclB`
   (CONJUNCTS_THEN2 (LABEL_TAC "balg") (LABEL_TAC "pord")) THENL
   [USE_THEN "cba" (fun th -> let b = MATCH_MP ECBA_IMP_BALG th in
      ACCEPT_TAC(CONJ b (MATCH_MP EBALG_IMP_PORDER b)));
    ALL_TAC] THEN
  USE_THEN "pb" (fun th -> let cs = CONJUNCTS(REWRITE_RULE[pbundle] th) in
    LABEL_TAC "mucD" (el 0 cs) THEN LABEL_TAC "muPD" (el 1 cs) THEN
        LABEL_TAC "autBD" (el 2 cs) THEN
    LABEL_TAC "bijci" (el 3 cs) THEN LABEL_TAC "bijP" (el 4 cs) THEN
        LABEL_TAC "bijB" (el 5 cs) THEN
    LABEL_TAC "mch" (el 6 cs) THEN LABEL_TAC "Pch" (el 7 cs) THEN
        LABEL_TAC "ach" (el 8 cs)) THEN
  USE_THEN "bijP" (fun th -> let cs = CONJUNCTS(REWRITE_RULE[ebij] th) in
