  USE_THEN "bijB" (fun th -> let cs = CONJUNCTS(REWRITE_RULE[ebij] th) in
    LABEL_TAC "Brng" (el 1 cs)) THEN
  USE_THEN "Ptot" (MP_TAC o SPEC `pi:A`) THEN
  ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `pi':A` (CONJUNCTS_THEN2 (LABEL_TAC "pi'D")
      (CONJUNCTS_THEN2 (LABEL_TAC "pi'P") (LABEL_TAC "mupi")))) THEN
  USE_THEN "Pch" (MP_TAC o SPECL [`pi:A`;`pi':A`]) THEN
