  DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (MP_TAC o REWRITE_RULE[muPrel])) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (LABEL_TAC "x'img")) THEN
  SUBGOAL_THEN `(E:A->A->bool) pi' x'` (LABEL_TAC "pi'x'") THENL
   [USE_THEN "x'img" (MP_TAC o SPEC `pi':A`) THEN
    ANTS_TAC THENL [USE_THEN "pi'D" ACCEPT_TAC; DISCH_THEN SUBST1_TAC] THEN
    EXISTS_TAC `pi:A` THEN REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) x' B` (LABEL_TAC "x'B") THENL
   [USE_THEN "Brng" (MP_TAC o SPECL [`x:A`;`x':A`]) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN(ACCEPT_TAC o CONJUNCT2)];
    ALL_TAC] THEN
  SUBGOAL_THEN `efunctional D (E:A->A->bool) pi /\
      efunctional D E pi'` (CONJUNCTS_THEN2 (LABEL_TAC "pifun")
      (LABEL_TAC "pi'fun")) THENL
   [CONJ_TAC THENL
     [USE_THEN "coh" (MP_TAC o SPEC `pi:A` o CONJUNCT2 o
                      REWRITE_RULE[ecohenp]) THEN
      ANTS_TAC THENL [USE_THEN "piD" ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> USE_THEN "piP"
                 (ACCEPT_TAC o CONJUNCT1 o CONJUNCT2 o EQ_MP th));
      USE_THEN "coh" (MP_TAC o SPEC `pi':A` o CONJUNCT2 o
                      REWRITE_RULE[ecohenp]) THEN
      ANTS_TAC THENL [USE_THEN "pi'D" ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> USE_THEN "pi'P"
                 (ACCEPT_TAC o CONJUNCT1 o CONJUNCT2 o EQ_MP th))];
    ALL_TAC] THEN
  (* KEY: an element of pi' is in pi, or its index is a' *)
  SUBGOAL_THEN
   `!z' u w'. z' IN D /\ u IN D /\ w' IN D /\ (E:A->A->bool) z' pi' /\
       eopair D E u w' z'
              ==> E z' pi \/ (?b6. b6 IN D /\ eopair D E a' b6 u)`
   (LABEL_TAC "KEY") THENL
   [MAP_EVERY X_GEN_TAC [`z':A`;`u:A`;`w':A`] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "z'D")
               (CONJUNCTS_THEN2 (LABEL_TAC "uD")
      (CONJUNCTS_THEN2 (LABEL_TAC "w'D")
       (CONJUNCTS_THEN2 (LABEL_TAC "z'pi'") (LABEL_TAC "opz'"))))) THEN
    USE_THEN "pi'img" (MP_TAC o SPEC `z':A`) THEN
    ANTS_TAC THENL [USE_THEN "z'D" ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "z'pi'" (MP_TAC o EQ_MP th)) THEN
    DISCH_THEN(X_CHOOSE_THEN `z0:A` (CONJUNCTS_THEN2 (LABEL_TAC "z0D")
        (CONJUNCTS_THEN2 (LABEL_TAC "z0pi")
      (LABEL_TAC "muz")))) THEN
    USE_THEN "mch" (MP_TAC o SPECL [`z0:A`;`z':A`]) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "muz" (MP_TAC o EQ_MP th)) THEN
    DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
               (MP_TAC o REWRITE_RULE[mucirel])) THEN
    DISCH_THEN(X_CHOOSE_THEN `b3:A` (X_CHOOSE_THEN `b4:A`
        (X_CHOOSE_THEN `b5:A` (X_CHOOSE_THEN `b6:A`
      (X_CHOOSE_THEN `b7:A` (X_CHOOSE_THEN `b8:A`
