        (CONJUNCTS_THEN2 (LABEL_TAC "b4D")
         (CONJUNCTS_THEN2 (LABEL_TAC "b5D") (CONJUNCTS_THEN2 (LABEL_TAC "b6D")
          (CONJUNCTS_THEN2 (LABEL_TAC "b7D") (CONJUNCTS_THEN2 (LABEL_TAC "b8D")
            (CONJUNCTS_THEN2 (LABEL_TAC "o53")
             (CONJUNCTS_THEN2 (LABEL_TAC "o34")
              (CONJUNCTS_THEN2 (LABEL_TAC "sg57")
               (CONJUNCTS_THEN2 (LABEL_TAC "o768")
                (LABEL_TAC "o84"))))))))))))))))) THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`u:A`;`w':A`;`b8:A`;`b4:A`;`z':A`]
           EOPAIR_INJ) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (SUBST_ALL_TAC o SYM) (SUBST_ALL_TAC o SYM)) THEN
    USE_THEN "TCH" (MP_TAC o SPECL [`b5:A`;`b7:A`]) THEN
