      (DISJ_CASES_THEN2 (CONJUNCTS_THEN2 SUBST_ALL_TAC SUBST_ALL_TAC)
         (CONJUNCTS_THEN2 (LABEL_TAC "n5a")
          (CONJUNCTS_THEN2 (LABEL_TAC "n5a'") SUBST_ALL_TAC)))) THENL
     [DISJ2_TAC THEN EXISTS_TAC `b6:A` THEN CONJ_TAC THEN
      FIRST_ASSUM ACCEPT_TAC;
      USE_THEN "FRESH" (MP_TAC o SPECL [`z0:A`;`b3:A`;`w':A`;
          `a':A`;`b6:A`]) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      REWRITE_TAC[]];
      DISJ1_TAC THEN
      SUBGOAL_THEN `b3:A = u` SUBST_ALL_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`b5:A`;`b6:A`;`b3:A`;`u:A`]
               EOPAIR_UNIQUE) THEN
        ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                        DISCH_THEN ACCEPT_TAC];
        ALL_TAC] THEN
      SUBGOAL_THEN `z0:A = z'` (fun th -> USE_THEN "z0pi"
          (ACCEPT_TAC o REWRITE_RULE[th])) THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`u:A`;`w':A`;`z0:A`;`z':A`]
             EOPAIR_UNIQUE) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN ACCEPT_TAC]];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`pi:A`;`pi':A`] EBUNION_EXISTS) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `rho:A` (LABEL_TAC "un")) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`pi:A`;`pi':A`;`rho:A`]
         EBUNION_MEM) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "rhoD") (LABEL_TAC "rhoch")) THEN
  SUBGOAL_THEN `efunctional D (E:A->A->bool) rho` (LABEL_TAC "rhofun") THENL
   [REWRITE_TAC[efunctional] THEN
    MAP_EVERY X_GEN_TAC [`z:A`;`z':A`;`u:A`;`w:A`;`w':A`] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "zD")
               (CONJUNCTS_THEN2 (LABEL_TAC "z'D")
                (CONJUNCTS_THEN2 (LABEL_TAC "uD")
      (CONJUNCTS_THEN2 (LABEL_TAC "wD") (CONJUNCTS_THEN2 (LABEL_TAC "w'D")
