      DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "oa'")
                 (X_CHOOSE_THEN `ww:A` (CONJUNCTS_THEN2 (LABEL_TAC "wwD")
          (LABEL_TAC "opv")))) THEN
      USE_THEN "FRESH" (MP_TAC o SPECL [`v:A`;`u:A`;`ww:A`;`a':A`;`b6:A`]) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      REWRITE_TAC[]];
      ALL_TAC] THEN
    USE_THEN "rhoch" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [USE_THEN "zD" ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "zrho" (MP_TAC o EQ_MP th)) THEN
