                      DISCH_THEN ACCEPT_TAC];
      (* z in pi', z' in pi *)
      USE_THEN "KEY" (MP_TAC o SPECL [`z:A`;`u:A`;`w:A`]) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "zpi")
        (X_CHOOSE_THEN `b6:A` (CONJUNCTS_THEN2 (LABEL_TAC "b6D")
                               (LABEL_TAC "oa'u")))) THENL
       [USE_THEN "pifun" (MP_TAC o REWRITE_RULE[efunctional]) THEN
        DISCH_THEN(MP_TAC o SPECL [`z:A`;`z':A`;`u:A`;`w:A`;`w':A`]) THEN
        ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                        DISCH_THEN ACCEPT_TAC];
        USE_THEN "noidx" (MP_TAC o SPEC `z':A`) THEN
        ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
