        ANTS_TAC THENL [USE_THEN "b6D" ACCEPT_TAC; ALL_TAC] THEN
        MATCH_MP_TAC(TAUT `p ==> ~p ==> q`) THEN CONJ_TAC THENL
            [USE_THEN "oa'u" ACCEPT_TAC; ALL_TAC] THEN
        EXISTS_TAC `w':A` THEN CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC];
      (* z in pi, z' in pi' *)
      USE_THEN "KEY" (MP_TAC o SPECL [`z':A`;`u:A`;`w':A`]) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "z'pi")
        (X_CHOOSE_THEN `b6:A` (CONJUNCTS_THEN2 (LABEL_TAC "b6D")
                               (LABEL_TAC "oa'u")))) THENL
       [USE_THEN "pifun" (MP_TAC o REWRITE_RULE[efunctional]) THEN
        DISCH_THEN(MP_TAC o SPECL [`z:A`;`z':A`;`u:A`;`w:A`;`w':A`]) THEN
        ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                        DISCH_THEN ACCEPT_TAC];
        USE_THEN "noidx" (MP_TAC o SPEC `z:A`) THEN
        ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
        DISCH_THEN(MP_TAC o SPEC `b6:A`) THEN
        ANTS_TAC THENL [USE_THEN "b6D" ACCEPT_TAC; ALL_TAC] THEN
        MATCH_MP_TAC(TAUT `p ==> ~p ==> q`) THEN CONJ_TAC THENL
            [USE_THEN "oa'u" ACCEPT_TAC; ALL_TAC] THEN
        EXISTS_TAC `w:A` THEN CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC];
      (* both in pi' *)
      USE_THEN "pi'fun" (MP_TAC o REWRITE_RULE[efunctional]) THEN
      DISCH_THEN(MP_TAC o SPECL [`z:A`;`z':A`;`u:A`;`w:A`;`w':A`]) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN ACCEPT_TAC]];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`ci:A`;`om:A`;`P:A`;`pi:A`;`pi':A`;
                `rho:A`] COHEN_UNION_IS_CONDITION) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                  DISCH_THEN(LABEL_TAC "rhoP")] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leqp rho pi /\
      erel D E leqp rho pi'` (CONJUNCTS_THEN2 (LABEL_TAC "rhopi")
      (LABEL_TAC "rhopi'")) THENL
   [CONJ_TAC THEN (MATCH_MP_TAC ELEQP_EREL_INTRO THEN EXISTS_TAC `P:A` THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
