                          (LABEL_TAC "x'op")) THENL
   [CONJ_TAC THENL
     [USE_THEN "ros" (MP_TAC o SPEC `x:A` o CONJUNCT2 o
                      REWRITE_RULE[eroset]) THEN
      ANTS_TAC THENL [USE_THEN "xD" ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> USE_THEN "xB"
                 (ACCEPT_TAC o CONJUNCT1 o CONJUNCT2 o EQ_MP th));
      USE_THEN "ros" (MP_TAC o SPEC `x':A` o CONJUNCT2 o
