   [USE_THEN "rhoD" ACCEPT_TAC;
    USE_THEN "rhoP" ACCEPT_TAC;
    USE_THEN "xop" (MP_TAC o SPECL [`pi:A`;`rho:A`] o REWRITE_RULE[eopen]) THEN
