                    DISCH_THEN ACCEPT_TAC];
    USE_THEN "x'op" (MP_TAC o SPECL [`pi':A`;`rho:A`] o
                     REWRITE_RULE[eopen]) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN ACCEPT_TAC]]);;

(* ===================================================================== *)
(* S6-E4 : FULLNAME_MEM_TOP, NCR_TOPLB (b <= G), and NCR_MAIN -- for every *)
(* HS y, [[CFF(S,y)]]^HS = BOT (the ~AC core: no HS name is a choice       *)
(* relation for the family S).                                              *)
(* ===================================================================== *)
let FULLNAME_MEM_TOP = prove
 (`!D (E:A->A->bool) B leq onebee cn s z.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
     onebee IN D /\ E onebee B /\ etop D E B leq onebee /\
     cn IN D /\ s IN D /\ bname D E B s /\ eapply D E cn s onebee /\
     z IN D /\ ebv_in D E B leq s cn z
     ==> etop D E B leq z`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`s:A`;`s:A`]
         EBV_EQ_VAL_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `es:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `etop D (E:A->A->bool) B leq es` ASSUME_TAC THENL
   [MATCH_MP_TAC EBV_EQ_REFL THEN EXISTS_TAC `s:A` THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq es z` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
                         `cn:A`;`s:A`;`s:A`;`z:A`;`es:A`]
       EFULLNAME_IN_GE_ELT) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) z B` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`s:A`;`cn:A`;
                         `z:A`] EBV_IN_IN_B) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[etop] THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `t:A` THEN STRIP_TAC THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`t:A`;`es:A`;
                       `z:A`] EPORDER_TRANS) THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC ETOP_GE THEN EXISTS_TAC `B:A` THEN ASM_REWRITE_TAC[]);;

let NCR_TOPLB = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X v Sh.
     hsbundle D E w1 om tw ii ci P leqp B inclB onebee X /\
     valuation D v /\ (!i. hsname D E B w1 X (v i)) /\ Sh IN D /\
         hsname D E B w1 X Sh /\
     etop D E B inclB (bvalf_HS D (E:A->A->bool) B inclB w1 X
                       ((1 |-> (Sh:A)) (v:num->A)) (1 %% 0))
     ==> erel D E inclB (bvalf_HS D (E:A->A->bool) B inclB w1 X (v:num->A)
                         (!! 1 ((1 %% 0) --> ?? 2 (((2 %% 1) &&
         ?? 5 (opair_form 1 2 5 && (5 %% 4))) &&
         ?? 3 ((Eq 3 2) && !! 2 (((2 %% 1) &&
         ?? 5 (opair_form 1 2 5 && (5 %% 4))) --> Eq 2 3))))))
         (bvalf_HS D (E:A->A->bool) B inclB w1 X ((1 |-> (Sh:A)) (v:num->A))
          (?? 2 (((2 %% 1) && ?? 5 (opair_form 1 2 5 && (5 %% 4))) &&
                 ?? 3 ((Eq 3 2) && !! 2 (((2 %% 1) &&
         ?? 5 (opair_form 1 2 5 && (5 %% 4))) --> Eq 2 3)))))`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "hsb")
             (CONJUNCTS_THEN2 (LABEL_TAC "vv")
              (CONJUNCTS_THEN2 (LABEL_TAC "hv")
               (CONJUNCTS_THEN2 (LABEL_TAC "ShD")
                (CONJUNCTS_THEN2 (LABEL_TAC "hsSh") (LABEL_TAC "top1")))))) THEN
  FIRST_ASSUM(fun th -> let cs = CONJUNCTS(REWRITE_RULE[hsbundle] th)
                        and cb = CONJUNCTS(MATCH_MP HSB_CBA th) in
    MAP_EVERY ASSUME_TAC [el 0 cs; el 1 cs; el 3 cs; el 15 cs; el 16 cs;
                          el 17 cs; el 18 cs; el 19 cs; el 0 cb; el 1 cb]) THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B inclB /\
      eporder D E B inclB` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((1 |-> (Sh:A)) (v:num->A)) /\
      (!i. hsname D (E:A->A->bool) B w1 X (((1 |-> (Sh:A)) (v:num->A)) i))`
     (CONJUNCTS_THEN2 (LABEL_TAC "vu") (LABEL_TAC "hu")) THENL
     [CONJ_TAC THENL
       [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC) THEN
        FIRST_ASSUM ACCEPT_TAC;
        REPEAT(MATCH_MP_TAC HSNAMEVAL_VALMOD THEN CONJ_TAC) THEN
            FIRST_ASSUM ACCEPT_TAC];
      ALL_TAC] THEN
  SUBGOAL_THEN `(bvalf_HS D (E:A->A->bool) B inclB w1 X (v:num->A)
                 (!! 1 ((1 %% 0) --> ?? 2 (((2 %% 1) &&
      ?? 5 (opair_form 1 2 5 && (5 %% 4))) &&
      ?? 3 ((Eq 3 2) && !! 2 (((2 %% 1) && ?? 5 (opair_form 1 2 5 && (5 %% 4)))
      --> Eq 2 3)))))) IN D /\ (E:A->A->bool)
      (bvalf_HS D (E:A->A->bool) B inclB w1 X (v:num->A)
