      ALL_TAC] THEN
  SUBGOAL_THEN `(bvalf_HS D (E:A->A->bool) B inclB w1 X
                 ((1 |-> (Sh:A)) (v:num->A)) (?? 2
      (((2 %% 1) && ?? 5 (opair_form 1 2 5 && (5 %% 4))) &&
       ?? 3 ((Eq 3 2) && !! 2 (((2 %% 1) && ?? 5 (opair_form 1 2 5 && (5 %% 4)))
      --> Eq 2 3))))) IN D /\ (E:A->A->bool)
      (bvalf_HS D (E:A->A->bool) B inclB w1 X ((1 |-> (Sh:A)) (v:num->A))
       (?? 2 (((2 %% 1) && ?? 5 (opair_form 1 2 5 && (5 %% 4))) &&
