      (CONJUNCTS_THEN2 (LABEL_TAC "T1D") (LABEL_TAC "T1B")) THENL
     [CONJ_TAC THENL
       [MP_TAC(ISPECL [`1 %% 0`;`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;
                       `w1:A`;`X:A`;`(1 |-> (Sh:A)) (v:num->A)`]
           BVALF_HS_SPEC) THEN
        ANTS_TAC THENL [REPEAT CONJ_TAC THEN
                        FIRST_ASSUM ACCEPT_TAC; SIMP_TAC[]];
        MATCH_MP_TAC BVALF_HS_IN_B THEN REPEAT CONJ_TAC THEN
            FIRST_ASSUM ACCEPT_TAC];
      ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) inclB
      (bvalf_HS D (E:A->A->bool) B inclB w1 X (v:num->A)
       (!! 1 ((1 %% 0) --> ?? 2 (((2 %% 1) &&
      ?? 5 (opair_form 1 2 5 && (5 %% 4))) &&
