(* ===================================================================== *)
(* S6-E5 : NCR_MAIN -- THE ~AC BOOLEAN CORE.  For the family S (NB_FAMILY) *)
(* and ANY hereditarily symmetric y, the Boolean value of the choice-      *)
(* relation formula CFF at (0..:=S, 4:=y) is BOTTOM.  y has a countable    *)
(* support e; the witness member Shat_e of S forces (NCR_TOPLB) that y     *)
(* picks a real r_a, a IN w1\e (NCR_SOME); a condition pi below that      *)
(* choice, a fresh index a' (FRESH_INDEX) and the transposition (a a')     *)
(* fixing e, y, S, Shat_e (TRANSPOSITION_EXISTS, SYM_BVALF_HS_PERM) give a *)
(* common extension rho (COND_SWAP) forcing that y picks both r_a and      *)
(* r_a', contradicting uniqueness (NCR_UNIQ, NB_REAL_DISTINCT).            *)
(* ===================================================================== *)
let NCR_MAIN = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X embf onetw ztw
  realfn fa fy sa ysa Z S y v.
     nbundle D E w1 om tw ii ci P leqp B inclB onebee X embf onetw ztw realfn /\
     fa IN D /\ fy IN D /\ eordinal D E fa /\ ebnstage D E B fa fy /\
     (!a r. a IN D /\ r IN D /\ eapply D E realfn a r ==> E r fy) /\
     esuc D E fa sa /\ ysa IN D /\ ebnstage D E B sa ysa /\
     Z IN D /\ (!z. z IN D ==> (E z Z <=> E z ysa /\ hsname D E B w1 X z /\
                ?t. t IN D /\ ?p. p IN D /\ E p z /\
                    eopair D (E:A->A->bool) t onebee p)) /\
     S IN D /\ eisfun D E S /\ (!s. s IN D /\ E s Z
         ==> eapply D E S s onebee) /\
               (!z. z IN D ==> (E z S <=> ?s. s IN D /\ E s Z /\
                                eopair D (E:A->A->bool) s onebee z)) /\
     hsname D E B w1 X S /\
     (!sg muci muP autB. sg IN D /\ eperm D E w1 sg /\
         pbundle D E ci P leqp B inclB sg muci muP autB
             ==> eautn D E B autB S S) /\
     y IN D /\ hsname D E B w1 X y /\
     valuation D v /\ (!i. hsname D E B w1 X (v i)) /\
         (!i. ~(i = 4) ==> v i = S) /\ v 4 = y
     ==> ebot D E B inclB (bvalf_HS D (E:A->A->bool) B inclB w1 X (v:num->A)
                           (!! 1 ((1 %% 0) --> ?? 2
         (((2 %% 1) && ?? 5 (opair_form 1 2 5 && (5 %% 4))) &&
          ?? 3 ((Eq 3 2) && !! 2 (((2 %% 1) &&
         ?? 5 (opair_form 1 2 5 && (5 %% 4))) --> Eq 2 3))))))`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "nb")
             (CONJUNCTS_THEN2 (LABEL_TAC "faD")
              (CONJUNCTS_THEN2 (LABEL_TAC "fyD")
               (CONJUNCTS_THEN2 (LABEL_TAC "faord")
                (CONJUNCTS_THEN2 (LABEL_TAC "stf")
                 (CONJUNCTS_THEN2 (LABEL_TAC "Rfy")
                  (CONJUNCTS_THEN2 (LABEL_TAC "suc")
                   (CONJUNCTS_THEN2 (LABEL_TAC "ysaD")
                    (CONJUNCTS_THEN2 (LABEL_TAC "sts")
