   [USE_THEN "coh" (ACCEPT_TAC o CONJUNCT1 o
                    REWRITE_RULE[ecohenp]); ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`B:A`;`m:A`;`m2:A`;
                `rho:A`] RO_COMPAT_INTER) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `w0:A` (CONJUNCTS_THEN2 (LABEL_TAC "w0D")
      (CONJUNCTS_THEN2 (LABEL_TAC "w0B")
    (CONJUNCTS_THEN2 (LABEL_TAC "rhow0")
     (CONJUNCTS_THEN2 (LABEL_TAC "w0m") (LABEL_TAC "w0m2")))))) THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) inclB w0 m /\
      erel D E inclB w0 m2` (CONJUNCTS_THEN2 (LABEL_TAC "lw0m")
      (LABEL_TAC "lw0m2")) THENL
   [CONJ_TAC THEN MATCH_MP_TAC EINCL_EREL_INTRO THEN EXISTS_TAC `B:A` THEN
    REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  (* w0 is BOT by the uniqueness core *)
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;`ii:A`;`ci:A`;
                `P:A`;`leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;
      `(1 |-> (Sh:A)) (v:num->A)`;`r:A`;`r':A`;`w0:A`] NCR_UNIQ) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THENL
     [SUBGOAL_THEN `(bvalf_HS D (E:A->A->bool) B inclB w1 X
                     ((2 |-> (r:A)) ((1 |-> (Sh:A)) (v:num->A))) (2 %% 1)) IN D
         /\ (E:A->A->bool) (bvalf_HS D (E:A->A->bool) B inclB w1 X
                            ((2 |-> (r:A)) ((1 |-> (Sh:A)) (v:num->A)))
         (2 %% 1)) B` (CONJUNCTS_THEN2 (LABEL_TAC "MrD")
                       (LABEL_TAC "MrB")) THENL
     [CONJ_TAC THENL
       [MP_TAC(ISPECL [`2 %% 1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;
                       `w1:A`;`X:A`;`(2 |-> (r:A)) ((1 |-> (Sh:A)) (v:num->A))`]
           BVALF_HS_SPEC) THEN
        ANTS_TAC THENL [REPEAT CONJ_TAC THEN
                        FIRST_ASSUM ACCEPT_TAC; SIMP_TAC[]];
        MATCH_MP_TAC BVALF_HS_IN_B THEN REPEAT CONJ_TAC THEN
            FIRST_ASSUM ACCEPT_TAC];
      ALL_TAC] THEN
      MATCH_MP_TAC FULLNAME_MEM_TOP THEN
          MAP_EVERY EXISTS_TAC [`onebee:A`;`Sh:A`;`r:A`] THEN
      REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THENL
       [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
        REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
        USE_THEN "Shap" MATCH_MP_TAC THEN CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
        MP_TAC(ISPECL [`2`;`1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;
                       `w1:A`;`X:A`;`(2 |-> (r:A)) ((1 |-> (Sh:A)) (v:num->A))`]
            BVALF_HS_MEM) THEN
        ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                        REWRITE_TAC[VALMOD; ARITH_EQ]]];
      SUBGOAL_THEN `(bvalf_HS D (E:A->A->bool) B inclB w1 X
                     ((2 |-> (r':A)) ((1 |-> (Sh:A)) (v:num->A))) (2 %% 1)) IN D
          /\ (E:A->A->bool) (bvalf_HS D (E:A->A->bool) B inclB w1 X
                             ((2 |-> (r':A)) ((1 |-> (Sh:A)) (v:num->A)))
          (2 %% 1)) B` (CONJUNCTS_THEN2 (LABEL_TAC "Mr'D")
                        (LABEL_TAC "Mr'B")) THENL
     [CONJ_TAC THENL
       [MP_TAC(ISPECL [`2 %% 1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;
                       `w1:A`;`X:A`;`(2 |-> (r':A))
           ((1 |-> (Sh:A)) (v:num->A))`] BVALF_HS_SPEC) THEN
        ANTS_TAC THENL [REPEAT CONJ_TAC THEN
                        FIRST_ASSUM ACCEPT_TAC; SIMP_TAC[]];
        MATCH_MP_TAC BVALF_HS_IN_B THEN REPEAT CONJ_TAC THEN
            FIRST_ASSUM ACCEPT_TAC];
      ALL_TAC] THEN
      MATCH_MP_TAC FULLNAME_MEM_TOP THEN
          MAP_EVERY EXISTS_TAC [`onebee:A`;`Sh:A`;`r':A`] THEN
      REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THENL
       [MATCH_MP_TAC HSNAME_BNAME THEN MAP_EVERY EXISTS_TAC [`w1:A`;`X:A`] THEN
        REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
        USE_THEN "Shap" MATCH_MP_TAC THEN CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
        MP_TAC(ISPECL [`2`;`1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;
                       `w1:A`;`X:A`;`(2 |-> (r':A))
            ((1 |-> (Sh:A)) (v:num->A))`] BVALF_HS_MEM) THEN
        ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                        REWRITE_TAC[VALMOD; ARITH_EQ]]];
      X_GEN_TAC `e:A` THEN DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "eD")
          (LABEL_TAC "eeq")) THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;`ii:A`;
                    `ci:A`;`P:A`;`leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;
          `embf:A`;`onetw:A`;`ztw:A`;`realfn:A`;`a:A`;`a':A`;`r:A`;`r':A`;`e:A`]
          NB_REAL_DISTINCT) THEN
      ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
      REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      DISCH_THEN SUBST_ALL_TAC THEN USE_THEN "a'a" (MP_TAC) THEN REWRITE_TAC[];
      MATCH_MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w0:A`;
                          `bvalf_HS D (E:A->A->bool) B inclB w1 X (v:num->A)
          (!! 1 ((1 %% 0) --> ?? 2 (((2 %% 1) &&
          ?? 5 (opair_form 1 2 5 && (5 %% 4))) &&
          ?? 3 ((Eq 3 2) && !! 2 (((2 %% 1) &&
          ?? 5 (opair_form 1 2 5 && (5 %% 4))) --> Eq 2 3)))))`;
          `bvalf_HS D (E:A->A->bool) B inclB w1 X ((1 |-> (Sh:A)) (v:num->A))
          (?? 2 (((2 %% 1) && ?? 5 (opair_form 1 2 5 && (5 %% 4))) &&
                 ?? 3 ((Eq 3 2) && !! 2 (((2 %% 1) &&
          ?? 5 (opair_form 1 2 5 && (5 %% 4))) --> Eq 2 3))))`]
          EPORDER_TRANS) THEN
    REPEAT CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC; FIRST_ASSUM ACCEPT_TAC; FIRST_ASSUM ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC; FIRST_ASSUM ACCEPT_TAC; FIRST_ASSUM ACCEPT_TAC;
      MATCH_MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w0:A`;
                          `m:A`;`bvalf_HS D (E:A->A->bool) B inclB w1 X
          (v:num->A) (!! 1 ((1 %% 0) --> ?? 2
                            (((2 %% 1) && ?? 5 (opair_form 1 2 5 && (5 %% 4)))
                             && ?? 3 ((Eq 3 2) && !! 2
          (((2 %% 1) && ?? 5 (opair_form 1 2 5 && (5 %% 4))) --> Eq 2 3)))))`]
          EPORDER_TRANS) THEN
    REPEAT CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC; FIRST_ASSUM ACCEPT_TAC; FIRST_ASSUM ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC; FIRST_ASSUM ACCEPT_TAC; FIRST_ASSUM ACCEPT_TAC;
      USE_THEN "lw0m" ACCEPT_TAC; USE_THEN "mb" ACCEPT_TAC];
          USE_THEN "bG" ACCEPT_TAC];
      MATCH_MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w0:A`;
                          `m:A`;`bvalf_HS D (E:A->A->bool) B inclB w1 X
          ((2 |-> (r:A)) ((1 |-> (Sh:A)) (v:num->A)))
          (?? 5 (opair_form 1 2 5 && (5 %% 4)))`] EPORDER_TRANS) THEN
    REPEAT CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC; FIRST_ASSUM ACCEPT_TAC; FIRST_ASSUM ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC; FIRST_ASSUM ACCEPT_TAC; FIRST_ASSUM ACCEPT_TAC;
      USE_THEN "lw0m" ACCEPT_TAC; USE_THEN "mcr" ACCEPT_TAC];
      MATCH_MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w0:A`;
                          `m2:A`;`bvalf_HS D (E:A->A->bool) B inclB w1 X
          ((2 |-> (r':A)) ((1 |-> (Sh:A)) (v:num->A)))
          (?? 5 (opair_form 1 2 5 && (5 %% 4)))`] EPORDER_TRANS) THEN
    REPEAT CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC; FIRST_ASSUM ACCEPT_TAC; FIRST_ASSUM ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC; FIRST_ASSUM ACCEPT_TAC; FIRST_ASSUM ACCEPT_TAC;
      USE_THEN "lw0m2" ACCEPT_TAC; USE_THEN "m2cr'" ACCEPT_TAC]];
    DISCH_THEN(LABEL_TAC "w0bot")] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`B:A`;`inclB:A`;
                `w0:A`;`rho:A`] BOT_NOMEM) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  USE_THEN "rhow0" (fun th -> REWRITE_TAC[th]));;

(* ===================================================================== *)
(* S6-F (part 1) : semantic readers for the N-level ~AC argument.          *)
(* FV_CHOICE_AX (choice_ax is a sentence), QREP_HS_IN_QDOM (HS names give  *)
(* points of the quotient), HOLDS_CFF_PP / HOLDS_CFF (the choice-relation  *)
(* formula CFF of NCR_MAIN says exactly what CHOICE_REL_INTERNAL delivers). *)
(* ===================================================================== *)
let FV_CHOICE_AX = prove
 (`FV choice_ax = {}`,
  REWRITE_TAC[choice_ax; FV; FV_CLAUSES] THEN
  REWRITE_TAC[EXTENSION; IN_UNION; IN_DELETE; IN_INSERT; NOT_IN_EMPTY] THEN
  ARITH_TAC);;

let QREP_HS_IN_QDOM = prove
 (`!D (E:A->A->bool) B leq w1 X U a.
     a IN D /\ hsname D E B w1 X a
     ==> qrep_HS D E B leq w1 X U a IN qdom_HS D E B leq w1 X U`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[IN] THEN REWRITE_TAC[qdom_HS] THEN
  EXISTS_TAC `a:A` THEN ASM_REWRITE_TAC[]);;

let HOLDS_CFF_PP = prove
 (`!D (E:A->A->bool) v.
     valuation D v
     ==> (holds D E v ((2 %% 1) && ?? 5 (opair_form 1 2 5 && (5 %% 4))) <=>
          E (v 2) (v 1) /\ ?p. p IN D /\ eopair D E (v 1) (v 2) p
              /\ E p (v 4))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[HOLDS_AND; HOLDS_EX; holds;
      VALMOD; ARITH_EQ] THEN
  SUBGOAL_THEN `!p:A. p IN D ==> (holds D E ((5 |-> p) v) (opair_form 1 2 5) <=>
                                  eopair D E ((v:num->A) 1) (v 2) p)`
    (fun th -> MESON_TAC[th]) THEN
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`(5 |-> (p:A)) v`;`1`;`2`;`5`]
         HOLDS_OPAIR_FORM) THEN
  ANTS_TAC THENL [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
                  DISCH_THEN SUBST1_TAC] THEN
  REWRITE_TAC[VALMOD; ARITH_EQ]);;

let HOLDS_CFF = prove
 (`!D (E:A->A->bool) v.
     valuation D v
     ==> (holds D E v (!! 1 ((1 %% 0) -->
                             ?? 2 (((2 %% 1) && ?? 5
         (opair_form 1 2 5 && (5 %% 4))) &&
         ?? 3 ((Eq 3 2) && !! 2 (((2 %% 1) &&
         ?? 5 (opair_form 1 2 5 && (5 %% 4))) --> Eq 2 3)))))
          <=> !x. x IN D /\ E x (v 0)
                 ==> ?z. z IN D /\ E z x /\
                         (?p. p IN D /\ eopair D E x z p /\ E p (v 4)) /\
                         !z'. z' IN D /\ E z' x /\
                              (?p'. p' IN D /\ eopair D E x z' p' /\ E p' (v 4))
                              ==> z' = z)`,
  REPEAT STRIP_TAC THEN
  ABBREV_TAC `pp = (2 %% 1) && ?? 5 (opair_form 1 2 5 && (5 %% 4))` THEN
  SUBGOAL_THEN `!x z:A. x IN D /\ z IN D
                  ==> (holds D E ((2 |-> z) ((1 |-> x) v)) pp <=>
                       E z x /\ ?p. p IN D /\ eopair D E x z p /\
                           E p ((v:num->A) 4))`
    (LABEL_TAC "pp1") THENL
   [MAP_EVERY X_GEN_TAC [`x:A`;`z:A`] THEN STRIP_TAC THEN EXPAND_TAC "pp" THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`(2 |-> (z:A)) ((1 |-> (x:A)) v)`]
           HOLDS_CFF_PP) THEN
    ANTS_TAC THENL
     [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC) THEN
      ASM_REWRITE_TAC[];
      DISCH_THEN SUBST1_TAC] THEN
    REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  SUBGOAL_THEN `!x z c d:A. x IN D /\ z IN D /\ c IN D /\ d IN D
                  ==> (holds D E ((2 |-> d) ((3 |-> c)
                      ((2 |-> z) ((1 |-> x) v)))) pp <=>
                       E d x /\ ?p. p IN D /\ eopair D E x d p /\
                           E p ((v:num->A) 4))`
    (LABEL_TAC "pp2") THENL
   [MAP_EVERY X_GEN_TAC [`x:A`;`z:A`;`c:A`;`d:A`] THEN STRIP_TAC THEN
    EXPAND_TAC "pp" THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;
                   `(2 |-> (d:A)) ((3 |-> (c:A))
                                   ((2 |-> (z:A)) ((1 |-> (x:A)) v)))`]
                       HOLDS_CFF_PP) THEN
    ANTS_TAC THENL
     [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC) THEN
      ASM_REWRITE_TAC[];
      DISCH_THEN SUBST1_TAC] THEN
    REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  REWRITE_TAC[holds; HOLDS_EX; HOLDS_AND; VALMOD; ARITH_EQ] THEN
  EQ_TAC THENL
   [DISCH_THEN(LABEL_TAC "H") THEN X_GEN_TAC `x:A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "xD") (LABEL_TAC "x0")) THEN
    USE_THEN "H" (MP_TAC o SPEC `x:A`) THEN
    ANTS_TAC THENL [USE_THEN "xD" ACCEPT_TAC; ALL_TAC] THEN
    ANTS_TAC THENL [USE_THEN "x0" ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `z:A` (CONJUNCTS_THEN2 (LABEL_TAC "zD")
        (CONJUNCTS_THEN2 (LABEL_TAC "hz")
      (X_CHOOSE_THEN `c:A` (CONJUNCTS_THEN2 (LABEL_TAC "cD")
                            (CONJUNCTS_THEN2 (LABEL_TAC "cz")
                             (LABEL_TAC "uq"))))))) THEN
    EXISTS_TAC `z:A` THEN
    USE_THEN "pp1" (MP_TAC o SPECL [`x:A`;`z:A`]) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "hz" (MP_TAC o EQ_MP th)) THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "zx") (LABEL_TAC "qz")) THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    X_GEN_TAC `z':A` THEN DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "z'D")
        (LABEL_TAC "z'q")) THEN
    USE_THEN "cz" (SUBST1_TAC o SYM) THEN
    USE_THEN "uq" (MATCH_MP_TAC o REWRITE_RULE[IMP_IMP]) THEN
    CONJ_TAC THENL [USE_THEN "z'D" ACCEPT_TAC; ALL_TAC] THEN
    USE_THEN "pp2" (MP_TAC o SPECL [`x:A`;`z:A`;`c:A`;`z':A`]) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN SUBST1_TAC] THEN
    USE_THEN "z'q" ACCEPT_TAC;
    DISCH_THEN(LABEL_TAC "H") THEN X_GEN_TAC `x:A` THEN
    DISCH_THEN(LABEL_TAC "xD") THEN DISCH_THEN(LABEL_TAC "x0") THEN
    USE_THEN "H" (MP_TAC o SPEC `x:A`) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `z:A` (CONJUNCTS_THEN2 (LABEL_TAC "zD")
        (CONJUNCTS_THEN2 (LABEL_TAC "zx")
      (CONJUNCTS_THEN2 (LABEL_TAC "qz") (LABEL_TAC "uq"))))) THEN
    EXISTS_TAC `z:A` THEN CONJ_TAC THENL
        [USE_THEN "zD" ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL
     [USE_THEN "pp1" (MP_TAC o SPECL [`x:A`;`z:A`]) THEN
      ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                      DISCH_THEN SUBST1_TAC] THEN
      CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
      ALL_TAC] THEN
    EXISTS_TAC `z:A` THEN REPEAT CONJ_TAC THENL
     [USE_THEN "zD" ACCEPT_TAC; REFL_TAC; ALL_TAC] THEN
    X_GEN_TAC `d:A` THEN DISCH_THEN(LABEL_TAC "dD") THEN
    USE_THEN "pp2" (MP_TAC o SPECL [`x:A`;`z:A`;`z:A`;`d:A`]) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN SUBST1_TAC] THEN
    DISCH_THEN(LABEL_TAC "dq") THEN
    USE_THEN "uq" MATCH_MP_TAC THEN
    CONJ_TAC THENL [USE_THEN "dD" ACCEPT_TAC; USE_THEN "dq" ACCEPT_TAC]]);;

(* ===================================================================== *)
(* S6-F (part 2) : HS_QUOT_NOT_AC -- the HS quotient N by ANY ultrafilter  *)
(* fails choice_ax at every valuation.  N |= ZF (HS_QUOT_MODEL_ZF); if     *)
(* N |= choice_ax then CHOICE_REL_INTERNAL applied to s = [S] (whose       *)
(* members are nonempty in N: FULLFAM_NE + LOS_HS) gives a choice relation *)
(* [y], i.e. N |= CFF at (0:=[S], 4:=[y]) (HOLDS_CFF), so by LOS_HS the    *)
(* Boolean value of CFF at (0:=S, 4:=y) is U-large -- but NCR_MAIN says it *)
(* is bottom, and bottom is never U-large (EULTRA_NOT_BOT).                *)
(* ===================================================================== *)
let HS_QUOT_NOT_AC = prove
 (`!D (E:A->A->bool) w1 om tw ii ci P leqp B inclB onebee X embf onetw
  ztw realfn U v.
     nbundle D E w1 om tw ii ci P leqp B inclB onebee X embf onetw ztw realfn /\
     eultra D E B inclB U /\ valuation (qdom_HS D E B inclB w1 X U) v
     ==> ~holds (qdom_HS D E B inclB w1 X U) (qmem D E B inclB U) v choice_ax`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "nb")
             (CONJUNCTS_THEN2 (LABEL_TAC "ult") (LABEL_TAC "vN"))) THEN
  DISCH_THEN(LABEL_TAC "acv") THEN
  USE_THEN "nb" (LABEL_TAC "hsb" o CONJUNCT1 o REWRITE_RULE[nbundle]) THEN
  USE_THEN "hsb" (fun th -> let cs = CONJUNCTS(REWRITE_RULE[hsbundle] th)
                        and cb = CONJUNCTS(MATCH_MP HSB_CBA th) in
    MAP_EVERY ASSUME_TAC [el 0 cs; el 1 cs; el 3 cs; el 15 cs;
                          el 16 cs; el 17 cs;
                          el 18 cs; el 19 cs; el 14 cs; el 0 cb; el 1 cb]) THEN
  (* N |= ZF *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;`ii:A`;
                 `ci:A`;`P:A`;`leqp:A`;
                 `B:A`;`inclB:A`;`onebee:A`;`X:A`;`U:A`] HS_QUOT_MODEL_ZF) THEN
  ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                  DISCH_THEN(LABEL_TAC "modN")] THEN
  (* choice_ax is a sentence: it holds at every N-valuation *)
  SUBGOAL_THEN `!w. valuation (qdom_HS D (E:A->A->bool) B inclB w1 X U) w
                    ==> holds (qdom_HS D E B inclB w1 X U)
                        (qmem D E B inclB U) w choice_ax`
    (LABEL_TAC "ac") THENL
   [X_GEN_TAC `w:num->A` THEN DISCH_TAC THEN
    MP_TAC(ISPECL [`qdom_HS D (E:A->A->bool) B inclB w1 X U`;
                   `qmem D (E:A->A->bool) B inclB U`;
                   `choice_ax`;`v:num->A`;`w:num->A`] HOLDS_VALUATION) THEN
    REWRITE_TAC[FV_CHOICE_AX; NOT_IN_EMPTY] THEN DISCH_THEN SUBST1_TAC THEN
    USE_THEN "acv" ACCEPT_TAC;
    ALL_TAC] THEN
  (* the family S *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;`ii:A`;
                 `ci:A`;`P:A`;`leqp:A`;
                 `B:A`;`inclB:A`;`onebee:A`;`X:A`;`embf:A`;`onetw:A`;`ztw:A`;
                     `realfn:A`] NB_FAMILY) THEN
  ANTS_TAC THENL [USE_THEN "nb" ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `fa:A` (X_CHOOSE_THEN `fy:A`
      (X_CHOOSE_THEN `sa:A` (X_CHOOSE_THEN `ysa:A`
    (X_CHOOSE_THEN `Z:A` (X_CHOOSE_THEN `S:A` (LABEL_TAC "fam"))))))) THEN
  USE_THEN "fam" (fun th -> let cs = CONJUNCTS th in
    MAP_EVERY (fun (s,i) -> LABEL_TAC s (el i cs))
      [("faD",0);("fyD",1);("faord",2);("stf",3);("Rfy",4);("suc",5);
       ("ysaD",6);("sts",7);
       ("ZD",8);("Zch",9);("SD",10);("Sfun",11);("Sap",12);("Sch",13);
           ("hsS",14);("Ssym",15)]) THEN
  SUBGOAL_THEN `!s. s IN D /\ (E:A->A->bool) s Z
                    ==> hsname D E B w1 X s /\
                        ?t. t IN D /\ ?p. p IN D /\ E p s /\
                            eopair D E t onebee p`
    (LABEL_TAC "Zmem") THENL
   [X_GEN_TAC `s:A` THEN STRIP_TAC THEN
    USE_THEN "Zch" (MP_TAC o SPEC `s:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> ACCEPT_TAC(CONJUNCT2(EQ_MP th
        (ASSUME `(E:A->A->bool) s Z`))));
    ALL_TAC] THEN
  (* the constant valuation at S *)
  SUBGOAL_THEN `valuation D (\i:num. (S:A))` (LABEL_TAC "vSv") THENL
   [REWRITE_TAC[valuation] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `!i:num. hsname D (E:A->A->bool) B w1 X ((\i:num. (S:A)) i)`
      (LABEL_TAC "vSh") THENL
   [GEN_TAC THEN BETA_TAC THEN USE_THEN "hsS" ACCEPT_TAC; ALL_TAC] THEN
  (* s = [S] is a point of N whose N-members are nonempty *)
  SUBGOAL_THEN `qrep_HS D (E:A->A->bool) B inclB w1 X U S IN qdom_HS D E
      B inclB w1 X U`
    (LABEL_TAC "sN") THENL
   [MATCH_MP_TAC QREP_HS_IN_QDOM THEN CONJ_TAC THEN
    FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `ubig D (E:A->A->bool) U
                  (bvalf_HS D E B inclB w1 X (\i:num. (S:A))
                   (!! 1 ((1 %% 0) --> ?? 2 (2 %% 1))))`
    (LABEL_TAC "neU") THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;`ii:A`;
                   `ci:A`;`P:A`;`leqp:A`;
                   `B:A`;`inclB:A`;`onebee:A`;`X:A`;`Z:A`;`S:A`;
                       `(\i:num. (S:A))`] FULLFAM_NE) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      BETA_TAC THEN REFL_TAC;
      DISCH_TAC] THEN
    MP_TAC(ISPECL [`!! 1 ((1 %% 0) --> ?? 2 (2 %% 1))`;`D:A->bool`;
                   `E:A->A->bool`;`B:A`;`inclB:A`;
                   `w1:A`;`X:A`;`U:A`;`(\i:num. (S:A))`] UBIG_BVALF_HS) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
                    DISCH_THEN SUBST1_TAC] THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`U:A`;
      `bvalf_HS D (E:A->A->bool) B inclB w1 X (\i:num. (S:A))
          (!! 1 ((1 %% 0) --> ?? 2 (2 %% 1)))`]
      EULTRA_TOP) THEN
    REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `!x. x IN qdom_HS D (E:A->A->bool) B inclB w1 X U /\
                    qmem D E B inclB U x (qrep_HS D E B inclB w1 X U S)
                    ==> ?z. z IN qdom_HS D E B inclB w1 X U /\
                        qmem D E B inclB U z x`
    (LABEL_TAC "neN") THENL
   [MP_TAC(ISPECL [`!! 1 ((1 %% 0) --> ?? 2 (2 %% 1))`;`D:A->bool`;
                   `E:A->A->bool`;`w1:A`;`om:A`;
                   `tw:A`;`ii:A`;`ci:A`;`P:A`;`leqp:A`;`B:A`;`inclB:A`;
                       `onebee:A`;`X:A`;`U:A`;
                   `(\i:num. (S:A))`] LOS_HS) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o snd o EQ_IMP_RULE) THEN
    ANTS_TAC THENL [USE_THEN "neU" ACCEPT_TAC; ALL_TAC] THEN
    REWRITE_TAC[holds; HOLDS_EX; VALMOD; ARITH_EQ] THEN MESON_TAC[];
    ALL_TAC] THEN
  (* a choice relation [y] for s in N *)
  MP_TAC(ISPECL [`qdom_HS D (E:A->A->bool) B inclB w1 X U`;
                 `qmem D (E:A->A->bool) B inclB U`;
                 `qrep_HS D (E:A->A->bool) B inclB w1 X U S`]
                     CHOICE_REL_INTERNAL) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `yq:A` (CONJUNCTS_THEN2 (LABEL_TAC "yqN")
      (LABEL_TAC "crel"))) THEN
  USE_THEN "yqN" (MP_TAC o REWRITE_RULE[qdom_HS] o REWRITE_RULE[IN]) THEN
  DISCH_THEN(X_CHOOSE_THEN `y:A` (CONJUNCTS_THEN2 (LABEL_TAC "yD")
    (CONJUNCTS_THEN2 (LABEL_TAC "hsy") (LABEL_TAC "yqe")))) THEN
  (* the valuation (0..:=S, 4:=y) *)
  SUBGOAL_THEN `valuation D ((4 |-> (y:A)) (\i:num. (S:A)))`
      (LABEL_TAC "vyv") THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THEN
    FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `!i. hsname D (E:A->A->bool) B w1 X
      (((4 |-> (y:A)) (\i:num. (S:A))) i)`
    (LABEL_TAC "vyh") THENL
   [GEN_TAC THEN REWRITE_TAC[VALMOD] THEN COND_CASES_TAC THENL
     [USE_THEN "hsy" ACCEPT_TAC; USE_THEN "hsS" ACCEPT_TAC]; ALL_TAC] THEN
  SUBGOAL_THEN `!i. ~(i = 4) ==> ((4 |-> (y:A)) (\i:num. (S:A))) i = S`
      (LABEL_TAC "vyS") THENL
   [GEN_TAC THEN DISCH_TAC THEN ASM_REWRITE_TAC[VALMOD]; ALL_TAC] THEN
  SUBGOAL_THEN `((4 |-> (y:A)) (\i:num. (S:A))) 4 = y` (LABEL_TAC "vy4") THENL
   [REWRITE_TAC[VALMOD]; ALL_TAC] THEN
  (* NCR_MAIN: the Boolean value of CFF there is bottom *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;`ii:A`;
                 `ci:A`;`P:A`;`leqp:A`;
                 `B:A`;`inclB:A`;`onebee:A`;`X:A`;`embf:A`;`onetw:A`;
                     `ztw:A`;`realfn:A`;
                 `fa:A`;`fy:A`;`sa:A`;`ysa:A`;`Z:A`;`S:A`;`y:A`;
                 `(4 |-> (y:A)) (\i:num. (S:A))`] NCR_MAIN) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; DISCH_TAC] THEN
  (* ... but CFF holds in N there, so its value is U-large *)
  SUBGOAL_THEN `valuation (qdom_HS D (E:A->A->bool) B inclB w1 X U)
                  (\i. qrep_HS D E B inclB w1 X U
                   (((4 |-> (y:A)) (\i:num. (S:A))) i))`
    (LABEL_TAC "qvN") THENL
   [REWRITE_TAC[valuation] THEN X_GEN_TAC `i:num` THEN BETA_TAC THEN
    MATCH_MP_TAC QREP_HS_IN_QDOM THEN CONJ_TAC THENL
     [USE_THEN "vyv" (fun th -> ACCEPT_TAC(SPEC `i:num`
         (REWRITE_RULE[valuation] th)));
      USE_THEN "vyh" (ACCEPT_TAC o SPEC `i:num`)];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`!! 1 ((1 %% 0) --> ?? 2
                        (((2 %% 1) && ?? 5 (opair_form 1 2 5 && (5 %% 4))) &&
                         ?? 3 ((Eq 3 2) && !! 2 (((2 %% 1) &&
      ?? 5 (opair_form 1 2 5 && (5 %% 4))) --> Eq 2 3))))`;
                 `D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;
                 `tw:A`;`ii:A`;`ci:A`;`P:A`;`leqp:A`;`B:A`;`inclB:A`;
                     `onebee:A`;`X:A`;`U:A`;
                 `(4 |-> (y:A)) (\i:num. (S:A))`] LOS_HS) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o fst o EQ_IMP_RULE) THEN
  ANTS_TAC THENL
   [MP_TAC(ISPECL [`qdom_HS D (E:A->A->bool) B inclB w1 X U`;
                   `qmem D (E:A->A->bool) B inclB U`;
                   `\i. qrep_HS D (E:A->A->bool) B inclB w1 X U
                       (((4 |-> (y:A)) (\i:num. (S:A))) i)`]
      HOLDS_CFF) THEN
    ANTS_TAC THENL [USE_THEN "qvN" ACCEPT_TAC; DISCH_THEN SUBST1_TAC] THEN
    REWRITE_TAC[VALMOD; ARITH_EQ] THEN
    USE_THEN "yqe" (SUBST1_TAC o SYM) THEN
    USE_THEN "crel" ACCEPT_TAC;
    ALL_TAC] THEN
  REWRITE_TAC[ubig] THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`U:A`;
    `bvalf_HS D (E:A->A->bool) B inclB w1 X ((4 |-> (y:A)) (\i:num. (S:A)))
        (!! 1 ((1 %% 0) --> ?? 2 (((2 %% 1) &&
        ?? 5 (opair_form 1 2 5 && (5 %% 4))) &&
        ?? 3 ((Eq 3 2) && !! 2 (((2 %% 1) &&
        ?? 5 (opair_form 1 2 5 && (5 %% 4))) --> Eq 2 3)))))`]
    EULTRA_NOT_BOT) THEN
  ASM_REWRITE_TAC[]);;

(* ===================================================================== *)
(* S7 (part 1) : COHEN_W1_EXISTS -- the Cohen algebra over ii = w1 x om,    *)
(* w1 = aleph_1 (the successor cardinal of om), value set tw = {0,1}.       *)
(* COHEN_CBA_FULL_EXISTS (godel_forcing.ml) with iibase := w1 instead       *)
(* of aleph_2, and without the ccc/bp/a2 parts the HS argument does not use.*)
(* ===================================================================== *)
let COHEN_W1_EXISTS = prove
 (`!D (E:A->A->bool).
     model D E ZF_AX /\ (!u:A. u IN D ==> elmem D E u)
     ==> ?om w1 tw onetw ztw ii ci P leqp B inclB z.
           eomega D E om /\ w1 IN D /\ ecardinal D E w1 /\
               eordinal D E w1 /\ E om w1 /\
           (!c'. c' IN D /\ E c' w1 ==> ~(ecardinal D E c' /\ E om c')) /\
           efin D E tw /\ E onetw tw /\ E ztw tw /\ ~(onetw = ztw) /\
           ecross D E w1 om ii /\ ecross D E ii tw ci /\ ecohenp D E ci om P /\
           eleqp D E P leqp /\ eroset D E P leqp B /\ eincl D E B inclB /\
           ecba D E B inclB /\ ebot D E B inclB z /\
               etop D E B inclB P /\ ~(z = P) /\
           B IN D /\ inclB IN D /\ P IN D /\ om IN D /\ onetw IN D /\ ztw IN D`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  (* om *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`] EOMEGA_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `om:A`) THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EOMEGA_IN); ALL_TAC] THEN
  (* w1 = aleph_1 = the successor cardinal of om *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`om:A`] ESUCCARD_EXISTS) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    MATCH_MP_TAC EOMEGA_ORDINAL THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `w1:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) w1` ASSUME_TAC THENL
   [MP_TAC(ASSUME `ecardinal D (E:A->A->bool) w1`) THEN
    REWRITE_TAC[ecardinal; ecardof] THEN STRIP_TAC THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* tw = {e0, {e0}} : 2-element finite set *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`] EEMPTY_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `e0:A`) THEN
  SUBGOAL_THEN `(e0:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EEMPTY_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`e0:A`;`e0:A`] EADJOIN_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `q1:A`) THEN
  SUBGOAL_THEN `(q1:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EADJOIN_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`q1:A`;`q1:A`] EADJOIN_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `q2:A`) THEN
  SUBGOAL_THEN `(q2:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EADJOIN_IN]; ALL_TAC] THEN
  (* membership facts for tw:=q2, onetw:=q1, ztw:=e0 *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`e0:A`;`e0:A`;`q1:A`]
         EADJOIN_MEM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "q1mem")) THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`q1:A`;`q1:A`;`q2:A`]
         EADJOIN_MEM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "q2mem")) THEN
  SUBGOAL_THEN `(E:A->A->bool) e0 q1` ASSUME_TAC THENL
   [USE_THEN "q1mem" (MP_TAC o SPEC `e0:A`) THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) q1 q2` ASSUME_TAC THENL
   [USE_THEN "q2mem" (MP_TAC o SPEC `q1:A`) THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) e0 q2` ASSUME_TAC THENL
   [USE_THEN "q2mem" (MP_TAC o SPEC `e0:A`) THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `~(q1:A = e0)` ASSUME_TAC THENL
   [DISCH_TAC THEN UNDISCH_TAC `eempty D (E:A->A->bool) e0` THEN
    REWRITE_TAC[eempty] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `efin D (E:A->A->bool) (q2:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`q1:A`;`q1:A`;`q2:A`]
                 EFIN_ADJOIN) THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`e0:A`;`e0:A`;`q1:A`]
                 EFIN_ADJOIN) THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`e0:A`] EFIN_EMPTY) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ii = w1 x om *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`] ECROSS_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `ii:A`) THEN
  SUBGOAL_THEN `(ii:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o GEN_REWRITE_RULE I
                [ecross]); ALL_TAC] THEN
  (* Cohen cba at (ii, tw, om) *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`ii:A`;`q2:A`;`om:A`]
         COHEN_CBA_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ci:A` (X_CHOOSE_THEN `P:A` (X_CHOOSE_THEN `leqp:A`
    (X_CHOOSE_THEN `B:A` (X_CHOOSE_THEN `inclB:A` (X_CHOOSE_THEN `z:A`
    STRIP_ASSUME_TAC)))))) THEN
  SUBGOAL_THEN `(P:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o GEN_REWRITE_RULE I
                [ecohenp]); ALL_TAC] THEN
  SUBGOAL_THEN `(B:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o GEN_REWRITE_RULE I
                [eroset]); ALL_TAC] THEN
  SUBGOAL_THEN `(inclB:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o GEN_REWRITE_RULE I
                [eincl]); ALL_TAC] THEN
  (* assemble *)
  MAP_EVERY EXISTS_TAC [`om:A`;`w1:A`;`q2:A`;`q1:A`;`e0:A`;`ii:A`;`ci:A`;`P:A`;
    `leqp:A`;`B:A`;`inclB:A`;`z:A`] THEN
  REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[]);;

(* ===================================================================== *)
(* S7 (part 2) : NBUNDLE_EXISTS -- from any model of ZF + V=L, the full    *)
(* S6 context: the hsbundle over the w1-Cohen algebra (onebee := P, the    *)
(* top of RO(P); X := ci UNION P), the RO-embedding embf, the two values  *)
(* onetw <> ztw of tw, and the real-name function realfn on w1; plus a     *)
(* bottom z <> top for EULTRA_EXISTS.  Mirrors forcing NOT_CH_FORCED.      *)
(* ===================================================================== *)
let NBUNDLE_EXISTS = prove
 (`!D (E:A->A->bool).
     model D E ZF_AX /\ (!u:A. u IN D ==> elmem D E u)
     ==> ?w1 om tw ii ci P leqp B inclB onebee X embf onetw ztw realfn z.
           nbundle D E w1 om tw ii ci P leqp B inclB onebee X embf
               onetw ztw realfn /\
           ecba D E B inclB /\ inclB IN D /\ ebot D E B inclB z /\
               ~(z = onebee)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`] COHEN_W1_EXISTS) THEN
  ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(DESTRUCT_TAC "@om w1 tw onetw ztw ii ci P leqp B inclB z. ctx")
      THEN
  REMOVE_THEN "ctx" STRIP_ASSUME_TAC THEN
  SUBGOAL_THEN `(tw:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o GEN_REWRITE_RULE I
                [efin]); ALL_TAC] THEN
  SUBGOAL_THEN `(ii:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o GEN_REWRITE_RULE I
                [ecross]); ALL_TAC] THEN
  SUBGOAL_THEN `(ci:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o GEN_REWRITE_RULE I
                [ecross]); ALL_TAC] THEN
  SUBGOAL_THEN `(leqp:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o GEN_REWRITE_RULE I
                [eleqp]); ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) P B` ASSUME_TAC THENL
      [ASM_MESON_TAC[ETOP_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B inclB` ASSUME_TAC THENL
   [MATCH_MP_TAC EBALG_IMP_PORDER THEN MATCH_MP_TAC ECBA_IMP_BALG THEN
    FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  (* X = ci UNION P *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`ci:A`;`P:A`] EBUNION_EXISTS) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `X:A` (LABEL_TAC "Xu")) THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`ci:A`;`P:A`;`X:A`] EBUNION_ALT) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  USE_THEN "Xu" (fun th -> REWRITE_TAC[th]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "Xch")) THEN
  SUBGOAL_THEN `!u. u IN D /\ (E:A->A->bool) u ci ==> E u X` ASSUME_TAC THENL
   [REPEAT STRIP_TAC THEN USE_THEN "Xch" (MP_TAC o SPEC `u:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; DISCH_THEN SUBST1_TAC] THEN
    DISJ1_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `!p. p IN D /\ (E:A->A->bool) p P ==> E p X` ASSUME_TAC THENL
   [REPEAT STRIP_TAC THEN USE_THEN "Xch" (MP_TAC o SPEC `p:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; DISCH_THEN SUBST1_TAC] THEN
    DISJ2_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  (* embf *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`B:A`;`ci:A`;
                `om:A`;`ii:A`;`tw:A`]
    EMBFUN_EXISTS) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `embf:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `eisfun D (E:A->A->bool) embf` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`ci:A`;
                        `embf:A`] EMBF_ISFUN) THEN
    REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `!cvs. cvs IN D /\ E cvs ci ==> ?b. b IN D /\
      eapply D (E:A->A->bool) embf cvs b`
    ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`B:A`;
                        `ci:A`;`om:A`;`ii:A`;
      `tw:A`;`embf:A`] EMBF_TOTAL) THEN REPEAT CONJ_TAC THEN
          FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `!cvs bb. cvs IN D /\ bb IN D /\
      eapply D (E:A->A->bool) embf cvs bb ==> E bb B`
    ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`B:A`;
                        `ci:A`;`om:A`;`ii:A`;
      `tw:A`;`embf:A`] EMBF_VAL_IN_B) THEN REPEAT CONJ_TAC THEN
          FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  (* realfn on w1 *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`ci:A`;
                `om:A`;`P:A`;`embf:A`;
    `w1:A`;`ii:A`;`tw:A`;`onetw:A`] REALFN_EXISTS) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `realfn:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (LABEL_TAC "rfch"))) THEN
  SUBGOAL_THEN `eisfun D (E:A->A->bool) realfn` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`realfn:A`;`w1:A`;
      `\a z:A. ?n sig b p15 cvs. n IN D /\ sig IN D /\ b IN D /\
          p15 IN D /\ cvs IN D /\
               E n om /\ eopair D E sig b z /\ echeck D E P n sig /\
                   eopair D E a n p15 /\
               eopair D E p15 onetw cvs /\ eapply D E embf cvs b`]
                   REALFN_ISFUN) THEN
    CONV_TAC(DEPTH_CONV BETA_CONV) THEN
    REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`ci:A`;`om:A`;
                `embf:A`;`w1:A`;
    `ii:A`;`tw:A`;`onetw:A`;`B:A`;`realfn:A`] PERALPHA) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(LABEL_TAC "pera") THEN
  SUBGOAL_THEN `!a. a IN D /\ (E:A->A->bool) a w1
                    ==> ?r. eapply D E realfn a r /\
                        ereal D E om P embf onetw a r`
    ASSUME_TAC THENL
   [X_GEN_TAC `a:A` THEN STRIP_TAC THEN
    USE_THEN "pera" (MP_TAC o SPEC `a:A`) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `rd:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `rd:A` THEN REWRITE_TAC[ereal] THEN
    REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `!a r. a IN D /\ r IN D /\ eapply D (E:A->A->bool) realfn a r
                      ==> E a w1 /\ ereal D E om P embf onetw a r`
    ASSUME_TAC THENL
   [MAP_EVERY X_GEN_TAC [`a:A`;`r:A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) a w1` ASSUME_TAC THENL
     [UNDISCH_TAC `eapply D (E:A->A->bool) realfn a r` THEN
      REWRITE_TAC[eapply] THEN
      DISCH_THEN(X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC) THEN
      SUBGOAL_THEN `(w:A) IN D` ASSUME_TAC THENL
          [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
      USE_THEN "rfch" (MP_TAC o SPEC `w:A`) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> MP_TAC(EQ_MP th
          (ASSUME `(E:A->A->bool) w realfn`))) THEN
      DISCH_THEN(X_CHOOSE_THEN `a':A` (X_CHOOSE_THEN `Y:A`
          STRIP_ASSUME_TAC)) THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`a:A`;`r:A`;`a':A`;`Y:A`;`w:A`]
             EOPAIR_INJ) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(CONJUNCTS_THEN2 SUBST_ALL_TAC (K ALL_TAC)) THEN
          FIRST_ASSUM ACCEPT_TAC;
      ALL_TAC] THEN
    CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    USE_THEN "pera" (MP_TAC o SPEC `a:A`) THEN
    ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `rd:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `r:A = rd` SUBST1_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`realfn:A`]
                   EAPPLY_UNIQUE) THEN
      EXISTS_TAC `a:A` THEN REPEAT CONJ_TAC THEN
          FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    REWRITE_TAC[ereal] THEN REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  (* assemble *)
  MAP_EVERY EXISTS_TAC [`w1:A`;`om:A`;`tw:A`;`ii:A`;`ci:A`;`P:A`;`leqp:A`;
                        `B:A`;`inclB:A`;
    `P:A`;`X:A`;`embf:A`;`onetw:A`;`ztw:A`;`realfn:A`;`z:A`] THEN
  REWRITE_TAC[nbundle; hsbundle; eembf] THEN
  REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC);;

(* ===================================================================== *)
(* S7 (part 3) : THE ENDPOINT.                                             *)
(* VL_MODEL_NOT_AC_MODEL (the symmetric-forcing step): from any model of   *)
(* ZF + V=L, the S6 context (NBUNDLE_EXISTS) + any ultrafilter             *)
(* (EULTRA_EXISTS) give the HS quotient N, a model of ZF (HS_QUOT_MODEL_ZF) *)
(* in which choice_ax fails at every valuation (HS_QUOT_NOT_AC).            *)
(* ZF_MODEL_NOT_AC_MODEL: Con(ZF) ==> Con(ZF + ~AC) in idealized form --   *)
(* pass to L (ZF_MODEL_VL_MODEL, the same bridge as the other three        *)
(* endpoints) and run the step there.  Same ambient type A throughout.     *)
(* ===================================================================== *)
let VL_MODEL_NOT_AC_MODEL = prove
 (`!D (E:A->A->bool).
     model D E ZF_AX /\ (!u:A. u IN D ==> elmem D E u)
     ==> ?B inclB w1 X U. model (qdom_HS D E B inclB w1 X U)
         (qmem D E B inclB U)
                                (Not choice_ax INSERT ZF_AX)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`] NBUNDLE_EXISTS) THEN
  ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(DESTRUCT_TAC
    "@w1 om tw ii ci P leqp B inclB onebee X embf onetw ztw realfn z. ctx") THEN
  REMOVE_THEN "ctx" (CONJUNCTS_THEN2 (LABEL_TAC "nb") STRIP_ASSUME_TAC) THEN
  USE_THEN "nb" (LABEL_TAC "hsb" o CONJUNCT1 o REWRITE_RULE[nbundle]) THEN
  USE_THEN "hsb" (fun th -> let cs = CONJUNCTS(REWRITE_RULE[hsbundle] th) in
    MAP_EVERY ASSUME_TAC [el 0 cs; el 1 cs; el 15 cs; el 17 cs]) THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`z:A`;`onebee:A`]
         EULTRA_EXISTS) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `U:A` STRIP_ASSUME_TAC) THEN
  MAP_EVERY EXISTS_TAC [`B:A`;`inclB:A`;`w1:A`;`X:A`;`U:A`] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;`tw:A`;`ii:A`;
                 `ci:A`;`P:A`;`leqp:A`;
                 `B:A`;`inclB:A`;`onebee:A`;`X:A`;`U:A`] HS_QUOT_MODEL_ZF) THEN
  ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  REWRITE_TAC[model; satisfies; IN_INSERT] THEN STRIP_TAC THEN
  CONJ_TAC THENL
   [FIRST_ASSUM ACCEPT_TAC;
    MAP_EVERY X_GEN_TAC [`w:num->A`;`p:form`] THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC DISJ_CASES_TAC) THENL
     [FIRST_X_ASSUM SUBST1_TAC THEN REWRITE_TAC[HOLDS_NOT] THEN
      MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`om:A`;
                           `tw:A`;`ii:A`;`ci:A`;
        `P:A`;`leqp:A`;`B:A`;`inclB:A`;`onebee:A`;`X:A`;`embf:A`;
            `onetw:A`;`ztw:A`;
        `realfn:A`;`U:A`;`w:num->A`] HS_QUOT_NOT_AC) THEN
      REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
      FIRST_X_ASSUM MATCH_MP_TAC THEN CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC]]);;

(* ================================================================= *)
(* ZF_MODEL_NOT_AC_MODEL : THE ~AC CAPSTONE.  Con(ZF) ==> Con(ZF+~AC) *)
(* in idealized form -- from ANY model of ZF, with NO V=L / choice /  *)
(* constructibility hypothesis on the ambient M, a model of           *)
(* Not choice_ax INSERT ZF_AX exists: pass to L (ZF_MODEL_VL_MODEL),  *)
(* then take the symmetric (HS) submodel of Cohen forcing over L      *)
(* adjoining aleph_1 reals, countable supports (VL_MODEL_NOT_AC_MODEL).*)
(* ================================================================= *)
let ZF_MODEL_NOT_AC_MODEL = prove
 (`!D (E:A->A->bool).
     model D E ZF_AX
     ==> ?D'' (E'':A->A->bool). model D'' E'' (Not choice_ax INSERT ZF_AX)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_MODEL_VL_MODEL) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `D':A->bool` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPECL [`D':A->bool`; `E:A->A->bool`] VL_MODEL_NOT_AC_MODEL) THEN
  ANTS_TAC THENL [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `B:A` (X_CHOOSE_THEN `inclB:A` (X_CHOOSE_THEN `w1:A`
    (X_CHOOSE_THEN `X:A` (X_CHOOSE_THEN `U:A` ASSUME_TAC))))) THEN
  MAP_EVERY EXISTS_TAC
   [`qdom_HS D' (E:A->A->bool) B inclB w1 X U`;
    `qmem D' (E:A->A->bool) B inclB U`] THEN
  FIRST_ASSUM ACCEPT_TAC);;

